import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * Returns the nth Newman‑Shanks‑Williams prime.
     *
     * The sequence of Newman‑Shanks‑Williams numbers is:
     *   a(0)=1, a(1)=1,
     *   a(n) = 2*a(n-1) + a(n-2)  (n ≥ 2)
     *
     * The function returns the prime at index n (0‑based). If the number
     * at that index is not prime, the next prime in the sequence is returned.
     *
     * Examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // First two numbers are 1 (not prime)
        if (n == 0 || n == 1) {
            // The problem expects n ≥ 2 for meaningful results;
            // we return 1 as a placeholder.
            return 1;
        }

        // Compute the nth Newman‑Shanks‑Williams number (0‑based)
        BigInteger aPrevPrev = BigInteger.ONE; // a(0)
        BigInteger aPrev     = BigInteger.ONE; // a(1)
        BigInteger a = BigInteger.ZERO;

        for (int i = 2; i <= n; i++) {
            a = aPrev.multiply(BigInteger.valueOf(2)).add(aPrevPrev);
            aPrevPrev = aPrev;
            aPrev = a;
        }

        // If a(n) is prime, return it
        if (a.isProbablePrime(20)) {
            return a.intValue();
        }

        // Otherwise find the next prime in the sequence
        BigInteger prevPrev = aPrevPrev;
        BigInteger prev     = aPrev;
        while (true) {
            BigInteger next = prev.multiply(BigInteger.valueOf(2)).add(prevPrev);
            prevPrev = prev;
            prev = next;
            if (next.isProbablePrime(20)) {
                return next.intValue();
            }
        }
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

