/**
 * Utility class that offers a method to strip odd‑positioned characters
 * from a given string.
 */
class RemoveOdd {

    /**
     * Removes characters at odd positions (1‑based) from the input string.
     *
     * <p>Examples:
     * <ul>
     *   <li>{@code removeOdd("python") → "yhn"}</li>
     *   <li>{@code removeOdd("program") → "rga"}</li>
     *   <li>{@code removeOdd("language") → "agae"}</li>
     * </ul>
     *
     * @param str1 the original string; may be {@code null}
     * @return a new string containing only the characters that were in even
     *         positions (2nd, 4th, 6th, …). Returns {@code null} if the input
     *         is {@code null}.
     */
    public static String removeOdd(String str1) {
        // Guard against null input
        if (str1 == null) {
            return null;
        }

        StringBuilder result = new StringBuilder(str1.length());

        // Loop through the string, keeping characters at even indices (1‑based)
        // i.e. indices 1, 3, 5, ...
        for (int i = 1; i < str1.length(); i += 2) {
            result.append(str1.charAt(i));
        }

        return result.toString();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));    // → yhn
        System.out.println(removeOdd("program"));   // → rga
        System.out.println(removeOdd("language"));  // → agae
    }
}

