class RectangleArea {
    /**
     * Write a function to find the area of a rectangle.
     *
     * > rectangleArea(10, 20)
     * 200
     * > rectangleArea(10, 5)
     * 50
     * > rectangleArea(4, 2)
     * 8
     */
    public static int rectangleArea(int l, int b) {
        // Simple validation – lengths cannot be negative
        if (l < 0 || b < 0) {
            throw new IllegalArgumentException("Length and breadth must be non‑negative");
