    public static void main(String[] args) {
        System.out.println(rectangleArea(10, 20)); // 200
        System.out.println(rectangleArea(10, 5));  // 50
        System.out.println(rectangleArea(4, 2));  // 8
    }
}

import java.util.*;

public class VolumeTetrahedron {

    // Constants – makes the formula clear and avoids repeated calculations
    private static final double SQRT2 = Math.sqrt(2.0);
    private static final double SIX   = 6.0;

    /**
     * Calculates the volume of a regular tetrahedron whose edge length is {@code num}.
     *
     * @param num edge length of the tetrahedron (must be non‑negative)
     * @return the volume rounded to two decimal places, wrapped in a {@code Double}
     */
    public static Double volumeTetrahedron(int num) {
        // Volume of a regular tetrahedron: V = a³ / (6·√2)
        double volume = (double) num * num * num / (SIX * SQRT2);

        // Round to two decimal places (matches the examples)
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Return as a Double (boxing)
        return rounded;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

