class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern to capture words (only letters, no digits or punctuation)
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();           // the current word
            String lower = word.toLowerCase();       // case‑insensitive check

            // A word must have at least 3 characters to have a middle position
            if (word.length() > 2) {
                // Scan characters from index 1 up to length‑2 (the “middle” area)
                for (int i = 1; i < word.length() - 1; i++) {
                    if (lower.charAt(i) == 'z') {
                        return "Found a match!";
                    }
                }
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

    // ---- simple test harness -------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));     // "Not matched!"
    }
}

import java.util.List;

/**
 * Finds the maximum average of a path from the top‑left corner to the
 * bottom‑right corner of a square matrix, moving only right or down.
 *
 * The path length is always 2·n‑1, therefore the problem is equivalent
 * to finding the maximum‑sum path.
 */
public class Maxaverageofpath {

    /**
     * Computes the maximum average of a valid path.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     size of the matrix (must match cost.size())
     * @return      the maximum possible average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive check – the list may already contain the correct size
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] = max sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                double cur = cost.get(i).get(j).doubleValue();

                if (i == 0 && j == 0) {
                    dp[i][j] = cur;                     // start cell
                } else {
                    double fromTop  = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double fromLeft = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = cur + Math.max(fromTop, fromLeft);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1);   // length of any valid path
        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------
    // Simple manual test (can be removed in production)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

