class CountVowels {

    // Vowel set (both lower‑ and upper‑case)
    private static final String VOWELS = "aeiouAEIOU";

    /**
     * Returns the number of characters in the given string that are not vowels
     * and have at least one vowel neighbour (to the left or to the right).
     *
     * @param testStr the input string
     * @return the required count
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels themselves – we only count consonants
            if (isVowel(ch)) {
                continue;
            }

            // Check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                count++;
                continue; // already satisfied, avoid double‑counting
            }

            // Check right neighbour
            if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                count++;
            }
        }

        return count;
    }

    /** Helper that tells whether a character is a vowel. */
    private static boolean isVowel(char ch) {
        return VOWELS.indexOf(ch) != -1;
    }

    // ------------------------------------------------------------
    // Optional test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

import java.util.ArrayList;
