public class CountAlphaDigSpl {

    /**
     * Counts alphabets, digits and special characters in the given string.
     *
     * @param string the input text (may be empty or null)
     * @return a List containing three integers: [alphabets, digits, special characters]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Default result for null input
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alphaCount = 0;
        int digitCount = 0;
        int specialCount = 0;

        for (char ch : string.toCharArray()) {
            if (Character.isLetter(ch)) {
                alphaCount++;
            } else if (Character.isDigit(ch)) {
                digitCount++;
            } else {
                specialCount++;
            }
        }

        // Return the three counts as a List
        List<Integer> result = new ArrayList<>(3);
        result.add(alphaCount);
        result.add(digitCount);
        result.add(specialCount);
        return result;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

