/**
 * A utility class for computing the sum of the series of squares.
 */
class SeriesSum {

    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound of the series (must be non‑negative)
     * @return the sum of squares from 1 to number (as an int)
     */
    public static int seriesSum(int number) {
        // Guard against negative input – the sum is zero for n < 0
        if (number < 0) {
            return 0;
        }

        // Use long for the intermediate calculation to prevent overflow.
        // The formula: n * (n + 1) * (2n + 1) / 6
        long sumLong = (long) number * (number + 1) * (2L * number + 1) / 6;

        // The problem statement expects an int return type.
        return (int) sumLong;
    }

    // -----------------------------------------------------------------
    // Optional main method for quick manual testing
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example usage:
        System.out.println(seriesSum(6));  // → 91
        System.out.println(seriesSum(7));  // → 140
        System.out.println(seriesSum(12)); // → 650
    }
}

