class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     *
     * The NSW numbers are generated by:
     *   a0 = 1, a1 = 1
     *   a_i = 2*a_{i-1} + a_{i-2}
     *
     * The NSW primes are the prime elements of this sequence.
     *
     * @param n the index (1‑based) of the NSW prime to return
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // a0 = 1, a1 = 1
        BigInteger aPrev2 = BigInteger.ONE; // a_{i-2}
        BigInteger aPrev  = BigInteger.ONE; // a_{i-1}
        int primeCount = 0;

        // start generating from a2 (i = 2)
        for (int i = 2; ; i++) {
            // a_i = 2*a_{i-1} + a_{i-2}
            BigInteger aCurr = aPrev.multiply(BigInteger.valueOf(2)).add(aPrev2);

            // primality test – isProbablePrime(10) is more than enough for these sizes
            if (aCurr.isProbablePrime(10)) {
                primeCount++;
                if (primeCount == n) {
                    // The problem expects an int; we assume n is small enough to fit.
                    return aCurr.intValue();
                }
            }

            // shift the window for the next iteration
            aPrev2 = aPrev;
            aPrev  = aCurr;
        }
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

