        return "Not matched!";
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class Maxaverageofpath {
    /**
     * Finds a path with the maximum average over all existing paths
     * for the given square matrix of size n*n.
     *
     * The path may only move right or down, starting at (0,0) and ending
     * at (n‑1, n‑1). The average is computed as:
     *      (maximum sum of the path) / (number of cells in the path)
     *      = maxSum / (2 * n - 1)
     *
     * @param cost the n×n matrix of integers representing the cost of each cell
     * @param n    the dimension of the square matrix
     * @return the maximum possible average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP[i][j] = maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table: the best sum to (i,j) is the cost of (i,j)
        // plus the larger of the sums to the cell above or to the left.
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The maximum sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // Number of cells visited on any valid path = (n‑1) right moves + (n‑1) down moves + 1
        int cellsInPath = 2 * n - 1;

        // Compute the average and return as a Double
        return maxSum / cellsInPath;
    }

    // --------------------------------------------------------------------
    // Optional main method for quick manual testing (not required by the task)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // Expected: 7.2
    }
}

