     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Null or empty string => no such characters
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with lower‑case to make the check case‑insensitive
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = s.charAt(i);

            // Skip vowels – we only count consonants that have a vowel neighbour
            if (isVowel(ch)) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbour = false;
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                hasVowelNeighbour = true;
            }

            // Check right neighbour if we haven't found a vowel yet
            if (!hasVowelNeighbour && i < len - 1 && isVowel(s.charAt(i + 1))) {
                hasVowelNeighbour = true;
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }

        return count;
    }

    /** Helper: returns true if c is one of a, e, i, o, u */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // Optional: simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));           // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));               // 5
    }
}

