/**
 * Utility class for computing the Newman–Shanks–Williams sequence.
 *
 * The n‑th term of the sequence is defined by:
 *   s₀ = 1, s₁ = 1,
 *   sₙ = 2·sₙ₋₁ + sₙ₋₂  for n ≥ 2.
 *
 * The problem statement asks for the “nth newman‑shanks‑williams prime”.
 * In the provided examples the returned values correspond to sₙ (the n‑th
 * term of the recurrence), so we simply compute sₙ.
 *
 * @author  (your name)
 * @version 1.0
 */
public final class NewmanPrime {

    // ---- Effective Java Item 4: enforce noninstantiability ----
    private NewmanPrime() {
        throw new UnsupportedOperationException("NewmanPrime is not meant to be instantiated");
    }

    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     *
     * @param n the index of the term to retrieve (0‑based)
     * @return the value of sₙ
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Use long for intermediate results to avoid overflow (Item 6)
        long s0 = 1L; // s₀
        long s1 = 1L; // s₁

        if (n == 0) {
            return (int) s0;
        }
        if (n == 1) {
            return (int) s1;
        }

        long sn = 0L;
        // Compute s₂ … sₙ iteratively (no extra objects are created)
        for (int i = 2; i <= n; i++) {
            sn = 2L * s1 + s0; // sₙ = 2·sₙ₋₁ + sₙ₋₂
            s0 = s1;
            s1 = sn;
        }

        // The problem expects int results, so we cast.  For larger n
        // consider returning long or BigInteger.
        return (int) sn;
    }

    // ---- Effective Java Item 12: always override toString ----
    @Override
    public String toString() {
        return "NewmanPrime";
    }

    // ---- Simple test driver (optional) ----
    public static void main(String[] args) {
        System.out.println("newmanPrime(3) = " + newmanPrime(3)); // 7
        System.out.println("newmanPrime(4) = " + newmanPrime(4)); // 17
        System.out.println("newmanPrime(5) = " + newmanPrime(5)); // 41
    }
}

