class Maxaverageofpath {

    /**
     * Returns the maximum possible average of the numbers on a path
     * from the top‑left to the bottom‑right of the square matrix.
     * Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return     the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] holds the maximum sum to reach cell (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                long val = cost.get(i).get(j).longValue();

                if (i == 0 && j == 0) {
                    // starting cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // can only come from the left
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    // can only come from above
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    // take the better of the two possible predecessors
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + val;
                }
            }
        }

        // A monotonic path from (0,0) to (n‑1,n‑1) always has exactly (2n‑1) cells.
        double maxAverage = dp[n - 1][n - 1] / (double) (2 * n - 1);
        return maxAverage;
    }

    // Optional simple test (not required for the solution)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

public static int countVowels(String testStr) {
    // Guard against null or empty strings
    if (testStr == null || testStr.isEmpty()) {
        return 0;
    }

    // Work in lower‑case to be case‑insensitive
    String s = testStr.toLowerCase();
    final String vowels = "aeiou";

    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        // Skip vowels – we only count consonants that are next to a vowel
        if (vowels.indexOf(c) != -1) {
            continue;
        }

        // Check left neighbour
        boolean leftIsVowel  = i > 0          && vowels.indexOf(s.charAt(i - 1)) != -1;
        // Check right neighbour
        boolean rightIsVowel = i < s.length() - 1 && vowels.indexOf(s.charAt(i + 1)) != -1;

        if (leftIsVowel || rightIsVowel) {
            count++;
        }
    }
    return count;
}

