class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        // The Newman–Shanks–Williams sequence: a(0)=1, a(1)=1, a(n)=2*a(n-1)+a(n-2)
        if (n == 0 || n == 1) {
            return 1;
        }
        long a0 = 1; // a(n-2)
        long a1 = 1; // a(n-1)
        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }
}

