class Maxaverageofpath {

    /**
     * Returns the maximum average of any path from the top‑left corner
     * to the bottom‑right corner of the given n×n matrix.
     * Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average (rounded to one decimal place)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // total number of cells visited on any top‑left → bottom‑right path
        int totalCells = 2 * n - 1;
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / totalCells;

        // round to one decimal place (as shown in the examples)
        average = Math.round(average * 10.0) / 10.0;

        return average; // auto‑boxed to Double
    }

    // Simple test driver
    public static void main(String[] args) {
