class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n of the series
     * @return the sum of squares from 1 to n
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Sum of squares formula: n * (n + 1) * (2n + 1) / 6
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;
        return (int) sum;   // the problem expects an int result
    }
}

