class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     * The Newman–Shanks–Williams sequence is defined by
     * s₀ = 1, s₁ = 1 and sᵢ = 2·sᵢ₋₁ + sᵢ₋₂ for i ≥ 2.
     * The method returns the smallest prime sⱼ such that j ≥ n.
     *
     * @param n the index (1‑based) in the Newman‑Shanks‑Williams sequence
     * @return the corresponding prime number
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        // Item 49: Check parameters for validity
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Use BigInteger to avoid overflow for larger indices
        BigInteger s0 = BigInteger.ONE; // s_{i-2}
        BigInteger s1 = BigInteger.ONE; // s_{i-1}

        // Compute s_n (or up to index n)
        for (int i = 2; i <= n; i++) {
            BigInteger s = s1.multiply(BigInteger.valueOf(2)).add(s0);
            s0 = s1;
            s1 = s;
        }

        // If s_n is not prime, find the next prime in the sequence
        while (!s1.isProbablePrime(100)) {
            BigInteger next = s1.multiply(BigInteger.valueOf(2)).add(s0);
            s0 = s1;
            s1 = next;
        }

        // The problem expects an int; we assume the result fits
        return s1.intValue();
    }
}

