class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron given its side length.
     *
     * @param num the side length of the tetrahedron (must be positive)
     * @return the volume rounded to two decimal places
     * @throws IllegalArgumentException if num is not positive
     */
    public static Double volumeTetrahedron(int num) {
        // Item 49: Check parameters for validity
        if (num <= 0) {
            throw new IllegalArgumentException("Side length must be positive");
        }

        double side = num;
        // Volume of a regular tetrahedron: V = a³ / (6·√2)
        double volume = (side * side * side) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places (matches the examples)
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Return as a boxed Double (return type is Double)
        return rounded;
    }
}

