class TextMatchWordzMiddle {

    /**
     * Determines whether any word in the given text contains the letter 'z'
     * somewhere other than the first or last character.
     *
     * @param text the input string (may contain punctuation, spaces, etc.)
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") -> "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")    -> "Found a match!"
     *   textMatchWordzMiddle("  lang  .")  -> "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Regex: one or more ASCII letters – this strips punctuation and whitespace
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();          // the current word
            String lower = word.toLowerCase();      // case‑insensitive check

            // A 'z' can only be “in the middle” if the word has at least 3 characters
            if (word.length() >= 3) {
                // Scan characters from index 1 up to length‑2 (inclusive)
                boolean middleZ = false;
                for (int i = 1; i < word.length() - 1; i++) {
                    if (lower.charAt(i) == 'z') {
                        middleZ = true;
                        break;
                    }
                }
                if (middleZ) {
                    return "Found a match!";
                }
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));    // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));  // "Not matched!"
    }
}

