class Maxaverageofpath {
    /**
     * Returns the maximum average of a path that travels from the top‑left corner
     * to the bottom‑right corner of the given n × n matrix, moving only right
     * or down. The average is computed as (sum of visited cells) / (2·n‑1).
     *
     * @param cost  the n × n matrix of non‑negative integer costs
     * @param n     the dimension of the square matrix
     * @return      the maximum possible average, or null if the input is invalid
     *
     * @throws IllegalArgumentException if {@code cost} is null, {@code n} is not
     *         positive, or the matrix dimensions do not match {@code n}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ----- Item 49: check parameters for validity -----
        if (cost == null) {
            throw new IllegalArgumentException("cost must not be null");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException("cost.size() must equal n");
        }
        for (List<Integer> row : cost) {
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Each row must be non‑null and have size n");
            }
        }

        // DP array holds the best sum to the current cell in the current row.
        double[] dp = new double[n];

        // ----- First row (i = 0) -----
        for (int j = 0; j < n; j++) {
            if (j == 0) {
                dp[j] = cost.get(0).get(j);
            } else {
                dp[j] = dp[j - 1] + cost.get(0).get(j);
            }
        }

        // ----- Remaining rows (i = 1 … n‑1) -----
        for (int i = 1; i < n; i++) {
            // First column: can only come from the cell above.
            dp[0] = dp[0] + cost.get(i).get(0);

            // Other columns: max of coming from above (dp[j]) or from the left (dp[j‑1]).
            for (int j = 1; j < n; j++) {
                dp[j] = Math.max(dp[j], dp[j - 1]) + cost.get(i).get(j);
            }
        }

        // The total number of cells visited on any valid path is (2·n‑1).
        double maxSum = dp[n - 1];
        double average = maxSum / (2.0 * n - 1.0);
        return average;
    }

    // ----- Simple test harness -----
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

