/**
 * Utility class for counting characters that have vowel neighbors.
 */
class CountVowels {

    /**
     * Counts the consonants in the given string that have at least one vowel
     * as an immediate neighbor (to the left or to the right).
     *
     * <p>Vowels are the characters {@code 'a', 'e', 'i', 'o', 'u'} (case‑insensitive).
     * The letter {@code 'y'} is treated as a consonant. Only non‑vowel characters
     * that are adjacent to a vowel are counted; the vowel characters themselves are
     * not included in the result.</p>
     *
     * @param testStr the input string; must not be {@code null}
     * @return the number of consonants that have a vowel neighbor
     * @throws IllegalArgumentException if {@code testStr} is {@code null}
     */
    public static int countVowels(String testStr) {
        // Item 49: Check parameters for validity
        if (testStr == null) {
            throw new IllegalArgumentException("Input string must not be null");
        }

        // Strings of length 0 or 1 have no neighbors, so the answer is 0.
        if (testStr.length() <= 1) {
            return 0;
        }

        // Work with lower‑case characters for case‑insensitive comparison.
        String s = testStr.toLowerCase();

        // Helper: true for each vowel letter.
        boolean[] isVowel = new boolean[26];
        for (char c : "aeiou".toCharArray()) {
            isVowel[c - 'a'] = true;
        }

        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char current = s.charAt(i);

            // Skip vowel characters – we only count consonants.
            if (isVowel[current - 'a']) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbor.
            if (i > 0) {
                char left = s.charAt(i - 1);
                if (isVowel[left - 'a']) {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbor if we haven't already found a vowel neighbor.
            if (!hasVowelNeighbor && i < s.length() - 1) {
                char right = s.charAt(i + 1);
                if (isVowel[right - 'a']) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

