/**
 * A utility class for computing the sum of squares of the first n positive integers.
 *
 * The series is: 1² + 2² + 3² + … + n²
 *
 * Examples:
 *   seriesSum(6) → 91
 *   seriesSum(7) → 140
 *   seriesSum(12) → 650
 */
public class SeriesSum {

    /**
     * Returns the sum of squares of the first {@code number} positive integers.
     *
     * @param number the count of terms (must be non‑negative)
     * @return the sum 1² + 2² + … + number²
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        // ---- Item 49: Check parameters for validity ----
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative");
        }

        // Use a long accumulator to avoid overflow while summing,
        // then cast back to int as required by the method signature.
        long sum = 0;
        for (int i = 1; i <= number; i++) {
            sum += (long) i * i;   // square the int, promote to long to avoid overflow
        }

        // ---- Item 50: Defensive copying not needed here (primitive) ----
        // ---- Item 54: Return empty/zero results, not nulls (already zero for number == 0) ----
        return (int) sum;
    }

    // Optional main method for quick manual testing
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

