import java.math.*;

class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2*a(n‑1) + a(n‑2)  for n >= 2
     *
     * The examples show that for n = 3,4,5 the returned values are 7, 17 and 41,
     * which correspond to a(3), a(4) and a(5) respectively.
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        // Guard against negative or zero indices – not expected by the spec,
        // but returning 0 keeps the API safe.
        if (n <= 0) {
            return 0;
        }

        // The first two terms of the sequence are both 1.
        long a0 = 1L; // a(n‑2)
        long a1 = 1L; // a(n‑1)

        // For n == 0 or 1 we can return directly.
        if (n == 0) {
            return (int) a0;
        }
        if (n == 1) {
            return (int) a1;
        }

        // Compute the remaining terms iteratively.
        long a = 0L; // will hold a(n)
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(n) = 2*a(n‑1) + a(n‑2)
            a0 = a1;         // shift for next iteration
            a1 = a;
        }

        // The problem expects an int return type; we cast the long value.
        // For the small values of n used in the test cases this conversion is safe.
        return (int) a;
    }

    // --------------------------------------------------------------------
    // Optional test driver (feel free to remove or comment out in production)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Example runs from the problem statement
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41

        // A few more terms to illustrate the sequence
        for (int i = 0; i <= 10; i++) {
            System.out.println("a(" + i + ") = " + newmanPrime(i));
        }
    }
}

class RemoveOdd {
    /**
     * Remove characters at even positions (0‑based index) and keep those at odd positions.
     *
     * > removeOdd("python")
     * "yhn"
     * > removeOdd("program")
     * "rga"
     * > removeOdd("language")
     * "agae"
     */
    public static String removeOdd(String str1) {
        // Guard against null input – return null as per conventional practice
        if (str1 == null) {
            return null;
        }

        StringBuilder result = new StringBuilder(str1.length() / 2 + 1);
        for (int i = 0; i < str1.length(); i++) {
            // Keep characters whose index is odd (i % 2 == 1)
            if (i % 2 == 1) {
                result.append(str1.charAt(i));
            }
        }
        return result.toString();
    }

    // Simple demo (optional)
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));    // yhn
        System.out.println(removeOdd("program"));   // rga
        System.out.println(removeOdd("language"));  // agae
