import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts at the
     * upper‑left corner of the given n×n matrix and ends at the lower‑right corner.
     * Movement is restricted to right or down steps only.
     *
     * @param cost  list of rows, each row is a list of integers
     * @param n     size of the square matrix
     * @return      the maximum average as a Double, or null if n <= 0
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return null;                     // defensive handling
        }

        // DP table: long to avoid overflow of the sum
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);   // matrix element

                if (i == 0 && j == 0) {
                    dp[i][j] = val;
                } else if (i == 0) {            // first row: can only come from the left
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {            // first column: can only come from above
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);
        return Double.valueOf(average);
    }

    // Simple manual test (not required for the solution)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

