class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a(1) = 1, a(2) = 3,
     *   a(i) = 2*a(i‑1) + a(i‑2) for i > 2.
     *
     * @param n index (1‑based)
     * @return the n‑th term of the NSW sequence
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // Base cases
        if (n == 1) return 1;   // a(1)
        if (n == 2) return 3;   // a(2)

        // Use long for intermediate values to avoid premature overflow
        long a = 1;   // a(i‑2)  -> a(1)
        long b = 3;   // a(i‑1)  -> a(2)
        long c = 0;

        for (int i = 3; i <= n; i++) {
            c = 2 * b + a; // a(i) = 2*a(i‑1) + a(i‑2)
            a = b;
            b = c;
        }
        return (int) b; // the result fits in int for reasonable n
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

