/**
 *  TextMatchWordzMiddle – finds a word that contains the letter 'z'
 *  somewhere inside it (i.e. not as the first or last character).
 *
 *  The method returns:
 *      "Found a match!"   – if such a word exists,
 *      "Not matched!"    – otherwise.
 *
 *  Examples:
 *      textMatchWordzMiddle("pythonzabc.") → "Found a match!"
 *      textMatchWordzMiddle("xyzabc.")      → "Found a match!"
 *      textMatchWordzMiddle("  lang  .")   → "Not matched!"
 */
public class TextMatchWordzMiddle {

    public static String textMatchWordzMiddle(String text) {
        // Guard against null / empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Pattern that matches a word: a maximal sequence of word characters
        // (\w = [a-zA-Z0-9_]) bounded by a word boundary (\b).
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        // Scan every word in the input string
        while (matcher.find()) {
            String word = matcher.group();

            // Find the first occurrence of 'z'
            int zIndex = word.indexOf('z');

            // If 'z' exists and is not at position 0 (start) nor at the last position,
            // we have a match.
            if (zIndex > 0 && zIndex < word.length() - 1) {
                return "Found a match!";
            }
        }

        // No qualifying word was found
        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // A tiny driver to illustrate the three examples from the Javadoc.
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        String[] tests = {
            "pythonzabc.",
            "xyzabc.",
            "  lang  ."
        };
        for (String t : tests) {
            System.out.printf("%s → %s%n", t, textMatchWordzMiddle(t));
        }
    }
}

