class Maxaverageofpath {
    /**
     * Returns the maximum average of a path from the top‑left to the bottom‑right
     * of the given n×n cost matrix. Movement is allowed only right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[j] holds the best sum to reach cell (i, j) from (0,0)
        double[] dp = new double[n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double cur = cost.get(i).get(j).doubleValue();

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[j] = cur;
                } else {
                    // Best sum reachable from the top (i-1, j) or from the left (i, j-1)
                    double fromTop  = (i > 0) ? dp[j] : Double.NEGATIVE_INFINITY;
                    double fromLeft = (j > 0) ? dp[j - 1] : Double.NEGATIVE_INFINITY;
                    dp[j] = cur + Math.max(fromTop, fromLeft);
                }
            }
        }

        // Number of cells visited in any valid path = 2*n - 1
        double maxAverage = dp[n - 1] / (2 * n - 1);
        return maxAverage;
    }
}

