public class CountVowels {

    /**
     * Counts characters that are not vowels but have at least one vowel neighbour.
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int length = testStr.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            char ch = testStr.charAt(i);

            // We only consider consonants (non‑vowels)
            if (isVowel(ch)) {
                continue;
            }

            // Check left neighbour
            boolean leftIsVowel = (i > 0) && isVowel(testStr.charAt(i - 1));
            // Check right neighbour
            boolean rightIsVowel = (i < length - 1) && isVowel(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }

    /**
     * Helper method that determines whether a given character is a vowel
     * (a, e, i, o, u). The check is case‑insensitive.
     *
     * @param c the character to test
     * @return true if c is a vowel, false otherwise
     */
    private static boolean isVowel(char c) {
        char lower = Character.toLowerCase(c);
        return lower == 'a' || lower == 'e' || lower == 'i'
                || lower == 'o' || lower == 'u';
    }

    // -----------------------------------------------------------------
    // Simple test driver (optional – can be removed in production)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
