class NewmanPrime {
    public static int newmanPrime(int n) {
        // Handle base cases for small n
        if (n == 0) return 1; // s(0) = 1
        if (n == 1) return 1; // s(1) = 1

        // Generate the nth NSW number using BigInteger
        BigInteger s0 = BigInteger.ONE;
        BigInteger s1 = BigInteger.ONE;
        BigInteger s = BigInteger.ONE;

        for (int i = 2; i <= n; i++) {
            s = s1.multiply(BigInteger.valueOf(2)).add(s0);
            s0 = s1;
            s1 = s;
        }

        // Return the nth NSW number (assuming it is prime for valid inputs)
        return s.intValue();
    }
}

