import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that goes from the top‑left corner
     * to the bottom‑right corner of the given n×n matrix.  Moves are allowed
     * only to the right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximal average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- basic validation -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // ---- DP table: maximum sum to reach each cell -------------------------
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0).doubleValue();

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j).doubleValue();
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0).doubleValue();
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j).doubleValue()
                         + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute the average ---------------------------------------------
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);   // constant path length

        return average;
    }
}

