class TextMatchWordzMiddle {
    /**
     * Returns "Found a match!" if the supplied text contains a word that
     * has the letter 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // \b\w+\b matches a whole word (letters, digits, underscore)
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();          // e.g. "pythonzabc"
            int zIdx = word.indexOf('z');            // -1 if no 'z'

            // 'z' must be present, and not at position 0 or the last position
            if (zIdx != -1 && zIdx != 0 && zIdx != word.length() - 1) {
                return "Found a match!";
            }
        }

        // No suitable word found
        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // A tiny test driver (optional – handy for manual verification)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));     // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

