public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that travels from the
     * top‑left corner to the bottom‑right corner of the given n×n matrix.
     * Movement is restricted to right or down steps only.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    dimension of the square matrix
     * @return the maximum average (as a Double) of any valid path
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against invalid input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] holds the maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Initialize start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The total number of cells visited on any top‑left → bottom‑right path
        int cellsCount = 2 * n - 1;   // (n‑1) right moves + (n‑1) down moves + start cell
        long maxSum = dp[n - 1][n - 1];

        // Compute average and autobox to Double
        return maxSum / (double) cellsCount;
    }

    // -----------------------------------------------------------------
    // Simple test driver (optional)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // Expected: 7.2
    }
}

