     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle invalid input
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Base cases for the Newman-Shanks-Williams sequence
        if (n == 1) return 1;
        if (n == 2) return 3;

        // Iteratively compute the nth term
        long a0 = 1; // a(n-2)
        long a1 = 1; // a(n-1)
        long a = 0;  // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        // Cast to int (assuming n is small enough to fit in int)
        return (int) a;
    }
}

