class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern to match words consisting only of letters (a‑z, A‑Z)
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();          // the word found
            String lower = word.toLowerCase();      // case‑insensitive check

            // Does the word contain 'z' at all?
            if (lower.contains("z")) {
                // Look for a 'z' that is not the first or last character
                boolean interiorZ = false;
                for (int i = 1; i < lower.length() - 1; i++) {
                    if (lower.charAt(i) == 'z') {
                        interiorZ = true;
                        break;
                    }
                }
                if (interiorZ) {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
        System.out.println(textMatchWordzMiddle("  lang  ."));
    }
}

import java.util.List;

/**
 * Computes the maximum possible average value of a path that starts
 * at the top‑left corner of a square matrix and ends at the bottom‑right
 * corner, moving only right or down.
 *
 * @param cost the n×n matrix of integer costs
 * @param n    size of the matrix (number of rows/columns)
 * @return the maximum average, or null if the input is invalid
 */
public class Maxaverageofpath {

    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: double to avoid overflow when summing many integers
        double[][] dp = new double[n][n];

        // Initialise the start cell
        dp[0][0] = cost.get(0).get(0).doubleValue();

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j).doubleValue();
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0).doubleValue();
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                double best = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = best + cost.get(i).get(j).doubleValue();
            }
        }

        // The path always contains exactly (2*n - 1) cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1);

        return average; // auto‑boxed to Double
    }

    // -----------------------------------------------------------------
    // Optional test driver (not required by the problem statement)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

