class CountVowels {
    /**
     * Counts the characters (non‑vowels) that have a vowel as a neighbour
     * (left or right) in the given string.
     *
     * @param testStr the input string (assumed to be non‑null)
     * @return the number of such characters
     *
     * Examples:
     *   countVowels("bestinstareels")          -> 7
     *   countVowels("partofthejourneyistheend")-> 12
     *   countVowels("amazonprime")             -> 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }

        // Vowel set (lower‑case).  We also accept upper‑case by converting to lower‑case.
        final String vowels = "aeiou";

        int n = testStr.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char c = testStr.charAt(i);
            // If the current character itself is a vowel, skip it – we only count consonants.
            if (vowels.indexOf(Character.toLowerCase(c)) != -1) {
                continue;
            }

            // Check neighbours
            boolean hasVowelNeighbour = false;

            // left neighbour
            if (i > 0) {
                char left = testStr.charAt(i - 1);
                if (vowels.indexOf(Character.toLowerCase(left)) != -1) {
                    hasVowelNeighbour = true;
                }
            }

            // right neighbour (only needed if we haven't already found a vowel neighbour)
            if (!hasVowelNeighbour && i < n - 1) {
                char right = testStr.charAt(i + 1);
                if (vowels.indexOf(Character.toLowerCase(right)) != -1) {
                    hasVowelNeighbour = true;
                }
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }

        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

