     */
    public static int seriesSum(int number) {
        // Handle non‑positive input: the sum is zero.
        if (number <= 0) {
            return 0;
        }

        // Use long for the intermediate calculation to avoid overflow.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The problem expects an int return type.
        return (int) sum;
    }

