import java.util.Scanner;

class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The first few values are: 1, 1, 3, 7, 17, 41, …
     *
     * @param n index (0‑based)
     * @return the n‑th term
     */
    public static int newmanPrime(int n) {
        // Handle the base cases
        if (n <= 0) return 1;   // a0
        if (n == 1) return 1;   // a1

        // Iterate using two variables (a(n‑2) and a(n‑1))
        int aPrev2 = 1; // a0
        int aPrev1 = 1; // a1
        int current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * aPrev1 + aPrev2; // a(i) = 2*a(i‑1) + a(i‑2)
            // shift the window for the next iteration
            aPrev2 = aPrev1;
            aPrev1 = current;
        }
        return current;
    }

    // Simple driver to test the function
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            System.out.println(newmanPrime(n));
        }
    }
}

