public static int newmanPrime(int n) {
    // handle edge cases
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }
    if (n == 0 || n == 1) {
        return 1;
    }
    int prev2 = 1; // s(0)
    int prev1 = 1; // s(1)
    int current = 0;
    for (int i = 2; i <= n; i++) {
        current = 2 * prev1 + prev2;
        prev2 = prev1;
        prev1 = current;
    }
    return current;
}

