class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the input text contains the letter 'z'
     * and that 'z' is not the first or last character of the word.
     * Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")    → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")  → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Pattern matches a whole word that contains at least one 'z'
        // \b = word boundary, [a-zA-Z] = letters only
        Pattern wordWithZ = Pattern.compile("\\b[a-zA-Z]*z[a-zA-Z]*\\b");
        Matcher m = wordWithZ.matcher(text);

        while (m.find()) {
            String word = m.group();

            // 'z' must not be the first or the last character
            if (!word.startsWith("z") && !word.endsWith("z")) {
                // Additional safety check: word length must be ≥3 so that
                // there is at least one character before and after the 'z'.
                if (word.length() >= 3) {
                    return "Found a match!";
                }
            }
        }

        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));    // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));  // "Not matched!"
    }
}

import java.util.List;
import java.util.Arrays;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given
     * n×n cost matrix. Movement is allowed only to the right or down.
     *
     * @param cost  list of rows, each row a list of integers
     * @param n     size of the square matrix
     * @return      the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive check
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[j] – best sum to reach cell (current row, j)
        long[] dp = new long[n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // start cell
                    dp[j] = val;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[j] = dp[j - 1] + val;
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[j] = dp[j] + val;
                } else {
                    // take the better of the two possible predecessors
                    dp[j] = val + Math.max(dp[j], dp[j - 1]);
                }
            }
        }

        long maxSum = dp[n - 1];
        double average = (double) maxSum / (2L * n - 1);
        return average;
    }

    // Simple test harness
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

