class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the last term of the series (n). Must be non‑negative.
     * @return the sum of squares from 1 to number.
     *
     * Example:
     * <pre>
     * seriesSum(6) → 91
     * seriesSum(7) → 140
     * seriesSum(12) → 650
     * </pre>
     */
    public static int seriesSum(int number) {
        // Guard against negative input – we can either throw or return 0.
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative");
        }

        // Use long for the intermediate computation to avoid overflow.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The problem expects an int return type.
        return (int) sum;
    }

