public static int newmanPrime(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }
    // base cases
    if (n == 0) return 1; // a0 = 1
    if (n == 1) return 1; // a1 = 1

    long a0 = 1; // a(n‑2)
    long a1 = 1; // a(n‑1)
    long a = 0;
    for (int i = 2; i <= n; i++) {
        a = 2 * a1 + a0; // recurrence a(n) = 2*a(n‑1) + a(n‑2)
        a0 = a1;
        a1 = a;
    }
    return (int) a;
}

