    for (int i = 0; i < str1.length(); i++) {
        // Keep characters at even indices (i.e., positions 2,4,6,... in 1‑based)
        if (i % 2 == 1) {
            sb.append(str1.charAt(i));
        }
    }
    return sb.toString();
}

