class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the given text contains a word that has the
     * letter 'z' (or 'Z') somewhere other than the first or last character.
     * Otherwise returns "Not matched!".
     *
     * @param text the input string to examine
     * @return the appropriate match message
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null input
        if (text == null) {
            return "Not matched!";
        }

        // Pattern to match a word: one or more ASCII letters
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A word shorter than 3 characters can never have a middle 'z'
            if (word.length() < 3) {
                continue;
            }

            // Scan the interior of the word (skip first and last characters)
            for (int i = 1; i < word.length() - 1; i++) {
                char ch = word.charAt(i);
                if (ch == 'z' || ch == 'Z') {
                    return "Found a match!";
                }
            }
        }

        // No qualifying word was found
        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));        // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));     // "Not matched!"
    }
}

