public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a monotone path
     * (moving only right or down) from the top‑left corner (0,0) to the
     * bottom‑right corner (n‑1,n‑1) in the given n×n cost matrix.
     *
     * @param cost  list of rows, each row a list of integer values
     * @param n     dimension of the square matrix
     * @return      the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;                     // defensive check
        }

        // DP[i][j] = maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Every monotone path from (0,0) to (n-1,n-1) has exactly (2n-1) cells
        int totalCells = 2 * n - 1;
        return dp[n - 1][n - 1] / totalCells;
    }

    // -----------------------------------------------------------------
    // Optional main method for quick manual testing
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

