        // The intermediate result is stored in a long to avoid overflow
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;

        // The problem expects an int return; we cast (the input is assumed
        // to be within the range where the sum fits in an int).
        return (int) sum;
    }

    // Simple test driver (optional)
