        int maxLength = 0;
        for (String word : list1) {
            // Skip any null entries
            if (word != null) {
                int len = word.length();
                if (len > maxLength) {
                    maxLength = len;
                }
            }
        }
        return maxLength;
    }
}

public static int newmanPrime(int n) {
    // The sequence is defined for n >= 0.
    // For n = 0 or 1 the value is 1.
    if (n <= 1) {
        return 1;
    }

    // s0 = s_{i-2}, s1 = s_{i-1}
    long s0 = 1;   // s_0
    long s1 = 1;   // s_1
    long s  = 0;   // s_n will be stored here

    // Compute s_2 … s_n using the recurrence
    for (int i = 2; i <= n; i++) {
        s = 2 * s1 + s0; // s_i = 2*s_{i-1} + s_{i-2}
        s0 = s1;
        s1 = s;
    }

    // The loop leaves 's' holding s_n
    return (int) s;
}

