public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the given text contains a word
     * that has the letter 'z' somewhere other than the first or last
     * position of that word.  Otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern that matches a word: a contiguous sequence of letters.
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            if (containsZNotAtEdges(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * Helper: true if the word contains a 'z' that is neither the first
     * nor the last character.
     */
    private static boolean containsZNotAtEdges(String word) {
        // A word shorter than 3 chars cannot have a middle character.
        if (word.length() < 3) {
            return false;
        }
        // Scan the interior of the word (exclude indices 0 and length‑1).
        for (int i = 1; i < word.length() - 1; i++) {
            if (word.charAt(i) == 'z') {
                return true;
            }
        }
        return false;
    }

    // --------------------------------------------------------------------
    // Simple test driver (optional)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));     // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that travels from the top‑left
     * corner to the bottom‑right corner of the given n×n matrix, moving only
     * right or down.
     *
     * @param cost  a square matrix represented as a list of rows
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximum average (as a {@code Double}) of a valid path,
     *              or {@code null} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal arguments
        if (cost == null || cost.size() != n || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] holds the maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Initialize the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the DP table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The total number of cells visited on any monotonic path is 2*n - 1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        return Double.valueOf(average);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // Expected: 7.2
    }
}

