class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the last term of the series (n)
     * @return the sum of squares from 1 to n
     */
    public static int seriesSum(int number) {
        long sum = 0;                     // use long to avoid overflow while accumulating
        for (int i = 1; i <= number; i++) {
            sum += (long) i * i;          // square the current integer and add to sum
        }
        return (int) sum;                 // the expected return type is int
    }

