class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1,
     *   an = 2 * a(n‑1) + a(n‑2)  for n >= 2.
     *
     * The problem’s examples (newmanPrime(3) = 7, newmanPrime(4) = 17,
     * newmanPrime(5) = 41) correspond to a[3], a[4] and a[5] of this
     * recurrence.
     *
     * @param n the index (1‑based) of the desired number
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // The first two values of the sequence are 1, 1
        long a0 = 1;
        long a1 = 1;

        // For n == 1 or n == 2 we return 1 (the sequence starts 1, 1, 3, 7, …)
        if (n == 1) {
            return (int) a0; // 1
        }
        if (n == 2) {
            return (int) a1; // 1
        }

        long a = 0;
        // Compute the sequence up to index n
        for (int i = 2; i < n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        // At this point a holds a[n] (since loop stops at i = n‑1)
        return (int) a;
    }
}

