     * Returns the maximum possible average of a monotonic path
     * (only moves right or down) from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost a list of n rows, each row a list of n integers
     * @param n    the dimension of the square matrix
     * @return     the maximum average as a Double, or null if input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] holds the maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // fill the first row (can only come from the left)
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // fill the first column (can only come from above)
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The number of cells in any monotonic path is 2*n - 1
        int totalCells = 2 * n - 1;

        // Convert the maximum sum to the average
        double maxAverage = dp[n - 1][n - 1] / totalCells;

