public static int newmanPrime(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    // a0 = a_{n-2}, a1 = a_{n-1}
    int a0 = 1; // a_0
    if (n == 0) return a0;

    int a1 = 1; // a_1
    if (n == 1) return a1;

    int a = 0; // a_n
    for (int i = 2; i <= n; i++) {
        a = 2 * a1 + a0; // recurrence: a_i = 2*a_{i-1} + a_{i-2}
        a0 = a1;
        a1 = a;
    }
    return a;
}

