/**
 * Solution for the “Count Vowels” problem.
 *
 * <p>Given a string, count the characters that are not vowels (consonants)
 * and that have at least one vowel as an immediate neighbour (left or right).
 */
public class CountVowels {

    /**
     * Counts consonants in the given string that have a vowel as a neighbour.
     *
     * @param testStr the input string (may contain mixed case)
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        // Guard against null or too‑short strings
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        // Work with a lower‑case version for easy vowel checking
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);

            // Skip vowels – we only count consonants
            if (isVowel(c)) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbor = false;
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }

            // Check right neighbour if we haven't found a vowel yet
            if (!hasVowelNeighbor && i < len - 1 && isVowel(s.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /** Helper: true if the character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }

    // -----------------------------------------------------------------
    // Optional test driver (matches the examples in the problem statement)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

