     * letter 'z' somewhere other than the first or last position.
     *
     * @param text the input string
     * @return     "Found a match!" or "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Regex: one or more ASCII letters => a word
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            if (containsZNotAtEdges(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * Helper: does the word contain 'z' at an index that is neither the first
     * nor the last character?
     */
    private static boolean containsZNotAtEdges(String word) {
        int len = word.length();
        // A middle position exists only if length >= 3
        if (len <= 2) {
            return false;
        }
        // Examine characters from index 1 up to len-2 (inclusive)
        for (int i = 1; i < len - 1; i++) {
            if (word.charAt(i) == 'z') {
                return true;
            }
        }
        return false;
    }

    // --------------------------------------------------------------------
    // Optional test driver
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
