public class Maxaverageofpath {

    /**
     * Returns the maximum average of a monotonic (right/down) path
     * from the top‑left to the bottom‑right of an n×n cost matrix.
     *
     * @param cost  list of n rows, each row having n integers
     * @param n     size of the square matrix
     * @return      the maximum average (as a Double) or null for invalid input
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- basic validation ------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // ---- DP table: maximum sum to reach (i, j) -------------------------
        long[][] dp = new long[n][n];

        // first cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells – take the better of the two predecessor paths
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average -------------------------------------------------
        long maxSum = dp[n - 1][n - 1];                // sum of the best path
        double average = (double) maxSum / (2L * n - 1); // every path has 2*n-1 cells

        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------------
    // Simple manual test (remove or comment out in production)
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
            Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
            ), 3)); // 5.2

        System.out.println(maxaverageofpath(
            Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
            ), 3)); // 6.2

        System.out.println(maxaverageofpath(
            Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
            ), 3)); // 7.2
    }
}

