class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   p0 = 1, p1 = 1
     *   pn = 2 * p(n‑1) + p(n‑2)   for n >= 2
     *
     * For n = 3 the method returns 7, for n = 4 it returns 17,
     * for n = 5 it returns 41, etc.
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // p0 and p1 are both 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long prev2 = 1; // p0
        long prev1 = 1; // p1
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // pn = 2 * p(n‑1) + p(n‑2)
            prev2 = prev1;
            prev1 = current;
        }

        // The values fit in int for reasonable n (up to n ≈ 25)
        return (int) current;
    }

    // Simple test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

