    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str1.length(); i++) {
        // Keep characters at even positions (1-indexed), i.e., index 1,3,5,...
        if (i % 2 == 1) {
            sb.append(str1.charAt(i));
        }
    }
    return sb.toString();
}

