class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron whose side length is *num*.
     *
     * The volume V of a regular tetrahedron with side length a is
     *     V = a³ / (6·√2)
     *
     * The result is rounded to two decimal places to match the expected output.
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        // Guard against non‑positive side lengths – a simple, defensive approach.
        if (num <= 0) {
            return 0.0;
        }

        // Compute the exact volume using the formula above.
        double volume = Math.pow(num, 3) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places (the expected output format).
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Return the boxed Double, matching the method’s return type.
        return rounded;
    }

    // A tiny test driver (not required by the problem, but handy for verification)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

