class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern to find words (sequences of letters only)
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();            // the current word
            String lower = word.toLowerCase();       // case‑insensitive check

            // A 'z' can only be "in the middle" if the word has at least 3 letters
            if (lower.length() >= 3) {
                // interior characters = everything except the first and last
                String interior = lower.substring(1, lower.length() - 1);
                if (interior.contains("z")) {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));     // "Not matched!"
    }
}

import java.util.List;
import java.util.Arrays;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner, ends at the bottom‑right corner and moves only
     * right or down.
     *
     * @param cost square matrix (List of List of Integer)
     * @param n    size of the matrix (n × n)
     * @return maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] – maximal sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                           + cost.get(i).get(j);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);   // number of visited cells
        return average;
    }

    // --------------------------------------------------------------------
    // Simple test driver (can be removed when the method is used elsewhere)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }

        int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // skip vowels – we only count consonants
            if (isVowel(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // check right neighbour
            if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /** Helper: returns true if the given character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // A simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

