/**
 * Utility class for counting alphabets, digits, and special characters
 * in a given string.
 */
class CountAlphaDigSpl {
    /**
     * Counts alphabets, digits and special characters in the supplied string.
     *
     * @param string the input string (may be null)
     * @return a List containing three integers:
     *         - count of alphabetic characters (A‑Z, a‑z)
     *         - count of digit characters (0‑9)
     *         - count of all other characters
     *
     * <p>Example usage:
     * <pre>
     * List&lt;Integer&gt; result = countAlphaDigSpl("abc!@#123");
     * // result == [3, 3, 3]
     * </pre>
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Handle null input gracefully – return zero counts.
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alphabets = 0;
        int digits = 0;
        int specials = 0;

        for (char ch : string.toCharArray()) {
            if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) {
                alphabets++;
            } else if (ch >= '0' && ch <= '9') {
                digits++;
            } else {
                specials++;
            }
        }

        // Return a fixed‑size list with the three counts.
        return Arrays.asList(alphabets, digits, specials);
    }

    // Optional main method for quick manual testing
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

