/**
 * Utility class for computing the sum of the series of squares:
 * 1² + 2² + 3² + … + n².
 */
class SeriesSum {

    /**
     * Returns the sum of the squares of the first {@code number} positive integers.
     *
     * @param number the count of terms (must be non‑negative)
     * @return the sum 1²+2²+…+number²
     */
    public static int seriesSum(int number) {
        // Guard against non‑positive input – the series is empty.
        if (number <= 0) {
            return 0;
        }

        // Use long arithmetic to avoid overflow of the intermediate products.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;   // n(n+1)(2n+1)/6

        // The problem statement expects an int; the cast is safe for typical inputs.
        return (int) sum;
    }

    // Simple manual test (can be removed or turned into JUnit tests)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

