import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)   for n >= 2
     *
     * Examples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // a0 and a1 are both 1
        if (n == 0 || n == 1) {
            return 1;
        }

        BigInteger a0 = BigInteger.ONE; // a(i‑2)
        BigInteger a1 = BigInteger.ONE; // a(i‑1)
        BigInteger a  = null;           // a(i)

        for (int i = 2; i <= n; i++) {
            // a = 2 * a1 + a0
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            // shift the window
            a0 = a1;
            a1 = a;
        }
        // The problem expects an int return type
        return a.intValue();
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

