class RemoveOdd {
    /**
     * Removes characters at odd positions (1‑based) from the input string.
     *
     * @param str1 the input string
     * @return a new string containing only the characters at even positions
     */
    public static String removeOdd(String str1) {
        // Guard against null or empty input
        if (str1 == null || str1.isEmpty()) {
            return str1;
        }

        StringBuilder sb = new StringBuilder();

        // Start from index 1 (the second character) and step by 2
        // because we want positions 2, 4, 6, … (1‑based)
        for (int i = 1; i < str1.length(); i += 2) {
            sb.append(str1.charAt(i));
        }

        return sb.toString();
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));    // "yhn"
        System.out.println(removeOdd("program"));   // "rga"
        System.out.println(removeOdd("language"));  // "agae"
    }
}

