class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split on whitespace – each element is a candidate word
        String[] words = text.split("\\s+");

        for (String word : words) {
            // Work case‑insensitively
            String w = word.toLowerCase();

            // Look for a 'z' that is not the first or last character
            boolean internalZ = false;
            for (int i = 1; i < w.length() - 1; i++) {
                if (w.charAt(i) == 'z') {
                    internalZ = true;
                    break;
                }
            }

            if (internalZ) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left cell
     * and ends at the bottom‑right cell of the given n×n matrix.
     * Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the size of the square matrix
     * @return the maximum possible average (as a Double)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] will hold the maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Initialize the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table: choose the better predecessor
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The maximum sum to reach the bottom‑right cell
        long maxSum = dp[n - 1][n - 1];

        // Number of cells visited on any valid path = (n‑1) + (n‑1) + 1 = 2*n‑1
        double average = (double) maxSum / (2 * n - 1);

        return average;
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // Expected: 7.2
    }
}

