import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path from the top‑left corner to the
     * bottom‑right corner of the given n×n matrix.  Movement is allowed only
     * to the right or down.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;                     // defensive programming
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);   // the cost of the current cell

                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    // take the better of the two possible predecessors
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + val;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // Any path from (0,0) to (n‑1,n‑1) using only right/down moves
        // visits exactly (2*n‑1) cells.
        double average = maxSum / (2.0 * n - 1);

        return average;
    }

    // --------------------------------------------------------------------
    // Optional test driver (can be removed when integrating into a larger
    // codebase).
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

