class NewmanPrime {
    /**
     * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // List to store NSW primes
        List<Long> primes = new ArrayList<>();

        // Initial values for the recurrence: a(0)=1, a(1)=1
        long a0 = 1;
        long a1 = 1;

        // Generate primes until we have enough
        if (n == 1) {
            // For n=1, we need the first prime (3)
            while (primes.size() < 1) {
                long a2 = 2 * a1 + a0;
                if (isPrime(a2)) {
                    primes.add(a2);
                }
                a0 = a1;
                a1 = a2;
            }
            return primes.get(0).intValue();
        } else {
            // For n>1, we need the (n-1)-th prime (0-indexed), so we need at least n-1 primes
            while (primes.size() < n - 1) {
                long a2 = 2 * a1 + a0;
                if (isPrime(a2)) {
                    primes.add(a2);
                }
                a0 = a1;
                a1 = a2;
            }
            // Return the (n-2)-th prime (0-indexed) for n>1
            return primes.get(n - 2).intValue();
        }
    }

    // Helper method to check if a number is prime
    private static boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

