class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a[0] = 1, a[1] = 1,
     *   a[n] = 2 * a[n‑1] + a[n‑2]  for n >= 2.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iterate using the recurrence
        int a0 = 1; // a[i‑2]
        int a1 = 1; // a[i‑1]
        int a = 0;  // a[i]

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a[i] = 2*a[i‑1] + a[i‑2]
            a0 = a1;
            a1 = a;
        }
        return a;
    }
}

