/**
 * Utility class that checks whether a word in the given text contains the
 * letter 'z' somewhere other than as the first or last character.
 *
 * The method returns one of two pre‑allocated strings, demonstrating the
 * static‑factory pattern and instance‑control.
 */
public final class TextMatchWordzMiddle {

    // Pre‑interned result strings – they can be returned directly
    private static final String FOUND      = "Found a match!";
    private static final String NOT_MATCHED = "Not matched!";

    // Prevent instantiation (Item 4)
    private TextMatchWordzMiddle() {
        throw new UnsupportedOperationException("Non‑instantiable");
    }

    /**
     * Static factory method that returns the appropriate pre‑allocated result.
     *
     * @param found true if a matching word was found, false otherwise
     * @return either {@value #FOUND} or {@value #NOT_MATCHED}
     */
    public static String fromBoolean(boolean found) {
        return found ? FOUND : NOT_MATCHED;
    }

    /**
     * Scans the input text for a word that contains the character 'z' but
     * not as the first or last letter.
     *
     * @param text the string to examine
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // \b\w+\b matches whole words (letters, digits, underscore)
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int idx = word.indexOf('z');           // position of 'z', if any
            // word contains 'z' and it is not the first nor the last character
            if (idx > 0 && idx < word.length() - 1) {
                return fromBoolean(true);
            }
        }
        return fromBoolean(false);
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));   // Not matched!
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    if (cost == null || n <= 0) {
        return null;               // defensive check
    }

    // dp[i][j] = maximum sum to reach cell (i, j)
    long[][] dp = new long[n][n];

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            long val = cost.get(i).get(j).longValue();

            if (i == 0 && j == 0) {
                dp[i][j] = val;                     // start cell
            } else {
                long best = Long.MIN_VALUE;
                if (i > 0) best = Math.max(best, dp[i - 1][j]); // from top
                if (j > 0) best = Math.max(best, dp[i][j - 1]); // from left
                dp[i][j] = val + best;
            }
        }
    }

    long maxSum = dp[n - 1][n - 1];
    // every path has (2*n - 1) cells
    double average = maxSum / (double) (2 * n - 1);
    return average;   // auto‑boxed to Double
}

