        // a(0) = 1, a(1) = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long prev2 = 1; // a(i‑2)
        long prev1 = 1; // a(i‑1)
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // recurrence
            prev2 = prev1;
            prev1 = current;
        }

        // The problem’s examples match a(3)=7, a(4)=17, a(5)=41
        return (int) current;
    }
}

