import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a monotonic path (right/down) from the
     * top‑left corner to the bottom‑right corner of the given n×n matrix.
     *
     * @param cost square matrix of integers
     * @param n    size of the matrix (number of rows/columns)
     * @return maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive check
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long val = cost.get(i).get(j).longValue();

                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[i][j] = val + dp[i][j - 1];
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[i][j] = val + dp[i - 1][j];
                } else {
                    // normal case: take the best of the two possible predecessors
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double maxAverage = maxSum / (double) (2 * n - 1);

        // Use the static factory method Double.valueOf (optional, just for style)
        return Double.valueOf(maxAverage);
    }
}

