    private CountVowels() { }

    /**
     * Counts consonants that have at least one vowel as an immediate neighbour
     * (either to the left or to the right).  Vowels themselves are never counted.
     *
     * @param testStr the input string (may contain mixed‑case letters)
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowel characters – we treat both lower‑ and upper‑case as vowels
        final Set<Character> VOWELS = Set.of('a', 'e', 'i', 'o', 'u',
                                             'A', 'E', 'I', 'O', 'U');

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only count consonants
            if (VOWELS.contains(ch)) {
                continue;
            }

            // Check left neighbour (if it exists)
            boolean leftIsVowel = (i > 0) && VOWELS.contains(testStr.charAt(i - 1));
            // Check right neighbour (if it exists)
            boolean rightIsVowel = (i < len - 1) && VOWELS.contains(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

