import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix.  
     * Movement is restricted to right or down only.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    dimension of the matrix
     * @return the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // A path from (0,0) to (n‑1,n‑1) using only right/down moves
        // always contains (2*n‑1) cells.
        double maxSum = dp[n - 1][n - 1];
        return maxSum / (2 * n - 1);
    }

    // Simple test driver
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

public class CountVowels {

    /**
     * Counts characters that are not vowels and have at least one vowel neighbour.
     *
     * @param testStr the input string (may be null or empty)
     * @return number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        String s = testStr.toLowerCase(); // case‑insensitive processing
        int n = s.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (isVowel(c)) {
                continue; // we only consider consonants
            }

            boolean hasVowelNeighbour = false;
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                hasVowelNeighbour = true;
            }
            if (i < n - 1 && isVowel(s.charAt(i + 1))) {
                hasVowelNeighbour = true;
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }
        return count;
    }

    /** Returns true if the given character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));         // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));           // 5
    }
}

