class SeriesSum {
    /**
     * Computes the sum of squares of the first n natural numbers.
     *
     * @param number the number of terms (n)
     * @return 1^2 + 2^2 + ... + n^2
     */
    public static int seriesSum(int number) {
        if (number <= 0) {
            return 0;
        }
        // Use long to avoid overflow of intermediate results
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;
