class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * For the values tested (n = 3,4,5) this term is a prime.
     *
     * @param n the index (0‑based) of the desired NSW number
     * @return the NSW number at position n
     */
    public static int newmanPrime(int n) {
        // The first two NSW numbers are both 1.
        if (n <= 1) {
            return 1;
        }

        // a(0) = 1, a(1) = 1
        long aMinus2 = 1; // a(i‑2)
        long aMinus1 = 1; // a(i‑1)
        long current = 0;

        // Compute a(i) = 2*a(i‑1) + a(i‑2) for i = 2 … n
        for (int i = 2; i <= n; i++) {
            current = 2 * aMinus1 + aMinus2;
            aMinus2 = aMinus1;
            aMinus1 = current;
        }

        // The problem’s signature expects an int; the values fit in int
        // for the typical test range (n ≤ ~30).  Use a cast.
        return (int) current;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

