class TextMatchWordzMiddle {
    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Use a static factory method (Pattern.compile) to obtain a Matcher
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // the current word
            String lower = word.toLowerCase();            // case‑insensitive check

            if (lower.contains("z")) {
                int firstZ = lower.indexOf("z");
                int lastZ  = lower.lastIndexOf("z");

                // ‘z’ must not be the first or the last character
                if (firstZ > 0 && lastZ < word.length() - 1) {
                    return "Found a match!";
                }
