import java.util.Arrays;
import java.util.List;

/**
 * Finds the maximum average of a path that starts in the upper‑left corner
 * of a square matrix and ends in the lower‑right corner, moving only right
 * or down.
 *
 * <p>The class follows the static‑factory‑method idiom (see Effective Java,
 * Item 1). The public API consists of two factory methods:
 * <ul>
 *   <li>{@link #maxaverageofpath(List, int)}</li>
 *   <li>{@link #valueOf(List, int)}</li>
 * </ul>
 *
 * <p>Both return the same result; {@code valueOf} follows the conventional
 * naming for static factories.
 */
public class Maxaverageofpath {

    /** Private constructor prevents direct instantiation. */
    private Maxaverageofpath() {
        throw new UnsupportedOperationException("static factory class");
    }

    /**
     * Returns the maximum average of a top‑left to bottom‑right path.
     *
     * @param cost the n×n matrix of non‑negative integers
     * @param n    size of the matrix (cost.size() == n)
     * @return the maximal average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Matrix size must be n × n");
        }

        // DP table: dp[i][j] = best sum to reach (i, j)
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                        + cost.get(i).get(j);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // length of any admissible path = 2*n - 1
        return maxSum / (2.0 * n - 1.0);
    }

    /**
     * Alias for {@link #maxaverageofpath(List, int)} – a static factory
     * method named according to the {@code valueOf} convention.
     *
     * @param cost the n×n matrix
     * @param n    size of the matrix
     * @return the maximal average
     */
    public static Double valueOf(List<List<Integer>> cost, int n) {
        return maxaverageofpath(cost, n);
    }

    /** Simple demonstration of the implementation. */
    public static void main(String[] args) {
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

