class NewmanPrime {
    /**
     * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle non-positive input
        if (n <= 0) {
            throw new IllegalArgumentException("Input must be positive");
        }

        // For n == 1, return the first NSW prime (3)
        if (n == 1) {
            return 3;
        }

        // For n >= 2, we need the (n-2)-th prime (0-indexed) in the NSW prime sequence
        int targetIndex = n - 2;

        // Initialize the first two NSW numbers: a(0)=1, a(1)=1
        BigInteger a0 = BigInteger.ONE;
        BigInteger a1 = BigInteger.ONE;

        // List to store NSW primes
        List<BigInteger> primes = new ArrayList<>();

        // Generate NSW numbers and check for primality until we have enough primes
        while (primes.size() <= targetIndex) {
            // Compute the next NSW number: a(n) = 2*a(n-1) + a(n-2)
            BigInteger a2 = a1.multiply(BigInteger.valueOf(2)).add(a0);

            // Check if a2 is prime (using probabilistic primality test with high certainty)
            if (a2.isProbablePrime(100)) {
                primes.add(a2);
            }

            // Update a0 and a1 for the next iteration
            a0 = a1;
            a1 = a2;
        }

        // Return the requested prime as an int (assuming it fits within int range)
        return primes.get(targetIndex).intValue();
    }
}

