/**
 * Helper to test primality of a (potentially large) number.
 */
private static boolean isPrime(long num) {
    if (num < 2)                return false;
    if (num % 2 == 0)           return num == 2;
    for (long i = 3; i <= num / i; i += 2) {
        if (num % i == 0)       return false;
    }
    return true;
}

/**
 * Returns the n‑th Newman–Shanks–Williams prime.
 * The sequence of NSW primes is: 2, 3, 7, 17, 41, 239, 577, …
 *
 * @param n 1‑based index (n must be > 0)
 * @return the n‑th NSW prime
 */
public static int newmanPrime(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }

    // Store the NSW primes we discover
    List<Integer> primes = new ArrayList<>();
    // The first NSW prime is 2
    primes.add(2);

    // Generate the NSW numbers using the recurrence:
    // a0 = 1, a1 = 1, a(i) = 2*a(i‑1) + a(i‑2)
    long a0 = 1;
    long a1 = 1;

    // Keep generating until we have collected at least n primes
    while (primes.size() < n) {
        long a2 = 2 * a1 + a0;   // next NSW number
        a0 = a1;
        a1 = a2;

        if (isPrime(a2)) {
            primes.add((int) a2);   // the result fits in int for reasonable n
        }
    }

    // 1‑based indexing → subtract one for list access
    return primes.get(n - 1);
}

