class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a path that
     * starts at the upper‑left cell (0,0) and ends at the lower‑right
     * cell (n‑1,n‑1) of the given n×n matrix.  Movement is allowed
     * only to the right or down.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     the dimension of the square matrix
     * @return      the maximum average of any valid path, or null if
     *              the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP[i][j] = max sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The best sum ends at the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // Every path from (0,0) to (n‑1,n‑1) visits exactly (2*n‑1) cells
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // -----------------------------------------------------------------
    // Optional test driver (feel free to remove or modify)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

