class CountVowels {
    /**
     * Counts the consonants in the given string that have a vowel
     * (a, e, i, o, u) as an immediate neighbour (either to the left
     * or to the right).
     *
     * @param testStr the input string
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        // Empty or single‑character strings cannot have a neighbour
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only care about consonants; skip vowels themselves
            if (isVowel(ch)) {
                continue;
            }

            // Check the left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                count++;
                continue;               // already counted, move to next character
            }

            // Check the right neighbour
            if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                count++;
            }
        }
        return count;
    }

    /** Helper: case‑insensitive vowel test. */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' ||
               lower == 'i' || lower == 'o' || lower == 'u';
    }
}

