class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2*a(n‑1) + a(n‑2)  for n >= 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     *
     * @param n the index (must be non‑negative)
     * @return the n‑th term of the Newman–Shanks–Williams sequence
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Handle the base cases
        if (n == 0 || n == 1) {
            return 1;   // a(0) = a(1) = 1
        }

        // Compute the sequence iteratively using long to avoid overflow
        long a0 = 1L; // a(n‑2)
        long a1 = 1L; // a(n‑1)
        long a  = 0L; // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(i) = 2*a(i‑1) + a(i‑2)
            // Shift the window for the next iteration
            a0 = a1;
            a1 = a;
        }

        // The problem expects an int; we cast the result.
        // For very large n the value may exceed Integer.MAX_VALUE,
        // in which case the cast discards higher bits.
        return (int) a;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

