class TextMatchWordzMiddle {

    /**
     * Write a function that matches a word containing 'z',
     * not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Defensive guard – treat null/empty as “no match”
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Regex explanation:
        // \b               – word boundary
        // [A-Za-z]+       – one or more letters (the part before the 'z')
        // z                – the literal 'z' we are looking for
        // [A-Za-z]+       – one or more letters (the part after the 'z')
        // \b               – closing word boundary
        // The pattern guarantees that 'z' is neither the first nor the last
        // character of a word.
        Pattern p = Pattern.compile("\\b[A-Za-z]+z[A-Za-z]+\\b");
        Matcher m = p.matcher(text);

        return m.find() ? "Found a match!" : "Not matched!";
    }

    // --------------------------------------------------------------------
    // Optional test driver (feel free to remove / comment out in production)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        String[] tests = {
            "pythonzabc.",
            "xyzabc.",
            "  lang  .",
            "zany",          // z is first → no match
            "bazz",          // z is last → no match
            "azb",           // z in middle → match
            "no-z-here",     // hyphen splits words, only “no” and “z” and “here” → no match
            "Zebra",         // uppercase Z should not match (spec uses lowercase)
            "abcz"           // z at end → no match
        };

        for (String t : tests) {
            System.out.println("Input : \"" + t + "\" → " + textMatchWordzMiddle(t));
        }
    }
}

import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all monotone paths
     * (moving only right or down) from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (must be > 0)
     * @return the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- defensive checks -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // Make sure we work with a square matrix of size n
        int size = Math.min(cost.size(), n);
        for (List<Integer> row : cost) {
            if (row == null || row.size() < size) {
                return null; // malformed input
            }
        }

        // ---- DP: maximum sum to reach each cell -------------------------------
        long[][] dp = new long[size][size];

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                int cur = cost.get(i).get(j);          // current cell value
                if (i == 0 && j == 0) {
                    dp[i][j] = cur;                     // start cell
                } else {
                    long fromAbove = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                    long fromLeft  = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;
                    dp[i][j] = cur + Math.max(fromAbove, fromLeft);
                }
            }
        }

        // ---- compute average ---------------------------------------------------
        long maxSum = dp[size - 1][size - 1];
        // Every monotone path visits exactly (2*size - 1) cells
        double maxAverage = maxSum / (double) (2 * size - 1);
        return maxAverage;
    }

    // -----------------------------------------------------------------------
    // Simple test driver (matches the examples from the description)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

