class CountVowels {

    /***
     * Counts characters that are not vowels but have a vowel as an immediate neighbour.
     *
     * A vowel is any of {@code a, e, i, o, u} (case‑insensitive).
     * The first and last characters are treated the same as any other position –
     * they are counted if they have a vowel neighbour on the side that exists.
     *
     * @param testStr the input string (may be {@code null} or empty)
     * @return the number of such characters
     *
     * <p>Example:
     * <ul>
     *   <li>{@code "bestinstareels" → 7}</li>
     *   <li>{@code "partofthejourneyistheend" → 12}</li>
     *   <li>{@code "amazonprime" → 5}</li>
     * </ul>
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set – using a Set for O(1) lookup
        final Set<Character> VOWELS = Set.of('a', 'e', 'i', 'o', 'u');

        // Work on a lower‑case copy so the check is case‑insensitive
        String lower = testStr.toLowerCase();

        int count = 0;
        int len = lower.length();

        for (int i = 0; i < len; i++) {
            char ch = lower.charAt(i);

            // Skip vowels themselves – we only count non‑vowel characters
            if (VOWELS.contains(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check the left neighbour (if it exists)
            if (i > 0 && VOWELS.contains(lower.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }

            // Check the right neighbour (if it exists)
            if (i < len - 1 && VOWELS.contains(lower.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // --------------------------------------------------------------------
    // A tiny driver to demonstrate the method (feel free to remove/ignore)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        String[] tests = {
            "bestinstareels",
            "partofthejourneyistheend",
            "amazonprime"
        };

        for (String s : tests) {
            System.out.printf("countVowels(\"%s\") = %d%n", s, countVowels(s));
        }
    }
}

