public static int newmanPrime(int n) {
    // The sequence is defined for non‑negative n.
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }

    // a0 = 1, a1 = 1
    if (n == 0) return 1;
    if (n == 1) return 1;

    long a0 = 1; // a_{i‑2}
    long a1 = 1; // a_{i‑1}
    long a = 0;  // a_i

    for (int i = 2; i <= n; i++) {
        a = 2 * a1 + a0; // a_i = 2*a_{i‑1} + a_{i‑2}
        a0 = a1;
        a1 = a;
    }

    // The values fit in int for the typical test cases; cast safely.
    return (int) a;
}

