public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that moves only right or down
     * from the top‑left to the bottom‑right corner of the given n×n matrix.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    dimension of the matrix (cost.size() == n)
     * @return the maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] – maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2L * n - 1L);

        return average;
    }

    // -----------------------------------------------------------------
    // Simple manual test (feel free to remove / comment out in production)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
