class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Null or empty string → no characters to count
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set (both lower‑ and upper‑case)
        final String vowels = "aeiouAEIOU";

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip the vowel characters themselves
            if (vowels.indexOf(ch) != -1) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbor
            if (i > 0) {
                char left = testStr.charAt(i - 1);
                if (vowels.indexOf(left) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbor (if not already found)
            if (!hasVowelNeighbor && i < len - 1) {
                char right = testStr.charAt(i + 1);
                if (vowels.indexOf(right) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

import java.util.ArrayList;
import java.util.List;

/**
 * Utility class to count alphabets, digits and special characters in a string.
 */
public class CountAlphaDigSpl {

    /**
     * Returns a list containing three integers:
     *   - number of alphabetic characters,
     *   - number of digit characters,
     *   - number of special (non‑letter, non‑digit) characters.
     *
     * @param str the input string (may be null)
     * @return list [alphabets, digits, specials]
     */
    public static List<Integer> countAlphaDigSpl(String str) {
        // Guard against null input
        if (str == null) {
            return List.of(0, 0, 0);               // Java 9+; for older JDK use Arrays.asList(0,0,0)
        }

        // Use a builder to gather the three counts
        Builder builder = new Builder();

        for (char ch : str.toCharArray()) {
            if (Character.isLetter(ch)) {
                builder.alpha();                  // increment alphabetic count
            } else if (Character.isDigit(ch)) {
                builder.digit();                  // increment digit count
            } else {
                builder.special();                 // increment special‑character count
            }
        }

        // Build the immutable result object
        CountResult result = builder.build();

        // Return the counts as a List<Integer>
        List<Integer> answer = new ArrayList<>();
        answer.add(result.getAlpha());
        answer.add(result.getDigit());
        answer.add(result.getSpecial());
        return answer;
    }

    // -----------------------------------------------------------------
    // Immutable value object that holds the three counts
    // -----------------------------------------------------------------
    private static final class CountResult {
        private final int alpha;
        private final int digit;
        private final int special;

        private CountResult(Builder builder) {
            this.alpha = builder.alpha;
            this.digit = builder.digit;
            this.special = builder.special;
        }

        int getAlpha()   { return alpha; }
        int getDigit()   { return digit; }
        int getSpecial() { return special; }
    }

    // -----------------------------------------------------------------
    // Builder for CountResult (per the “Consider a Builder” advice)
    // -----------------------------------------------------------------
    public static class Builder {
        private int alpha = 0;
        private int digit = 0;
        private int special = 0;

        /** Increments the alphabetic counter. */
        public Builder alpha() {
            alpha++;
            return this;
        }

        /** Increments the digit counter. */
        public Builder digit() {
            digit++;
            return this;
        }

        /** Increments the special‑character counter. */
        public Builder special() {
            special++;
            return this;
        }

        /** Constructs the immutable CountResult. */
        public CountResult build() {
            return new CountResult(this);
        }
    }

    // -----------------------------------------------------------------
    // Simple test driver (optional)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

