class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the value of n (must be non‑negative)
     * @return the sum of squares from 1 to number
     *
     * Example:
     * seriesSum(6) -> 91
     * seriesSum(7) -> 140
     * seriesSum(12) -> 650
     */
    public static int seriesSum(int number) {
        // Use long to avoid overflow while computing the intermediate product
        long n = number;
        // Formula: n * (n + 1) * (2n + 1) / 6
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;   // the result fits in an int for typical input ranges
    }

