class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        int len = text.length();
        int i = 0;

        while (i < len) {
            // Skip non‑letter characters to find the beginning of a word
            while (i < len && !Character.isLetter(text.charAt(i))) {
                i++;
            }
            if (i >= len) {
                break; // no more words
            }

            int start = i;
            // Advance to the end of the word
            while (i < len && Character.isLetter(text.charAt(i))) {
                i++;
            }
            int end = i; // exclusive

            String word = text.substring(start, end);

            // Check the required condition:
            // - contains at least one 'z'
            // - 'z' is not the first character
            // - 'z' is not the last character
            if (word.contains("z") && !word.startsWith("z") && !word.endsWith("z")) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!
    }
}

import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the upper‑left
     * cell (0,0) and ends at the bottom‑right cell (n‑1,n‑1), moving only
     * right or down.  The average is computed as (max sum) / (2·n‑1).
     *
     * @param cost the n×n matrix of integers
     * @param n    the dimension of the square matrix
     * @return the maximal possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximal sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // total number of cells visited on any path is (2*n - 1)
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return Double.valueOf(average);
    }

    // ------------------------------------------------------------------
    // Optional test driver (you can delete or comment out in production)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

