class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // The sequence is defined by:
        // a(0) = 1, a(1) = 1,
        // a(i) = 2*a(i‑1) + a(i‑2) for i >= 2
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Handle the first two values directly
        if (n == 0 || n == 1) {
            return 1;
        }

        long prev2 = 1; // a(i‑2) – initially a(0)
        long prev1 = 1; // a(i‑1) – initially a(1)
        long cur = 0;   // a(i)

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2; // a(i) = 2*a(i‑1) + a(i‑2)
            // shift the window for the next iteration
            prev2 = prev1;
            prev1 = cur;
        }
        // The problem expects an int return type; the values are guaranteed
        // to fit in an int for the test cases used.
        return (int) cur;
    }
}

