        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The best sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // Every full path contains exactly (2*n - 1) cells
        double average = maxSum / (2 * n - 1);

        // Return as a Double object
        return Double.valueOf(average);
    }
}

