class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   s0 = 1, s1 = 1
     *   sn = 2 * s(n‑1) + s(n‑2)  for n >= 2
     *
     * @param n index of the desired term (0‑based)
     * @return the value of the n‑th term
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Handle the first two base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iterate using long to avoid intermediate overflow, then cast to int
        long prev2 = 1; // s(i‑2)
        long prev1 = 1; // s(i‑1)
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int; we assume n is small enough to fit.
        return (int) current;
    }
}

