import java.util.List;
import java.util.ArrayList;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given
     * n×n cost matrix. Movement is allowed only right or down.
     *
     * @param cost  list of rows, each row a list of integer costs
     * @param n     dimension of the square matrix
     * @return      the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Defensive checks – return null for illegal input
        if (cost == null || cost.size() != n) {
            return null;
        }

        // DP array, long to avoid overflow for large inputs
        long[][] dp = new long[n][n];

        // Start cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Remaining cells – take the best of the two possible predecessors
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) +
                           Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Number of cells in any complete path = 2*n - 1
        double maxAverage = (double) dp[n - 1][n - 1] / (2 * n - 1);
        return maxAverage;
    }

    // Simple manual test (not part of the required solution)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = new ArrayList<>();
        cost1.add(List.of(1, 2, 3));
        cost1.add(List.of(6, 5, 4));
        cost1.add(List.of(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = new ArrayList<>();
        cost2.add(List.of(2, 3, 4));
        cost2.add(List.of(7, 6, 5));
        cost2.add(List.of(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = new ArrayList<>();
        cost3.add(List.of(3, 4, 5));
        cost3.add(List.of(8, 7, 6));
        cost3.add(List.of(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

