class NewmanPrime {
    /**
     * Finds the nth Newman-Shanks-Williams prime number.
     * 
     * @param n the index of the prime to find (1-indexed)
     * @return the nth Newman-Shaks-Williams prime
     */
    public static int newmanPrime(int n) {
        // List to store the NSW primes
        List<Long> primes = new ArrayList<>();
        primes.add(2L); // First NSW prime
        primes.add(3L); // Second NSW prime

        // Initialize the recurrence terms
        long p0 = 1;
        long p1 = 3;
        long p2 = 0;

        // Generate terms until we have at least n primes
        while (primes.size() < n) {
            p2 = 2 * p1 + p0;
            if (isPrime(p2)) {
                primes.add(p2);
            }
            p0 = p1;
            p1 = p2;
        }

        // Return the nth prime (convert to int)
        return (int) primes.get(n - 1);
    }

    /**
     * Checks if a number is prime.
     * 
     * @param num the number to check
     * @return true if prime, false otherwise
     */
    private static boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }
        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }

    // Main method for testing
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // Expected: 7
        System.out.println(newmanPrime(4)); // Expected: 17
        System.out.println(newmanPrime(5)); // Expected: 41
    }
}

