     * from the top‑left corner to the bottom‑right corner of the
     * given n×n matrix.  Movement is allowed only to the right or down.
     *
     * @param cost the square matrix (List of Lists of Integer)
     * @param n    dimension of the matrix
     * @return     the maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum of a path from (0,0) to (i,j)
        double[][] dp = new double[n][n];

        // Initialise the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                double bestFromAboveOrLeft = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = cost.get(i).get(j) + bestFromAboveOrLeft;
            }
        }

        // The number of cells visited on any such path is always 2*n - 1
        int totalCells = 2 * n - 1;
        double maxSum = dp[n - 1][n - 1];
        return maxSum / totalCells;
    }

    // ------------------------------------------------------------------
    // A tiny demo (you can remove this part when integrating into a larger project)
