/**
 * Utility class that counts consonants which are adjacent to a vowel
 * in a given string.
 *
 * The algorithm:
 *   – Iterate over each character of the input.
 *   – If the current character is a consonant (i.e. not a vowel),
 *     check its left and/or right neighbour(s). 
 *   – If at least one neighbour is a vowel (a, e, i, o, u – case‑insensitive),
 *     increment the result.
 *
 * The method is static because no instance state is required.
 */
class CountVowels {

    /** 
     * Returns the number of consonants in {@code testStr} that have 
     * a vowel as one of their immediate neighbours.
     *
     * @param testStr the input string (may be empty, must not be null)
     * @return the required count
     */
    public static int countVowels(String testStr) {
        // Guard against null/empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowels – both lower‑ and upper‑case for case‑insensitivity
        final String VOWELS = "aeiouAEIOU";

        char[] a = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < a.length; i++) {
            char cur = a[i];

            // We only care about consonants; skip vowels
            if (VOWELS.indexOf(cur) != -1) {
                continue;
            }

            boolean hasVowelNeighbour = false;

            // Check left neighbour
            if (i > 0 && VOWELS.indexOf(a[i - 1]) != -1) {
                hasVowelNeighbour = true;
            }
            // Check right neighbour (only if left didn’t already satisfy)
            if (!hasVowelNeighbour && i < a.length - 1 && VOWELS.indexOf(a[i + 1]) != -1) {
                hasVowelNeighbour = true;
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }

        return count;
    }

    // --------------------------------------------------------------------
    // Optional driver for manual testing (not required by the problem)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

