class SeriesSum {
    // ---- Singleton enforcement (Item 3) ----
    /** Sole instance – accessed via {@link #getInstance()}. */
    public static final SeriesSum INSTANCE = new SeriesSum();

    /** Private constructor prevents instantiation from outside. */
    private SeriesSum() {
        // No‑op – nothing to initialise
    }

    /** Returns the singleton instance. */
    public static SeriesSum getInstance() {
        return INSTANCE;
    }
    // -----------------------------------------

    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n (must be non‑negative)
     * @return the sum of squares 1²+…+n²
     *
     * <p>Examples:</p>
     * <ul>
     *   <li>seriesSum(6) → 91</li>
     *   <li>seriesSum(7) → 140</li>
     *   <li>seriesSum(12) → 650</li>
     * </ul>
     */
    public static int seriesSum(int number) {
        if (number <= 0) {
            return 0;                     // empty sum
        }
        // Use the closed‑form formula: n(n+1)(2n+1)/6
        // The intermediate result fits in a long, so we cast to long
        // before dividing to avoid any premature integer overflow.
        long result = (long) number * (number + 1) * (2L * number + 1) / 6;
        return (int) result;              // final result fits in int for typical inputs
    }
}

