import java.math.*;

class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2 * a(n‑1) + a(n‑2)   for n >= 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle the small base cases
        if (n <= 0) {
            // Not defined for non‑positive indices; return 0 as a safe default
            return 0;
        }
        if (n == 1) {
            return 1; // a(1) = 1
        }
        if (n == 2) {
            return 3; // a(2) = 3
        }

        // Iteratively compute the sequence using long to avoid overflow
        long a0 = 1; // a(1)
        long a1 = 3; // a(2)
        long a2 = 0;

        for (int i = 3; i <= n; i++) {
            a2 = 2 * a1 + a0; // a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a2;
        }

        // The result fits in an int for the expected range of n
        return (int) a1;
    }

    // Optional main method for quick testing
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

