public class TextMatchWordzMiddle {

    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Pattern to match words (sequences of letters)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A 'z' can only be “in the middle” if the word is longer than 2 characters
            if (word.length() > 2) {
                // Look at the substring that excludes the first and last characters
                String middle = word.substring(1, word.length() - 1);
                // If 'z' appears anywhere in that substring, we have a match
                if (middle.indexOf('z') != -1) {
                    return "Found a match!";
                }
            }
        }

        return "Not matched!";
    }
}

import java.util.List;

public class Maxaverageofpath {
    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given
     * n×n matrix. Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // Maximum sum from start to finish
        double maxSum = dp[n - 1][n - 1];

        // Path length = (n‑1) down moves + (n‑1) right moves + 1 cell = 2·n‑1
        double average = maxSum / (2.0 * n - 1);

        return average;
    }
}

