/**
 * Utility class that provides a static method to obtain the n‑th
 * Newman–Shanks–Williams number.  The prime values among these
 * numbers are the NSW primes.
 *
 * The sequence is defined by:
 *   a(0) = 1, a(1) = 1,
 *   a(n) = 2 * a(n‑1) + a(n‑2)   for n ≥ 2.
 *
 * The sample calls:
 *   newmanPrime(3) → 7
 *   newmanPrime(4) → 17
 *   newmanPrime(5) → 41
 */
public class NewmanPrime {

    // ----  Item 4: enforce noninstantiability  -------------------------
    /** Private constructor prevents instantiation. */
    private NewmanPrime() {
        // AssertionError provides a safety net in case of accidental call
        throw new AssertionError("Cannot instantiate " + NewmanPrime.class.getName());
    }
    // --------------------------------------------------------------------

    /**
     * Returns the n‑th term (zero‑based) of the Newman–Shanks–Williams
     * sequence.
     *
     * @param n the index of the term to compute (n ≥ 0)
     * @return the value of the n‑th term
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;   // a(0) = a(1) = 1
        }

        // Iterate using long to avoid intermediate overflow; final result fits in int
        long prev2 = 1L; // a(0)
        long prev1 = 1L; // a(1)
        long cur   = 0L;

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2; // a(i) = 2*a(i‑1) + a(i‑2)
            prev2 = prev1;
            prev1 = cur;
        }

        return (int) cur;
    }

    // Simple manual test (not required for the solution)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

