     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        // Volume of a regular tetrahedron: V = (sqrt(2) / 12) * a^3
        double volume = (Math.sqrt(2.0) / 12.0) * num * num * num;

        // Round to two decimal places (half‑up)
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Auto‑boxing to Double
        return rounded;
    }
}

