import java.util.*;
import java.math.*;

public class Maxaverageofpath {

    // ----  Item 4: enforce noninstantiability  ----
    private Maxaverageofpath() {
        // Private constructor prevents instantiation and also prevents subclassing
        throw new AssertionError("Cannot instantiate " + getClass().getName());
    }

    /**
     * Returns the maximum average of any path that goes from the top‑left
     * corner to the bottom‑right corner of the given n×n cost matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost  a list of n rows, each row a list of n integers
     * @param n     size of the square matrix (number of rows/columns)
     * @return      the maximum average as a {@code Double}, or {@code null}
     *              if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // DP array – using double to avoid overflow for large sums
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The path length is always (2*n - 1) cells
        double maxSum = dp[n - 1][n - 1];
        double maxAverage = maxSum / (2 * n - 1);

        return maxAverage;
    }

    // ---- simple test harness ----
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

