/**
 * Utility class that provides a static method to count consonants
 * that are adjacent to a vowel in a given string.
 *
 * The class is not intended to be instantiated – see the private constructor.
 */
public class CountVowels {

    /**
     * Suppress default constructor for noninstantiability.
     *
     * @throws AssertionError if accidentally invoked from within the class
     */
    private CountVowels() {
        throw new AssertionError("Cannot instantiate " + getClass().getName());
    }

    /**
     * Counts the characters (consonants) in {@code testStr} that have
     * at least one vowel (a, e, i, o, u) as an immediate neighbor
     * (either to the left or to the right).
     *
     * @param testStr the input string (may contain only letters)
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int length = testStr.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            char ch = testStr.charAt(i);

            // We only count consonants; skip vowels
            if (isVowel(ch)) {
                continue;
            }

            // Check left neighbor (if present)
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                count++;
                continue; // no need to check right neighbor
            }

            // Check right neighbor (if present)
            if (i < length - 1 && isVowel(testStr.charAt(i + 1))) {
                count++;
            }
        }

        return count;
    }

    /**
     * Determines whether a given character is a vowel (case‑insensitive).
     *
     * @param ch the character to test
     * @return {@code true} if {@code ch} is a, e, i, o, or u (ignoring case)
     */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u';
    }

    // -----------------------------------------------------------------
    // Optional test driver (can be removed when integrating into a larger project)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));         // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

