import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(1) = 1
     *   a(2) = 3
     *   a(k) = 2·a(k‑1) + a(k‑2)  for k > 2
     *
     * The examples match this definition:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n the index (1‑based) of the desired Newman‑Shanks‑Williams number
     * @return the value at position n
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // Base cases
        if (n == 1) return 1;   // a(1) = 1
        if (n == 2) return 3;  // a(2) = 3

        // Use long to avoid overflow before casting back to int.
        // The largest n that still fits in int is around 24.
        long prev2 = 1; // a(1)
        long prev1 = 3; // a(2)

        for (int i = 3; i <= n; i++) {
            long cur = 2 * prev1 + prev2; // a(i) = 2·a(i‑1) + a(i‑2)
            prev2 = prev1;
            prev1 = cur;
        }

        // The problem expects an int return type; the values fit for n ≤ 24.
        return (int) prev1;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

