/**
 * Utility class that checks whether any word in the supplied text contains the
 * letter 'z' in a position that is **not** the first or the last character of
 * the word.
 *
 * The matching behaviour is provided by a {@link WordMatcher} dependency,
 * which is injected (by default a {@link ZInMiddleMatcher}).  This follows the
 * recommendation from *Effective Java* – Item 5: “Prefer dependency injection
 * to hardwiring resources”.
 */
public class TextMatchWordzMiddle {

    /** Interface that decides whether a given word satisfies a condition. */
    @FunctionalInterface
    public interface WordMatcher {
        /** Returns true if the word matches the intended criteria. */
        boolean matches(String word);
    }

    /** Default implementation: word must contain 'z' (or 'Z') not at start/end. */
    public static class ZInMiddleMatcher implements WordMatcher {
        @Override
        public boolean matches(String word) {
            if (word == null || word.length() < 3) {
                return false;                     // can't have a middle character
            }
            for (int i = 1; i < word.length() - 1; i++) {
                if (Character.toLowerCase(word.charAt(i)) == 'z') {
                    return true;
                }
            }
            return false;
        }
    }

    // The injected matcher – initially the default ZInMiddleMatcher.
    private static WordMatcher matcher = new ZInMiddleMatcher();

    /** Allows injection of a custom {@link WordMatcher} (useful for testing). */
    public static void setMatcher(WordMatcher m) {
        if (m != null) {
            matcher = m;
        }
    }

    /**
     * Scans the supplied text for words (sequences of ASCII letters) and returns
     * "Found a match!" if any word contains the letter 'z' in a position that is
     * not the first or the last character.  Otherwise it returns "Not matched!".
     *
     * @param text the input string (may contain punctuation, spaces, etc.)
     * @return     "Found a match!" or "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // A word is defined as a consecutive run of ASCII letters (A–Z or a–z).
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher m = wordPattern.matcher(text);

        while (m.find()) {
            String word = m.group();
            if (matcher.matches(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // -----------------------------------------------------------------------
    // Simple manual test (can be removed or replaced by JUnit tests)
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));    // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  .")); // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that starts at the top‑left cell
     * and ends at the bottom‑right cell of the given n×n matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integers (List of rows)
     * @param n    size of the square matrix
     * @return     the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP[i][j] – maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Initialise the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                double best = Math.max(dp[i - 1][j], dp[i][j - 1]); // max from above or left
                dp[i][j] = best + cost.get(i).get(j);
            }
        }

        // The path always contains exactly (2*n - 1) cells
        int cellsInPath = 2 * n - 1;
        double maxSum = dp[n - 1][n - 1];
        double maxAverage = maxSum / cellsInPath;

        return Double.valueOf(maxAverage);
    }

    // --------------------------------------------------------------------
    // Simple manual test (you can remove or replace with JUnit tests)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
            List.of(1, 2, 3),
            List.of(6, 5, 4),
            List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
            List.of(2, 3, 4),
            List.of(7, 6, 5),
            List.of(8, 4, 10)
