class CountVowels {

    // Helper that tells whether a given character is a vowel (a, e, i, o, u)
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u';
    }

    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char current = testStr.charAt(i);

            // We only care about consonants (i.e. characters that are NOT vowels)
            if (!isVowel(current)) {
                boolean leftIsVowel  = (i > 0)         && isVowel(testStr.charAt(i - 1));
                boolean rightIsVowel = (i < len - 1) && isVowel(testStr.charAt(i + 1));

                // Count the consonant if it has at least one vowel neighbour
                if (leftIsVowel || rightIsVowel) {
                    count++;
                }
            }
        }
        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));           // 5
    }
}

import java.util.ArrayList;
import java.util.List;

/**
 * Counts alphabetic characters, digits and special characters in a string.
 *
 * The counting logic is driven by a {@link CharacterClassifier} that is injected
 * via the constructor.  This makes the class test‑friendly and flexible (e.g.
 * you could supply a different classifier for Unicode letters or for a
 * custom “digit” definition).
 */
public class CountAlphaDigSpl {

    /** Interface that determines what is considered an alphabet or a digit. */
    @FunctionalInterface
    public interface CharacterClassifier {
        /** Returns true if the given character is considered an alphabetic character. */
        boolean isAlphabet(char c);

        /** Returns true if the given character is considered a digit. */
        boolean isDigit(char c);
    }

    /** Default classifier that uses {@link Character#isLetter(char)} and
     *  {@link Character#isDigit(char)}. */
    public static final CharacterClassifier DEFAULT_CLASSIFIER = new CharacterClassifier() {
        @Override
        public boolean isAlphabet(char c) {
            return Character.isLetter(c);
        }

        @Override
        public boolean isDigit(char c) {
            return Character.isDigit(c);
        }
    };

    private final CharacterClassifier classifier;

    /** Constructs a counter that uses the supplied classifier. */
    public CountAlphaDigSpl(CharacterClassifier classifier) {
        if (classifier == null) {
            throw new IllegalArgumentException("classifier must not be null");
        }
        this.classifier = classifier;
    }

    /** Constructs a counter that uses the default classifier. */
    public CountAlphaDigSpl() {
        this(DEFAULT_CLASSIFIER);
    }

    /**
     * Returns a list containing the count of alphabetic characters,
     * digits, and special characters in the input string.
     *
     * @param string the input string
     * @return a list {@code [alphabets, digits, special]}
     */
    public List<Integer> countAlphaDigSpl(String string) {
        int alphabets = 0;
        int digits = 0;
        int specials = 0;

        for (int i = 0; i < string.length(); i++) {
            char ch = string.charAt(i);
            if (classifier.isAlphabet(ch)) {
                alphabets++;
            } else if (classifier.isDigit(ch)) {
                digits++;
            } else {
                specials++;
            }
        }

        List<Integer> result = new ArrayList<>(3);
        result.add(alphabets);
        result.add(digits);
        result.add(specials);
        return result;
    }

    /**
     * Static convenience method that uses the default classifier.
     *
     * @param string the input string
     * @return a list {@code [alphabets, digits, special]}
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Uses the default classifier – an example of “dependency injection”
        return new CountAlphaDigSpl(DEFAULT_CLASSIFIER).countAlphaDigSpl(string);
    }

    // ---------------------------------------------------------------
    // Example usage (can be removed when integrating into a test suite)
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n of the series (must be >= 0)
     * @return the sum of squares from 1 to n
     */
    public static int seriesSum(int number) {
        // Guard against non‑positive input
        if (number <= 0) {
            return 0;
        }

        // Use long for intermediate arithmetic to avoid overflow
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The result fits in an int for the expected range; cast back
        return (int) sum;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

