/**
 * Utility class for computing the Newman‑Shanks‑Williams numbers.
 *
 * The sequence is defined by:
 *   a(0) = 1, a(1) = 1,
 *   a(n) = 2·a(n‑1) + a(n‑2)  for n ≥ 2.
 *
 * The first few values are: 1, 1, 3, 7, 17, 41, 99, …
 */
public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * @param n the zero‑based index of the desired term (n ≥ 0)
     * @return the value of a(n) in the NSW sequence
     * @throws IllegalArgumentException if n is negative
     */
    public static long newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1L;
        }

        // Iteratively compute a(n) using the recurrence
        long aMinus2 = 1L; // a(i‑2)
        long aMinus1 = 1L; // a(i‑1)
        long aCurrent = 0L;

        for (int i = 2; i <= n; i++) {
            aCurrent = 2 * aMinus1 + aMinus2;
            // shift the window
            aMinus2 = aMinus1;
            aMinus1 = aCurrent;
        }

        return aCurrent;
    }

    // ---- Optional quick test -------------------------------------------------
    public static void main(String[] args) {
        // Example calls from the problem statement
        System.out.println(newmanPrime(3)); // → 7
        System.out.println(newmanPrime(4)); // → 17
        System.out.println(newmanPrime(5)); // → 41
    }
}

