import java.util.*;
import java.util.Objects;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a monotonic path
     * (moving only right or down) from the top‑left corner to the bottom‑right
     * corner of the given n×n cost matrix.
     *
     * @param cost the n×n matrix of non‑negative integers
     * @param n    the dimension of the square matrix
     * @return the highest average (as a {@code Double}) among all valid paths,
     *         or {@code null} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- Dependency‑injection style validation ----
        Objects.requireNonNull(cost, "Cost matrix must not be null");
        if (cost.size() != n) {
            throw new IllegalArgumentException(
                "Matrix dimension mismatch: expected " + n + " rows, got " + cost.size()
            );
        }
        for (int i = 0; i < n; ++i) {
            List<Integer> row = cost.get(i);
            Objects.requireNonNull(row, "Row " + i + " must not be null");
            if (row.size() != n) {
                throw new IllegalArgumentException(
                    "Row " + i + " has " + row.size() + " columns, expected " + n
                );
            }
        }

        // ---- DP to compute the maximum sum from (0,0) to (i,j) ----
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Remaining cells – choose the better predecessor
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                           + cost.get(i).get(j);
            }
        }

        // The path always contains exactly (2 * n - 1) cells
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);

        // Return as a boxed Double (as required by the signature)
        return Double.valueOf(average);
    }

    // --------------------------------------------------------------------
    // Example usage (matches the three test cases from the description)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
            List.of(1, 2, 3),
            List.of(6, 5, 4),
            List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = List.of(
            List.of(2, 3, 4),
            List.of(7, 6, 5),
            List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = List.of(
            List.of(3, 4, 5),
            List.of(8, 7, 6),
            List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Null or empty string yields 0
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowels (both lower‑ and upper‑case)
        Set<Character> vowels = new HashSet<>(Arrays.asList(
            'a', 'e', 'i', 'o', 'u',
            'A', 'E', 'I', 'O', 'U'
        ));

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only count consonants that are next to a vowel
            if (vowels.contains(ch)) {
                continue;
            }

            boolean leftIsVowel  = i > 0     && vowels.contains(testStr.charAt(i - 1));
            boolean rightIsVowel = i < len - 1 && vowels.contains(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend"));// 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

import java.util.*;
import java.util.function.Supplier;

/**
 * Utility class that counts alphabets, digits and special characters in a string.
 *
 * The counting logic is driven by a {@link CharacterClassifier} that can be
 * injected – this makes the class flexible and easy to test.
 */
public class CountAlphaDigSpl {

    /**
     * Enumeration describing the three possible categories of a character.
     */
    public enum Category {
        ALPHABET,
        DIGIT,
        SPECIAL
    }

    /**
     * Interface that decides to which category a given character belongs.
     * Implementations can be injected to replace the default behaviour.
     */
    @FunctionalInterface
    public interface CharacterClassifier {
        Category classify(char ch);
    }

    /**
     * Default implementation that uses {@link Character#isLetter(char)} and
     * {@link Character#isDigit(char)} from the JDK.
     */
    public static final class DefaultCharacterClassifier implements CharacterClassifier {
        @Override
        public Category classify(char ch) {
            if (Character.isLetter(ch)) {
                return Category.ALPHABET;
            } else if (Character.isDigit(ch)) {
                return Category.DIGIT;
            } else {
                return Category.SPECIAL;
            }
        }
    }

    /**
     * Returns a list containing three integers:
     * <ol>
     *   <li>Number of alphabetic characters</li>
     *   <li>Number of digit characters</li>
     *   <li>Number of special (non‑letter, non‑digit) characters</li>
     * </ol>
     *
     * @param string the input string (must not be {@code null})
     * @return a {@link List} with the three counts in the order described above
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Use a supplier to create the default classifier – this follows the
        // “pass a factory” variant of dependency injection (see Item 5).
        return countAlphaDigSpl(string, DefaultCharacterClassifier::new);
    }

    /**
     * Overloaded version that accepts a supplier of a {@link CharacterClassifier}.
     * This allows callers to inject their own classifier (e.g., a mock for unit tests).
     *
     * @param string            the input string (must not be {@code null})
     * @param classifierFactory a supplier that yields a {@code CharacterClassifier}
     * @return list with the three counts
     */
    public static List<Integer> countAlphaDigSpl(String string,
                                                 Supplier<? extends CharacterClassifier> classifierFactory) {
        Objects.requireNonNull(string, "Input string must not be null");
        Objects.requireNonNull(classifierFactory, "Classifier factory must not be null");

        final CharacterClassifier classifier = classifierFactory.get();

        int alphabets = 0;
        int digits    = 0;
        int specials  = 0;

        for (int i = 0; i < string.length(); i++) {
            switch (classifier.classify(string.charAt(i))) {
                case ALPHABET:
                    alphabets++;
                    break;
                case DIGIT:
                    digits++;
                    break;
                case SPECIAL:
                    specials++;
                    break;
            }
        }

        // Return an immutable list to preserve immutability (Item 17)
        return Collections.unmodifiableList(Arrays.asList(alphabets, digits, specials));
    }

    // -----------------------------------------------------------------------
    // Example usage (uncomment to run)
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

