import java.util.ArrayList;
import java.util.List;
import java.math.BigInteger;

public class NewmanPrime {

    // Reusable constant – avoids repeated allocations
    private static final BigInteger TWO = BigInteger.valueOf(2);

    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     * The sequence of NSW primes begins: 2, 3, 7, 17, 41, …
     *
     * @param n 1‑based index (n >= 1)
     * @return the n‑th NSW prime as an int
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // The first NSW prime is 2, which is not generated by the recurrence.
        if (n == 1) {
            return 2;
        }

        // Store the primes we have found so far.
        List<BigInteger> primes = new ArrayList<>(n);
        primes.add(TWO);                 // 2

        // NSW recurrence: a0 = 1, a1 = 1,
        // a(i) = 2 * a(i‑1) + a(i‑2)  for i >= 2
        BigInteger a0 = BigInteger.ONE; // a(0)
        BigInteger a1 = BigInteger.ONE; // a(1)
        BigInteger a_i = null;

        while (primes.size() < n) {
            // Compute next NSW number
            a_i = a1.multiply(TWO).add(a0);

            // Probabilistic primality test (certainty = 100) – fast & reusable
            if (a_i.isProbablePrime(100)) {
                primes.add(a_i);
            }

            // Shift the window for the next iteration
            a0 = a1;
            a1 = a_i;
        }

        // The result is guaranteed to fit into an int for the intended input range.
        return primes.get(n - 1).intValue();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        for (int i = 1; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

