class VolumeTetrahedron {

    // Reuse the immutable sqrt(2) value – no need to compute it each time.
    private static final double SQRT2 = Math.sqrt(2.0);

    /**
     * Calculates the volume of a regular tetrahedron with side length `num`.
     *
     * The volume formula for a regular tetrahedron is:
     *     V = a³ / (6·√2)
     *
     * The result is rounded to two decimal places to match the expected output.
     *
     * @param num the side length of the tetrahedron (integer)
     * @return the volume as a {@code Double}
     */
    public static Double volumeTetrahedron(int num) {
        double side = num;                     // convert int → double
        // V = a³ / (6·√2)
        double volume = (side * side * side) / (6.0 * SQRT2);

        // Round to two decimal places (e.g., 117.85, 397.75, 942.81)
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Auto‑boxing to Double (the method signature requires a Double)
        return rounded;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

