/**
 * Detects a word that contains the letter 'z' (or 'Z') somewhere
 * other than the first or last position.
 */
public class TextMatchWordzMiddle {

    // Compiled once and reused for every call – no unnecessary object creation.
    private static final Pattern WORD_PATTERN = Pattern.compile("\\b[A-Za-z]+\\b");

    public static String textMatchWordzMiddle(String text) {
        Matcher matcher = WORD_PATTERN.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int len = word.length();

            // Need at least three characters to have a middle position.
            if (len >= 3) {
                // Scan only the interior characters (skip first and last).
                for (int i = 1; i < len - 1; i++) {
                    char c = word.charAt(i);
                    if (c == 'z' || c == 'Z') {
                        return "Found a match!";
                    }
                }
            }
        }

        return "Not matched!";
    }

    // Simple sanity check (can be removed in production)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

