/**
 * Solution for the "Maximum average of path" problem.
 *
 * Given an n×n matrix of costs, find the path from the top‑left corner to the
 * bottom‑right corner (moving only right or down) that yields the highest average
 * value.  The average is computed as (sum of visited cells) / (2·n‑1) because
 * every such path contains exactly that many cells.
 */
class Maxaverageofpath {

    /**
     * Computes the maximum possible average of a right‑/down‑only path
     * from the top‑left to the bottom‑right of the given square matrix.
     *
     * @param cost the n×n matrix of integer costs (as a list of rows)
     * @param n    the dimension of the matrix (number of rows/columns)
     * @return     the maximum average as a {@code Double}, or {@code null} if
     *             the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation ------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // ---- DP: max sum to reach each cell ----------------------------------
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // rest of the table: take the better predecessor and add current cost
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // ---- compute average --------------------------------------------------
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // -----------------------------------------------------------------------
    // Optional simple test driver (can be removed when integrating into a
    // larger codebase).
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

class CountVowels {
    /** 
     * Counts characters that are **not** vowels but have at least one vowel neighbour
     * (either to the left or to the right).
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        // Null/empty guard – no characters can satisfy the condition.
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Re‑used vowel table – stored once, not recreated on each call.
        final String VOWELS = "aeiouAEIOU";

        int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only count non‑vowel characters.
            if (VOWELS.indexOf(ch) != -1) {
                continue;
            }

            // Check left neighbour.
            boolean hasVowelNeighbor = (i > 0 && VOWELS.indexOf(testStr.charAt(i - 1)) != -1);

            // Check right neighbour if we haven't found a vowel yet.
            if (!hasVowelNeighbor && i < len - 1) {
                hasVowelNeighbor = (VOWELS.indexOf(testStr.charAt(i + 1)) != -1);
            }

            if (hasVowelNeighbor) {
                ++count;
            }
        }
        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));          // 5
    }
}

import java.util.List;
import java.util.Arrays;

public class CountAlphaDigSpl {

    /**
     * Counts alphabets, digits and special characters in the given string.
     *
     * @param string the input text (must not be null)
     * @return a List containing three integers: [alphabets, digits, special characters]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        int alphas = 0;
        int digits = 0;
        int specials = 0;

        // Iterate over each character without creating any new objects.
        for (int i = 0, len = string.length(); i < len; i++) {
            char ch = string.charAt(i);
            if (Character.isLetter(ch)) {
                alphas++;
            } else if (Character.isDigit(ch)) {
                digits++;
            } else {
                specials++;
            }
        }

        // Reuse the immutable list returned by Arrays.asList.
        return Arrays.asList(alphas, digits, specials);
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

public static int seriesSum(int number) {
    // Use a primitive long to avoid overflow while computing the formula.
    long n = number;
    // Sum of squares = n*(n+1)*(2n+1)/6
    return (int)(n * (n + 1) * (2 * n + 1) / 6);
}

import java.util.List;

class LenLog {
    /**
     * Returns the length of the longest string in the given list.
     *
     * @param list1 a list of strings (may be empty or contain nulls)
     * @return length of the longest string, or 0 if the list is empty
     */
    public static int lenLog(List<String> list1) {
        // Guard against null or empty input – no need to create any extra objects
        if (list1 == null || list1.isEmpty()) {
            return 0;
        }

        int maxLen = 0;
        for (String word : list1) {
            // Skip null entries to avoid NullPointerException
            if (word != null && word.length() > maxLen) {
                maxLen = word.length();
            }
        }
        return maxLen;
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(lenLog(java.util.Arrays.asList("python", "PHP", "bigdata"))); // 7
        System.out.println(lenLog(java.util.Arrays.asList("a", "ab", "abc")));           // 3
        System.out.println(lenLog(java.util.Arrays.asList("small", "big", "tall")));    // 5
    }
}

public class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The NSW sequence is defined by:
     *   a(0) = 1,  a(1) = 1
     *   a(n) = 2·a(n‑1) + a(n‑2)   for n ≥ 2
     *
     * For the first few indices (n = 2,3,4,5) the result is a prime,
     * which is why these values are referred to as “Newman‑Shanks‑Williams primes”.
     *
     * @param n the index of the desired term (must be ≥ 0)
     * @return the n‑th term of the NSW sequence
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;   // a(0) = a(1) = 1
        }

        // Compute the sequence iteratively – O(n) time, O(1) extra space
        int aMinus2 = 1; // a(0)
        int aMinus1 = 1; // a(1)
        int current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * aMinus1 + aMinus2; // a(i) = 2·a(i‑1) + a(i‑2)
            // Shift the window for the next iteration
            aMinus2 = aMinus1;
            aMinus1 = current;
        }

        return current;
    }
}

import java.util.*;

public class RemoveOdd {

    /**
     * Removes characters at odd positions (1‑indexed) from the input string.
     * Example: "python" → "yhn"
     *
     * @param str1 the original string (may be null)
     * @return a new string containing only the characters at even positions,
     *         or null if the input is null
     */
    public static String removeOdd(String str1) {
        // Guard against null input
        if (str1 == null) {
            return null;
        }

        // StringBuilder avoids repeated string allocations
        StringBuilder result = new StringBuilder(str1.length() / 2 + 1);

        // Start at index 1 (the 2nd character) and step by 2
        for (int i = 1; i < str1.length(); i += 2) {
            result.append(str1.charAt(i));
        }

        return result.toString();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));    // → "yhn"
        System.out.println(removeOdd("program"));   // → "rga"
        System.out.println(removeOdd("language"));  // → "agae"
    }
}

