class VolumeTetrahedron {
    // Reuse the constant factor – avoids recomputing sqrt(2) on every call.
    private static final double VOLUME_FACTOR = 1.0 / (6.0 * Math.sqrt(2.0));

    /**
     * Calculates the volume of a regular tetrahedron with side length `num`.
     *
     * @param num the length of each edge (integer)
     * @return the volume rounded to two decimal places
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        // Volume formula for a regular tetrahedron: V = a³ / (6·√2)
        double volume = VOLUME_FACTOR * num * num * num;

        // Round to two decimal places (as shown in the examples)
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Return the boxed Double (as required by the method signature)
        return Double.valueOf(rounded);
    }
}

import java.util.regex.Pattern;

class TextMatchWordzMiddle {

    // Compile the regex once and keep it immutable.
    // \b          – word boundary
    // \w+         – one or more word characters before the 'z'
    // z           – the literal 'z'
    // \w+         – one or more word characters after the 'z'
    // \b          – word boundary
    // This forces the 'z' to be neither the first nor the last character of a word.
    private static final Pattern WORD_WITH_Z_MIDDLE = Pattern.compile("\\b\\w+z\\w+\\b");

    /**
     * Returns "Found a match!" if the input text contains a word that has the
     * letter 'z' somewhere other than the first or last position; otherwise
     * returns "Not matched!".
     *
     * @param text the input string to examine
     * @return the appropriate match message
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }
        // Use find() rather than matches() – we only need to know whether such a word exists.
        return WORD_WITH_Z_MIDDLE.matcher(text).find()
                ? "Found a match!"
                : "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));     // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class Maxaverageofpath {
    /**
     * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP array stores the maximum sum to reach each cell.
        double[][] dp = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double cur = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = cur;                 // start cell
                } else {
                    double fromTop = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double fromLeft = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = cur + Math.max(fromTop, fromLeft);
                }
            }
        }
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);
        return average;
    }

    // Simple test harness
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

import java.io.*;
