class CountVowels {

    /** 
     * Vowels are immutable and can be reused safely – create the set once.
     */
    private static final Set<Character> VOWELS = Set.of(
            'a', 'e', 'i', 'o', 'u',
            'A', 'E', 'I', 'O', 'U'
    );

    /**
     * Counts characters that are NOT vowels (i.e., consonants) and that have
     * at least one vowel neighbour (to the left or right).
     *
     * @param testStr the input string
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // only consider consonants; vowels are ignored
            if (!VOWELS.contains(ch)) {
                boolean hasVowelNeighbor = false;

                // check left neighbour
                if (i > 0 && VOWELS.contains(testStr.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // check right neighbour if not already found
                else if (i < len - 1 && VOWELS.contains(testStr.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    // Simple test harness
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;
import java.util.regex.*;   // needed for Pattern and Matcher

class CountAlphaDigSpl {

    // Pre‑compiled patterns – created once and reused (Item 6)
    private static final Pattern ALPHA  = Pattern.compile("[a-zA-Z]");
    private static final Pattern DIGIT  = Pattern.compile("\\d");
    private static final Pattern SPECIAL = Pattern.compile("[^a-zA-Z\\d]");

    /**
     * Write a function to count alphabets, digits and special characters in a given string.
     *
     * > countAlphaDigSpl("abc!@#123")
     * [3, 3, 3]
     * > countAlphaDigSpl("dgsuy@#$%&1255")
     * [5, 4, 5]
     * > countAlphaDigSpl("fjdsif627348#%$^&")
     * [6, 6, 5]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Guard against null input
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alphaCount  = countMatches(string, ALPHA);
        int digitCount  = countMatches(string, DIGIT);
        int specialCount = countMatches(string, SPECIAL);

        // Return result as a List<Integer>
        return Arrays.asList(alphaCount, digitCount, specialCount);
    }

    /** Helper method that counts non‑overlapping matches of a pattern in a string. */
    private static int countMatches(String s, Pattern p) {
        Matcher m = p.matcher(s);
        int count = 0;
        while (m.find()) {
            count++;
        }
        return count;
    }
}

