class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        if (n == 0) return 1;
        if (n == 1) return 1;
        long a = 1; // s_{n-2}
        long b = 1; // s_{n-1}
        long c = 0;
        for (int i = 2; i <= n; i++) {
            c = 2 * b + a;
            a = b;
            b = c;
        }
        return (int) b;
    }
}

