import java.lang.Math;   // optional, since Math is automatically available

class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron given its side length.
     *
     * @param num the side length of the tetrahedron
     * @return the volume
     */
    public static Double volumeTetrahedron(int num) {
        // Use a primitive double for the calculation (no autoboxing overhead)
        double side = (double) num;
        double volume = (side * side * side) / (6.0 * Math.sqrt(2.0));
        // The returned value is automatically boxed to Double
        return volume;
    }

    // Optional main to quick‑check the examples
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

public static String textMatchWordzMiddle(String text) {
    // Replace any non‑letter characters with spaces so that each word is isolated
    String cleaned = text.replaceAll("[^a-zA-Z]", " ");
    // Split the string on whitespace to obtain individual words
    String[] words = cleaned.split("\\s+");

    for (String word : words) {
        // A word must be at least 3 characters long to have a middle position
        if (word.length() >= 3) {
            // Look for a 'z' that is not the first or last character
            for (int i = 1; i < word.length() - 1; i++) {
                if (word.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }
    }
    return "Not matched!";
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given square
     * matrix, moving only right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the matrix
     * @return the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] holds the maximum sum to reach (i, j)
        long[][] dp = new long[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells: take the best of the two possible predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                        + cost.get(i).get(j);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);

        return average;               // autoboxed to Double
    }
}

