class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper limit of the series (n)
     * @return the sum of squares from 1 to n
     *
     * Example:
     * seriesSum(6) → 91
