     * seriesSum(12) → 650
     */
    public static int seriesSum(int number) {
        // Use the mathematical formula: n(n + 1)(2n + 1) / 6
        // Compute with 'long' to avoid overflow, then cast back to 'int'.
        long n = number;                     // primitive long, no autoboxing
        long sum = n * (n + 1) * (2 * n + 1) / 6; // all arithmetic stays primitive
        return (int) sum;                     // final result fits in an int for typical inputs
    }
}

