class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // The sequence is defined by:
        // a0 = 1, a1 = 1
        // a(i) = 2*a(i-1) + a(i-2) for i >= 2
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Use long to avoid overflow for reasonable input sizes.
        long a0 = 1; // a(0)
        long a1 = 1; // a(1)

        if (n == 0) return (int) a0;
        if (n == 1) return (int) a1;

        long current = 0;
        for (int i = 2; i <= n; i++) {
            current = 2 * a1 + a0;
            a0 = a1;
            a1 = current;
        }
        return (int) current;
    }

    // Simple test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

