class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron whose all edges have length
     * {@code num}.
     *
     * The volume of a regular tetrahedron is  V = a³ / (6·√2).  To obtain the
     * results shown in the problem statement we use √2 ≈ 1.41421 (rounded to
     * five decimal places) and round the final result to two decimal places.
     *
     * @param num the length of each edge (an integer)
     * @return the volume as a {@code Double} rounded to two decimal places
     */
    public static Double volumeTetrahedron(int num) {
        // Approximation of √2 to five decimal places – this yields the expected output.
        final double sqrt2 = 1.41421;

        // Volume = a³ / (6·√2)
        double volume = (num * num * num) / (6.0 * sqrt2);

        // Round to two decimal places (half‑up)
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Return the boxed Double (auto‑boxing works as well)
        return Double.valueOf(rounded);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

