import java.util.*;

public class Maxaverageofpath {
    /**
     * Returns the maximum average of any path from the top‑left corner to the
     * bottom‑right corner of the given n×n matrix, moving only right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    dimension of the square matrix
     * @return the maximum average as a {@code Double}, or {@code null} for
     *         invalid input
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against bad input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP array holds the best sum to reach each cell in the current row.
        // Using long prevents overflow for large n and large cell values.
        long[] dp = new long[n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                int val = row.get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[0] = val;
                } else if (i == 0) {
                    // First row: can only come from the left
                    dp[j] = dp[j - 1] + val;
                } else if (j == 0) {
                    // First column: can only come from above
                    dp[0] = dp[0] + val;
                } else {
                    // General case: take the better of the cell above or left
                    dp[j] = val + Math.max(dp[j], dp[j - 1]);
                }
            }
        }

        // All paths have exactly (2*n - 1) cells, so average = sum / (2*n - 1)
        double maxAvg = dp[n - 1] / (2.0 * n - 1);
        // Boxing only at the final return
        return Double.valueOf(maxAvg);
    }
}

