class CountVowels {
    /**
     * Counts consonants that have at least one vowel as a neighbour
     * (either on the left or on the right side).
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with lower‑case characters only
        String s = testStr.toLowerCase();

        // Vowel set as a constant string – no extra objects are created
        final String VOWELS = "aeiou";

        int count = 0;
        int len = s.length();

        for (int i = 0; i < len; i++) {
            char ch = s.charAt(i);

            // Skip vowels – we only count consonants
            if (VOWELS.indexOf(ch) != -1) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0 && VOWELS.indexOf(s.charAt(i - 1)) != -1) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour if we haven't found a vowel yet
            if (!hasVowelNeighbor && i < len - 1 && VOWELS.indexOf(s.charAt(i + 1)) != -1) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple manual test (optional)
