        // Compute the sequence iteratively
        long prev2 = 1; // a[0]
        long prev1 = 1; // a[1]
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // a[i] = 2*a[i‑1] + a[i‑2]
            prev2 = prev1;
            prev1 = current;
        }

        // The returned value is the n‑th NSW number; for the given
        // inputs (n = 3,4,5) this number is prime.
        return (int) current;
    }
}

