import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a monotonic
     * (right/down) path from the top‑left corner to the bottom‑right
     * corner of the given n×n cost matrix.
     *
     * @param cost  list of rows, each row is a list of integers
     * @param n     size of the square matrix
     * @return      maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;                     // defensive programming
        }

        // dp[i][j] holds the best sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // initial cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                long bestFromAboveOrLeft = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = cost.get(i).get(j) + bestFromAboveOrLeft;
            }
        }

        // total number of cells visited on any monotonic path = 2*n - 1
        double pathLength = 2.0 * n - 1.0;
        return dp[n - 1][n - 1] / pathLength;
    }

    // --------------------------------------------------------------------
    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

