import java.math.BigInteger;

class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * For n >= 2 this term is a prime (e.g., 3, 7, 17, 41, …).
     *
     * @param n index of the required term (0‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases: the first two values are 1
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use BigInteger to avoid overflow for larger indices.
        // We keep only the two most recent values, so no obsolete
        // object references remain after each iteration.
        BigInteger aMinus2 = BigInteger.ONE; // a_{i‑2}
        BigInteger aMinus1 = BigInteger.ONE; // a_{i‑1}
        BigInteger current = BigInteger.ZERO;

        for (int i = 2; i <= n; i++) {
            // a_i = 2 * a_{i‑1} + a_{i‑2}
            current = aMinus1.multiply(BigInteger.valueOf(2)).add(aMinus2);

            // Shift the window – the older reference becomes obsolete
            aMinus2 = aMinus1;
            aMinus1 = current;
        }

        // The result fits into an int for the expected range of n.
        return current.intValue();
    }
}

