class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Use a regular expression to extract words (sequences of letters).
        // Define Pattern and Matcher in the narrowest possible scope.
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher wordMatcher = wordPattern.matcher(text);

        boolean found = false;

        // Iterate over each word in the input text.
        while (wordMatcher.find()) {
            String word = wordMatcher.group();

            // Check whether the word contains a 'z' that is not the first or last character.
            boolean interiorZ = false;
            // Examine only the interior characters (index 1 to length‑2).
            for (int i = 1; i < word.length() - 1; i++) {
                if (word.charAt(i) == 'z') {
                    interiorZ = true;
                    break; // No need to continue once we find an interior 'z'.
                }
            }

            if (interiorZ) {
                found = true;
            }

            // Eliminate obsolete reference to the word after processing.
            word = null;
        }

        // Eliminate obsolete references to the Pattern and Matcher.
        wordMatcher = null;
        wordPattern = null;

        return found ? "Found a match!" : "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
        System.out.println(textMatchWordzMiddle("  lang  ."));
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that starts at the top‑left
     * cell of the given n×n matrix and ends at the bottom‑right cell.
     * Movement is allowed only to the right or downwards.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the square matrix
     * @return the maximum average as a Double, or null for illegal input
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // ---- DP table: dp[i][j] = best sum to reach cell (i, j) -------------
        double[][] dp = new double[n][n];

        // first cell
        dp[0][0] = cost.get(0).get(0);

        // first row (只能從左邊來)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column (只能從上邊來)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average --------------------------------------------------
        double maxSum = dp[n - 1][n - 1];
        double avg = maxSum / (2 * n - 1);

        // round to one decimal place (as shown in the examples)
        avg = Math.round(avg * 10.0) / 10.0;

        // ---- eliminate obsolete reference (see Item 7) -----------------------
        dp = null;   // allow the GC to reclaim the table now that we no longer need it

        return avg;
    }

    // -----------------------------------------------------------------------
    // Optional test driver (can be removed when the method is used elsewhere)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

