class NewmanPrime {
    /**
     * Returns the n-th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   s_0 = 1, s_1 = 1
     *   s_n = 2 * s_{n-1} + s_{n-2} for n >= 2
     *
     * @param n the index (1‑based) of the term to return
     * @return the n‑th term of the sequence
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // For n == 1 the sequence value is 1 (not a prime)
        if (n == 1) {
            return 1;
        }
        long prev2 = 1; // s_{i-2}
        long prev1 = 1; // s_{i-1}
        for (int i = 2; i <= n; i++) {
            long current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        // The values grow quickly; we cast to int assuming n is small enough
        // to fit in an int. For larger n a bigger type should be used.
        return (int) prev1;
    }
}

