public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path from the top‑left cell
     * to the bottom‑right cell of the given n×n cost matrix.
     * Movement is allowed only rightwards or downwards.
     *
     * @param cost  a square list of lists representing the matrix
     * @param n     dimension of the matrix (cost.size() == n)
