            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long val = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // First row: can only come from the left
                    dp[i][j] = val + dp[0][j - 1];
                } else if (j == 0) {
                    // First column: can only come from above
                    dp[i][j] = val + dp[i - 1][0];
                } else {
                    // General case: take the better of the two predecessors
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // Maximum sum to reach the bottom‑right corner
        long maxSum = dp[n - 1][n - 1];

        // Every path contains exactly (2 * n - 1) cells
        double average = maxSum / (double) (2 * n - 1);

        return average;
    }
}

