class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2·a(n‑1) + a(n‑2)  for n ≥ 2
     *
     * @param n the index (1‑based) of the desired term
     * @return the value a(n)
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // a(0) and a(1) are both 1
        if (n == 1) {
            return 1;
        }

        long prev2 = 1; // a(i‑2)
        long prev1 = 1; // a(i‑1)

        for (int i = 2; i <= n; i++) {
            long current = 2 * prev1 + prev2; // a(i)
            prev2 = prev1;
            prev1 = current;
        }

        // The result fits in an int for reasonable values of n;
        // for very large n you could switch to long or BigInteger.
        return (int) prev1;
    }
}

