public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the letter 'z'
     * (or 'Z') somewhere other than the first or last character of that word.
     * Otherwise returns "Not matched!".
     *
     * @param text the input string (may contain punctuation, spaces, etc.)
     * @return    the result message
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches a contiguous sequence of letters (a‑z or A‑Z)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A word must be at least 3 characters long to have an interior position
            if (word.length() < 3) {
                continue;
            }

            // Scan the word for a 'z' (case‑insensitive) that is not at index 0 or at the last index
            for (int i = 1; i < word.length() - 1; i++) {
                if (Character.toLowerCase(word.charAt(i)) == 'z') {
                    return "Found a match!";
                }
            }
        }

        return "Not matched!";
    }

    // Simple manual test harness
