public class NewmanPrime {
    /**
     * Returns the n-th term of the Newman-Shanks-Williams sequence.
     * The sequence is defined by a(0) = 1, a(1) = 1, and a(k) = 2*a(k-1) + a(k-2) for k >= 2.
     * The returned value is the n-th term (i.e., a(n)).
     *
     * @param n the index of the term to return (>= 0)
     * @return the n-th Newman-Shanks-Williams number
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        if (n == 0 || n == 1) {
            return 1;
        }
        long a0 = 1;
        long a1 = 1;
        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }
}

