public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a monotonic path
     * (only right/down moves) from the top‑left to the bottom‑right
     * of an n×n cost matrix.
     *
     * @param cost  a square matrix represented as a list of rows,
     *              each row being a list of integers
     * @param n     the dimension of the square matrix (number of rows/columns)
     * @return      the maximum average as a Double; the fractional part
     *              reflects the true average (rounded to one decimal place
     *              in the examples)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.size() != n) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int cur = cost.get(i).get(j);          // value of current cell

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cur;
                } else {
                    double bestFromAbove = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double bestFromLeft  = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = cur + Math.max(bestFromAbove, bestFromLeft);
                }
            }
        }

        // The total number of cells visited on any monotonic path is (2*n - 1)
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // ------------------------------------------------------------------
    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
