     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) return 0;
        if (n == 1) return 1;
        long a0 = 1;
        long a1 = 1;
        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }
}

