import java.util.List;

/**
 * Computes the maximum average of all paths that start at the top‑left cell
 * of a square matrix and finish at the bottom‑right cell, moving only right
 * or down.
 *
 * The average is defined as (sum of the cell values on the path) /
 * (number of cells visited). Since every such path has exactly 2·n‑1 cells,
 * the problem reduces to finding the path with the maximum sum.
 *
 * @param cost  a square matrix (List of Lists) of non‑negative integers
 * @param n     the dimension of the matrix (number of rows/columns)
 * @return      the maximum possible average as a {@code Double}, or
 *              {@code null} if the input is invalid
 */
public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // Guard against malformed input
    if (cost == null || cost.isEmpty() || cost.size() != n) {
        return null;
    }

    // DP array: dp[i][j] = maximum sum to reach cell (i, j)
    double[][] dp = new double[n][n];

    // Start cell
    dp[0][0] = cost.get(0).get(0);

    // First row – can only come from the left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // First column – can only come from above
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill the rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    // The best sum到达 (n‑1, n‑1)
    double maxSum = dp[n - 1][n - 1];

    // Every path from (0,0) to (n‑1,n‑1) has exactly (2*n‑1) cells
    int totalCells = 2 * n - 1;

    return maxSum / totalCells;
}

