            // s_i = 2 * s_{i-1} + s_{i-2}
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        return (int) current;
    }

    // Optional test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
