     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that captures words consisting only of letters (a‑z, A‑Z)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            if (hasInteriorZ(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /** Returns true if {@code word} contains the character 'z' at any index
     *  other than the first (index 0) or the last (index length‑1). */
    private static boolean hasInteriorZ(String word) {
        // Need at least three characters to have an interior position
        if (word.length() < 3) {
            return false;
        }
        // Scan the interior of the word (skip the first and last characters)
        for (int i = 1; i < word.length() - 1; i++) {
            if (word.charAt(i) == 'z') {
                return true;
            }
        }
        return false;
    }

