class Maxaverageofpath {
    /**
     * Returns the maximum average of a path from the top‑left to the bottom‑right
     * of the given n×n cost matrix. Movement is restricted to right and down.
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) return null;

        // dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int val = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // can only come from the left
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    // can only come from above
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    // take the best of the two possible predecessors
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // Every valid path contains exactly (2*n - 1) cells
        double average = maxSum / (double) (2 * n - 1);

        return average;
    }
}

