import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a monotonic path (right/down) from the
     * top‑left corner to the bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost  List of n rows, each row a List of n integers
     * @param n     size of the square matrix (number of rows/columns)
     * @return      the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP[i][j] = maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Remaining cells: take the better of the two predecessors and add current cost
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The length of any path from (0,0) to (n‑1,n‑1) is 2*n‑1 cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Null/empty safety – return 0 for empty or null strings.
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set (both lower‑ and upper‑case).  ‘y’ is treated as a consonant.
        final String VOWELS = "aeiouAEIOU";

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only want to count consonants.
            if (VOWELS.indexOf(ch) != -1) {
                continue;
            }

            // Check left neighbour.
            boolean hasVowelNeighbor = false;
            if (i > 0 && VOWELS.indexOf(testStr.charAt(i - 1)) != -1) {
                hasVowelNeighbor = true;
            }

            // Check right neighbour.
            if (i < len - 1 && VOWELS.indexOf(testStr.charAt(i + 1)) != -1) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
