class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle negative indices
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        // Base cases: the first two terms of the sequence are 1, 1
        if (n == 0) return 1;
        if (n == 1) return 1;
        // Use long to avoid overflow for moderate n
        long prev2 = 1; // a_{i-2}
        long prev1 = 1; // a_{i-1}
        long current = 0;
        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            // Shift the previous values
            prev2 = prev1;
            prev1 = current;
        }
        // The result fits into int for the expected range of n
        return (int) current;
    }
}

