import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that travels from the top‑left
     * corner to the bottom‑right corner of the given n×n matrix, moving only
     * right or down.
     *
     * @param cost  a list of rows, each row a list of integers
     * @param n     size of the square matrix
     * @return      the maximal average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] – maximal sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;               // number of visited cells
        return maxSum / pathLength;               // maximal average
    }

    /**
     * Simple driver that reads the matrix from stdin and prints the result.
     * Demonstrates the use of try‑with‑resources (BufferedReader).
     */
    public static void main(String[] args) {
        // try‑with‑resources guarantees the reader is closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line;

            // ---- read n -------------------------------------------------
            // skip possible empty lines
            while ((line = br.readLine()) != null && line.trim().isEmpty()) {
                // ignore
            }
            if (line == null) {
                System.out.println("No input.");
                return;
            }
            int n = Integer.parseInt(line.trim());

            // ---- read the n×n matrix ------------------------------------
            List<List<Integer>> cost = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                // skip empty lines between rows
                while ((line = br.readLine()) != null && line.trim().isEmpty()) {
                    // ignore
                }
                if (line == null) break; // defensive, should not happen

                String[] tokens = line.trim().split("\\s+");
                List<Integer> row = new ArrayList<>(tokens.length);
                for (String tok : tokens) {
                    row.add(Integer.parseInt(tok));
                }
                // If a row happened to be split across multiple lines you could
                // keep reading, but for the given problem a single line per row
                // is sufficient.
                cost.add(row);
            }

            // ---- compute and output --------------------------------------
            Double result = maxaverageofpath(cost, n);
            // print with one decimal place to match the examples
            System.out.printf("%.1f%n", result);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } catch (NumberFormatException e) {
            System.err.println("Invalid number format: " + e.getMessage());
        }
    }
}

