import java.util.Scanner;

/**
 * Utility class for computing Newman‑Shanks‑Williams numbers.
 *
 * The sequence is defined by:
 *   a(0) = 1
 *   a(1) = 1
 *   a(n) = 2·a(n‑1) + a(n‑2)   for n ≥ 2
 *
 * The values at indices 2,3,4,5,… are the “Newman‑Shanks‑Williams primes”.
 */
public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * @param n the zero‑based index (n ≥ 0)
     * @return the value a(n)
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute iteratively using long to avoid overflow before casting back to int
        long a0 = 1; // a(n‑2)
        long a1 = 1; // a(n‑1)
        long a2 = 0;

        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0;
            a0 = a1;
            a1 = a2;
        }

        // The problem expects an int; values fit in int for reasonable input ranges.
        return (int) a2;
    }

    /**
     * Simple driver to read an integer from stdin and print the corresponding
     * Newman‑Shanks‑Williams number.  Demonstrates try‑with‑resources.
     */
    public static void main(String[] args) {
        // Try‑with‑resources ensures the Scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            System.out.println(newmanPrime(n));
        } catch (Exception e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

