/**
 * Helper class that demonstrates how to detect a 'z' inside a word,
 * but not at the start or at the end of that word.
 */
class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     *
     * @param text the input string (may contain punctuation, spaces, etc.)
     * @return    the appropriate message
     */
    public static String textMatchWordzMiddle(String text) {
        // Word pattern: a sequence of one or more letters bounded by non‑letter chars.
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // Check for a 'z' that is not the first or last character.
            // For words of length <= 2 the loop body never runs, which is correct
            // because a 'z' would be at the start or the end.
            for (int i = 1; i < word.length() - 1; i++) {
                if (word.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }

        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // A tiny test driver (optional)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));        // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));      // "Not matched!"
    }
}

