import java.math.*;

class Maxaverageofpath {

    /**
     * Write a function to find a path with the maximum average over all existing
     * paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     *
     * @param cost 2‑D list representing the n×n matrix.
     * @param n    size of the square matrix.
     * @return the maximum average value of a path from the top‑left to the
     *         bottom‑right, moving only right or down.
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // every path from (0,0) to (n‑1,n‑1) contains exactly (2*n‑1) cells
        return maxSum / (2 * n - 1);
    }

    /**
     * Optional entry point that reads the matrix from standard input and prints
     * the result.  Demonstrates the use of try‑with‑resources (ITEM 9).
     */
    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee the BufferedReader is closed.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line;

            // Read the size n
            if ((line = br.readLine()) == null) return;
            int n = Integer.parseInt(line.trim());

            // Read the n×n matrix
            List<List<Integer>> cost = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                line = br.readLine();
                if (line == null) break;
                String[] tokens = line.trim().split("\\s+");
                List<Integer> row = new ArrayList<>();
                for (String token : tokens) {
                    row.add(Integer.parseInt(token));
                }
                cost.add(row);
            }

            // Compute and output the answer (one decimal place)
            Double answer = maxaverageofpath(cost, n);
            System.out.printf("%.1f%n", answer);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

