class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // The Newman-Shanks-Williams sequence is defined as:
        // a(0) = 1, a(1) = 1, a(n) = 2*a(n-1) + a(n-2) for n >= 2
        // The sample suggests returning the NSW number at index n (0-indexed),
        // which is prime for the given inputs.

        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }

        long a0 = 1; // a(0)
        long a1 = 1; // a(1)

        if (n == 0) return (int) a0;
        if (n == 1) return (int) a1;

        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        return (int) a;
    }

    // Main method for testing (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // Expected: 7
        System.out.println(newmanPrime(4)); // Expected: 17
        System.out.println(newmanPrime(5)); // Expected: 41
    }
}

