            if (!hasVowelNeighbor && i < len - 1) {
                char right = testStr.charAt(i + 1);
                if (vowels.indexOf(Character.toLowerCase(right)) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

