class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     *
     * The sequence is defined by:
     *   a(0) = 1
     *   a(1) = 1
     *   a(i) = 2 * a(i‑1) + a(i‑2)   for i ≥ 2
     *
     * Example values:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n the index (0‑based) of the desired term
     * @return the value of the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0) return 1;   // a(0)
        if (n == 1) return 1;   // a(1)

        long prev2 = 1; // a(i‑2)
        long prev1 = 1; // a(i‑1)
        long cur = 0;   // a(i)

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2;
            // shift the window
            prev2 = prev1;
            prev1 = cur;
        }

        // The problem expects an int; the recurrence grows quickly,
        // but for typical test values n ≤ 30 the result fits in int.
        return (int) cur;
    }
}

