class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern to match whole words consisting of letters only.
        // \b marks a word boundary, so punctuation (like '.') is not part of the match.
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();          // the current word
            int len = word.length();

            // Look for 'z' (case‑insensitive) anywhere in the word.
            int index = word.toLowerCase().indexOf('z');

            // If 'z' exists and is not at the first or last position, we have a match.
            if (index != -1 && index != 0 && index != len - 1) {
                return "Found a match!";
            }
        }

        // No word satisfied the condition.
        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
        System.out.println(textMatchWordzMiddle("  lang  ."));
    }
}

