class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * For n ≥ 2 the values produced are prime for the first few terms
     * (3, 7, 17, 41, …), matching the expected “prime” sequence.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // The first two terms of the NSW sequence are a1 = 1, a2 = 1
        if (n == 1) return 1;   // a1
        if (n == 2) return 3;   // a2 = 2*1 + 1 = 3

        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a  = 0; // a(i)

        // Compute a(i) for i = 3 … n
        for (int i = 3; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence: a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

