import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that travels from the top‑left
     * corner to the bottom‑right corner of the given n×n matrix.
     * Movement is allowed only down or right.
     *
     * @param cost the n×n matrix of integers
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}, or {@code null} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal arguments
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The total number of cells visited on any down/right path is (2*n - 1)
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // Simple test driver
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // Expected: 7.2
    }
}

