import java.util.List;
import java.util.Arrays;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that travels from the top‑left
     * to the bottom‑right of the given n×n matrix, moving only right or down.
     *
     * @param cost  the square matrix (List of rows, each row a List of Integers)
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximal average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ----- input validation ------------------------------------------------
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;                     // defensive; caller can decide what to do
        }
        for (int i = 0; i < n; ++i) {
            if (cost.get(i) == null || cost.get(i).size() != n) {
                return null;
            }
        }

        // ----- DP: keep only the current row to save memory --------------------
        long[] dp = new long[n];              // dp[j] = max sum to (current row, column j)

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int cur = cost.get(i).get(j);    // cost[i][j]

                if (i == 0 && j == 0) {
                    // start cell
                    dp[j] = cur;
                } else {
                    long fromTop  = (i > 0) ? dp[j]          : Long.MIN_VALUE;
                    long fromLeft = (j > 0) ? dp[j - 1]      : Long.MIN_VALUE;
                    dp[j] = cur + Math.max(fromTop, fromLeft);
                }
            }
        }

        long maxSum = dp[n - 1];                     // sum of the best path
        double average = (double) maxSum / (2L * n - 1);   // 2·n‑1 cells in any path
        return average;
    }

    // -----------------------------------------------------------------------
    // Simple test driver (not required for the solution, but handy for verification)
    public static void main(String[] args) {
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

