class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2 * a(n‑1) + a(n‑2)  for n >= 2.
     *
     * For n = 3, 4, 5 the results are 7, 17, 41 respectively,
     * matching the examples given in the problem statement.
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the base cases
        if (n == 0 || n == 1) {
            return 1;   // a(0) = a(1) = 1
        }

        // Compute the sequence iteratively
        int a0 = 1; // a(n‑2)
        int a1 = 1; // a(n‑1)
        int a = 0;  // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence relation
            a0 = a1;
            a1 = a;
        }

        return a;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

