            boolean hasVowelNeighbor = false;

            // Check left neighbor
            if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
                hasVowelNeighbor = true;
            }
            // Check right neighbor (only if left wasn’t a vowel)
            if (!hasVowelNeighbor && i < testStr.length() - 1
                    && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    // Simple test driver
