class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // \b[a‑zA‑Z]+\b matches a whole word consisting of letters only.
        // This automatically strips punctuation such as '.' or ','.
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // Look for 'z' (case‑insensitive)
            int idx = word.indexOf('z');
            if (idx == -1) {
                idx = word.indexOf('Z'); // also accept uppercase 'Z'
            }

            // If 'z' is present and is not the first or last character → success
            if (idx != -1 && idx != 0 && idx != word.length() - 1) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // Simple test harness
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

