public static int newmanPrime(int n) {
    // The sequence is defined for n >= 0
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }

    // a(0) = 1, a(1) = 1
    if (n == 0 || n == 1) {
        return 1;
    }

    // iterative computation using long to avoid overflow before the cast
    long a_i_minus_2 = 1; // a(0)
    long a_i_minus_1 = 1; // a(1)
    long a_i = 0;

    for (int i = 2; i <= n; i++) {
        a_i = 2 * a_i_minus_1 + a_i_minus_2;
        // shift the window for the next iteration
        a_i_minus_2 = a_i_minus_1;
        a_i_minus_1 = a_i;
    }

    // The problem expects an int return; the series stays within int for the
    // small values shown in the examples.  Cast safely.
    return (int) a_i;
}

