class Maxaverageofpath {
    /**
     * Find a path with the maximum average over all existing paths for the
     * given square matrix of size n * n.
     *
     * A path may only move right or down, starting at (0,0) and ending at
     * (n‑1, n‑1). The average of a path equals (sum of visited cells) /
     * (number of visited cells) = sum / (2*n‑1). Therefore maximizing the
     * average is equivalent to maximizing the sum.
     *
     * @param cost the n×n matrix of integers
     * @param n    size of the matrix
     * @return the maximum average as a {@code Double}, or {@code null} if
     *         the input is invalid.
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int val = cost.get(i).get(j);          // value of current cell
                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = val;
                } else {
                    double best = Double.NEGATIVE_INFINITY;
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]); // from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]); // from left
                    }
                    dp[i][j] = val + best;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);   // number of cells visited = 2n‑1
        return Double.valueOf(average);
    }

