class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1
     *   a(1) = 1
     *   a(n) = 2 * a(n-1) + a(n-2)  for n >= 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     *
     * @param n the index (0‑based) of the term to return
     * @return the n‑th Newman–Shanks–Williams number
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iterate using long to avoid overflow for moderate n
        long a0 = 1; // a(n-2)
        long a1 = 1; // a(n-1)
        long a2 = 0; // a(n)

        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0; // recurrence relation
            a0 = a1;
            a1 = a2;
        }

        // Cast to int; the problem expects an int result
        return (int) a2;
    }
}

