import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left corner
     * of the square matrix and ends at the bottom‑right corner.
     * Movement is restricted to only rightward or downward steps.
     *
     * @param cost the n×n matrix of non‑negative integers
     * @param n    the dimension of the square matrix (number of rows/columns)
     * @return the maximum possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation -------------------------------------------------
        if (cost == null || n <= 0) {
            return null;
        }
        int rows = cost.size();
        if (rows != n) {                     // defensive: adapt to actual size
            n = rows;
        }

        // ---- DP table (long to avoid overflow of large sums) -------------------
        long[][] dp = new long[n][n];

        // first cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // total number of cells visited on any top‑left → bottom‑right path
        int pathLength = 2 * n - 1;
        double maxAverage = (double) dp[n - 1][n - 1] / pathLength;

        return Double.valueOf(maxAverage);
    }

    // ---------------------------------------------------------------------------
    // Simple manual test (uncomment to run)
    // ---------------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

