class Maxaverageofpath {
    /**
     * Returns the maximum average of any path that goes from the top‑left corner
     * to the bottom‑right corner of the given n×n cost matrix.  Movement is
     * restricted to right or down steps.
     *
     * @param cost  a square list of lists representing the matrix
     * @param n     dimension of the matrix (cost.size() == n)
     * @return      the highest possible average (as a {@code Double})
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || cost.get(0).isEmpty()) {
            return null;
        }

        // The actual size of the matrix (redundant safety check)
        final int N = Math.max(n, cost.size());

        // dp[i][j] = maximum sum to reach (i, j) from (0,0)
        double[][] dp = new double[N][N];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < N; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < N; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < N; ++i) {
            for (int j = 1; j < N; ++j) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The best sum to reach the bottom‑right corner
        double maxSum = dp[N - 1][N - 1];

        // Number of cells visited on any top‑left → bottom‑right path = 2·N‑1
        double average = maxSum / (2 * N - 1);

        // Return as a boxed Double (auto‑boxing works as well)
        return Double.valueOf(average);
    }

