class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        // base cases
        if (n == 0) return 1;
        if (n == 1) return 1;
        long prev2 = 1; // s_{i-2}
        long prev1 = 1; // s_{i-1}
        for (int i = 2; i <= n; i++) {
            long current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        return (int) prev1;
    }
}

