public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' (ignoring case) at a position that is neither the first nor
     * the last character of the word.  Otherwise returns "Not matched!".
     *
     * Examples:
     *   "pythonzabc." → Found a match!   (z is at position 6 of 10)
     *   "xyzabc."     → Found a match!   (z is at position 2 of 6)
     *   "  lang  ."   → Not matched!
     */
    public static String textMatchWordzMiddle(String text) {
        // A word is a consecutive run of ASCII letters (A‑Z or a‑z).
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A 'z' can only be "in the middle" if the word is at least 3 characters long.
            if (word.length() >= 3) {
                // Look at the substring that excludes the first and last characters.
                String middle = word.substring(1, word.length() - 1).toLowerCase();
                if (middle.contains("z")) {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

    // Simple manual test harness (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

/**
 * Solution for the “maximum average path” problem.
 *
 * The path is allowed to move only right or down from the top‑left corner
 * (0,0) to the bottom‑right corner (n‑1,n‑1). All such paths contain exactly
 * (2·n‑1) cells, therefore the average of a path is its total sum divided by
 * (2·n‑1).
 *
 * The algorithm runs in O(n²) time and O(n²) space (a 1‑D DP would also work,
 * but the 2‑D version is clearer).
 */
class Maxaverageofpath {

    /**
     * Returns the maximum possible average value among all paths that start
     * at the top‑left corner of the given cost matrix and end at the bottom‑right
     * corner, moving only right or down.
     *
     * @param cost a square matrix (List of Lists) of integers
     * @param n    the dimension of the matrix (cost.size() == n)
     * @return     the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        // Initialize start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Number of cells visited on any valid path = (n‑1) downs + (n‑1) rights + 1 start = 2·n‑1
        int totalCells = 2 * n - 1;
        return dp[n - 1][n - 1] / totalCells;
    }

    // --------------------------------------------------------------------
    // A tiny driver to illustrate the expected results (not required)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

