class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a(0) = 1
     *   a(1) = 1
     *   a(n) = 2*a(n‑1) + a(n‑2)   for n >= 2
     *
     * The first few terms are: 1, 1, 3, 7, 17, 41, 99, …
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use long for intermediate values to avoid overflow.
        long prev2 = 1L; // a(i‑2)
        long prev1 = 1L; // a(i‑1)
        long cur   = 0L; // a(i)

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2;
            // shift the window
            prev2 = prev1;
            prev1 = cur;
        }

        // The problem expects an int; the values for reasonable n fit in int.
        return (int) cur;
    }
}

