class TextMatchWordzMiddle {

    // Pre‑compiled pattern that finds whole words (letters, digits, underscore).
    private static final Pattern WORD_PATTERN = Pattern.compile("\\b\\w+\\b");

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' **and** 'z' is neither the first nor the last character of
     * that word.  Otherwise returns "Not matched!".
     *
     * The implementation follows the advice from Chapter 3 of *Effective Java*:
     *   • The instanceof operator returns false for null, so we do not need an
     *     explicit null‑check.
     *   • The argument is already known to be a String (the method signature),
     *     but the instanceof guard makes the contract explicit and safe.
     */
    public static String textMatchWordzMiddle(String text) {

        // The instanceof test also covers the null case (it returns false for null).
        if (!(text instanceof String)) {
            return "Not matched!";
        }

        Matcher matcher = WORD_PATTERN.matcher(text);
        while (matcher.find()) {
            String word = matcher.group();

            // Does the word contain a 'z'?
            if (word.indexOf('z') != -1) {
                // 'z' must not be the first or the last character.
                if (word.charAt(0) != 'z' && word.charAt(word.length() - 1) != 'z') {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // A tiny driver to illustrate the expected output.
