        System.out.println(textMatchWordzMiddle("xyzabc."));     // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Finds the maximum average of any path that goes from the top‑left corner
     * to the bottom‑right corner of an n×n cost matrix.  Movement is allowed
     * only **right** or **down**.
     *
     * @param cost  list of n rows, each row having n integer values
     * @param n     size of the square matrix (number of rows/columns)
     * @return      the maximum average as a {@code Double}, or {@code null} if
     *              the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation -------------------------------------------------
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }
        for (int i = 0; i < n; i++) {
            if (cost.get(i) == null || cost.get(i).size() != n) {
                return null;
            }
        }

        // ---- DP table ----------------------------------------------------------
        double[][] dp = new double[n][n];

        try {
            dp[0][0] = cost.get(0).get(0);               // start cell
        } catch (Exception e) {                         // defensive fallback
            return null;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    continue; // already initialised
                }

                double cellValue;
                try {
                    cellValue = cost.get(i).get(j);
                } catch (Exception e) {
                    return null; // malformed input
                }

                double fromTop    = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                double fromLeft  = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;

                dp[i][j] = cellValue + Math.max(fromTop, fromLeft);
            }
        }

        // ---- compute average ---------------------------------------------------
        // A path from (0,0) to (n‑1,n‑1) contains (2*n‑1) cells.
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // --------------------------------------------------------------------- //
    // A tiny driver to test the three examples given in the problem statement
    // --------------------------------------------------------------------- //
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // expected: 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // expected: 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // expected: 7.2
    }
}

