class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle invalid input
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // Base cases
        if (n == 1) return 1;   // First term of the sequence
        if (n == 2) return 3;  // Second term of the sequence

        // Iterate to compute the nth term using the recurrence
        // a(n) = 2 * a(n-1) + a(n-2)
        long a1 = 1; // a(1)
        long a2 = 3; // a(2)
        long a = 0;

        for (int i = 3; i <= n; i++) {
            a = 2 * a2 + a1; // Compute a(i)
            a1 = a2;         // Shift a1 to a2 for next iteration
            a2 = a;          // Shift a2 to a for next iteration
        }

        // Cast to int as per the return type
        return (int) a;
    }
}

