class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        int len = text.length();
        int i = 0;

        while (i < len) {
            // Skip any non‑letter characters (punctuation, spaces, digits, etc.)
            while (i < len && !Character.isLetter(text.charAt(i))) {
                i++;
            }
            if (i >= len) break;   // no more words

            int start = i;
            // Advance to the end of the current word
            while (i < len && Character.isLetter(text.charAt(i))) {
                i++;
            }

            String word = text.substring(start, i);

            // A word must have at least three letters for a 'z' to be in the middle
            if (word.length() >= 3) {
                // Look for 'z' or 'Z' (case‑insensitive)
                int idx = word.indexOf('z');
                if (idx == -1) {
                    idx = word.indexOf('Z');
                }
                // If 'z' is present and it is not the first or last character → match
                if (idx != -1 && idx != 0 && idx != word.length() - 1) {
                    return "Found a match!";
                }
            }
        }

        return "Not matched!";
    }
}

import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum average of a path that goes from the top‑left
     * corner to the bottom‑right corner of the given n×n matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost  list of rows, each row is a list of integers
     * @param n     size of the square matrix
     * @return      the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive check
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                double val = cost.get(i).get(j);   // the value of the current cell

                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    // take the better of the two possible predecessors
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // The longest possible path (top‑left → bottom‑right) contains 2*n‑1 cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // ----- simple test driver -----
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

