class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(i) = 2 * a(i‑1) + a(i‑2)  for i ≥ 2
     *
     * Examples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     *
     * @param n the index (1‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // a0 = a(i‑2), a1 = a(i‑1)
        long a0 = 1; // a(0)
        long a1 = 1; // a(1)

        // For n == 1 or n == 2 the sequence yields 1
        if (n == 1) return (int) a0;
        if (n == 2) return (int) a1;

        long a = 0;
        // Compute terms from index 2 up to n
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }

        return (int) a; // the result fits in an int for the expected range
    }
}

