class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a monotone (right/down)
     * path from the top‑left corner to the bottom‑right corner of the
     * given n×n cost matrix.
     *
     * @param cost  list of rows, each row a list of integers
     * @param n     size of the square matrix
     * @return      maximum average as a Double, or null for invalid input
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive checks
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) +
                           Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // maximum sum at the destination
        double maxSum = dp[n - 1][n - 1];

        // average = sum / number of visited cells (2·n‑1)
        return maxSum / (2 * n - 1);
    }
}

