/**
 * Solution for the “Series Sum” problem.
 * The method computes 1² + 2² + … + n².
 */
class SeriesSum {

    /**
     * Returns the sum of the squares of the first {@code number} positive integers.
     *
     * @param number the number of terms (must be non‑negative)
     * @return the sum of squares, fits into an {@code int}
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative: " + number);
        }

        // Use long for the intermediate calculation to avoid overflow.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The problem expects an int return; the result is guaranteed to fit
        // for typical inputs (the formula fits in int for n ≤ 46340).
        return (int) sum;
    }

    // -----------------------------------------------------------------
    // A tiny test driver (optional – handy for quick verification)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        int[][] tests = {
            {6, 91},
            {7, 140},
            {12, 650},
            {0, 0},
            {1, 1}
        };

        for (int[] t : tests) {
            int n = t[0];
            int expected = t[1];
            int result = seriesSum(n);
            System.out.printf("seriesSum(%d) = %d  %s%n",
                    n, result, (result == expected ? "OK" : "FAIL"));
        }
    }
}

