class TextMatchWordzMiddle {
    /**
     * Returns "Found a match!" if the given text contains a word that has the
     * character 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     *
     * @param text the input string to examine
     * @return     appropriate match message
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split on whitespace – each token is considered a “word”
        String[] words = text.split("\\s+");

        for (String word : words) {
            int len = word.length();

            // A word of length <= 2 cannot have an internal 'z'
            if (len <= 2) {
                continue;
            }

            // Scan the word for any 'z' that is not at position 0 or len‑1
            boolean hasInternalZ = false;
            for (int i = 0; i < len; i++) {
                if (word.charAt(i) == 'z') {
                    if (i > 0 && i < len - 1) {
                        hasInternalZ = true;
                        break;          // no need to look further
                    }
                }
            }

            if (hasInternalZ) {
                return "Found a match!";
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));     // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a path that starts at the
     * top‑left cell and ends at the bottom‑right cell of the given n×n matrix.
     * Movement is allowed only to the right or downward.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] holds the maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);           // value of current cell
                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else {
                    long fromTop = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                    long fromLeft = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;
                    dp[i][j] = val + Math.max(fromTop, fromLeft);
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // Number of cells visited on any valid path = 2*n - 1
        double average = maxSum / (double) (2 * n - 1);
        return average;
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // Expected: 7.2
    }
}

