class CountVowels {

    /**
     * Counts consonants that have at least one vowel neighbour.
     *
     * @param testStr the input string
     * @return number of such consonants
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // skip vowels – we only count consonants
            if (isVowel(ch)) {
                continue;
            }

            boolean hasVowelNeighbour = false;

            // check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbour = true;
            }
            // check right neighbour
            if (!hasVowelNeighbour && i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbour = true;
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }

        return count;
    }

    /** Returns true if c is a vowel (a, e, i, o, u) – case‑insensitive. */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // ------------------------------------------------------------------------
    // Optional test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

