class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // base cases
        if (n == 1) {
            return 1;
        }
        // compute the n-th Newman‑Shanks‑Williams number
        BigInteger a0 = BigInteger.ONE; // a_{i-2}
        BigInteger a1 = BigInteger.ONE; // a_{i-1}
        for (int i = 2; i <= n; i++) {
            BigInteger a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            a0 = a1;
            a1 = a;
        }
        // the value fits in int for the expected range
        return a1.intValue();
    }

    // optional test
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

