    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null input – treat it as no match.
        if (text == null) {
            return "Not matched!";
        }

        // Pattern that matches a contiguous sequence of alphabetic characters (a‑zA‑Z).
        // This works for words separated by any non‑letter character (spaces, punctuation, etc.).
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();                // the actual word as it appears
            String lower = word.toLowerCase();            // case‑insensitive check

            // Find the first occurrence of 'z'
            int idx = lower.indexOf('z');

            // A match is valid only if:
            // 1. the word actually contains 'z'
            // 2. the 'z' is not the first character (idx != 0)
            // 3. the 'z' is not the last character (idx != word.length() - 1)
            if (idx != -1 && idx != 0 && idx != word.length() - 1) {
                return "Found a match!";
            }
        }

        // No word satisfied the condition.
        return "Not matched!";
    }

