import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of all paths that go from the
     * top‑left corner to the bottom‑right corner of the given square matrix.
     * Movement is restricted to right or down steps only.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (cost.size() == n)
     * @return the maximum average as a {@code Double}, or {@code null} if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ----- defensive programming -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }
        // ---------------------------------------------------------------------------

        // dp[i][j] holds the maximum sum reachable at cell (i, j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                           + cost.get(i).get(j);
            }
        }

        // the best sum and the constant path length (number of visited cells)
        double maxSum = dp[n - 1][n - 1];
        double pathLength = 2L * n - 1;   // 2*n‑1 fits in a long, cast to double

        return maxSum / pathLength;
    }

    // ---------------------------------------------------------------------------
    // A tiny test driver (not required by the problem, but handy for verification)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // Expected: 7.2
    }
}

