class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2·a(n‑1) + a(n‑2)  for n ≥ 2
     *
     * For n ≥ 2 the result is a prime (the first few values are 3, 7, 17, 41, …).
     *
     * @param n index of the required term (0‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use long to avoid overflow while computing the recurrence.
        long prev2 = 1; // a(i‑2)
        long prev1 = 1; // a(i‑1)
        long cur   = 0;

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2;
            // shift the window
            prev2 = prev1;
            prev1 = cur;
        }

        // The problem expects an int return type; the input n is small enough
        // that the result fits into an int.
        return (int) cur;
    }
}

