class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms (n)
     * @return the sum of squares from 1 to n
     *
     * Example:
     * <pre>
     * seriesSum(6) → 91   // 1+4+9+16+25+36
     * seriesSum(7) → 140  // 1+4+9+16+25+36+49
     * seriesSum(12) → 650 // 1+4+9+16+25+36+49+64+81+100+121+144
     * </pre>
     */
    public static int seriesSum(int number) {
        // Use the closed‑form formula: n(n+1)(2n+1)/6
        // Compute in long to avoid overflow of intermediate int values.
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;
        // The problem expects an int return type; the result fits in int for reasonable inputs.
        return (int) sum;
    }

    // Optional main method for quick manual testing
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

