import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a monotone path
     * (right‑or‑down only) from the top‑left corner to the bottom‑right
     * corner of the given n×n cost matrix.
     *
     * @param cost  list of rows, each row is a list of integers
     * @param n     size of the square matrix (number of rows/columns)
     * @return      the maximal average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- basic validation -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // ---- DP array (long to avoid overflow for large sums) ----------------
        long[][] dp = new long[n][n];

        // ---- first cell --------------------------------------------------------
        dp[0][0] = cost.get(0).get(0);

        // ---- first row (can only come from the left) --------------------------
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // ---- first column (can only come from above) --------------------------
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // ---- fill the rest -----------------------------------------------------
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute the average ------------------------------------------------
        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);

        return average;
    }

    // ---------------------------------------------------------------------------
    // Optional test driver (feel free to remove / comment out in production)
    // ---------------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

