class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 2) {
            throw new IllegalArgumentException("Input must be >= 2");
        }
        long a0 = 1; // a_{i-2}
        long a1 = 1; // a_{i-1}

        // Generate the Newman–Shanks–Williams sequence up to index n
        for (int i = 2; i <= n; i++) {
            long a_i = 2 * a1 + a0;
            a0 = a1;
            a1 = a_i;
        }

        long current = a1; // a_n
        long prev = a0;    // a_{n-1}

        // If a_n is not prime, find the next prime in the sequence
        while (!isPrime((int) current)) {
            long next = 2 * current + prev;
            prev = current;
            current = next;
        }

        return (int) current;
    }

    // Helper method to check if a number is prime
    private static boolean isPrime(int num) {
        if (num < 2) return false;
        if (num % 2 == 0) return num == 2;
        int sqrt = (int) Math.sqrt(num);
        for (int i = 3; i <= sqrt; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

