import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that
     * starts at the top‑left corner of the given n×n matrix and
     * ends at the bottom‑right corner, moving only right or down.
     *
     * @param cost square matrix of integers
     * @param n    size of the matrix (number of rows/columns)
     * @return maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ----- input validation -----
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }
        // quick check that the matrix is really n×n
        if (cost.size() != n) {
            return null;
        }

        // ----- dynamic programming table -----
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // maximum sum at the destination
        double maxSum = dp[n - 1][n - 1];

        // number of cells visited on any start‑to‑finish path = 2*n - 1
        double average = maxSum / (2 * n - 1);

        return Double.valueOf(average);
