class CountVowels {
    /**
     * Counts characters that are not vowels (consonants) and that have at least
     * one vowel as an immediate neighbour (left or right).
     *
     * @param testStr the input string (may contain upper‑/lower‑case letters)
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // ignore the vowel characters themselves
            if (isVowel(ch)) {
                continue;
            }

            // check left neighbour
            boolean hasVowelNeighbor = false;
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // check right neighbour if left wasn't a vowel
            if (!hasVowelNeighbor && i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    /** Returns true if {@code c} is a vowel (a, e, i, o, u) – case‑insensitive. */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

