class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n of the series (must be non‑negative)
     * @return the sum of squares from 1 to n
     */
    public static int seriesSum(int number) {
        // Guard against non‑positive input
        if (number <= 0) {
            return 0;
        }

        // Use the formula n(n+1)(2n+1)/6 to compute the sum in O(1) time.
        // Cast to long to avoid overflow while performing the intermediate multiplication.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The result fits in an int for typical values of n; cast back to int.
        return (int) sum;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

