/**
 * Class that provides a utility for the Newman‑Shanks‑Williams prime sequence.
 * Implements the required static method and overrides toString for easier debugging.
 */
class NewmanPrime {

    /** The index for which we compute the NSW number. */
    private final int n;

    /** Construct a NewmanPrime object for a given index. */
    public NewmanPrime(int n) {
        this.n = n;
    }

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined as:
     *   a(0) = 1, a(1) = 1,
     *   a(i) = 2*a(i‑1) + a(i‑2)  for i >= 2.
     *
     * @param n the position in the sequence (must be non‑negative)
     * @return the NSW number at position n
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use long to avoid overflow for moderate n; the result is cast back to int
        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a  = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        return (int) a1; // safe for the expected range of n
    }

    /**
     * Returns a string representation of this object, showing the index and the
     * corresponding Newman‑Shanks‑Williams number.
     *
     * @return a string like "NewmanPrime[3] = 7"
     */
    @Override
    public String toString() {
        return "NewmanPrime[" + n + "] = " + newmanPrime(n);
    }

    // --------------------------------------------------------------------
    // Example usage (optional – useful for quick testing)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println("newmanPrime(3) = " + newmanPrime(3)); // 7
        System.out.println("newmanPrime(4) = " + newmanPrime(4)); // 17
        System.out.println("newmanPrime(5) = " + newmanPrime(5)); // 41

        // Demonstrate the toString override
        System.out.println(new NewmanPrime(3)); // NewmanPrime[3] = 7
    }
}

