class RemoveOdd {
    /**
     * Removes characters at odd positions (1‑based) from the input string.
     * In other words, it keeps the characters at even positions (2nd, 4th, …).
     *
     * @param str1 the original string; may be null
     * @return a new string containing only the characters at even positions,
     *         or null if the input is null
     */
    public static String removeOdd(String str1) {
        // Guard against null input
        if (str1 == null) {
            return null;
        }

        StringBuilder sb = new StringBuilder();
        // i = 0 → 1st character (odd) → skip,
        // i = 1 → 2nd character (even) → keep, etc.
        for (int i = 0; i < str1.length(); i++) {
            if (i % 2 == 1) { // keep characters at even 1‑based positions
                sb.append(str1.charAt(i));
            }
        }
        return sb.toString();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));    // → "yhn"
        System.out.println(removeOdd("program"));   // → "rga"
        System.out.println(removeOdd("language"));  // → "agae"
    }
}

