class TextMatchWordzMiddle {

    /**
     * Checks whether any word in the given text contains the letter 'z'
     * that is neither the first nor the last character of that word.
     *
     * @param text the input text to be examined
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // \S+ matches any sequence of non‑whitespace characters (a word)
        Pattern wordPattern = Pattern.compile("\\S+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int length = word.length();
            int zIndex = word.indexOf('z');

            // 'z' must be present and not be the first or last character
            if (zIndex != -1 && zIndex != 0 && zIndex != length - 1) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    /**
     * Provides a concise, informative description of this utility class.
     *
     * @return a string representation of the class
     */
    @Override
    public String toString() {
        return "TextMatchWordzMiddle[utility class for detecting 'z' inside words]";
    }

    // -----------------------------------------------------------------
    // A simple test driver (optional)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"

