}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that starts at the top‑left
     * cell and ends at the bottom‑right cell of the given n×n matrix.
     * Movement is allowed only to the right or downward.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average of any valid path, as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] holds the maximum sum to reach cell (i, j) from (0,0)
        long[][] dp = new long[n][n];

        // Initialize the starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The total number of cells visited on any such path is 2*n - 1
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);

        return average;
    }

    /**
     * Simple demonstration of the method.
     */
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println("Max average: " + maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println("Max average: " + maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println("Max average: " + maxaverageofpath(mat3, 3)); // 7.2
    }

    /**
     * Overriding toString as suggested by the programming advice.
     *
     * @return a concise description of this class
     */
    @Override
    public String toString() {
        return "Maxaverageofpath{}";
    }
}

