/**
 * Utility class that provides a method to count consonants that have
 * a vowel as an immediate neighbour.
 *
 * Following the advice in Item 12, we also override {@link #toString}
 * to give a concise, informative representation of the class.
 */
class CountVowels {

    /**
     * Counts those characters (consonants) in {@code testStr} that have
     * at least one vowel (a, e, i, o, u) as an immediate neighbour
     * (either to the left or to the right).
     *
     * @param testStr the input string (may contain mixed‑case letters)
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with a lower‑case version so the vowel test is case‑insensitive
        String lower = testStr.toLowerCase();
        int count = 0;

        for (int i = 0; i < lower.length(); i++) {
            char ch = lower.charAt(i);

            // We only care about non‑vowel characters (consonants)
            if (!isVowel(ch)) {
                boolean hasVowelNeighbor = false;

                // Check the character to the left, if it exists
                if (i > 0 && isVowel(lower.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // Check the character to the right, if it exists
                if (i < lower.length() - 1 && isVowel(lower.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Helper method that determines whether a given character is a vowel.
     *
     * @param ch the character to test
     * @return {@code true} if {@code ch} is one of a, e, i, o, u; {@code false} otherwise
     */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }

    /**
     * Returns a concise, informative string representation of this class.
     * (Per Item 12 – always override toString.)
     *
     * @return a short description of the class
     */
    @Override
    public String toString() {
        return "CountVowels";
    }

    // -----------------------------------------------------------------
    // Optional main method for quick manual testing
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

