import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     *
     * The sequence is defined by:
     *   a(0) = 1
     *   a(1) = 1
     *   a(n) = 2 * a(n‑1) + a(n‑2)   for n > 1
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the first two base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use long to avoid overflow while iterating; cast to int at the end.
        long prev2 = 1; // a(i‑2)
        long prev1 = 1; // a(i‑1)
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            // Shift the window for the next iteration
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int return type; the values fit in int for n ≤ 24.
        return (int) current;
    }

