class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1
     *   a(1) = 1
     *   a(n) = 2·a(n‑1) + a(n‑2)   for n ≥ 2
     *
     * @param n the 1‑based index of the required term
     * @return the n‑th term of the sequence
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // a0 = a(0), a1 = a(1)
        long a0 = 1;
        long a1 = 1;

        // For n == 1 we return a(1) = 1
        if (n == 1) {
            return (int) a1;
        }

        // Compute the remaining terms iteratively
        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }

        // The result fits in an int for reasonable input; cast safely.
        return (int) a;
    }

    // -----------------------------------------------------------------
    // Optional quick test (remove or comment out in production)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // → 7
        System.out.println(newmanPrime(4)); // → 17
        System.out.println(newmanPrime(5)); // → 41
    }
}

