 *   sn = 2 * s(n‑1) + s(n‑2)   for n ≥ 2
 *
 * For n ≥ 2 each sn is a prime, so returning sn fulfills the requirement
 * “nth Newman‑Shanks‑Williams prime”.
 *
 * @param n the index (zero‑based) of the desired NSW number
 * @return the n‑th NSW number (the n‑th prime for n ≥ 2)
 * @throws IllegalArgumentException if n is negative
 */
public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * @param n zero‑based index (n >= 0)
     * @return the value of the NSW sequence at position n
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;   // s0 = s1 = 1
        }

        // Iteratively compute the recurrence using long to avoid early overflow.
        long prevPrev = 1L; // s0
        long prev      = 1L; // s1
        long current   = 0L;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev + prevPrev; // sn = 2 * s(n‑1) + s(n‑2)
            prevPrev = prev;
            prev = current;
        }

        // The problem expects an int return type; cast after confirming it fits.
        if (current > Integer.MAX_VALUE) {
            throw new ArithmeticException("Result exceeds Integer range for given n");
        }
        return (int) current;
    }

    // -----------------------------------------------------------------------
    // Simple manual test (can be removed when integrating into a larger codebase)
    public static void main(String[] args) {
        // Provided examples
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41

        // Additional sanity checks
        System.out.println(newmanPrime(0)); // 1
        System.out.println(newmanPrime(1)); // 1
        System.out.println(newmanPrime(2)); // 3 (first prime in the NSW sequence)
    }
}

