import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner, ends at the bottom‑right corner and moves only
     * right or down.
     *
     * @param cost  square matrix of integers (size n × n)
     * @param n     dimension of the matrix
     * @return      maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive checks
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = best sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                double cellValue = cost.get(i).get(j).doubleValue();

                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = cellValue;
                } else {
                    double bestPrev = 0.0;
                    if (i > 0) {
                        bestPrev = Math.max(bestPrev, dp[i - 1][j]);
                    }
                    if (j > 0) {
                        bestPrev = Math.max(bestPrev, dp[i][j - 1]);
                    }
                    dp[i][j] = cellValue + bestPrev;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1);   // denominator is constant

        return Double.valueOf(average);
    }
}

