import java.math.BigInteger;

class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   ai = 2 * a(i‑1) + a(i‑2)   for i ≥ 2
     *
     * For the given examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n the index (1‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Use BigInteger to avoid overflow for larger n; the result is cast back to int.
        BigInteger a0 = BigInteger.ONE; // a0 = a(0)
        BigInteger a1 = BigInteger.ONE; // a1 = a(1)

        if (n == 1) {
            return a0.intValue(); // 1
        }
        if (n == 2) {
            // a2 = 2*a1 + a0 = 3
            return a1.multiply(BigInteger.TWO).add(a0).intValue();
        }

        BigInteger a = BigInteger.ZERO; // will hold a(i)
        for (int i = 2; i <= n; i++) {
            a = a1.multiply(BigInteger.TWO).add(a0); // a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }
        return a.intValue();
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

