class CountVowels {

    /**
     * Counts consonants in the given string that have at least one vowel
     * as an immediate neighbour (to the left or to the right).
     *
     * @param testStr the input string
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int length = testStr.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            char ch = testStr.charAt(i);

            // Consider only consonants (i.e. characters that are not vowels)
            if (!isVowel(ch)) {
                boolean hasVowelNeighbor = (i > 0 && isVowel(testStr.charAt(i - 1)))
                        || (i < length - 1 && isVowel(testStr.charAt(i + 1)));

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Helper method to check if a character is a vowel (case‑insensitive). */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
