    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The first two values are 1.
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use BigInteger to be safe for larger n; the result is cast back to int
        // because the problem constraints expect values that fit in an int.
        BigInteger a0 = BigInteger.ONE; // a(i‑2)
        BigInteger a1 = BigInteger.ONE; // a(i‑1)
        BigInteger a  = BigInteger.ZERO;

        for (int i = 2; i <= n; i++) {
            a = a1.multiply(BigInteger.valueOf(2)).add(a0); // a = 2*a1 + a0
            a0 = a1;
            a1 = a;
        }

        return a.intValue();   // safe for the expected range of n
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

