import java.util.*;

class Maxaverageofpath {
    /**
     * Find a path with the maximum average over all existing paths for the given
     * square matrix of size n×n.  Movement is restricted to right or down.
     *
     * @param cost 2‑D list representing the n×n matrix of integers.
     * @param n    size of the matrix (number of rows/columns).
     * @return the maximum average value as a Double.
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum that can be obtained when reaching cell (i,j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cur = cost.get(i).get(j);           // value of the current cell
                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cur;
                } else {
                    double best = 0.0;
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]); // came from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]); // came from the left
                    }
                    dp[i][j] = cur + best;
                }
            }
        }

        // All paths from (0,0) to (n‑1,n‑1) have exactly (2*n‑1) cells,
        // therefore the maximum average = (max sum) / (2*n‑1).
        double maxSum = dp[n - 1][n - 1];
        double maxAverage = maxSum / (2 * n - 1);

        return maxAverage;
    }

    // --------------------------------------------------------------------
    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

