class SeriesSum {
    /**
     * Returns the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the last term of the series (n)
     * @return the total sum of squares from 1 to number
     */
    public static int seriesSum(int number) {
        // Use a long for the intermediate calculation to avoid overflow.
        long n = number;
        // Formula: n * (n + 1) * (2n + 1) / 6
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;   // The result fits in an int for reasonable inputs.
    }
}

