     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // For n <= 1 the sequence value is 1 (the base case)
        if (n <= 1) {
            return 1;
        }

        // Use long to avoid overflow while computing the sequence
        long a0 = 1; // a_{i-2}
        long a1 = 1; // a_{i-1}
