        // Compute a_n iteratively
        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0; // a_i = 2*a_{i-1} + a_{i-2}
            a0 = a1;
            a1 = a2;
        }

        // The result fits in int for the expected small values of n
        return (int) a2;
    }

    // Optional main method for quick testing
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

