            boolean leftIsVowel  = i > 0         && isVowel(testStr.charAt(i - 1));
            boolean rightIsVowel = i < len - 1 && isVowel(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

    /** Helper that returns true if the given character is a vowel (case‑insensitive). */
    private static boolean isVowel(char ch) {
        return "aeiouAEIOU".indexOf(ch) != -1;
    }

