        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0; // a(n) = 2*a(n-1) + a(n-2)
            a0 = a1;
            a1 = a2;
        }
        // Cast to int as the problem expects an int return type
        return (int) a2;
    }
}

