class CountVowels {
    /**
     * Counts characters that are **not** vowels but have at least one
     * vowel immediately to their left or right in the given string.
     *
     * @param testStr the input string (may contain mixed case)
     * @return the number of such characters
     *
     * Examples:
     *   countVowels("bestinstareels")          -> 7
     *   countVowels("partofthejourneyistheend")-> 12
     *   countVowels("amazonprime")             -> 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work in lowercase so the check is case‑insensitive
        String s = testStr.toLowerCase();

        // Set of the five English vowels
        Set<Character> vowels = new HashSet<>(Arrays.asList('a', 'e', 'i', 'o', 'u'));

        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);

            // Skip the vowel characters themselves
            if (vowels.contains(ch)) {
                continue;
            }

            // Check left neighbour (if it exists)
            boolean leftIsVowel  = i > 0 && vowels.contains(s.charAt(i - 1));
            // Check right neighbour (if it exists)
            boolean rightIsVowel = i + 1 < s.length() && vowels.contains(s.charAt(i + 1));

            // Count this character if at least one neighbour is a vowel
            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

    // --------------------------------------------------------------------
    // Optional main method to verify the examples (not required for the task)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend"));// 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

