public class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     *
     * The sequence of NSW primes begins: 2, 3, 7, 17, 41, 127, …
     *
     * @param n position in the NSW prime sequence (1‑based)
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // The first NSW prime is 2
        if (n == 1) {
            return 2;
        }

        // Generate the NSW numbers: a0 = 1, a1 = 1, a_i = 2*a_{i-1} + a_{i-2}
        int a = 1; // a_{i-2}
        int b = 1; // a_{i-1}
        int count = 1; // we already have the prime 2

        while (true) {
            int c = 2 * b + a; // next NSW number

            if (isPrime(c)) {
                count++;
                if (count == n) {
                    return c;
                }
            }

            // Move the window forward
            a = b;
            b = c;
        }
    }

    /** Simple deterministic primality test for int values. */
    private static boolean isPrime(int num) {
        if (num <= 1) return false;
        if (num <= 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        int limit = (int) Math.sqrt(num);
        for (int i = 5; i <= limit; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

