class CountVowels {

    /**
     * Counts consonants that have at least one vowel as an immediate neighbour.
     *
     * @param testStr the input string (may contain upper‑case letters)
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with lower‑case characters only
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = s.charAt(i);
            // If the character itself is a vowel we do not count it
            if (isVowel(ch)) {
                continue;
            }

            // Check left neighbour
            boolean leftVowel = (i > 0) && isVowel(s.charAt(i - 1));
            // Check right neighbour
            boolean rightVowel = (i < len - 1) && isVowel(s.charAt(i + 1));

            if (leftVowel || rightVowel) {
                count++;
            }
        }
        return count;
    }

    /** Helper: true if c is one of a, e, i, o, u */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // -----------------------------------------------------------------
    // Optional test driver (can be removed when submitting on a platform)
