import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     * According to the provided examples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     *
     * The implementation treats the first NSW prime (3) as the result for n == 2,
     * so the returned value is the (n‑1)-th prime in the NSW sequence.
     *
     * @param n the index (must be >= 1)
     * @return the corresponding NSW prime as an int
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Special case: the very first NSW prime (3) when n == 1
        if (n == 1) {
            return 3;
        }

        // List to store the NSW primes we discover
        List<BigInteger> nswPrimes = new ArrayList<>();

        // a0 = 1, a1 = 1  (the first two Newman‑Shanks‑Williams numbers)
        BigInteger aPrev2 = BigInteger.ONE; // a(i‑2)
        BigInteger aPrev1 = BigInteger.ONE; // a(i‑1)

        // Generate numbers starting from i = 2 (the third term of the sequence)
        for (int i = 2; nswPrimes.size() < n - 1; i++) {
            // a(i) = 2 * a(i‑1) + a(i‑2)
            BigInteger current = aPrev1.multiply(BigInteger.TWO).add(aPrev2);

            // Test primality using BigInteger's probabilistic test (certainty = 100)
            if (current.isProbablePrime(100)) {
                nswPrimes.add(current);
            }

            // Shift the window for the next iteration
            aPrev2 = aPrev1;
            aPrev1 = current;
        }

        // The required prime is at index n‑2 (0‑based) in the list
        BigInteger result = nswPrimes.get(n - 2);

        // The problem expects an int; we assume the result fits into int.
        return result.intValue();
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

