public class Maxaverageofpath {
    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left cell and ends at the bottom‑right cell of the given
     * n × n matrix.  Movement is allowed only to the right or down.
     *
     * @param cost the n × n matrix of integers
     * @param n    size of the matrix (number of rows/columns)
     * @return     the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        int size = n;                     // actual matrix dimension
        double[][] dp = new double[size][size];

        // First cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < size; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < size; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table: take the best of the two possible predecessors
        for (int i = 1; i < size; ++i) {
            for (int j = 1; j < size; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum to reach the bottom‑right cell
        double maxSum = dp[size - 1][size - 1];

        // Every valid path contains exactly (2 * n - 1) cells
        double average = maxSum / (2 * size - 1);

        return average;   // auto‑boxed to Double
    }

