import java.util.Objects;

/**
 *  Newman‑Shanks‑Williams numbers.
 *  The sequence is defined by:
 *      a(0) = 1,  a(1) = 1
 *      a(n) = 4·a(n‑1) – a(n‑2)   for n ≥ 2
 *
 *  The problem asks for the n‑th element of this sequence (0‑based index).
 */
public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * @param n index of the required element (0‑based)
     * @return the value a(n) of the NSW sequence
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The first two values are 1.
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use long to avoid overflow for moderate n (the recurrence grows quickly).
        long prev2 = 1L; // a(i‑2)
        long prev1 = 1L; // a(i‑1)
        long cur   = 0L; // a(i)

        for (int i = 2; i <= n; i++) {
            cur = 4L * prev1 - prev2;
            // shift the window for the next iteration
            prev2 = prev1;
            prev1 = cur;
        }

        // The problem expects an int return type; the test cases are within int range.
        return (int) cur;
    }

    // --------------------------------------------------------------------
    // A tiny driver to illustrate the required output (not required for the
    // final answer, but useful for quick local testing).
    public static void main(String[] args) {
        for (int i = 3; i <= 5; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

