import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left cell (0,0) and ends at the bottom‑right cell (n‑1,n‑1),
     * moving only right or down. The average is computed as
     * (maximum sum) / (2 * n - 1).
     *
     * @param cost  a square n×n matrix given as a list of rows
     * @param n     the size of the matrix (number of rows/columns)
     * @return      the maximum average as a {@code Double}, or {@code null}
     *              if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = max sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First column (can only come from the cell above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // First row (can only come from the cell on the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The path always contains (2 * n - 1) cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }
}

class CountVowels {
    /**
     * Returns the number of consonants in the input string that have at least one
     * adjacent vowel (either to the left or to the right). The check is case‑insensitive.
     *
     * @param testStr the input string
     * @return count of such consonants
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }
        // treat a, e, i, o, u as vowels (case‑insensitive)
        final String vowels = "aeiou";
        String s = testStr.toLowerCase();
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            // skip vowels – we only count consonants
            if (vowels.indexOf(ch) != -1) {
                continue;
            }
            boolean hasVowelNeighbor = false;
            if (i > 0 && vowels.indexOf(s.charAt(i - 1)) != -1) {
                hasVowelNeighbor = true;
            }
            if (i < s.length() - 1 && vowels.indexOf(s.charAt(i + 1)) != -1) {
                hasVowelNeighbor = true;
            }
            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }
}

