class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // The sequence is defined as:
        // a(0) = 1, a(1) = 1,
        // a(i) = 2*a(i-1) + a(i-2) for i >= 2
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        if (n == 0 || n == 1) {
            return 1;               // a(0) = a(1) = 1
        }

        int a0 = 1; // a(i-2)
        int a1 = 1; // a(i-1)
        int a2 = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0; // compute next term
            a0 = a1;          // shift window
            a1 = a2;
        }
        return a2;
    }

    // Optional test harness
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

