class Maxaverageofpath {
    /**
     * Returns the maximum average value of a monotone path
     * (moving only right or down) from the top‑left corner
     * to the bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost the n×n matrix of path costs
     * @param n    size of the matrix (cost.size() == n)
     * @return     the maximum average (sum of visited cells / number of cells)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive check
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum reachable at cell (i, j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0).doubleValue();

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j).doubleValue();
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0).doubleValue();
        }

        // rest of the matrix
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j).doubleValue()
                            + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // A monotone path from (0,0) to (n‑1,n‑1) visits exactly 2*n‑1 cells.
        double maxAverage = dp[n - 1][n - 1] / (2.0 * n - 1.0);
        return maxAverage;
    }

    // --------------------------------------------------------------------
    // Optional test driver
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

