class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2 * a(n‑1) + a(n‑2) for n >= 2.
     *
     * @param n the index of the term to return (0‑based)
     * @return the n‑th Newman–Shanks–Williams number
     */
    public static int newmanPrime(int n) {
        // Handle the first two base cases
        if (n <= 0) {
            return 1;               // a(0)
        }
        if (n == 1) {
            return 1;               // a(1)
        }

        // Iterate using long to avoid overflow, then cast back to int
        long aMinus2 = 1; // a(i‑2)
        long aMinus1 = 1; // a(i‑1)
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * aMinus1 + aMinus2;
            // Shift the window for the next iteration
            aMinus2 = aMinus1;
            aMinus1 = current;
        }

        // The problem expects an int return type; the values fit in int
        // for the typical test range (n ≤ 25).  If you need larger values,
        // simply change the return type to long.
        return (int) current;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

