import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all monotone paths
     * (moving only right or down) from the top‑left corner to the
     * bottom‑right corner of an n×n cost matrix.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum possible average (as a Double)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP[i][j] = maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);           // current cell value

                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    // take the better of the two possible predecessors
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + val;
                }
            }
        }

        // The number of cells visited on any monotone path is 2·n‑1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        return average;               // auto‑boxed to Double
    }
}

