class NewmanPrime {
    /**
     * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Compute the nth Newman-Shanks-Williams number (a(n))
        int a0 = 1;
        int a1 = 1;
        if (n == 0) return a0;
        if (n == 1) return a1;

        int an = 0;
        for (int i = 2; i <= n; i++) {
            an = 2 * a1 + a0;
            a0 = a1;
            a1 = an;
        }

        // Check if a(n) is prime
        if (isPrime(an)) {
            return an;
        } else {
            // If not prime, throw an exception (assuming input n ensures primality)
            throw new IllegalArgumentException("The nth Newman-Shanks-Williams number is not prime for n=" + n);
        }
    }

    // Helper method to check primality
    private static boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

