public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the upper‑left corner
     * of the square matrix and ends at the lower‑right corner, moving only
     * right or down.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximum possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: longest path sum to each cell
        long[][] dp = new long[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // the total number of cells visited on any such path is 2*n‑1
        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);

        return average;
    }

    // --------------------------------------------------------------------
    // Simple manual test (feel free to remove / comment out in production)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
