     * (i.e. newmanPrime(3) = 7, newmanPrime(4) = 17, …).
     *
     * @param n the index (must be > 0)
     * @return the n‑th NSW prime
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Special case for n == 1 (the first NSW prime is 3)
        if (n == 1) {
            return 3;
        }

        // a0 = a(0), a1 = a(1)
        long a0 = 1;
        long a1 = 1;

        int count = 0;               // how many NSW primes we have seen
        int target = n - 1;          // we need the (n‑1)-th prime (1‑based)

        while (true) {
            // Compute next NSW number: a(i) = 2*a(i‑1) + a(i‑2)
            long a = 2 * a1 + a0;

            // For reasonably small inputs the value fits in an int.
            // If it overflows, we switch to a BigInteger based version.
            if (a > Integer.MAX_VALUE) {
                return newmanPrimeBig(n).intValue();
            }

            if (isPrime((int) a)) {
                count++;
                if (count == target) {
                    return (int) a;
                }
            }

            // Move the window forward
            a0 = a1;
            a1 = a;
        }
    }

    /** Simple deterministic primality test for int values. */
    private static boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        int limit = (int) Math.sqrt(num);
        for (int i = 3; i <= limit; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }

    /** Fallback using BigInteger for very large n (not needed for the given examples). */
    private static BigInteger newmanPrimeBig(int n) {
        if (n <= 0) throw new IllegalArgumentException("n must be positive");
        if (n == 1) return BigInteger.valueOf(3);

        BigInteger a0 = BigInteger.ONE;
        BigInteger a1 = BigInteger.ONE;

        int count = 0;
        int target = n - 1;

        while (true) {
            BigInteger a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            if (a.isProbablePrime(20)) { // Miller‑Rabin with sufficient certainty
                count++;
                if (count == target) {
                    return a;
                }
            }
            a0 = a1;
            a1 = a;
        }
    }
}

