import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that starts at the top‑left
     * cell of the square matrix and ends at the bottom‑right cell.
     * Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    the dimension of the matrix (cost.size() == n)
     * @return the maximum average as a {@code Double}, or {@code null} if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // DP array holds the best sum to reach each cell.
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table: each cell's best sum is the value of the
        // cell plus the larger of the two predecessor sums (top or left).
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                long bestPrev = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = cost.get(i).get(j) + bestPrev;
            }
        }

        // The path always contains exactly (2*n - 1) cells:
        // (n‑1) moves right + (n‑1) moves down + the start cell.
        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);

        // Return as a Double object (not primitive)
        return Double.valueOf(average);
    }

    // --------------------------------------------------------------------
    // Simple test driver (not required for the solution, but useful for verification)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

