class CountVowels {

    /**
     * Counts consonants in the given string that have at least one vowel
     * as an immediate neighbour (either to the left or to the right).
     *
     * @param testStr the input string
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int length = testStr.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            char ch = testStr.charAt(i);

            // We only care about consonants (i.e. non‑vowel characters)
            if (!isVowel(ch)) {
                boolean hasVowelNeighbor = false;

                // Check the left neighbour
                if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // Check the right neighbour
                if (i < length - 1 && isVowel(testStr.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Helper that tells whether a character is a vowel (case‑insensitive). */
    private static boolean isVowel(char c) {
        char lower = Character.toLowerCase(c);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u';
    }

    // -----------------------------------------------------------------
    // Optional test driver
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

