public static int seriesSum(int number) {
    int sum = 0;
    int i = 1;

    // Use Integer.compare instead of the < or > operators
    while (Integer.compare(i, number) <= 0) {
        sum += i * i;   // add i² to the running total
        i++;            // move to the next integer
    }

    return sum;
}

