class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   s0 = 1, s1 = 1
     *   sn = 2 * s(n‑1) + s(n‑2)  for n >= 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        int prev2 = 1; // s_{i-2}
        int prev1 = 1; // s_{i-1}
        int current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            // shift the window
            prev2 = prev1;
            prev1 = current;
        }
        return current;
    }

    // Optional simple test
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

