 */
public class RemoveOdd {

    /**
     * Removes the characters at even indices (0, 2, 4, …) and returns
     * the string made up of the characters at odd indices (1, 3, 5, …).

     * @param str the input string (may be {@code null})
     * @return a new string consisting of the odd‑position characters,
     *         or {@code null} if the input is {@code null}
