        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // To have a middle position the word must be at least 3 characters long
            for (int i = 1; i < word.length() - 1; i++) {
                // case‑insensitive check for 'z'
                if (Character.toLowerCase(word.charAt(i)) == 'z') {
                    return "Found a match!";
                }
            }
            // If the word is longer and contains 'z' only at the start or end,
            // it does not satisfy the requirement, so we continue searching.
