class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle edge cases for n < 2
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        if (n == 0) {
            return 1;
        }
        if (n == 1) {
            return 1;
        }

        // Initialize the first two terms of the sequence
        int a0 = 1;
        int a1 = 1;
        int a2 = 0;

        // Compute the sequence up to index n
        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0;
            a0 = a1;
            a1 = a2;
        }

        // Return the nth term (a_n)
        return a1;
    }
}

