class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2 * a(n‑1) + a(n‑2)  for n >= 2.
     *
     * @param n index of the term (0‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        long a0 = 1; // a(0)
        long a1 = 1; // a(1)
        long a = 0;  // a(n) will be stored here

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }
        return (int) a; // fit into int (caller is expected to use reasonable n)
    }
}

