     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // The recurrence is defined for indices 0 and 1 as 1.
        // The first prime in the sequence appears at index 2 (a₂ = 3).
        if (n < 2) {
            throw new IllegalArgumentException("n must be at least 2");
        }

        // Use BigInteger to avoid overflow for larger indices.
        BigInteger a0 = BigInteger.ONE; // a(i-2)
        BigInteger a1 = BigInteger.ONE; // a(i-1)
        BigInteger a  = null;          // a(i)

        // Compute a(n) iteratively.
        for (int i = 2; i <= n; i++) {
            a = a0.multiply(BigInteger.valueOf(2)).add(a1);
            a0 = a1;
            a1 = a;
        }

        // Verify that the term is prime (the problem expects this).
        if (!a.isProbablePrime(100)) {
            throw new IllegalArgumentException("The term at index " + n + " is not prime.");
        }

        // The result is assumed to fit into an int for the tested range.
        return a.intValue();
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
