class SeriesSum {
    /**
     * Calculates the sum of the squares of the first n natural numbers:
     * 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms to sum (must be non‑negative)
     * @return the sum of squares, or 0 if number <= 0
     */
    public static int seriesSum(int number) {
        // Guard against non‑positive input
        if (number <= 0) {
            return 0;
        }

        // Use long for the intermediate computation to avoid overflow.
        // The closed‑form formula for the sum of squares is:
        // n * (n + 1) * (2n + 1) / 6
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The specification expects an int return type; cast the result.
        return (int) sum;
    }
}

