import java.math.BigInteger;

public class NewmanPrime {
    /**
     * Returns the n-th Newman–Shanks–Williams prime.
     * The sequence is defined by a_0 = 1, a_1 = 1 and a_i = 2*a_{i-1} + a_{i-2} for i >= 2.
     * For n >= 2 the value a_n is a prime.
     *
     * @param n index (0‑based) of the required term
     * @return the n‑th term of the NSW sequence
     * @throws IllegalArgumentException if n < 0
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Use BigInteger to avoid overflow for moderately large n
        BigInteger a0 = BigInteger.ONE; // a_0
        if (n == 0) return a0.intValue();
        BigInteger a1 = BigInteger.ONE; // a_1
        if (n == 1) return a1.intValue();

        BigInteger a = BigInteger.ZERO;
        for (int i = 2; i <= n; i++) {
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            a0 = a1;
            a1 = a;
        }
        return a.intValue();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

