import java.util.*;

public class Maxaverageofpath {
    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left cell and ends at the bottom‑right cell of the given
     * n×n matrix.  Movement is allowed only right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    dimension of the square matrix
     * @return the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation ------------------------------------------------
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Matrix dimensions must match n");
        }
        for (int i = 0; i < n; i++) {
            if (cost.get(i) == null || cost.get(i).size() != n) {
                throw new IllegalArgumentException("Matrix must be square");
            }
        }

        // ---- dynamic programming: maximum sum to each cell --------------------
        long[][] dp = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long cell = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = cell;                     // start cell
                } else {
                    long best = Long.MIN_VALUE;
                    if (i > 0) best = Math.max(best, dp[i - 1][j]); // from above
                    if (j > 0) best = Math.max(best, dp[i][j - 1]); // from left
                    dp[i][j] = cell + best;
                }
            }
        }

        // ---- compute average --------------------------------------------------
        long maxSum = dp[n - 1][n - 1];
        double denominator = 2.0 * n - 1;   // number of cells in any valid path
        return maxSum / denominator;        // auto‑boxed to Double
    }
}

