import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) return 0;
        if (n == 1) return 3; // First prime in the sequence

        List<Integer> primes = new ArrayList<>();
        int s0 = 1, s1 = 1;

        // Generate the Newman–Shanks–Williams sequence until we have n primes
        while (primes.size() < n) {
            int s = 2 * s1 + s0;
            s0 = s1;
            s1 = s;

            if (isPrime(s)) {
                primes.add(s);
            }
        }

        // Return the (n-1)th prime (0-indexed) to match the given examples
        return primes.get(n - 2);
    }

    // Helper method to check if a number is prime
    private static boolean isPrime(int x) {
        if (x < 2) return false;
        if (x == 2) return true;
        if (x % 2 == 0) return false;

        for (int i = 3; i * i <= x; i += 2) {
            if (x % i == 0) return false;
        }
        return true;
