public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if a word in the given text contains the character
     * 'z' (case‑insensitive) somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Defensive guard – treat null or empty input as no match.
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // \b\w+\b matches each maximal sequence of word characters (letters, digits, '_').
        Matcher matcher = Pattern.compile("\\b\\w+\\b").matcher(text);

        while (matcher.find()) {
            String word = matcher.group();           // the actual word text
            String lower = word.toLowerCase();      // case‑insensitive check

            // A 'z' can only be “in the middle” if the word is at least 3 characters long
            // and the substring excluding the first and last characters contains 'z'.
            if (word.length() >= 3
                    && lower.substring(1, word.length() - 1).contains("z")) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // Optional test driver (feel free to remove or comment out in production)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

import java.util.List;
import java.util.Arrays;

class Maxaverageofpath {
    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left cell and ends at the bottom‑right cell of an n×n matrix.
     * Movement is restricted to right or down steps only.
     *
     * @param cost the n×n matrix of path costs
     * @param n    size of the square matrix
     * @return     maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP[i][j] = maximum sum to reach cell (i,j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) +
                           Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);

        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

import java.lang.*;

class CountVowels {

    /**
     * Counts consonants that have at least one vowel as an adjacent character.
     *
     * @param testStr the input string
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int n = testStr.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char c = testStr.charAt(i);
            if (isVowel(c)) {
                continue; // we only count consonants
            }

            // check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                count++;
                continue;
            }

            // check right neighbour
            if (i < n - 1 && isVowel(testStr.charAt(i + 1))) {
                count++;
            }
        }
        return count;
    }

    /** Returns true if ch is a vowel (case‑insensitive). */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' ||
               lower == 'i' || lower == 'o' || lower == 'u';
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));          // 5
    }
}

