import java.math.*;

class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     *
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)  for n >= 2
     *
     * Examples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     *
     * @param n the index of the term to return (0‑based)
     * @return the n‑th Newman–Shanks–Williams number
     */
    public static int newmanPrime(int n) {
        // Base cases
        if (n <= 0) return 1;   // a0
        if (n == 1) return 1;   // a1

        // Iteratively compute the sequence
        long prev2 = 1; // a0
        long prev1 = 1; // a1
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            // Shift the window for the next iteration
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int; the input range is assumed to fit in int.
        return (int) current;
    }
}

