class RemoveOdd {
    /**
     * Removes characters at odd positions (1‑based) from the given string.
     * In other words, it keeps the characters at even positions (2, 4, 6, …)
     *
     * @param str1 the input string
     * @return a new string containing only the characters at even positions
     */
    public static String removeOdd(String str1) {
        // Guard against null input
        if (str1 == null) {
            return null;
        }

        StringBuilder result = new StringBuilder();

        // Iterate using the accessor methods; keep characters whose 1‑based position is even
        for (int i = 0; i < str1.length(); i++) {
            // i = 0 → position 1 (odd) → skip
            // i = 1 → position 2 (even) → keep
            // i = 2 → position 3 (odd) → skip
            // ...
            if ((i & 1) == 1) {               // same as i % 2 == 1
                result.append(str1.charAt(i));
            }
        }

        return result.toString();
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));    // → "yhn"
        System.out.println(removeOdd("program"));   // → "rga"
