import java.util.Arrays;
import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a monotonic (right/down) path
     * from the top‑left corner to the bottom‑right corner of the given
     * n×n cost matrix.
     *
     * @param cost  list of rows, each row is a list of integers representing
     *              the cell costs
     * @param n     size of the square matrix (number of rows/columns)
     * @return      the highest average among all valid paths, or null if the
     *              input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum reachable at cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cellCost = cost.get(i).get(j);   // accessor method, not a public field

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cellCost;
                } else {
                    double bestFromTop  = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double bestFromLeft = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = cellCost + Math.max(bestFromTop, bestFromLeft);
                }
            }
        }

        // Number of cells visited in any path = (n‑1) downs + (n‑1) rights + 1 start = 2n‑1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;   // returned as a Double object as required
    }

    // Simple test driver (not part of the required solution)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

