import java.util.*;
import java.math.*;

public final class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams (NSW) sequence.
     * The sequence is defined by:
     *   s0 = 1, s1 = 1
     *   sn = 2·sn‑1 + sn‑2  for n ≥ 2
     *
     * @param n the index of the term to retrieve (0‑based)
     * @return the n‑th NSW number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use long to avoid overflow for moderate values of n
        long prevPrev = 1; // s_{i‑2}
        long prev      = 1; // s_{i‑1}

        for (int i = 2; i <= n; i++) {
            long current = 2 * prev + prevPrev; // s_i
            prevPrev = prev;
            prev = current;
        }

        // The return type is int; the value is guaranteed to fit for the
        // expected range of n. If an overflow occurs the cast will simply
        // truncate the value.
        return (int) prev;
    }

    // Optional test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

