class TextMatchWordzMiddle {
    /**
     * Returns "Found a match!" if a word in the given text contains the letter 'z'
     * somewhere other than the first or last position; otherwise returns
     * "Not matched!".
     *
     * A word is defined as a maximal consecutive sequence of alphabetic characters
     * (a‑z or A‑Z).  The check is case‑insensitive.
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern that matches a whole word consisting only of letters.
        final Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        final Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            // To have a middle position we need at least 3 characters.
            for (int i = 1; i < word.length() - 1; i++) {
                char c = word.charAt(i);
                if (c == 'z' || c == 'Z') {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // Optional test driver (feel free to remove / comment out in production)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

import java.util.List;

/**
 * Provides a utility method to compute the maximum average of a path
 * that moves only right or down from the top‑left to the bottom‑right
 * corner of a square matrix.
 */
public final class Maxaverageofpath {

    // Prevent instantiation – all functionality is static.
    private Maxaverageofpath() {
    }

    /**
     * Computes the maximum possible average of a path from (0,0) to (n‑1,n‑1)
     * moving only right or down.
     *
     * @param cost the n×n matrix of integers representing the cost of each cell
     * @param n    the dimension of the square matrix (must be > 0)
     * @return     the maximum average as a {@code Double}, or {@code null} if
     *             the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input.
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i,j).
        long[][] dp = new long[n][n];

        // Initialize start cell.
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left.
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above.
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Remaining cells – take the best of the two possible predecessors.
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                         + cost.get(i).get(j);
            }
        }

        // Every path contains exactly (2 * n - 1) cells.
        double average = dp[n - 1][n - 1] / (double) (2 * n - 1);
        return Double.valueOf(average);
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

