/**
 * A utility class that provides a static method to compute
 * the sum of the series 1² + 2² + 3² + … + n².
 *
 * The class is immutable:
 * - It is declared final to prevent subclassing (Rule 2).
 * - It has no fields (Rules 3 & 4 are vacuously satisfied).
 * - It provides no mutators (Rule 1).
 */
public final class SeriesSum {

    // Prevent instantiation – this class is a pure utility.
    private SeriesSum() {
        throw new UnsupportedOperationException("Utility class - do not instantiate");
    }

    /**
     * Calculates the sum of squares of the first {@code number} positive integers.
     *
     * @param number the number of terms (must be non‑negative)
     * @return the value of 1² + 2² + … + {@code number}²
     */
    public static int seriesSum(int number) {
        // Handle non‑positive input gracefully
        if (number <= 0) {
            return 0;
        }

        // Use long arithmetic to avoid intermediate overflow, then cast back to int.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;   // n(n+1)(2n+1)/6
        return (int) sum;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

