class LenLog {
    /**
     * Returns the length of the longest word in the given list.
     *
     * @param list1 a list of strings (may be null or contain null elements)
     * @return the maximum length among the strings; 0 if the list is null or empty
     *
     * Example:
     *   lenLog(Arrays.asList("python", "PHP", "bigdata")) → 7
     *   lenLog(Arrays.asList("a", "ab", "abc"))          → 3
     *   lenLog(Arrays.asList("small", "big", "tall"))   → 5
     */
    public static int lenLog(List<String> list1) {
        // Guard against null or empty input
        if (list1 == null || list1.isEmpty()) {
            return 0;
        }

        // Using a simple for‑each loop – clear and efficient
        int maxLen = 0;
        for (String word : list1) {
            // Skip any null entries (or you could throw an exception)
            if (word != null && word.length() > maxLen) {
                maxLen = word.length();
            }
        }
        return maxLen;
    }

