class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1,
     *   an = 2 * a(n‑1) + a(n‑2)  for n >= 2.
     *
     * Examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n the index (1‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // a(1) = 1
        if (n == 1) {
            return 1;
        }

        // a(0) = 1, a(1) = 1
        int a0 = 1; // a(i‑2)
        int a1 = 1; // a(i‑1)
        int a = 0;  // a(i)

        // Compute a(2) … a(n)
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence
            a0 = a1;
            a1 = a;
        }
        return a;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        for (int i = 1; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

