class TextMatchWordzMiddle {

    /**
     * Write a function that matches a word containing 'z',
     * not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        StringBuilder word = new StringBuilder();
        int len = text.length();

        for (int i = 0; i < len; i++) {
            char ch = text.charAt(i);

            // Treat a letter as part of a word; anything else is a delimiter.
            if (Character.isLetter(ch)) {
                word.append(ch);
            } else {
                // End of a word – examine it.
                if (word.length() > 0) {
                    if (hasMiddleZ(word.toString())) {
                        return "Found a match!";
                    }
                    word.setLength(0); // reset for next word
                }
            }
        }

        // In case the string ends with a word (no trailing delimiter).
        if (word.length() > 0) {
            if (hasMiddleZ(word.toString())) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    /**
     * Returns true if the given word contains the letter 'z'
     * at any position other than the first or last character.
     */
    private static boolean hasMiddleZ(String word) {
        // A word of length <= 2 can never have a middle 'z'.
        if (word.length() <= 2) {
            return false;
        }
        // Check characters from index 1 up to length-2 (inclusive).
        for (int i = 1; i < word.length() - 1; i++) {
            if (word.charAt(i) == 'z') {
                return true;
            }
        }
        return false;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
        System.out.println(textMatchWordzMiddle("  lang  ."));
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left corner,
     * ends at the bottom‑right corner and may only move right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    size of the square matrix
     * @return the maximum possible average (as a {@code Double})
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table holds the best sum to reach each cell.
        double[][] dp = new double[n][n];

        // (0,0) is the starting point.
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left.
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above.
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table.
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The path length is always 2·n – 1.
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1);

        return average;               // auto‑boxed to Double
    }

    // -----------------------------------------------------------------
    // Simple manual test (optional)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9));
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10));
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11));
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

