class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2·a(n‑1) + a(n‑2)   for n ≥ 2
     *
     * The first few terms are:
     *   1, 1, 3, 7, 17, 41, 99, 239, 577, …
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman–Shanks–Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The first two values of the sequence are 1, 1.
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use `long` to avoid overflow for moderate n.
        long a0 = 1; // a(n‑2)
        long a1 = 1; // a(n‑1)
        long a2 = 0; // a(n)

        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0; // recurrence relation
            // Shift the window forward for the next iteration
            a0 = a1;
            a1 = a2;
        }

        // The result fits in an `int` for the small n shown in the examples.
        return (int) a2;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

