import java.math.*;

/**
 * Utility class that provides a method to compute the maximum average
 * of a path that moves only right or down from the top‑left corner to
 * the bottom‑right corner of a square matrix.
 */
class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at
     * (0,0) and ends at (n‑1,n‑1) moving only right or down.
     *
     * @param cost a square matrix (List of List of Integer) of size n×n
     * @param n    dimension of the matrix
     * @return the maximum average as a {@code Double}, or {@code null}
     *         if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // dp[i][j] – maximum sum to reach cell (i,j)
        long[][] dp = new long[n][n];

        // Initialise the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table: take the max of the top and left neighbours
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                          + cost.get(i).get(j);
            }
        }

        // All paths have the same length: 2*n - 1 cells
        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2L * n - 1);

        return average;
    }

    // -----------------------------------------------------------------
    // Optional test driver (can be removed when integrating into a larger project)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

