            boolean hasVowelNeighbor = false;

            // Check left neighbor
            if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
                hasVowelNeighbor = true;
            }
            // Check right neighbor
            if (!hasVowelNeighbor && i < len - 1 && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

