import java.math.BigInteger;

class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * The sequence is defined by:
     *   a(1) = 1
     *   a(2) = 3
     *   a(i) = 2·a(i‑1) + a(i‑2)  for i ≥ 3
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // Base cases
        if (n == 1) return 1;   // a(1) = 1
        if (n == 2) return 3;   // a(2) = 3

        // Use immutable BigInteger for arbitrary precision
        BigInteger aMinus2 = BigInteger.ONE;      // a(1)
        BigInteger aMinus1 = BigInteger.valueOf(3); // a(2)

        // Compute a(i) iteratively
        for (int i = 3; i <= n; i++) {
            BigInteger cur = aMinus1.multiply(BigInteger.TWO).add(aMinus2);
            aMinus2 = aMinus1;
            aMinus1 = cur;
        }

        // The problem expects an int; the result fits into int for the
        // typical test range (n ≤ 25).  For larger n the value would overflow.
        return aMinus1.intValue();
    }
}

