import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path from the top‑left corner to the
     * bottom‑right corner of the given cost matrix.  The path may only move
     * right or down, and all paths have exactly (2*n‑1) cells.
     *
     * @param cost  a square matrix (List of List of Integer) of size n×n
     * @param n     the dimension of the matrix
     * @return      the maximum average as a {@code Double}, or {@code null}
     *              if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation ------------------------------------------------
        if (cost == null || cost.size() != n) {
            return null;
        }
        for (int i = 0; i < n; ++i) {
            if (cost.get(i) == null || cost.get(i).size() != n) {
                return null;
            }
        }

        // ---- dynamic programming (1‑dimensional array) -----------------------
        // dp[j] holds the best sum to reach cell (i, j) in the current row.
        long[] dp = new long[n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                long cellValue = cost.get(i).get(j).longValue();

                if (i == 0 && j == 0) {
                    // start cell
                    dp[j] = cellValue;
                } else {
                    long bestFromAbove  = (i > 0) ? dp[j]         : Long.MIN_VALUE;
                    long bestFromLeft   = (j > 0) ? dp[j - 1]     : Long.MIN_VALUE;
                    dp[j] = cellValue + Math.max(bestFromAbove, bestFromLeft);
                }
            }
        }

        // ---- compute average --------------------------------------------------
        long maxSum = dp[n - 1];                 // sum of the best path
        int pathLength = 2 * n - 1;              // number of cells in any valid path
        return (double) maxSum / pathLength;     // convert to Double
    }
}

