import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2·a(n‑1) + a(n‑2)  for n ≥ 2
     *
     * For the values shown in the examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n the index (must be ≥ 1)
     * @return the n‑th NSW number
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Handle the trivial cases
        if (n == 1) {
            return 1;   // a1 = 1 (not a prime, but part of the recurrence)
        }

        // a0 = 1, a1 = 1
        long prev2 = 1L; // a(i‑2)
        long prev1 = 1L; // a(i‑1)
        long cur = 0L;

        // Compute a2 … an
        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2;
            // Shift the window for the next iteration
            prev2 = prev1;
            prev1 = cur;
        }

        // The result fits in an int for the expected inputs
        return (int) cur;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

