class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' (or 'Z') at a position that is neither the first nor the
     * last character of that word.  Otherwise it returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   → "Not matched!"
     *
     * @param text the input string to examine
     * @return     "Found a match!" or "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split on whitespace – punctuation stays attached to the word
        String[] words = text.split("\\s+");

        for (String word : words) {
            if (word.isEmpty()) {
                continue;               // skip any empty tokens
            }

            // Look for 'z' or 'Z' in the current word
            int index = word.indexOf('z');
            if (index == -1) {
                index = word.indexOf('Z');
            }

            // If we found a 'z' and it is not at the first or last position
            if (index != -1 && index > 0 && index < word.length() - 1) {
                return "Found a match!";
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

    // A tiny test driver (optional)
