/**
 * Utility class for computing the sum of squares 1² + 2² + … + n².
 * The class is immutable and uses a static cache to memoize results.
 */
public final class SeriesSum {

    // Cache for previously computed sums (lazy initialization)
    private static final Map<Integer, Integer> cache = new HashMap<>();

    // Prevent instantiation
    private SeriesSum() {
        throw new AssertionError("Cannot instantiate utility class SeriesSum");
    }

    /**
     * Calculates the sum of the series 1² + 2² + … + n².
     *
     * @param number the term up to which the series is summed (n ≥ 0)
     * @return the sum of squares from 1 to number
     */
    public static int seriesSum(int number) {
        if (number <= 0) {
            return 0;
        }

        // Return cached result if available
        Integer cached = cache.get(number);
        if (cached != null) {
            return cached;
        }

        // Use the closed‑form formula: n*(n+1)*(2n+1)/6
        long sumLong = (long) number * (number + 1) * (2L * number + 1) / 6;
        int result = (int) sumLong;

        // Cache the computed result before returning
        cache.put(number, result);
        return result;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

