class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (n == 1) {
            return 1; // a(1) = 1, not prime, but returned as per recurrence
        }
        long a0 = 1; // a(0)
        long a1 = 1; // a(1)
        long a = 1;  // a(2) initially
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // Compute a(i)
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }
}

