/**
 * Utility class that checks whether any word in the given text contains
 * the letter 'z' (or 'Z') somewhere other than at the first or last position.
 */
public final class TextMatchWordzMiddle {

    // Prevent instantiation – all behaviour is static.
    private TextMatchWordzMiddle() {
        throw new UnsupportedOperationException("This class is not intended to be instantiated");
    }

    /**
     * Returns "Found a match!" if a word contains the letter 'z' (or 'Z')
     * neither as its first nor as its last character; otherwise returns
     * "Not matched!".
     *
     * @param text the input text to examine
     * @return the appropriate match message
     */
    public static String textMatchWordzMiddle(String text) {
        // \b\w+\b matches a whole word consisting of word characters (letters, digits, underscore).
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A word must be at least three characters long to have a middle character.
            if (word.length() >= 3) {
                // Case‑insensitive search for 'z'.
                int idx = word.toLowerCase().indexOf('z');
                // 'z' is not at the start (idx > 0) and not at the end (idx < length‑1).
                if (idx > 0 && idx < word.length() - 1) {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));    // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));  // "Not matched!"
    }
}

import java.util.*;

public final class Maxaverageofpath {

    // Prevent instantiation – utility class
    private Maxaverageofpath() {
        throw new AssertionError("Cannot instantiate utility class");
    }

    /**
     * Returns the maximum average of any path that travels from the
     * top‑left corner to the bottom‑right corner of the given n×n matrix.
     * Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of non‑negative integers
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}, or {@code null} if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation ------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }
        if (cost.size() < n) {
            throw new IllegalArgumentException("Matrix dimension does not match n");
        }

        // ---- dynamic programming – keep maximum sum to each cell -------------
        // Use long to avoid overflow for large n and large cell values
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Remaining cells: take the better predecessor and add current cost
        for (int i = 1; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 1; j < n; j++) {
                dp[i][j] = row.get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average -------------------------------------------------
        // Every path from (0,0) to (n‑1,n‑1) visits exactly (2·n‑1) cells
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);

        return average;               // auto‑boxed to Double
    }

    // -----------------------------------------------------------------------
    // Optional test driver (not required for the solution)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

