/**
 * Utility class for counting consonants that have a vowel neighbor.
 * No instance of this class is needed; all functionality is provided
 * through a static method.
 */
public final class CountVowels {

    // Prevent instantiation – there is no need for objects of this class.
    private CountVowels() {
        throw new AssertionError("Cannot instantiate " + getClass().getName());
    }

    /**
     * Counts those characters (consonants) in the given string that have
     * at least one vowel (a, e, i, o, u) as an immediate neighbor
     * (either to the left or to the right).
     *
     * @param testStr the input string (may be {@code null})
     * @return the number of consonants that are adjacent to a vowel
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }

        // Work with lower‑case to treat upper‑case letters the same way.
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = s.charAt(i);

            // Skip vowels – we only count consonants.
            if (isVowel(ch)) {
                continue;
            }

            // Check the left neighbour.
            boolean hasVowelNeighbor = (i > 0 && isVowel(s.charAt(i - 1)));

            // Check the right neighbour if we haven't found one yet.
            if (!hasVowelNeighbor && i < len - 1) {
                hasVowelNeighbor = isVowel(s.charAt(i + 1));
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /** Helper that returns true if the supplied character is a vowel. */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }
}

public static List<Integer> countAlphaDigSpl(String string) {
    int alphabets = 0;
    int digits = 0;
    int special = 0;

    for (char c : string.toCharArray()) {
        if (Character.isLetter(c)) {
            alphabets++;
        } else if (Character.isDigit(c)) {
            digits++;
        } else {
            special++;
        }
    }

    List<Integer> result = new ArrayList<>();
    result.add(alphabets);
    result.add(digits);
    result.add(special);

    return result;
}

