class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound of the series (must be non‑negative)
     * @return the sum of squares from 1 to number (as an int)
     *
     * Example:
     * <pre>
     * seriesSum(6) → 91
     * seriesSum(7) → 140
     * seriesSum(12) → 650
     * </pre>
     */
    public static int seriesSum(int number) {
        // Guard against non‑positive input – the mathematical sum is 0.
        if (number <= 0) {
            return 0;
        }

        // Use long for the intermediate product to avoid overflow
        // before the final division by 6.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The problem statement expects an int return type.
        return (int) sum;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12)); // 650
    }
}

