class RemoveOdd {
    /**
     * Remove characters at odd positions (1‑based) from the input string.
     * In other words, keep the characters at even positions (1‑based),
     * which correspond to odd indices in a zero‑based index system.
     *
     * Examples:
     *   removeOdd("python")   -> "yhn"
     *   removeOdd("program")  -> "rga"
     *   removeOdd("language") -> "agae"
     *
     * @param str1 the original string
     * @return a new string containing only the characters at even positions
     */
    public static String removeOdd(String str1) {
        if (str1 == null) {
            return null;               // preserve null input behavior
        }

        StringBuilder sb = new StringBuilder();
        // i == 0 → position 1 (odd) → drop it
        // i == 1 → position 2 (even) → keep it
        // i == 2 → position 3 (odd)  → drop it
        // ...
        for (int i = 0; i < str1.length(); i++) {
            if (i % 2 == 1) { // keep odd indices (even positions in 1‑based)
                sb.append(str1.charAt(i));
            }
        }
        return sb.toString();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));   // yhn
        System.out.println(removeOdd("program"));  // rga
        System.out.println(removeOdd("language")); // agae
    }
}

