/**
 * Solution for the “maximum‑average‑of‑path” problem.
 *
 * The maximum average of a path from the top‑left corner to the bottom‑right
 * corner (moving only right or down) is obtained by maximizing the path sum,
 * because every valid path has exactly (2·n‑1) cells, so the average is
 * (sum / (2·n‑1)).
 *
 * We use a simple dynamic‑programming table.  To keep the code modular we
 * employ **composition**: the logic for computing the maximum sum is placed
 * in a separate helper class that holds the cost matrix instead of
 * inheriting from it.
 */
class Maxaverageofpath {

    /**
     * Helper class that computes the maximum‑average path using composition.
     * It does **not** extend any existing class; it merely “has a” cost matrix.
     */
    private static class PathFinder {
        private final List<List<Integer>> cost;
        private final int n;

        PathFinder(List<List<Integer>> cost, int n) {
            this.cost = cost;
            this.n = n;
        }

        /** Returns the maximum average of any right/down path. */
        double computeMaxAverage() {
            // DP table: dp[i][j] = max sum to reach (i, j)
            long[][] dp = new long[n][n];

            // Starting cell
            dp[0][0] = cost.get(0).get(0);

            // First row – can only come from the left
            for (int j = 1; j < n; j++) {
                dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
            }

            // First column – can only come from above
            for (int i = 1; i < n; i++) {
                dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
            }

            // Fill the rest of the table
            for (int i = 1; i < n; i++) {
                for (int j = 1; j < n; j++) {
                    dp[i][j] = cost.get(i).get(j) +
                               Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }

            // The total number of cells in any valid path is (2·n‑1)
            long maxSum = dp[n - 1][n - 1];
            return (double) maxSum / (2 * n - 1);
        }
    }

    /**
     * Returns the maximum average of a path from the top‑left to the bottom‑right
     * of the given n×n cost matrix.  Movement is restricted to right and down.
     *
     * @param cost  list of rows, each row a list of integers
     * @param n     dimension of the square matrix
     * @return      the maximum average as a {@code Double}, or {@code null} if
     *              the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Simple validation (the problem guarantees a valid square matrix)
        if (cost == null || cost.size() != n) {
            return null;
        }

        // Use composition: create a PathFinder that holds the cost matrix
        PathFinder finder = new PathFinder(cost, n);
        double result = finder.computeMaxAverage();

        // Return as a boxed Double (as required by the method signature)
        return Double.valueOf(result);
    }

    // --------------------------------------------------------------------
    // Optional test driver (feel free to remove / comment out in production)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

