import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // The Newman–Shanks–Williams sequence is defined by:
        // a(0) = 1, a(1) = 1,
        // a(i) = 2*a(i-1) + a(i-2) for i >= 2.
        // The values a(2), a(3), a(4), ... are 3, 7, 17, 41, ...
        if (n <= 0) return 1;   // a(0)
        if (n == 1) return 1;   // a(1)

        long a0 = 1; // a(i-2)
        long a1 = 1; // a(i-1)
        long a  = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return (int) a;   // the result fits in an int for the expected range
    }

    // A small test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

