import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum average of a path that starts at the top‑left
     * cell (0,0) and ends at the bottom‑right cell (n‑1,n‑1), moving only
     * right or down. The average is computed as:
     *
     *   maxSum / (2 * n - 1)
     *
     * because any such path visits exactly 2*n‑1 cells.
     *
     * @param cost  a square n×n matrix of integer costs
     * @param n     the dimension of the matrix
     * @return      the maximum possible average
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = maximum sum to reach cell (i,j) from (0,0)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);

        return average; // auto‑boxed to Double
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
            List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
            ), 3));
        // Expected output: 5.2
    }
}

