import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {

    // Composition: the public API delegates to a private NewmanSequence instance.
    private static final NewmanSequence sequence = new NewmanSequence();

    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * For the examples given the returned values happen to be prime.
     *
     * @param n index (1‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        // Forward the request to the component that knows how to compute the sequence.
        return (int) sequence.getTerm(n);
    }

    /**
     * Helper class that encapsulates the recurrence logic for the
     * Newman‑Shanks‑Williams sequence.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(i) = 2 * a(i‑1) + a(i‑2)   for i ≥ 2
     *
     * Using a separate class (composition) avoids the pitfalls of inheritance
     * and makes the code robust against future changes to the sequence definition.
     */
    private static class NewmanSequence {

        /**
         * Computes the n‑th term of the Newman‑Shanks‑Williams sequence.
         *
         * @param n the index (0‑based) of the term to compute
         * @return the value of the n‑th term
         */
        public long getTerm(int n) {
            // Handle the base cases.
            if (n <= 0) {
                return 1L;               // a(0) = 1
            }
            if (n == 1) {
                return 1L;               // a(1) = 1
            }

            // Iteratively compute the remaining terms.
            long a = 1L; // a(0)
            long b = 1L; // a(1)
            long c = 0L; // placeholder for a(i)

            for (int i = 2; i <= n; i++) {
                c = 2 * b + a; // a(i) = 2*a(i‑1) + a(i‑2)
                a = b;
                b = c;
            }
            return b; // b now holds a(n)
        }
    }
}

