import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Detects whether any word in the given text contains the letter 'z'
 * (or 'Z') somewhere other than the first or last position.
 *
 * Examples:
 *   "pythonzabc."  → Found a match!   (z is in the middle)
 *   "xyzabc."      → Found a match!   (z is in the middle)
 *   "  lang  ."    → Not matched!
 */
public class TextMatchWordzMiddle {

    /**
     * Component that knows how to test a single word.
     * It can be reused anywhere a “middle‑z” test is needed.
     */
    private static class WordChecker {
        /** Returns true if the word contains 'z' (or 'Z') and it is not the first or last character. */
        boolean containsZInMiddle(String word) {
            if (word == null || word.length() < 3) {
                return false;                     // too short to have a middle character
            }
            // Look for lower‑case 'z' first, then upper‑case 'Z'
            int idx = word.indexOf('z');
            if (idx == -1) {
                idx = word.indexOf('Z');
            }
            // idx == -1 → no 'z' at all
            // idx == 0  → 'z' is the first character
            // idx == word.length()‑1 → 'z' is the last character
            return idx > 0 && idx < word.length() - 1;
        }
    }

    /**
     * Scans the supplied text for words and checks each one.
     *
     * @param text the input string (may contain punctuation, spaces, etc.)
     * @return "Found a match!" if any word meets the criteria,
     *         otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Regex that captures contiguous alphabetic sequences (i.e. words)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        // Create a component that does the real work (composition)
        WordChecker checker = new WordChecker();

        while (matcher.find()) {
            String word = matcher.group();
            if (checker.containsZInMiddle(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // Simple demo (optional)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        String[] tests = {
            "pythonzabc.",
            "xyzabc.",
            "  lang  .",
            "zabc",
            "abz",
            "azz",
            "Zebra",
            "pythoNza."
        };
        for (String t : tests) {
            System.out.printf("%-20s → %s%n", t, textMatchWordzMiddle(t));
        }
    }
}

import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that travels from the
     * top‑left cell (0,0) to the bottom‑right cell (n‑1,n‑1) of the
     * given n×n cost matrix, moving only right or down.
     *
     * @param cost  list of rows, each row is a list of integers
     * @param n     dimension of the square matrix
     * @return      the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- defensive checks -------------------------------------------------
        if (cost == null || n <= 0) {
            return null;
        }

        // ---- DP: max sum to reach each cell ------------------------------------
        // dp[i][j] = maximum sum of a path that ends at (i, j)
        long[][] dp = new long[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average ----------------------------------------------------
        long maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;                 // number of cells visited
        double average = maxSum / (double) pathLength;

