public class SeriesSum {

    // ─────────────────────────────────────────────────────────────
    //  Composition: the class delegates the actual work to an
    //  instance of the helper component below.
    // ─────────────────────────────────────────────────────────────
    private static final SumOfSquares sumOfSquares = new SumOfSquares();

    /**
     * Returns the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms (n)
     * @return the sum of squares from 1 to n
     *
     * Example:
     * <pre>
     * seriesSum(6) → 91
     * seriesSum(7) → 140
     * seriesSum(12) → 650
     * </pre>
     */
    public static int seriesSum(int number) {
        // Delegate to the component (composition)
        return (int) sumOfSquares.compute(number);
    }

    // ─────────────────────────────────────────────────────────────
    //  Helper component that encapsulates the sum‑of‑squares logic.
    //  It could be reused elsewhere or unit‑tested independently.
    // ─────────────────────────────────────────────────────────────
    private static class SumOfSquares {
        /**
         * Computes the sum of squares 1² + 2² + … + n².
         *
         * @param n the number of terms
         * @return the sum (as a long to avoid overflow before casting)
         */
        public long compute(int n) {
            // Use the closed‑form formula: n(n+1)(2n+1)/6
            long nn = n;
            return nn * (nn + 1) * (2 * nn + 1) / 6;
        }
    }

    // Optional main method for quick manual testing
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

