public static int newmanPrime(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }
    // The first two values of the sequence are 1, 1
    if (n == 0 || n == 1) {
        return 1;
    }

    int s0 = 1; // s_{n-2}
    int s1 = 1; // s_{n-1}
    int s  = 0; // s_n

    for (int i = 2; i <= n; i++) {
        s = 2 * s1 + s0;   // s_n = 2*s_{n-1} + s_{n-2}
        s0 = s1;
        s1 = s;
    }
    return s;
}

