import java.util.regex.*;

class TextMatchWordzMiddle {
    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' (or 'Z') **somewhere other than** the first or last character
     * of that word.  Otherwise it returns "Not matched!".
     *
     * The method treats a “word” as a maximal sequence of ASCII letters
     * ([a‑zA‑Z]), so punctuation such as '.' or ',' is not part of the word.
     */
    public static String textMatchWordzMiddle(String text) {
        // Regex: a word boundary, then one or more ASCII letters, then a word boundary.
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();           // e.g. "pythonzabc"
            String lower = word.toLowerCase();       // case‑insensitive check
            int idx = lower.indexOf('z');            // position of 'z' (or -1 if none)

            // Match if 'z' is present and is neither the first nor the last character.
            if (idx != -1 && idx != 0 && idx != lower.length() - 1) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));    // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));  // "Not matched!"
    }
}

import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum possible average of a path that goes from the
     * top‑left to the bottom‑right of the given n×n cost matrix.
     * Movement is restricted to rightwards or downwards only.
     *
     * @param cost  a list of n rows, each row being a list of n integers
     * @param n     the dimension of the square matrix
     * @return      the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against invalid input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum to reach the bottom‑right corner
        long maxSum = dp[n - 1][n - 1];

        // Every path has exactly (2*n - 1) cells, so the average is:
        double average = maxSum / (double) (2 * n - 1);

        return average;
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

