class Maxaverageofpath {

    /**
     * Returns the maximum average of all paths that go from the top‑left
     * corner to the bottom‑right corner of the square matrix `cost`
     * moving only right or down.
     *
     * @param cost a square n×n matrix represented as a list of rows
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average (as a {@code Double}) of any valid path
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] holds the maximum sum to reach cell (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int val = cost.get(i).get(j);          // value of current cell
                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // First row – can only come from the left
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    // First column – can only come from above
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    // Take the best of the two possible predecessors
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // The best sum到达 (n‑1, n‑1)
        long maxSum = dp[n - 1][n - 1];

        // Any valid path contains exactly (2n‑1) cells
        double average = (double) maxSum / (2L * n - 1);

        return average;
    }

    // --------------------------------------------------------------------
    // Optional test driver (feel free to remove / comment out in production)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // Expected: 5.2

