import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     * The sequence of NSW primes begins: 2, 3, 7, 17, 41, 239, 577, …
     *
     * @param n 1‑based index of the required prime
     * @return the n‑th NSW prime
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // The first NSW prime is 2
        if (n == 1) {
            return 2;
        }

        // The recurrence: s(0)=1, s(1)=1, s(i)=2*s(i‑1)+s(i‑2)
        long a0 = 1; // s(0)
        long a1 = 1; // s(1)
        int primesFound = 0; // number of NSW primes discovered besides the leading 2

        while (true) {
            long a2 = 2L * a1 + a0; // next term

            if (isPrime(a2)) {
                primesFound++;
                if (primesFound == n - 1) { // we have collected n‑1 primes after the leading 2
                    return (int) a2;
                }
            }

            // Move the window forward
            a0 = a1;
            a1 = a2;

            // If we are about to overflow int, switch to BigInteger handling
            if (a2 > Integer.MAX_VALUE) {
                return newmanPrimeBig(n, primesFound, a0, a1);
            }
        }
    }

    /**
     * Continues the search using BigInteger when the values exceed the range of int/long.
     */
    private static int newmanPrimeBig(int n, int found, long a0, long a1) {
        BigInteger b0 = BigInteger.valueOf(a0);
        BigInteger b1 = BigInteger.valueOf(a1);
        int needed = n - 1 - found; // still need this many primes

        for (int i = 0; i < needed; ) {
            BigInteger b2 = b1.multiply(BigInteger.valueOf(2)).add(b0);
            if (isPrimeBig(b2)) {
                i++;
                if (i == needed) {
                    // The result is assumed to fit into an int (problem constraints)
                    return b2.intValue();
                }
            }
            b0 = b1;
            b1 = b2;
        }
        // Should not reach here under normal circumstances
        throw new IllegalArgumentException("Result exceeds int range for given n");
    }

    /** Simple trial‑division primality test for long values (works for int as well). */
    private static boolean isPrime(long num) {
        if (num < 2) return false;
        if (num % 2 == 0) return num == 2;
        long limit = (long) Math.sqrt(num);
        for (long d = 3; d <= limit; d += 2) {
            if (num % d == 0) return false;
        }
        return true;
    }

    /** Primality test for BigInteger. */
    private static boolean isPrimeBig(BigInteger num) {
        if (num.compareTo(BigInteger.TWO) < 0) return false;
        if (num.equals(BigInteger.TWO)) return true;
        if (num.mod(BigInteger.TWO).equals(BigInteger.ZERO)) return false;

        // If the number fits in a long, reuse the cheap trial‑division test
        if (num.compareTo(BigInteger.valueOf(Long.MAX_VALUE)) <= 0) {
            return isPrime(num.longValue());
        }

        // For larger numbers, rely on Miller‑Rabin with high certainty
        return num.isProbablePrime(20);
    }
}

