import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class TextMatchWordzMiddle {

    /**
     * Checks whether the given text contains a word that includes the character 'z'
     * somewhere other than at the first or last position of that word.
     *
     * @param text the input string to examine
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null input
        if (text == null) {
            return "Not matched!";
        }

        // Regex explanation:
        // \b           – word boundary
        // [A-Za-z]+    – one or more letters (the part before the 'z')
        // z            – the literal 'z' character
        // [A-Za-z]+    – one or more letters (the part after the 'z')
        // \b           – word boundary
        // This enforces that 'z' is not the first nor the last character of the word.
        Pattern pattern = Pattern.compile("\\b[A-Za-z]+z[A-Za-z]+\\b");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        } else {
            return "Not matched!";
        }
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));        // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));      // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that goes from the top‑left
     * corner to the bottom‑right corner of the given n×n matrix.
     * Movement is restricted to right or down steps only.
     *
     * @param cost the n×n matrix of non‑negative integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation ------------------------------------------------
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;                     // invalid matrix size
        }
        for (List<Integer> row : cost) {
            if (row == null || row.size() != n) {
                return null;                 // ragged or wrong‑size row
            }
        }

        // ---- DP: maximum sum to each cell ------------------------------------
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // rest of the matrix
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average -------------------------------------------------
        // Any valid path has exactly (2*n - 1) cells:
        //   (n‑1) moves right + (n‑1) moves down + the starting cell.
        double maxSum = dp[n - 1][n - 1];
        double denominator = 2.0 * n - 1.0;
        return maxSum / denominator;
    }

    // -----------------------------------------------------------------------
    // A tiny test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
            List.of(1, 2, 3),
            List.of(6, 5, 4),
            List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // expected 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
            List.of(2, 3, 4),
            List.of(7, 6, 5),
            List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // expected 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
            List.of(3, 4, 5),
            List.of(8, 7, 6),
            List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // expected 7.2
    }
}

