import java.math.*;

class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * <p>The sequence is defined by:</p>
     * <ul>
     *   <li>a(1) = 1</li>
     *   <li>a(2) = 3</li>
     *   <li>a(n) = 2·a(n‑1) + a(n‑2)  for n &gt; 2</li>
     * </ul>
     *
     * <p>Examples:</p>
     * <ul>
     *   <li>{@code newmanPrime(3) → 7}</li>
     *   <li>{@code newmanPrime(4) → 17}</li>
     *   <li>{@code newmanPrime(5) → 41}</li>
     * </ul>
     *
     * @param n the 1‑based index of the desired Newman–Shanks–Williams number
     * @return the value of the n‑th Newman–Shanks–Williams number
     * @throws IllegalArgumentException if {@code n} is less than or equal to 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Base cases
        if (n == 1) return 1;   // a(1)
        if (n == 2) return 3;   // a(2)

        // Iterate using long to avoid early overflow; final result is cast back to int.
        long prevPrev = 1; // a(n‑2)
        long prev     = 3; // a(n‑1)
        long current  = 0;

        for (int i = 3; i <= n; i++) {
            current = 2 * prev + prevPrev;
            prevPrev = prev;
            prev = current;
        }

        // The sequence grows quickly; for sufficiently large n the result may exceed
        // Integer.MAX_VALUE. The cast truncates the value – callers expecting large
        // results should use a larger return type.
        return (int) current;
    }
}

