import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts
     * at the top‑left corner and ends at the bottom‑right corner of the
     * given n×n cost matrix.  Movement is allowed only to the right or
     * down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = maximum sum of a path that ends at cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int cur = cost.get(i).get(j);          // current cell value
                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = cur;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[i][j] = dp[i][j - 1] + cur;
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[i][j] = dp[i - 1][j] + cur;
                } else {
                    // take the better of the two possible predecessors
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cur;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // Every valid path has exactly (2*n - 1) cells
        double average = maxSum / (2 * n - 1);

        return average;               // auto‑boxed to Double
    }
}

