import java.math.BigInteger;

public class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2*a(n‑1) + a(n‑2)  for n ≥ 2.
     *
     * @param n the index (0‑based) of the term to compute
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // a0 = a(0), a1 = a(1)
        BigInteger a0 = BigInteger.ONE;
        BigInteger a1 = BigInteger.ONE;
        BigInteger a = null; // will hold a(i)

        for (int i = 2; i <= n; i++) {
            // a(i) = 2 * a(i‑1) + a(i‑2)
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            // shift the window for the next iteration
            a0 = a1;
            a1 = a;
        }

        // The problem expects an int return type; intValueExact() will throw
        // an ArithmeticException if the value does not fit in an int.
        return a.intValueExact();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

