class CountVowels {
    /**
     * Counts the number of characters (non‑vowels) that have a vowel
     * as an immediate neighbor (either to the left or to the right)
     * in the given string.
     *
     * Examples:
     * <pre>
     * countVowels("bestinstareels")        -> 7
     * countVowels("partofthejourneyistheend") -> 12
     * countVowels("amazonprime")          -> 5
     * </pre>
     *
     * @param testStr the input string
     * @return the count of characters with a vowel neighbor
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }
        String s = testStr.toLowerCase();
        int length = s.length();
        int count = 0;
        for (int i = 0; i < length; i++) {
            char c = s.charAt(i);
            if (isVowel(c)) {
                // skip vowels themselves
                continue;
            }
            boolean hasVowelNeighbor = false;
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                hasVowelNeighbor = true;
            } else if (i < length - 1 && isVowel(s.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }
            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    /**
     * Determines whether a given character is a vowel (a, e, i, o, u).
     *
     * @param ch the character to test
     * @return true if ch is a vowel, false otherwise
     */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }

    // Optional main method for quick testing
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));           // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
