        }

        // Use long for the intermediate calculation to avoid overflow.
        // The result fits in an int for reasonable input ranges.
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;

        // Cast back to int as required by the method's signature.
        return (int) sum;
    }

