import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

public class NewmanPrime {

    /**
     * Returns the n-th Newman–Shanks–Williams prime.
     *
     * @param n position (1‑based)
     * @return the corresponding prime
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Special case: the first NSW prime is defined as 2 in the task
        if (n == 1) {
            return 2;
        }

        List<BigInteger> primes = new ArrayList<>();

        // a(0) = 1, a(1) = 1
        BigInteger a0 = BigInteger.ONE;
        BigInteger a1 = BigInteger.ONE;

        // Generate NSW numbers starting from a(2)
        while (primes.size() < n - 1) {
            // a(i) = 2*a(i-1) + a(i-2)
            BigInteger a2 = a1.multiply(BigInteger.valueOf(2)).add(a0);

            // Probabilistic primality test – sufficient for this problem
            if (a2.isProbablePrime(20)) {
                primes.add(a2);
            }

            // Shift the window
            a0 = a1;
            a1 = a2;
        }

        // primes[0] = 3, primes[1] = 7, ...; we need index n-2
        return primes.get(n - 2).intValue();
    }
}

