import java.util.List;

public class Maxaverageofpath {
    /**
     * Returns the maximum average of a monotonic path from the top‑left corner
     * to the bottom‑right corner of the given n×n cost matrix.
     * The path may only move right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}, or {@code null} if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }
        // ensure the matrix size matches n (if not, use the actual size)
        int N = Math.min(n, cost.size());
        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[N][N];

        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                int val = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = val;
                } else {
                    double best = Double.NEGATIVE_INFINITY;
                    if (i > 0) best = Math.max(best, dp[i - 1][j]);
                    if (j > 0) best = Math.max(best, dp[i][j - 1]);
                    dp[i][j] = best + val;
                }
            }
        }

        double maxSum = dp[N - 1][N - 1];
        double average = maxSum / (2 * N - 1);
        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9));
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10));
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11));
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

