/**
 * Utility class for counting characters that have vowels as neighbours.
 * The class is declared final to prohibit inheritance, as recommended
 * by Item 19 of “Effective Java”.
 */
public final class CountVowels {

    // Prevent instantiation – all members are static.
    private CountVowels() { }

    /**
     * Counts consonants in the given string that have a vowel as an immediate
     * neighbour (either to the left or to the right).
     *
     * <p>Examples:
     * <ul>
     *   <li>{@code countVowels("bestinstareels")} → 7</li>
     *   <li>{@code countVowels("partofthejourneyistheend")} → 12</li>
     *   <li>{@code countVowels("amazonprime")} → 5</li>
     * </ul>
     *
     * @param testStr the input string (may be {@code null})
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        // Guard against null or strings that cannot have neighbours.
        if (testStr == null || testStr.length() <= 1) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only want to count consonants.
            if (isVowel(ch)) {
                continue;
            }

            // Check left neighbour.
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                count++;
                continue; // no need to check right side once counted
            }

            // Check right neighbour.
            if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                count++;
            }
        }
        return count;
    }

    /**
     * Determines whether a given character is a vowel (a, e, i, o, u) regardless
     * of case.
     *
     * @param ch the character to test
     * @return {@code true} if {@code ch} is a vowel, {@code false} otherwise
     */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i'
                || lower == 'o' || lower == 'u';
    }
}

