 * 1² + 2² + … + n².
 *
 * <p>This class is not designed for inheritance; it is declared {@code final}
 * and has a private constructor to prevent instantiation.
 *
 * @author ...
 */
public final class SeriesSum {

    // Prevent instantiation
    private SeriesSum() {
        throw new UnsupportedOperationException("This class is not intended to be instantiated");
    }

    /**
     * Computes the sum of the series 1² + 2² + … + n².
     *
     * @param number the number of terms in the series (must be non‑negative)
     * @return the sum of squares of the first {@code number} positive integers
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative");
        }
        long n = number;
        // Use the formula n(n+1)(2n+1)/6 to avoid O(n) loops.
        long result = n * (n + 1) * (2 * n + 1) / 6;
        return (int) result;
    }
}

