import java.math.BigInteger;

public class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     *
     * @param n 1‑based index (n >= 1)
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // a0 = 1, a1 = 1
        BigInteger aPrev2 = BigInteger.ONE; // a_{i-2}
        BigInteger aPrev1 = BigInteger.ONE; // a_{i-1}

        int count = 0; // how many NSW primes we have found

        while (true) {
            // compute next NSW number: a_i = 2*a_{i-1} + a_{i-2}
            BigInteger cur = aPrev1.multiply(BigInteger.TWO).add(aPrev2);

            // check primality (certainty = 10 is more than enough for this use case)
            if (cur.isProbablePrime(10)) {
                count++;
                if (count == n) {
                    // the result is guaranteed to fit in an int for reasonable n
                    return cur.intValueExact();
                }
            }

            // advance the recurrence
            aPrev2 = aPrev1;
            aPrev1 = cur;
        }
    }

    // Simple sanity‑check (not required for the solution)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

