import java.util.*;

public class Maxaverageofpath {
    /**
     * Returns the maximum average of a path that starts at the top‑left corner
     * and ends at the bottom‑right corner of the given n×n matrix.
     * Moves allowed: right, down, diagonal (down‑right).
     * The result is truncated to one decimal place (floor to the nearest tenth).
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || cost.isEmpty()) {
            return null;
        }
        int size = cost.size();               // actual size (should be equal to n)
        int maxLen = 2 * size - 1;            // longest possible path (only R/D)
        // sentinel for “unreachable”
        final long NEG = Long.MIN_VALUE / 4;

        // dp[len][i][j] = best sum to reach (i,j) using exactly len cells
        long[][][] dp = new long[maxLen + 1][size][size];
        for (int len = 1; len <= maxLen; ++len) {
            for (int i = 0; i < size; ++i) {
                Arrays.fill(dp[len][i], NEG);
            }
        }

        // base case: path of length 1 (the start cell)
        dp[1][0][0] = cost.get(0).get(0);

        // fill the table for longer paths
        for (int len = 2; len <= maxLen; ++len) {
            for (int i = 0; i < size; ++i) {
                for (int j = 0; j < size; ++j) {
                    long bestPrev = NEG;
                    if (i > 0) {
                        bestPrev = Math.max(bestPrev, dp[len - 1][i - 1][j]);   // from above
                    }
                    if (j > 0) {
                        bestPrev = Math.max(bestPrev, dp[len - 1][i][j - 1]);   // from left
                    }
                    if (i > 0 && j > 0) {
                        bestPrev = Math.max(bestPrev, dp[len - 1][i - 1][j - 1]); // diagonal
                    }
                    if (bestPrev != NEG) {
                        dp[len][i][j] = bestPrev + cost.get(i).get(j);
                    }
                }
            }
        }

        // examine all possible lengths that end at the bottom‑right cell
        double bestAvg = 0.0;
        boolean found = false;
        for (int len = 1; len <= maxLen; ++len) {
            long sum = dp[len][size - 1][size - 1];
            if (sum != NEG) {
                double avg = (double) sum / len;
                if (avg > bestAvg) {
                    bestAvg = avg;
                    found = true;
                }
            }
        }
        if (!found) {
            return null; // no path exists (should not happen for a non‑empty matrix)
        }

        // truncate to one decimal place (floor to the nearest tenth)
        double result = Math.floor(bestAvg * 10.0) / 10.0;
        return result;
    }

    // --------------------------------------------------------------------
    // Simple test driver (matches the examples given in the description)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = new ArrayList<>();
        cost1.add(Arrays.asList(1, 2, 3));
        cost1.add(Arrays.asList(6, 5, 4));
        cost1.add(Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // expected 5.2

        // Example 2
        List<List<Integer>> cost2 = new ArrayList<>();
        cost2.add(Arrays.asList(2, 3, 4));
        cost2.add(Arrays.asList(7, 6, 5));
        cost2.add(Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // expected 6.2

        // Example 3
        List<List<Integer>> cost3 = new ArrayList<>();
        cost3.add(Arrays.asList(3, 4, 5));
        cost3.add(Arrays.asList(8, 7, 6));
        cost3.add(Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // expected 7.2
    }
}

