class NewmanPrime {
    /**
     * Write a function to find the nth Newman–Shanks–Williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // n must be positive
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Base cases of the recurrence: s0 = 1, s1 = 1
        if (n == 1) return 1;
        if (n == 2) return 3;   // s2 = 2*1 + 1 = 3

        int prev2 = 1; // s_{i-2}
        int prev1 = 1; // s_{i-1}
        int cur = 0;

        // Compute s_i for i = 3 .. n
        for (int i = 3; i <= n; i++) {
            cur = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = cur;
        }
        return cur;
    }
}

