public final class Maxaverageofpath {

    // Prevent instantiation – there is no need to create objects of this class.
    private Maxaverageofpath() {
        throw new UnsupportedOperationException("This class is not intended to be instantiated");
    }

    /**
     * Returns the maximum possible average of a path that travels from the
     * top‑left corner to the bottom‑right corner of the given n×n matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix (cost.size() == n)
     * @return the maximum average (as a {@code Double}), or {@code null} if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // DP array holds the maximum sum to reach each cell.
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table – choose the better predecessor and add current cost
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The path always contains exactly (2 * n - 1) cells
        double maxSum = dp[n - 1][n - 1];
        double maxAverage = maxSum / (2 * n - 1);

        return maxAverage;
    }
}

