     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowel characters (both cases)
        final String VOWELS = "aeiouAEIOU";

        // Helper to test if a character is a vowel
        java.util.function.Predicate<Character> isVowel = ch -> VOWELS.indexOf(ch) != -1;

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only count consonants that are next to a vowel
            if (isVowel.test(ch)) {
                continue;
            }

            // Check left neighbour
            boolean leftIsVowel = i > 0 && isVowel.test(testStr.charAt(i - 1));
            // Check right neighbour
            boolean rightIsVowel = i < len - 1 && isVowel.test(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }

