class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The Newman‑Shanks‑Williams sequence starts with a(0) = 1, a(1) = 1
        long a0 = 1;
        long a1 = 1;

        // Handle the first two positions directly
        if (n == 0) return (int) a0;
        if (n == 1) return (int) a1;

        // Compute a(i) for i = 2 .. n
        for (int i = 2; i <= n; i++) {
            long a2 = 2 * a1 + a0; // recurrence relation
            a0 = a1;
            a1 = a2;
        }

        // The result fits in an int for the expected range of n
        return (int) a1;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

