        // \b           – word boundary
        // This guarantees that 'z' is not the first or last character of the word.
        Pattern p = Pattern.compile("\\b[a-z]+z[a-z]+\\b");
        Matcher m = p.matcher(lower);

        return m.find() ? "Found a match!" : "Not matched!";
    }

