public final class Maxaverageofpath {

    /**
     * Returns the maximum average of a monotonic (right‑only / down‑only) path
     * from the top‑left corner to the bottom‑right corner of the given n×n matrix.
     *
     * @param cost the n×n matrix of integer costs (List of List of Integer)
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a {@code Double}, or {@code null} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- basic validation -------------------------------------------------
        if (cost == null || n <= 0) {
            return null;
        }
        // If the outer list size does not match the supplied n, adapt to the real size.
        if (cost.size() != n) {
            n = cost.size();
        }

        // ---- DP: dp[i][j] = max sum to reach cell (i,j) -----------------------
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; ++j) {
                double val = row.get(j).doubleValue();

                if (i == 0 && j == 0) {
                    // starting cell
                    dp[i][j] = val;
                } else {
                    double fromTop  = (i > 0)     ? dp[i - 1][j]   : Double.NEGATIVE_INFINITY;
                    double fromLeft = (j > 0)     ? dp[i][j - 1]   : Double.NEGATIVE_INFINITY;
                    dp[i][j] = val + Math.max(fromTop, fromLeft);
                }
            }
        }

        // ---- compute average ---------------------------------------------------
        // Any monotonic path from (0,0) to (n‑1,n‑1) visits exactly (2*n‑1) cells.
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // ---- simple test driver (optional) ---------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

