     * It follows the recurrence:
     *   Pell(0) = 1
     *   Pell(1) = 3
     *   Pell(k) = 2·Pell(k‑1) + Pell(k‑2)   for k ≥ 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     *
     * @param n 1‑based index (n must be positive)
     * @return the n‑th term of the sequence
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Pell(0) = 1, Pell(1) = 3
        long a = 1;   // Pell(k‑2)
        long b = 3;   // Pell(k‑1)

        // Direct answers for the first two positions
        if (n == 1) return (int) a;   // 1
        if (n == 2) return (int) b;   // 3

        // Compute Pell(k) for k = 2 … n‑1
        long c = 0;   // Pell(k)
        for (int i = 2; i <= n - 1; i++) {
            c = 2 * b + a;   // recurrence relation
            a = b;
            b = c;
        }
        return (int) c;   // Pell(n‑1)
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

