import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all monotone (right/down) paths
     * from the top‑left to the bottom‑right of the square matrix.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the size of the matrix (number of rows/columns)
     * @return the maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against bad input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] holds the greatest possible sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int cellValue = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cellValue;
                } else if (i == 0) {
                    // First row – can only come from the left
                    dp[i][j] = dp[i][j - 1] + cellValue;
                } else if (j == 0) {
                    // First column – can only come from above
                    dp[i][j] = dp[i - 1][j] + cellValue;
                } else {
                    // Take the better of the two predecessor paths and add current cell
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cellValue;
                }
            }
        }

        // The best sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // All monotone paths have exactly (2*n - 1) cells, so the average is:
        double average = maxSum / (2 * n - 1);

        return Double.valueOf(average);
    }

    // --------------------------------------------------------------------
    // Simple manual test (can be removed or replaced by JUnit tests)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // Expected: 7.2
    }
}

