import java.math.BigInteger;

class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   p0 = 1, p1 = 1
     *   pn = 2·p(n‑1) + p(n‑2)  for n ≥ 2
     *
     * For the given examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n the index (1‑based) of the desired term
     * @return the n‑th term of the Newman‑Shanks‑Williams sequence
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // p0 = 1, p1 = 1
        BigInteger p0 = BigInteger.ONE;
        BigInteger p1 = BigInteger.ONE;

        // Compute p2 … pn
        for (int i = 2; i <= n; i++) {
            BigInteger p2 = p1.multiply(BigInteger.valueOf(2)).add(p0);
            p0 = p1;
            p1 = p2;
        }

        // p1 now holds pn
        // The problem’s examples use small n, so an int return is sufficient.
        return p1.intValue();
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

