class CountVowels {
    /**
     * Counts characters that are not vowels and that have at least one vowel
     * as an immediate neighbour (to the left or right).
     *
     * @param testStr the input string
     * @return the number of such characters
     *
     * Example:
     * <pre>
     * countVowels("bestinstareels")        -> 7
     * countVowels("partofthejourneyistheend") -> 12
     * countVowels("amazonprime")          -> 5
     * </pre>
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only count consonants (i.e., non‑vowel characters)
            if (isVowel(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // check right neighbour
            if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    /** Helper: case‑insensitive vowel test. */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' ||
               lower == 'i' || lower == 'o' || lower == 'u';
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));         // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

