            return 0;
        }

        // Use the formula n(n+1)(2n+1)/6 for the sum of squares.
        // Store intermediate result in long to avoid overflow, then cast back to int.
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;
        return (int) sum;
    }
}

