public static int newmanPrime(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0 || n == 1) {
        return 1;
    }
    long prev2 = 1; // a_{i-2}
    long prev1 = 1; // a_{i-1}
    long current = 0;
    for (int i = 2; i <= n; i++) {
        current = 2 * prev1 + prev2;
        prev2 = prev1;
        prev1 = current;
    }
    return (int) current;
}

