import java.util.*;
import java.util.Objects;

/**
 * Computes the maximum average of a path that moves only right or down
 * from the top‑left corner to the bottom‑right corner of an n×n matrix.
 *
 * The average is the sum of the cell values on the path divided by the
 * number of cells visited (always 2·n – 1).
 */
public class Maxaverageofpath {

    // ---------------------------------------------------------------------
    // 1. Interface – the contract for any calculator
    // ---------------------------------------------------------------------
    @FunctionalInterface
    public interface MaxAverageComputer {
        /**
         * Returns the maximum possible average of a right‑/down‑only path.
         *
         * @param cost the square matrix (List of rows)
         * @param n    size of the matrix (number of rows/columns)
         * @return the maximal average as a {@code Double}
         */
        Double maxAverage(List<List<Integer>> cost, int n);
    }

    // ---------------------------------------------------------------------
    // 2. Skeletal (abstract) implementation – the “template method”
    // ---------------------------------------------------------------------
    abstract class AbstractMaxAverageComputer implements MaxAverageComputer {

        /**
         * Template method: first computes the maximal sum, then converts it
         * to an average.
         */
        @Override
        public final Double maxAverage(List<List<Integer>> cost, int n) {
            Objects.requireNonNull(cost, "cost must not be null");
            if (n <= 0) {
                throw new IllegalArgumentException("n must be positive");
            }

            int maxSum = computeMaxSum(cost, n);
            // Every right/down path contains exactly 2*n‑1 cells.
            return (double) maxSum / (2 * n - 1);
        }

        /**
         * Core DP algorithm – can be overridden by subclasses if a different
         * strategy is needed.
         *
         * @param cost the matrix
         * @param n   dimension
         * @return maximal sum from (0,0) to (n‑1,n‑1) moving only right/down
         */
        protected int computeMaxSum(List<List<Integer>> cost, int n) {
            int[][] dp = new int[n][n];

            // (0,0)
            dp[0][0] = cost.get(0).get(0);

            // first row – can only come from the left
            for (int j = 1; j < n; j++) {
                dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
            }

            // first column – can only come from above
            for (int i = 1; i < n; i++) {
                dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
            }

            // interior cells – take the better of the two predecessors
            for (int i = 1; i < n; i++) {
                for (int j = 1; j < n; j++) {
                    dp[i][j] = cost.get(i).get(j) +
                               Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }

            return dp[n - 1][n - 1];
        }
    }

    // ---------------------------------------------------------------------
    // 3. Concrete (final) implementation – the “public API”
    // ---------------------------------------------------------------------
    final class MaxAveragePath extends AbstractMaxAverageComputer {
        // No extra code needed; the skeleton does everything.
    }

    // ---------------------------------------------------------------------
    // 4. Public static entry point required by the problem statement
    // ---------------------------------------------------------------------
    /**
     * Returns the maximum average of any path that moves only right or down
     * from the top‑left to the bottom‑right of the given square matrix.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the matrix (number of rows/columns)
     * @return the maximal average, or {@code null} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // The concrete implementation is created once and reused.
        // Using the diamond operator (&lt;&gt;) works from Java 7 onward.
        MaxAverageComputer computer = new Maxaverageofpath().new MaxAveragePath();
        return computer.maxAverage(cost, n);
    }

    // ---------------------------------------------------------------------
    // 5. Simple test driver (optional – can be removed in production)
    // ---------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

