class CountVowels {
    /**
     * Counts characters (excluding vowels) that have at least one vowel
     * as an immediate neighbor (to the left or to the right).
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with a lower‑case version for case‑insensitive comparison
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);
            // Skip vowels themselves – we only count consonants that have a vowel neighbor
            if (isVowel(c)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbor
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbor
            if (i < len - 1 && isVowel(s.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /** Helper method to determine if a character is a vowel. */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

