class TextMatchWordzMiddle {
    /**
     * Returns "Found a match!" if the input string contains a word
     * that has the letter 'z' somewhere other than the first or last
     * position; otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")      → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")    → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern to match a sequence of letters (a word) – punctuation is ignored.
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // the actual word as it appears
            String lower = word.toLowerCase();           // case‑insensitive check
            int idx = lower.indexOf('z');                // position of 'z' (or -1 if none)

            // ‘z’ must be present and not at the start or end of the word.
            if (idx > 0 && idx < word.length() - 1) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

