import java.util.List;

class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a monotonic path
     * (moving only right or down) from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost  a square list of lists representing the matrix
     * @param n     size of the matrix (number of rows/columns)
     * @return      the highest average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive check – not strictly required by the task but avoids NPEs
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[j] holds the best sum to reach cell (i, j) from (0,0)
        long[] dp = new long[n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                long val = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // start cell
                    dp[j] = val;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[j] = dp[j - 1] + val;
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[j] = dp[j] + val;          // dp[j] still contains the value from the previous row
                } else {
                    // interior cell – take the better of the cell above or the cell to the left
                    dp[j] = Math.max(dp[j], dp[j - 1]) + val;
                }
            }
        }

        long maxSum = dp[n - 1];                 // best sum to (n‑1, n‑1)
        double average = (double) maxSum / (2L * n - 1); // total cells visited = 2n‑1

        return Double.valueOf(average);
    }
}

