class CountVowels {
    /**
     * Counts consonants in the given string that have a vowel as one of their
     * immediate neighbours (left or right).
     *
     * @param testStr the input string
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with a lower‑case copy for case‑insensitive vowel detection
        String s = testStr.toLowerCase();
        int n = s.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            // Skip vowels – we only count consonants
            if (isVowel(c)) {
                continue;
            }

            // Check left neighbour
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                count++;
                continue; // no need to check right neighbour
            }

            // Check right neighbour
            if (i < n - 1 && isVowel(s.charAt(i + 1))) {
                count++;
            }
        }
        return count;
    }

    /** Helper that returns true if the given character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

