public static int newmanPrime(int n) {
    // negative index is not valid
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }

    // a(0) = 1, a(1) = 1
    if (n == 0 || n == 1) {
        return 1;
    }

    long a = 1;   // a(i‑2)  → a(0)
    long b = 1;   // a(i‑1)  → a(1)
    long c = 0;   // a(i)

    for (int i = 2; i <= n; i++) {
        c = 2 * b + a;   // a(i) = 2*a(i‑1) + a(i‑2)
        a = b;
        b = c;
    }

    // The sequence grows quickly; for reasonably small n the result fits in int
    return (int) c;
}

