    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // s0 = 1, s1 = 1
        long s0 = 1;
        long s1 = 1;

        if (n == 0) return (int) s0;
        if (n == 1) return (int) s1;

        long sn = 0;
        for (int i = 2; i <= n; i++) {
            // sn = 2 * s_{i-1} + s_{i-2}
            sn = 2 * s1 + s0;
            s0 = s1;
            s1 = sn;
        }

        // The sequence grows quickly; using long prevents overflow for moderate n.
        // The problem’s examples use n such that the result fits in int.
        return (int) sn;
    }
}

