class Maxaverageofpath {

    /**
     * Returns the maximum average value among all monotonic (right‑down) paths
     * from the top‑left corner to the bottom‑right corner of an n×n cost matrix.
     *
     * @param cost a list of n rows, each row a list of n integers
     * @param n    dimension of the square matrix
     * @return     the maximum average as a {@code Double}, or {@code null} if input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table holds the best sum to reach each cell
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First column:只能从上向下
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // First row:只能从左到右
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum from start to finish
        double maxSum = dp[n - 1][n - 1];

        // Number of cells in any monotonic path = 2 * n - 1
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // --------------------------------------------------------------------
    // Optional test driver
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Handle null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }
        // Work with lower‑case for case‑insensitive vowel detection
        String s = testStr.toLowerCase();
        int n = s.length();
        int count = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            // We only count consonants (characters that are not vowels)
            if (isVowel(c)) {
                continue;
            }
            boolean hasVowelNeighbor = false;
            // Check left neighbor
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbor if left neighbor is not a vowel
            if (!hasVowelNeighbor && i < n - 1 && isVowel(s.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }
            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    /** Returns true if ch is one of a, e, i, o, u. */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }
}

