class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * For n >= 2 this is the n‑th term of the sequence:
     *   s0 = 1, s1 = 1, sn = 2·sn‑1 + sn‑2.
     *
     * @param n the index (1‑based) of the desired term
     * @return the n‑th NSW number
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // s0 and s1 are both 1
        if (n == 1) {
            return 1;
        }

        long a = 1; // s0
        long b = 1; // s1
        long c = 0; // will hold sn

        for (int i = 2; i <= n; i++) {
            c = 2 * b + a; // sn = 2·sn‑1 + sn‑2
            a = b;
            b = c;
        }
        // The problem expects an int; the test data fits in int range.
        return (int) c;
    }

    // Simple manual test (not required for the final answer)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

