     * Returns the maximum average value among all monotone paths
     * (right‑/down moves only) from the top‑left corner to the bottom‑right
     * corner of an n×n cost matrix.
     *
     * @param cost  list of rows, each row is a list of Integer values
     * @param n     size of the square matrix
     * @return      the maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation -------------------------------------------------
        if (cost == null || cost.size() != n) {
            return null;                     // defensive check
        }

        // ---- DP table: maximum sum to each cell -------------------------------
        long[][] dp = new long[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest: take the better of the two predecessor paths
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) +
                            Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average --------------------------------------------------
        long maxSum = dp[n - 1][n - 1];                // sum on the best path
        double average = maxSum / (double) (2 * n - 1); // length = 2·n‑1 cells

        return average;
    }

