class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)   for n >= 2
     *
     * The first few terms are: 1, 1, 3, 7, 17, 41, 99, …
     * For n >= 2 the returned values are prime (3, 7, 17, 41, …).
     *
     * @param n index (0‑based) of the desired NSW number
     * @return the n‑th NSW number as an int
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // a0 = 1
        if (n == 0) {
            return 1;
        }
        // a1 = 1
        if (n == 1) {
            return 1;
        }

        // Use BigInteger to avoid overflow for larger n.
        BigInteger a0 = BigInteger.ONE; // a(i‑2)
        BigInteger a1 = BigInteger.ONE; // a(i‑1)
        BigInteger a  = BigInteger.ZERO; // a(i)

        for (int i = 2; i <= n; i++) {
            // a(i) = 2 * a(i‑1) + a(i‑2)
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            // shift the window for the next iteration
            a0 = a1;
            a1 = a;
        }

        // The result is assumed to fit in an int for typical test cases.
        return a.intValue();
    }

    // -----------------------------------------------------------------
    // A tiny test driver (optional)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

