     * * Write a function to calculate volume of a tetrahedron.
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        // Edge length of the regular tetrahedron
        double a = num;

        // Volume formula: V = a^3 / (6 * sqrt(2))
        double volume = (a * a * a) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places to match the expected output
        volume = Math.round(volume * 100.0) / 100.0;

        return volume;
    }
}

import java.util.regex.*;

public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the given text contains a word that has the
     * letter 'z' (case‑insensitive) somewhere other than the first or last
     * character. Otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches a sequence of letters (a–z or A–Z)
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            if (containsZNotAtEdges(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * Helper method: checks whether the supplied word contains a 'z' or 'Z'
     * at any position other than the first or last character.
     */
    private static boolean containsZNotAtEdges(String word) {
        // A word of length 0‑2 cannot have a middle 'z'
        if (word.length() <= 2) {
            return false;
        }
        // Scan the interior of the word (indices 1 … length‑2)
        for (int i = 1; i < word.length() - 1; i++) {
            char ch = word.charAt(i);
            if (ch == 'z' || ch == 'Z') {
                return true;
            }
        }
        return false;
    }

    // --------------------------------------------------------------------
    // Optional test driver (you can remove or comment out this part)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a monotonic (right/down) path
     * from the top‑left to the bottom‑right of the n×n cost matrix.
     *
     * @param cost  list of rows, each row a list of integers
     * @param n     size of the square matrix
     * @return      maximum average as a Double, or null for invalid input
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal arguments
        if (cost == null || n <= 0) {
            return null;
        }

        // DP array holds the best sum reaching each cell
        long[][] dp = new long[n][n];

        // Initialize start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest: each cell is the cost of current cell plus the best
        // of the cell above or to the left.
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // All monotonic paths have exactly (2*n - 1) cells,
        // so the average is total sum divided by that constant.
        double average = (double) dp[n - 1][n - 1] / (2L * n - 1);
        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
            List.of(1, 2, 3),
            List.of(6, 5, 4),
            List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // expected 5.2

        List<List<Integer>> m2 = List.of(
            List.of(2, 3, 4),
            List.of(7, 6, 5),
            List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // expected 6.2

        List<List<Integer>> m3 = List.of(
            List.of(3, 4, 5),
            List.of(8, 7, 6),
            List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // expected 7.2
    }
}

