import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2 * a(n-1) + a(n-2)   for n >= 2
     *
     * @param n the index (1‑based) of the desired term
     * @return the n‑th term of the NSW sequence
     * @throws IllegalArgumentException if n <= 0
     *
     * Example values:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // a(0) = 1, a(1) = 1
        long a0 = 1L;
        long a1 = 1L;

        // For n == 1 or n == 2 we return the base values (both are 1)
        if (n == 1) {
            return (int) a0;
        }
        if (n == 2) {
            return (int) a1;
        }

        // Compute a(n) iteratively
        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(i) = 2*a(i-1) + a(i-2)
            a0 = a1;         // shift for next iteration
            a1 = a;
        }

        // The problem expects an int result; the loop above guarantees
        // the value fits into int for the typical small n used in the tests.
        return (int) a;
    }

    // --------------------------------------------------------------------
    // A tiny driver to quick‑check the implementation (optional)
    public static void main(String[] args) {
        for (int i = 1; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

