public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' somewhere other than the first or last character of the word.
     * Otherwise returns "Not matched!".
     *
     * @param text the input text (may contain punctuation, spaces, etc.)
     * @return the appropriate message
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Pattern that matches a word: one or more ASCII letters
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int len = word.length();

            // A middle position exists only if the word has at least 3 letters
            if (len >= 3) {
                // Look for a 'z' (case‑insensitive) that is not at index 0 or len‑1
                for (int i = 1; i < len - 1; i++) {
                    if (Character.toLowerCase(word.charAt(i)) == 'z') {
                        return "Found a match!";
                    }
                }
            }
        }

        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // Simple test driver (feel free to remove or adapt)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // → Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // → Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // → Not matched!
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that moves only right or down
     * from the top‑left to the bottom‑right corner of an n×n cost matrix.
     *
     * @param cost the n×n matrix of integers
     * @param n    dimension of the square matrix
     * @return the maximum possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal arguments
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Initialize the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                         + cost.get(i).get(j);
            }
        }

        // The path always contains exactly (2*n - 1) cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

