     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowels (both lower‑ and upper‑case)
        Set<Character> vowels = Set.of('a', 'e', 'i', 'o', 'u',
                                       'A', 'E', 'I', 'O', 'U');

        char[] ch = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < ch.length; i++) {
            char c = ch[i];
            // We only count non‑vowel characters that are adjacent to a vowel
            if (vowels.contains(c)) {
                continue; // skip vowels themselves
