            boolean hasVowelNeighbor = false;

            // Check left neighbor
            if (i > 0 && vowels.contains(ch[i - 1])) {
                hasVowelNeighbor = true;
            }
            // Check right neighbor
            if (i < ch.length - 1 && vowels.contains(ch[i + 1])) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

