import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   s0 = 1, s1 = 1,
     *   sn = 2 * s(n‑1) + s(n‑2)  for n >= 2.
     *
     * For example:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     *
     * @param n index of the desired term (0‑based)
     * @return the n‑th term as an int
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Use BigInteger to avoid overflow for larger n.
        BigInteger a = BigInteger.ONE; // s0
        BigInteger b = BigInteger.ONE; // s1

        for (int i = 2; i <= n; i++) {
            // sn = 2 * s(n‑1) + s(n‑2)
            BigInteger c = b.multiply(BigInteger.valueOf(2)).add(a);
            a = b;
            b = c;
        }

        // For n == 0 or n == 1 the loop is skipped and b == 1,
        // which matches the definition of s0 and s1.
        return b.intValue();   // final result as int (caller expects int)
    }
}

class RemoveOdd {
    /**
     * Removes characters at odd positions (1‑indexed) from the input string.
     *
     * @param str1 the original string
     * @return a new string containing only the characters that were at even
     *         positions (0‑based odd indices) in the original string
     */
    public static String removeOdd(String str1) {
        if (str1 == null) {
            return null;               // or throw an exception, depending on requirements
        }
        StringBuilder result = new StringBuilder();
        // start at index 1 (the second character) and step by 2
        for (int i = 1; i < str1.length(); i += 2) {
            result.append(str1.charAt(i));
        }
        return result.toString();
    }
}

