import java.lang.Math;   // already imported via java.lang.*

class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron with side length `num`.
     *
     * @param num the side length of the tetrahedron
     * @return the volume rounded to two decimal places
     */
    public static Double volumeTetrahedron(int num) {
        // Volume of a regular tetrahedron: V = a^3 / (6 * sqrt(2))
        double side = num;                     // promote int to double
        double volume = Math.pow(side, 3) / (6 * Math.sqrt(2));

        // Round to two decimal places (optional, matches the examples)
        double rounded = Math.round(volume * 100.0) / 100.0;

        return Double.valueOf(rounded);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

import java.util.regex.*;

public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' other than at the first or last position; otherwise returns
     * "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern matches whole words consisting of letters only
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            // Convert to lower‑case for case‑insensitive matching
            String lowerWord = word.toLowerCase();
            int zIndex = lowerWord.indexOf('z');

            // If 'z' is present and is not the first or last character
            if (zIndex > 0 && zIndex < word.length() - 1) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
    }
}

import java.util.List;
import java.util.Arrays;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a monotone path (right‑/down moves only)
     * from the top‑left corner to the bottom‑right corner of an n×n cost matrix.
     *
     * @param cost  a list of n rows, each row a list of n integers
     * @param n     size of the square matrix
     * @return      the maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum ends at the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // Every monotone path visits exactly (2 * n - 1) cells
        double average = maxSum / (2.0 * n - 1.0);

        return average;
    }

    // Simple manual test (can be removed when integrating into a larger codebase)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // Expected: 7.2
    }
}

