class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the integer n (must be non‑negative)
     * @return the sum of squares from 1 to number
     *
     * Example:
     * seriesSum(6) → 91
     * seriesSum(7) → 140
     * seriesSum(12) → 650
     */
    public static int seriesSum(int number) {
        // Guard against non‑positive input
        if (number <= 0) {
            return 0;
        }

        // Use long for the intermediate product to avoid overflow,
        // then cast back to int for the final result.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;
    }

    // Optional: simple test driver
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

