import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (n == 1) {
            return 2;
        }
        long a = 1; // s0
        long b = 1; // s1
        int count = 1; // we have counted the prime 2
        while (true) {
            long c = 2 * b + a; // s_i
            if (isPrime(c)) {
                count++;
                if (count == n) {
                    return (int) c;
                }
            }
            a = b;
            b = c;
        }
    }

    // Helper method to test primality using BigInteger's probable prime test
    private static boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;
        return BigInteger.valueOf(num).isProbablePrime(100);
    }
}

