public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        // \b\w+\b matches a whole word (letters, digits, underscore)
        Matcher matcher = Pattern.compile("\\b\\w+\\b").matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int len = word.length();

            // Look for a 'z' that is not at index 0 or at the last index.
            for (int i = 1; i < len - 1; i++) {
                if (word.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

