class CountVowels {
    /**
     * Counts characters that are not vowels (consonants) and have at least
     * one vowel neighbor (to the left or right). Edge characters are counted
     * if their only neighbor is a vowel.
     *
     * Examples:
     *   countVowels("bestinstareels")        → 7
     *   countVowels("partofthejourneyistheend") → 12
     *   countVowels("amazonprime")           → 5
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with lower‑case to be case‑insensitive
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = s.charAt(i);

            // We only consider consonants (i.e. non‑vowel characters)
            if (!VowelChecker.isVowel(ch)) {
                boolean hasVowelNeighbor = false;

                // Check left neighbor
                if (i > 0 && VowelChecker.isVowel(s.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // Check right neighbor
                if (i < len - 1 && VowelChecker.isVowel(s.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Static member class that provides a simple vowel‑checking utility.
     * Using a static member class follows the advice to favor static over
     * nonstatic nested classes.
     */
    static class VowelChecker {
        private static final String VOWELS = "aeiou";

        /** Returns true if the given character is a vowel (a, e, i, o, u). */
        static boolean isVowel(char c) {
            return VOWELS.indexOf(c) >= 0;
        }
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

