/**
 * Utility class that provides a simple logging‑oriented operation:
 * finding the length of the longest word in a list of strings.
 */
class LenLog {

    /**
     * Returns the length of the longest string in the supplied list.
     * If the list is null or empty, the method returns 0.
     *
     * @param list1 a list of strings (may contain nulls)
     * @return the maximum length among the strings, or 0 if none exist
     */
    public static int lenLog(List<String> list1) {
        // Guard against null or empty input
        if (list1 == null || list1.isEmpty()) {
            return 0;
        }

        // Using streams – concise, clear, and avoids explicit loops
        return list1.stream()
                .filter(Objects::nonNull)          // ignore null entries
                .mapToInt(String::length)          // map each word to its length
                .max()                             // OptionalInt containing the largest length
                .orElse(0);                        // default if no non‑null elements exist
    }

    // ---- Simple test driver -------------------------------------------------
    public static void main(String[] args) {
        System.out.println(lenLog(Arrays.asList("python", "PHP", "bigdata"))); // 7
        System.out.println(lenLog(Arrays.asList("a", "ab", "abc")));          // 3
        System.out.println(lenLog(Arrays.asList("small", "big", "tall")));    // 5
        System.out.println(lenLog(Collections.emptyList()));                  // 0
    }
}

import java.math.BigInteger;

/**
 * <p>
 * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
 * The sequence is defined by:
 * <pre>
 *     s(0) = 1
 *     s(1) = 1
 *     s(n) = 2 * s(n-1) + s(n-2)   for n >= 2
 * </pre>
 * The values produced for n = 3, 4, 5 … are 7, 17, 41 … which match the
 * examples given in the problem statement.
 * </p>
 *
 * @param n the index (1‑based) of the desired term; must be positive
 * @return the n‑th Newman‑Shanks‑Williams number as an {@code int}
 * @throws IllegalArgumentException if {@code n <= 0}
 */
public class NewmanPrime {

    /**
     * Computes the n‑th Newman‑Shanks‑Williams number.
     *
     * @param n a positive integer (1‑based)
     * @return the value s(n) of the sequence
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // Base cases s(0) = 1, s(1) = 1
        if (n == 1) {
            return 1;
        }

        BigInteger s0 = BigInteger.ONE; // s(0)
        BigInteger s1 = BigInteger.ONE; // s(1)
        BigInteger sn = null;

        // Compute s(2) … s(n)
        for (int i = 2; i <= n; i++) {
            sn = s1.multiply(BigInteger.TWO).add(s0); // s(i) = 2*s(i-1) + s(i-2)
            s0 = s1;
            s1 = sn;
        }

        // The problem expects an int return type.
        return sn.intValue();
    }

    // Simple sanity‑check (can be removed or turned into JUnit tests)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

import java.util.Iterator;

/**
 * Utility class that removes characters at even positions (0‑based)
 * from a string, leaving only the characters at odd positions.
 */
public class RemoveOdd {

    /**
     * Returns a new string containing only the characters from the
     * original string that are at odd positions (index 1, 3, 5, …).
     *
     * @param str1 the input string (may be null)
     * @return a string with odd‑index characters, or null if the input is null
     *
     * Example:
     *   removeOdd("python") → "yhn"
     *   removeOdd("program") → "rga"
     *   removeOdd("language") → "agae"
     */
    public static String removeOdd(String str1) {
        if (str1 == null) {
            return null;
        }

        StringBuilder sb = new StringBuilder();
        // Use the static nested iterator to walk odd indices
        for (Iterator<Character> it = new OddIndexIterator(str1); it.hasNext(); ) {
            sb.append(it.next());
        }
        return sb.toString();
    }

    /**
     * Static nested class that iterates over the characters of a string
     * located at odd positions (1, 3, 5, …).  Because it does not need
     * a reference to an enclosing instance, it is declared static,
     * avoiding the overhead of an implicit outer‑class reference.
     */
    private static class OddIndexIterator implements Iterator<Character> {
        private final String str;
        private int index = 1; // start at the first odd position

        OddIndexIterator(String s) {
            this.str = s;
        }

        @Override
        public boolean hasNext() {
            return index < str.length();
        }

        @Override
        public Character next() {
            char c = str.charAt(index);
            index += 2; // jump to the next odd index
            return c;
        }
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));    // yhn
        System.out.println(removeOdd("program"));   // rga
        System.out.println(removeOdd("language"));  // agae
    }
}

