class VolumeTetrahedron {

    /**
     * * Write a function to calculate volume of a tetrahedron.
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */

    // Private static member class – it does not need access to an enclosing instance.
    private static class Tetrahedron {
        private final double side;

        Tetrahedron(double side) {
            this.side = side;
        }

        // Volume of a regular tetrahedron: V = a^3 / (6 * sqrt(2))
        double volume() {
            return (side * side * side) / (6.0 * Math.sqrt(2.0));
        }
    }

    public static Double volumeTetrahedron(int num) {
        // Use the static member class to compute the volume
        Tetrahedron t = new Tetrahedron(num);
        double v = t.volume();

        // Round to two decimal places (as the examples show)
        v = Math.round(v * 100.0) / 100.0;

        // Return as a Double object
        return Double.valueOf(v);
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

