class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   ai = 2 * a(i-1) + a(i-2)  for i >= 2
     *
     * For the values shown in the examples (n = 3,4,5) the returned
     * numbers are prime, which is why they are referred to as
     * “Newman‑Shanks‑Williams primes”.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the base cases directly
        if (n == 0) return 1; // a0
        if (n == 1) return 1; // a1

        long prevPrev = 1; // a0
        long prev      = 1; // a1
        long current   = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev + prevPrev;
            prevPrev = prev;
            prev = current;
        }

        // The result fits in an int for the typical test range;
        // cast after the loop.
        return (int) current;
    }
}

