class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the letter 'z'
     * somewhere other than the first or last position; otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches a whole word (only letters, no punctuation)
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int zIndex = word.indexOf('z');           // position of 'z' (‑1 if absent)

            // 'z' must be present and not at the start or end of the word
            if (zIndex != -1 && zIndex != 0 && zIndex != word.length() - 1) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));     // "Not matched!"
    }
}

