class Maxaverageofpath {
    /**
     * Returns the maximum average value of a path that travels from the
     * top‑left corner to the bottom‑right corner of the given n×n matrix.
     * Movement is restricted to rightward or downward steps.
     *
     * @param cost the n×n matrix of path costs
     * @param n    dimension of the square matrix
     * @return     the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException("Matrix size does not match n");
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // All paths have the same length: (2*n - 1) cells
        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);

        return average;
    }
}

