            char ch = s.charAt(i);

            // Skip vowels – we only want to count consonants
            if (isVowel(ch)) {
                continue;
            }

            // Check left neighbour
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                count++;
                continue;               // already satisfied, no need to check right
            }

            // Check right neighbour
            if (i < len - 1 && isVowel(s.charAt(i + 1))) {
                count++;
            }
        }
        return count;
    }

    /** Helper that tells whether a character is a vowel (a, e, i, o, u). */
