class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   a_i = 2 * a_{i-1} + a_{i-2}   (i ≥ 2)
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // Base values for the recurrence
        if (n == 1) return 1;   // a1 = 1
        if (n == 2) return 3;   // a2 = 3

        long a0 = 1; // a(0)
        long a1 = 1; // a(1)
        long a  = 0; // will hold a(i)

        // Compute a(i) iteratively up to n
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a_i = 2*a_{i-1} + a_{i-2}
            a0 = a1;
            a1 = a;
        }

        // The problem expects an int return type
        return (int) a;
    }
}

