class TextMatchWordzMiddle {
    /**
     * Checks whether any word in the given text contains the letter 'z'
     * (or 'Z') that is **not** the first or last character of that word.
     *
     * @param text the input string to examine
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     *
     * Example usage:
     *   textMatchWordzMiddle("pythonzabc.")  → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")       → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")     → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // \b\w+\b matches whole words (letters, digits, underscore) ignoring punctuation.
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A word shorter than 3 characters can never have a middle 'z'.
            if (word.length() < 3) continue;

            // Look for a 'z' (or 'Z') that is not the first or last character.
            for (int i = 1; i < word.length() - 1; i++) {
                if (Character.toLowerCase(word.charAt(i)) == 'z') {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // → Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // → Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // → Not matched!
    }
}

import java.util.List;
import java.util.ArrayList;

public class Maxaverageofpath {
    /**
     * Returns the maximum average of any path that travels from the top‑left
     * corner to the bottom‑right corner of an n×n matrix, moving only right
     * or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a {@code Double}, or {@code null} if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.size() != n) {
            return null;
        }

        // DP[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Maximum sum at the destination
        long maxSum = dp[n - 1][n - 1];

        // Every path has exactly (2*n - 1) cells
        double average = (double) maxSum / (2L * n - 1);
        return Double.valueOf(average);
    }

    // --------------------------------------------------------------------
    // Optional test driver (matches the examples from the description)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = new ArrayList<>();
        cost1.add(List.of(1, 2, 3));
        cost1.add(List.of(6, 5, 4));
        cost1.add(List.of(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = new ArrayList<>();
        cost2.add(List.of(2, 3, 4));
        cost2.add(List.of(7, 6, 5));
        cost2.add(List.of(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = new ArrayList<>();
        cost3.add(List.of(3, 4, 5));
        cost3.add(List.of(8, 7, 6));
        cost3.add(List.of(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

