     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i < testStr.length(); i++) {
            char ch = testStr.charAt(i);

            // we only count consonants (i.e., non‑vowel characters)
            if (isVowel(ch)) {
                continue;
            }

            boolean leftIsVowel  = i > 0                 && isVowel(testStr.charAt(i - 1));
            boolean rightIsVowel = i < testStr.length() - 1 && isVowel(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

    /** Helper method to check if a character is a vowel (case‑insensitive). */
    private static boolean isVowel(char c) {
        char lower = Character.toLowerCase(c);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u';
    }
}

