public class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(i) = 2*a(i‑1) + a(i‑2)  for i ≥ 2
     *
     * @param n the 1‑based index of the desired number (n >= 1)
     * @return the n‑th Newman–Shanks–Williams number
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Use BigInteger to avoid overflow during the computation.
        BigInteger a0 = BigInteger.ONE; // a(0)
        BigInteger a1 = BigInteger.ONE; // a(1)

        if (n == 1) {
            return a0.intValue(); // returns 1
        }
        if (n == 2) {
            return a1.intValue(); // returns 1
        }

        BigInteger a = null;
        for (int i = 2; i <= n; i++) {
            // a(i) = 2*a(i‑1) + a(i‑2)
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            a0 = a1;
            a1 = a;
        }

        // The problem expects an int result; the test cases use small n,
        // so converting the BigInteger to int is safe for the given range.
        return a.intValue();
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

