class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     *
     * The NSW prime sequence (starting from the first prime) is:
     *   3, 7, 17, 41, 239, 577, …
     *
     * According to the problem's examples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     *
     * This corresponds to returning the (n‑2)-th NSW prime (zero‑based),
     * i.e. for n >= 2.
     *
     * @param n the index (must be >= 2)
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n < 2
     */
    public static int newmanPrime(int n) {
        if (n < 2) {
            throw new IllegalArgumentException("Input must be >= 2");
        }

        // Zero‑based index of the prime we need
        int targetIndex = n - 2;
        int primesFound = 0;

        // NSW sequence: a0 = 1, a1 = 1, a_i = 2*a_{i-1} + a_{i-2}
        long aMinus2 = 1; // a[i‑2]
        long aMinus1 = 1; // a[i‑1]

        // Generate NSW numbers starting from i = 2
        for (int i = 2; ; i++) {
            long a_i = 2 * aMinus1 + aMinus2;
            int candidate = (int) a_i; // fits in int for reasonable n

            if (isPrime(candidate)) {
                primesFound++;
                if (primesFound == targetIndex + 1) {
                    return candidate;
                }
            }

            // Prepare next iteration
            aMinus2 = aMinus1;
            aMinus1 = a_i;
        }
    }

    /**
     * Simple deterministic primality test for int values.
     * Checks divisibility up to sqrt(n) using the 6k±1 optimisation.
     *
     * @param n the number to test (must be non‑negative)
     * @return true if n is prime, false otherwise
     */
    private static boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;

        // Check factors of the form 6k ± 1 up to sqrt(n)
        for (int i = 5; i * (long) i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    // Optional quick test
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41

        // Additional sanity checks
        System.out.println(newmanPrime(2)); // 3
        System.out.println(newmanPrime(6)); // 239
        System.out.println(newmanPrime(7)); // 577
    }
}

