import java.util.*;

public class Maxaverageofpath {
    /**
     * Returns the maximum possible average value among all paths that go
     * from the top‑left corner to the bottom‑right corner of the n×n matrix.
     * Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the square matrix
     * @return the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] – maximum sum of a path from (0,0) to (i,j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // Number of cells visited on any full path = 2*n - 1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return Double.valueOf(average);
    }
}

