class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Negative indices are not valid.
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The first two values of the sequence are both 1.
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute the sequence iteratively.
        long a0 = 1; // a(0)
        long a1 = 1; // a(1)
        long a = 0; // a(n) will be stored here

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(i) = 2*a(i‑1) + a(i‑2)
            // Shift the previous two values forward.
            a0 = a1;
            a1 = a;
        }

        // The problem expects an int; the values fit in int for the intended range.
        return (int) a;
    }
}

