import java.util.List;

public class Maxaverageofpath {

    /**
     * Finds a path with the maximum average over all existing paths
     * in an n×n cost matrix.  Movement is restricted to right or down.
     *
     * @param cost  a square matrix (List of rows) containing the cell costs
     * @param n     the dimension of the matrix (number of rows/columns)
     * @return      the maximum possible average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP array holds the maximum sum to reach each cell.
        // Using long to avoid overflow for large n and large cell values.
        long[][] dp = new long[n][n];

        // Initialize the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum to reach the bottom‑right corner
        long maxSum = dp[n - 1][n - 1];

        // Every monotone path has exactly (2*n - 1) cells
        double average = maxSum / (2.0 * n - 1.0);

        return Double.valueOf(average);
    }
}

class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty strings
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Normalise to lower‑case so we can treat 'A' and 'a' the same
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = s.charAt(i);

            // We only count consonants (i.e. characters that are NOT vowels)
            if (isVowel(ch)) {
                continue; // skip vowels
            }

            boolean hasVowelNeighbor = false;

            // Check the left neighbour
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }

            // Check the right neighbour
            if (i < len - 1 && isVowel(s.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /** Helper that returns true if the given character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
