import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

/**
 * Solution for the “maximum average of a path” problem.
 *
 * Given a square matrix (size n×n) and the ability to move only right or down,
 * find the maximum possible average of the values on a path from the top‑left
 * corner to the bottom‑right corner.
 *
 * The average is computed as (maxSum / (2·n‑1)), because every path from
 * (0,0) to (n‑1,n‑1) contains exactly 2·n‑1 cells (n‑1 moves right + n‑1 moves down).
 */
class Maxaverageofpath {

    /**
     * Returns the maximum average of a path in the given n×n matrix.
     *
     * @param cost a list of n rows, each a list of n integers
     * @param n    the dimension of the square matrix
     * @return     the maximum average as a {@code Double}, or {@code null} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }
        // Ensure the matrix really has n rows and each row has n columns.
        if (cost.size() != n) {
            throw new IllegalArgumentException("Matrix row count does not match n");
        }
        for (int i = 0; i < n; i++) {
            if (cost.get(i) == null || cost.get(i).size() != n) {
                throw new IllegalArgumentException("Matrix column count does not match n");
            }
        }

        // ---- DP: maximum sum to each cell ------------------------------------
        // Use double to keep precision when we later divide by (2*n-1).
        double[][] dp = new double[n][n];

        // First cell (starting point)
        dp[0][0] = cost.get(0).get(0).doubleValue();

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j).doubleValue();
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0).doubleValue();
        }

        // Remaining cells: take the better of the two possible predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                        + cost.get(i).get(j).doubleValue();
            }
        }

        // ---- compute average --------------------------------------------------
        double maxSum = dp[n - 1][n - 1];
        int numberOfCellsOnPath = 2 * n - 1;
        return maxSum / numberOfCellsOnPath;
    }

    // -----------------------------------------------------------------------
    // A tiny test harness (not required for the solution, but useful for verification)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

