public class CountVowels {
    private static final Set<Character> VOWELS = Set.of('a', 'e', 'i', 'o', 'u');

    public static int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }
        String s = testStr.toLowerCase();
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            // only consider consonants (i.e., characters that are not vowels)
            if (!VOWELS.contains(c)) {
                boolean leftVowel = i > 0 && VOWELS.contains(s.charAt(i - 1));
                boolean rightVowel = i < s.length() - 1 && VOWELS.contains(s.charAt(i + 1));
                if (leftVowel || rightVowel) {
                    count++;
                }
            }
        }
        return count;
    }

    // Optional test
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

