class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   ai = 2 * a(i‑1) + a(i‑2)   for i >= 2
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        // Base cases: a0 = 1, a1 = 1
        if (n <= 1) {
            return 1;
        }

        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a  = 0; // a(i)

        // Compute terms from index 2 up to n
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence
            a0 = a1;
            a1 = a;
        }

        // The result fits in an int for reasonable n; cast safely
        return (int) a;
    }
}

