public class Maxaverageofpath {

    /**
     * Finds the maximum average of all monotonic (right‑down) paths
     * from the top‑left to the bottom‑right of an n×n integer matrix.
     *
     * @param cost  a list of n rows, each row a list of n integers
     * @param n     the dimension of the square matrix
     * @return      the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] holds the maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The total number of cells visited on any such path is (2*n - 1)
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        // Auto‑boxing to Double
        return average;
    }
}

public static int countVowels(String testStr) {
    // Guard against null or empty input
    if (testStr == null || testStr.isEmpty()) {
        return 0;
    }

    // Vowel set (both lower‑ and upper‑case)
    final String vowels = "aeiouAEIOU";

    int count = 0;
    int len = testStr.length();

    for (int i = 0; i < len; i++) {
        char ch = testStr.charAt(i);

        // We only consider consonants – skip vowels themselves
        if (vowels.indexOf(ch) >= 0) {
            continue;
        }

        // Check left neighbour
        boolean hasVowelNeighbor = false;
        if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) >= 0) {
            hasVowelNeighbor = true;
        }

        // Check right neighbour
        if (!hasVowelNeighbor && i < len - 1 && vowels.indexOf(testStr.charAt(i + 1)) >= 0) {
            hasVowelNeighbor = true;
        }

        if (hasVowelNeighbor) {
            count++;
        }
    }

    return count;
}

