class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     *
     * The sequence is defined by:
     *   a(1) = 1
     *   a(2) = 3
     *   a(n) = 2·a(n‑1) + a(n‑2)  for n > 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     *
     * @param n the 1‑based index (must be > 0)
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Base cases
        if (n == 1) {
            return 1; // a(1)
        }
        if (n == 2) {
            return 3; // a(2)
        }

        // Use long to avoid overflow before casting back to int.
        long prev2 = 1L; // a(1)
        long prev1 = 3L; // a(2)
        long current = 0L;

        for (int i = 3; i <= n; i++) {
            current = 2 * prev1 + prev2; // a(i) = 2·a(i‑1) + a(i‑2)
            // Shift the window forward
            prev2 = prev1;
            prev1 = current;
        }

        return (int) current;
    }

    // Optional quick test
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

