class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2*a(n-1) + a(n-2) for n >= 2
     *
     * @param n the index of the required term (0‑based)
     * @return the n‑th term of the NSW sequence
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the first two base cases
        if (n == 0) return 1;
        if (n == 1) return 1;

        // Iteratively compute the sequence
        long a0 = 1; // a(n‑2)
        long a1 = 1; // a(n‑1)
        long a  = 0; // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        // The result fits in an int for reasonable input sizes;
        // cast is safe for the intended constraints.
        return (int) a;
    }
}

