     * includes the letter 'z' (or 'Z') somewhere other than the first or
     * last position of that word; otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern that matches a maximal sequence of letters (a word)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A word of length <=2 cannot have an interior character
            if (word.length() <= 2) {
                continue;
            }

            // Scan interior characters (skip first and last)
            for (int i = 1; i < word.length() - 1; i++) {
                char c = word.charAt(i);
                if (c == 'z' || c == 'Z') {
                    return "Found a match!";
                }
            }
        }

        return "Not matched!";
