            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        // The result fits in an int for the expected range of n
        return (int) a1;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
