class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * character 'z' at a position other than the first or last character
     * of that word.  Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")      → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")    → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split on whitespace – punctuation stays attached to the word
        for (String token : text.split("\\s+")) {
            // Look for any occurrence of 'z' inside the token
            int idx = token.indexOf('z');
            while (idx != -1) {
                // Check that 'z' is not the first nor the last character
                if (idx > 0 && idx < token.length() - 1) {
                    return "Found a match!";
                }
                // Continue searching for other 'z' characters in the same token
                idx = token.indexOf('z', idx + 1);
            }
        }

        // No suitable 'z' was found
        return "Not matched!";
    }

