import java.util.*;

public class Maxaverageofpath {
    /**
     * Returns the maximum average of any path from the top‑left cell to the
     * bottom‑right cell in the given n×n matrix.  Movement is allowed only
     * right or down.
     *
     * @param cost  square matrix of integers (size n×n)
     * @param n     dimension of the matrix
     * @return      maximum average (as a Double)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The number of cells in any such path is always 2*n‑1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        return average;               // auto‑boxed to Double
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

