class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n == 1) return 2;

        long a0 = 1;
        long a1 = 1;
        int count = 0;
        int result = 0;

        while (true) {
            long ai = 2 * a1 + a0;
            if (isPrime(ai)) {
                count++;
                if (count == n - 1) {
                    // Cast to int, assuming it fits
                    @SuppressWarnings("unchecked")
                    int castedResult = (int) ai;
                    result = castedResult;
                    break;
                }
            }
            a0 = a1;
            a1 = ai;
        }
        return result;
    }

    private static boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

