class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")      → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")    → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // \b marks word boundaries; [a-zA-Z]+ matches a sequence of letters.
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A word of length <= 2 can never have a 'z' that is not at
            // the start or the end, so skip such words.
            if (word.length() <= 2) {
                continue;
            }

            // Scan the interior of the word (positions 1 .. length-2).
            for (int i = 1; i < word.length() - 1; i++) {
                if (word.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }

        return "Not matched!";
    }

    // A tiny test driver (optional)
