     */
    public static int countVowels(String testStr) {
        // Null or empty string yields zero
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with lower‑case to treat uppercase letters the same
        String s = testStr.toLowerCase();
        int len = s.length();
