class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2*a(n‑1) + a(n‑2)   for n >= 2
     *
     * Examples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Base cases: a(1) = 1, a(2) = 3
        if (n == 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }

        // Use long to avoid overflow of the intermediate values.
        // The cast to int at the end is safe because the problem
        // constraints guarantee the result fits in an int.
        long a1 = 1;   // a(i‑2)
        long a2 = 3;   // a(i‑1)
        long a  = 0;   // a(i)

        for (int i = 3; i <= n; i++) {
            a = 2 * a2 + a1; // a(i) = 2*a(i‑1) + a(i‑2)
            a1 = a2;
            a2 = a;
        }

        return (int) a2;
    }
}

