        StringBuilder result = new StringBuilder(str1.length() / 2 + 1);

        // Loop over *even* positions (1‑based) → odd indices (0‑based).
        // Starting at index 1 (the 2nd character) and stepping by 2 picks exactly
        // the characters at positions 2, 4, 6, … of the original string.
        for (int i = 1; i < str1.length(); i += 2) {
            result.append(str1.charAt(i));
        }

        return result.toString();
    }
}

