class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the input text contains a word that
     * has the letter 'z' somewhere other than the first or last position.
     * Otherwise it returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") -> "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     -> "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   -> "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // -----------------------------------------------------------------
        // No unchecked warnings are generated by this method.
        // All generic usage (Pattern, Matcher) is fully type‑safe.
        // -----------------------------------------------------------------

        // Pattern that captures contiguous sequences of letters (words).
        // This avoids matching punctuation or whitespace.
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A 'z' can only be "in the middle" if the word is at least 3 characters long.
            if (word.length() >= 3) {
                // Scan only the interior characters (index 1 … length‑2).
                for (int i = 1; i < word.length() - 1; i++) {
                    if (word.charAt(i) == 'z') {
                        // We have found a word with a 'z' that is not at the start or end.
                        return "Found a match!";
                    }
                }
            }
            // If the word is shorter or has no interior 'z', keep searching.
        }

        // No qualifying word was found.
        return "Not matched!";
    }

    // -----------------------------------------------------------------
    // Optional test driver (not required by the problem statement)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));     // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

