class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a monotonic
     * (right‑down only) path from the upper‑left corner to the
     * lower‑right corner of an n×n cost matrix.
     *
     * @param cost  a list of n rows, each row a list of n integers
     * @param n     the dimension of the square matrix (cost.size() == n)
     * @return      the maximum average as a {@code Double};
     *              {@code null} if the input is invalid
     *
     * Example:
     * <pre>
     * List&lt;List&lt;Integer&gt;&gt; mat = Arrays.asList(
     *     Arrays.asList(1,2,3),
     *     Arrays.asList(6,5,4),
     *     Arrays.asList(7,3,9)
     * );
     * Maxaverageofpath.maxaverageofpath(mat, 3); // returns 5.2
     * </pre>
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // dp[i][j] – maximum sum of a monotonic path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        // Initialize the starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                // Safe to unbox Integer → int; the operation is guaranteed
                // to be within bounds because the input matrix is square.
                int cellValue = cost.get(i).get(j);
                dp[i][j] = cellValue + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // A monotonic path from (0,0) to (n‑1,n‑1) visits exactly (2n‑1) cells.
        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2L * n - 1);

        return average;
    }
}

