class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Null or too short strings have no characters with neighbours.
        if (testStr == null || testStr.length() <= 1) {
            return 0;
        }

        // Work with a lower‑case copy for case‑insensitive vowel detection.
        String s = testStr.toLowerCase();
        int count = 0;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            // Consider only consonants (i.e., characters that are NOT vowels).
            if (!isVowel(c)) {
                boolean leftIsVowel  = (i > 0)            && isVowel(s.charAt(i - 1));
                boolean rightIsVowel = (i < s.length() - 1) && isVowel(s.charAt(i + 1));
                if (leftIsVowel || rightIsVowel) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Returns true if ch is one of a, e, i, o, u (case‑insensitive). */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }

    // Optional main method for manual testing
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

