class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper limit n of the series (must be non‑negative)
     * @return the sum of squares from 1 to n
     *
     * Example:
     * <pre>
     * seriesSum(6) → 91
     * seriesSum(7) → 140
     * seriesSum(12) → 650
     * </pre>
     */
    public static int seriesSum(int number) {
        // The closed‑form formula for the sum of squares is n(n+1)(2n+1)/6.
        // Using long arithmetic avoids intermediate overflow for reasonable
        // input values. The final result fits in an int for the expected
        // range of inputs; the cast is therefore safe.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;   // safe: sum is guaranteed to be within int range for valid inputs
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

