class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle base cases
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        if (n == 0) return 1;
        if (n == 1) return 1;

        // Initialize the first two terms
        long a0 = 1;
        long a1 = 1;
        long current = 0;

        // Compute the nth term iteratively
        for (int i = 2; i <= n; i++) {
            current = 2 * a1 + a0;
            a0 = a1;
            a1 = current;
        }

        return (int) current;
    }
}

