class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation -------------------------------------------------
        if (cost == null || n <= 0) {
            return null;
        }
        if (cost.size() < n) {
            return null;
        }
        for (int i = 0; i < n; i++) {
            if (cost.get(i) == null || cost.get(i).size() < n) {
                return null;
            }
        }

        // ---- DP: maximum sum to reach each cell --------------------------------
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // rest of the matrix
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average ---------------------------------------------------
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1);   // exact number of cells visited

        return Double.valueOf(average);
    }

    // ---------------------------------------------------------------------------
    // Optional quick test (can be removed or commented out)
    public static void main(String[] args) {
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

