class CountVowels {

    // Vowel set (both lower‑ and upper‑case)
    private static final Set<Character> VOWELS = Set.of(
            'a', 'e', 'i', 'o', 'u',
            'A', 'E', 'I', 'O', 'U'
    );

    /**
     * Returns the number of characters in the given string that are *not* vowels
     * but have a vowel as an immediate neighbour (left or right).
     *
     * @param testStr the input string
     * @return count of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int n = testStr.length();

        for (int i = 0; i < n; i++) {
            char ch = testStr.charAt(i);

            // We only consider non‑vowel characters
            if (!isVowel(ch)) {
                boolean hasVowelNeighbour = false;

                // check left neighbour
                if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                    hasVowelNeighbour = true;
                }
                // check right neighbour (only if left didn’t already find one)
                if (!hasVowelNeighbour && i < n - 1 && isVowel(testStr.charAt(i + 1))) {
                    hasVowelNeighbour = true;
                }

                if (hasVowelNeighbour) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Helper to test if a character is a vowel. */
    private static boolean isVowel(char ch) {
        return VOWELS.contains(ch);
    }

