import java.util.ArrayList;
import java.util.List;

/**
 * Solution for the “Newman‑Shanks‑Williams prime” problem.
 *
 * The sequence of NSW numbers is defined by:
 *   a0 = 1, a1 = 1
 *   an = 2·a(n‑1) + a(n‑2)   for n ≥ 2
 *
 * The NSW primes are the prime numbers that appear in this sequence,
 * with the extra first prime 2 (which does not arise from the recurrence).
 *
 * The nth NSW prime (1‑based) is returned.
 */
public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     *
     * @param n the index (1‑based) of the desired NSW prime
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Use a List to store the primes we have found (Item 28: prefer lists to arrays)
        List<Integer> primes = new ArrayList<>();
        primes.add(2);               // first NSW prime

        if (n == 1) {
            return primes.get(0);
        }

        // Generate the NSW numbers: a0 = 1, a1 = 1, a2 = 3, …
        long aPrev2 = 1; // a[n‑2]
        long aPrev1 = 1; // a[n‑1]

        // Keep generating until we have collected n primes
        while (primes.size() < n) {
            long current = 2 * aPrev1 + aPrev2; // a[n]

            if (isPrime(current)) {
                // The result is guaranteed to fit into int for the expected input range.
                // If it didn’t, we would need BigInteger, but the problem specifies int return.
                primes.add((int) current);
            }

            // Shift the window forward
            aPrev2 = aPrev1;
            aPrev1 = current;
        }

        return primes.get(n - 1);
    }

    /**
     * Simple trial‑division primality test suitable for the relatively small
     * numbers we encounter (the NSW primes grow quickly).
     */
    private static boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num <= 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }
        // Check factors of the form 6k ± 1 up to √num
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    // -----------------------------------------------------------------------
    // Optional test driver (can be removed when integrating into a larger project)
    public static void main(String[] args) {
        // Provided examples
        System.out.println("newmanPrime(3) = " + newmanPrime(3)); // 7
        System.out.println("newmanPrime(4) = " + newmanPrime(4)); // 17
        System.out.println("newmanPrime(5) = " + newmanPrime(5)); // 41

        // A few more terms to illustrate correctness
        for (int i = 1; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

