class TextMatchWordzMiddle {

    // Pre‑compiled pattern that matches a word: one or more ASCII letters.
    private static final Pattern WORD_PATTERN = Pattern.compile("[A-Za-z]+");

    /**
     * Returns "Found a match!" if the supplied text contains a word that has the
     * letter 'z' (or 'Z') somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     *
     * @param text the input string to examine
