class CountVowels {
    // Using a Set (a collection) for O(1) vowel look‑ups – no raw arrays needed.
    private static final Set<Character> VOWELS = Set.of(
            'a', 'e', 'i', 'o', 'u',
            'A', 'E', 'I', 'O', 'U'
    );

    /**
     * Counts characters (consonants) that have a vowel as one of their neighbours.
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only count consonants; skip vowels themselves.
            if (VOWELS.contains(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check the left neighbour.
            if (i > 0 && VOWELS.contains(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }

            // Check the right neighbour.
            if (i < len - 1 && VOWELS.contains(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

