class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2*a(n‑1) + a(n‑2)  for n >= 2.
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        // Guard against negative indices
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The first two terms are both 1
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iterate using long to avoid intermediate overflow
        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a  = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // compute a(i)
            a0 = a1;         // shift for next iteration
            a1 = a;
        }

        // The result fits in an int for the expected small values of n
        return (int) a;
    }
}

