public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path from the top‑left to the bottom‑right
     * of an n×n cost matrix. Movement is restricted to right or down steps.
     *
     * @param cost  a square list of lists of integers (n×n)
     * @param n     the dimension of the matrix
     * @return      the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP[i][j] = maximum sum to reach cell (i, j) from (0,0)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);
        return average;
    }

