class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle base cases
        if (n <= 0) {
            // For n <= 0, return 1 as the sequence starts at index 0 with 1.
            return 1;
        }
        if (n == 1) {
            return 1;
        }
        // Use long to avoid overflow for moderate n
        long prev2 = 1; // s_{i-2}
        long prev1 = 1; // s_{i-1}
        long current = 0;
        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        return (int) current;
    }

    // Optional main method for testing
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

