import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum possible average of a monotonic path
     * (right‑ or down‑ moves only) from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost  a list of n rows, each row a list of n integers
     * @param n     size of the square matrix
     * @return      the highest average (as a Double) or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // ---- DP table: maximum sum to reach each cell -------------------------
        // Using List<List<Double>> instead of a raw array to stay type‑safe.
        List<List<Double>> dp = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            List<Double> row = new ArrayList<>(n);
            for (int j = 0; j < n; j++) {
                row.add(0.0);
            }
            dp.add(row);
        }

        // ---- base case ---------------------------------------------------------
        dp.get(0).set(0, cost.get(0).get(0).doubleValue());

        // ---- first row (can only come from the left) -------------------------
        for (int j = 1; j < n; j++) {
            dp.get(0).set(j, dp.get(0).get(j - 1) + cost.get(0).get(j).doubleValue());
        }

        // ---- first column (can only come from above) -------------------------
        for (int i = 1; i < n; i++) {
            dp.get(i).set(0, dp.get(i - 1).get(0) + cost.get(i).get(0).doubleValue());
        }

        // ---- fill the rest of the table ---------------------------------------
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                double bestFromAboveOrLeft = Math.max(dp.get(i - 1).get(j), dp.get(i).get(j - 1));
                dp.get(i).set(j, bestFromAboveOrLeft + cost.get(i).get(j).doubleValue());
            }
        }

        // ---- compute the average -----------------------------------------------
        // Every monotonic path from (0,0) to (n‑1,n‑1) visits exactly (2*n‑1) cells.
        double maxSum = dp.get(n - 1).get(n - 1);
        double average = maxSum / (2.0 * n - 1);
        return average;
    }

    // -----------------------------------------------------------------------
    // Optional test driver (feel free to remove or comment out in production)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

