public class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The definition is:
     *   a0 = 1, a1 = 1
     *   an = 2·a(n‑1) + a(n‑2)  (n ≥ 2)
     *
     * For the first few indices (n ≥ 2) the value is prime,
     * which is why the sequence is commonly referred to as the
     * Newman‑Shanks‑Williams primes.
     *
     * @param n index of the required term (0‑based)
     * @return the n‑th NSW number
     */
    public static int newmanPrime(int n) {
        // a(0) = a(1) = 1
        if (n <= 1) {
            return 1;
        }

        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long cur = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            cur = 2 * a1 + a0; // recurrence
            a0 = a1;
            a1 = cur;
        }

        // The problem expects an int; the values for the given test
        // cases fit into an int.
        return (int) cur;
    }

    // Simple manual test (not part of the required solution)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

