class TextMatchWordzMiddle {

    /**
     * Write a function that matches a word containing 'z',
     * not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches a word consisting only of letters (a‑z or A‑Z)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            if (hasMiddleZ(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * Returns true if the given word contains the letter 'z'
     * (either lower‑case or upper‑case) at a position other than
     * the first or the last character.
     */
    private static boolean hasMiddleZ(String word) {
        int len = word.length();
        // A word shorter than 3 characters can never have a middle character
        if (len <= 2) {
            return false;
        }
        // Scan only the interior of the word (skip first and last)
        for (int i = 1; i < len - 1; i++) {
            char c = word.charAt(i);
            if (c == 'z' || c == 'Z') {
                return true;
            }
        }
        return false;
    }

    // --------------------------------------------------------------------
    // Optional quick‑test driver
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!
    }
}

