class Maxaverageofpath {
    /**
     * Find a path with the maximum average over all existing paths for the given
     * square matrix of size n × n. Movement is allowed only to the right or down.
     *
     * @param cost the n × n matrix of integers
     * @param n    the dimension of the square matrix
     * @return the maximum average of any valid path, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against bad input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // The path length is always (2*n - 1) because we must make (n‑1) right moves
        // and (n‑1) down moves, visiting (2*n - 1) cells in total.
        final int pathLen = 2 * n - 1;

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Initialise the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The best sum is stored at the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // Convert the sum to the average (as a Double)
        return maxSum / pathLen;
    }

    // --------------------------------------------------------------------
    // Optional test driver (feel free to remove or adapt)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // Expected: 7.2
    }
}

