public static int newmanPrime(int n) {
    // Handle negative input
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }

    // Base cases: s0 = 1, s1 = 1
    if (n == 0 || n == 1) {
        return 1;
    }

    // Compute the sequence iteratively using long to avoid overflow
    long prev2 = 1; // s_{i‑2}
    long prev1 = 1; // s_{i‑1}
    long current = 0;

    for (int i = 2; i <= n; i++) {
        // s_i = 2 * s_{i‑1} + s_{i‑2}
        current = 2 * prev1 + prev2;
        // Shift the window
        prev2 = prev1;
        prev1 = current;
    }

    // The returned value fits in an int for the expected range of n
    return (int) current;
}

