import java.util.ArrayList;
import java.util.List;

public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     * The sequence of NSW primes begins: 2, 3, 7, 17, 41, 239, 577, …
     *
     * @param n 1‑based index of the desired NSW prime (n >= 1)
     * @return the n‑th NSW prime
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            return 0;                 // undefined for non‑positive n
        }

        // List to hold the NSW primes we have found so far
        List<Long> primes = new ArrayList<>();
        primes.add(2L);               // the first NSW prime by definition

        // initialise the recurrence a0 = 1, a1 = 1
        long a0 = 1;
        long a1 = 1;

        // generate the sequence until we have n primes
        while (primes.size() < n) {
            // compute the next term: a = 2*a1 + a0
            long a = 2 * a1 + a0;

            // if it is prime, add it to our list
            if (isPrime(a)) {
                primes.add(a);
            }

            // shift the window for the next iteration
            a0 = a1;
            a1 = a;
        }

        // the list is 0‑based, so return the (n‑1)‑th element
        return primes.get(n - 1).intValue();
    }

    /**
     * Simple deterministic primality test for numbers that fit in a long.
     * Sufficient for the small n values typical of this problem.
     */
    private static boolean isPrime(long x) {
        if (x < 2) {
            return false;
        }
        if (x == 2) {
            return true;
        }
        if (x % 2 == 0) {
            return false;
        }
        // trial division by odd numbers up to sqrt(x)
        for (long i = 3; i * i <= x; i += 2) {
            if (x % i == 0) {
                return false;
            }
        }
        return true;
    }
}

