public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that travels from the
     * top‑left to the bottom‑right of the given n×n matrix, moving only
     * right or down.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     the dimension of the square matrix
     * @return      the maximum average (as a Double) over all valid paths
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First column: can only come from the cell above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // First row: can only come from the cell on the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // The length of any top‑left → bottom‑right path is 2·n‑1 cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

