public class TextMatchWordzMiddle {
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }
        // \b marks word boundary; [A-Za-z]+ matches one or more letters
        Pattern wordPattern = Pattern.compile("\\b[A-Za-z]+\\b");
        Matcher matcher = wordPattern.matcher(text);
        while (matcher.find()) {
            String word = matcher.group();
            int len = word.length();
            // Need at least 3 characters to have a middle position
            if (len < 3) {
                continue;
            }
            // Check each character except the first and last for 'z'
            for (int i = 1; i < len - 1; i++) {
                if (word.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }
}

