public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that travels from the top‑left
     * corner to the bottom‑right corner of the given n×n matrix.
     * Movement is restricted to steps to the right or down.
     *
     * @param cost the n×n matrix of integer costs (List of List of Integer)
     * @param n    the dimension of the square matrix
     * @return the highest possible average (as a Double)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] – maximum sum of a path that ends at row i, column j
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                long bestFromAboveOrLeft = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = bestFromAboveOrLeft + cost.get(i).get(j);
            }
        }

        // The best sum ends at the bottom‑right corner
        long maxSum = dp[n - 1][n - 1];

        // All paths have exactly (2 * n - 1) cells, so average = sum / (2n‑1)
        double average = (double) maxSum / (2 * n - 1);

        return average;
    }

