class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // The first two terms of the NSW sequence are 1, 1
        if (n <= 0) return 1;   // a0
        if (n == 1) return 1;   // a1

        long prev2 = 1; // a_{i-2}
        long prev1 = 1; // a_{i-1}
        long cur = 0;   // a_i

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2; // recurrence: a_i = 2*a_{i-1} + a_{i-2}
            prev2 = prev1;
            prev1 = cur;
        }
        // The result fits in an int for the typical test range; 
        // for larger n you could switch to long or BigInteger.
        return (int) cur;
    }
}

