class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a0 = 1
     *   a1 = 3
     *   an = 2 * a(n‑1) + a(n‑2)   for n >= 2
     *
     * @param n the 1‑based index (must be > 0)
     * @return the n‑th term of the sequence
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // base cases
        if (n == 1) return 1;   // a0
        if (n == 2) return 3;   // a1

        // use long to avoid overflow of the intermediate result
        long prev2 = 1L; // a0
        long prev1 = 3L; // a1
        long cur   = 0L; // an

        // compute a2 … an
        for (int i = 3; i <= n; i++) {
            cur = 2 * prev1 + prev2; // an = 2*a(n‑1) + a(n‑2)
            prev2 = prev1;
            prev1 = cur;
        }

        // the result always fits in int for the expected small n values
        return (int) prev1;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example calls from the problem statement
        System.out.println("newmanPrime(3) = " + newmanPrime(3)); // 7
        System.out.println("newmanPrime(4) = " + newmanPrime(4)); // 17
        System.out.println("newmanPrime(5) = " + newmanPrime(5)); // 41
    }
}

