    /**
     * Finds a path with the maximum average over all existing paths for the given
     * square matrix of size n*n.
     *
     * A path may only move right or down, starting at (0,0) and ending at (n‑1,n‑1).
     * The average of a path = (sum of the cell values) / (2*n - 1).
     *
     * @param cost the n×n matrix of integers
     * @param n    the dimension of the matrix
     * @return the maximum possible average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] holds the maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum到达终点 (n‑1, n‑1)
        double maxSum = dp[n - 1][n - 1];

        // Every monotone path contains exactly (2*n‑1) cells
        double average = maxSum / (2.0 * n - 1);

        // Return as a boxed Double
        return average;
    }

