import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     *
     * The NSW numbers are defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(k) = 2·a(k‑1) + a(k‑2)   for k ≥ 2.
     * The NSW primes are the prime numbers that appear in this sequence.
     *
     * The mapping used here is:
     *   n = 1 or 2 → 3 (the first NSW prime)
     *   n ≥ 3      → the (n‑2)-th NSW prime (0‑based index)
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // The first two NSW primes are both 3 (a(2) = 3)
        if (n == 1 || n == 2) {
            return 3;
        }

        // Collect NSW primes until we have at least (n‑1) of them
        List<Integer> nswPrimes = new ArrayList<>();

        long a0 = 1; // a(0)
        long a1 = 1; // a(1)

        // Generate NSW numbers starting from index 2
        for (long i = 2; ; i++) {
            long a2 = 2 * a1 + a0; // a(i) = 2·a(i‑1) + a(i‑2)

            if (isPrime(a2)) {
                nswPrimes.add((int) a2);
            }

            // Shift the window forward
            a0 = a1;
            a1 = a2;

            // We need the (n‑2)-th prime (0‑based), i.e. at least n‑1 primes
            if (nswPrimes.size() >= n - 1) {
                break;
            }
        }

        // Return the (n‑2)-th prime (0‑based index)
        return nswPrimes.get(n - 2);
    }

    /** Simple deterministic primality test for numbers that fit in a 32‑bit int. */
    private static boolean isPrime(long n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;

        // Check factors of the form 6k ± 1 up to √n
        for (long i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}

