/**
 * Demonstrates a simple word‑by‑word scan to find a 'z' that is
 * not at the start or the end of a word.
 */
class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains
     * the letter 'z' (or 'Z') at a position other than the first or last
     * character of that word; otherwise returns "Not matched!".
     *
     * @param text the input string (may contain spaces, punctuation, etc.)
     * @return    the appropriate message
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        StringBuilder currentWord = new StringBuilder();

        // Scan the whole string, treating any non‑letter as a delimiter
        for (int i = 0; i <= text.length(); i++) {
            char ch = (i < text.length()) ? text.charAt(i) : ' '; // sentinel delimiter at the end

            if (Character.isLetter(ch)) {
                currentWord.append(ch);
            } else {
                // We have reached the end of a word (or the string)
                if (currentWord.length() > 0) {
                    if (containsZNotAtEdges(currentWord.toString())) {
                        return "Found a match!";
                    }
                    // Reset for the next word
                    currentWord.setLength(0);
                }
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

    /**
     * Helper that checks whether the given word contains 'z' (or 'Z')
     * at a position that is neither the first nor the last character.
     *
     * @param word a non‑empty word consisting only of letters
     * @return true if the condition is met, false otherwise
     */
    private static boolean containsZNotAtEdges(String word) {
        // Look for 'z' or 'Z'
        int idx = word.indexOf('z');
        if (idx == -1) {
            idx = word.indexOf('Z');
        }
        // No 'z' at all → not a match
        if (idx == -1) {
            return false;
        }
        // 'z' must not be the first or the last character
        return idx > 0 && idx < word.length() - 1;
    }

    // -----------------------------------------------------------------
    // Optional test driver (not required by the problem statement)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        String[] tests = {
            "pythonzabc.",
            "xyzabc.",
            "  lang  .",
            "The quick brown fox jumps over the lazy dog.",
            "zebra",
            "azbzc",
            "noZhere",
            "Zany",
            "   zyzz   "
        };

        for (String t : tests) {
            System.out.println("Input : \"" + t + "\"");
            System.out.println("Output: " + textMatchWordzMiddle(t));
            System.out.println();
        }
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a monotonic (right/down) path
     * from the top‑left corner to the bottom‑right corner of the
     * given n×n cost matrix.
     *
     * @param cost  list of rows, each row a list of integers
     * @param n     size of the square matrix
     * @return      maximum average as a Double, or null for invalid input
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = best sum to reach (i, j)
        double[][] dp = new double[n][n];

        // Initialize start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Maximum sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // All monotonic paths have exactly (2*n - 1) cells
        double average = maxSum / (2 * n - 1);

        return average;
    }
}

class CountVowels {
    /** 
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set (both lower‑ and upper‑case)
        final String VOWELS = "aeiouAEIOU";

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only count consonants that are next to a vowel
            if (VOWELS.indexOf(ch) >= 0) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbor
            if (i > 0 && VOWELS.indexOf(testStr.charAt(i - 1)) >= 0) {
                hasVowelNeighbor = true;
            }
            // Check right neighbor (only if left wasn’t a vowel)
            else if (i < len - 1 && VOWELS.indexOf(testStr.charAt(i + 1)) >= 0) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Optional simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend"));// 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

