public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that starts at the
     * top‑left cell (0,0) and ends at the bottom‑right cell (n‑1,n‑1)
     * while moving only right or down.
     *
     * @param cost  square matrix of size n×n (list of rows)
     * @param n     dimension of the matrix
     * @return      the highest possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation – adjust according to your needs
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] holds the maximum sum to reach cell (i,j)
        long[][] dp = new long[n][n];

        // First cell (0,0)
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                long best = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = cost.get(i).get(j) + best;
            }
        }

        // The path always contains exactly (2*n - 1) cells
        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);

        return average;
    }

    // --------------------------------------------------------------------
    // Optional test driver (feel free to remove / adapt)
    // --------------------------------------------------------------------
