            char cur = testStr.charAt(i);
            char curLower = Character.toLowerCase(cur);

            // We only count non‑vowel characters
            if (!VOWELS.contains(curLower)) {
                boolean hasVowelNeighbor = false;

                // check left neighbour
                if (i - 1 >= 0) {
                    char left = Character.toLowerCase(testStr.charAt(i - 1));
                    if (VOWELS.contains(left)) {
                        hasVowelNeighbor = true;
                    }
                }

                // check right neighbour if we haven't found a vowel yet
                if (!hasVowelNeighbor && i + 1 < testStr.length()) {
                    char right = Character.toLowerCase(testStr.charAt(i + 1));
                    if (VOWELS.contains(right)) {
                        hasVowelNeighbor = true;
                    }
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));       // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
