class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * For n >= 2 the term is a prime (e.g. newmanPrime(3) == 7,
     * newmanPrime(4) == 17, newmanPrime(5) == 41).
     *
     * @param n index in the sequence (0‑based)
     * @return the value s[n]
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // s[0] = 1, s[1] = 1
        if (n == 0) return 1;
        if (n == 1) return 1;

        long prev2 = 1; // s[i‑2]
        long prev1 = 1; // s[i‑1]
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // s[i] = 2*s[i‑1] + s[i‑2]
            prev2 = prev1;
            prev1 = current;
        }

        // The values fit in int for reasonable n (≈ n ≤ 45);
        // cast is safe for the problem’s constraints.
        return (int) current;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

