import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all paths that go from the top‑left
     * corner to the bottom‑right corner of the given n×n cost matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost  list of rows, each row a list of integers representing cell costs
     * @param n     size of the square matrix (number of rows/columns)
     * @return      the maximal average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation ------------------------------------------------
        if (cost == null || n <= 0 || cost.size() != n) {
            throw new IllegalArgumentException("Invalid matrix dimensions");
        }
        for (List<Integer> row : cost) {
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Invalid matrix dimensions");
            }
        }

        // ---- DP: maximal sum to each cell ------------------------------------
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                long cell = cost.get(i).get(j).longValue();

                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = cell;
                } else {
                    long bestFromAbove = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                    long bestFromLeft = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;
                    dp[i][j] = cell + Math.max(bestFromAbove, bestFromLeft);
                }
            }
        }

        // ---- compute average -------------------------------------------------
        long maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;                 // number of cells visited
        double average = (double) maxSum / pathLength;

        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------------
    // Example usage (can be removed when integrating into a larger codebase)
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

