public static int newmanPrime(int n) {
    // The NSW sequence is defined as:
    // a0 = 1, a1 = 1
    // a_i = 2 * a_{i-1} + a_{i-2}  for i >= 2
    if (n <= 0) return 1;   // a0
    if (n == 1) return 1;  // a1

    int aPrev2 = 1; // a_{i-2}
    int aPrev1 = 1; // a_{i-1}
    int aCurr = 0;  // a_i

    for (int i = 2; i <= n; i++) {
        aCurr = 2 * aPrev1 + aPrev2; // a_i = 2*a_{i-1} + a_{i-2}
        // shift the window for the next iteration
        aPrev2 = aPrev1;
        aPrev1 = aCurr;
    }
    return aCurr;
}

