public class Maxaverageofpath {
    /**
     * Returns the maximum average of a path from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix. Movement is allowed
     * only to the right or down.
     *
     * @param cost n×n list of lists containing the cell costs
     * @param n    size of the matrix (number of rows/columns)
     * @return     the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] holds the maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cur = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = cur;
                } else {
                    double bestPrev = 0;
                    if (i == 0) {
                        bestPrev = dp[0][j - 1];
                    } else if (j == 0) {
                        bestPrev = dp[i - 1][0];
                    } else {
                        bestPrev = Math.max(dp[i - 1][j], dp[i][j - 1]);
                    }
                    dp[i][j] = cur + bestPrev;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // Every path from (0,0) to (n-1,n-1) contains exactly (2*n - 1) cells
        double average = maxSum / (2 * n - 1);
        return Double.valueOf(average);
    }
}

