class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle invalid input
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // Base cases
        if (n == 1) return 1;
        if (n == 2) return 3;

        // Compute NSW numbers iteratively
        long a1 = 1; // a(n-2)
        long a2 = 3; // a(n-1)
        long a = 0;  // a(n)

        for (int i = 3; i <= n; i++) {
            a = 2 * a2 + a1;
            a1 = a2;
            a2 = a;
        }

        return (int) a;
    }
}

