import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.math.BigInteger;

/**
 *  Helper class that generates the Newman‑Shanks‑Williams (NSW) sequence
 *  and extracts the primes from it.
 *
 *  The NSW sequence is defined by:
 *      s0 = 1, s1 = 1
 *      sn = 2·s(n‑1) + s(n‑2)   for n ≥ 2
 *
 *  The NSW primes are those sn that are prime.
 */
public class NewmanPrime {

    /** Cache of the NSW numbers (s0, s1, …). */
    private static final List<BigInteger> nswNumbers = new ArrayList<>();

    /** Cache of the NSW primes (the primes among the NSW numbers). */
    private static final List<BigInteger> nswPrimes = new ArrayList<>();

    static {
        // seed the sequence with s0 and s1
        nswNumbers.add(BigInteger.ONE);   // s0
        nswNumbers.add(BigInteger.ONE);   // s1
    }

    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime (1‑based).
     *
     * @param n the index of the required NSW prime (n ≥ 1)
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // Make sure we have generated at least n primes
        generatePrimesUpTo(n);
        // The list is 0‑based, so the n‑th prime is at position n‑1
        return nswPrimes.get(n - 1).intValueExact();
    }

    /**
     * Generates NSW numbers and records the primes until we have at least
     * {@code count} primes in the cache.
     *
     * @param count the desired number of primes
     */
    private static void generatePrimesUpTo(int count) {
        while (nswPrimes.size() < count) {
            // Compute the next NSW number: sn = 2·s(n‑1) + s(n‑2)
            int nextIdx = nswNumbers.size();
            BigInteger sPrev = nswNumbers.get(nextIdx - 1);
            BigInteger sPrev2 = nswNumbers.get(nextIdx - 2);
            BigInteger sNext = sPrev.multiply(BigInteger.TWO).add(sPrev2);
            nswNumbers.add(sNext);

            // Probabilistic primality test – more than enough for these sizes
            if (sNext.isProbablePrime(20)) {
                nswPrimes.add(sNext);
            }
        }
    }

    /**
     * Utility method that collects the first {@code count} NSW primes into
     * any collection that can hold {@code Integer} values.  This demonstrates
     * the use of a bounded wildcard (consumer‑super) as recommended by the
     * PECS mnemonic.
     *
     * @param count      number of primes to collect
     * @param collection a consumer collection that accepts {@code Integer}
     *                   (e.g. {@code List<Integer>} or {@code Set<Integer>})
     */
    public static void collectNewmanPrimes(int count,
                                           Collection<? super Integer> collection) {
        // Ensure we have generated enough primes
        generatePrimesUpTo(count);
        for (int i = 0; i < count; i++) {
            collection.add(nswPrimes.get(i).intValueExact());
        }
    }

    // -----------------------------------------------------------------------
    // A tiny demo / quick test (feel free to remove or comment out)
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        for (int i = 1; i <= 10; i++) {
            System.out.printf("newmanPrime(%d) = %d%n", i, newmanPrime(i));
        }
        // Example using the wildcard‑based collector:
        List<Integer> dest = new ArrayList<>();
        collectNewmanPrimes(5, dest);
        System.out.println("First 5 NSW primes (via collector): " + dest);
    }
}

