import java.util.regex.*;

public class TextMatchWordzMiddle {

    /**
     * Determines whether any word in the given text contains the letter 'z'
     * that is *not* the first or the last character of that word.
     *
     * @param text the input string to be examined
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")    → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")  → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // \b = word boundary, \w+ = one or more word characters (letters, digits, underscore)
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();           // the actual word text
            String lower = word.toLowerCase();       // case‑insensitive check

            // A word must be at least two characters long to have a “middle” character
            if (lower.length() >= 2
                    && lower.contains("z")
                    && !lower.startsWith("z")
                    && !lower.endsWith("z")) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // Simple manual test harness
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a monotonic path
     * (right / down moves only) from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost square matrix of integers
     * @param n    dimension of the matrix (must be cost.size())
     * @return maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[j] – best sum to reach cell (current row, column j)
        double[] dp = new double[n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cur = cost.get(i).get(j);          // value in current cell

                if (i == 0 && j == 0) {                // start cell
                    dp[j] = cur;
                } else {
                    double fromTop  = (i > 0) ? dp[j] : Double.NEGATIVE_INFINITY;
                    double fromLeft = (j > 0) ? dp[j - 1] : Double.NEGATIVE_INFINITY;
                    dp[j] = cur + Math.max(fromTop, fromLeft);
                }
            }
        }

        double maxSum = dp[n - 1];
        // denominator = number of cells on any monotonic path = 2*n - 1
        double average = maxSum / (2L * n - 1);
        return average;
    }
}

