import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all paths that start at the
     * top‑left corner, end at the bottom‑right corner, and move only right
     * or down.
     *
     * @param cost square matrix (n × n) of non‑negative integers
     * @param n    size of the matrix
     * @return     maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table holds the maximum sum reachable at each cell.
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first column (can only come from the cell above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the first row (can only come from the cell on the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Remaining cells: take the better of the two predecessors and add current cost
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The best sum for a complete path
        long maxSum = dp[n - 1][n - 1];

        // Every monotonic path has exactly (2*n‑1) cells, so the average is:
        double average = (double) maxSum / (2 * n - 1);

        return Double.valueOf(average);
    }
}

