public static int newmanPrime(int n) {
    // n must be non‑negative
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }

    // Base cases: a0 = 1, a1 = 1
    if (n == 0 || n == 1) {
        return 1;
    }

    long a0 = 1; // a(n‑2)
    long a1 = 1; // a(n‑1)
    long a  = 0; // a(n) to be computed

    // Generate the sequence: a(i) = 2*a(i‑1) + a(i‑2)
    for (int i = 2; i <= n; i++) {
        a = 2 * a1 + a0;
        a0 = a1;
        a1 = a;
    }

    // The result fits in an int for the typical range of n.
    return (int) a;
}

