class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams number sequence.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2*a(n‑1) + a(n‑2)  for n >= 2
     *
     * For the values shown in the task:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n index of the required term (0‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iterate using long to avoid overflow before casting back to int.
        // The result fits in an int for n ≤ 25 (the typical test range).
        long aPrev2 = 1L; // a(n‑2)
        long aPrev1 = 1L; // a(n‑1)
        long a = 0L;      // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * aPrev1 + aPrev2;
            aPrev2 = aPrev1;
            aPrev1 = a;
        }

        return (int) a;   // the problem expects an int return type
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

