class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // -----------------------------------------------------------------
        // 1. Extract all words (sequences of letters) from the input text.
        // -----------------------------------------------------------------
        List<String> words = new ArrayList<>();
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);
        while (matcher.find()) {
            words.add(matcher.group());
        }

        // -----------------------------------------------------------------
        // 2. Use the wildcard‑based public helper (captures the list type)
        //    and the generic private helper to perform the actual check.
        // -----------------------------------------------------------------
        boolean found = containsMiddleZ(words);

        return found ? "Found a match!" : "Not matched!";
    }

    // -----------------------------------------------------------------
    // Public wrapper that uses a bounded wildcard (List<?>).
    // -----------------------------------------------------------------
    private static boolean containsMiddleZ(List<?> list) {
        // Delegate to the generic helper that captures the wildcard.
        return containsMiddleZHelper(list);
    }

    // -----------------------------------------------------------------
    // Generic helper method – it “captures” the wildcard type, allowing
    // us to treat the list elements uniformly.
    // -----------------------------------------------------------------
    private static <E> boolean containsMiddleZHelper(List<E> list) {
        for (E element : list) {
            String word = element.toString();
            if (hasMiddleZ(word)) {
                return true;
            }
        }
        return false;
    }

    // -----------------------------------------------------------------
    // Helper that determines whether a given word contains the letter
    // 'z' (or 'Z') somewhere other than the first or last position.
    // -----------------------------------------------------------------
    private static boolean hasMiddleZ(String word) {
        // A word shorter than 3 characters cannot have a middle 'z'.
        if (word.length() < 3) {
            return false;
        }
        // Perform a case‑insensitive check.
        String lower = word.toLowerCase();
        // Scan only the interior characters (index 1 … length‑2).
        for (int i = 1; i < lower.length() - 1; i++) {
            if (lower.charAt(i) == 'z') {
                return true;
            }
        }
        return false;
    }

    // -----------------------------------------------------------------
    // Optional quick test driver.
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!
    }
}

