class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that
     * starts at the top‑left corner of the square matrix `cost`
     * and ends at the bottom‑right corner, moving only right or down.
     *
     * @param cost a square matrix (List of rows) of integers
     * @param n    size of the matrix (n × n)
     * @return the maximal average (rounded to one decimal place)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] – maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // All paths have exactly (2*n - 1) cells (including start and end)
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        // Round to one decimal place to match the examples
        average = Math.round(average * 10.0) / 10.0;

        return average;
    }

    // Optional test driver
    public static void main(String[] args) {
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
