        }

        // Generate the Newman‑Shanks‑Williams sequence:
        // s0 = 1, s1 = 1, si = 2*si‑1 + si‑2
        BigInteger prev2 = BigInteger.ONE; // s_{i‑2}
        BigInteger prev1 = BigInteger.ONE; // s_{i‑1}
        int primeCount = 1;                // we already have the prime 2
        BigInteger current = null;

        for (int i = 2; ; i++) {
            current = prev1.multiply(BigInteger.valueOf(2)).add(prev2); // s_i

            if (isPrime(current)) {
                primeCount++;
                if (primeCount == n) {
                    // The result is assumed to fit in an int (n is small in practice)
                    return current.intValue();
                }
            }

            // Shift the window for the next iteration
            prev2 = prev1;
            prev1 = current;
        }
    }

    /** Simple primality test using BigInteger's probabilistic Miller‑Rabin. */
    private static boolean isPrime(BigInteger n) {
        if (n.compareTo(BigInteger.ONE) <= 0) {
            return false;
        }
        // Handle small primes explicitly for speed
        if (n.equals(BigInteger.valueOf(2)) || n.equals(BigInteger.valueOf(3))) {
            return true;
        }
        // Eliminate multiples of 2 and 3 early
        if (n.mod(BigInteger.valueOf(2)).equals(BigInteger.ZERO) ||
            n.mod(BigInteger.valueOf(3)).equals(BigInteger.ZERO)) {
            return false;
        }
        // Use a deterministic‑enough Miller‑Rabin with high certainty
        return n.isProbablePrime(100);
    }
}

