public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     *
     * @param text the input text to examine
     * @return    the appropriate result string
     */
    public static String textMatchWordzMiddle(String text) {
        // Defensive check – not strictly required by the spec but good practice
        if (text == null) {
            return "Not matched!";
        }

        // Pattern that matches a sequence of letters (a “word”)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A 'z' can only be “in the middle” if the word is at least 3 characters long
            if (word.length() >= 3) {
                // Scan characters from index 1 up to length‑2 (inclusive)
                for (int i = 1; i < word.length() - 1; i++) {
                    if (word.charAt(i) == 'z') {
                        return "Found a match!";
                    }
                }
            }
        }

        return "Not matched!";
    }

