class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams number sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2*a(n‑1) + a(n‑2)  for n > 1.
     *
     * The values produced for n = 2,3,4,… are 3,7,17,41,… which are the
     * primes referred to in the problem statement.
     *
     * @param n the index of the desired term (0‑based)
     * @return the value a(n)
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a  = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence relation
            a0 = a1;
            a1 = a;
        }

        // The problem expects an int return type; the values fit in int
        // for the typical test range (n ≤ 25).  For larger n, long could
        // be returned, but the signature is int.
        return (int) a;
    }
}

