public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    if (cost == null || cost.isEmpty() || n <= 0) {
        return 0.0;
    }

    // Create DP table
    double[][] dp = new double[n][n];

    // Initialize
    dp[0][0] = cost.get(0).get(0);

    // First row
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j-1] + cost.get(0).get(j);
    }

    // First column
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i-1][0] + cost.get(i).get(0);
    }

    // Fill the rest
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i-1][j], dp[i][j-1]);
        }
    }

    // Maximum sum is dp[n-1][n-1]
    // Number of cells in path is 2*n - 1
    double maxSum = dp[n-1][n-1];
    double pathLength = 2 * n - 1;

    return maxSum / pathLength;
}

public static int countVowels(String testStr) {
    // Guard against null or empty input
    if (testStr == null || testStr.isEmpty()) {
        return 0;
    }

    // Work in lower‑case to handle uppercase letters as well
    String s = testStr.toLowerCase();
    int count = 0;

    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);

        // Skip the vowel characters themselves – we only count consonants
        if (isVowel(ch)) {
            continue;
        }

        // Check whether there is a vowel to the left or to the right
        boolean hasVowelNeighbor = (i > 0 && isVowel(s.charAt(i - 1))) ||
                                   (i < s.length() - 1 && isVowel(s.charAt(i + 1)));

        if (hasVowelNeighbor) {
            count++;
        }
    }
    return count;
}

