class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n of the series (must be non‑negative)
     * @return the sum of squares from 1 to number
     *
     * Example:
     * <pre>
     * seriesSum(6)  // returns 91
     * seriesSum(7)  // returns 140
     * seriesSum(12) // returns 650
     * </pre>
     */
    public static int seriesSum(int number) {
        // Guard against negative input – the series is empty for n <= 0.
        if (number <= 0) {
            return 0;
        }

        // Use the formula n * (n + 1) * (2n + 1) / 6.
        // All intermediate values are promoted to long to prevent overflow.
        long n = number;
        long sum = n * (n + 1) * (2L * n + 1) / 6;

        // The result fits in an int for typical values of n; cast back.
        return (int) sum;
    }

    // A simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12)); // 650
    }
}

