class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * For n >= 2 this value is always a prime (3, 7, 17, 41, …).
     *
     * @param n the index (1‑based) in the Newman‑Shanks‑Williams sequence
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // The first two values of the sequence are 1, 1
        if (n == 1) {
            return 1;               // not a prime, but fits the recurrence
        }
        long prev2 = 1; // a_{i-2}
        long prev1 = 1; // a_{i-1}
        long cur = 1;   // a_i

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2; // a_i = 2*a_{i-1} + a_{i-2}
            prev2 = prev1;
            prev1 = cur;
        }
        return (int) cur; // the problem expects int, and n is small enough
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

