class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms (n)
     * @return the sum of squares of the first 'number' natural numbers
     */
    public static int seriesSum(int number) {
        // Use the formula: n * (n + 1) * (2n + 1) / 6
        long n = number;                     // promote to long to avoid overflow in the intermediate products
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;                     // the problem guarantees the result fits in an int
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

