import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // The recurrence: a0 = 1, a1 = 1, a_n = 2*a_{n-1} + a_{n-2}
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the base cases
        if (n == 0) return 1; // a0
        if (n == 1) return 1; // a1

        long a0 = 1; // a_{i-2}
        long a1 = 1; // a_{i-1}
        long current = 0; // a_i

        for (int i = 2; i <= n; i++) {
            current = 2 * a1 + a0; // a_i = 2*a_{i-1} + a_{i-2}
            a0 = a1;
            a1 = current;
        }

        // The problem’s examples expect the term itself, not a prime‑filtering index.
        // The result fits in an int for reasonable input values.
        return (int) current;
    }
}

