import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class TextMatchWordzMiddle {

    /**
     * Checks whether the given text contains a word that has the letter 'z'
     * somewhere other than the first or last position.
     *
     * @param text the input string (may contain spaces, punctuation, etc.)
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // \b = word boundary
        // [A-Za-z]+ = one or more letters
        // z = the literal 'z'
        // [A-Za-z]+ = one or more letters after the 'z'
        // \b = closing word boundary
        // The pattern therefore requires at least one letter before and after 'z',
        // guaranteeing that 'z' is not at the start or the end of the word.
        Pattern pattern = Pattern.compile("\\b[A-Za-z]+z[A-Za-z]+\\b");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        } else {
            return "Not matched!";
        }
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner, ends at the bottom‑right corner and may only move
     * right or down.
     *
     * @param cost square matrix (n × n)
     * @param n    dimension of the matrix
     * @return     maximal average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table holds the best sum to reach each cell
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest: best of the two possible predecessors + current cost
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Number of cells visited on any top‑left → bottom‑right path
        int cellsInPath = 2 * n - 1;
        double maxSum = dp[n - 1][n - 1];
        return maxSum / cellsInPath;
    }
}

