class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() <= 1) {
            return 0;
        }

        // Set of vowels (both lower‑ and upper‑case handled by toLowerCase)
        Set<Character> vowelSet = new HashSet<>(Arrays.asList('a', 'e', 'i', 'o', 'u'));

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char current = Character.toLowerCase(testStr.charAt(i));

            // Skip vowels themselves – we only count consonants that are next to a vowel
            if (vowelSet.contains(current)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbor
            if (i > 0) {
                char left = Character.toLowerCase(testStr.charAt(i - 1));
                if (vowelSet.contains(left)) {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbor (if we haven't already found a vowel neighbor)
            if (!hasVowelNeighbor && i < len - 1) {
                char right = Character.toLowerCase(testStr.charAt(i + 1));
                if (vowelSet.contains(right)) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));           // 5
    }
}

