import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2*a(n‑1) + a(n‑2)   for n >= 2
     *
     * For n >= 2 the values 3, 7, 17, 41, … are prime, which is why
     * the problem refers to them as “prime numbers”.
     *
     * @param n the index (1‑based) of the desired term; must be > 0
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Base cases
        if (n == 1) {
            return 1; // a(1) = 1
        }
        if (n == 2) {
            return 3; // first “prime” in the sequence
        }

        // Iteratively compute the recurrence.
        // Use long to avoid overflow while iterating; the final result fits
        // in int for the typical small values of n.
        long a0 = 1; // a(1)
        long a1 = 1; // a(2) after the first iteration
        for (int i = 2; i < n; i++) {
            long a2 = 2 * a1 + a0; // a(i+1) = 2*a(i) + a(i-1)
            a0 = a1;
            a1 = a2;
        }
        // After the loop, a1 holds a(n)
        return (int) a1;
    }

    // Simple driver to verify the examples from the problem statement.
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

