import java.util.*;

class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that travels from the top‑left
     * corner to the bottom‑right corner of the given n×n cost matrix.
     * Movement is restricted to right‑ or down‑steps only.
     *
     * @param cost the n×n matrix of path costs
     * @param n    size of the matrix (number of rows/columns)
     * @return     the highest possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- basic validation ----------------------------------------------------
        if (cost == null || cost.size() != n) {
            return null;
        }
        for (int i = 0; i < n; i++) {
            if (cost.get(i) == null || cost.get(i).size() != n) {
                return null;
            }
        }

        // ---- DP table: best sum to reach each cell --------------------------------
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double cur = cost.get(i).get(j).doubleValue();

                if (i == 0 && j == 0) {
                    // starting cell
                    dp[i][j] = cur;
                } else {
                    double fromTop    = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double fromLeft   = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = cur + Math.max(fromTop, fromLeft);
                }
            }
        }

        // length of any path from (0,0) to (n‑1,n‑1) is 2·n‑1
        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / pathLength;
    }

    // ---------------------------------------------------------------------------
    // Helper that lets you call the method with varargs – e.g.
    //   maxaverageofpath( List.of(1,2,3), List.of(6,5,4), List.of(7,3,9) )
    // ---------------------------------------------------------------------------
    @SafeVarargs
    public static Double maxaverageofpath(List<Integer>... rows) {
        int n = rows.length;
        List<List<Integer>> matrix = new ArrayList<>(n);
        for (List<Integer> row : rows) {
            matrix.add(Collections.unmodifiableList(row));
        }
        return maxaverageofpath(matrix, n);
    }

    // ---------------------------------------------------------------------------
    // Simple test driver (matches the examples from the problem statement)
    // ---------------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        System.out.println(maxaverageofpath(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        )); // Expected: 5.2

        // Example 2
        System.out.println(maxaverageofpath(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        )); // Expected: 6.2

        // Example 3
        System.out.println(maxaverageofpath(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        )); // Expected: 7.2
    }
}

