class CountVowels {
    /**
     * Counts characters (consonants) that have a vowel as a neighbour
     * (either to the left or to the right).
     *
     * @param testStr the input string
     * @return number of such characters
     *
     * > countVowels("bestinstareels")          // 7
     * > countVowels("partofthejourneyistheend")// 12
     * > countVowels("amazonprime")             // 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work in lower‑case so the vowel test is case‑insensitive
        String s = testStr.toLowerCase();
        int count = 0;

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);

            // We only count consonants; vowels themselves are ignored
            if (isVowel(ch)) {
                continue;
            }

            boolean leftIsVowel  = i > 0          && isVowel(s.charAt(i - 1));
            boolean rightIsVowel = i < s.length() - 1 && isVowel(s.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

    /** Helper: returns true if c is one of a, e, i, o, u. */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // --------------------------------------------------------------------
    // Optional main for quick testing
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

