class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * For n >= 2 this value is a prime (3, 7, 17, 41, …).
     *
     * @param n index in the sequence (0‑based)
     * @return the n‑th term of the NSW sequence
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // a0 = a(0) = 1, a1 = a(1) = 1
        long a0 = 1;
        long a1 = 1;

        if (n == 0) return (int) a0;
        if (n == 1) return (int) a1;

        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence: a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        // Examples from the problem statement
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41

        // Additional checks
        System.out.println(newmanPrime(2)); // 3
        System.out.println(newmanPrime(6)); // 99 (not prime, but still the correct sequence term)
    }
}

