public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all paths that go from the
     * top‑left corner to the bottom‑right corner of the given n×n matrix.
     * Movement is restricted to right or down steps.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     the dimension of the square matrix
     * @return      the maximum average (rounded to one decimal place)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive checks – not strictly required by the task but good practice
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // dp[i][j] = best sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                double cellValue = cost.get(i).get(j).doubleValue();

                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = cellValue;
                } else {
                    double best = 0.0;
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]);   // came from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]);   // came from left
                    }
                    dp[i][j] = cellValue + best;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        // round to one decimal place (as the examples show)
        average = Math.round(average * 10.0) / 10.0;

        return average;
    }

    // --------------------------------------------------------------------
    // Simple test driver (matches the examples from the problem statement)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
