            // Check right neighbor
            if (!hasVowelNeighbor && i < testStr.length() - 1) {
                char right = Character.toLowerCase(testStr.charAt(i + 1));
                if (vowels.contains(right)) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

