class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Empty or single‑character strings have no neighbours to evaluate
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        // Set of vowels (both lower‑ and upper‑case)
        Set<Character> vowelSet = new HashSet<>(
                Arrays.asList('a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U')
        );

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip the vowel characters themselves
            if (vowelSet.contains(ch)) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbor = false;
            if (i > 0 && vowelSet.contains(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour (if not already found)
            if (!hasVowelNeighbor && i < len - 1 && vowelSet.contains(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));           // 5
    }
}

