class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence,
     * defined by:
     *   a₁ = 1, a₂ = 3,
     *   aₙ = 2·aₙ₋₁ + aₙ₋₂  for n > 2.
     *
     * @param n the index (1‑based) of the desired term
     * @return the n‑th Newman–Shanks–Williams number
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Base cases
        if (n == 1) return 1;   // a₁ = 1
        if (n == 2) return 3;   // a₂ = 3

        // Iteratively compute the sequence
        long prev2 = 1; // aₙ₋₂
        long prev1 = 3; // aₙ₋₁
        long cur   = 0; // aₙ

        for (int i = 3; i <= n; i++) {
            cur = 2 * prev1 + prev2; // aₙ = 2·aₙ₋₁ + aₙ₋₂
            prev2 = prev1;
            prev1 = cur;
        }

        // The result fits in an int for reasonable n; cast is safe for the problem’s limits
        return (int) cur;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

