     * top‑left cell (0,0) to the bottom‑right cell (n‑1,n‑1) moving only
     * right or down.
     *
     * @param cost a square n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return the highest possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // Initialise the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The number of cells visited on any such path is always 2*n - 1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

