    }
}

import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner of the given n×n matrix and ends at the bottom‑right
     * corner, moving only right or down.
     *
     * @param cost the square matrix (List of Lists of Integer)
     * @param n    the dimension of the matrix (number of rows/columns)
     * @return the highest average among all valid paths, or null if the
     *         input is invalid.
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] holds the maximum sum reachable at cell (i, j)
        double[][] dp = new double[n][n];

        // Start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The total number of cells visited on any such path is 2*n - 1
        double maxSum = dp[n - 1][n - 1];
        return maxSum / (2 * n - 1);
    }

    // ------------------------------------------------------------------
    // A tiny test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

public static int countVowels(String testStr) {
    // Edge cases: null or too short to have a neighbour
    if (testStr == null || testStr.length() < 2) {
        return 0;
    }

    // Vowel characters (both cases)
    final String vowels = "aeiouAEIOU";

    int count = 0;
    for (int i = 0; i < testStr.length(); i++) {
        char ch = testStr.charAt(i);

        // Skip vowels themselves – we only count consonants that touch a vowel
        if (vowels.indexOf(ch) != -1) {
            continue;
        }

        boolean hasVowelNeighbor = false;

        // Check the left neighbour
        if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
            hasVowelNeighbor = true;
        }
        // Check the right neighbour (if not already true)
        if (!hasVowelNeighbor && i < testStr.length() - 1
                && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
            hasVowelNeighbor = true;
        }

        if (hasVowelNeighbor) {
            count++;
        }
    }
    return count;
}

