class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper limit n of the series (must be non‑negative)
     * @return the sum of squares from 1 to number
     */
    public static int seriesSum(int number) {
        // Guard against negative input – treat it as zero.
        if (number < 0) {
            return 0;
        }

        // Use the closed‑form formula: n*(n+1)*(2n+1)/6
        // The intermediate result can exceed int range for very large n,
        // so we cast to long during the multiplication and then back to int.
        return (int) ((long) number * (number + 1) * (2L * number + 1) / 6);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example calls from the problem statement
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

