     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split on whitespace – punctuation stays attached to the word
        String[] words = text.split("\\s+");

        for (String word : words) {
            if (word.isEmpty()) {
                continue;               // skip any empty tokens
            }

            // Does the word contain the letter 'z'?
            if (word.contains("z")) {
                char first = word.charAt(0);
                char last  = word.charAt(word.length() - 1);

                // ‘z’ must not be the first or last character
                if (first != 'z' && last != 'z') {
                    return "Found a match!";
                }
            }
        }

        // No qualifying word was found
        return "Not matched!";
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts at
     * the top‑left corner, ends at the bottom‑right corner and moves only
     * right or down.
     *
     * @param cost square matrix (n × n) of integer costs
     * @param n    dimension of the matrix
     * @return     maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[j] – best sum to reach current cell in column j of the current row
        double[] dp = new double[n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);          // cost of the current cell

                if (i == 0 && j == 0) {
                    // start cell
                    dp[j] = val;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[j] = dp[j - 1] + val;
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[j] = dp[j] + val;   // dp[0] still holds the value from the previous row
                } else {
                    // inner cell – take the better of "from above" (dp[j]) or "from left" (dp[j-1])
                    dp[j] = val + Math.max(dp[j], dp[j - 1]);
                }
            }
        }

        double maxSum = dp[n - 1];
        double average = maxSum / (2L * n - 1);   // length of any valid path
        return average;
    }
}

