class CountVowels {
    private static final Set<Character> VOWELS = Set.of('a', 'e', 'i', 'o', 'u');

    /**
     * Counts characters (excluding vowels) that have at least one vowel neighbor.
     *
     * @param testStr input string
     * @return count of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }
        int count = 0;
        int n = testStr.length();
        for (int i = 0; i < n; i++) {
            char ch = Character.toLowerCase(testStr.charAt(i));
            // skip vowels
            if (VOWELS.contains(ch)) {
                continue;
            }
            boolean hasVowelNeighbor = false;
            if (i > 0) {
                char left = Character.toLowerCase(testStr.charAt(i - 1));
                if (VOWELS.contains(left)) {
                    hasVowelNeighbor = true;
                }
            }
            if (i < n - 1) {
                char right = Character.toLowerCase(testStr.charAt(i + 1));
                if (VOWELS.contains(right)) {
                    hasVowelNeighbor = true;
                }
            }
            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

