class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) return 0; // Invalid input, return 0
        long a0 = 1; // a(n-2)
        long a1 = 1; // a(n-1)
        if (n == 1) return (int) a0;
        if (n == 2) return (int) a1;

        long a = 0; // a(n)
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }
}

