    private static final Pattern WORD_PATTERN = Pattern.compile("\\b[a-zA-Z]+\\b");

    /**
     * Returns "Found a match!" if any word in the supplied text contains the
     * letter 'z' (case‑insensitive) at a position other than the first or last
     * character of the word. Otherwise returns "Not matched!".
