import java.util.Arrays;

class Maxaverageofpath {
    /**
     * Returns the maximum possible average of a monotone path
     * (right‑/down moves only) from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost  list of n rows, each row a list of n integers
     * @param n     size of the square matrix
     * @return      the highest average (as a Double) among all such paths
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table holds the best sum to reach each cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Remaining cells: take the better of the two predecessors
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // Every monotone path has exactly (2*n - 1) cells
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

public static int countVowels(String testStr) {
    if (testStr == null) return 0;
    int count = 0;
    int len = testStr.length();
    for (int i = 0; i < len; i++) {
        char c = testStr.charAt(i);
        if (!isVowel(c)) {
            boolean neighborIsVowel = false;
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                neighborIsVowel = true;
            }
            if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                neighborIsVowel = true;
            }
            if (neighborIsVowel) {
                count++;
            }
        }
    }
    return count;
}

// Helper method
private static boolean isVowel(char ch) {
    char lower = Character.toLowerCase(ch);
    return lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u';
}

