public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(1) = 1
     *   a(2) = 3
     *   a(n) = 2·a(n‑1) + a(n‑2)  for n > 2
     *
     * @param n the index (1‑based) of the desired number
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // First two values of the sequence
        if (n == 1) return 1;   // a(1)
        if (n == 2) return 3;   // a(2)

        // Use long to avoid intermediate overflow; the result fits in int for reasonable n.
        long prev2 = 1;   // a(n‑2)  → a(1)
        long prev1 = 3;   // a(n‑1)  → a(2)
        long cur = 0;

        for (int i = 3; i <= n; i++) {
            cur = 2 * prev1 + prev2; // a(i) = 2·a(i‑1) + a(i‑2)
            prev2 = prev1;
            prev1 = cur;
        }
        return (int) cur;
    }
}

