class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron given the length of its edges.
     *
     * The volume V of a regular tetrahedron with edge length a is:
     *     V = a^3 / (6 * sqrt(2))
     *
     * @param num the length of each edge (integer)
     * @return the volume rounded to two decimal places as a Double
     */
    public static Double volumeTetrahedron(int num) {
        // Compute the exact volume using double arithmetic
        double edge = num;                     // edge length
        double edgeCube = Math.pow(edge, 3);   // a^3
        double denominator = 6.0 * Math.sqrt(2.0); // 6*sqrt(2)
        double volume = edgeCube / denominator;

        // Round to two decimal places (as shown in the examples)
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Return as a Double object
        return Double.valueOf(rounded);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

