class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowels for O(1) lookup (both cases)
        final Set<Character> vowelSet = new HashSet<>(Arrays.asList(
            'a', 'e', 'i', 'o', 'u',
            'A', 'E', 'I', 'O', 'U'
        ));

        char[] chars = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            // We only count consonants (i.e. characters that are NOT vowels)
            if (!vowelSet.contains(c)) {
                boolean leftIsVowel  = i > 0         && vowelSet.contains(chars[i - 1]);
                boolean rightIsVowel = i < chars.length - 1 && vowelSet.contains(chars[i + 1]);

                if (leftIsVowel || rightIsVowel) {
                    count++;
                }
            }
        }
        return count;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

