     * Write a function to count alphabets, digits and special characters in a given string.
     *
     * > countAlphaDigSpl("abc!@#123")
     * [3, 3, 3]
     * > countAlphaDigSpl("dgsuy@#$%&1255")
     * [5, 4, 5]
     * > countAlphaDigSpl("fjdsif627348#%$^&")
     * [6, 6, 5]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Guard against null input
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        // -----------------------------------------------------------------
        // 1) Define an enum for the three categories (following the advice)
        // -----------------------------------------------------------------
        enum CharCategory {
            ALPHABET,
            DIGIT,
            SPECIAL
        }

        // -----------------------------------------------------------------
        // 2) Helper that returns the category of a given character
        // -----------------------------------------------------------------
        CharCategory classify(char ch) {
            if (Character.isLetter(ch)) {
                return CharCategory.ALPHABET;
            } else if (Character.isDigit(ch)) {
                return CharCategory.DIGIT;
            } else {
                return CharCategory.SPECIAL;
            }
        }

        // -----------------------------------------------------------------
        // 3) Count using an EnumMap (ordered, efficient)
        // -----------------------------------------------------------------
        Map<CharCategory, Integer> counts = new EnumMap<>(CharCategory.class);
        for (CharCategory cat : CharCategory.values()) {
            counts.put(cat, 0);
        }

        for (char ch : string.toCharArray()) {
            CharCategory cat = classify(ch);
            counts.put(cat, counts.get(cat) + 1);
        }

        // -----------------------------------------------------------------
        // 4) Return the result in the required order: alphabets, digits, specials
        // -----------------------------------------------------------------
        return Arrays.asList(
                counts.get(CharCategory.ALPHABET),
                counts.get(CharCategory.DIGIT),
                counts.get(CharCategory.SPECIAL));
    }

    // -----------------------------------------------------------------
    // Simple test driver (optional)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&"));
    }
}

