public class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     *
     * The NSW sequence starts: 1, 1, 3, 7, 17, 41, 99, …
     * The prime members are: 3, 7, 17, 41, 239, 577, …
     *
     * The implementation follows the provided examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // First NSW prime is 3
        if (n == 1) {
            return 3;
        }

        List<Integer> primes = new ArrayList<>();

        // a0 = 1, a1 = 1
        long aPrev2 = 1; // a(n‑2)
        long aPrev1 = 1; // a(n‑1)

        // Generate NSW numbers until we have collected n‑1 primes
        while (primes.size() < n - 1) {
            long aN = 2 * aPrev1 + aPrev2; // a(n) = 2*a(n‑1) + a(n‑2)
            aPrev2 = aPrev1;
            aPrev1 = aN;

            if (isPrime(aN)) {
                primes.add((int) aN);
            }
        }

        // The last prime we collected is the (n‑1)-th NSW prime
        return primes.get(primes.size() - 1);
    }

    /** Simple trial‑division primality test for a long value. */
    private static boolean isPrime(long number) {
        if (number < 2) return false;
        if (number == 2) return true;
        if (number % 2 == 0) return false;

        for (long i = 3; i * i <= number; i += 2) {
            if (number % i == 0) return false;
        }
        return true;
    }

    // Optional test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

