class CountVowels {

    /**
     * Counts characters (other than vowels) that have a vowel as one of their
     * immediate neighbours in the given string.
     *
     * @param testStr the input string
     * @return the number of such characters
     *
     * > countVowels("bestinstareels")          // 7
     * > countVowels("partofthejourneyistheend") // 12
     * > countVowels("amazonprime")            // 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i < testStr.length(); i++) {
            char ch = testStr.charAt(i);

            // We only care about non‑vowel characters
            if (!Vowel.isVowel(ch)) {
                boolean leftIsVowel  = i > 0               && Vowel.isVowel(testStr.charAt(i - 1));
                boolean rightIsVowel = i < testStr.length() - 1 && Vowel.isVowel(testStr.charAt(i + 1));

                if (leftIsVowel || rightIsVowel) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Enum representing the five English vowels. */
    enum Vowel {
        A, E, I, O, U;

        /**
         * Checks whether a given character is a vowel (case‑insensitive).
         *
         * @param c the character to check
         * @return true if c is A, E, I, O or U (ignoring case)
         */
        public static boolean isVowel(char c) {
            char upper = Character.toUpperCase(c);
            for (Vowel v : values()) {
                if (v.name().charAt(0) == upper) {
                    return true;
                }
            }
            return false;
        }
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend"));// 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

