class NewmanPrime {
    /**
     * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle edge cases
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        if (n == 0) return 1;
        if (n == 1) return 1;

        // Compute the nth term of the Newman-Shanks-Williams sequence
        // Using 0-based indexing: a(0)=1, a(1)=1, a(n)=2*a(n-1)+a(n-2)
        long a0 = 1;
        long a1 = 1;
        long a2 = 0;

        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0;
            a0 = a1;
            a1 = a2;
        }

        return (int) a2;
    }
}

