public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that
     * starts at the top‑left corner and ends at the bottom‑right corner
     * of the given n×n cost matrix. Movement is allowed only right or down.
     *
     * @param cost  list of rows, each row a list of integers
     * @param n     dimension of the square matrix
     * @return      the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive: if the list is empty, return null or 0
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: maximum sum to reach each cell
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // interior cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // total number of cells in any valid path = 2*n - 1
        int pathLength = 2 * n - 1;
        double maxSum = dp[n - 1][n - 1];
        return maxSum / pathLength;   // maximum average
    }
}

