import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     *
     * The examples show that newmanPrime(3) == 7, newmanPrime(4) == 17,
     * newmanPrime(5) == 41, i.e. the function returns the (n‑2)-th prime
     * (0‑based) in the NSW prime sequence.
     *
     * @param n  a positive integer (n >= 2)
     * @return   the requested NSW prime
     */
    public static int newmanPrime(int n) {
        if (n < 2) {
            throw new IllegalArgumentException("n must be at least 2");
        }

        // List to hold the NSW primes we discover
        List<Integer> nswPrimes = new ArrayList<>();

        // a0 = 1, a1 = 1
        BigInteger aPrev2 = BigInteger.ONE; // a(n‑2)
        BigInteger aPrev1 = BigInteger.ONE; // a(n‑1)

        // zero‑based index of the prime we need
        int targetIndex = n - 2;

        // Generate NSW numbers until we have enough primes
        while (nswPrimes.size() <= targetIndex) {
            // a(n) = 2*a(n‑1) + a(n‑2)
            BigInteger aCurr = aPrev1.multiply(BigInteger.valueOf(2)).add(aPrev2);

            // If aCurr is prime, store it
            if (aCurr.isProbablePrime(20)) {
                // For the expected range of n the value fits in an int
                nswPrimes.add(aCurr.intValue());
            }

            // Shift the sliding window
            aPrev2 = aPrev1;
            aPrev1 = aCurr;
        }

        return nswPrimes.get(targetIndex);
    }

    // -----------------------------------------------------------------
    // Simple manual test (not required for the final answer)
