/** 
 * Solution that detects a word containing the letter 'z' 
 * that is neither the first nor the last character of the word.
 */
public class TextMatchWordzMiddle {

    /**
     * Enum representing the two possible outcomes.
     * The overridden toString() returns the required text.
     */
    private enum MatchResult {
        MATCH("Found a match!"),
        NO_MATCH("Not matched!");

        private final String message;

        MatchResult(String msg) {
            this.message = msg;
        }

        @Override
        public String toString() {
            return message;
        }
    }

    /**
     * Returns "Found a match!" if any word in the given text contains
     * the letter 'z' somewhere other than the first or last position;
     * otherwise returns "Not matched!".
     *
     * @param text the input string to examine
     * @return the appropriate message as described above
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return MatchResult.NO_MATCH.toString();
        }

        // \b\w+\b matches a word: a sequence of word characters bounded by
        // non‑word characters (spaces, punctuation, etc.).
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // the actual word
            String lower = word.toLowerCase();           // make the check case‑insensitive
            int idx = lower.indexOf('z');                // position of 'z' (or -1 if none)

            // If 'z' exists and is not at the first or last position
            if (idx > 0 && idx < lower.length() - 1) {
                return MatchResult.MATCH.toString();
            }
        }

        // No qualifying word found
        return MatchResult.NO_MATCH.toString();
    }

    // --------------------------------------------------------------------
    // Optional main method for quick manual testing
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));    // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));  // "Not matched!"
    }
}

