class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only want to count consonants.
            if (Vowel.isVowel(ch)) {
                continue;
            }

            // Ignore any non‑letter characters.
            if (!Character.isLetter(ch)) {
                continue;
            }

            // Does this consonant have a vowel neighbor on the left or right?
            boolean hasVowelNeighbor = false;
            if (i > 0 && Vowel.isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            if (i < len - 1 && Vowel.isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /** Enum representing the five English vowels, with a case‑insensitive test method. */
    private enum Vowel {
        A, E, I, O, U;

        /** Returns true if the given character is a vowel (a, e, i, o, u), ignoring case. */
        public static boolean isVowel(char c) {
            char lower = Character.toLowerCase(c);
            return lower == 'a' || lower == 'e' || lower == 'i' ||
                   lower == 'o' || lower == 'u';
        }
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

