public static int seriesSum(int number) {
    // Sum = 1² + 2² + … + n² = n·(n+1)·(2n+1) / 6
    long n = number;                     // use long for intermediate arithmetic
    long sum = n * (n + 1) * (2 * n + 1) / 6;
