import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

/**
 *  NewmanPrime – computes the n‑th Newman‑Shanks‑Williams prime.
 *
 *  The NSW sequence is defined by:
 *      a0 = 1, a1 = 1
 *      an = 2·a(n‑1) + a(n‑2)   for n ≥ 2
 *
 *  The primes among the terms a2, a3, … are the NSW primes:
 *      a2 = 3   (1st NSW prime)
 *      a3 = 5   (2nd)
 *      a4 = 7   (3rd)
 *      a5 = 17  (4th)
 *      a6 = 41  (5th)
 *      …
 *
 *  This implementation uses a deterministic Miller‑Rabin test that is
 *  guaranteed to be correct for all 64‑bit integers, so it works for
 *  reasonably large n (up to roughly n ≈ 45 where the values still fit
 *  in a signed 64‑bit long).  The method returns the result as an int,
 *  which is sufficient for the typical small test cases.
 */
public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime (1‑based).
     *
     * @param n the index (must be > 0)
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // a0 = 1, a1 = 1
        long a0 = 1L;
        long a1 = 1L;
        int primeCount = 0;
        long current = 0L;

        // start generating from a2 (i = 2)
        for (int i = 2; ; i++) {
            // compute next term: a_i = 2*a_{i-1} + a_{i-2}
            current = 2L * a1 + a0;

            // check primality
            if (isPrime(current)) {
                primeCount++;
                if (primeCount == n) {
                    // the result fits into int for the expected range
                    return (int) current;
                }
            }

            // shift the window for the next iteration
            a0 = a1;
            a1 = current;
        }
    }

    /**
     * Deterministic Miller‑Rabin primality test for 64‑bit numbers.
     * The set of bases {2, 325, 9375, 28178, 450775, 9780504, 1795265022}
     * is sufficient for all numbers < 2^64.
     *
     * @param n the number to test (must be non‑negative)
     * @return true if n is prime, false otherwise
     */
    private static boolean isPrime(long n) {
        if (n < 2) {
            return false;
        }
        // small primes – quick elimination
        long[] smallPrimes = {2L, 3L, 5L, 7L, 11L, 13L, 17L, 19L, 23L, 29L, 31L, 37L};
        for (long p : smallPrimes) {
            if (n % p == 0) {
                return n == p;
            }
        }

        // write n‑1 = d * 2^s with d odd
        long d = n - 1;
        int s = 0;
        while ((d & 1L) == 0L) {
            d >>= 1;
            s++;
        }

        // bases that guarantee correctness for n < 2^64
        long[] bases = {2L, 325L, 9375L, 28178L, 450775L, 9780504L, 1795265022L};

        for (long a : bases) {
            if (a % n == 0) {
                continue; // base congruent to 0 (mod n) is useless
            }

            long x = modPow(a, d, n);
            if (x == 1L || x == n - 1) {
                continue;
            }

            boolean composite = true;
            for (int r = 1; r < s; r++) {
                x = mulMod(x, x, n);
                if (x == n - 1) {
                    composite = false;
                    break;
                }
            }
            if (composite) {
                return false;
            }
        }
        return true;
    }

    /**
     * Computes (base^exp) % mod using BigInteger (safe from overflow).
     */
    private static long modPow(long base, long exp, long mod) {
        return BigInteger.valueOf(base)
                .modPow(BigInteger.valueOf(exp), BigInteger.valueOf(mod))
                .longValue();
    }

    /**
     * Computes (a * b) % mod using BigInteger.
     */
    private static long mulMod(long a, long b, long mod) {
        return BigInteger.valueOf(a)
                .multiply(BigInteger.valueOf(b))
                .mod(BigInteger.valueOf(mod))
                .longValue();
    }

    // -----------------------------------------------------------------
    // Optional test driver (uncomment to run manually)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example calls from the problem statement
        System.out.println(newmanPrime(3));  // -> 7
        System.out.println(newmanPrime(4));  // -> 17
        System.out.println(newmanPrime(5));  // -> 41

        // A few more
        for (int i = 1; i <= 10; i++) {
            System.out.println("n=" + i + " -> " + newmanPrime(i));
        }
    }
}

