public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' (or 'Z') that is neither the first nor the last character
     * of that word; otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern to match words: consecutive letters only
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();          // the word itself
            String lower = word.toLowerCase();      // case‑insensitive check

            // Scan for any 'z' that is not at position 0 or at the last position
            int idx = lower.indexOf('z');
            while (idx != -1) {
                if (idx != 0 && idx != lower.length() - 1) {
                    return "Found a match!";
                }
                // look for the next occurrence in the same word
                idx = lower.indexOf('z', idx + 1);
            }
        }

        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));      // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that goes from the top‑left corner
     * to the bottom‑right corner of the given n×n matrix, moving only right
     * or down.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     dimension of the square matrix
     * @return      the maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive checks
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] = best sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // maximum sum = dp[n-1][n-1]
        double maxSum = dp[n - 1][n - 1];
        // each path contains exactly (2*n - 1) cells
        double average = maxSum / (2.0 * n - 1.0);

        return Double.valueOf(average);
    }
}

