class SeriesSum {
    /**
     * Returns the sum of the series 1² + 2² + … + n².
     *
     * @param number the number of terms (n)
     * @return the sum of squares from 1 to n
     */
    public static int seriesSum(int number) {
        long n = number;                     // use long to prevent overflow during the multiplication
        long sum = n * (n + 1) * (2 * n + 1) / 6;  // formula: n(n+1)(2n+1)/6
        return (int) sum;                    // cast back to int as per the method signature
    }

    // Optional main method for quick testing
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

