import java.math.BigInteger;

public class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * For the inputs shown in the task (n = 3,4,5) the returned values are
     * the NSW primes 7, 17 and 41 respectively.
     *
     * @param n index of the required term (n >= 0)
     * @return S_n as an int
     * @throws IllegalArgumentException if n is negative
     * @throws ArithmeticException       if the result does not fit in an int
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // S(0) = 1, S(1) = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        BigInteger a0 = BigInteger.ONE; // S(0)
        BigInteger a1 = BigInteger.ONE; // S(1)
        BigInteger a2 = null;

        for (int i = 2; i <= n; i++) {
            // S(i) = 2 * S(i‑1) + S(i‑2)
            a2 = a1.multiply(BigInteger.valueOf(2)).add(a0);
            a0 = a1;
            a1 = a2;
        }

        // The problem’s test cases stay well within int range.
        if (a1.compareTo(BigInteger.valueOf(Integer.MAX_VALUE)) > 0) {
            throw new ArithmeticException("Result exceeds Integer.MAX_VALUE");
        }

        return a1.intValue();
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        for (int i = 2; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

