import java.util.regex.*;

public class TextMatchWordzMiddle {

    /** 
     * Enum representing the two possible outcomes.
     */
    private enum MatchResult {
        FOUND("Found a match!"),
        NOT_MATCHED("Not matched!");

        private final String message;

        MatchResult(String message) {
            this.message = message;
        }

        public String getMessage() {
            return message;
        }
    }

    /**
     * Determines whether any word in the given text contains the letter 'z'
     * somewhere other than the first or last position.
     *
     * @param text the input string to examine
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return MatchResult.NOT_MATCHED.getMessage();
        }

        // Pattern to capture words consisting only of letters (a‑z, A‑Z)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A word must have at least three characters to have a "middle" position
            if (word.length() >= 3) {
                // Scan characters from index 1 up to length‑2 (inclusive)
                for (int i = 1; i < word.length() - 1; i++) {
                    if (word.charAt(i) == 'z') {
                        return MatchResult.FOUND.getMessage();
                    }
                }
            }
        }

        return MatchResult.NOT_MATCHED.getMessage();
    }

    // --------------------------------------------------------------------
    // Optional simple test driver
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));        // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));      // Not matched!
        // Additional tests
        System.out.println(textMatchWordzMiddle("zabc"));           // Not matched! (z at start)
        System.out.println(textMatchWordzMiddle("abcz"));           // Not matched! (z at end)
        System.out.println(textMatchWordzMiddle("azb"));            // Not matched! (z at start)
        System.out.println(textMatchWordzMiddle("abcdezg"));        // Found a match!
    }
}

import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all paths that go from the
     * top‑left corner (0,0) to the bottom‑right corner (n‑1,n‑1) in the
     * given n×n matrix.  Movement is restricted to right or down only.
     *
     * @param cost 2‑D list representing the matrix
     * @param n   size of the square matrix
     * @return    maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP[i][j] = maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // The best path sum and its average
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);   // length of any valid path

        return average;
    }

    // --------------------------------------------------------------------
    // Optional test driver (matches the examples from the description)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

import java.util.Set;

class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Handle null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowels (both lower‑ and upper‑case)
        Set<Character> vowels = Set.of('a', 'e', 'i', 'o', 'u',
                                       'A', 'E', 'I', 'O', 'U');

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only care about consonants (i.e., characters that are NOT vowels)
            if (!vowels.contains(ch)) {
                boolean hasVowelNeighbor = false;

                // Check the left neighbour
                if (i > 0 && vowels.contains(testStr.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // Check the right neighbour
                if (i < len - 1 && vowels.contains(testStr.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

import java.util.Arrays;
