/**
 * Counts alphabets, digits and special characters in a given string.
 */
public class CountAlphaDigSpl {

    /** Enum representing the three possible kinds of characters we care about. */
    private enum CharKind {
        ALPHABET {
            @Override
            boolean matches(char c) {
                return Character.isLetter(c);
            }
        },
        DIGIT {
            @Override
            boolean matches(char c) {
                return Character.isDigit(c);
            }
        },
        SPECIAL {
            @Override
            boolean matches(char c) {
                // Anything that is neither a letter nor a digit is considered “special”.
                return !Character.isLetter(c) && !Character.isDigit(c);
            }
        };

        /** Returns true if the supplied character belongs to this kind. */
        abstract boolean matches(char c);
    }

    /**
     * Returns a List containing three integers:
     *   - count of alphabetic characters,
     *   - count of digit characters,
     *   - count of all other (special) characters.
     *
     * @param string the input text (may be null)
     * @return List<Integer> in the order [alphabets, digits, special]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Guard against null input – treat it as an empty string.
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alphaCount = 0;
        int digitCount = 0;
        int specialCount = 0;

        for (char c : string.toCharArray()) {
            if (CharKind.ALPHABET.matches(c)) {
                alphaCount++;
            } else if (CharKind.DIGIT.matches(c)) {
                digitCount++;
            } else {
                specialCount++;
            }
        }

        return Arrays.asList(alphaCount, digitCount, specialCount);
    }

    // --------------------------------------------------------------------
    // Simple test driver (optional – can be removed in production)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));   // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

