import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;
import java.util.stream.*;

/**
 * Solution for the “textMatchWordzMiddle” problem.
 *
 * The method returns:
 *   • "Found a match!" – if any word contains the letter 'z' somewhere
 *                       other than the first or last position.
 *   • "Not matched!"   – otherwise.
 *
 * The result is represented by an enum {@link MatchResult} that overrides
 * {@code toString()} to return the required message and provides a
 * {@code fromString()} method (as suggested in the programming advice).
 */
class TextMatchWordzMiddle {

    /** Enum that models the two possible outcomes. */
    enum MatchResult {
        FOUND("Found a match!"),
        NOT_FOUND("Not matched!");

        private final String message;

        MatchResult(String message) {
            this.message = message;
        }

        /** Returns the message that must be printed. */
        @Override
        public String toString() {
            return message;
        }

        /** Map from the string returned by toString() to the enum constant. */
        private static final Map<String, MatchResult> stringToEnum =
                Stream.of(values())
                      .collect(Collectors.toMap(Object::toString, e -> e));

        /**
         * Translates a string (the custom toString representation) back to a
         * {@code MatchResult} constant, if such a constant exists.
         *
         * @param s the string representation
         * @return an {@code Optional} containing the matching constant, or empty
         */
        public static Optional<MatchResult> fromString(String s) {
            return Optional.ofNullable(stringToEnum.get(s));
        }
    }

    /**
     * Checks the input text for a word that contains the letter 'z' not at
     * the first or last position.
     *
     * @param text the input text (may contain spaces, punctuation, etc.)
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return MatchResult.NOT_FOUND.toString();
        }

        // Split the input on whitespace – each token is treated as a “word”
        String[] words = text.split("\\s+");

        for (String word : words) {
            int len = word.length();
            // Scan each character of the word
            for (int i = 0; i < len; i++) {
                if (word.charAt(i) == 'z') {
                    // ‘z’ is not at the start (i > 0) and not at the end (i < len‑1)
                    if (i > 0 && i < len - 1) {
                        return MatchResult.FOUND.toString();
                    }
                }
            }
        }

        // No suitable word was found
        return MatchResult.NOT_FOUND.toString();
    }

    /** Simple manual test harness. */
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
        System.out.println(textMatchWordzMiddle("  lang  ."));

        // Example of using the fromString method (optional)
        String result = textMatchWordzMiddle("pythonzabc.");
        MatchResult.fromString(result).ifPresent(m -> System.out.println("Parsed: " + m));
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a monotonic path
     * (moving only right or down) from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost list of rows, each row a list of integer costs
     * @param n    size of the square matrix (number of rows/columns)
     * @return     the maximal average as a {@code Double}, or null if the
     *             input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.isEmpty() || cost.get(0).isEmpty()) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach (i, j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                           + cost.get(i).get(j);
            }
        }

        // total number of cells in any monotonic path = 2*n - 1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        return average;
    }

    // ------------------------------------------------------------------
    // Optional test harness (can be removed when integrating into a larger
    // project)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

