class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle base cases
        if (n == 0) return 1;
        if (n == 1) return 1;

        // Compute the nth Newman–Shanks–Williams number iteratively
        long a0 = 1; // a(n-2)
        long a1 = 1; // a(n-1)
        long a = 0;  // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        // Return the result as an int (assuming it fits)
        return (int) a;
    }
}

