import java.util.List;

/**
 * Returns the maximum average of any path that travels from the top‑left
 * corner to the bottom‑right corner of the given n×n matrix.
 * Movement is allowed only to the right or down.
 *
 * @param cost the n×n matrix of integer costs
 * @param n    size of the matrix
 * @return the maximum average as a {@code Double}, or {@code null} if the input is invalid
 */
public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // Basic validation
    if (cost == null || n <= 0) {
        return null;
    }

    // DP table: dp[i][j] = maximum sum to reach cell (i, j)
    long[][] dp = new long[n][n];

    // Starting cell
    dp[0][0] = cost.get(0).get(0);

    // First row: can only come from the left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // First column: can only come from above
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill the rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // The best sum to reach the bottom‑right corner
    long maxSum = dp[n - 1][n - 1];

    // Every path from (0,0) to (n-1,n-1) with only right/down moves
    // contains exactly (2*n - 1) cells.
    double average = (double) maxSum / (2 * n - 1);

    return average;
}

