/**
 * Utility class that counts how many alphabetic characters,
 * digits, and special (non‑letter/non‑digit) characters appear
 * in a given string.
 */
public class CountAlphaDigSpl {

    /** Enum representing the three possible categories of a character. */
    enum CharType {
        ALPHABET {
            @Override
            boolean matches(char c) {
                return Character.isLetter(c);
            }
        },
        DIGIT {
            @Override
            boolean matches(char c) {
                return Character.isDigit(c);
            }
        },
        SPECIAL {
            @Override
            boolean matches(char c) {
                // Anything that is neither a letter nor a digit is “special”.
                return !Character.isLetter(c) && !Character.isDigit(c);
            }
        };

        /** Returns true if the given character belongs to this category. */
        abstract boolean matches(char c);
    }

    /**
     * Counts alphabets, digits and special characters in the supplied string.
     *
     * @param string the input (may be {@code null})
     * @return a {@link List} containing three integers:
     *         <ol>
     *           <li>number of alphabetic characters</li>
     *           <li>number of digit characters</li>
     *           <li>number of special characters</li>
     *         </ol>
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Guard against null input – treat it as an empty string.
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alphaCount = 0;
        int digitCount = 0;
        int specialCount = 0;

        for (char ch : string.toCharArray()) {
            if (CharType.ALPHABET.matches(ch)) {
                alphaCount++;
            } else if (CharType.DIGIT.matches(ch)) {
                digitCount++;
            } else {
                // Anything that is not a letter or a digit falls into SPECIAL.
                specialCount++;
            }
        }

        return Arrays.asList(alphaCount, digitCount, specialCount);
    }

    /** Simple test driver. */
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));     // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

