class SeriesSum {
    /**
     * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Guard against negative input – the series isn’t defined for n < 0
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative");
        }

        // Use long to avoid intermediate overflow, then cast back to int.
        // Formula: n*(n+1)*(2n+1)/6
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;
        return (int) sum;
    }

