class NewmanPrime {
    /**
     * Returns the n-th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a(1) = 1
     *   a(2) = 3
     *   a(n) = 2 * a(n-1) + a(n-2) for n > 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (n == 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }

        int a = 0;
        int a1 = 3; // a(2)
        int a2 = 1; // a(1)

        for (int i = 3; i <= n; i++) {
            a = 2 * a1 + a2;
            a2 = a1;
            a1 = a;
        }
        return a;
    }
}

