class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' (or 'Z') that is not the first or last character of the word.
     * Otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        // \b\w+\b finds whole words (letters, digits, underscore)
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A word must be at least 3 characters long to have a “middle”
            if (word.length() >= 3) {
                // Look at the substring that excludes the first and last chars
                String middle = word.substring(1, word.length() - 1);

                // If there is a 'z' or 'Z' inside that substring, we have a match
                if (middle.indexOf('z') != -1 || middle.indexOf('Z') != -1) {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
