        System.out.println(textMatchWordzMiddle("xyzabc."));      // → Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));   // → Not matched!
    }
}

import java.util.List;

public class Maxaverageofpath {
    /**
     * Returns the maximum average value among all monotonic (right‑/down‑only) paths
     * from the top‑left corner (0,0) to the bottom‑right corner (n‑1,n‑1) of the
     * given n×n cost matrix.
     *
     * @param cost a list of n rows, each row a list of n integers
     * @param n    the dimension of the square matrix
     * @return the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against empty input
        if (cost == null || cost.isEmpty() || cost.get(0).isEmpty()) {
            return null;
        }

        // dp[i][j] holds the maximum sum reachable at cell (i,j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the DP table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The total number of cells in any monotonic path from (0,0) to (n-1,n-1)
        // is 2*n - 1 (n-1 moves down + n-1 moves right + the start cell)
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);

        return average;
    }
}

