public class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2*a(n‑1) + a(n‑2) for n >= 2
     *
     * @param n the index (0‑based) of the term to return
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        // Handle the base cases
        if (n <= 0) return 1;   // a(0)
        if (n == 1) return 1;  // a(1)

        long prev2 = 1; // a(n‑2), initially a(0)
        long prev1 = 1; // a(n‑1), initially a(1)
        long curr = 0;  // a(n)

        for (int i = 2; i <= n; i++) {
            curr = 2 * prev1 + prev2; // a(i) = 2*a(i‑1) + a(i‑2)
            prev2 = prev1;
            prev1 = curr;
        }

        // The method's return type is int; the cast is safe for the
        // expected input range.
        return (int) prev1;
    }
}

