public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the top‑left
     * cell and ends at the bottom‑right cell of the given square matrix.
     * Movement is restricted to right or down steps only.
     *
     * @param cost  list of rows, each row is a list of integers
     * @param n     size of the matrix (n × n)
     * @return      the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Invalid matrix size");
        }

        // DP table: dp[i][j] = max sum to reach (i, j)
        int[][] dp = new int[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                           + cost.get(i).get(j);
            }
        }

        int maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);

        return average;               // auto‑boxed to Double
    }
}

