class NewmanPrime {
    /**
     * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle negative indices
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }

        // Base cases: the first two terms of the sequence are both 1
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iterate to compute the nth term using the recurrence:
        // a_n = 2 * a_{n-1} + a_{n-2}
        long a0 = 1; // a_{n-2}
        long a1 = 1; // a_{n-1}
        long a = 0;  // a_n

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        // Cast to int, assuming n is small enough for the result to fit
        return (int) a;
    }
}

