/**
 * Solution for the “count characters that have vowels as neighbours” problem.
 *
 * The method counts a character if:
 *   1. It is a consonant (i.e. not a vowel), and
 *   2. At least one of its immediate neighbours (the character to the left,
 *      the character to the right, or both) is a vowel.
 *
 * Examples:
 *   countVowels("bestinstareels")          → 7
 *   countVowels("partofthejourneyistheend")→ 12
 *   countVowels("amazonprime")             → 5
 */
class CountVowels {

    /** Simple enum for the English vowels (case‑insensitive). */
    private enum Vowel {
        A, E, I, O, U
    }

    /**
     * Returns the number of consonants in {@code testStr} that have a vowel
     * as either their left or right neighbour.
     *
     * @param testStr the input string (may contain mixed case letters)
     * @return the required count
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // EnumSet that holds all vowel values – internally a bit‑vector (Item 36)
        final EnumSet<Vowel> VOWELS = EnumSet.allOf(Vowel.class);

        int count = 0;
        final int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // -----------------------------------------------------------------
            // Helper: is this character a vowel?  (case‑insensitive)
            // -----------------------------------------------------------------
            boolean isVowel;
            try {
                Vowel v = Vowel.valueOf(Character.toString(ch).toUpperCase());
                isVowel = VOWELS.contains(v);
            } catch (IllegalArgumentException notAVowel) {
                isVowel = false;
            }

            // We only count consonants, not vowels themselves
            if (isVowel) {
                continue;
            }

            // -----------------------------------------------------------------
            // Does this consonant have at least one vowel neighbour?
            // -----------------------------------------------------------------
            boolean hasVowelNeighbour = false;

            // Check left neighbour
            if (i > 0) {
                char left = testStr.charAt(i - 1);
                try {
                    Vowel v = Vowel.valueOf(Character.toString(left).toUpperCase());
                    if (VOWELS.contains(v)) {
                        hasVowelNeighbour = true;
                    }
                } catch (IllegalArgumentException ignored) {
                    // left character is not a vowel
                }
            }

            // Check right neighbour (only if we haven't already found a vowel)
            if (!hasVowelNeighbour && i < len - 1) {
                char right = testStr.charAt(i + 1);
                try {
                    Vowel v = Vowel.valueOf(Character.toString(right).toUpperCase());
                    if (VOWELS.contains(v)) {
                        hasVowelNeighbour = true;
                    }
                } catch (IllegalArgumentException ignored) {
                    // right character is not a vowel
                }
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }

        return count;
    }

    // -----------------------------------------------------------------------
    // Simple manual test driver
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

