class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle trivial cases
        if (n <= 0) return 0;   // not defined for non‑positive n
        if (n == 1) return 1;   // a(1) = 1

        // Compute the Newman‑Shanks‑Williams sequence:
        // a(0)=1, a(1)=1, a(i) = 2*a(i‑1) + a(i‑2)
        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        for (int i = 2; i <= n; i++) {
            long a2 = 2 * a1 + a0; // a(i)
            a0 = a1;
            a1 = a2;
        }
        return (int) a1; // a(n)
    }
}

