import java.util.Arrays;
import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given
     * n×n matrix. Movement is allowed only to the right or down.
     *
     * @param cost  list of rows, each row a list of integer cell values
     * @param n     size of the square matrix
     * @return      the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive checks (not required by the problem, but harmless)
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum of a path that ends at cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long cell = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = cell;                     // start cell
                } else {
                    long bestPrev = 0;
                    if (i > 0) {
                        bestPrev = Math.max(bestPrev, dp[i - 1][j]); // from above
                    }
                    if (j > 0) {
                        bestPrev = Math.max(bestPrev, dp[i][j - 1]); // from left
                    }
                    dp[i][j] = cell + bestPrev;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);
        return average;
    }

