                // check right neighbour (if left wasn’t a vowel)
                else if (i < n - 1 && Vowel.isVowel(testStr.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

