import java.util.*;          // for EnumMap, etc.

public class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)   for n ≥ 2
     *
     * For the test cases:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // EnumMap to hold the two most recent values (prev = a(i‑2), curr = a(i‑1))
        enum Last { PREV, CURR }
        EnumMap<Last, Long> seq = new EnumMap<>(Last.class);
        seq.put(Last.PREV, 1L);   // a0
        seq.put(Last.CURR, 1L);   // a1

        // Build the sequence up to index n
        for (int i = 2; i <= n; i++) {
            long next = 2 * seq.get(Last.CURR) + seq.get(Last.PREV); // an = 2*a(n‑1) + a(n‑2)
            // Shift the window
            seq.put(Last.PREV, seq.get(Last.CURR));
            seq.put(Last.CURR, next);
        }

        // The current value is the answer; cast to int (fits for reasonable n)
        return (int) seq.get(Last.CURR);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

public static String removeOdd(String str1) {
    // Guard against null input
    if (str1 == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();

    // i == 0 → 1st character (odd position) → skip
    // i == 1 → 2nd character (even position) → keep
    // i == 2 → 3rd character (odd position) → skip
    // …
    for (int i = 0; i < str1.length(); i++) {
        if (i % 2 == 1) {               // keep characters at even positions (1‑based)
            sb.append(str1.charAt(i));
        }
    }

    return sb.toString();
}

