     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set – works for both lower‑ and upper‑case letters
        Set<Character> vowels = Set.of(
                'a', 'e', 'i', 'o', 'u',
                'A', 'E', 'I', 'O', 'U'
        );

        char[] a = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < a.length; i++) {
            char ch = a[i];
            // we only consider consonants
            if (vowels.contains(ch)) {
                continue;
            }

            boolean hasVowelNeighbour = false;

            // check left neighbour
            if (i > 0 && vowels.contains(a[i - 1])) {
                hasVowelNeighbour = true;
