public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the given text contains a word that has the
     * letter 'z' (or 'Z') somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches a whole word consisting of letters only.
        // \b denotes a word boundary, so punctuation such as '.' is ignored.
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // Look for 'z' or 'Z' (case‑insensitive) inside the word.
            int idx = word.indexOf('z');
            if (idx == -1) {
                idx = word.indexOf('Z');
            }

            // If a 'z' exists and it is not at the first or last position,
            // we have a match.
            if (idx != -1 && idx != 0 && idx != word.length() - 1) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!
    }
}

