     *
     * @param cost the n×n matrix of integers (as a list of rows)
     * @param n    the dimension of the square matrix
     * @return the maximum average (sum / (2·n‑1)) as a {@code Double},
     *         or {@code null} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP array holds the best sum to reach each cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int val = cost.get(i).get(j);          // the cost of the current cell
                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // First row – can only come from the left
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    // First column – can only come from above
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    // General case: take the best of the two predecessors
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // The total number of cells visited on any top‑left → bottom‑right path
        int pathLength = 2 * n - 1;
        long maxSum = dp[n - 1][n - 1];

        // Convert to double and return the average
        return (double) maxSum / pathLength;
    }

    // -----------------------------------------------------------------------
    // A tiny demo (optional)
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

