class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2 * a(n-1) + a(n-2)  for n >= 2.
     *
     * > newmanPrime(3)  -> 7
     * > newmanPrime(4)  -> 17
     * > newmanPrime(5)  -> 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // a0 = a(0), a1 = a(1)
        long a0 = 1;
        long a1 = 1;

        if (n == 0) return (int) a0;
        if (n == 1) return (int) a1;

        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }
        return (int) a;   // the result fits in an int for the expected small n
    }
}

