class Maxaverageofpath {
    /**
     * Finds the maximum average of any path that starts at the top‑left
     * cell (0,0) and ends at the bottom‑right cell (n‑1,n‑1) while
     * moving only right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    size of the matrix (cost.size() == n)
     * @return the maximum average value as a Double
     *
     * Example:
     *   maxaverageofpath([[1,2,3],[6,5,4],[7,3,9]], 3) → 5.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table: dp[i][j] = maximum sum to reach cell (i,j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0).longValue();

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j).longValue();
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0).longValue();
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j).longValue()
                           + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;               // number of cells in any valid path
        double maxAverage = maxSum / (double) pathLength;

        return maxAverage; // auto‑boxed to Double
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
