class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)  for n >= 2
     *
     * Examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n index of the required term (0‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use BigInteger to avoid overflow for larger n, then narrow to int
        BigInteger a0 = BigInteger.ONE; // a(i‑2)
        BigInteger a1 = BigInteger.ONE; // a(i‑1)
        BigInteger a  = BigInteger.ZERO; // a(i)

        for (int i = 2; i <= n; i++) {
            // a = 2 * a1 + a0
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            // shift the window
            a0 = a1;
            a1 = a;
        }

        // The problem expects an int result; the test cases stay within int range.
        return a.intValue();
    }
}

