        // 1. Guard against illegal input
        // ------------------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;                     // or throw an exception
        }

        // ------------------------------------------------------------
        // 2. Set up the direction enum and an EnumMap that maps each
        //    direction to its row/col delta (row delta, col delta).
        // ------------------------------------------------------------
        enum Direction { RIGHT, DOWN }

        EnumMap<Direction, int[]> delta = new EnumMap<>(Direction.class);
        delta.put(Direction.RIGHT, new int[]{0, 1}); // move one column to the right
        delta.put(Direction.DOWN,  new int[]{1, 0}); // move one row    down

        // ------------------------------------------------------------
        // 3. DP table: dp[i][j] = maximum sum reachable at (i, j)
        // ------------------------------------------------------------
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // fill the first row (只能从左边来)
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // fill the first column (只能从上边来)
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells – take the best of the two possible predecessors
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                double bestPrev = Double.NEGATIVE_INFINITY;
                for (Direction dir : Direction.values()) {
                    int[] d = delta.get(dir);
                    int pi = i - d[0]; // predecessor row
                    int pj = j - d[1]; // predecessor col
                    // the predecessor is guaranteed to be inside the matrix
                    bestPrev = Math.max(bestPrev, dp[pi][pj]);
                }
                dp[i][j] = bestPrev + cost.get(i).get(j);
            }
        }

        // ------------------------------------------------------------
        // 4. Convert the maximal sum to the maximal average.
        //    A path from (0,0) to (n‑1,n‑1) always contains 2·n‑1 cells.
        // ------------------------------------------------------------
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------
    // Simple manual test harness (can be removed / commented out)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

