import java.util.*;

public class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams (Pell) number.
     * The sequence is defined by:
     *   P0 = 1, P1 = 1
     *   Pn = 2·Pn‑1 + Pn‑2   for n ≥ 2
     *
     * @param n the index (0‑based) of the desired Pell number
     * @return the value of Pn
     * @throws IllegalArgumentException if n is negative
     */
    public static long newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // P0 = 1
        if (n == 0) {
            return 1L;
        }
        // P1 = 1
        if (n == 1) {
            return 1L;
        }

        long prev2 = 1L; // P0
        long prev1 = 1L; // P1
        long current = 0L;

        for (int i = 2; i <= n; i++) {
            current = 2L * prev1 + prev2; // Pn = 2·Pn‑1 + Pn‑2
            prev2 = prev1;
            prev1 = current;
        }
        return current;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

