    }
}

import java.util.StringTokenizer;

public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the given text contains a word that includes
     * the letter 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") -> "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")      -> "Found a match!"
     *   textMatchWordzMiddle("  lang  .")    -> "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split on whitespace – each token is treated as a “word”.
        StringTokenizer st = new StringTokenizer(text);
        while (st.hasMoreTokens()) {
            String token = st.nextToken();

            // Work case‑insensitively
            String lower = token.toLowerCase();

            // Must contain 'z' and the 'z' must not be the first or last character.
            if (lower.contains("z") && !lower.startsWith("z") && !lower.endsWith("z")) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts at the
     * top‑left cell and ends at the bottom‑right cell of the given n×n matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.size() != n) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else {
                    long bestFromAbove = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                    long bestFromLeft  = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;
                    dp[i][j] = val + Math.max(bestFromAbove, bestFromLeft);
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // Every valid path has exactly (2*n - 1) cells
        double average = maxSum / (double) (2 * n - 1);

        return average;
    }
}

