import java.util.regex.*;

public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the input contains the letter 'z'
     * (or 'Z') at a position other than the first or last character of the word.
     * Otherwise returns "Not matched!".
     *
     * @param text the input string (may contain punctuation, spaces, etc.)
     * @return the appropriate message
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Pattern to match a word: one or more ASCII letters
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // the actual word
            // Case‑insensitive search for 'z'
            int idx = word.toLowerCase().indexOf('z');

            // Check that 'z' exists and is not at the start or end
            if (idx > 0 && idx < word.length() - 1) {
                return "Found a match!";
            }
        }

        // No qualifying word found
