/**
 * Utility class to count alphabets, digits and special characters
 * in a given string.
 */
public class CountAlphaDigSpl {

    /** Enum representing the three categories we want to count. */
    private enum Category {
        ALPHA,   // letters (a‑z, A‑Z)
        DIGIT,   // decimal digits 0‑9
        SPECIAL  // everything else
    }

    /**
     * Returns a list containing three integers:
     *   - number of alphabetic characters,
     *   - number of digit characters,
     *   - number of special (non‑letter, non‑digit) characters.
     *
     * @param string the input string (may be null)
     * @return a List<Integer> with the three counts in the order [alpha, digit, special]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Guard against null input
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        // Use an EnumMap to hold the three counters – clear, safe and O(1) access.
        EnumMap<Category, Integer> counts = new EnumMap<>(Category.class);
        counts.put(Category.ALPHA,   0);
        counts.put(Category.DIGIT,   0);
        counts.put(Category.SPECIAL, 0);

        // Iterate over each character and increment the appropriate counter.
        for (char ch : string.toCharArray()) {
            if (Character.isLetter(ch)) {
                counts.put(Category.ALPHA, counts.get(Category.ALPHA) + 1);
            } else if (Character.isDigit(ch)) {
                counts.put(Category.DIGIT, counts.get(Category.DIGIT) + 1);
            } else {
                counts.put(Category.SPECIAL, counts.get(Category.SPECIAL) + 1);
            }
        }

        // Return the results in the required order.
        return Arrays.asList(
                counts.get(Category.ALPHA),
                counts.get(Category.DIGIT),
                counts.get(Category.SPECIAL)
        );
    }

    // --------------------------------------------------------------------
    // Simple manual test (optional)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

