class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the last term of the series (n ≥ 1)
     * @return the sum of squares from 1 to number
     *
     * Example:
     * seriesSum(6) → 91
     * seriesSum(7) → 140
     * seriesSum(12) → 650
     */
    public static int seriesSum(int number) {
        // Guard against non‑positive input
        if (number <= 0) {
            return 0;
        }

        // Use the formula n*(n+1)*(2n+1)/6 to compute the sum in O(1) time.
        // The intermediate result is stored in a long to avoid overflow,
        // then cast back to int (the problem expects int results that fit in 32 bits).
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

