class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }

        // Base cases for the NSW sequence
        if (n == 0) return 1;
        if (n == 1) return 1;

        // Initialize the first two terms
        long a0 = 1; // a(n-2)
        long a1 = 1; // a(n-1)
        long a = 0;  // Current term

        // Compute the n-th term iteratively
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            // Update for next iteration
            a0 = a1;
            a1 = a;
        }

        // Return the result as an integer (assuming it fits)
        return (int) a;
    }
}

