public class TextMatchWordzMiddle {

    /**
     * Determines whether any word in the given text contains the letter 'z'
     * somewhere other than the first or last position.
     *
     * @param text the input string to be examined
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null input
        if (text == null) {
            return "Not matched!";
        }

        // \b\w+\b matches whole words (letters, digits, underscore)
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A word shorter than 3 characters cannot have a middle 'z'
            if (word.length() < 3) {
                continue;
            }

            // Scan characters between the first and last index
            for (int i = 1; i < word.length() - 1; i++) {
                if (word.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

    // Optional simple test harness
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));      // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {
    /**
     * Returns the maximum average of a path that moves only right or down
     * from the top‑left to the bottom‑right corner of the given square matrix.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum possible average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] holds the maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cur = cost.get(i).get(j);          // current cell cost
                if (i == 0 && j == 0) {
                    dp[i][j] = cur;                    // start cell
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + cur;     // only from the left
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + cur;     // only from above
                } else {
                    dp[i][j] = cur + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1);   // denominator = number of visited cells
        return average;
    }
}

