class NewmanPrime {
    /**
     * Returns the n-th term of the Newman-Shanks-Williams sequence.
     * The sequence is defined by a(0) = 1, a(1) = 1, and a(n) = 2*a(n-1) + a(n-2) for n >= 2.
     *
     * @param n the index of the term to return (1-based)
     * @return the n-th term of the Newman-Shanks-Williams sequence
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // Handle the first two base cases
        if (n == 1) return 1; // a(1) = 1
        if (n == 2) return 3; // a(2) = 3

        long a0 = 1; // a(n-2)
        long a1 = 1; // a(n-1)

        for (int i = 3; i <= n; i++) {
            long a2 = 2 * a1 + a0; // a(n) = 2*a(n-1) + a(n-2)
            a0 = a1;
            a1 = a2;
        }
        return (int) a1;
    }

    // Optional main method for testing
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

