class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the term up to which the squares are summed (n ≥ 0)
     * @return the sum of squares from 1 to n
     *
     * Example:
     * seriesSum(6) → 91
     * seriesSum(7) → 140
     * seriesSum(12) → 650
     */
    public static int seriesSum(int number) {
        // Guard against non‑positive input
        if (number <= 0) {
            return 0;
        }

        // Use long to avoid intermediate overflow, then cast back to int
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;   // n(n+1)(2n+1)/6
        return (int) sum;
    }
}

