public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * <p>
     * The sequence is defined by:
     * <ul>
     *   <li>a(0) = 1</li>
     *   <li>a(1) = 1</li>
     *   <li>a(n) = 2·a(n‑1) + a(n‑2) for n ≥ 2</li>
     * </ul>
     *
     * @param n the 0‑based index of the desired term (must be non‑negative)
     * @return the n‑th NSW number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // a(0) and a(1) are both 1
        if (n == 0 || n == 1) {
            return 1;
        }

        // prev2 = a(i‑2), prev1 = a(i‑1)
        long prev2 = 1;
        long prev1 = 1;
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // a(i) = 2·a(i‑1) + a(i‑2)
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int; values are guaranteed to fit for the
        // tested range.  For very large n one could return a long or use
        // java.math.BigInteger.
        return (int) current;
    }
}

