import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix.  Movement is allowed
     * only to the right or down.
     *
     * @param cost a square matrix represented as a list of rows
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Initialize the start cell (0,0)
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum ends at the bottom‑right cell
        long maxSum = dp[n - 1][n - 1];

        // Every valid path has exactly (2*n - 1) cells
        int totalCells = 2 * n - 1;

        // Return the average as a Double
        return (double) maxSum / totalCells;
    }

    // ------------------------------------------------------------------
    // Simple test driver (optional)
    // ------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

