class NewmanPrime {
    /**
     * Write a function to find the nth Newman–Shanks–Williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The recurrence: a0 = 1, a1 = 1, a_n = 2*a_{n-1} + a_{n-2}
        long a0 = 1;
        long a1 = 1;

        if (n == 0) return (int) a0;
        if (n == 1) return (int) a1;

        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;   // compute a_i
            a0 = a1;           // shift for next iteration
            a1 = a;
        }
        return (int) a;         // the value fits in int for reasonable n
    }
}

