import java.util.List;

public class Maxaverageofpath {
    /**
     * Find the maximum average of any path from the top‑left to the bottom‑right
     * of an n×n cost matrix. Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    dimension of the square matrix
     * @return the maximum possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against invalid input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] holds the maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);          // current cell value

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // First row: can only come from the left
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    // First column: can only come from above
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    // General case: choose the larger of the two predecessors
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // The longest path from (0,0) to (n-1,n-1) contains (2*n-1) cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }
}

