class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            return 0; // Invalid input, return 0
        }
        if (n == 1) {
            return 3; // First NSW prime
        }

        List<Integer> primes = new ArrayList<>();
        BigInteger a0 = BigInteger.ONE;
        BigInteger a1 = BigInteger.ONE;
        BigInteger a = BigInteger.ZERO;

        // Generate NSW numbers and collect primes until we have at least (n-1) primes
        while (primes.size() < n - 1) {
            a = a0.multiply(BigInteger.valueOf(2)).add(a1);
            // Check if the current NSW number is prime
            if (a.isProbablePrime(100)) {
                primes.add(a.intValue());
            }
            // Update for next iteration
            a0 = a1;
            a1 = a;
        }

        // Return the (n-2)th prime (0-indexed)
        return primes.get(n - 2);
    }
}

