class TextMatchWordzMiddle {

    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        StringBuilder word = new StringBuilder();
        int n = text.length();

        for (int i = 0; i < n; i++) {
            char c = text.charAt(i);
            if (Character.isLetter(c)) {
                // still inside a word
                word.append(c);
            } else {
                // word ended – examine it
                if (word.length() > 0) {
                    if (containsZNotAtEdges(word.toString())) {
                        return "Found a match!";
                    }
                    word.setLength(0); // reset for next word
                }
            }
        }

        // check the last word (if the string ends with a letter)
        if (word.length() > 0) {
            if (containsZNotAtEdges(word.toString())) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    /**
     * Returns true if the given word (case‑insensitive) contains the letter 'z'
     * somewhere other than the first or last position.
     */
    private static boolean containsZNotAtEdges(String w) {
        String lower = w.toLowerCase(); // case‑insensitive
        int idx = lower.indexOf('z');
        // 'z' must be present and not at position 0 or at the last position
