import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum average value of a path that moves only right or down
     * from the top‑left corner to the bottom‑right corner of an n×n cost matrix.
     *
     * @param cost a list of n rows, each containing n integers
     * @param n    the dimension of the square matrix
     * @return the maximum average (as a Double) over all valid paths
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The path length is always (n‑1) right moves + (n‑1) down moves + 1 cell = 2·n‑1
        double maxSum = dp[n - 1][n - 1];
        return maxSum / (2 * n - 1);
    }
}

