class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)  for n >= 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // n is expected to be non‑negative; the first two values are 1.
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        if (n == 0) return 1; // a0
        if (n == 1) return 1; // a1

        int a0 = 1; // a(n‑2)
        int a1 = 1; // a(n‑1)
        int a  = 0; // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence
            a0 = a1;
            a1 = a;
        }
        return a;
    }
}

