class Maxaverageofpath {

    /**
     * Returns the maximum average value among all monotone paths
     * (right / down only) from the top‑left to the bottom‑right corner
     * of the given n×n cost matrix.
     *
     * @param cost  list of n rows, each row a list of n integers
     * @param n     size of the square matrix
     * @return      the maximal average as a Double, or null if the input
     *              is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.size() != n) {
            return null;
        }

        // DP table: double to avoid overflow when summing many numbers
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // fill first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // fill first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells: take the better of the two predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // maximal sum and corresponding average
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);
        return average;
    }

    // -----------------------------------------------------------------
    // Optional test driver (not required by the problem statement)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
