class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2·a(n‑1) + a(n‑2)  for n ≥ 2
     *
     * Example values:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n index (0‑based) of the desired number
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use BigInteger to avoid overflow for larger n
        BigInteger a0 = BigInteger.ONE; // a(0)
        BigInteger a1 = BigInteger.ONE; // a(1)
        BigInteger a  = BigInteger.ZERO;

        for (int i = 2; i <= n; i++) {
            // a(i) = 2 * a(i‑1) + a(i‑2)
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            // Shift the window
            a0 = a1;
            a1 = a;
        }

        // The method signature expects int; we truncate if the value exceeds Integer.MAX_VALUE
        return a.intValue();
    }
}

