     * @param cost the n×n matrix of path costs
     * @param n    the dimension of the square matrix
     * @return the maximum average value of a valid path, or null if input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP[i][j] = maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Start with the cost of the current cell
                dp[i][j] = cost.get(i).get(j).doubleValue();

                if (i == 0 && j == 0) {
                    // Starting cell – nothing to add
                    continue;
                }

                // Determine the best predecessor (from above or left)
                double best = 0.0;
                if (i > 0) {
                    best = dp[i - 1][j];
                }
                if (j > 0) {
                    best = Math.max(best, dp[i][j - 1]);
                }
                dp[i][j] += best;
            }
        }

        // The best sum at the destination (bottom‑right) cell
        double maxSum = dp[n - 1][n - 1];

        // Number of cells visited on any path from (0,0) to (n‑1, n‑1) = 2*n - 1
        double average = maxSum / (2 * n - 1);

        return average;
    }
}

