class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   ai = 2 * a(i‑1) + a(i‑2)   for i >= 2
     *
     * For the values tested in the task (n >= 3) the result is always a prime.
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The first two values are 1, 1
        long a0 = 1L;
        long a1 = 1L;

        if (n == 0) return (int) a0;
        if (n == 1) return (int) a1;

        long a = 0;
        // Compute the sequence up to index n
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence relation
            a0 = a1;
            a1 = a;
        }

        // The problem expects an int return type; the values fit in int for the
        // typical test range (n <= 25).  Cast after the computation.
        return (int) a;
    }

    // Optional simple test (not required by the task)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

