class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2 * a(n‑1) + a(n‑2)  for n >= 2
     *
     * @param n index (0‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iteratively compute the sequence
        long prev2 = 1; // a(i‑2)
        long prev1 = 1; // a(i‑1)
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            // shift the window
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int; the sequence fits in int for reasonable n.
        return (int) current;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        for (int i = 0; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

