import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a monotonic path
     * (only moves right or down) from the top‑left cell (0,0) to the
     * bottom‑right cell (n‑1,n‑1) in the given n×n cost matrix.
     *
     * @param cost  list of rows, each row a list of n integers
     * @param n     size of the square matrix
     * @return      the highest average (as a {@code Double}) among all such paths
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Defensive checks – you can adjust the behaviour as needed
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum reachable at cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum is at the bottom‑right corner.
        // Every monotonic path uses exactly (2*n - 1) cells,
        // so the average is sum / (2*n - 1).
        double maxSum = dp[n - 1][n - 1];
        return maxSum / (2 * n - 1);
    }

    // -----------------------------------------------------------------
    // A tiny demo (optional) to verify the three examples from the
    // problem statement.
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // expected 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // expected 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
