class CountVowels {
    /**
     * Counts consonants in the given string that have at least one vowel
     * as a neighbour (either to the left or to the right).  The first and
     * last characters are considered to have only one neighbour.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Use a Set for O(1) vowel look‑up; treat 'y' as a consonant.
        final Set<Character> vowels = Set.of('a', 'e', 'i', 'o', 'u');

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only count consonants (non‑vowels)
            if (vowels.contains(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0 && vowels.contains(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour
            if (i < len - 1 && vowels.contains(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

