class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     *
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)   for n >= 2
     *
     * The values for n = 3, 4, 5 are 7, 17, 41 respectively,
     * which are the 3rd, 4th and 5th NSW primes.
     *
     * @param n the index of the term to return (0‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // a0 = 1, a1 = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long prev2 = 1; // a(n‑2)
        long prev1 = 1; // a(n‑1)
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // an = 2*a(n‑1) + a(n‑2)
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int return type; overflow is possible for large n.
        return (int) current;
    }
}

