public class Maxaverageofpath {

    /**
     * Finds the maximum average of any path that starts at the top‑left corner
     * and ends at the bottom‑right corner of an n×n matrix.
     *
     * Movement is restricted to right or down steps only.
     *
     * @param cost  a square list of lists representing the n×n matrix
     * @param n     the dimension of the square matrix
     * @return      the maximum average value among all valid paths,
     *              or null if the input is invalid (e.g., n <= 0)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal arguments
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // DP[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                double val = cost.get(i).get(j); // cell value as double

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // First row: can only come from the left
                    dp[i][j] = val + dp[0][j - 1];
                } else if (j == 0) {
                    // First column: can only come from above
                    dp[i][j] = val + dp[i - 1][0];
                } else {
                    // General case: take the better of the two predecessors
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // The total number of cells visited on any valid path is (2*n - 1)
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // --------------------------------------------------------------------
    // Optional test driver (can be removed when integrating into a larger project)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
