import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all monotonic (right‑/down) paths
     * from the top‑left corner to the bottom‑right corner of the given n×n matrix.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Invalid cost matrix: must be non‑null and have n rows.");
        }
        for (List<Integer> row : cost) {
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Invalid cost matrix: each row must have n elements.");
            }
        }

        // dp[i][j] – maximum sum to reach cell (i, j) from (0,0)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // Maximum sum to reach the bottom‑right corner
        long maxSum = dp[n - 1][n - 1];

        // A monotonic path always contains exactly (2*n - 1) cells
        double average = maxSum / (double) (2 * n - 1);

        return average; // auto‑boxed to Double
    }

    // ---- Simple test driver (optional) ----
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

class CountVowels {
    /**
     * Counts characters (consonants) that have a vowel as an immediate neighbour
     * (either to the left or to the right).
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only count consonants; skip vowels themselves
            if (isVowel(ch)) {
                continue;
            }

            boolean leftIsVowel  = i > 0     && isVowel(testStr.charAt(i - 1));
            boolean rightIsVowel = i < len - 1 && isVowel(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

    /** Helper: returns true if the character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i'
            || lower == 'o' || lower == 'u';
    }

    // Optional test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));         // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

