class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * For n >= 3 this number is prime, so it serves as the n‑th NSW prime.
     *
     * Examples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     *
     * @param n the index (must be >= 1)
     * @return the n‑th NSW number
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // a(0) = 1, a(1) = 1
        long a0 = 1;
        long a1 = 1;

        // Compute a(n) using the recurrence a(i) = 2*a(i-1) + a(i-2)
        for (int i = 2; i <= n; i++) {
            long a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        // For n == 1 or n == 2 the loop never runs and a1 is 1,
        // which matches the definition of the sequence.
        return (int) a1;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

