class CountVowels {

    /** 
     * Counts characters (other than vowels) that have a vowel as one of their immediate neighbours.
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        // Guard against null or too‑short strings
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        // Normalise to lower‑case for easy vowel checking
        String s = testStr.toLowerCase();

        // Set of vowel characters
        final Set<Character> vowels = new HashSet<>();
        for (char c : "aeiou".toCharArray()) {
            vowels.add(c);
        }

        int count = 0;
        int len = s.length();

        for (int i = 0; i < len; i++) {
            char current = s.charAt(i);

            // We only count consonants (characters that are NOT vowels)
            if (vowels.contains(current)) {
                continue; // skip vowels
            }

            boolean hasVowelNeighbour = false;

            // Check left neighbour
            if (i > 0 && vowels.contains(s.charAt(i - 1))) {
                hasVowelNeighbour = true;
