            // Check right neighbour (only if not already found)
            if (!hasVowelNeighbour && i < len - 1 && vowels.contains(s.charAt(i + 1))) {
                hasVowelNeighbour = true;
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }

        return count;
    }

