     * Write a function to find the nth Newman–Shanks–Williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // The first two terms of the sequence are 1, 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long prev2 = 1; // a(n‑2)
        long prev1 = 1; // a(n‑1)
        long current = 0;

        // Compute a(i) = 2*a(i‑1) + a(i‑2) for i = 2 … n
        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }

        // The sequence grows quickly; use long during the calculation
        return (int) current;
    }
}

