public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts in the
     * upper‑left cell (0,0) of the given n×n matrix and ends in the lower‑right
     * cell (n‑1,n‑1).  Moving is allowed only to the right or down.
     *
     * Because every admissible path contains exactly (2·n‑1) cells,
     * maximizing the average is equivalent to maximizing the sum of the visited
     * cells.  We therefore compute the maximal sum with a classic DP table.
     *
     * @param cost  a square matrix represented as a list of rows
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximal average as a {@code Double}, or {@code null} if
     *              the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // ---- DP table: maximal sum to reach each cell ------------------------
        double[][] dp = new double[n][n];

        // (0,0)
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells – take the better predecessor (up or left)
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute the average ---------------------------------------------
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);   // number of cells in any path
        return average;
    }

    // -------------------------------------------------------------------------
    // The following two methods demonstrate the use of @Override as advised
    // in Item 40.  They are not required for the core algorithm but are kept
    // to show good practice.
    // -------------------------------------------------------------------------

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        // This class has no instance state, so all instances are considered equal.
        return true;
    }

    @Override
    public int hashCode() {
        // For a class with no instance fields the hash code can be constant.
        return 42;
    }

    // -------------------------------------------------------------------------
    // A tiny driver to verify the three examples from the problem statement.
    // -------------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
