/**
 * Utility class for counting characters that are adjacent to a vowel.
 */
class CountVowels {

    /***
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * @param testStr the input string
     * @return the number of non‑vowel characters that have at least one vowel neighbour
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowel characters (both lower‑ and upper‑case)
        final String VOWELS = "aeiouAEIOU";

        int count = 0;
        int n = testStr.length();

        for (int i = 0; i < n; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only count consonants
            if (VOWELS.indexOf(ch) != -1) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0) {
                char left = testStr.charAt(i - 1);
                if (VOWELS.indexOf(left) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbour (only if we haven't already found a vowel neighbour)
            if (!hasVowelNeighbor && i < n - 1) {
                char right = testStr.charAt(i + 1);
                if (VOWELS.indexOf(right) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // ------------------------------------------------------------------
    // Optional main method for quick manual testing
    // ------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

