class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms to include (must be non‑negative)
     * @return the sum of squares from 1² up to number²
     *
     * Example:
     * <pre>
     * seriesSum(6) → 91
     * seriesSum(7) → 140
     * seriesSum(12) → 650
     * </pre>
     */
    public static int seriesSum(int number) {
        // Handle non‑positive input
        if (number <= 0) {
            return 0;
        }

        int sum = 0;
        for (int i = 1; i <= number; i++) {
            sum += i * i;   // add i² to the running total
        }
        return sum;
    }

