class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams prime sequence.
     * The sequence is defined by:
     *   a(1) = 1
     *   a(2) = 3
     *   a(n) = 2*a(n‑1) + a(n‑2)  for n > 2
     *
     * @param n the 1‑based index (must be > 0)
     * @return the n‑th term of the sequence
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        if (n == 1) return 1;
        if (n == 2) return 3;

        long aPrev2 = 1; // a(i‑2)
        long aPrev1 = 3; // a(i‑1)

        for (int i = 3; i <= n; i++) {
            long aCurrent = 2 * aPrev1 + aPrev2;
            aPrev2 = aPrev1;
            aPrev1 = aCurrent;
        }

        return (int) aPrev1;
    }

    // Simple test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

