import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class TextMatchWordzMiddle {

    /**
     * Determines whether any word in the given text contains the letter 'z'
     * that is not at the start or the end of the word.
     *
     * @param text the input text to be examined
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            // Defensive check – treat null as no match
            return "Not matched!";
        }

        // Pattern that matches a sequence of one or more letters (a word)
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int len = word.length();

            // A 'z' can only be in the middle if the word is at least 3 characters long
            if (len < 3) {
                continue;
            }

            // Look for the first occurrence of 'z' (case‑sensitive)
            int zIndex = word.indexOf('z');

            // If 'z' is present and is neither the first nor the last character → match
            if (zIndex != -1 && zIndex != 0 && zIndex != len - 1) {
                return "Found a match!";
            }
        }

        // No qualifying word was found
        return "Not matched!";
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));     // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

