class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts at the
     * top‑left cell (0,0) and ends at the bottom‑right cell (n‑1,n‑1) while
     * moving only right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the square matrix
     * @return the maximum average (as a {@code Double}) or {@code null} if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against bad input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP[i][j] – maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The path always contains exactly (2 * n - 1) cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

