class SeriesSum {
    /**
     * Calculates the sum of the squares of the first {@code number} positive integers.
     *
     * <p>The formula used is:
     * <pre>
     *     Σ i² = n·(n + 1)·(2n + 1) / 6
     * </pre>
     *
     * @param number the upper bound (n). Must be non‑negative.
     * @return the sum 1² + 2² + … + n² as an {@code int}.
     * @throws IllegalArgumentException if {@code number} is negative.
     */
    public static int seriesSum(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative");
        }

        // Use long for the intermediate multiplication to avoid overflow
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The problem statement expects an int return type.
        return (int) sum;
    }
}

