class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   s0 = 1, s1 = 1
     *   sn = 2·sn‑1 + sn‑2   for n ≥ 2
     *
     * For n ≥ 2 the values are primes (3, 7, 17, 41, …).
     *
     * @param n the index of the desired term (0‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        // Base cases: s0 = 1, s1 = 1
        if (n <= 1) {
            return 1;
        }

        long prev2 = 1; // s0
        long prev1 = 1; // s1
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // sn = 2·sn‑1 + sn‑2
            prev2 = prev1;
            prev1 = current;
        }

        // The problem guarantees that n is small enough to fit in an int.
        return (int) current;
    }
}

