import java.lang.*;
import java.math.*;

class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron given the length of its side.
     *
     * @param num the length of each edge of the tetrahedron
     * @return the volume, rounded to two decimal places
     */
    public static Double volumeTetrahedron(int num) {
        // Convert the side length to double for the computation
        double a = num;

        // Volume formula for a regular tetrahedron: V = a^3 / (6 * sqrt(2))
        double volume = (Math.pow(a, 3.0)) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places to match the expected output
        double roundedVolume = Math.round(volume * 100.0) / 100.0;

        return roundedVolume;
    }

    // Optional simple test driver
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

