class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split the input into words (whitespace‑separated)
        String[] words = text.split("\\s+");

        // Examine each word
        for (String word : words) {
            // Look for a 'z' that is not the first or last character
            for (int i = 0; i < word.length(); i++) {
                if (word.charAt(i) == 'z' && i > 0 && i < word.length() - 1) {
                    return "Found a match!";
                }
            }
        }

        // No suitable 'z' was found
        return "Not matched!";
    }

    // Optional quick test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));     // "Not matched!"
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    double[][] dp = new double[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            double cellCost = cost.get(i).get(j); // automatically promoted to double
            if (i == 0 && j == 0) {
                dp[i][j] = cellCost;
            } else {
                double best = -Double.MAX_VALUE;
                if (i > 0) best = Math.max(best, dp[i - 1][j]);
                if (j > 0) best = Math.max(best, dp[i][j - 1]);
                dp[i][j] = cellCost + best;
            }
        }
    }
    double maxSum = dp[n - 1][n - 1];
    double average = maxSum / (2 * n - 1);
    return average;
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Null or empty string yields zero
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only count non‑vowel characters
            if (!isVowel(ch)) {
                boolean hasVowelNeighbor = false;

                // Check left neighbour
                if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // Check right neighbour
                if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Helper that returns true if the given character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u';
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));         // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

