    }
}

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

/**
 * Utility class for computing Newman‑Shanks‑Williams (NSW) primes.
 *
 * The NSW sequence is defined by:
 *   a(0) = 1, a(1) = 1,
 *   a(n) = 2·a(n‑1) + a(n‑2)   for n ≥ 2.
 *
 * The NSW primes are the prime values among the a(n).  The first few are:
 *   3, 7, 17, 41, 239, 577, …
 *
 * This implementation expects n ≥ 2, where:
 *   newmanPrime(2) = 3,
 *   newmanPrime(3) = 7,
 *   newmanPrime(4) = 17,
 *   …
 */
public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     *
     * @param n the index (must be ≥ 2) of the NSW prime to retrieve
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n < 2
     */
    public static int newmanPrime(int n) {
        if (n < 2) {
            throw new IllegalArgumentException("n must be at least 2");
        }

        // List to store the NSW primes we discover
        List<Integer> nswPrimes = new ArrayList<>();

        // a(0) = 1, a(1) = 1
        BigInteger a0 = BigInteger.ONE; // a(i‑2)
        BigInteger a1 = BigInteger.ONE; // a(i‑1)
        BigInteger a; // a(i)

        // Generate NSW numbers starting from index 2
        for (int i = 2; nswPrimes.size() < n - 1; i++) {
            // a(i) = 2·a(i‑1) + a(i‑2)
            a = a0.multiply(BigInteger.TWO).add(a1);

            // If a(i) is prime, store it
            if (a.isProbablePrime(100)) {
                nswPrimes.add(a.intValue());
            }

            // Shift the window for the next iteration
            a0 = a1;
            a1 = a;
        }

        // The required prime is at index (n‑2) (0‑based)
        return nswPrimes.get(n - 2);
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

