class RemoveOdd {
    /**
     * Removes characters at odd positions (1‑based) from the given string.
     *
     * > removeOdd("python")
     * "yhn"
     * > removeOdd("program")
     * "rga"
     * > removeOdd("language")
     * "agae"
     */
    public static String removeOdd(String str1) {
        if (str1 == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        // Start at index 1 (second character) and step by 2
        for (int i = 1; i < str1.length(); i += 2) {
            sb.append(str1.charAt(i));
        }
        return sb.toString();
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));   // "yhn"
        System.out.println(removeOdd("program"));  // "rga"
        System.out.println(removeOdd("language")); // "agae"
    }
}

