class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the supplied text contains a word
     * that has the letter 'z' (either lower‑ or upper‑case) somewhere
     * other than the first or last character of the word.
     * Otherwise returns "Not matched!".
     *
     * Examples:
     *   "pythonzabc." → Found a match!
     *   "xyzabc."     → Found a match!
     *   "  lang  ."   → Not matched!
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        StringBuilder word = new StringBuilder();

        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);
            if (Character.isLetter(ch)) {
                // Build the current word
                word.append(ch);
            } else {
                // End of a word – examine it
                if (matches(word.toString())) {
                    return "Found a match!";
                }
                // Reset for the next word
                word.setLength(0);
            }
        }

        // Check the final word (in case the string ends with letters)
        if (matches(word.toString())) {
            return "Found a match!";
        }

        return "Not matched!";
    }

    /**
     * Helper that decides whether a given word satisfies the required condition:
     * 1. Its length is at least 3 (otherwise 'z' could not be in the middle).
     * 2. The first and last characters are not 'z' (case‑insensitive).
     * 3. The word contains at least one 'z' (case‑insensitive) somewhere inside.
     */
    private static boolean matches(String w) {
        if (w.length() < 3) {
            return false;
        }

        // Work with a lower‑case copy for case‑insensitive comparison
        String lower = w.toLowerCase();
        char first = lower.charAt(0);
        char last  = lower.charAt(lower.length() - 1);

        // 'z' must not be the first or last character
        if (first == 'z' || last == 'z') {
            return false;
        }

        // There must be a 'z' somewhere inside the word
        return lower.contains("z");
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class Maxaverageofpath {
    /**
     * Find a path with the maximum average over all existing paths for the given
     * square matrix of size n*n.  Movement is restricted to right and down.
     *
     * @param cost 2‑D list representing the n×n matrix of integers
     * @param n    size of the square matrix
     * @return     the maximum possible average (as a Double)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive: if n is given but the list size differs, use the list size
        if (n != cost.size()) {
            n = cost.size();
        }

        // dp[i][j] = maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // total number of cells in any valid path = (n‑1) downs + (n‑1) rights + 1 start
        int pathLength = 2 * n - 1;
        double maxAverage = dp[n - 1][n - 1] / pathLength;

        return maxAverage;
    }

    // Simple test (optional)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

import java.io.*;
import java.lang.*;
