import java.math.*;

class CountVowels {
    /**
     * Counts consonants in {@code testStr} that have a vowel as one of their
     * immediate neighbours (either to the left or to the right).
     *
     * @param testStr the input string (may contain upper‑case letters)
     * @return the number of such consonants
     *
     * <p>Examples:
     * <ul>
     *   <li>{@code countVowels("bestinstareels")} → 7</li>
     *   <li>{@code countVowels("partofthejourneyistheend")} → 12</li>
     *   <li>{@code countVowels("amazonprime")} → 5</li>
     * </ul>
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work case‑insensitively
        String s = testStr.toLowerCase();

        // Vowel set (both lower‑case and upper‑case are covered by toLowerCase)
        final String vowels = "aeiou";

        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);

            // Only consider consonants; skip vowels
            if (vowels.indexOf(ch) != -1) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbour = false;
            if (i > 0 && vowels.indexOf(s.charAt(i - 1)) != -1) {
                hasVowelNeighbour = true;
            }
            // Check right neighbour (if not already found)
            if (!hasVowelNeighbour && i < s.length() - 1 && vowels.indexOf(s.charAt(i + 1)) != -1) {
                hasVowelNeighbour = true;
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }
        return count;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));          // 5
    }
}

