class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms (n)
     * @return the sum of squares from 1 to n
     *
     * @example
     * <pre>
     * seriesSum(6)  // returns 91
     * seriesSum(7)  // returns 140
     * seriesSum(12) // returns 650
     * </pre>
     */
    public static int seriesSum(int number) {
        // Use long to avoid overflow while computing the intermediate product.
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;
        return (int) sum;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

