    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

/**
 * Solutions to the “Newman‑Shanks‑Williams prime” problem.
 *
 * The sequence is defined by:
 *   a(0) = 1, a(1) = 1,
 *   a(n) = 2·a(n‑1) + a(n‑2)  (n ≥ 2)
 *
 * The 3rd, 4th and 5th terms are 7, 17 and 41, which are the first
 * three primes of the sequence.
 */
class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     *
     * @param n the index (0‑based).  n = 0 → 1, n = 1 → 1,
     *          n = 2 → 3, n = 3 → 7, …
     * @return the value a(n)
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iteratively compute a(i) = 2*a(i‑1) + a(i‑2)
        long prev2 = 1; // a(i‑2)
        long prev1 = 1; // a(i‑1)
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }

        // The result fits in an int for the typical problem constraints
        return (int) current;
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

