public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(1) = 1, a(2) = 3,
     *   a(i) = 2·a(i‑1) + a(i‑2)  for i ≥ 3.
     *
     * @param n the index (1‑based) of the desired number
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // First two values of the sequence
        if (n == 1) return 1;   // a(1)
        if (n == 2) return 3;   // a(2)

        // Use long to avoid overflow while computing the intermediate values
        long prevPrev = 1L; // a(i‑2)  → a(1)
        long prev     = 3L; // a(i‑1)  → a(2)
        long current  = 0L;

        for (int i = 3; i <= n; i++) {
            current = 2 * prev + prevPrev; // a(i) = 2·a(i‑1) + a(i‑2)
            prevPrev = prev;
            prev = current;
        }

        // The result fits in an int for reasonable input sizes;
        // cast back to int as the method’s return type is int.
        return (int) current;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // → 7
        System.out.println(newmanPrime(4)); // → 17
        System.out.println(newmanPrime(5)); // → 41
    }
}

