            if (!hasVowelNeighbour && i < n - 1 && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
                hasVowelNeighbour = true;
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }

        return count;
    }

