import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     *
     * The NSW numbers are defined by:
     *   N0 = 1, N1 = 1,
     *   Ni = 2*Ni‑1 + Ni‑2   (i ≥ 2)
     *
     * The NSW primes are the primes among the Ni.
     * The first NSW prime is N2 = 3, the second is N3 = 7, etc.
     *
     * @param n the index (≥ 1) of the NSW prime to return
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // N0 = 1, N1 = 1
        long prev2 = 1L; // Ni‑2
        long prev1 = 1L; // Ni‑1
        int primesFound = 0;

        // start generating from i = 2 (N2)
        while (true) {
            long current = 2 * prev1 + prev2; // Ni = 2*Ni‑1 + Ni‑2

            if (isPrime(current)) {
                primesFound++;
                if (primesFound == n) {
                    // the result always fits into int for reasonable n
                    return (int) current;
                }
            }

            // shift the window for the next iteration
            prev2 = prev1;
            prev1 = current;
        }
    }

    /**
     * Simple deterministic primality test for numbers that fit in a 32‑bit int.
     * Checks divisibility up to √num using the 6k ± 1 optimization.
     */
    private static boolean isPrime(long num) {
        if (num < 2) return false;
        if (num % 2 == 0) return num == 2;
        if (num % 3 == 0) return num == 3;

        long limit = (long) Math.sqrt(num);
        for (long i = 5; i <= limit; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    // ---- simple test harness ----
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

