class CountVowels {

    // Lambda that returns true if a character is a vowel (a, e, i, o, u)
    private static final Predicate<Character> IS_VOWEL = c ->
        "aeiou".indexOf(Character.toLowerCase(c)) >= 0;

    /**
     * Counts characters that are **not** vowels but have at least one vowel
     * neighbour (left or right).  The first and last characters are checked
     * using only the existing neighbour.
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only count non‑vowel characters that are next to a vowel
            if (IS_VOWEL.test(ch)) {
                continue;
            }

            boolean leftIsVowel  = i > 0 && IS_VOWEL.test(testStr.charAt(i - 1));
            boolean rightIsVowel = i < len - 1 && IS_VOWEL.test(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

