class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // The NSW sequence is defined by:
        // p0 = 1, p1 = 1, pn = 2 * p(n-1) + p(n-2) for n >= 2
        long prev2 = 1; // p0
        long prev1 = 1; // p1
        if (n == 1) return (int) prev1; // p1 = 1 (not prime, but returned as per definition)
        if (n == 2) return (int) (2 * prev1 + prev2); // p2 = 3

        long current = 0;
        for (int i = 3; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        return (int) current;
    }
}

