public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the input text contains a word that has the
     * letter 'z' somewhere other than the first or last character.
     * Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")      → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")    → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches whole words (letters, digits, underscore).
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A word shorter than 3 characters cannot have a middle 'z'.
            if (word.length() < 3) {
                continue;
            }

            // Look for a 'z' that is not at position 0 or at the last position.
            boolean hasMiddleZ = false;
            for (int i = 1; i < word.length() - 1; i++) {
                if (word.charAt(i) == 'z') {
                    hasMiddleZ = true;
                    break;
                }
            }

            if (hasMiddleZ) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a monotone (right/down) path
     * from the top‑left corner to the bottom‑right corner of the given
     * n×n cost matrix.
     *
     * @param cost square matrix of integers (List of rows)
     * @param n    size of the matrix (number of rows/columns)
     * @return     maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.size() != n || n <= 0) {
            return null;
        }

        // dp[i][j] = best sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cellValue = cost.get(i).get(j); // safe, we validated sizes

                if (i == 0 && j == 0) {
                    dp[i][j] = cellValue;
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + cellValue;
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + cellValue;
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cellValue;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1);   // denominator is constant
        return average;
    }
}

