import java.math.*;

class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // List to store NSW primes
        List<Integer> primes = new ArrayList<>();
        primes.add(2); // First NSW prime

        // Initialize sequence: a0 = 1, a1 = 1
        long a0 = 1, a1 = 1;

        // Generate sequence until we have n primes
        while (primes.size() < n) {
            // Compute next term: a_n = 2 * a_{n-1} + a_{n-2}
            long a2 = 2 * a1 + a0;

            // Update previous terms
            a0 = a1;
            a1 = a2;

            // Check if a2 is prime and add to list if so
            if (isPrime(a2)) {
                primes.add((int) a2);
            }
        }

        // Return the nth prime (1-indexed)
        return primes.get(n - 1);
    }

    /**
     * Helper method to check if a number is prime.
     */
    private static boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

