class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches a whole word (sequence of letters)
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // the actual word
            // Perform a case‑insensitive search for 'z'
            int idx = word.toLowerCase().indexOf('z');
            // z must not be the first or last character of the word
            if (idx > 0 && idx < word.length() - 1) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));    // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));  // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner of the given n×n matrix and ends at the bottom‑right
     * corner.  Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against bad input
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] holds the greatest possible sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Base cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table using the method reference Math::max
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j)
                           + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // All valid paths have exactly (2*n‑1) cells, so the average is
        // maxSum / (2*n‑1)
        double maxAvg = dp[n - 1][n - 1] / (double) (2 * n - 1);
        return Double.valueOf(maxAvg);
    }
}

