class CountVowels {
    /** Vowels (both lower‑ and upper‑case are handled). */
    private static final String VOWELS = "aeiou";

    /**
     * Counts characters that are not vowels and that have at least one vowel
     * as an immediate neighbour (left or right).
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() < 2) {
            return 0;                 // no possible neighbours
        }

        // Stream of indices, keep those that satisfy the required condition
        return (int) IntStream.range(0, testStr.length())
                .filter(i -> {
                    char c = testStr.charAt(i);
                    if (isVowel(c)) {
                        return false; // we only count consonants
                    }
                    boolean leftVowel  = i > 0 && isVowel(testStr.charAt(i - 1));
                    boolean rightVowel = i < testStr.length() - 1 &&
                                          isVowel(testStr.charAt(i + 1));
                    return leftVowel || rightVowel;
                })
                .count();
    }

    /** Helper: case‑insensitive vowel test. */
    private static boolean isVowel(char c) {
        return VOWELS.indexOf(Character.toLowerCase(c)) >= 0;
    }

    // ---- simple test driver ----
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

