public class CountAlphaDigSpl {

    /**
     * Returns a list containing the count of alphabetic characters,
     * digits, and special characters in the given string.
     *
     * @param string the input text (may be null)
     * @return a List of three integers: [alphabets, digits, specials]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        // Method references make the intent clear and the code concise
        long alphabets = string.chars().filter(Character::isLetter).count();
        long digits    = string.chars().filter(Character::isDigit).count();

        // Special characters are anything that is neither a letter nor a digit
        long specials  = string.chars()
                               .filter(c -> !Character.isLetter(c) && !Character.isDigit(c))
                               .count();

        // Convert long counts to int as required by the return type
        return Arrays.asList((int) alphabets, (int) digits, (int) specials);
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));     // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

