class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n of the series
     * @return the sum of squares from 1 to n
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Use a stream of integers from 1 to 'number', square each via a method reference,
        // then reduce with Integer::sum (also a method reference).
        return IntStream.rangeClosed(1, number)
                        .map(SeriesSum::square)   // method reference for squaring
                        .reduce(0, Integer::sum); // method reference for addition
    }

    // Helper method to compute the square of an int; referenced above.
    private static int square(int i) {
        return i * i;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));  // 91
        System.out.println(seriesSum(7));  // 140
        System.out.println(seriesSum(12)); // 650
    }
}

