class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2 * a(n‑1) + a(n‑2)   for n >= 2.
     *
     * The values for small n are:
     *   n = 2 → 3
     *   n = 3 → 7
     *   n = 4 → 17
     *   n = 5 → 41
     *
     * @param n the index (must be >= 1)
     * @return the n‑th term of the Newman–Shanks–Williams sequence
     * @throws IllegalArgumentException if n is less than 1
     */
    public static int newmanPrime(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n must be at least 1");
        }

        // Handle the base cases a(0) and a(1) – both equal to 1.
        if (n == 1) {
            return 1;
        }

        long a0 = 1; // a(0)
        long a1 = 1; // a(1)
        long a = 0;  // will hold a(n)

        // Compute a(2) … a(n)
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }

        // The sequence grows quickly; we return the result as an int.
        // For realistic inputs (n ≤ 31) the value fits in an int.
        return (int) a;
    }
}

