class RemoveOdd {
    /**
     * Write a function to remove odd characters in a string.
     *
     * > removeOdd("python")
     * "yhn"
     * > removeOdd("program")
     * "rga"
     * > removeOdd("language")
     * "agae"
     */
    public static String removeOdd(String str1) {
        // Guard against null input
        if (str1 == null) {
            return null;
        }

        // Keep characters whose index is odd (1, 3, 5, …)
        return IntStream.range(0, str1.length())
                .filter(i -> i % 2 == 1)            // keep odd‑indexed positions
                .mapToObj(str1::charAt)             // method reference: charAt
                .collect(StringBuilder::new,
                         StringBuilder::append,
                         StringBuilder::append)
                .toString();
    }
}

