import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left
     * cell and ends at the bottom‑right cell of the given n×n matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of path costs
     * @param n    the dimension of the square matrix
     * @return the maximum average value among all valid paths
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive checks – the list sizes should match n
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Invalid matrix dimensions");
        }

        // DP array: maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Initialize the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the DP table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The path length is (2 * n - 1) cells (including both ends)
        int pathLength = 2 * n - 1;
        double maxAverage = (double) dp[n - 1][n - 1] / pathLength;

        return maxAverage;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // expected 5.2

        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // expected 6.2

        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // expected 7.2
    }
}

