class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbours in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with a lower‑case copy so the vowel test is case‑insensitive
        String s = testStr.toLowerCase();

        // Use an IntStream to process each index.  Keep a character only if:
        //   • it is NOT a vowel (i.e., a consonant)
        //   • and it has at least one neighbour (left or right) that IS a vowel
        return (int) IntStream.range(0, s.length())
                .filter(i -> {
                    char c = s.charAt(i);
                    if (isVowel(c)) {
                        return false;               // we don’t count vowels themselves
                    }
                    boolean leftVowel  = i > 0          && isVowel(s.charAt(i - 1));
                    boolean rightVowel = i < s.length() - 1 && isVowel(s.charAt(i + 1));
                    return leftVowel || rightVowel;    // at least one vowel neighbour
                })
                .count();
    }

    /** Helper that tells whether a given character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend"));// 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

