/**
 *  NewmanPrime – returns the n‑th term of the Newman‑Shanks‑Williams sequence.
 *
 *  The sequence is defined by
 *      s(0) = 1, s(1) = 1
 *      s(n) = 2·s(n‑1) + s(n‑2)   for n ≥ 2
 *
 *  The first few terms that are prime are 3, 7, 17, 41, …
 *
 *  Examples:
 *      newmanPrime(3) → 7
 *      newmanPrime(4) → 17
 *      newmanPrime(5) → 41
 */
public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * @param n the index (must be non‑negative)
     * @return the value of s(n)
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute the sequence iteratively
        long prev2 = 1; // s(i‑2)
        long prev1 = 1; // s(i‑1)
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            // Shift the window for the next iteration
            prev2 = prev1;
            prev1 = current;
        }

        // The result fits into an int for the typical range of n used in the kata
        return (int) current;
    }

    // Simple test harness (feel free to remove)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

public static String removeOdd(String str1) {
    if (str1 == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();

    // start at index 1 (the second character) and step by 2
    for (int i = 1; i < str1.length(); i += 2) {
        result.append(str1.charAt(i));
    }

    return result.toString();
}

