        };

        // Scan each word in the input text
        while (matcher.find()) {
            String word = matcher.group();
            if (hasMiddleZ.test(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class Maxaverageofpath {
    /**
     * Write a function to find a path with the maximum average over all existing
     * paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive check
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = max sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);          // the cost of the current cell

                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    // take the better of the two possible previous cells
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // every path from (0,0) to (n‑1,n‑1) using only right/down moves
        // contains exactly (2*n‑1) cells
        double average = maxSum / (2 * n - 1);

        return average;
    }
}

