class CountVowels {

    /**
     * Counts characters that are not vowels and have at least one vowel neighbour.
     *
     * @param testStr the input string (may contain mixed case letters)
     * @return the required count
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // skip vowels themselves
            if (isVowel(ch)) {
                continue;
            }

            boolean leftIsVowel  = i > 0         && isVowel(testStr.charAt(i - 1));
            boolean rightIsVowel = i < len - 1 && isVowel(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

    /** Helper: returns true if c is a vowel (case‑insensitive). */
    private static boolean isVowel(char c) {
        char lower = Character.toLowerCase(c);
        return lower == 'a' || lower == 'e' ||
               lower == 'i' || lower == 'o' || lower == 'u';
    }

    // ---- optional test driver ----
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

