public static int newmanPrime(int n) {
    // The recurrence is defined for n >= 0.
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }
    // a0 = 1, a1 = 1
    if (n == 0 || n == 1) {
        return 1;
    }

    int aPrev2 = 1; // a_{i‑2}
    int aPrev1 = 1; // a_{i‑1}
    int aCurrent = 0;

    for (int i = 2; i <= n; i++) {
        // a_i = 2 * a_{i‑1} + a_{i‑2}
        aCurrent = 2 * aPrev1 + aPrev2;
        // shift the window for the next iteration
        aPrev2 = aPrev1;
        aPrev1 = aCurrent;
    }
    return aCurrent;
}

