class VolumeTetrahedron {
    /**
     * * Write a function to calculate volume of a tetrahedron.
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        // Use the standard functional interface Function<Integer,Double>
        // instead of a custom functional interface.
        Function<Integer, Double> volumeFunc = n -> {
            // Volume of a regular tetrahedron: V = a^3 / (6 * sqrt(2))
            double v = Math.pow(n, 3) / (6.0 * Math.sqrt(2.0));
