import java.util.List;

class Maxaverageofpath {
    /**
     * Returns the maximum average of any path that starts at the upper‑left cell
     * and ends at the lower‑right cell of the given n×n cost matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost a list of n rows, each a list of n integers representing cell costs
     * @param n    the dimension of the square matrix (number of rows/columns)
     * @return the maximum possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] holds the greatest sum reachable at (i, j)
        long[][] dp = new long[n][n];

        // Initialize the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table using the standard functional method Math::max
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum is in the bottom‑right corner
        long maxSum = dp[n - 1][n - 1];

        // Every path from (0,0) to (n‑1,n‑1) has exactly (2*n‑1) cells
        double average = (double) maxSum / (2 * n - 1);

        // Return the result as a boxed Double (as required by the method signature)
        return Double.valueOf(average);
    }
}

