import java.util.function.Predicate;

public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     * The sequence of NSW numbers is defined by:
     *   N0 = 1, N1 = 1,
     *   Nn = 2·N(n‑1) + N(n‑2)  (n ≥ 2).
     * The NSW primes are the primes that appear in this sequence.
     *
     * According to the examples given in the task,
     * the first NSW prime considered is 7 (the prime at index 3).
     * Hence newmanPrime(3) = 7, newmanPrime(4) = 17, newmanPrime(5) = 41, …
     *
     * @param n the position (must be ≥ 1)
     * @return the n‑th NSW prime as described above
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Special handling for the first two values (optional, matches the usual list)
        if (n == 1) return 3;   // first NSW prime (normally 3)
        if (n == 2) return 7;   // second NSW prime (normally 7)

        // We need the (n‑2)-th prime starting from index 3 of the NSW sequence.
        // Generate the sequence and count primes.
        Predicate<Long> isPrime = p -> {
            if (p < 2) return false;
            if (p == 2) return true;
            if (p % 2 == 0) return false;
            for (long d = 3; d * d <= p; d += 2) {
                if (p % d == 0) return false;
            }
            return true;
        };

        // aPrev2 = N(i‑2), aPrev1 = N(i‑1)
        long aPrev2 = 1; // N0
        long aPrev1 = 1; // N1

        // Compute N2 = 3
        long current = 2 * aPrev1 + aPrev2; // N2 = 3
        // shift for the next iteration
        aPrev2 = aPrev1; // now N1
        aPrev1 = current; // now N2

        // Now generate from index 3 onward (i = 3)
        int primeCount = 0;
        int target = n - 2; // we need this many primes from index ≥3

        while (true) {
            // compute next NSW number N_i
            current = 2 * aPrev1 + aPrev2;

            if (isPrime.test(current)) {
                primeCount++;
                if (primeCount == target) {
                    return (int) current;
                }
            }

            // shift for the next step
            aPrev2 = aPrev1;
            aPrev1 = current;
        }
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

