        DoubleUnaryOperator volumeCalc = a -> Math.pow(a, 3) / (6.0 * Math.sqrt(2.0));

        // Compute the volume for the given side length.
        double volume = volumeCalc.applyAsDouble(num);

        // Round to two decimal places (as required by the examples).
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Return the result as a Double (boxed).
        return rounded;
    }
}

