import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given
     * n×n matrix. Movement is allowed only to the right or downwards.
     *
     * @param cost  the square matrix represented as a list of rows
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximal average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: double is used to avoid overflow when the sum is large
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double cur = cost.get(i).get(j).doubleValue();

                if (i == 0 && j == 0) {
                    // starting cell
                    dp[i][j] = cur;
                } else {
                    double fromTop = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double fromLeft = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = cur + Math.max(fromTop, fromLeft);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        int totalCells = 2 * n - 1;            // cells visited on any valid path
        return maxSum / totalCells;
    }

    // --------------------------------------------------------------------
    // Simple manual test harness (not required for the solution itself)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // Expected: 7.2
