class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1,
     *   an = 2 * a(n‑1) + a(n‑2)  for n >= 2.
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman–Shanks–Williams number
     */
    public static int newmanPrime(int n) {
        // Handle the first two base cases
        if (n <= 1) {
            return 1;               // a0 = a1 = 1
        }

        int a0 = 1; // a(n‑2)
        int a1 = 1; // a(n‑1)
        int a = 0;  // a(n) – the term we will compute

        // Compute the sequence iteratively up to index n
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence relation
            // Shift the window for the next iteration
            a0 = a1;
            a1 = a;
        }

        return a;
    }

    // Simple test (optional)
    public static void main(String[] args) {
        // Example calls from the problem statement
        System.out.println(newmanPrime(3)); // → 7
        System.out.println(newmanPrime(4)); // → 17
        System.out.println(newmanPrime(5)); // → 41
    }
}

class RemoveOdd {
    /**
     * Removes characters at even positions (0‑indexed) and returns a string
     * containing only the characters at odd positions (1‑indexed).
     *
     * @param str1 the input string (may be null)
     * @return a new string consisting of the characters at odd indices,
     *         or null if the input is null
     */
    public static String removeOdd(String str1) {
        if (str1 == null) {
            return null;               // preserve null semantics
        }

        StringBuilder sb = new StringBuilder(str1.length() / 2 + 1);
        // start at index 1 (the second character) and step by 2
        for (int i = 1; i < str1.length(); i += 2) {
            sb.append(str1.charAt(i));
        }
        return sb.toString();
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
