public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given
     * n×n matrix. Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of non‑negative integers
     * @param n    size of the matrix
     * @return the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || n <= 0) {
            return 0.0;
        }

        // DP table, long to avoid overflow
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long val = cost.get(i).get(j);          // value of current cell

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else {
                    long best = 0;
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]); // from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]); // from left
                    }
                    dp[i][j] = best + val;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2L * n - 1);
        return average;
    }
}

