class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(k) = 2 * a(k‑1) + a(k‑2)   for k >= 2
     *
     * @param n 1‑based index of the required term (n >= 1)
     * @return the n‑th Newman–Shanks–Williams number
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        long a = 1;   // a(0)
        long b = 1;   // a(1)

        // Compute a(2) … a(n)
        for (int i = 2; i <= n; i++) {
            long c = 2 * b + a; // a(i)
            a = b;
            b = c;
        }

        // For n == 1 the loop is skipped and b stays 1 (a(1))
        // For n == 2 the loop runs once and b becomes 3 (a(2)), etc.
        return (int) b;
    }

    // Simple test driver (not required by the problem, but handy for verification)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

