     * @param text the input string
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Split on non-word characters to obtain individual words.
        boolean found = Arrays.stream(text.split("\\W+"))
                // Word must be at least two characters long.
                .filter(word -> word.length() > 1)
                // Must contain at least one 'z'.
                .filter(word -> word.contains("z"))
                // 'z' must not be the first or last character.
                .anyMatch(word -> !word.startsWith("z") && !word.endsWith("z"));

        return found ? "Found a match!" : "Not matched!";
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that starts at the top‑left cell
     * (0,0) and ends at the bottom‑right cell (n‑1,n‑1) while moving only
     * right or down.
     *
     * @param cost the n×n matrix of integer costs (List of List of Integer)
     * @param n    the dimension of the square matrix
     * @return the maximum average (as a {@code Double}) of a valid path,
     *         or {@code null} if the input is invalid.
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against bad input
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i,j) from (0,0)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cur = cost.get(i).get(j);          // unbox once
                if (i == 0 && j == 0) {
                    dp[i][j] = cur;                    // start cell
                } else {
                    double bestFromTop = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double bestFromLeft = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = Math.max(bestFromTop, bestFromLeft) + cur;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // Every path has exactly (2 * n - 1) cells
        double average = maxSum / (double) (2L * n - 1);
        return average;
    }

    // ----------------------------------------------------------------------
    // Simple test harness (optional)
    // ----------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

