     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Null or string shorter than 2 cannot have a neighbour
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        // Work with lower‑case to cover both cases
        String s = testStr.toLowerCase();
        final String vowels = "aeiou";

