                    boolean leftIsVowel  = i > 0 && vowels.indexOf(s.charAt(i - 1)) >= 0;
                    boolean rightIsVowel = i < s.length() - 1 && vowels.indexOf(s.charAt(i + 1)) >= 0;
                    return leftIsVowel || rightIsVowel;
                })
                .count();
    }

