class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * For n >= 3 this number is a prime (the “Newman‑Shanks‑Williams prime”).
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // Base cases of the recurrence
        if (n == 1) return 1;   // a0 = 1
        if (n == 2) return 3;   // a1 = 1, a2 = 2*1+1 = 3

        int aPrev2 = 1; // a0
        int aPrev1 = 1; // a1
        int a = 0;

        // Compute a_n for n >= 2
        for (int i = 2; i <= n; i++) {
            a = 2 * aPrev1 + aPrev2; // a_i = 2*a_{i-1} + a_{i-2}
            aPrev2 = aPrev1;
            aPrev1 = a;
        }
        // After the loop, aPrev1 holds a_n
        return aPrev1;
    }
}

