import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all monotone paths
     * (moving only right or down) from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost  a list of n rows, each row a list of n integers
     * @param n     size of the square matrix
     * @return      the highest possible average (as a Double), or null
     *              if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.isEmpty() || cost.get(0).isEmpty()) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // maximum sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // every monotone path has exactly (2*n - 1) cells
        return maxSum / (2 * n - 1);
    }
}

