/**
 *  NewmanPrime – returns the n‑th Newman‑Shanks‑Williams number.
 *
 *  The sequence is defined by:
 *      a(0) = 1, a(1) = 1
 *      a(n) = 2·a(n‑1) + a(n‑2)   for n ≥ 2
 *
 *  The first few terms are: 1, 1, 3, 7, 17, 41, 99, …
 *
 *  Examples:
 *      newmanPrime(3) → 7
 *      newmanPrime(4) → 17
 *      newmanPrime(5) → 41
 */
class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number (n ≥ 0).
     *
     * @param n the index of the desired term (0‑based)
     * @return the NSW number at position n
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The first two values are both 1
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iteratively compute the sequence
        int aMinus2 = 1; // a(n‑2)
        int aMinus1 = 1; // a(n‑1)
        int current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * aMinus1 + aMinus2;
            aMinus2 = aMinus1;
            aMinus1 = current;
        }
        return current;
    }

    // -----------------------------------------------------------------
    // A small test driver (optional)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Print first 10 NSW numbers to illustrate the sequence
        for (int i = 0; i < 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

