import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

public class NewmanPrime {
    /**
     * Returns the nth Newman–Shanks–Williams prime number.
     * The sequence starts: 1, 1, 3, 7, 17, 41, ...
     * The prime numbers in this sequence are: 3, 7, 17, 41, ...
     * Based on the provided samples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     *
     * @param n the index of the Newman–Shanks–Williams prime (starting from 2)
     * @return the nth Newman–Shanks–Williams prime
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Special case for n == 1 (if needed)
        if (n == 1) {
            return 3; // First NSW prime
        }

        List<BigInteger> primes = new ArrayList<>();
        BigInteger a = BigInteger.ONE; // N0
        BigInteger b = BigInteger.ONE; // N1

        // Generate NSW numbers starting from index 2
        // Continue until we have collected at least (n-1) primes
        for (int i = 2; primes.size() < n - 1; i++) {
            // Compute next NSW number: N_i = 2 * N_{i-1} + N_{i-2}
            BigInteger c = b.multiply(BigInteger.valueOf(2)).add(a);

            // Check for primality (using probabilistic test)
            if (c.isProbablePrime(10)) {
                primes.add(c);
            }

            // Update previous two numbers
            a = b;
            b = c;
        }

        // Return the (n-2)th prime (0-indexed) for n >= 2
        return primes.get(n - 2).intValue();
    }
}

