public class Maxaverageofpath {

    /**
     * Finds a path with the maximum average over all existing paths
     * for the given square matrix of size n × n.
     *
     * The path may only move right or down, starting at (0,0) and ending at (n‑1,n‑1).
     *
     * @param cost the n×n matrix of path costs (each cell is a non‑negative integer)
     * @param n    the dimension of the square matrix
     * @return the maximum average of any valid path, or null if the input is invalid
     *
     * Example:
     *   maxaverageofpath([[1,2,3],[6,5,4],[7,3,9]], 3) → 5.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // First cell (0,0)
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the DP table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The maximum sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // Every path from (0,0) to (n-1,n-1) contains exactly (2*n - 1) cells
        double average = maxSum / (2.0 * n - 1);

        // Return as a Double object
        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

