     * Counts characters that are NOT vowels (i.e. consonants) and that have
     * at least one vowel neighbour (either to the left or to the right).
     *
     * @param testStr the input string
     * @return the number of such characters
     *
     * Examples:
     *   countVowels("bestinstareels")          -> 7
     *   countVowels("partofthejourneyistheend")-> 12
     *   countVowels("amazonprime")             -> 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }

        final String vowels = "aeiou";
        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            char lower = Character.toLowerCase(ch);

            // we only care about non‑vowel characters
            if (vowels.indexOf(lower) == -1) {
                boolean hasVowelNeighbor = false;

                // check left neighbour
                if (i > 0) {
                    char left = Character.toLowerCase(testStr.charAt(i - 1));
                    if (vowels.indexOf(left) != -1) {
                        hasVowelNeighbor = true;
