public class TextMatchWordzMiddle {
    /**
     * Returns "Found a match!" if any word in the given text contains the letter
     * 'z' (or 'Z') that is not the first or last character of that word;
     * otherwise returns "Not matched!".
     *
     * @param text the input string
     * @return the appropriate result message
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches a whole word (letters only)
        Pattern wordPattern = Pattern.compile("\\b[A-Za-z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            String lower = word.toLowerCase();   // make the check case‑insensitive

            // Look for any 'z' that is not at the first or last index
            int idx = lower.indexOf('z');
            while (idx != -1) {
                if (idx > 0 && idx < lower.length() - 1) {
                    return "Found a match!";
                }
                // continue searching for other 'z' in the same word
                idx = lower.indexOf('z', idx + 1);
            }
        }
        return "Not matched!";
    }
}

