public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left cell,
     * ends at the bottom‑right cell and may move only right or down.
     *
     * @param cost  square matrix (n × n) of integers
     * @param n     size of the matrix
     * @return      the maximal average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table: dp[i][j] = maximal sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Base case – starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // Number of cells visited on any such path = 2 * n - 1
        double average = maxSum / (2.0 * n - 1.0);

        return Double.valueOf(average);
    }
}

