class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        char[] a = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < a.length; i++) {
            char ch = a[i];
            // we only count consonants that have a vowel neighbour
            if (isVowel(ch)) {
                continue;
            }

            boolean hasVowelNeighbour = false;
            if (i > 0 && isVowel(a[i - 1])) {
                hasVowelNeighbour = true;
            }
            if (i < a.length - 1 && isVowel(a[i + 1])) {
                hasVowelNeighbour = true;
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }
        return count;
    }

    /** Helper: returns true if ch is a vowel (both lower‑ and upper‑case). */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i'
                || lower == 'o' || lower == 'u';
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

