class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        List<BigInteger> primes = new ArrayList<>();

        // Initialize the NSW sequence
        BigInteger a0 = BigInteger.ONE;
        BigInteger a1 = BigInteger.ONE;

        // Generate NSW numbers and collect primes
        for (int i = 2; i >= 2; i++) {
            BigInteger a2 = a1.multiply(BigInteger.valueOf(2)).add(a0);

            // Check if a2 is prime
            if (a2.isProbablePrime(50)) {
                primes.add(a2);
            }

            // Update sequence
            a0 = a1;
            a1 = a2;

            // Check if we have enough primes
            if (n == 1 && primes.size() >= 1) {
                break;
            } else if (n > 1 && primes.size() >= n - 1) {
                break;
            }
        }

        // Return the result based on n
        if (n == 1) {
            return primes.get(0).intValue();
        } else {
            return primes.get(n - 2).intValue();
        }
    }
}

