public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left
     * corner and ends at the bottom‑right corner of the given n×n matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return     maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = best sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                double val = cost.get(i).get(j).doubleValue();

                if (i == 0 && j == 0) {
                    // starting cell
                    dp[i][j] = val;
                } else {
                    double fromTop  = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double fromLeft = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = val + Math.max(fromTop, fromLeft);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // every path contains exactly (2*n - 1) cells
        return maxSum / (2 * n - 1);
    }

    // --------------------------------------------------------------------
    // Optional test harness (matches the examples from the statement)
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
            List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
            ), 3));   // 5.2

        System.out.println(maxaverageofpath(
            List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
            ), 3));   // 6.2

        System.out.println(maxaverageofpath(
            List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
            ), 3));   // 7.2
    }
}

