class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // Base cases: a(1) = 1, a(2) = 3
        if (n == 1) return 1;
        if (n == 2) return 3;

        // Use BigInteger to handle potentially large values.
        BigInteger aPrev2 = BigInteger.ONE;   // a(i‑2)
        BigInteger aPrev1 = BigInteger.valueOf(3); // a(i‑1)
        BigInteger aCurr = null;

        for (int i = 3; i <= n; i++) {
            // a(i) = 2 * a(i‑1) + a(i‑2)
            aCurr = aPrev1.multiply(BigInteger.valueOf(2)).add(aPrev2);
            // shift the window
            aPrev2 = aPrev1;
            aPrev1 = aCurr;
        }
        // The result fits in an int for the typical range of n;
        // we simply truncate to int.
        return aCurr.intValue();
    }
}

