class Maxaverageofpath {
    /**
     * Write a function to find a path with the maximum average over all existing
     * paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] holds the maximum sum reachable at cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int cur = cost.get(i).get(j);          // cost of the current cell
                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = cur;
                } else if (i == 0) {
                    // can only come from the left
                    dp[i][j] = dp[i][j - 1] + cur;
                } else if (j == 0) {
                    // can only come from above
                    dp[i - 1][j] + cur;
                    dp[i][j] = dp[i - 1][j] + cur;
                } else {
                    // take the best of the two possible predecessors
                    dp[i][j] = cur + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // Every path from (0,0) to (n‑1,n‑1) contains exactly (2*n‑1) cells
        double average = maxSum / (2 * n - 1);

        return average;               // auto‑boxed to Double
    }

    // A tiny test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

