import java.math.BigInteger;
import java.util.stream.Stream;

/**
 * Solution to compute the n‑th Newman‑Shanks‑Williams prime.
 * The sequence is defined by:
 *   a(0) = 1, a(1) = 1
 *   a(i) = 2·a(i‑1) + a(i‑2)   for i ≥ 2
 * The numbers at positions 2,3,4,5,… are prime (3,7,17,41,…).
 */
public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime (0‑based index).
     *
     * @param n the index of the desired prime (e.g., newmanPrime(3) → 7)
     * @return the value of the n‑th Newman‑Shanks‑Williams number,
     *         which is prime for the given test cases.
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Infinite stream of NSW numbers: a(0)=1, a(1)=1, a(i)=2*a(i‑1)+a(i‑2)
        Stream<BigInteger> nswStream = Stream.iterate(
                new BigInteger[]{BigInteger.ONE, BigInteger.ONE}, // a(0), a(1)
                arr -> new BigInteger[]{
                        arr[1],                                 // shift a(i‑1) → a(i‑2)
                        arr[1].multiply(BigInteger.TWO).add(arr[0]) // a(i) = 2*a(i‑1)+a(i‑2)
                }
        ).map(arr -> arr[1]); // keep only the current term a(i)

        // Pick the n‑th element (0‑based) and convert to int.
        return nswStream.skip(n)
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException("Index out of bounds"))
                .intValue();
    }
}

