import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path from the top‑left to the
     * bottom‑right of a square matrix, moving only right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the matrix (may be omitted; the method
     *             derives the size from the list)
     * @return the highest possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation -------------------------------------------------
        if (cost == null || cost.isEmpty()) {
            return null;
        }
        int size = cost.size();                 // actual matrix size
        if (size != n) {
            n = size;                           // use the real size if they differ
        }

        // ---- DP table: dp[i][j] = max sum to reach (i, j) --------------------
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // remaining cells – take the better predecessor and add current cost
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // ---- compute average ---------------------------------------------------
        // Every path from (0,0) to (n‑1,n‑1) contains exactly (2*n‑1) cells.
        double maxSum = dp[n - 1][n - 1];
        return maxSum / (2 * n - 1);
    }
}

