class CountVowels {
    /** 
     * Returns the number of characters in the given string that are NOT vowels
     * but have at least one vowel as an immediate neighbour (left or right).
     *
     * Examples:
     *   countVowels("bestinstareels")          → 7
     *   countVowels("partofthejourneyistheend")→ 12
     *   countVowels("amazonprime")             → 5
     *
     * @param testStr the input string (may contain mixed case)
     * @return the count of such characters
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        final int len = testStr.length();

        // Helper that tells whether a character is a vowel (case‑insensitive)
        // The method is pure and has no side effects.
        IntStream intStream = IntStream.range(0, len);
        return (int) intStream
                .filter(i -> {
                    char c = testStr.charAt(i);
                    // We only count non‑vowel characters
                    if (isVowel(c)) {
                        return false;
                    }
                    // Check neighbours
                    boolean hasVowelNeighbour =
                            (i > 0 && isVowel(testStr.charAt(i - 1))) ||
                            (i < len - 1 && isVowel(testStr.charAt(i + 1)));
                    return hasVowelNeighbour;
                })
                .count();
    }

    /** 
     * Returns true if the given character is a vowel (a, e, i, o, u) 
     * regardless of case. The method is pure and has no side effects.
     */
    private static boolean isVowel(char c) {
        char lower = Character.toLowerCase(c);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u';
    }
}

