class CountAlphaDigSpl {
    /**
     * Write a function to count alphabets, digits and special characters in a given string.
     *
     * > countAlphaDigSpl("abc!@#123")
     * [3, 3, 3]
     * > countAlphaDigSpl("dgsuy@#$%&1255")
     * [5, 4, 5]
     * > countAlphaDigSpl("fjdsif627348#%$^&")
     * [6, 6, 5]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Guard against null input
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        // Map each character to a category: 0 = alphabetic, 1 = digit, 2 = special
        Map<Integer, Long> freq = string.chars()
                .mapToObj(c -> Character.isAlphabetic(c) ? 0
                        : (Character.isDigit(c) ? 1 : 2))
                .collect(Collectors.groupingBy(i -> i, Collectors.counting()));

        // Retrieve counts, defaulting to 0 if a category is absent
        int alphas = freq.getOrDefault(0, 0L).intValue();
        int digits = freq.getOrDefault(1, 0L).intValue();
        int specials = freq.getOrDefault(2, 0L).intValue();

        return Arrays.asList(alphas, digits, specials);
    }
}

