class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle non-positive indices
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        // The Newman–Shanks–Williams sequence starts with 1, 1
        if (n == 0 || n == 1) {
            return 1;
        }
        long prev2 = 1; // a0
        long prev1 = 1; // a1
        long current = 0;
        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        return (int) current;
    }
}

