     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches whole words consisting only of letters.
        // \b = word boundary, [A-Za-z]+ = one or more letters.
        Pattern wordPattern = Pattern.compile("\\b[A-Za-z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        // Scan each word found in the input string.
        while (matcher.find()) {
            String word = matcher.group();          // the actual word text
            if (containsZNotAtEnds(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * Returns true if the supplied word contains the letter 'z'
     * in a position other than the first or last character.
     * The check is case‑sensitive (only lower‑case 'z' is considered,
     * matching the examples).
