    private static boolean containsZNotAtEnds(String word) {
        // A word must be at least 3 characters long to have a “middle” position.
        if (word.length() < 3) {
            return false;
        }
        // Examine characters at indices 1 … length‑2 (i.e., not the first or last).
        for (int i = 1; i < word.length() - 1; i++) {
            if (word.charAt(i) == 'z') {
                return true;
            }
        }
        return false;
    }

