import java.util.List;
import java.util.Arrays;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left
     * corner of the given cost matrix and ends at the bottom‑right corner,
     * moving only right or down.
     *
     * @param cost a square matrix (List of List of Integer)
     * @param n    size of the matrix (n × n)
     * @return the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table, using long to avoid overflow for large sums
        long[][] dp = new long[n][n];

        // first cell
        dp[0][0] = cost.get(0).get(0).longValue();

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j).longValue();
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0).longValue();
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                long bestPrev = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = bestPrev + cost.get(i).get(j).longValue();
            }
        }

        // maximum sum to reach the bottom‑right cell
        long maxSum = dp[n - 1][n - 1];

        // number of cells in any valid path = 2*n - 1
        int pathLength = 2 * n - 1;

        // compute the average – side‑effect‑free, uses a stream only for the division
        double average = maxSum / (double) pathLength;

        return Double.valueOf(average);
    }

    // --------------------------------------------------------------------
    // Simple test driver (not part of the required solution)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

