                        return false;
                    }
                    boolean leftIsVowel  = i > 0            && isVowel(s.charAt(i - 1));
                    boolean rightIsVowel = i < s.length() - 1 && isVowel(s.charAt(i + 1));
                    return leftIsVowel || rightIsVowel;
                })
                .count();   // terminal operation – no side effects
    }

    /** Returns true if the given character is one of a, e, i, o, u. */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }
}

