class NewmanPrime {
    /**
     * Returns the nth term in the Newman-Shanks-Williams sequence.
     * The sequence is defined as:
     * a[0] = 1, a[1] = 3, a[n] = 2 * a[n-1] + a[n-2] for n >= 2.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // Handle the first two terms directly
        if (n == 1) return 1;
        if (n == 2) return 3;

        // Initialize the first two terms
        long a0 = 1;
        long a1 = 3;
        long an = 0;

        // Compute terms from index 2 to n-1 (0-indexed)
        for (int i = 2; i < n; i++) {
            an = 2 * a1 + a0;
            a0 = a1;
            a1 = an;
        }

        // Return the nth term (1-indexed)
        return (int) an;
    }
}

