import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left corner,
     * ends at the bottom‑right corner and may only move right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    size of the square matrix
     * @return the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] = greatest sum to reach (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else {
                    long best = Long.MIN_VALUE;
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]); // from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]); // from left
                    }
                    dp[i][j] = val + best;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // Every path has exactly (2*n - 1) cells
        double average = (double) maxSum / (2L * n - 1);
        return average;
    }

    // ------------------------------------------------------------------
    // Simple test (can be removed when integrating into a larger project)
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                List.of(List.of(1, 2, 3),
                        List.of(6, 5, 4),
                        List.of(7, 3, 9)), 3)); // 5.2

        System.out.println(maxaverageofpath(
                List.of(List.of(2, 3, 4),
                        List.of(7, 6, 5),
                        List.of(8, 4, 10)), 3)); // 6.2

        System.out.println(maxaverageofpath(
                List.of(List.of(3, 4, 5),
                        List.of(8, 7, 6),
                        List.of(9, 5, 11)), 3)); // 7.2
    }
}

