public class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks–Williams number.
     * For n >= 2 this number is a prime, matching the examples
     * newmanPrime(3) = 7, newmanPrime(4) = 17, newmanPrime(5) = 41.
     *
     * @param n index (0‑based) of the desired NSW number
     * @return the n‑th NSW number
     */
    public static int newmanPrime(int n) {
        // a0 = 1, a1 = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long prev2 = 1; // a0
        long prev1 = 1; // a1
        long cur = 0;

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2; // an = 2*a(n‑1) + a(n‑2)
            prev2 = prev1;
            prev1 = cur;
        }

        // The problem expects an int; n is limited so the value fits.
        return (int) cur;
    }
}

