public class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given
     * n × n matrix.  Movement is restricted to right and down steps only.
     *
     * @param cost the square matrix of non‑negative integers
     * @param n    the dimension of the matrix
     * @return the maximum average (as a {@code Double}) over all valid paths
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic sanity check – return null for illegal input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0).longValue();

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j).longValue();
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0).longValue();
        }

        // Fill the rest of the table: take the best of the two predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j).longValue()
                         + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // All paths have the same number of cells: 2*n - 1
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        // Return as a boxed Double
        return Double.valueOf(average);
    }

    // ---- Example usage (not required for the solution) ----
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

