     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() < 2) {
            return 0;                     // no neighbour pairs possible
        }

        // work case‑insensitively
        String s = testStr.toLowerCase();
        Set<Character> vowels = Set.of('a', 'e', 'i', 'o', 'u');

        // stream over all indices, keep only consonants that have a vowel neighbour
        return (int) IntStream.range(0, s.length())
