                    if (vowels.contains(ch)) {
                        return false;
                    }
                    // check left neighbour
                    boolean hasVowelNeighbour = (i > 0 && vowels.contains(s.charAt(i - 1)));
                    // check right neighbour if not already found
                    if (!hasVowelNeighbour) {
                        hasVowelNeighbour = (i < s.length() - 1 && vowels.contains(s.charAt(i + 1)));
                    }
                    return hasVowelNeighbour;
                })
                .count();
    }
}

