import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

public class NewmanPrime {
    /**
     * Returns the nth Newman–Shanks–Williams prime.
     * Based on the examples, the function returns the (n-2)-th prime (0-indexed)
     * in the sequence of NSW primes.
     *
     * @param n the index (must be >= 2)
     * @return the nth NSW prime
     */
    public static int newmanPrime(int n) {
        if (n <= 1) {
            // For n <= 1, the mapping is not defined.
            // Return 0 as a safe default.
            return 0;
        }

        List<BigInteger> primes = new ArrayList<>();
        BigInteger a = BigInteger.ONE; // a0
        BigInteger b = BigInteger.ONE; // a1

        // Generate NSW numbers starting from index 2
        for (int i = 2; ; i++) {
            // Compute next NSW number: c = 2*b + a
            BigInteger c = b.multiply(BigInteger.TWO).add(a);

            // Check for primality
            if (c.isProbablePrime(100)) {
                primes.add(c);
                // Stop when we have at least (n-1) primes
                if (primes.size() >= n - 1) {
                    break;
                }
            }

            // Update a and b for next iteration
            a = b;
            b = c;
        }

        // Return the (n-2)-th prime (0-indexed)
        return primes.get(n - 2).intValue();
    }
}

