import java.util.List;
import java.util.Arrays;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts
     * at the top‑left corner and ends at the bottom‑right corner of the
     * given n×n matrix, moving only right or down.
     *
     * @param cost square matrix of integers
     * @param n    size of the matrix (number of rows/columns)
     * @return     maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                long val = row.get(j).longValue();

                if (i == 0 && j == 0) {
                    dp[i][j] = val;                 // start cell
                } else {
                    long best = Long.MIN_VALUE;
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]); // from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]); // from left
                    }
                    dp[i][j] = val + best;
                }
            }
        }

        double denominator = 2.0 * n - 1.0;          // number of visited cells
        return dp[n - 1][n - 1] / denominator;
    }

    // ---------------------------------------------------------------
    // Simple manual test (not required for the solution, but useful)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

