/**
 * Utility class that counts alphabetic characters, digits and
 * special characters in a given string.
 */
class CountAlphaDigSpl {

    /**
     * Returns a list [alphabets, digits, special characters] for the supplied string.
     *
     * @param string the input text (may be null or empty)
     * @return a list containing three integer counts
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Guard against null input – return zeroes
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        // 1️⃣ Convert the string to an IntStream of code points.
        // 2️⃣ Map each code point to a category name.
        // 3️⃣ Use groupingBy + counting to obtain a Map<Category, Long>.
        Map<String, Long> freq = string.codePoints()               // IntStream of Unicode code points
                .mapToObj(cp -> {
                    if (Character.isLetter(cp)) {
                        return "Alpha";
                    } else if (Character.isDigit(cp)) {
                        return "Digit";
                    } else {
                        return "Special";
                    }
                })
                .collect(Collectors.groupingBy(
                        Function.identity(),        // key = category name
                        Collectors.counting()));    // downstream = count occurrences

        // Retrieve the three counts, defaulting to 0L if a category is absent.
        long alphaCount   = freq.getOrDefault("Alpha",   0L);
        long digitCount   = freq.getOrDefault("Digit",   0L);
        long specialCount = freq.getOrDefault("Special", 0L);

        // Return the result as a List<Integer>.
        return Arrays.asList((int) alphaCount, (int) digitCount, (int) specialCount);
    }

    // --------------------------------------------------------------------
    // Simple manual test (optional)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));           // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));      // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&"));   // [6, 6, 5]
    }
}

