import java.util.stream.*;

public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * @param n the index (0‑based) of the desired number
     * @return the value a_n of the NSW sequence
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Iterative, side‑effect‑free computation of the NSW sequence.
        long prev = 1;   // a0
        long curr = 1;   // a1

        for (int i = 2; i <= n; i++) {
            long next = 2 * curr + prev; // a_i = 2·a_{i‑1} + a_{i‑2}
            prev = curr;
            curr = next;
        }

        // For n = 0 or 1 the value is 1.
        if (n == 0 || n == 1) {
            return 1;
        }

        return (int) curr;
    }
}

