    /**
     * Counts characters that are **not** vowels (i.e. consonants) and that have
     * at least one vowel neighbour (either to the left or to the right).
     * Edge characters are counted if they have a vowel neighbour on the side
     * that exists.
     *
     * @param testStr the input string
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int len = testStr.length();

        // Stream over the indices, keep only consonants that have a vowel neighbour
        return (int) IntStream.range(0, len)
                .filter(i -> {
                    char ch = testStr.charAt(i);
                    if (isVowel(ch)) {               // we count only consonants
                        return false;
                    }
                    boolean leftVowel  = i > 0        && isVowel(testStr.charAt(i - 1));
                    boolean rightVowel = i < len - 1 && isVowel(testStr.charAt(i + 1));
                    return leftVowel || rightVowel;   // at least one vowel neighbour
                })
                .count();
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

