class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     *
     * The NSW numbers are defined by:
     *     s0 = 1, s1 = 1
     *     sn = 2*sn‑1 + sn‑2  (n ≥ 2)
     * The NSW primes are those sn that are prime.
     *
     * @param n the index (1‑based) of the desired NSW prime
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Special case: the first NSW prime is 3
        if (n == 1) {
            return 3;
        }

        // We need the (n‑1)‑th prime because the first prime corresponds to n = 2
        int targetCount = n - 1;
        int count = 0;

        // s0 = 1, s1 = 1
        long sPrev2 = 1; // s_{i‑2}
        long sPrev1 = 1; // s_{i‑1}

        for (int i = 2; ; i++) {
            long s_i = 2 * sPrev1 + sPrev2; // sn = 2*sn‑1 + sn‑2

            if (isPrime(s_i)) {
                count++;
                if (count == targetCount) {
                    // The result always fits in an int for reasonable n
                    return (int) s_i;
                }
            }

            // shift the window
            sPrev2 = sPrev1;
            sPrev1 = s_i;
        }
    }

    /**
     * Simple deterministic primality test for values that fit in a long.
     * Sufficient for the range of NSW numbers we encounter.
     */
    private static boolean isPrime(long value) {
        if (value < 2) {
            return false;
        }
        if (value == 2) {
            return true;
        }
        if (value % 2 == 0) {
            return false;
        }
        long limit = (long) Math.sqrt(value);
        for (long d = 3; d <= limit; d += 2) {
            if (value % d == 0) {
                return false;
            }
        }
        return true;
    }

    // Optional test driver (not required by the problem statement)
    public static void main(String[] args) {
        // Example tests
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
        // Additional sanity checks
        System.out.println(newmanPrime(1)); // 3
        System.out.println(newmanPrime(2)); // 3
        System.out.println(newmanPrime(6)); // 239
        System.out.println(newmanPrime(7)); // 577
    }
}

