     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null input
        if (text == null) {
            return "Not matched!";
        }

        // Pattern to match words: consecutive letters (A‑Z or a‑z)
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // the raw word
            String lowerWord = word.toLowerCase();       // case‑insensitive check

