            if (lowerWord.contains("z")) {
                // Ensure 'z' is neither the first nor the last character
                if (lowerWord.charAt(0) != 'z' &&
                    lowerWord.charAt(lowerWord.length() - 1) != 'z') {
                    return "Found a match!";
                }
            }
        }

        // No qualifying word found
        return "Not matched!";
    }

