public class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     *
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2·a(n‑1) + a(n‑2)  for n ≥ 2
     *
     * @param n index of the required term (0‑based)
     * @return the value a_n
     * @throws IllegalArgumentException if n is negative
     */
    public static long newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // a0 = 1, a1 = 1
        if (n == 0 || n == 1) {
            return 1L;
        }

        long prev2 = 1L; // a(n‑2)
        long prev1 = 1L; // a(n‑1)
        long current = 0L;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // an = 2·a(n‑1) + a(n‑2)
            prev2 = prev1;
            prev1 = current;
        }

        return current;
    }

    // ---- simple test harness -------------------------------------------------
    public static void main(String[] args) {
        // Example calls from the problem statement
        System.out.println(newmanPrime(3)); // → 7
        System.out.println(newmanPrime(4)); // → 17
        System.out.println(newmanPrime(5)); // → 41

        // A few more terms to illustrate the growth
        for (int i = 0; i <= 10; i++) {
            System.out.printf("a(%d) = %d%n", i, newmanPrime(i));
        }
    }
}

