import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum average of a path from the top‑left corner to the
     * bottom‑right corner of the given n×n matrix.  Movement is allowed only
     * to the right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    the dimension of the square matrix
     * @return the maximum average value (as a {@code Double}) of any valid path
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] – maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);          // value in current cell
                if (i == 0 && j == 0) {
                    dp[i][j] = val;                    // start cell
                } else {
                    double best = 0;
                    if (i > 0)   best = Math.max(best, dp[i - 1][j]); // from above
                    if (j > 0)   best = Math.max(best, dp[i][j - 1]); // from left
                    dp[i][j] = val + best;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);   // path always has 2*n‑1 cells
        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

