public static int newmanPrime(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (n == 1) {
        return 1; // a1 = 1
    }
    if (n == 2) {
        return 3; // a2 = 3
    }
    long a1 = 1; // a(i-2)
    long a2 = 3; // a(i-1)
    for (int i = 3; i <= n; i++) {
        long a3 = 2 * a2 + a1;
        a1 = a2;
        a2 = a3;
    }
    return (int) a2;
}

