        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            // Vowels are not counted; we only count consonants that have a vowel neighbour
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0) {
                char left = s.charAt(i - 1);
                if (left == 'a' || left == 'e' || left == 'i' || left == 'o' || left == 'u') {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbour (if we haven't already found a vowel neighbour)
            if (!hasVowelNeighbor && i < s.length() - 1) {
                char right = s.charAt(i + 1);
                if (right == 'a' || right == 'e' || right == 'i' || right == 'o' || right == 'u') {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Optional main method for quick manual testing
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
