class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n == 1) {
            return 2;
        }

        BigInteger a0 = BigInteger.ONE; // a(n-2)
        BigInteger a1 = BigInteger.ONE; // a(n-1)
        int count = 0; // Count of primes found in the sequence (excluding the initial 2)

        while (true) {
            // Generate next term: a(n) = 2*a(n-1) + a(n-2)
            BigInteger a = a1.multiply(BigInteger.valueOf(2)).add(a0);

            // Check if a is prime
            if (isPrime(a)) {
                count++;
                // When we have found (n-1) primes in this sequence, return a
                if (count == n - 1) {
                    return a.intValue();
                }
            }

            // Update for next iteration
            a0 = a1;
            a1 = a;
        }
    }

    // Helper method to check if a BigInteger is prime
    private static boolean isPrime(BigInteger n) {
        if (n.compareTo(BigInteger.ONE) <= 0) {
            return false;
        }
        if (n.equals(BigInteger.valueOf(2))) {
            return true;
        }
        if (n.mod(BigInteger.valueOf(2)).equals(BigInteger.ZERO)) {
            return false;
        }
        // Use probabilistic primality test with sufficient certainty
        return n.isProbablePrime(100);
    }
}

