import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all monotone (right/down) paths
     * from the top‑left corner to the bottom‑right corner of the given n×n matrix.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (cost.size() == n)
     * @return the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                double cur = cost.get(i).get(j);           // value of current cell
                if (i == 0 && j == 0) {
                    dp[i][j] = cur;                         // start cell
                } else {
                    double bestFromTop    = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double bestFromLeft   = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = cur + Math.max(bestFromTop, bestFromLeft);
                }
            }
        }

        // All paths have exactly (2*n - 1) cells, so the average = sum / (2*n - 1)
        double maxSum = dp[n - 1][n - 1];
        return maxSum / (2L * n - 1);
    }
}

