     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases: the first two terms are both 1
        if (n == 0) return 1;
        if (n == 1) return 1;

        // Initialize the sequence values
        long a0 = 1; // a_{i-2}
        long a1 = 1; // a_{i-1}
        long a2 = 0; // a_i

        // Compute the nth term iteratively
        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0; // Apply recurrence relation
            // Update a0 and a1 for next iteration
            a0 = a1;
            a1 = a2;
        }

        // Return the nth term as an int
        return (int) a2;
    }
}

