public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value among all paths that start
     * at the upper‑left corner of the given n×n matrix and end at the
     * bottom‑right corner.  Movement is allowed only **right** or **down**.
     *
     * @param cost the n×n matrix of integer costs (List of rows)
     * @param n    size of the square matrix
     * @return     the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // First cell (0,0)
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // The path always contains exactly (2 * n - 1) cells
        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);

        return Double.valueOf(average);
    }

    // --------------------------------------------------------------------
    // Simple manual test (can be removed or replaced by JUnit tests)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

/**
 * Counts characters that are not vowels but have a vowel as an immediate neighbour.
 *
 * @param testStr the input string
 * @return the number of such characters
 */
public static int countVowels(String testStr) {
    if (testStr == null || testStr.isEmpty()) {
        return 0;
    }

    // Set of vowel characters (both lower‑ and upper‑case)
    final String VOWELS = "aeiouAEIOU";

    int count = 0;
    int len = testStr.length();

    for (int i = 0; i < len; i++) {
        char ch = testStr.charAt(i);

        // Skip vowels – we only count consonants (or any non‑vowel)
        if (VOWELS.indexOf(ch) != -1) {
            continue;
        }

        // Check left neighbour
        boolean hasVowelNeighbour = false;
        if (i > 0 && VOWELS.indexOf(testStr.charAt(i - 1)) != -1) {
            hasVowelNeighbour = true;
        }
        // Check right neighbour
        if (i < len - 1 && VOWELS.indexOf(testStr.charAt(i + 1)) != -1) {
            hasVowelNeighbour = true;
        }

        if (hasVowelNeighbour) {
            count++;
        }
    }

    return count;
}

