class NewmanPrime {
    /**
     * Returns the nth Newman-Shanks-Williams number.
     * The sequence is defined as:
     *   a(1) = 1
     *   a(2) = 3
     *   a(n) = 2 * a(n-1) + a(n-2) for n > 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // a(1) = 1, a(2) = 3
        long a1 = 1;
        long a2 = 3;

        if (n == 1) return (int) a1;
        if (n == 2) return (int) a2;

        long a = 0;
        for (int i = 3; i <= n; i++) {
            a = 2 * a2 + a1;
            a1 = a2;
            a2 = a;
        }

        return (int) a;
    }
}

