import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the input text contains a word that has the
     * letter 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") -> "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     -> "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   -> "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern that matches a word: consecutive letters (a‑z or A‑Z)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int len = word.length();

            // A word must be at least 3 characters long to have a middle position.
            if (len >= 3) {
                // Scan characters between the first and last index.
                for (int i = 1; i < len - 1; i++) {
                    char c = word.charAt(i);
                    if (c == 'z' || c == 'Z') {
                        return "Found a match!";
                    }
                }
            }
        }

        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
    }
}

import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that travels from the top‑left
     * corner to the bottom‑right corner of the given n×n matrix.
     * Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of costs (each row is a List of Integer)
     * @param n    the dimension of the square matrix
     * @return     the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0) {
            return null;                     // invalid input
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // total number of cells visited on any valid path = 2*n - 1
        double average = dp[n - 1][n - 1] / (double) (2 * n - 1);
        return average; // auto‑boxed to Double
    }

    // Simple test driver
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

