     * > countAlphaDigSpl("dgsuy@#$%&1255")
     * [5, 4, 5]
     * > countAlphaDigSpl("fjdsif627348#%$^&")
     * [6, 6, 5]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Count alphabetic characters
        long alphabets = string.chars()
                               .filter(Character::isLetter)
                               .count();

        // Count digit characters
        long digits = string.chars()
                            .filter(Character::isDigit)
                            .count();

        // Special characters are whatever is left
        long specials = string.length() - alphabets - digits;

        // Return as a list of Integer (the problem expects a List<Integer>)
        return Arrays.asList((int) alphabets, (int) digits, (int) specials);
    }
