class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n (must be >= 0)
     * @return the sum of squares from 1 to n
     */
    public static int seriesSum(int number) {
        // Use the arithmetic series formula: n(n+1)(2n+1)/6
        // Use long for the intermediate computation to avoid overflow.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;   // the result fits in int for typical input ranges
    }

    // Optional quick test
