class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)   for n >= 2
     *
     * The values at positions 2,3,4,… are the “Newman‑Shanks‑Williams primes”.
     *
     * Examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // For very small n we can return directly.
        if (n == 0) return 1;   // a0
        if (n == 1) return 1;   // a1

        // Use long to avoid overflow for moderate n; the result is cast back to int.
        long a0 = 1L;   // a(n‑2)
        long a1 = 1L;   // a(n‑1)
        long cur = 0L;  // a(n)

        for (int i = 2; i <= n; i++) {
            cur = 2 * a1 + a0;   // an = 2*a(n‑1) + a(n‑2)
            a0 = a1;
            a1 = cur;
        }

        // The problem’s signature expects int; the values for reasonable n fit in int.
        return (int) cur;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        for (int i = 0; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

