class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the last term of the series (n)
     * @return the sum of squares from 1 to n
     */
    public static int seriesSum(int number) {
        if (number <= 0) {
            return 0;                     // no terms to sum
        }
        // Use a sequential stream – it's safe, stateless, and non‑interfering.
        return IntStream.rangeClosed(1, number)
                        .map(i -> i * i) // square each integer
                        .sum();          // reduces with associative accumulator
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

