class TextMatchWordzMiddle {
    /**
     * Returns "Found a match!" if the input text contains a word
     * that has the letter 'z' somewhere other than the first or last
     * character of that word; otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")      → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")    → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Null/empty input can’t match
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Regex explanation:
        // \b           – word boundary
        // [a-zA-Z]+    – one or more letters (the part before 'z')
        // z            – the literal 'z' (case‑insensitive)
        // [a-zA-Z]+    – one or more letters (the part after 'z')
        // \b           – word boundary
        Pattern p = Pattern.compile("\\b[a-zA-Z]+z[a-zA-Z]+\\b",
                                     Pattern.CASE_INSENSITIVE);

        // If the pattern finds any match, we have a word with 'z' not at the edges
        if (p.matcher(text).find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

