public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left corner
     * (0,0) and ends at the bottom‑right corner (n‑1,n‑1) moving only right or down.
     *
     * @param cost  a square n×n matrix given as a list of rows
     * @param n     size of the matrix
     * @return      the maximal average (rounded to one decimal place)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;                     // invalid input
        }

        // dp[i][j] = maximum sum of a path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                long cellValue = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = cellValue;                 // start cell
                } else {
                    long bestPrev = 0;
                    if (i > 0) bestPrev = Math.max(bestPrev, dp[i - 1][j]); // from above
                    if (j > 0) bestPrev = Math.max(bestPrev, dp[i][j - 1]); // from left
                    dp[i][j] = cellValue + bestPrev;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2L * n - 1);   // length of any such path

        // Round to one decimal place to match the examples (5.2, 6.2, …)
        average = Math.round(average * 10.0) / 10.0;

        return average;
    }

    // -----------------------------------------------------------------
    // Simple manual test (not required for the solution, but handy)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

