class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Null or too short strings have no neighbours to consider
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        // Work with a lower‑case version for easy vowel checking
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);
            // Ignore vowels themselves – we only count non‑vowel characters
            if (isVowel(c)) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbor = false;
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour if we haven't already found a vowel neighbour
            if (!hasVowelNeighbor && i < len - 1 && isVowel(s.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    /** Helper method that returns true if the given character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
}

