class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     *
     * The sequence is defined by:
     * <ul>
     *   <li>a(0) = 1</li>
     *   <li>a(1) = 1</li>
     *   <li>a(n) = 2·a(n‑1) + a(n‑2)  for n ≥ 2</li>
     * </ul>
     * The first few values are: 1, 1, 3, 7, 17, 41, …
     *
     * @param n the index of the term to return (0‑based)
     * @return the n‑th Newman–Shanks–Williams number
     * @throws IllegalArgumentException if {@code n} is negative
     */
    public static int newmanPrime(int n) {
        // ---- Item 49: check parameters for validity ----
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute the sequence iteratively using long to avoid overflow
        // for the typical range of n (the result fits in an int for n ≤ 25)
        long a0 = 1;   // a(n‑2)
        long a1 = 1;   // a(n‑1)
        long a2 = 0;   // a(n)

        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0; // recurrence
            a0 = a1;
            a1 = a2;
        }

        // The problem expects an int; cast after confirming it fits.
        return (int) a2;
    }
}

