     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern to match words (sequences of letters)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            if (hasInternalZ(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * Returns true if the given word contains the letter 'z' (or 'Z')
     * at any position other than the first or last character.
     */
    private static boolean hasInternalZ(String word) {
        // Need at least 3 characters to have a middle position
        if (word.length() < 3) {
            return false;
        }
        // Check each interior character
        for (int i = 1; i < word.length() - 1; i++) {
            if (Character.toLowerCase(word.charAt(i)) == 'z') {
                return true;
            }
        }
        return false;
    }
}

import java.util.List;
import java.util.Objects;

/**
 * Computes the maximum average of any path that travels from the upper‑left
 * cell to the lower‑right cell of a square matrix, moving only right or down.
 *
 * The average of a path is the sum of the visited cell values divided by the
 * number of visited cells (2·n – 1 for an n × n grid).  Because the denominator
 * is constant for a given n, maximising the average is equivalent to maximising
 * the path sum, which can be obtained with a simple dynamic‑programming table.
 *
 * @param cost the n × n matrix of non‑negative integers (must not be null)
 * @param n    the dimension of the square matrix (must be > 0)
 * @return the maximum possible average as a {@code Double}
 * @throws IllegalArgumentException if the preconditions are violated
 *
 * @see #maxaverageofpath(List, int)
 */
public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // ------------------------------------------------------------------
    // 1. Parameter validation (Item 49)
    // ------------------------------------------------------------------
    if (cost == null) {
        throw new IllegalArgumentException("cost must not be null");
    }
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive, got " + n);
    }
    if (cost.size() != n) {
        throw new IllegalArgumentException(
                "cost.size() (" + cost.size() + ") does not match n (" + n + ")");
    }
    for (int i = 0; i < n; i++) {
        List<Integer> row = cost.get(i);
        if (row == null) {
            throw new IllegalArgumentException("row " + i + " is null");
        }
        if (row.size() != n) {
            throw new IllegalArgumentException(
                    "row " + i + " has size " + row.size() + " but expected " + n);
        }
    }

    // ------------------------------------------------------------------
    // 2. Dynamic programming – maximum sum to each cell
    // ------------------------------------------------------------------
    // dp[i][j] = best sum to reach cell (i, j) from (0,0)
    double[][] dp = new double[n][n];

    // Initialize the start cell
    dp[0][0] = cost.get(0).get(0);

    // First row – can only come from the left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // First column – can only come from above
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Remaining cells – take the better of the two possible predecessors
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            double bestPrev = Math.max(dp[i - 1][j], dp[i][j - 1]);
            dp[i][j] = bestPrev + cost.get(i).get(j);
        }
    }

    // ------------------------------------------------------------------
    // 3. Compute the average
    // ------------------------------------------------------------------
    // A monotone path from (0,0) to (n‑1,n‑1) always visits exactly 2·n‑1 cells.
    int pathLength = 2 * n - 1;
    double maxSum = dp[n - 1][n - 1];
    return maxSum / pathLength;
}

