class CountVowels {

    /**
     * Counts characters that are not vowels and that have at least one vowel
     * neighbour (immediately to the left or right).
     *
     * @param testStr the input string (must not be {@code null})
     * @return the number of such characters
     * @throws IllegalArgumentException if {@code testStr} is {@code null}
     */
    public static int countVowels(String testStr) {
        // ---- Item 49: check parameters for validity ----
        if (testStr == null) {
            throw new IllegalArgumentException("Input string must not be null");
        }

        // Vowel set (both lower‑ and upper‑case)
        final String vowels = "aeiouAEIOU";

        int count = 0;
        for (int i = 0; i < testStr.length(); i++) {
            char ch = testStr.charAt(i);

            // Skip the vowel characters themselves – we only count non‑vowels
            if (vowels.indexOf(ch) != -1) {
                continue;
            }

            boolean hasVowelNeighbour = false;

            // Check left neighbour
            if (i > 0) {
                char left = testStr.charAt(i - 1);
                if (vowels.indexOf(left) != -1) {
                    hasVowelNeighbour = true;
                }
            }

            // Check right neighbour if we haven't found a vowel yet
            if (!hasVowelNeighbour && i < testStr.length() - 1) {
                char right = testStr.charAt(i + 1);
                if (vowels.indexOf(right) != -1) {
                    hasVowelNeighbour = true;
                }
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }
        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

