/**
 * A utility class for computing series sums.
 */
class SeriesSum {

    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the final term of the series (must be non‑negative)
     * @return the sum of squares from 1 to {@code number}
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        // ---- Item 49: Check parameters for validity ----
        if (number < 0) {
            throw new IllegalArgumentException(
                "Parameter 'number' must be non‑negative; got " + number);
        }

        // Use the formula n(n+1)(2n+1)/6 to compute the sum in O(1) time.
        // The intermediate result can exceed the range of int, so we use long.
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;

        // The problem statement expects an int result, so we cast back.
        return (int) sum;
    }
}

