import java.util.Objects;

class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     * <ul>
     *   <li>a(0) = 1</li>
     *   <li>a(1) = 1</li>
     *   <li>a(n) = 2·a(n‑1) + a(n‑2)  for n ≥ 2</li>
     * </ul>
     *
     * @param n the index of the term to return (must be non‑negative)
     * @return the n‑th term of the Newman–Shanks–Williams sequence
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        // Validate the input parameter
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative: " + n);
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iteratively compute a(n) using the recurrence relation
        int aMinus2 = 1; // a(i‑2)
        int aMinus1 = 1; // a(i‑1)
        int aCurrent = 0;

        for (int i = 2; i <= n; i++) {
            aCurrent = 2 * aMinus1 + aMinus2;
            aMinus2 = aMinus1;
            aMinus1 = aCurrent;
        }

        return aCurrent;
    }
}

