class VolumeTetrahedron {
    /**
     * Returns the volume of a regular tetrahedron whose edge length is {@code num}.
     *
     * The volume V of a regular tetrahedron with edge length a is:
     * V = a^3 / (6 * sqrt(2))
     *
     * @param num the length of each edge; must be positive
     * @return the volume, rounded to two decimal places
     * @throws IllegalArgumentException if {@code num} <= 0
     */
    public static Double volumeTetrahedron(int num) {
        if (num <= 0) {
            throw new IllegalArgumentException("Edge length must be positive: " + num);
        }
        double a = num;
        double volume = (a * a * a) / (6.0 * Math.sqrt(2.0));
        // Round to two decimal places to match the expected output
        double rounded = Math.round(volume * 100.0) / 100.0;
        return Double.valueOf(rounded);
    }
}

