class TextMatchWordzMiddle {

    /**
     * Determines whether any word in the given text contains the letter 'z'
     * somewhere other than the first or last character of the word.
     *
     * A “word” is defined by the regular expression {@code \b\w+\b},
     * i.e. a maximal sequence of word characters (letters, digits, underscore)
     * bounded by word boundaries.  Punctuation such as '.' or ',' is not
     * part of the word.
     *
     * @param text the string to be examined; must not be {@code null}
     * @return "Found a match!" if at least one word satisfies the condition,
     *         otherwise "Not matched!"
     * @throws IllegalArgumentException if {@code text} is {@code null}
     */
    public static String textMatchWordzMiddle(String text) {
        // Enforce the documented restriction: text must not be null.
        Objects.requireNonNull(text, "text must not be null");

        // \b\w+\b matches each whole word in the input.
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // Look for the character 'z' (case‑sensitive).
            int zIndex = word.indexOf('z');

            // The word contains 'z' and the 'z' is not at the first
            // or last position.
            if (zIndex != -1 && zIndex > 0 && zIndex < word.length() - 1) {
                return "Found a match!";
            }
        }

        // No word satisfied the required pattern.
        return "Not matched!";
    }

