}

import java.util.List;
import java.util.Objects;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path from the top‑left corner to the
     * bottom‑right corner of an n × n cost matrix.  Paths may move only
     * right or down.
     *
     * @param cost the n × n matrix of integer costs; must not be {@code null},
     *             each inner list must contain exactly {@code n} elements,
     *             and none of the elements may be {@code null}.
     * @param n    the dimension of the square matrix; must be positive.
     * @return the maximum average (as a {@code Double}) over all valid paths.
     * @throws NullPointerException     if {@code cost} is {@code null},
     *                                  if any inner list is {@code null},
     *                                  or if any matrix element is {@code null}.
     * @throws IllegalArgumentException if {@code n} is not positive or
     *                                  does not match the size of {@code cost}.
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- parameter validation -------------------------------------------------
        Objects.requireNonNull(cost, "cost must not be null");
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException("cost.size() must equal n");
        }

        // ---- dynamic programming: maximum sum to each cell -----------------------
        // Use long to avoid overflow when the sum gets large.
        long[][] dp = new long[n][n];

        // (0,0)
        Integer startVal = cost.get(0).get(0);
        Objects.requireNonNull(startVal, "matrix elements must not be null");
        dp[0][0] = startVal;

        // First row – can only come from the left
        for (int j = 1; j < n; ++j) {
            Integer v = cost.get(0).get(j);
            Objects.requireNonNull(v, "matrix elements must not be null");
            dp[0][j] = dp[0][j - 1] + v;
        }

        // First column – can only come from above
        for (int i = 1; i < n; ++i) {
            Integer v = cost.get(i).get(0);
            Objects.requireNonNull(v, "matrix elements must not be null");
            dp[i][0] = dp[i - 1][0] + v;
        }

        // Remaining cells – take the better of the two predecessor paths
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                Integer v = cost.get(i).get(j);
                Objects.requireNonNull(v, "matrix elements must not be null");
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + v;
            }
        }

        // ---- compute average ------------------------------------------------------
        long maxSum = dp[n - 1][n - 1];
        // A path from (0,0) to (n‑1,n‑1) using only right/down visits exactly
        // (2*n‑1) cells.
        double average = (double) maxSum / (2L * n - 1);

        return Double.valueOf(average);
    }
}

import java.util.Objects;

class CountVowels {
    /**
     * Counts the consonants in {@code testStr} that have a vowel
     * (a, e, i, o, u – case‑insensitive) as an immediate neighbour
     * (to the left or to the right).
     *
     * <p>Vowel characters themselves are not counted, even if they are
     * adjacent to another vowel.
     *
     * @param testStr the input string; must not be {@code null}
     * @return the number of consonants that are adjacent to at least one vowel
     * @throws IllegalArgumentException if {@code testStr} is {@code null}
     */
    public static int countVowels(String testStr) {
        // Enforce the documented restriction: testStr must not be null.
        Objects.requireNonNull(testStr, "testStr must not be null");

        int length = testStr.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only count consonants.
            if (isVowel(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check the character to the left.
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }

            // Check the character to the right.
            if (i < length - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /**
     * Returns {@code true} if the given character is a vowel
     * (a, e, i, o, u) in either lower‑case or upper‑case.
     *
     * @param ch the character to test
     * @return {@code true} if {@code ch} is a vowel, {@code false} otherwise
     */
    private static boolean isVowel(char ch) {
        return "aeiouAEIOU".indexOf(ch) >= 0;
    }

    // Simple manual test (not required for the solution)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));           // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

