     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Check parameter validity
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute the sequence using the recurrence:
        // a(0) = 1, a(1) = 1, a(i) = 2*a(i-1) + a(i-2) for i >= 2
        long a0 = 1; // a(i-2)
        long a1 = 1; // a(i-1)
        long a = 0;  // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        // The result fits in int for reasonable n; cast safely.
        return (int) a;
    }
}

