import java.util.*;

public class Maxaverageofpath {
    /**
     * Returns the maximum average value among all paths from the top‑left corner
     * to the bottom‑right corner of the given n×n cost matrix. Movement is
     * restricted to right or down steps.
     *
     * @param cost the n×n matrix of costs (List of Lists of Integer)
     * @param n    the dimension of the square matrix
     * @return     the maximum average path value, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- Parameter validation (Item 49) ----
        if (cost == null) {
            throw new NullPointerException("cost must not be null");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException("cost.size() must equal n");
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null) {
                throw new NullPointerException("cost row " + i + " must not be null");
            }
            if (row.size() != n) {
                throw new IllegalArgumentException("row " + i + " must have length n");
            }
        }

        // ---- DP to compute the maximal sum ----
        long[][] dp = new long[n][n];
        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);
        return average;
    }
}

