class CountVowels {
    /**
     * Counts characters that are **not** vowels but have at least one vowel
     * neighbor (the character immediately before or after them).
     *
     * The check is case‑insensitive; only 'a', 'e', 'i', 'o', 'u' (and their
     * uppercase forms) are considered vowels.
     *
     * @param testStr the input string (must not be null)
     * @return the number of such characters
     * @throws NullPointerException if testStr is null
     */
    public static int countVowels(String testStr) {
        // ITEM 49: Check parameters for validity
        Objects.requireNonNull(testStr, "Input string must not be null");

        int len = testStr.length();
        // A string of length 0 or 1 can never have a non‑vowel with a vowel neighbour
        if (len <= 1) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            if (isVowel(ch)) {
                // Skip vowels themselves – we only count non‑vowel characters
                continue;
            }

            boolean hasVowelNeighbor = false;
            // check previous character
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // check next character (if not already found a vowel neighbour)
            if (!hasVowelNeighbor && i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    /** Helper that returns true if the given character is a vowel (case‑insensitive). */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u';
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

