class SeriesSum {
    /**
     * Calculates the sum of the squares of the first {@code n} positive integers:
     * 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms (must be non‑negative)
     * @return the sum of the series
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        // Check parameter for validity (Item 49)
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative: " + number);
        }

        // Use the closed‑form formula: n(n+1)(2n+1)/6.
        // Compute in long to avoid overflow before the division.
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;

        // The problem statement expects an int return type.
        return (int) sum;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));  // 91
        System.out.println(seriesSum(7));  // 140
        System.out.println(seriesSum(12)); // 650
    }
}

