class NewmanPrime {
    /**
     * Returns the nth Newman–Shanks–Williams prime.
     * Based on the examples, this returns the (n-1)th prime in the NSW sequence.
     *
     * @param n the index (1-indexed)
     * @return the nth NSW prime
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (n == 1) {
            return 3; // First NSW prime
        }
        // For n >= 2, return the (n-1)th NSW prime
        return nswPrime(n - 1);
    }

    // Helper method to return the kth NSW prime (1-indexed)
    private static int nswPrime(int k) {
        if (k <= 0) {
            throw new IllegalArgumentException("k must be positive");
        }
        int count = 0;
        long a0 = 1;
        long a1 = 1;
        while (true) {
            long a = 2 * a1 + a0;
            if (isPrime(a)) {
                count++;
                if (count == k) {
                    return (int) a;
                }
            }
            a0 = a1;
            a1 = a;
        }
    }

    // Primality test for long values
    private static boolean isPrime(long n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (long i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }
}

