/**
 * Utility class that demonstrates removing “odd” characters from a string.
 *
 * <p>For this problem “odd” means “odd position” when positions are counted
 * from 1 (i.e. 1, 3, 5, …).  Therefore the method keeps the characters at
 * even positions (2, 4, 6, …) and returns them as a new string.
 *
 * <p>Examples:
 * <ul>
 *   <li>{@code removeOdd("python")   → "yhn"}</li>
 *   <li>{@code removeOdd("program")  → "rga"}</li>
 *   <li>{@code removeOdd("language") → "agae"}</li>
 * </ul>
 */
class RemoveOdd {

    /**
     * Removes characters at odd positions (1‑based) from the input string.
     *
     * @param str1 the original string; must not be {@code null}
     * @return a new string consisting of the characters that were at even
     *         positions (2, 4, 6, …) in the original string
     * @throws IllegalArgumentException if {@code str1} is {@code null}
     */
    public static String removeOdd(String str1) {
        // ---- Explicit validity check (Item 73) ----
        if (str1 == null) {
            throw new IllegalArgumentException("Input string must not be null");
        }

        // Use StringBuilder for O(n) construction of the result
        StringBuilder result = new StringBuilder(str1.length() / 2 + 1);

        // Keep characters whose 1‑based index is even → 0‑based index is odd
        for (int i = 0; i < str1.length(); i++) {
            if (i % 2 == 1) {               // i = 1 → 2nd character, i = 3 → 4th, …
                result.append(str1.charAt(i));
            }
        }

        return result.toString();
    }

    // ---- Simple test driver ----
    public static void main(String[] args) {
        String[] tests = { "python", "program", "language", "", "a", "ab" };
        for (String s : tests) {
            System.out.printf("removeOdd(%-10s) → \"%s\"%n",
                    s == null ? "null" : "\"" + s + "\"", removeOdd(s));
        }
    }
}

