class TextMatchWordzMiddle {

    /**
     * Determines whether any word in the given text contains the letter 'z'
     * somewhere other than the first or last position of that word.
     *
     * @param text the input string to be examined
     * @return "Found a match!" if a word with a middle 'z' is found,
     *         otherwise "Not matched!"
     * @throws IllegalArgumentException if text is null
     */
    public static String textMatchWordzMiddle(String text) {
        // ---- Parameter validation (Item 73/76) ----
        if (text == null) {
            throw new IllegalArgumentException("Input text must not be null");
        }

        // Split the input on whitespace to obtain individual words/tokens.
        // This also handles multiple spaces, tabs, newlines, etc.
        String[] words = text.split("\\s+");

        for (String word : words) {
            // Ignore empty tokens (e.g., from consecutive delimiters)
            if (word.isEmpty()) {
                continue;
            }

            // A middle character can only exist if the word has at least 3 characters.
            if (word.length() < 3) {
                continue;
            }

            // Look for a 'z' that is not at index 0 or at the last index.
            boolean hasMiddleZ = false;
            for (int i = 1; i <= word.length() - 2; i++) {
                if (word.charAt(i) == 'z') {
                    hasMiddleZ = true;
                    break; // no need to search further
                }
            }

            if (hasMiddleZ) {
                return "Found a match!";
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

    // -----------------------------------------------------------------
    // Optional test driver (can be removed when integrating into a larger project)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));     // "Not matched!"
    }
}

