public class Maxaverageofpath {

    /**
     * Finds a path with the maximum average over all existing paths
     * in the given n×n matrix.  Paths start at the upper‑left cell (0,0)
     * and end at the lower‑right cell (n‑1,n‑1); they may only move
     * right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum possible average (as a {@code Double})
     * @throws IllegalArgumentException if the matrix is null, not square,
     *         or its dimension does not match n
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- explicit validity check ---------------------------------
        if (cost == null) {
            throw new IllegalArgumentException("Matrix cost must not be null");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("Matrix dimension n must be positive");
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException(
                "Matrix size mismatch: expected " + n + " rows, got " + cost.size());
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException(
                    "Row " + i + " is null or does not have " + n + " columns");
            }
        }
        // --------------------------------------------------------------

        // dp[i][j] = maximum sum to reach cell (i, j) from (0,0)
        long[][] dp = new long[n][n];

        // initial cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                           + cost.get(i).get(j);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;               // number of cells in any valid path
        double average = (double) maxSum / pathLength;

        return Double.valueOf(average);
    }

