public static int countVowels(String testStr) {
    // Enforce the precondition: the argument must not be null.
    if (testStr == null) {
        throw new IllegalArgumentException("Input string must not be null");
    }

    // Vowel set (both lower‑ and upper‑case are handled by toLowerCase).
    final String vowels = "aeiou";

    int count = 0;
    int len = testStr.length();

    for (int i = 0; i < len; i++) {
        char ch = testStr.charAt(i);
        // Consider only consonants; skip vowels.
        if (vowels.indexOf(Character.toLowerCase(ch)) == -1) {
            boolean hasVowelNeighbor = false;

            // Check the left neighbour.
            if (i > 0) {
                char left = testStr.charAt(i - 1);
                if (vowels.indexOf(Character.toLowerCase(left)) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            // Check the right neighbour (if not already found).
            if (!hasVowelNeighbor && i < len - 1) {
                char right = testStr.charAt(i + 1);
                if (vowels.indexOf(Character.toLowerCase(right)) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
    }
    return count;
}

