class SeriesSum {
    /**
     * Calculates the sum of the squares of the first {@code n} natural numbers:
     * 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms (must be non‑negative)
     * @return the sum of squares of the first {@code number} positive integers
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        // ---- explicit validity check (Item 49) ----
        if (number < 0) {
            throw new IllegalArgumentException("Parameter 'number' must be non‑negative; got " + number);
        }

        // ---- compute using the closed‑form formula ----
        // n * (n + 1) * (2n + 1) / 6
        // Use long arithmetic to avoid intermediate overflow.
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;

        // The result always fits in an int for the range where int is safe,
        // so we can safely cast back to int.
        return (int) sum;
    }

    // ---- simple test harness ----
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12)); // 650
    }
}

