class NewmanPrime {
    /**
     * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Guard against invalid input
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases of the Newman‑Shanks‑Williams sequence
        if (n == 0 || n == 1) {
            return 1;   // a(0) = a(1) = 1
        }

        // Iteratively compute a(i) = 2*a(i‑1) + a(i‑2)
        long prev2 = 1; // a(0)
        long prev1 = 1; // a(1)
        long cur = 0;

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2;
            // shift the window for the next iteration
            prev2 = prev1;
            prev1 = cur;
        }

        // The problem expects an int; the sequence fits in int for the given test cases.
        return (int) cur;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

