class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // -----------------------------------------------------------------
        // Defensive copy note:
        // String is immutable in Java, so the caller cannot alter the
        // underlying character array after we receive the reference.
        // If we were dealing with a mutable type (e.g., char[] or a
        // mutable collection), we would create a defensive copy before
        // processing to guard against later modification.
        // -----------------------------------------------------------------
        if (text == null) {
            return "Not matched!";
        }

        // Pattern that matches a word: one or more ASCII letters.
        // This automatically skips punctuation, spaces, digits, etc.
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A 'z' can only be in the middle if the word has at least
            // three letters (so there is a character before and after it).
            // We check the substring that excludes the first and last chars.
            if (word.length() >= 3
                    && word.substring(1, word.length() - 1).contains("z")) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    // -----------------------------------------------------------------
    // Optional test driver
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));  // Not matched!

        // Additional sanity checks
        System.out.println(textMatchWordzMiddle("zabc"));       // Not matched (z at start)
        System.out.println(textMatchWordzMiddle("abcz"));       // Not matched (z at end)
        System.out.println(textMatchWordzMiddle("zzz"));        // Found a match! (middle z)
        System.out.println(textMatchWordzMiddle("abcze"));      // Found a match!
    }
}

import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that travels
     * from the top‑left corner to the bottom‑right corner of the
     * n×n matrix. Movement is restricted to right and down steps.
     *
     * @param cost  the n×n matrix of path costs
     * @param n     size of the square matrix
     * @return      the maximum average as a {@code Double}, or {@code null}
     *              if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- defensive checks -------------------------------------------------
        if (cost == null || n <= 0) {
            return null;
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException(
                "Matrix size mismatch: cost.size() = " + cost.size() + ", expected " + n);
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException(
                    "Row " + i + " is not of length " + n);
            }
        }

        // ---- copy the input into a primitive array (defensive copy) ---------
        long[][] dp = new long[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dp[i][j] = cost.get(i).get(j);
            }
        }

        // ---- DP: maximum sum to each cell ------------------------------------
        // first cell
        // dp[0][0] already contains cost[0][0]

        // first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] += dp[0][j - 1];
        }

        // first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] += dp[i - 1][0];
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] += Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average --------------------------------------------------
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);

        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------------
    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = new ArrayList<>(Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = new ArrayList<>(Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = new ArrayList<>(Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

