import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     *
     * The NSW sequence is defined by:
     *   s0 = 1, s1 = 1
     *   si = 2 * s(i‑1) + s(i‑2)   for i ≥ 2
     * The primes that appear in this sequence are:
     *   3, 7, 17, 41, 239, 577, 8119, …
     *
     * Based on the examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * The method returns the (n‑1)-th prime in the list (i.e. newmanPrime(2) = 3).
     *
     * @param n the index (must be ≥ 2; for n = 1 the first prime 3 is returned)
     * @return the corresponding Newman–Shanks–Williams prime
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // n == 1 is not part of the official examples, but we return the first prime for completeness.
        if (n == 1) {
            return 3;               // first NSW prime
        }

        // Collect NSW primes until we have (n‑1) of them.
        List<Integer> primes = new ArrayList<>();

        long a0 = 1;   // s0
        long a1 = 1;   // s1

        // Generate the sequence starting from index 2 (s2 = 3)
        for (int i = 2; ; i++) {
            long a2 = 2 * a1 + a0;   // si = 2*s(i‑1) + s(i‑2)

            if (isPrime(a2)) {
                primes.add((int) a2);
                // When we have collected enough primes, return the last one.
                if (primes.size() == n - 1) {
                    return primes.get(primes.size() - 1);
                }
            }

            // Shift the window for the next iteration
            a0 = a1;
            a1 = a2;
        }
    }

    /**
     * Simple deterministic primality test for small to medium numbers.
     * Works for values that fit in a long.
     */
    private static boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }
        long limit = (long) Math.sqrt(num);
        for (long d = 3; d <= limit; d += 2) {
            if (num % d == 0) {
                return false;
            }
        }
        return true;
    }
}

