import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that travels
     * from the top‑left cell to the bottom‑right cell of the given n×n
     * matrix.  Movement is allowed only to the right or downwards.
     *
     * @param cost  list of rows, each row is a list of integer costs
     * @param n     dimension of the square matrix (number of rows/columns)
     * @return      the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table: dp[i][j] holds the maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table: choose the better predecessor
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The path length (number of cells visited) is always 2*n - 1
        int pathLength = 2 * n - 1;
        double maxSum = dp[n - 1][n - 1];
        return maxSum / pathLength;
    }
}

