     * Counts characters that are not vowels and have at least one vowel
     * as an immediate neighbour (left or right).
     *
     * @param testStr the input string (may contain letters, case‑insensitive)
     * @return the number of such characters
     * @throws IllegalArgumentException if testStr is null
     */
    public static int countVowels(String testStr) {
        // Defensive check – validate the input (Item 49)
        if (testStr == null) {
            throw new IllegalArgumentException("Input string must not be null");
        }

        // Set for O(1) vowel lookup (both lower‑ and upper‑case)
        Set<Character> vowelSet = new HashSet<>();
        for (char c : "aeiouAEIOU".toCharArray()) {
            vowelSet.add(c);
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
