            }
            // Check right neighbour
            if (i < len - 1 && vowelSet.contains(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

