    public static int seriesSum(int number) {
        // Guard against illegal/non‑positive input
        if (number <= 0) {
            return 0;
        }

        // Use long to avoid intermediate overflow, then cast back to int
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The problem constraints guarantee the result fits in an int,
        // so a narrowing conversion is safe here.
        return (int) sum;
    }

