import java.math.BigInteger;

/**
 * Utility class for computing Newman‑Shanks‑Williams numbers.
 *
 * The n‑th NSW number (n ≥ 1) is defined by
 *   s0 = 1, s1 = 1,
 *   sn = 2·sn‑1 + sn‑2  (n ≥ 2).
 *
 * For n ≥ 2 many of these numbers are prime; the method returns the
 * raw sequence value (the "n‑th NSW prime" in the problem statement).
 */
public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * @param n the index (1‑based) of the desired number
     * @return the value sn of the NSW sequence
     * @throws IllegalArgumentException if n is not positive
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // Use BigInteger to avoid overflow for moderately large n.
        BigInteger prev2 = BigInteger.ONE; // s0
        BigInteger prev1 = BigInteger.ONE; // s1

        if (n == 1) {
            return prev1.intValue(); // s1 = 1
        }

        BigInteger current = null;
        for (int i = 2; i <= n; i++) {
            // sn = 2 * sn-1 + sn-2
            current = prev1.multiply(BigInteger.valueOf(2)).add(prev2);
            // shift the window
            prev2 = prev1;
            prev1 = current;
        }

        // The result fits into int for the test data; otherwise the
        // caller can work with BigInteger if needed.
        return prev1.intValue();
    }

    // Simple sanity checks (not part of the required solution)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

