public class Maxaverageofpath {
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive copy of the input to avoid external modification
        if (cost == null || n <= 0 || cost.size() < n) {
            return null;
        }
        // Create a 2D double array for DP
        double[][] dp = new double[n][n];
        // Initialize the start cell
        dp[0][0] = cost.get(0).get(0);
        // Fill the first row
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j-1] + cost.get(0).get(j);
        }
        // Fill the first column
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i-1][0] + cost.get(i).get(0);
        }
        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i-1][j], dp[i][j-1]);
            }
        }
        // The number of cells visited in any monotonic path from top‑left to bottom‑right
        int cells = 2 * n - 1;
        double average = dp[n-1][n-1] / cells;
        return Double.valueOf(average);
    }
}

