public class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     *
     * The sequence is defined by
     *   b0 = 1, b1 = 3,
     *   bk = 2*bk‑1 + bk‑2   (k ≥ 2)
     * and the function returns b_{n‑1}.
     *
     * @param n the index (must be ≥ 1)
     * @return the value b_{n‑1}
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        // Defensive check – fail fast on illegal input
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // b0 = 1, b1 = 3
        BigInteger prev = BigInteger.ONE;          // b_{k‑2}
        BigInteger curr = BigInteger.valueOf(3);  // b_{k‑1}

        // If n == 1 we need b0 = 1 (the problem never asks for this case,
        // but we return it for completeness)
        if (n == 1) {
            return prev.intValue();
        }

        // Compute b2 … b_{n‑1}
        for (int i = 2; i <= n - 1; i++) {
            // bk = 2 * b_{k‑1} + b_{k‑2}
            BigInteger next = curr.multiply(BigInteger.valueOf(2)).add(prev);
            prev = curr;
            curr = next;
        }

        // The result fits in an int for the typical range of n.
        // If it does not, the conversion throws an ArithmeticException.
        return curr.intValue();
    }

    // -----------------------------------------------------------------
    // Optional test harness (not required for the solution itself)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example usage:
        System.out.println(newmanPrime(3)); // → 7
        System.out.println(newmanPrime(4)); // → 17
        System.out.println(newmanPrime(5)); // → 41
    }
}

