import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that starts at the top‑left
     * corner of the given n×n matrix and ends at the bottom‑right corner.
     * Movement is restricted to the two directions: right and down.
     *
     * @param cost the n×n matrix of integers
     * @param n    the dimension of the square matrix
     * @return the maximum average (as a Double) of all valid paths,
     *         or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The maximum sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // Number of cells in any such path = 2 * n - 1
        double average = maxSum / (2 * n - 1);

        return average;               // auto‑boxed to Double
    }
}

