class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams (NSW) sequence.
     * The sequence is defined by:
     *   a_0 = 1, a_1 = 1
     *   a_i = 2 * a_{i-1} + a_{i-2}   for i >= 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Guard against non‑positive indices – the 0‑th term is defined as 1.
        if (n <= 0) {
            return 1;
        }
        if (n == 1) {
            return 1;   // a_1 = 1
        }

        // Iteratively compute the sequence.
        // a0 holds a_{i-2}, a1 holds a_{i-1}.
        int a0 = 1; // a_0
        int a1 = 1; // a_1
        int a = 0;  // a_i

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a_i = 2*a_{i-1} + a_{i-2}
            a0 = a1;
            a1 = a;
        }
        return a;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

