public class Maxaverageofpath {

    /**
     * Finds a path with the maximum average over all existing paths
     * in the given n×n matrix. Movement is allowed only to the right
     * or down, starting at (0,0) and ending at (n‑1,n‑1).
     *
     * @param cost the square matrix represented as a list of rows
     * @param n    the size of the matrix (number of rows/columns)
     * @return the maximum average value of a path, or null if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Defensive checks for invalid input
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // DP table: dp[i][j] holds the maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // Initialize the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // The best possible sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // All monotonic paths have exactly (2*n - 1) cells
        double average = maxSum / (2 * n - 1);

        return average;
    }
}

