     * Counts characters that are not vowels but have a vowel as one of their
     * immediate neighbours (left or right).
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        // Defensive check – String is immutable, so no copy is required.
        if (testStr == null) {
            return 0;
        }

        int length = testStr.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels themselves – we only count consonants (or any
            // non‑vowel characters) that are adjacent to a vowel.
            if (isVowel(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check the character to the left
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check the character to the right (if not already found)
            if (!hasVowelNeighbor && i < length - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

