import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that travels from the
     * top‑left to the bottom‑right of the given n×n matrix, moving only
     * right or down.  The average is the sum of the cell values divided
     * by the number of cells visited (always 2·n‑1).
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return     the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table holds the best sum to reach each cell (i, j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum reaches the bottom‑right cell
        long maxSum = dp[n - 1][n - 1];

        // Average = sum / (number of visited cells) = sum / (2·n‑1)
        double average = (double) maxSum / (2L * n - 1);

        return average;
    }
}

