class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2 * a(n‑1) + a(n‑2)  for n ≥ 2
     *
     * @param n index (0‑based)
     * @return the n‑th term of the NSW sequence
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // a(0) = 1, a(1) = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a  = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }

    // Simple test (optional)
    public static void main(String[] args) {
        for (int i = 0; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

