public class Maxaverageofpath {
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // handle trivial case
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i,j) from (0,0) moving only right or down
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double val = cost.get(i).get(j); // auto‑boxing int -> Double
                if (i == 0 && j == 0) {
                    dp[i][j] = val;
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // number of cells visited = 2*n - 1
        double average = maxSum / (2 * n - 1);
        return Double.valueOf(average);
    }

    // Simple test driver
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
