        // Use BigInteger to avoid overflow for larger n
        BigInteger a0 = BigInteger.ONE; // a(0)
        BigInteger a1 = BigInteger.ONE; // a(1)

        for (int i = 2; i <= n; i++) {
            BigInteger a2 = a1.multiply(BigInteger.valueOf(2)).add(a0); // a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a2;
        }

        // The problem expects an int; the values are assumed to fit into int
        return a1.intValue();
    }
}

