                        return "Found a match!";
                    }
                }
            }
        }

        // No word with a middle‑position ‘z’ was found
        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));        // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));     // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given
     * n×n cost matrix. Movement is restricted to right or down steps only.
     *
     * @param cost  list of rows, each row a list of integer cell costs
     * @param n     size of the square matrix
     * @return      maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = best sum to reach (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long cell = cost.get(i).get(j).longValue();

                if (i == 0 && j == 0) {
                    // starting cell
                    dp[i][j] = cell;
                } else {
                    long fromAbove = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                    long fromLeft  = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;
                    dp[i][j] = Math.max(fromAbove, fromLeft) + cell;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2L * n - 1);
        return average;
    }

    // -----------------------------------------------------------------
    // Optional simple test driver (not required by the problem statement)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

