class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1
     *   a(1) = 1
     *   a(n) = 2*a(n‑1) + a(n‑2)   for n >= 2
     *
     * Examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n the index (0‑based) of the desired number
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        BigInteger a0 = BigInteger.ONE; // a(0)
        BigInteger a1 = BigInteger.ONE; // a(1)
        BigInteger a  = BigInteger.ZERO;

        for (int i = 2; i <= n; i++) {
            // a(i) = 2*a(i‑1) + a(i‑2)
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            // shift the window for the next iteration
            a0 = a1;
            a1 = a;
        }

        // The method’s return type is int; we assume n is small enough to fit.
        return a.intValue();
    }

    // A tiny test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

