public class VolumeTetrahedron {

    /**
     * Calculates the volume of a regular tetrahedron whose side length is `num`.
     *
     * @param num the side length of the tetrahedron
     * @return the volume rounded to two decimal places
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        // Convert the int to double for the calculation
        double side = num;

        // Volume of a regular tetrahedron: V = a^3 / (6 * sqrt(2))
        double volume = Math.pow(side, 3) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places (as shown in the examples)
        volume = Math.round(volume * 100.0) / 100.0;

        return volume;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

