/**
 * Utility class that provides a method to detect a word that contains the
 * letter 'z' somewhere other than at the very start or the very end.
 */
public class TextMatchWordzMiddle {

    /**
     * Checks the supplied text for any word that contains the character 'z'
     * (case‑insensitive) in a position other than the first or last character.
     *
     * @param text the input string to be examined
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // \b = word boundary, \w+ = one or more word characters (letters, digits, _)
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // the actual word
            String lowerWord = word.toLowerCase();       // make the check case‑insensitive
            int zIndex = lowerWord.indexOf('z');

            // z must be present, and it must not be the first or last character
            if (zIndex != -1 && zIndex != 0 && zIndex != word.length() - 1) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // --------------------------------------------------------------
    // Optional quick‑test driver (feel free to remove or comment out)
    // --------------------------------------------------------------
    public static void main(String[] args) {
        String[] tests = {
            "pythonzabc.",
            "xyzabc.",
            "  lang  .",
            "zabc",
            "abcz",
            "azb",
            "The quick brown fox jumps over the lazy dog."
        };

        for (String t : tests) {
            System.out.println(t + " -> " + textMatchWordzMiddle(t));
        }
    }
}

