import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given
     * n×n matrix. Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a Double, or null for invalid input
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: long to avoid overflow of the sum
        long[][] dp = new long[n][n];

        // First cell
        dp[0][0] = cost.get(0).get(0);

        // Fill first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Remaining cells: optimal of coming from top or left + current cost
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) +
                           Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2L * n - 1);

        return Double.valueOf(average);
    }

    // --------------------------------------------------------------------
    // Simple manual test (not part of the required solution)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
