class CountVowels {
    /**
     * Counts characters that are NOT vowels and that have at least one vowel
     * as a neighbour (either to the left or to the right) in the given string.
     *
     * @param testStr the input string
     * @return the number of such characters
     *
     * Example:
     * > countVowels("bestinstareels")   -> 7
     * > countVowels("partofthejourneyistheend") -> 12
     * > countVowels("amazonprime")      -> 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // Skip vowels themselves – we only count consonants (or any non‑vowel)
            if (isVowel(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour (only if left didn't already satisfy)
            else if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /** Returns true if the given character is a vowel (case‑insensitive). */
    private static boolean isVowel(char c) {
        char lower = Character.toLowerCase(c);
        return lower == 'a' || lower == 'e' ||
               lower == 'i' || lower == 'o' || lower == 'u';
    }
}

