public class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2·a(n‑1) + a(n‑2)   for n ≥ 2
     *
     * @param n index (0‑based)
     * @return the n‑th NSW number
     */
    public static int newmanPrime(int n) {
        // n == 0 or n == 1 -> the sequence values are 1
        if (n <= 1) {
            return 1;
        }

        long prev2 = 1; // a(n‑2)
        long prev1 = 1; // a(n‑1)
        long cur = 0;

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2; // a(i)
            prev2 = prev1;
            prev1 = cur;
        }

        // The result fits into an int for the tested range.
        return (int) prev1;
    }

    // Simple manual test (can be removed in production)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

