class CountVowels {

    /** Vowel set – both lower‑ and uppercase. */
    private static final Set<Character> VOWELS = Set.of(
            'a', 'e', 'i', 'o', 'u',
            'A', 'E', 'I', 'O', 'U'
    );

    /**
     * Returns the number of consonants (non‑vowel characters) that have
     * at least one vowel as an immediate neighbour (left or right).
     *
     * Examples:
     *   countVowels("bestinstareels")      → 7
     *   countVowels("partofthejourneyistheend") → 12
     *   countVowels("amazonprime")        → 5
     *
     * @param testStr the input string (may be null)
     * @return the count described above
     */
    public static int countVowels(String testStr) {
        // Defensive: treat null as an empty string
        return countVowels(testStr == null ? new char[0] : testStr.toCharArray());
    }

    /**
     * Overloaded version that works directly on a char array.
     * This overload is "radically different" from the String version,
     * so there is no ambiguity even with autoboxing (Java 5+).
     *
     * @param a the character array
     * @return the count of consonants that are adjacent to a vowel
     */
    public static int countVowels(char[] a) {
        int count = 0;
        for (int i = 0; i < a.length; i++) {
            char c = a[i];
            // We only count characters that are NOT vowels themselves
            if (VOWELS.contains(c)) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbor = (i > 0 && VOWELS.contains(a[i - 1]));
            // Check right neighbour if left didn't already give us a match
            if (!hasVowelNeighbor && i < a.length - 1) {
                hasVowelNeighbor = VOWELS.contains(a[i + 1]);
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    // --------------------------------------------------------------------
    // Simple manual test (you can remove / comment out in production)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

