class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   ai = 2 * a(i‑1) + a(i‑2)  for i >= 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Basic cases – the sequence is defined for n >= 0
        if (n <= 0) return 1;   // a0
        if (n == 1) return 1;   // a1

        // Use long to avoid overflow before casting back to int.
        long prev2 = 1; // a0
        long prev1 = 1; // a1
        long cur = 0;

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2; // ai = 2*a(i‑1) + a(i‑2)
            prev2 = prev1;
            prev1 = cur;
        }
        return (int) cur; // the problem expects an int result
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

