import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a monotonic path
     * (right‑down only) from the top‑left corner to the bottom‑right
     * corner of the given n×n cost matrix.
     *
     * @param cost  a square matrix represented as a List of List of Integer
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] holds the greatest sum reachable at cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cur = cost.get(i).get(j);          // current cell cost
                if (i == 0 && j == 0) {
                    dp[i][j] = cur;                    // start cell
                } else {
                    double best = Double.NEGATIVE_INFINITY;
                    if (i > 0) best = Math.max(best, dp[i - 1][j]); // from above
                    if (j > 0) best = Math.max(best, dp[i][j - 1]); // from left
                    dp[i][j] = cur + best;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // Every monotonic path has exactly (2*n - 1) cells
        double average = maxSum / (2 * n - 1);
        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------
    // Simple test harness (you can delete or comment it out when integrating)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // expected 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // expected 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // expected 7.2
    }
}

