public class CountVowels {

    /**
     * Counts characters that are not vowels but have a vowel as an immediate neighbour.
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        // Vowel set – we treat both lower‑ and upper‑case as vowels.
        final String VOWELS = "aeiouAEIOU";

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels themselves – we only count consonants.
            if (VOWELS.indexOf(ch) != -1) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0) {
                char left = testStr.charAt(i - 1);
                if (VOWELS.indexOf(left) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbour (if we haven't already found a vowel neighbour)
            if (!hasVowelNeighbor && i < len - 1) {
                char right = testStr.charAt(i + 1);
                if (VOWELS.indexOf(right) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // --------------------------------------------------------------------
    // Optional simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12 (or 11 – see note)
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

