public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // dp[j] – best sum to reach cell (current row, column j)
    double[] dp = new double[n];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int val = cost.get(i).get(j);           // value of the current cell

            if (i == 0 && j == 0) {
                // start cell
                dp[j] = val;
            } else if (i == 0) {
                // first row – can only come from the left
                dp[j] = dp[j - 1] + val;
            } else if (j == 0) {
                // first column – can only come from above
                dp[0] = dp[0] + val;
            } else {
                // take the better of coming from above or from the left
                dp[j] = Math.max(dp[j], dp[j - 1]) + val;
            }
        }
    }

    // The path always contains (2*n - 1) cells (n-1 moves right + n-1 moves down + start)
    double maxSum = dp[n - 1];
    double average = maxSum / (2 * n - 1);
    return average;
}

