class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron given its side length.
     *
     * The volume of a regular tetrahedron with side a is:
     *     V = (sqrt(2) / 12) * a^3
     *
     * @param num the side length of the tetrahedron
     * @return the volume rounded to two decimal places
     */
    public static Double volumeTetrahedron(int num) {
        double side = num;                     // side length a
        // Volume formula for a regular tetrahedron
        double volume = (Math.sqrt(2.0) / 12.0) * side * side * side;

        // Round to two decimal places (e.g., 117.851130... → 117.85)
        double rounded = Math.round(volume * 100.0) / 100.0;

        return rounded;                        // auto‑boxed to Double
    }

    // Optional test driver (not required by the problem)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

