class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' (or 'Z') somewhere other than the first or last character
     * of that word; otherwise returns "Not matched!".
     *
     * @param text the input string to examine
     * @return     appropriate message indicating whether a matching word exists
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split on one or more whitespace characters – punctuation stays part of the word
        String[] words = text.split("\\s+");

        for (String word : words) {
            // Look for 'z' (case‑insensitive)
            int idx = word.indexOf('z');
            if (idx == -1) {
                idx = word.indexOf('Z');
            }

            // If a 'z' was found and it is neither the first nor the last character
            if (idx != -1 && idx != 0 && idx != word.length() - 1) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    // Simple manual test driver
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));        // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));      // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a monotone path (only moves right or down)
     * from the top‑left corner to the bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost a square matrix (List of Lists) containing the cell costs
     * @param n    size of the matrix (cost.size() == n)
     * @return     the highest possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against empty input
        if (cost == null || cost.isEmpty() || cost.get(0).isEmpty()) {
            return null;
        }

        int N = n;                     // matrix dimension
        double[][] dp = new double[N][N];

        // Initialize the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < N; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < N; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the DP table
        for (int i = 1; i < N; ++i) {
            for (int j = 1; j < N; ++j) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                           + cost.get(i).get(j);
            }
        }

        // The best sum to reach the bottom‑right corner
        double maxSum = dp[N - 1][N - 1];

        // Number of cells visited on any monotone path = 2*n - 1
        double average = maxSum / (2.0 * N - 1.0);

        return average;   // auto‑boxed to Double
    }

    // -----------------------------------------------------------------
    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

