public class CountAlphaDigSpl {

    /**
     * Counts alphabets, digits and special characters in a given string.
     *
     * @param string the input text (may be null or empty)
     * @return a List containing three integers:
     *         - number of alphabetic characters (a‑z, A‑Z)
     *         - number of digit characters (0‑9)
     *         - number of all other characters
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Guard against null input
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alphas = 0;
        int digits = 0;
        int specials = 0;

        for (char ch : string.toCharArray()) {
            if (Character.isLetter(ch)) {
                alphas++;
            } else if (Character.isDigit(ch)) {
                digits++;
            } else {
                specials++;
            }
        }

        // Returns [alphabets, digits, special characters]
        return Arrays.asList(alphas, digits, specials);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

