class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams “prime” number.
     *
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   a_i = 2 * a_{i-1} + a_{i-2}  (i >= 2)
     *
     * The values for i = 2,3,4,… are 3, 7, 17, 41, … which are primes.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // a0 = 1, a1 = 1
        long a0 = 1;
        long a1 = 1;
        long a = 1; // will hold a_n

        // Compute a_i for i = 2 … n
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a_i = 2*a_{i-1} + a_{i-2}
            a0 = a1;
            a1 = a;
        }

        // For n == 1 we return a0 (which is 1), but the problem expects n >= 2.
        return (int) a;
    }
}

