class RemoveOdd {
    /**
     * Removes characters at odd positions (1‑based) from the given string.
     *
     * Example:
     *   removeOdd("python") → "yhn"
     *   removeOdd("program") → "rga"
     *   removeOdd("language") → "agae"
     *
     * @param str1 the input string (may be null)
     * @return a new string containing only the characters at even positions,
     *         or null if the input is null
     */
    public static String removeOdd(String str1) {
        // Guard against null input
        if (str1 == null) {
            return null;
        }

        StringBuilder result = new StringBuilder();

        // Start at index 1 (the second character) and step by 2
        // to pick characters at even positions (1‑based).
        for (int i = 1; i < str1.length(); i += 2) {
            result.append(str1.charAt(i));
        }

        return result.toString();
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));   // "yhn"
        System.out.println(removeOdd("program")); // "rga"
        System.out.println(removeOdd("language"));// "agae"
    }
}

