class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' somewhere other than the first or last character of the word.
     * Otherwise returns "Not matched!".
     *
     * @param text the input string to be examined
     * @return the appropriate message
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches a contiguous sequence of letters (a–z or A–Z).
        // This automatically strips punctuation such as '.' or ','.
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // the actual word found
            String lower = word.toLowerCase();            // case‑insensitive check

            int idx = lower.indexOf('z');                 // position of 'z' (or -1)
            // 'z' must be present and not at the first or last position
            if (idx != -1 && idx > 0 && idx < lower.length() - 1) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));        // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));      // "Not matched!"
    }
}

