class Maxaverageofpath {
    /**
     * Find a path with the maximum average over all existing paths
     * for the given square matrix of size n*n.
     *
     * The path starts at (0,0) and ends at (n‑1,n‑1) and may only
     * move right or down. The average is computed over the values of
     * the cells that belong to the path.
     *
     * @param cost 2‑D list representing the n×n matrix
     * @param n    size of the matrix
     * @return the maximum possible average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = max sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the DP table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The total number of cells visited on any valid path is 2*n‑1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // expected 5.2

        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // expected 6.2

        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // expected 7.2
    }
}

