class CountVowels {

    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() == 0) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // If the current character is a vowel we do not count it
            if (isVowel(ch)) {
                continue;
            }

            // Check left neighbour
            boolean leftIsVowel = (i > 0) && isVowel(testStr.charAt(i - 1));
            // Check right neighbour
            boolean rightIsVowel = (i < len - 1) && isVowel(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

    /** Helper method that returns true if c is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // -----------------------------------------------------------------
    // Optional: a small main to demonstrate the examples given in the
    // javadoc.  This is not required for the solution but helps to verify
    // the implementation.
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

