class SeriesSum {
    /**
     * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        if (number <= 0) {
            return 0;                 // no terms to sum for non‑positive input
        }
        // Use the formula n*(n+1)*(2n+1)/6 to compute the sum in O(1) time.
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;
        return (int) sum;              // the result fits in an int for typical inputs
    }
}

