import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * Returns the n-th Newman-Shanks-Williams number.
     * For n >= 3, this number is prime based on the given examples.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (n == 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }
        long a0 = 1; // a(n-2)
        long a1 = 1; // a(n-1)
        long a = 0;  // a(n)
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(newmanPrime(3)); // Expected: 7
        System.out.println(newmanPrime(4)); // Expected: 17
        System.out.println(newmanPrime(5)); // Expected: 41
    }
}

