     * A word is defined as a maximal sequence of ASCII letters (A‑Z/a‑z).
     * The check is case‑insensitive, so both 'z' and 'Z' are considered.
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
