import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value among all monotonic
     * (right‑/down‑only) paths from the top‑left corner to the bottom‑right
     * corner of the given n×n cost matrix.
     *
     * @param cost a List of n Lists, each containing n Integer values
     * @param n    the dimension of the square matrix
     * @return the maximum average (as a Double) of any such path
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;                     // invalid input
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // All monotonic paths have exactly (2*n - 1) cells.
        double maxSum = dp[n - 1][n - 1];
        return maxSum / (2 * n - 1);
    }

    // --------------------------------------------------------------------
    // Example usage (you can delete or comment out this main method):
    public static void main(String[] args) {
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

