class NewmanPrime {
    /**
     * Returns the n-th term of the Newman-Shanks-Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2*a(n-1) + a(n-2) for n >= 2.
     *
     * @param n the index (1‑based) of the required term
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }
        long a0 = 1; // a(0)
        long a1 = 1; // a(1)

        if (n == 1) {
            return (int) a1;
        }

        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }
}

