     * (or 'Z') and the 'z' is not the first or last character of that word.
     * Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")      → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")    → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern matches whole words consisting of ASCII letters only.
        // \b marks a word boundary, [A-Za-z]+ captures one or more letters.
        Pattern wordPattern = Pattern.compile("\\b[A-Za-z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();           // the current word
            String lowerWord = word.toLowerCase();   // case‑insensitive comparison

            // Quick check: does the word contain 'z' at all?
            if (!lowerWord.contains("z")) {
                continue; // move to next word
            }

            // We need at least one 'z' that is NOT at position 0 or at the last position.
            // Iterate through the characters to find such a 'z'.
            boolean hasMiddleZ = false;
            for (int i = 0; i < word.length(); i++) {
                if (lowerWord.charAt(i) == 'z' && i != 0 && i != word.length() - 1) {
                    hasMiddleZ = true;
                    break;
                }
            }

            if (hasMiddleZ) {
                return "Found a match!";
            }
            // If all 'z' characters are at the start or end, keep searching other words.
        }

        return "Not matched!";
    }

    // Simple manual test (optional)
