class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left cell (0,0) and ends at the bottom‑right cell (n‑1,n‑1)
     * while moving only right or down.
     *
     * @param cost the n×n matrix of path costs
     * @param n    size of the square matrix
     * @return     the maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // Use long to avoid overflow for large sums
        long[][] dp = new long[n][n];

        // Initialize the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // DP: each cell is the best (maximum) sum to reach it
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // The path always contains exactly (2*n - 1) cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1);

        return average;
    }

    // --------------------------------------------------------------
    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
