class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a₀ = 1, a₁ = 1
     *   aₙ = 2·aₙ₋₁ + aₙ₋₂  for n ≥ 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     *
     * @param n the index (1‑based) of the desired number
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // a0 = aₙ₋₂, a1 = aₙ₋₁
        long a0 = 1; // a₀
        long a1 = 1; // a₁

        // Compute a₂ … aₙ
        for (int i = 2; i <= n; i++) {
            long a = 2 * a1 + a0; // aₙ = 2·aₙ₋₁ + aₙ₋₂
            a0 = a1;
            a1 = a;
        }

        // For n == 1 the loop never runs and a1 is still 1 (a₁)
        // For n == 2 the loop runs once and a1 becomes a₂ = 3, etc.
        return (int) a1;
    }
}

