import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner, ends at the bottom‑right corner and moves only
     * right or down.
     *
     * @param cost square matrix (List of Lists of Integer)
     * @param n    size of the matrix (n × n)
     * @return maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive: empty input → return null (should not happen in valid tests)
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] = maximal sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long cellValue = cost.get(i).get(j).longValue();

                if (i == 0 && j == 0) {
                    dp[i][j] = cellValue;                 // start cell
                } else {
                    long bestPrev = 0;
                    if (i > 0) bestPrev = Math.max(bestPrev, dp[i - 1][j]);
                    if (j > 0) bestPrev = Math.max(bestPrev, dp[i][j - 1]);
                    dp[i][j] = cellValue + bestPrev;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double maxAverage = maxSum / (2.0 * n - 1.0);
        return maxAverage;
    }

    // --------------------------------------------------------------------
    // Optional quick test (can be removed when the method is used elsewhere)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
