public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)   for n >= 2
     *
     * @param n index of the required term (0‑based)
     * @return the n‑th term as an int
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases: a0 = 1, a1 = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long prev2 = 1L; // a0
        long prev1 = 1L; // a1
        long current = 0L;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // an = 2 * a(n‑1) + a(n‑2)
            // shift the window for the next iteration
            prev2 = prev1;
            prev1 = current;
        }

        // The values fit in int for n up to 25; cast is safe for the expected range.
        return (int) current;
    }

    // -----------------------------------------------------------------
    // A tiny test harness (optional)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Provided examples
        System.out.println(newmanPrime(3)); // -> 7
        System.out.println(newmanPrime(4)); // -> 17
        System.out.println(newmanPrime(5)); // -> 41

        // A few more terms
        for (int i = 0; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

