import java.util.List;

/**
 * Finds the maximum average of all paths that go from the top‑left corner
 * to the bottom‑right corner of a square matrix, moving only right or down.
 *
 * @param cost  the n×n matrix of integer costs
 * @param n     size of the matrix (number of rows/columns)
 * @return      the maximum possible average (as a {@code Double})
 * @throws IllegalArgumentException if the input is invalid
 */
public class Maxaverageofpath {

    /** Utility constant – never allocate an empty array repeatedly. */
    private static final double[] EMPTY_DOUBLE_ARRAY = new double[0];

    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation -------------------------------------------------
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Cost list must have exactly n rows.");
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Each row must contain exactly n integers.");
            }
        }

        // ---- DP table ---------------------------------------------------------
        double[][] dp = new double[n][n];
        dp[0][0] = cost.get(0).get(0);

        // first row – only from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }
        // first column – only from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                double bestFrom = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = cost.get(i).get(j) + bestFrom;
            }
        }

        // ---- compute average --------------------------------------------------
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        // The method contract says we return a Double, never null.
        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------------
    // Example usage (not required for the solution, but handy for testing)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

