    private static final Set<Character> VOWELS = Set.of(
            'a', 'e', 'i', 'o', 'u',
            'A', 'E', 'I', 'O', 'U'
    );

    /**
     * Returns the number of characters in {@code testStr} that
     * (1) are not vowels themselves, and
     * (2) have at least one vowel immediately to their left or right.
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only count consonants; skip vowels entirely
            if (VOWELS.contains(ch)) {
                continue;
            }

            // Check left neighbour
            if (i > 0 && VOWELS.contains(testStr.charAt(i - 1))) {
                count++;
                continue;               // no need to check right neighbour
            }

            // Check right neighbour
            if (i < len - 1 && VOWELS.contains(testStr.charAt(i + 1))) {
                count++;
            }
        }
        return count;
    }

