public static int newmanPrime(int n) {
    // n must be non‑negative; for negative values we throw an exception.
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }

    // The first two values of the sequence are 1, 1.
    if (n == 0 || n == 1) {
        return 1;
    }

    int a0 = 1; // a_{i‑2}
    int a1 = 1; // a_{i‑1}
    int a  = 0; // a_i

    // Compute a_n iteratively using the recurrence.
    for (int i = 2; i <= n; i++) {
        a = 2 * a1 + a0; // a_i = 2*a_{i‑1} + a_{i‑2}
        a0 = a1;
        a1 = a;
    }
    return a;
}

