public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    if (cost == null || cost.isEmpty() || n <= 0) {
        return null; // or throw IllegalArgumentException
    }

    // dp[i][j] = maximum sum to reach cell (i,j) from (0,0)
    long[][] dp = new long[n][n];
    dp[0][0] = cost.get(0).get(0);

    // first row
    for (int j = 1; j < n; ++j) {
        dp[0][j] = dp[0][j-1] + cost.get(0).get(j);
    }
    // first column
    for (int i = 1; i < n; ++i) {
        dp[i][0] = dp[i-1][0] + cost.get(i).get(0);
    }
    // fill remaining cells
    for (int i = 1; i < n; ++i) {
        for (int j = 1; j < n; ++j) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i-1][j], dp[i][j-1]);
        }
    }

    long maxSum = dp[n-1][n-1];
    double average = maxSum / (double) (2 * n - 1);
    // optional rounding to one decimal place
    // average = Math.round(average * 10.0) / 10.0;
    return average;
}

