    public static int countVowels(String testStr) {
        // Guard against null or empty input – there are no consonants to count.
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowel characters (lower‑case).  'y' is treated as a consonant.
        final Set<Character> VOWELS = new HashSet<>(Arrays.asList('a', 'e', 'i', 'o', 'u'));

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // Consider only consonants (i.e. characters that are not vowels)
            if (!VOWELS.contains(Character.toLowerCase(ch))) {
