import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left cell
     * and ends at the bottom‑right cell of the given n×n matrix.
     * Movement is restricted to right or down steps only.
     *
     * @param cost  list of rows, each row is a list of integers
     * @param n     size of the square matrix
     * @return      maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || n <= 0 || cost.isEmpty()) {
            return null;
        }

        // DP array: dp[j] holds the best sum to reach cell (current row, column j)
        long[] dp = new long[n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long val = cost.get(i).get(j);          // value of current cell

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[j] = val;
                } else if (i == 0) {
                    // First row – can only come from the left
                    dp[j] = dp[j - 1] + val;
                } else if (j == 0) {
                    // First column – can only come from above
                    dp[j] = dp[j] + val;
                } else {
                    // General case: take the larger of the cell above (dp[j])
                    // or the cell to the left (dp[j‑1]), then add current value
                    dp[j] = Math.max(dp[j], dp[j - 1]) + val;
                }
            }
        }

        long maxSum = dp[n - 1];                     // best sum to reach (n‑1, n‑1)
        double average = maxSum / (double) (2 * n - 1); // every path has 2·n‑1 cells
        return average;
    }

    // -----------------------------------------------------------------
    // Optional main method for quick manual testing
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

