    long prev2 = 1; // a(n‑2)
    long prev1 = 1; // a(n‑1)
    long cur = 0;   // a(n)

    for (int i = 2; i <= n; i++) {
        cur = 2 * prev1 + prev2; // a(i) = 2*a(i‑1) + a(i‑2)
        prev2 = prev1;
        prev1 = cur;
    }

    // The result fits in an int for the expected range of n
    return (int) cur;
}

