import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum average of all monotonic paths
     * (right‑/down only) from the top‑left to the bottom‑right
     * of an n×n cost matrix.
     *
     * @param cost  list of rows, each row a list of integers
     * @param n     dimension of the square matrix
     * @return      the highest average, or null if the input is invalid
     *
     * Example:
     *   maxaverageofpath([[1,2,3],[6,5,4],[7,3,9]], 3) → 5.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- basic validation -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;                     // no valid path exists
        }

        // ---- DP table: dp[i][j] = max sum to reach cell (i,j) ----------------
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                int val = row.get(j);        // the cost of the current cell
                if (i == 0 && j == 0) {
                    dp[i][j] = val;          // start cell
                } else {
                    double best = Double.NEGATIVE_INFINITY;
                    if (i > 0) best = Math.max(best, dp[i - 1][j]); // from above
                    if (j > 0) best = Math.max(best, dp[i][j - 1]); // from left
                    dp[i][j] = val + best;
                }
            }
        }

        // ---- compute average --------------------------------------------------
        // A monotonic path from (0,0) to (n‑1, n‑1) visits exactly (2n‑1) cells.
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1);   // use long to avoid overflow
        return average;                            // auto‑boxed to Double
    }

    // -------------------------------------------------------------------------
    // Optional‑based wrapper that follows the advice from the description.
    // It returns an empty Optional for invalid input, otherwise wraps the result.
    // -------------------------------------------------------------------------
    public static Optional<Double> maxaverageofpathOptional(List<List<Integer>> cost, int n) {
        Double result = maxaverageofpath(cost, n);
        return Optional.ofNullable(result);
    }

    // -------------------------------------------------------------------------
    // Simple test driver (you can remove it when integrating into a larger code base)
    // -------------------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

