class CountVowels {
    /**
     * Counts consonants in the given string that have at least one vowel
     * as an immediate neighbour (left or right).  The endpoints are considered
     * to have only one neighbour.
     *
     * @param testStr the input string (may be null)
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            if (isVowel(ch)) {
                // We only count consonants, so skip vowels
                continue;
            }

            boolean hasVowelNeighbour = false;

            // Check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbour = true;
            }
            // Check right neighbour (only if we haven't already found a vowel)
            if (!hasVowelNeighbour && i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbour = true;
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }
        return count;
    }

    /** Helper method to determine if a character is a vowel (case‑insensitive). */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));           // 5
    }
}

