/**
 * Returns the n‑th Newman‑Shanks‑Williams number.
 *
 * The sequence is defined by:
 *   a0 = 1, a1 = 1,
 *   an = 2 * a(n‑1) + a(n‑2)   for n >= 2
 *
 * @param n index of the required term (must be non‑negative)
 * @return the n‑th term of the Newman‑Shanks‑Williams sequence
 * @throws IllegalArgumentException if n is negative
 */
public static int newmanPrime(int n) {
    // Guard against illegal input
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }

    // First two terms are both 1
    if (n == 0 || n == 1) {
        return 1;
    }

    // Use long to avoid overflow for moderate n; the result is finally cast to int.
    long a0 = 1L; // a(n‑2)
    long a1 = 1L; // a(n‑1)

    for (int i = 2; i <= n; i++) {
        long a = 2 * a1 + a0; // compute a(i)
        a0 = a1;
        a1 = a;
    }

    // The problem statement expects an int return type.
    return (int) a1;
}

