public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the
     * given n×n matrix. Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    dimension of the square matrix
     * @return the maximum possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation – the problem guarantees a valid input,
        // but we guard against illegal arguments
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] = best sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                double cell = cost.get(i).get(j); // autoboxing to double
                if (i == 0 && j == 0) {
                    dp[i][j] = cell;                 // start cell
                } else {
                    double fromAbove = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double fromLeft  = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = cell + Math.max(fromAbove, fromLeft);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);
        return average;               // auto‑boxed to Double
    }
}

