            // Does either neighbour contain a vowel?
            boolean hasVowelNeighbour = left.filter(vowels::contains).isPresent()
                                      || right.filter(vowels::contains).isPresent();

            if (hasVowelNeighbour) {
                count++;
            }
        }
        return count;
