class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 2) {
            throw new IllegalArgumentException("n must be at least 2");
        }

        // Compute the NSW number at index n
        int a0 = 1; // a(n-2)
        int a1 = 1; // a(n-1)
        int a = 1;  // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        // Check if the computed NSW number is prime
        if (isPrime(a)) {
            return a;
        } else {
            throw new IllegalStateException("The NSW number at index " + n + " is not prime");
        }
    }

    // Helper method to check if a number is prime
    private static boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;

        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

