public class Maxaverageofpath {

    /**
     * Returns the maximum average of any monotone (right‑or‑down) path
     * from the top‑left corner (0,0) to the bottom‑right corner (n‑1,n‑1)
     * of the given n×n cost matrix.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximal average, or null if the input is invalid
     *
     * Example:
     *   maxaverageofpath([[1,2,3],[6,5,4],[7,3,9]], 3) → 5.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;                     // no valid path exists
        }

        // DP[i][j] = maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                double cur = cost.get(i).get(j).doubleValue();

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cur;
                } else {
                    double bestFromTop  = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double bestFromLeft = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = cur + Math.max(bestFromTop, bestFromLeft);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // All monotone paths have exactly (2*n‑1) cells
        double average = maxSum / (2.0 * n - 1.0);

        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

