    /**
     * Returns a list containing the counts of alphabetic characters,
     * digits, and special characters in the given string.
     *
     * @param string the input string (may be null)
     * @return a list [alphabets, digits, special]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Handle null input gracefully
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alpha = 0;    // count of alphabetic characters
        int digit = 0;    // count of digit characters
        int special = 0; // count of everything else (including whitespace)

        for (char ch : string.toCharArray()) {
            if (Character.isLetter(ch)) {
                alpha++;
            } else if (Character.isDigit(ch)) {
                digit++;
            } else {
                special++;
            }
        }

        return Arrays.asList(alpha, digit, special);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&"));// [6, 6, 5]
    }
}

