class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n of the series (must be non‑negative)
     * @return the sum of squares from 1 to number
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Handle non‑positive input – the sum is zero
        if (number <= 0) {
            return 0;
        }

        // Use long to avoid intermediate overflow, then cast to int
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;   // formula: n(n+1)(2n+1)/6
        return (int) sum;
    }

    // Optional simple test driver (uncomment to run)
    // public static void main(String[] args) {
    //     System.out.println(seriesSum(6));   // 91
    //     System.out.println(seriesSum(7));   // 140
    //     System.out.println(seriesSum(12));  // 650
    // }
}

