class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains a 'z'
     * (or 'Z') that is not the first or last character of that word.
     * Otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern to match words (sequences of letters)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // Check each character except the first and last one
            for (int i = 1; i < word.length() - 1; i++) {
                char c = word.charAt(i);
                if (c == 'z' || c == 'Z') {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));     // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

import java.util.List;

class Maxaverageofpath {
    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner of the given n×n matrix and ends at the bottom‑right
     * corner.  Movement is allowed only rightwards or downwards.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    dimension of the square matrix
     * @return the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || cost.get(0).isEmpty()) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // Every path contains exactly (2 * n - 1) cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;               // auto‑boxed to Double
    }
}

