class VolumeTetrahedron {

    /**
     * Calculates the volume of a regular tetrahedron for a given edge length.
     *
     * @param num the length of each edge of the tetrahedron (must be non‑negative)
     * @return the volume of the tetrahedron; returns {@code null} if {@code num}
