/**
 * Utility class for simple word‑matching demonstrations.
 */
public class TextMatchWordzMiddle {

    /**
     * Checks whether the supplied text contains a word that includes the letter {@code 'z'}
     * (case‑insensitive) somewhere other than as the first or last character of the word.
     *
     * <p>Examples:</p>
     * <ul>
     *   <li>{@code textMatchWordzMiddle("pythonzabc.")} → "Found a match!"</li>
     *   <li>{@code textMatchWordzMiddle("xyzabc.")}    → "Found a match!"</li>
     *   <li>{@code textMatchWordzMiddle("  lang  .")}  → "Not matched!"</li>
     * </ul>
     *
     * @param text the input string to be examined; may be {@code null}
     * @return "Found a match!" if a word with an interior {@code 'z'} exists,
     *         otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // A word is a maximal sequence of ASCII letters.
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();            // the actual word
            String lower = word.toLowerCase();        // case‑insensitive check
            int len = lower.length();

            // An interior 'z' is only possible when the word is at least 3 characters long.
            if (len >= 3) {
                // Scan positions 1 … len‑2 (i.e., not the first or last character).
                for (int i = 1; i < len - 1; i++) {
                    if (lower.charAt(i) == 'z') {
                        return "Found a match!";
                    }
                }
            }
        }

        return "Not matched!";
    }

    /** Simple driver to demonstrate the method. */
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
        System.out.println(textMatchWordzMiddle("  lang  ."));
    }
}

