class Maxaverageofpath {
    /**
     * Returns the maximum average of a path from the top‑left corner to the
     * bottom‑right corner of the given {@code n × n} cost matrix when movement
     * is restricted to the directions **right** and **down**.
     *
     * @param cost the {@code n × n} matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}
     *
     * @example
     * <pre>{@code
     * List<List<Integer>> matrix = Arrays.asList(
     *     Arrays.asList(1, 2, 3),
     *     Arrays.asList(6, 5, 4),
     *     Arrays.asList(7, 3, 9)
     * );
     * System.out.println(maxaverageofpath(matrix, 3)); // 5.2
     * }</pre>
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation – adjust as needed for your context
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Cost matrix must be non‑null and have n rows.");
        }

        // dp[i][j] holds the maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The number of cells visited on any valid path is always (2*n - 1)
        int pathLength = 2 * n - 1;
        long maxSum = dp[n - 1][n - 1];

        // Convert to double and return as a Double (auto‑boxing)
        return (double) maxSum / pathLength;
    }
}

import java.io.*;
