class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * <p>A vowel neighbor is a vowel (a, e, i, o, u) that appears immediately to the left or right of a character.
     * Only consonants (i.e., characters that are not vowels) are counted. The first and last characters have
     * only one neighbor.</p>
     *
     * @param testStr the input string
     * @return the number of consonants that have at least one vowel neighbor
     * @throws IllegalArgumentException if testStr is null
     *
     * <p>Example usage:</p>
     * <pre>
     * int n = CountVowels.countVowels("bestinstareels");      // returns 7
     * int n = CountVowels.countVowels("partofthejourneyistheend"); // returns 12
     * int n = CountVowels.countVowels("amazonprime");        // returns 5
     * </pre>
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            throw new IllegalArgumentException("Input string must not be null");
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // We only count consonants that have a vowel neighbor
            if (!isVowel(ch)) {
                boolean hasVowelNeighbor = false;

                // Check left neighbor
                if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // Check right neighbor
                if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Determines whether a given character is a vowel (a, e, i, o, u) in a case‑insensitive manner.
     *
     * @param ch the character to check
     * @return true if ch is a vowel, false otherwise
     */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u';
    }

    // Optional main method for quick testing
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));          // 5
    }
}

