class NewmanPrime {
    /**
     * Returns the nth term of the Newman-Shanks-Williams sequence.
     *
     * <p>The sequence is defined by a(0) = 1, a(1) = 1, and
     * a(n) = 2 * a(n-1) + a(n-2) for n >= 2.
     * This sequence yields prime numbers at certain indices (e.g., a(2)=3,
     * a(3)=7, a(4)=17, a(5)=41, ...).</p>
     *
     * @param n the index of the term to return (must be non-negative)
     * @return the nth term of the Newman-Shanks-Williams sequence
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }

        // Handle base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute the sequence iteratively
        long a0 = 1; // a(n-2)
        long a1 = 1; // a(n-1)
        long a = 0; // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        return (int) a;
    }
}

