public class TextMatchWordzMiddle {

    /**
     * Determines whether any word in the given text contains the letter 'z'
     * somewhere other than the first or last character.
     *
     * <p>The function scans each word (a maximal sequence of ASCII letters)
     * in the input string. If a word contains the character {@code 'z'} and
     * the {@code 'z'} is not the first or last character of that word, the
     * method returns {@code "Found a match!"}. If no such word is found, it
     * returns {@code "Not matched!"}.
     *
     * @param text the input string to be examined; may contain punctuation,
     *             whitespace, and other non‑letter characters
     * @return {@code "Found a match!"} if a word with a non‑initial,
     *         non‑final {@code 'z'} exists; otherwise {@code "Not matched!"}
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches whole words made of ASCII letters only
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // Look for the first occurrence of 'z' (case‑sensitive)
            int zIndex = word.indexOf('z');

            // Accept only if 'z' is present and is NOT at the first or last position
            if (zIndex != -1 && zIndex != 0 && zIndex != word.length() - 1) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

