class Maxaverageofpath {
    /**
     * Returns the maximum average value among all paths from the top‑left
     * corner to the bottom‑right corner of the given square matrix.
     *
     * <p>Paths may only move right or down. The length of any path is
     * {@code 2*n - 1} (including both endpoints), so maximizing the
     * average is equivalent to maximizing the sum.</p>
     *
     * @param cost a square matrix represented as a list of rows,
     *             each row being a list of integers; must be non‑null
     *             and have {@code n} rows of length {@code n}
     * @param n    the size of the square matrix (number of rows and columns)
     * @return the maximum average value of a valid path, expressed as a
     *         {@code Double}
     * @throws NullPointerException     if {@code cost} is {@code null}
     * @throws IndexOutOfBoundsException if the dimensions of {@code cost}
     *                                   do not match {@code n}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null) {
            throw new NullPointerException("cost must not be null");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Use long to avoid overflow for large sums
        long[][] dp = new long[n][n];

        // Initialize the starting cell
        dp[0][0] = cost.get(0).get(0).longValue();

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j).longValue();
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0).longValue();
        }

        // Fill the rest of the DP table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j).longValue();
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);
        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

