class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     *
     * <p>The Newman‑Shanks‑Williams sequence is defined by:
     * a(0) = 1, a(1) = 1, and a(i) = 2·a(i‑1) + a(i‑2) for i {@literal >=} 2.
     * This method returns a(n) assuming n is an index for which a(n) is prime.
     *
     * <p>Example:
     * <pre>{@code
     * newmanPrime(3) // returns 7
     * }</pre>
     *
     * @param n the index of the Newman‑Shanks‑Williams prime (must be {@literal >=} 2)
     * @return the n‑th Newman‑Shanks‑Williams prime
     * @throws IllegalArgumentException if n is less than 2
     * @implSpec
     * This implementation computes the sequence iteratively using the recurrence
     * {@code a(i) = 2 * a(i-1) + a(i-2)} and returns a(n).
     */
    public static int newmanPrime(int n) {
        if (n < 2) {
            throw new IllegalArgumentException("n must be >= 2");
        }
        int a0 = 1; // a(i-2)
        int a1 = 1; // a(i-1)
        int a  = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return a;
    }
}

