     * Returns the volume of a regular tetrahedron with the given side length.
     *
     * @param num the length of each edge of the tetrahedron
     * @return the volume, rounded to two decimal places
     * @implSpec
     * This implementation computes {@code (num^3) / (6 * sqrt(2))} and rounds
     * the result to two decimal places.
     */
    public static Double volumeTetrahedron(int num) {
        // Volume of a regular tetrahedron: V = a^3 / (6 * sqrt(2))
        double volume = (num * num * num) / (6.0 * Math.sqrt(2.0));
        // Round to two decimal places to match the expected output
        return Math.round(volume * 100.0) / 100.0;
    }

    // Optional main method for manual testing
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Utility class for simple word‑matching demonstrations.
 */
public class TextMatchWordzMiddle {

    /**
     * <p>Checks whether the supplied text contains a word that includes the
     * letter <em>z</em> somewhere other than the first or last character of
     * that word.</p>
     *
     * <p>Examples:</p>
     * <ul>
     *   <li>{@code "pythonzabc."} → {@code "Found a match!"}</li>
     *   <li>{@code "xyzabc."}     → {@code "Found a match!"}</li>
     *   <li>{@code "  lang  ."}   → {@code "Not matched!"}</li>
     * </ul>
     *
     * @implSpec
     * This implementation extracts each maximal sequence of letters from the
     * input using the regular expression {@code [a-zA-Z]+}.  For every such
     * word it inspects the characters at positions {@code 1} through
     * {@code word.length()‑2} (i.e. the interior of the word).  If any of those
     * characters is {@code 'z'} (case‑insensitive), the method immediately
     * returns {@code "Found a match!"}.  If no word yields a match, the method
     * returns {@code "Not matched!"}.
     *
     * @param text the string to be examined
     * @return {@code "Found a match!"} if a word with an interior {@code 'z'}
     *         is found; {@code "Not matched!"} otherwise
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches a contiguous run of ASCII letters (a‑z or A‑Z)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            if (containsZMiddle(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * Determines whether the given word contains the letter {@code 'z'} in a
     * position that is neither the first nor the last character.
     *
     * @param word a non‑null word consisting only of letters
     * @return {@code true} if the word has an interior {@code 'z'},
     *         {@code false} otherwise
     */
    private static boolean containsZMiddle(String word) {
        // Convert to lower‑case for case‑insensitive comparison
        String lower = word.toLowerCase();

        // A word shorter than three characters cannot have an interior letter
        if (lower.length() < 3) {
            return false;
        }

        // Examine characters from index 1 up to length‑2 (inclusive)
        for (int i = 1; i < lower.length() - 1; i++) {
            if (lower.charAt(i) == 'z') {
                return true;
            }
        }
        return false;
    }

    // -----------------------------------------------------------------------
    // Optional test driver
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
        System.out.println(textMatchWordzMiddle("  lang  ."));
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given
     * n × n matrix.  The path may only move right or down.
     *
     * @param cost the n × n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average value, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Initialise the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The path length (number of visited cells) is always 2*n - 1
        int pathLength = 2 * n - 1;
        double maxAverage = (double) dp[n - 1][n - 1] / pathLength;

        // Auto‑boxing to Double
        return maxAverage;
    }

    // Example usage (not required for the solution, but handy for testing)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = List.of(
            List.of(1, 2, 3),
            List.of(6, 5, 4),
            List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = List.of(
            List.of(2, 3, 4),
            List.of(7, 6, 5),
            List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = List.of(
            List.of(3, 4, 5),
            List.of(8, 7, 6),
            List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

