class CountVowels {
    /**
     * Counts the characters in the given string that have a vowel as one of their
     * immediate neighbours. Only consonants are considered; a consonant is counted
     * if either its left or right neighbour (or both) is a vowel.
     *
     * @param testStr the input string
     * @return the number of consonants that are adjacent to a vowel
     *
     * Examples:
     * <ul>
     *   <li>countVowels("bestinstareels") → 7</li>
     *   <li>countVowels("partofthejourneyistheend") → 12</li>
     *   <li>countVowels("amazonprime") → 5</li>
     * </ul>
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowels (both lower‑ and upper‑case)
        Set<Character> vowelSet = new HashSet<>(Arrays.asList(
                'a', 'e', 'i', 'o', 'u',
                'A', 'E', 'I', 'O', 'U'
        ));

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only care about consonants (i.e. characters that are not vowels)
            if (!vowelSet.contains(ch)) {
                boolean hasVowelNeighbor = false;

                // Check left neighbour
                if (i > 0 && vowelSet.contains(testStr.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // Check right neighbour
                if (i < len - 1 && vowelSet.contains(testStr.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));         // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

