class SeriesSum {
    /**
     * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     *
     * @param number the upper limit n of the series
     * @return the sum of squares from 1² to number²
     */
    public static int seriesSum(int number) {
        // Use the formula: n(n+1)(2n+1)/6
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;
        return (int) sum;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

