class NewmanPrime {
    /**
     * Returns the nth Newman‑Shanks‑Williams prime.
     *
     * <p>The Newman‑Shanks‑Williams numbers are defined by the recurrence
     * S₀ = 1, S₁ = 1, and Sₙ = 2·Sₙ₋₁ + Sₙ₋₂ for n ≥ 2.
     * The value returned is prime for n ≥ 2 (i.e., the result is a prime
     * number when n is 2 or greater).
     *
     * @param n the index of the Newman‑Shanks‑Williams number to return
     *          (starting from 0, so {@code n = 3} yields 7, {@code n = 4}
     *          yields 17, etc.)
     * @return the nth Newman‑Shanks‑Williams number, which is prime for
     *         n ≥ 2
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Handle the base cases S_0 and S_1
        if (n == 0) return 1;
        if (n == 1) return 1;

        // Compute S_n using the recurrence S_n = 2*S_{n-1} + S_{n-2}
        long a0 = 1; // S_0
        long a1 = 1; // S_1
        long a = 0;  // S_n

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return (int) a1; // Cast to int, as the values fit within int for reasonable n
    }
}

