/**
 * <p>Utility class that provides a method to detect a word containing the
 * letter {@code 'z'} that is <strong>not</strong> at the start or the end of
 * the word.</p>
 *
 * <p>This class is used in the “Middle of the Z” coding challenge.</p>
 */
public class TextMatchWordzMiddle {

    /** Utility class – not intended to be instantiated. */
    private TextMatchWordzMiddle() {
        // empty
    }

    /**
     * Determines whether the given text contains a word that includes the
     * letter {@code 'z'} somewhere other than as the first or last character.
     *
     * <p>The search is case‑insensitive, so both {@code 'z'} and {@code 'Z'}
     * are considered.</p>
     *
     * @param text the input text to be examined
     * @return {@code "Found a match!"} if such a word exists;
     *         {@code "Not matched!"} otherwise
     *
     * @example {@code textMatchWordzMiddle("pythonzabc.")} returns {@code "Found a match!"}
     * @example {@code textMatchWordzMiddle("xyzabc.")}   returns {@code "Found a match!"}
     * @example {@code textMatchWordzMiddle("  lang  .")} returns {@code "Not matched!"}
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches a whole word consisting of ASCII letters.
        // \b denotes a word boundary (between a word character and a non‑word character).
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            String lower = word.toLowerCase(); // case‑insensitive check

            // A match occurs if the word contains at least one 'z' and the
            // 'z' is neither the first nor the last character.
            if (lower.contains("z") && !lower.startsWith("z") && !lower.endsWith("z")) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // ------------------------------------------------------------------
    // Optional main method for quick manual testing
    // ------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
        System.out.println(textMatchWordzMiddle("  lang  ."));
    }
}

import java.util.Arrays;
import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all paths from the top‑left
     * corner to the bottom‑right corner of the given n × n cost matrix.
     * Movement is restricted to steps to the right or down.
     *
     * <p>All valid paths have exactly {@code 2*n‑1} cells (including the
     * start and end cells), therefore maximizing the average is equivalent
     * to maximizing the total sum of a path.
     *
     * @param cost a list of {@code n} rows, each row being a list of
     *             {@code n} integers that represent the cost of the cell.
     * @param n    the dimension of the square matrix (number of rows/columns).
     * @return a {@code Double} representing the maximum average of any
     *         valid path; returns {@code null} if the input is invalid.
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- Input validation -------------------------------------------------
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }
        for (List<Integer> row : cost) {
            if (row == null || row.size() != n) {
                return null;
            }
        }

        // ---- DP: dp[i][j] = maximum sum to reach cell (i, j) -----------------
        double[][] dp = new double[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], Double.NEGATIVE_INFINITY);
        }

        dp[0][0] = cost.get(0).get(0).doubleValue();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    continue; // start cell already initialised
                }

                double best = Double.NEGATIVE_INFINITY;
                if (i > 0) {
                    best = Math.max(best, dp[i - 1][j]); // from above
                }
                if (j > 0) {
                    best = Math.max(best, dp[i][j - 1]); // from left
                }

                // If both neighbours are unreachable, this cell is unreachable
                if (best == Double.NEGATIVE_INFINITY) {
                    continue;
                }

                dp[i][j] = cost.get(i).get(j).doubleValue() + best;
            }
        }

        // ---- Compute average --------------------------------------------------
        double maxSum = dp[n - 1][n - 1];
        // Every path contains exactly (2*n - 1) cells
        double average = maxSum / (2 * n - 1);

        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------------
    // Simple test driver (feel free to remove / comment out in production)
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(
                        Arrays.asList(1, 2, 3),
                        Arrays.asList(6, 5, 4),
                        Arrays.asList(7, 3, 9)),
                3)); // 5.2

        System.out.println(maxaverageofpath(
                Arrays.asList(
                        Arrays.asList(2, 3, 4),
                        Arrays.asList(7, 6, 5),
                        Arrays.asList(8, 4, 10)),
                3)); // 6.2

        System.out.println(maxaverageofpath(
                Arrays.asList(
                        Arrays.asList(3, 4, 5),
                        Arrays.asList(8, 7, 6),
                        Arrays.asList(9, 5, 11)),
                3)); // 7.2
    }
}

