/**
 * A utility class for simple string‑analysis exercises.
 */
class CountVowels {

    /**
     * Counts the consonants in the string that have a vowel neighbour.
     *
     * <p>A consonant is counted if it is adjacent to at least one vowel
     * (either immediately before or after it).  Vowel characters themselves
     * are never counted, even if they are next to another vowel.</p>
     *
     * <p>Examples:</p>
     * <pre>
     * countVowels("bestinstareels")      → 7
     * countVowels("partofthejourneyistheend") → 12
     * countVowels("amazonprime")         → 5
     * </pre>
     *
     * @param testStr the input string (may contain only letters)
     * @return the number of consonants that have a vowel neighbour
     */
    public static int countVowels(String testStr) {
        // Defensive: treat null or empty string as zero
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        final String vowels = "aeiouAEIOU";

        for (int i = 0; i < testStr.length(); i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – they are never counted
            if (vowels.indexOf(ch) != -1) {
                continue;
            }

            // Check the left neighbour
            boolean hasVowelNeighbor = false;
            if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
                hasVowelNeighbor = true;
            }

            // Check the right neighbour if we haven't found a vowel yet
            if (!hasVowelNeighbor && i + 1 < testStr.length()
                    && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // --------------------------------------------------------------------
    // Optional main method for quick manual testing
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        String[] tests = {
            "bestinstareels",
            "partofthejourneyistheend",
            "amazonprime"
        };
        int[] expected = { 7, 12, 5 };

        for (int i = 0; i < tests.length; i++) {
            int result = countVowels(tests[i]);
            System.out.printf("countVowels(\"%s\") = %d (expected %d)%n",
                    tests[i], result, expected[i]);
        }
    }
}

