     *
     * @param number the count of terms to sum (must be non‑negative)
     * @return the sum 1² + 2² + … + {@code number}²
     */
    public static int seriesSum(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("Number must be non‑negative");
        }
        // Use the closed‑form formula n*(n+1)*(2n+1)/6 to avoid a loop.
        long n = number;
        return (int) (n * (n + 1) * (2 * n + 1) / 6);
    }
}

