import java.util.*;

public class Maxaverageofpath {
    /**
     * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table to store the maximum sum to reach each cell
        double[][] dp = new double[n][n];

        // Initialize start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j-1] + cost.get(0).get(j);
        }

        // Fill first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i-1][0] + cost.get(i).get(0);
        }

        // Fill rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i-1][j], dp[i][j-1]);
            }
        }

        // Maximum sum from top‑left to bottom‑right
        double maxSum = dp[n-1][n-1];

        // Number of cells in any such path = 2*n - 1
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // Simple test (optional)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

