/**
 * Provides a utility method for generating the Newman‑Shanks‑Williams (NSW) sequence.
 * <p>
 * The NSW sequence is defined by:
 * <ul>
 *   <li>{@code a(0) = 1}</li>
 *   <li>{@code a(1) = 1}</li>
 *   <li>{@code a(k) = 2 * a(k‑1) + a(k‑2)} for {@code k ≥ 2}</li>
 * </ul>
 * The numbers produced by this recurrence are sometimes called
 * {@code Newman‑Shaks‑Williams numbers}, and the primes that appear
 * in the sequence are known as {@code Newman‑Shaks‑Williams primes}.
 * </p>
 *
 * @author  (your name)
 * @version 1.0
 */
class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * <p>
     * The sequence is zero‑based: the term at index {@code 0} is {@code 1},
     * the term at index {@code 1} is also {@code 1}, and each subsequent term
     * is computed as {@code 2 * previous + previous‑previous}.
     * </p>
     *
     * <p>Example usage:</p>
     * <pre>
     * NewmanPrime.newmanPrime(3) // returns 7
     * NewmanPrime.newmanPrime(4) // returns 17
     * NewmanPrime.newmanPrime(5) // returns 41
     * </pre>
     *
     * @param n the zero‑based index of the desired term (must be non‑negative)
     * @return the value of the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if {@code n} is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the first two base cases directly.
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute the sequence iteratively using long to avoid overflow
        // of the intermediate results; the final result is cast back to int.
        long prev2 = 1L; // a(0)
        long prev1 = 1L; // a(1)
        long current = 0L;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            // Shift the window forward.
            prev2 = prev1;
            prev1 = current;
        }

        return (int) current;
    }
}

