/**
 * Utility class that provides a method for computing the maximum average of a
 * path in a square matrix.
 *
 * <p>A <i>path</i> starts at the top‑left cell {@code (0,0)} and ends at the
 * bottom‑right cell {@code (n‑1,n‑1)}.  At each step the path may move only
 * <b>right</b> ({@code (i, j) → (i, j+1)}) or <b>down</b>
 * ({@code (i, j) → (i+1, j)}).  Because exactly {@code n‑1} moves right and
 * {@code n‑1} moves down are required, every valid path visits exactly
 * {@code 2·n‑1} cells.  The average of a path is therefore the sum of the
 * visited cell values divided by {@code 2·n‑1}.  Maximising the average is
 * equivalent to maximising the sum, which can be done with a simple dynamic‑
 * programming table.</p>
 *
 * @author  (your name)
 * @version 1.0
 */
public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path from the top‑left corner
     * to the bottom‑right corner of the given {@code n×n} matrix.
     *
     * <p>The implementation first computes the maximum sum of any
     * right‑/down‑only path using dynamic programming, then divides that sum by
     * the number of visited cells ({@code 2·n‑1}) to obtain the average.</p>
     *
     * <p>If the input is invalid ({@code cost} is {@code null}, {@code n <= 0},
     * or the dimensions do not match), the method returns {@code null}.</p>
     *
     * @param cost a non‑null square matrix represented as a list of rows,
     *             each row being a list of {@code Integer} values
     * @param n    the dimension of the square matrix (must be equal to
     *             {@code cost.size()} and each row's size)
     * @return a {@code Double} containing the maximum average, or {@code null}
     *         if the input is invalid
     * @throws IllegalArgumentException if any row in {@code cost} is {@code null}
     *                                  or has a length different from {@code n}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- Input validation ------------------------------------------------
        if (cost == null || n <= 0) {
            return null;
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException("Matrix dimension does not match n");
        }

        // ---- Dynamic programming for maximum path sum -----------------------
        // dp[i][j] holds the maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // First cell
        dp[0][0] = cost.get(0).get(0).longValue();

        // First column (can only come from above)
        for (int i = 1; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Invalid row length at index " + i);
            }
            dp[i][0] = dp[i - 1][0] + row.get(0).longValue();
        }

        // First row (can only come from the left)
        for (int j = 1; j < n; j++) {
            List<Integer> row = cost.get(0);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Invalid row length at index 0");
            }
            dp[0][j] = dp[0][j - 1] + row.get(j).longValue();
        }

        // Remaining cells: max of top or left neighbor plus current cell value
        for (int i = 1; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Invalid row length at index " + i);
            }
            for (int j = 1; j < n; j++) {
                dp[i][j] = row.get(j).longValue() + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- Compute average --------------------------------------------------
        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2L * n - 1);

        return Double.valueOf(average);
    }
}

