/**
 * Utility class for counting characters that have vowels as neighbours.
 *
 * @author  (your name)
 * @version 1.0
 */
class CountVowels {

    /**
     * Counts the characters in {@code testStr} that are consonants and have
     * at least one vowel as an immediate neighbour (either to the left or to
     * the right).
     *
     * <p>Examples:
     * <ul>
     *   <li>{@code countVowels("bestinstareels")} → {@code 7}</li>
     *   <li>{@code countVowels("partofthejourneyistheend")} → {@code 12}</li>
     *   <li>{@code countVowels("amazonprime")} → {@code 5}</li>
     * </ul>
     *
     * @param testStr the input string (must not be {@code null})
     * @return the number of consonants that are adjacent to a vowel
     * @throws IllegalArgumentException if {@code testStr} is {@code null}
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            throw new IllegalArgumentException("Input string must not be null");
        }

        char[] ch = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < ch.length; i++) {
            char c = ch[i];
            // Consider only consonants (i.e., characters that are not vowels)
            if (!isVowel(c)) {
                boolean hasVowelNeighbor = (i > 0 && isVowel(ch[i - 1]))   // left neighbour
                                         || (i < ch.length - 1 && isVowel(ch[i + 1])); // right neighbour
                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Determines whether a given character is a vowel (a, e, i, o, u) irrespective
     * of case.
     *
     * @param c the character to test
     * @return {@code true} if {@code c} is a vowel, {@code false} otherwise
     */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
}

