class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * <p>
     * The sequence is defined by {@code a0 = 1, a1 = 1} and
     * {@code a_i = 2 * a_{i‑1} + a_{i‑2}} for {@code i ≥ 2}.
     * <p>
     * Examples:
     * <ul>
     *   <li>{@code newmanPrime(3) → 7}</li>
     *   <li>{@code newmanPrime(4) → 17}</li>
     *   <li>{@code newmanPrime(5) → 41}</li>
     * </ul>
     *
     * @param n the index of the term to compute (0‑based)
     * @return the n‑th term of the Newman–Shanks–Williams sequence
     * @throws IllegalArgumentException if {@code n} is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Base cases: a0 = 1, a1 = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long prev2 = 1; // a_{i‑2}
        long prev1 = 1; // a_{i‑1}
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            // shift the window for the next iteration
            prev2 = prev1;
            prev1 = current;
        }

        // The sequence grows quickly; cast to int is safe for the expected range.
        return (int) current;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

