class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron given the length of its edges.
     *
     * @param num the length of each edge of the regular tetrahedron
     * @return the volume of the tetrahedron, rounded to two decimal places
     */
    public static Double volumeTetrahedron(int num) {
        // Edge length
        double a = num;
        // Volume of a regular tetrahedron: V = a^3 / (6 * sqrt(2))
        double volume = Math.pow(a, 3) / (6.0 * Math.sqrt(2.0));
