/**
 * A utility class for computing the sum of squares of the first n positive integers.
 *
 * <p>The series is defined as 1² + 2² + 3² + … + n².
 *
 * <p>Example:
 * <ul>
 *   <li>seriesSum(6) returns 91 (1+4+9+16+25+36)</li>
 *   <li>seriesSum(7) returns 140</li>
 *   <li>seriesSum(12) returns 650</li>
 * </ul>
 *
 * @author  (your name)
 * @version 1.0
 */
class SeriesSum {

    /**
     * Calculates the sum of squares of the first {@code number} positive integers.
     *
     * <p>If {@code number} is less than or equal to zero, the method returns 0,
     * as there are no terms to sum.
     *
     * @param number the count of terms to include in the series (must be non‑negative)
     * @return the sum of the series 1²+2²+…+n² as an {@code int}
     */
    public static int seriesSum(int number) {
        // Guard against non‑positive input
        if (number <= 0) {
            return 0;
        }

        // Use a long accumulator to avoid intermediate overflow, then cast to int.
        long sum = 0L;
        for (int i = 1; i <= number; i++) {
            sum += (long) i * i;   // i² fits in a long even if not in an int for large i
        }

        // The problem statement expects an int return type; the result should fit in int
        return (int) sum;
    }
}

