class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * For n >= 2 this value is a prime.
     *
     * <pre>
     * newmanPrime(3) → 7
     * newmanPrime(4) → 17
     * newmanPrime(5) → 41
     * </pre>
     *
     * @param n index of the desired NSW number (0‑based)
     * @return the n‑th NSW number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // a0 = 1, a1 = 1
        long prev = 1; // a(n‑2)
        long cur  = 1; // a(n‑1)

        if (n == 0) return (int) prev;
        if (n == 1) return (int) cur;

        long next = 0;
        for (int i = 2; i <= n; i++) {
            next = 4 * cur - prev; // recurrence: a(i) = 4*a(i‑1) – a(i‑2)
            prev = cur;
            cur  = next;
        }
        return (int) cur;
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        for (int i = 3; i <= 5; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

