import java.math.*;

class Maxaverageofpath {
    /**
     * Returns the maximum average of any monotonic path (right‑down only)
     * from the top‑left corner to the bottom‑right corner of an n×n cost matrix.
     *
     * @param cost  list of n rows, each row a list of n integers
     * @param n     size of the square matrix
     * @return      the maximum average as a Double, or null for illegal input
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input – keeps the method robust.
        if (cost == null || n <= 0) {
            return null;
        }

        // Two 1‑D arrays hold the DP values for the previous row and the current row.
        // Their scope is limited to this method, satisfying the “minimize scope” rule.
        long[] prev = new long[n];
        long[] curr = new long[n];

        // Initialise the first cell (0,0).
        prev[0] = cost.get(0).get(0);

        // Fill the first row – we can only arrive from the left.
        for (int j = 1; j < n; j++) {
            prev[j] = prev[j - 1] + cost.get(0).get(j);
        }

        // Process each subsequent row.
        for (int i = 1; i < n; i++) {
            // First column of the current row – we can only come from above.
            curr[0] = prev[0] + cost.get(i).get(0);

            // For the rest of the columns we pick the larger of the two possible predecessors.
            for (int j = 1; j < n; j++) {
                long best = Math.max(prev[j], curr[j - 1]);
                curr[j] = best + cost.get(i).get(j);
            }

            // Swap the two rows so that ‘prev’ always contains the latest DP values.
            long[] tmp = prev;
            prev = curr;
            curr = tmp;
        }

        // The maximum sum is located at the bottom‑right corner.
        long maxSum = prev[n - 1];

        // A monotonic path always contains (2*n‑1) cells, therefore the average is:
        double average = maxSum / (2.0 * n - 1.0);

        return average;
    }

    // --------------------------------------------------------------------
    // Optional test driver (feel free to remove or comment out in production)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

