class NewmanPrime {
    /**
     * Write a function to find the nth Newman–Shanks–Williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Guard against negative indices
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases: a(0) = a(1) = 1
        if (n == 0 || n == 1) {
            return 1;   // not prime, but returned for completeness
        }

        // Compute the sequence iteratively
        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a  = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }

        // The problem guarantees that the requested term is prime,
        // so we simply return the computed value.
        return (int) a;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

