public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the letter 'z'
     * (case‑insensitive) **somewhere other than the first or last character** of that word.
     * Otherwise it returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // -----------------------------------------------------------------
        // 1. Extract all “words” – sequences of ASCII letters.
        // -----------------------------------------------------------------
        List<String> words = new ArrayList<>();
        Matcher m = Pattern.compile("[a-zA-Z]+").matcher(text);
        while (m.find()) {
            words.add(m.group());               // each match is a word
        }

        // -----------------------------------------------------------------
        // 2. Use a for‑each loop (as recommended) to inspect each word.
        // -----------------------------------------------------------------
        for (String word : words) {
            // Convert to lower‑case so the check is case‑insensitive.
            String w = word.toLowerCase();

            // The pattern [a-z]z[a-z] guarantees that there is a letter
            // both before and after the 'z', i.e. the 'z' is not at the
            // start or the end of the word.
            if (w.matches(".*[a-z]z[a-z].*")) {
                return "Found a match!";
            }
        }

        // No word satisfied the condition.
        return "Not matched!";
    }
}

import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a path that starts at the
     * upper‑left cell of the square matrix `cost` (size n×n) and ends at the
     * bottom‑right cell, moving only right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a {@code Double}, or {@code null} if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else {
                    long best = Long.MIN_VALUE;
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]); // from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]); // from left
                    }
                    dp[i][j] = best + val;
                }
            }
        }

        // The best sum reaches the bottom‑right corner
        long maxSum = dp[n - 1][n - 1];

        // Every path has exactly (2 * n - 1) cells
        double denominator = 2.0 * n - 1.0;
        double average = maxSum / denominator;

        return Double.valueOf(average);
    }
}

