public class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a monotonic path
     * (only moves right or down) from the top‑left to the bottom‑right
     * of the given n×n cost matrix.
     *
     * @param cost  list of rows, each row a list of integers
     * @param n     size of the square matrix
     * @return      the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Start cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Total number of cells visited on any such path is 2*n - 1
        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2L * n - 1);

        return Double.valueOf(average);
    }
}

