public class NewmanPrime {
    /**
     * Returns the nth Newman-Shanks-Williams prime.
     * For n >= 2, returns the (n-2)th prime in the NSW sequence (0-indexed).
     * For example:
     * newmanPrime(3) -> 7
     * newmanPrime(4) -> 17
     * newmanPrime(5) -> 41
     */
    public static int newmanPrime(int n) {
        if (n < 2) {
            throw new IllegalArgumentException("n must be at least 2");
        }

        List<Integer> primes = new ArrayList<>();
        long a = 1; // S0
        long b = 1; // S1

        // Generate NSW numbers starting from index 2
        // Continue until we have collected at least (n-1) primes
        for (int i = 2; primes.size() < n - 1; i++) {
            long c = 2 * b + a;
            if (isPrime(c)) {
                primes.add((int) c);
            }
            a = b;
            b = c;
        }

        // Use a for-each loop to retrieve the (n-2)th prime (0-indexed)
        int targetIndex = n - 2;
        int result = 0;
        int index = 0;
        for (int p : primes) {
            if (index == targetIndex) {
                result = p;
                break;
            }
            index++;
        }
        return result;
    }

    /**
     * Helper method to check if a number is prime.
     */
    private static boolean isPrime(long num) {
        if (num <= 1) return false;
        if (num <= 3) return true;
        if (num % 2 == 0) return false;
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

