import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a monotone path
     * (right / down only) from the top‑left to the bottom‑right corner
     * of the given n×n cost matrix.
     *
     * @param cost  list of rows, each row a list of integer cell costs
     * @param n     size of the square matrix
     * @return      the maximum average (as a Double)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;                     // defensive programming
        }

        // dp[i][j] – maximal sum reaching cell (i,j)
        long[][] dp = new long[n][n];

        // ----- initialise the first cell -----
        dp[0][0] = cost.get(0).get(0);

        // ----- first row (can only come from the left) -----
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // ----- first column (can only come from above) -----
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // ----- fill the rest of the table -----
        for (int i = 1; i < n; i++) {
            // using an enhanced for‑loop to iterate over the columns of the current row
            List<Integer> row = cost.get(i);
            for (int j = 1; j < n; j++) {
                long bestFromAboveOrLeft = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = row.get(j) + bestFromAboveOrLeft;
            }
        }

        // ----- compute the average -----
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);

        return Double.valueOf(average);
    }
}

