class CountVowels {

    /**
     * Counts characters (excluding vowels) that have at least one vowel
     * as an immediate neighbour (either to the left or to the right).
     *
     * @param testStr the input string
     * @return the number of such characters
     *
     * Example:
     * countVowels("bestinstareels")  -> 7
     * countVowels("partofthejourneyistheend") -> 12
     * countVowels("amazonprime") -> 5
     */
    public static int countVowels(String testStr) {
        // Defensive: null or too short -> no neighbours
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        // Iterate over the string using an index – needed to inspect neighbours.
        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Vowels themselves are not counted (the problem asks for characters
            // that have vowel neighbours, not for vowels).
            if (isVowel(ch)) {
                continue;
            }

            // Check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                count++;
                continue;               // already satisfied, avoid double‑count
            }

            // Check right neighbour
            if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                count++;
            }
        }

        return count;
    }

    /** Helper: case‑insensitive vowel test. */
    private static boolean isVowel(char c) {
        return "aeiouAEIOU".indexOf(c) != -1;
    }

