class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms (n). Must be non‑negative.
     * @return the sum of the squares of the first n natural numbers.
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Guard against non‑positive input
        if (number <= 0) {
            return 0;
        }

        // 1. Create an array containing the numbers 1 … number.
        //    (We still need a traditional loop to fill the array,
        //     but the iteration over the array will be done with for‑each.)
        int[] values = new int[number];
        for (int i = 0; i < number; i++) {
            values[i] = i + 1;          // 1‑based index
        }

        // 2. Use the preferred for‑each loop to iterate over the array
        //    and accumulate the sum of squares.
        int sum = 0;
        for (int v : values) {
            sum += v * v;
        }

        // The result fits in an int for typical problem constraints;
        // if you need larger ranges, change the return type to long.
        return sum;
    }

    // -----------------------------------------------------------------
    // Optional simple test harness (not required by the problem statement)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
