class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * For n >= 2 this number is a prime (the “prime” in the problem description).
     *
     * @param n index of the desired term (0‑based)
     * @return the n‑th NSW number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // a(0) = 1, a(1) = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a  = 0; // a(i)

        // Compute a(2) … a(n)
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence: a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }

        // The result fits in an int for the typical test values.
        return (int) a;
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

