class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a path that goes from the
     * top‑left corner to the bottom‑right corner of the square matrix.
     * Movement is restricted to right and down steps.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximum average value as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive: if the list is empty, there is no path
        if (cost == null || cost.isEmpty() || cost.get(0).isEmpty()) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) +
                           Math.max(dp[i - 1][j],   // from above
                                    dp[i][j - 1]); // from left
            }
        }

        // the best sum ends at the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // every path from (0,0) to (n‑1,n‑1) contains exactly (2*n‑1) cells
        double average = maxSum / (2 * n - 1);

        return average;
    }

