import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * upper‑left cell and ends at the lower‑right cell of the given
     * n×n matrix. Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of non‑negative integers
     * @param n    size of the matrix (cost.size() == n)
     * @return the maximal average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = maximal sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int val = cost.get(i).get(j);
                long best = val;                     // start with the cell itself
                if (i > 0) best = Math.max(best, dp[i - 1][j] + val); // from top
                if (j > 0) best = Math.max(best, dp[i][j - 1] + val); // from left
                dp[i][j] = best;
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2L * n - 1);
        return average;
    }

    // --------------------------------------------------------------------
    // Simple manual test (can be removed when integrating into a larger project)
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

