class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams (NSW) number.
     *
     * The NSW sequence is defined by:
     *   a(0) = 1,  a(1) = 1
     *   a(n) = 2·a(n‑1) + a(n‑2)  for n ≥ 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases: a(0) = a(1) = 1
        if (n <= 1) {
            return 1;
        }

        // Use BigInteger to avoid overflow for larger n.
        BigInteger a0 = BigInteger.ONE; // a(i‑2)
        BigInteger a1 = BigInteger.ONE; // a(i‑1)
        BigInteger a  = BigInteger.ZERO; // a(i)

        for (int i = 2; i <= n; i++) {
            // a(i) = 2 * a(i‑1) + a(i‑2)
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            // shift the window
            a0 = a1;
            a1 = a;
        }

        // The problem expects an int; the result fits for the usual range.
        return a.intValue();
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

