            if (vowelSet.contains(Character.toLowerCase(ch))) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbor
            if (i > 0) {
                char left = testStr.charAt(i - 1);
                if (vowelSet.contains(Character.toLowerCase(left))) {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbor (if we haven’t already found a vowel)
            if (!hasVowelNeighbor && i < len - 1) {
                char right = testStr.charAt(i + 1);
                if (vowelSet.contains(Character.toLowerCase(right))) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

