class LenLog {
    /**
     * * Write a Java function to find the length of the longest word.
     *
     * > lenLog(["python", "PHP", "bigdata"])
     * 7
     * > lenLog(["a", "ab", "abc"])
     * 3
     * > lenLog(["small", "big", "tall"])
     * 5
     */
    public static int lenLog(List<String> list1) {
        // Guard against null or empty input
        if (list1 == null || list1.isEmpty()) {
            return 0;
        }

        int maxLen = 0;
        for (String word : list1) {
            // Ignore any null entries
            if (word != null && word.length() > maxLen) {
                maxLen = word.length();
            }
        }
        return maxLen;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(lenLog(Arrays.asList("python", "PHP", "bigdata"))); // 7
        System.out.println(lenLog(Arrays.asList("a", "ab", "abc")));          // 3
        System.out.println(lenLog(Arrays.asList("small", "big", "tall")));    // 5
    }
}

