class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2*a(n-1) + a(n-2) for n >= 2.
     *
     * Examples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     *
     * @param n index of the required term (0‑based)
     * @return the n‑th NSW number
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases a(0) = a(1) = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a  = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(i)
            a0 = a1;
            a1 = a;
        }

        return (int) a; // the problem expects int
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

