        StringBuilder result = new StringBuilder();

        // Start at index 1 and step by 2 to pick only odd‑indexed characters
        for (int i = 1; i < str1.length(); i += 2) {
            result.append(str1.charAt(i));
        }

        return result.toString();
    }

