import java.util.regex.*;

public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the given text contains a word that has
     * the letter 'z' somewhere other than the first or last character.
     * Otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        // Use a regex to find each word (sequence of letters) in the input.
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A 'z' can only be interior if the word is at least 3 characters long.
            // Check each character from index 1 up to length‑2 (inclusive).
            for (int i = 1; i < word.length() - 1; i++) {
                if (word.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

    // Simple test harness
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a monotone path
     * (right/down) from the top‑left corner to the bottom‑right corner
     * of the given n×n cost matrix.
     *
     * @param cost square matrix of integers (List of List)
     * @param n    size of the matrix (number of rows/columns)
     * @return     the maximal average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP array, long is used to avoid overflow for large inputs
        long[][] dp = new long[n][n];

        // first cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                         + cost.get(i).get(j);
            }
        }

        // maximal sum and its average
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);

        return average;
    }

    // --------------------------------------------------------------------
    // Optional test harness (can be removed when the method is used elsewhere)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

