/* 
 * CountVowels counts characters that are not vowels (i.e. consonants) 
 * and that have a vowel as one of their immediate neighbours.
 */
class CountVowels {

    /** 
     * Returns the number of consonants in {@code testStr} that have 
     * at least one vowel (a, e, i, o, u) as a neighbour.
     *
     * @param testStr the input string (may contain upper‑ or lower‑case letters)
     * @return the required count
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Helper to test a character (case‑insensitive) for vowelness
        final String vowels = "aeiouAEIOU";

        int count = 0;
        int n = testStr.length();

        for (int i = 0; i < n; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only count consonants
            if (vowels.indexOf(ch) != -1) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbor = (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1);
            // Check right neighbour
            if (!hasVowelNeighbor && i < n - 1) {
                hasVowelNeighbor = (vowels.indexOf(testStr.charAt(i + 1)) != -1);
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));          // 5
    }
}

