class CountAlphaDigSpl {
    /**
     * Counts alphabets, digits and special characters in a given string.
     *
     * @param string the input text (may be null)
     * @return a List with three elements:
     *         - index 0 → number of alphabetic characters
     *         - index 1 → number of digit characters
     *         - index 2 → number of all other characters (special)
     *
     * Example:
     *   countAlphaDigSpl("abc!@#123") → [3, 3, 3]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Guard against null to satisfy defensive coding style
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alpha = 0, digit = 0, special = 0;

        // Use the standard library's Character helpers – they are well‑tested
        for (char ch : string.toCharArray()) {
            if (Character.isLetter(ch)) {
                alpha++;
            } else if (Character.isDigit(ch)) {
                digit++;
            } else {
                special++;
            }
        }

        // Return a fixed‑size list with the three counts
        return Arrays.asList(alpha, digit, special);
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

public static int seriesSum(int number) {
    // Use long to avoid intermediate overflow, then cast back to int.
    long n = number;
    long sum = n * (n + 1) * (2 * n + 1) / 6;   // n(n+1)(2n+1)/6
    return (int) sum;
}

