class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks–Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(i) = 2 * a(i‑1) + a(i‑2)  for i ≥ 2.
     *
     * @param n the index (0‑based) of the term to return
     * @return the n‑th Newman‑Shanks–Williams number
     * @throws IllegalArgumentException if n is negative
     * @throws ArithmeticException     if the result overflows int
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // a(0) and a(1) are both 1
        if (n == 0 || n == 1) {
            return 1;
        }

        int a0 = 1; // a(i‑2)
        int a1 = 1; // a(i‑1)

        for (int i = 2; i <= n; i++) {
            int a2 = 2 * a1 + a0;   // a(i) = 2*a(i‑1) + a(i‑2)

            // Optional overflow check (int overflow is rare for small n)
            if (a2 < 0) {
                throw new ArithmeticException("Overflow: value exceeds Integer range");
            }

            // shift the window for the next iteration
            a0 = a1;
            a1 = a2;
        }

        return a1;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

