class VolumeTetrahedron {
    /**
     * Write a function to calculate volume of a tetrahedron.
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        // Volume of a regular tetrahedron: V = a^3 / (6 * sqrt(2))
        double side = num;                     // the side length 'a'
        double volume = Math.pow(side, 3) / (6.0 * Math.sqrt(2));

        // Round to two decimal places (as required by the examples)
        double rounded = Math.round(volume * 100.0) / 100.0;

        return rounded;   // auto‑boxed to Double
    }
}

