     * Returns "Found a match!" if any word in the given text contains the
     * character 'z' somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern to find words: consecutive letters (a‑z or A‑Z)
        Pattern p = Pattern.compile("[a-zA-Z]+");
        Matcher m = p.matcher(text);

        while (m.find()) {
            String word = m.group();

            // Scan characters except the first and last.
            for (int i = 1; i < word.length() - 1; i++) {
                if (word.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

