class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the upper‑left cell
     * and ends at the lower‑right cell of the given n×n matrix.
     * Movement is restricted to steps to the right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum possible average (as a Double)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the DP table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Any path from (0,0) to (n‑1,n‑1) using only right/down moves
        // contains exactly (2*n - 1) cells.
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);
        return average;
    }

    // -----------------------------------------------------------------
    // Optional test driver (feel free to remove or comment out)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

class CountVowels {

    /**
     * Returns the number of characters (excluding the first and last)
     * that have at least one vowel (a, e, i, o, u, y) as a neighbour.
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() <= 2) {
            return 0;                     // nothing to examine
        }

        // Vowel set – includes 'y' as requested
        final String vowels = "aeiouy";
        int count = 0;

        // i runs from 1 to length‑2, i.e. we skip the first and last characters
        for (int i = 1; i < testStr.length() - 1; i++) {
            char prev = Character.toLowerCase(testStr.charAt(i - 1));
            char next = Character.toLowerCase(testStr.charAt(i + 1));

            if (vowels.indexOf(prev) >= 0 || vowels.indexOf(next) >= 0) {
                count++;
            }
        }
        return count;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));           // 5
    }
}

