class NewmanPrime {
    /**
     * Returns the n-th Newman–Shanks–Williams number.
     * The sequence is defined by a0 = 1, a1 = 1, a_i = 2*a_{i-1} + a_{i-2}.
     * For n >= 2 the values are 3, 7, 17, 41, ... (some of which are prime).
     *
     * @param n index (0‑based)
     * @return the n‑th term of the NSW sequence
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        if (n == 0) return 1;
        if (n == 1) return 1;

        long a0 = 1;
        long a1 = 1;
        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }

    // Optional test driver
    public static void main(String[] args) {
        for (int i = 2; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

