class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron given the edge length.
     *
     * @param num the length of each edge (integer)
     * @return the volume rounded to two decimal places
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        // Convert the integer edge length to double for the calculation
        double a = num;

        // Apply the regular tetrahedron volume formula: V = a³ / (6·√2)
        double volume = (a * a * a) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places to match the expected output format
        BigDecimal rounded = new BigDecimal(volume)
                .setScale(2, RoundingMode.HALF_UP);

        // Return the rounded value as a Double (auto‑boxed)
        return rounded.doubleValue();
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

import java.util.regex.*;

public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the supplied text contains a word that
     * includes the letter 'z' somewhere other than the first or last position.
     * Otherwise it returns "Not matched!".
     *
     * @param text the input string (may contain punctuation, spaces, etc.)
     * @return the appropriate message
     */
    public static String textMatchWordzMiddle(String text) {
        // Defensive check – a null or empty string can’t contain a matching word
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // \b marks word boundaries; [a-zA-Z]+ matches one or more letters.
        // This automatically strips punctuation such as '.' or ','.
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // e.g. "pythonzabc"
            String lower = word.toLowerCase();            // make the check case‑insensitive

            int zIndex = lower.indexOf('z');              // position of 'z' inside the word

            // A match occurs when 'z' is present and it is neither the first
            // nor the last character.
            if (zIndex != -1 && zIndex != 0 && zIndex != lower.length() - 1) {
                return "Found a match!";
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // A tiny main method to demonstrate the three examples from the Javadoc.
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left
     * corner and ends at the bottom‑right corner of the given n×n matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table holds the maximum sum to reach each cell.
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Maximum sum from top‑left to bottom‑right
        double maxSum = dp[n - 1][n - 1];

        // Every such path contains exactly (2*n - 1) cells
        double average = maxSum / (2 * n - 1);

        return average; // auto‑boxed to Double
    }

    // -----------------------------------------------------------------
    // Simple test harness (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

