class CountVowels {

    /**
     * Counts consonants that have at least one vowel as an adjacent character.
     *
     * @param testStr the input string (may contain letters only)
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }

        // Vowel set – we treat both lower‑ and upper‑case as vowels
        final String vowels = "aeiou";

        int n = testStr.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char ch = testStr.charAt(i);
            // Skip vowels themselves – we only count consonants
            if (vowels.indexOf(Character.toLowerCase(ch)) != -1) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0) {
                char left = testStr.charAt(i - 1);
                if (vowels.indexOf(Character.toLowerCase(left)) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbour (only if we haven't found a vowel yet)
            if (!hasVowelNeighbor && i < n - 1) {
                char right = testStr.charAt(i + 1);
                if (vowels.indexOf(Character.toLowerCase(right)) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple manual test (not required by the platform)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

