class LenLog {
    /**
     * Returns the length of the longest word in the given list.
     *
     * @param list1 a List of String objects (may be null or empty)
     * @return the maximum length among the strings; 0 if the list is null/empty
     *
     * Example:
     *   lenLog(Arrays.asList("python", "PHP", "bigdata")) → 7
     *   lenLog(Arrays.asList("a", "ab", "abc"))           → 3
     *   lenLog(Arrays.asList("small", "big", "tall"))    → 5
     */
    public static int lenLog(List<String> list1) {
        // Guard against null or empty input
        if (list1 == null || list1.isEmpty()) {
            return 0;
        }

        int maxLen = 0;
        for (String s : list1) {
            // Skip any null entries – they don’t contribute to the length
            if (s != null && s.length() > maxLen) {
                maxLen = s.length();
            }
        }
        return maxLen;
    }

    // Optional: a simple test driver
    public static void main(String[] args) {
        System.out.println(lenLog(Arrays.asList("python", "PHP", "bigdata"))); // 7
        System.out.println(lenLog(Arrays.asList("a", "ab", "abc")));          // 3
        System.out.println(lenLog(Arrays.asList("small", "big", "tall")));    // 5
    }
}

import java.io.*;
