import java.math.*;

class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle invalid input
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // The first NSW prime is 2
        if (n == 1) {
            return 2;
        }

        // List to store NSW primes (excluding the first prime 2)
        List<BigInteger> primes = new ArrayList<>();

        // Initialize the sequence: a(0) = 1, a(1) = 1
        BigInteger a0 = BigInteger.ONE;
        BigInteger a1 = BigInteger.ONE;

        // Generate primes from a(2) onward
        // We need to collect (n-1) primes because the first prime (2) is handled separately
        for (int i = 2; primes.size() < n - 1; i++) {
            // Compute a(i) = 2 * a(i-1) + a(i-2)
            BigInteger a2 = a1.multiply(BigInteger.valueOf(2)).add(a0);

            // Check if a2 is prime
            if (a2.isProbablePrime(100)) {
                primes.add(a2);
            }

            // Update the sequence
            a0 = a1;
            a1 = a2;
        }

        // Return the n-th NSW prime (primes list is 0-indexed, so we get index n-2)
        // Convert BigInteger to int (assuming it fits within integer range)
        return primes.get(n - 2).intValue();
    }
}

