class VolumeTetrahedron {
    /**
     * * Write a function to calculate volume of a tetrahedron.
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        // Use BigDecimal for exact arithmetic (no floating‑point rounding during the calculation)
        BigDecimal a = BigDecimal.valueOf(num);          // side length
        BigDecimal aCubed = a.pow(3);                    // a³

        // sqrt(2) with enough precision (double precision is sufficient for this scale)
        BigDecimal sqrt2 = BigDecimal.valueOf(Math.sqrt(2));

        // denominator = 6 * sqrt(2)
        BigDecimal denominator = BigDecimal.valueOf(6).multiply(sqrt2);

        // Compute volume with a higher internal scale before rounding
        // 10 scale gives us extra precision before we finally round to 2 decimals
        BigDecimal volume = aCubed.divide(denominator, 10, RoundingMode.HALF_UP);

        // Round to two decimal places to match the expected output
        BigDecimal result = volume.setScale(2, RoundingMode.HALF_UP);

        // Return as a boxed Double (the required return type)
        return result.doubleValue();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

