class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split the input into "words" – sequences of letters only
        String[] words = text.split("[^a-zA-Z]+");

        for (String word : words) {
            // Skip any empty tokens (e.g., from leading/trailing delimiters)
            if (word.isEmpty()) {
                continue;
            }

            // Perform a case‑insensitive search for 'z'
            int idx = word.toLowerCase().indexOf('z');

            // If 'z' exists and is not at the first or last position, we have a match
            if (idx > 0 && idx < word.length() - 1) {
                return "Found a match!";
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

import java.util.*;
import java.math.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner of the given n×n matrix and ends at the bottom‑right
     * corner, moving only right or down.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     the dimension of the square matrix
     * @return      the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic sanity check
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long cellValue = cost.get(i).get(j).longValue();

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cellValue;
                } else {
                    long bestFromAbove = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                    long bestFromLeft = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;
                    dp[i][j] = cellValue + Math.max(bestFromAbove, bestFromLeft);
                }
            }
        }

        // The length of any valid path is always 2*n - 1
        int pathLength = 2 * n - 1;
        long maxSum = dp[n - 1][n - 1];

        // Compute the average as a double (the denominator is constant,
        // so maximizing the sum also maximizes the average)
        double average = (double) maxSum / pathLength;

        return average;
    }

    // ------------------------------------------------------------------
    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

