/**
 * CountVowels counts the consonants (non‑vowel characters) in a string
 * that have a vowel as an immediate neighbor (either to the left or right).
 */
class CountVowels {

    /**
     * Returns the number of characters that are not vowels and have at least
     * one vowel neighbor.
     *
     * @param testStr the input string
     * @return count of such characters
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty strings
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with a lower‑case version for easy vowel checking
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = s.charAt(i);

            // Skip vowels – we only count consonants that have a vowel neighbor
            if (isVowel(ch)) {
                continue;
            }

            // Check left neighbor
            boolean leftIsVowel = (i > 0) && isVowel(s.charAt(i - 1));
            // Check right neighbor
            boolean rightIsVowel = (i < len - 1) && isVowel(s.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

    /** Helper method to determine if a character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // --------------------------------------------------------------------
    // Optional main method for quick manual testing
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

import java.util.Arrays;
import java.util.List;

public class CountAlphaDigSpl {

    /**
     * Counts alphabets, digits and special characters in a given string.
     *
     * @param string the input text (may be null)
     * @return a List containing three integers:
     *         - number of alphabetic characters,
     *         - number of digit characters,
     *         - number of special (non‑letter, non‑digit) characters
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Treat null as an empty string
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alphabets = 0;
        int digits = 0;
        int specials = 0;

        for (char ch : string.toCharArray()) {
            if (Character.isLetter(ch)) {
                alphabets++;
            } else if (Character.isDigit(ch)) {
                digits++;
            } else {
                specials++;
            }
        }

        // Return the three counts as an immutable list
        return Arrays.asList(alphabets, digits, specials);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

