class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle non‑negative index
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases for the NSW sequence
        if (n == 0) return 1; // a(0)
        if (n == 1) return 1; // a(1)

        // Iterate to compute the n‑th term
        long a0 = 1; // a(i-2)
        long a1 = 1; // a(i-1)
        long a = 0;  // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence relation
            a0 = a1;
            a1 = a;
        }

        // Return the computed value as an int
        return (int) a;
    }
}

class RemoveOdd {
    /**
     * Removes characters at odd positions (1‑based) from the input string,
