     * @return a new string containing only the characters at odd indices
     */
    public static String removeOdd(String str1) {
        // Guard against null or very short strings
        if (str1 == null || str1.length() <= 1) {
            return "";
        }

        StringBuilder result = new StringBuilder();

        // Start at index 1 and step by 2 to pick every odd‑indexed character
        for (int i = 1; i < str1.length(); i += 2) {
            result.append(str1.charAt(i));
        }

        return result.toString();
    }

