class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron with edge length `num`.
     *
     * Volume formula: V = a³ / (6·√2)
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        // Use primitive double for the calculation (Item 61)
        double edge = num;
        double volume = (edge * edge * edge) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places to match the expected output
        volume = Math.round(volume * 100.0) / 100.0;

        // Autobox to Double for the return type
        return volume;
    }

    // Optional main method for manual testing
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

