import java.util.*;

public class Maxaverageofpath {
    /**
     * Returns the maximum average of any path that travels from the top‑left
     * corner to the bottom‑right corner of an n×n matrix, moving only right
     * or down.  The average is (sum of visited cells) / (2·n‑1) because every
     * such path contains exactly 2·n‑1 cells.
     *
     * @param cost  list of rows, each row a list of integers
     * @param n     size of the square matrix
     * @return      the maximum average as a boxed {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation – the problem guarantees correct input,
        // but we guard against null/empty for robustness.
        if (cost == null || cost.size() < n) {
            return null;
        }

        // ------------------------------------------------------------
        // DP using primitive double (Item 61: prefer primitives)
        // ------------------------------------------------------------
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Remaining cells – take the better of the two predecessors
        for (int i = 1; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 1; j < n; j++) {
                double best = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = best + row.get(j);
            }
        }

        // The best sum is in the bottom‑right cell.
        double maxSum = dp[n - 1][n - 1];

        // Every path has exactly (2·n‑1) cells, so the average is:
        double average = maxSum / (2.0 * n - 1.0);

        // Auto‑boxing converts the primitive double to a Double.
        return average;
    }

    // -----------------------------------------------------------------
    // Simple test driver (feel free to remove / comment out)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

