class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   s0 = 1, s1 = 1
     *   sn = 2 * s(n‑1) + s(n‑2)  for n >= 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute the sequence iteratively using long to avoid early overflow
        long prev2 = 1; // s0
        long prev1 = 1; // s1
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // sn = 2*s(n‑1) + s(n‑2)
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int; cast (the test values are within int range)
        return (int) current;
    }
}

