public class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a path that starts at the
     * top‑left corner of the square matrix and ends at the bottom‑right corner.
     * The path may move only right or down, and every cell's value is taken
     * into the sum. The average is the sum divided by the number of visited
     * cells (2·n‑1).
     *
     * @param cost the n×n matrix of Integer values
     * @param n    size of the matrix (must match cost.size())
     * @return the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against bad input – following the advice to avoid null‑related bugs
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = best sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Retrieve the cell value; the Integer is auto‑unboxed to a primitive int.
                // Using a primitive int avoids the NullPointerException described in the advice.
                long cur = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cur;
                } else if (i == 0) {
                    // First row – can only come from the left
                    dp[i][j] = dp[i][j - 1] + cur;
                } else if (j == 0) {
                    // First column – can only come from above
                    dp[i][j] = dp[i - 1][j] + cur;
                } else {
                    // General case: choose the better of the two possible predecessors
                    dp[i][j] = cur + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // The best sum reaches the bottom‑right corner
        long maxSum = dp[n - 1][n - 1];

        // Number of cells visited by any monotone path = 2·n – 1
        double average = maxSum / (double) (2 * n - 1);

        return average;
    }

    // -----------------------------------------------------------------
    // Optional test driver (you can remove this when submitting)
    public static void main(String[] args) {
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

