public static int newmanPrime(int n) {
    // Handle edge cases: n <= 0 returns 0, n == 1 returns 1
    if (n <= 0) return 0;
    if (n == 1) return 1;

    // Initialize the first two terms of the sequence
    long a0 = 1;
    long a1 = 1;

    // Compute the sequence up to the nth term
    for (int i = 2; i <= n; i++) {
        long a2 = 2 * a1 + a0; // Recurrence: a_n = 2*a_{n-1} + a_{n-2}
        a0 = a1;
        a1 = a2;
    }

    // Return the nth term cast to int
    return (int) a1;
}

