class Maxaverageofpath {
    /**
     * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP array for maximum sum from (0,0) to each cell (i,j)
        double[][] dp = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j); // boxed Integer -> int
                if (i == 0 && j == 0) {
                    dp[i][j] = val;
                } else if (i == 0) {
                    dp[i][j] = dp[i][j-1] + val;
                } else if (j == 0) {
                    dp[i][j] = dp[i-1][j] + val;
                } else {
                    dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]) + val;
                }
            }
        }
        double maxSum = dp[n-1][n-1];
        // Number of cells visited in any monotonic path = 2*n - 1
        double average = maxSum / (2 * n - 1);
        return Double.valueOf(average);
    }

    // Optional test driver
    public static void main(String[] args) {
        List<List<Integer>> cost1 = List.of(
            List.of(1, 2, 3),
            List.of(6, 5, 4),
            List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = List.of(
            List.of(2, 3, 4),
            List.of(7, 6, 5),
            List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = List.of(
            List.of(3, 4, 5),
            List.of(8, 7, 6),
            List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

