/**
 * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
 *
 * The sequence is defined by:
 *   a0 = 1, a1 = 1,
 *   a_n = 2 * a_{n-1} + a_{n-2}   for n >= 2
 *
 * @param n the index of the term to return (0‑based)
 * @return the value of a_n
 * @throws IllegalArgumentException if n is negative
 */
public static int newmanPrime(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }

    // Handle the first two base cases
    if (n == 0 || n == 1) {
        return 1;
    }

    int a0 = 1; // a_{n-2}
    int a1 = 1; // a_{n-1}
    int a = 0;  // a_n

    // Compute the sequence iteratively up to index n
    for (int i = 2; i <= n; i++) {
        a = 2 * a1 + a0; // a_n = 2*a_{n-1} + a_{n-2}
        a0 = a1;         // shift for next iteration
        a1 = a;
    }

    return a;
}

