class TextMatchWordzMiddle {

    /**
     * Checks whether any word in the given text contains the letter 'z'
     * that is not at the first or the last position of the word.
     *
     * @param text the input text (may contain punctuation, spaces, etc.)
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Regular expression that matches a word: one or more ASCII letters.
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A single‑character word can never have an internal 'z'.
            if (word.length() < 3) {
                continue;
            }

            // Scan for a 'z' that is not the first or last character.
            boolean hasInternalZ = false;
            for (int i = 1; i < word.length() - 1; i++) {
                if (word.charAt(i) == 'z' || word.charAt(i) == 'Z') {
                    hasInternalZ = true;
                    break;
                }
            }

            if (hasInternalZ) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

