            // left neighbour
            if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) >= 0) {
                hasVowelNeighbor = true;
            }
            // right neighbour
            if (!hasVowelNeighbor && i < len - 1 && vowels.indexOf(testStr.charAt(i + 1)) >= 0) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

