class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the last term of the series (must be non‑negative)
     * @return the sum of the squares from 1 to number
     * @throws IllegalArgumentException if number is negative
     */
    public static int seriesSum(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("Number must be non‑negative");
        }

        // Use the closed‑form formula: n(n+1)(2n+1)/6
        // Compute in long to avoid intermediate overflow, then cast back to int.
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;
        return (int) sum;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

