public class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     * The sequence is defined by:
     *   a1 = 1, a2 = 3,
     *   an = 2·a(n‑1) + a(n‑2)  for n ≥ 3.
     *
     * @param n position in the sequence (1‑based)
     * @return the value a_n (the n‑th NSW number, which is prime for n ≥ 2)
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            // The problem definition does not cover non‑positive indices.
            // We return 0 as a sentinel; callers are expected to use n ≥ 1.
            return 0;
        }
        if (n == 1) {
            return 1;   // a1 = 1 (not prime, but part of the recurrence)
        }
        if (n == 2) {
            return 3;   // a2 = 3 (first prime in the sequence)
        }

        long prev2 = 1L; // a1
        long prev1 = 3L; // a2

        for (int i = 3; i <= n; i++) {
            long cur = 2 * prev1 + prev2; // an
            prev2 = prev1;
            prev1 = cur;
        }

        // The result fits into an int for the typical range of n.
        return (int) prev1;
    }

    // Simple manual test (can be removed)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

