class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        StringBuilder currentWord = new StringBuilder();

        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);
            if (Character.isLetter(ch)) {
                // Build the current word
                currentWord.append(ch);
            } else {
                // Encountered a non‑letter → end of a word
                if (containsMiddleZ(currentWord.toString())) {
                    return "Found a match!";
                }
                // Reset for the next word
                currentWord.setLength(0);
            }
        }

        // Check the last word in case the string ends with letters
        if (containsMiddleZ(currentWord.toString())) {
            return "Found a match!";
        }

        return "Not matched!";
    }

    /**
     * Returns true if the given word contains the letter 'z' (case‑insensitive)
     * in a position that is neither the first nor the last character.
     */
    private static boolean containsMiddleZ(String word) {
        // A word shorter than 3 characters cannot have a middle 'z'
        if (word == null || word.length() < 3) {
            return false;
        }
        // Examine only the interior characters (index 1 .. length-2)
        for (int i = 1; i < word.length() - 1; i++) {
            if (Character.toLowerCase(word.charAt(i)) == 'z') {
                return true;
            }
        }
        return false;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
