    /**
     * Returns the n‑th Newman‑Shanks‑Williams number (0‑based index).
     *
     * @param n the index of the required number (n ≥ 0)
     * @return the value s_n of the NSW sequence
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // s0 = 1, s1 = 1
        if (n == 0 || n == 1) {
            return 1;
