        long a1 = 1; // s1

        for (int i = 2; i <= n; i++) {
            long an = 2 * a1 + a0; // s_i = 2·s_{i‑1} + s_{i‑2}
            a0 = a1;
            a1 = an;
        }
        return (int) a1; // the problem expects an int
    }

