public static String textMatchWordzMiddle(String text) {
    // Pattern matches sequences of ASCII letters – i.e. words.
    // Using CASE_INSENSITIVE lets us match both 'z' and 'Z' with a single search.
    Pattern wordPattern = Pattern.compile("[A-Za-z]+", Pattern.CASE_INSENSITIVE);
    Matcher matcher = wordPattern.matcher(text);

    while (matcher.find()) {
        String word = matcher.group();

        // Find the index of 'z' (or 'Z') inside the word.
        int zIndex = word.indexOf('z');            // indexOf works for lower‑case
        if (zIndex == -1) {
            // If not found as lower‑case, try upper‑case (not needed with CASE_INSENSITIVE,
            // but kept for clarity)
            zIndex = word.indexOf('Z');
        }

        // The word matches if it contains 'z' and that character is not at the
        // first or last position.
        if (zIndex != -1 && zIndex > 0 && zIndex < word.length() - 1) {
            return "Found a match!";
        }
    }

    // No qualifying word was found.
    return "Not matched!";
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // dp[i][j] stores the maximum sum to reach cell (i, j)
    long[][] dp = new long[n][n];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            long val = cost.get(i).get(j);          // value of the current cell
            if (i == 0 && j == 0) {
                dp[i][j] = val;                     // start cell
            } else {
                long best = Long.MIN_VALUE;
                if (i > 0) best = Math.max(best, dp[i - 1][j]); // from above
                if (j > 0) best = Math.max(best, dp[i][j - 1]); // from left
                dp[i][j] = val + best;
            }
        }
    }

    long maxSum = dp[n - 1][n - 1];                // maximum sum to the bottom‑right
    // Every path has exactly (2*n - 1) cells, so the average is:
    double average = (double) maxSum / (2 * n - 1);
    return average;                                 // auto‑boxed to Double
}

