class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2*a(n‑1) + a(n‑2)  for n >= 2
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // For n = 0 or 1 the value is 1
        if (n == 0 || n == 1) {
            return 1;
        }

        BigInteger a0 = BigInteger.ONE; // a(n‑2)
        BigInteger a1 = BigInteger.ONE; // a(n‑1)
        BigInteger a  = BigInteger.ZERO; // a(n)

        for (int i = 2; i <= n; i++) {
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            a0 = a1;
            a1 = a;
        }
        // The result fits in an int for reasonable n; cast accordingly
        return a.intValue();
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

