class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        boolean found = false;
        int i = 0;
        final int n = text.length();

        // Scan the input once, extracting each word (sequence of letters).
        while (i < n) {
            // Skip non‑letter characters.
            while (i < n && !Character.isLetter(text.charAt(i))) {
                i++;
            }
            if (i >= n) break;                // no more words

            int start = i;
            // Advance to the end of the current word.
            while (i < n && Character.isLetter(text.charAt(i))) {
                i++;
            }
            String word = text.substring(start, i); // word length = i - start

            // A 'z' can only be “in the middle” if the word is at least 3 characters long.
            if (word.length() >= 3) {
                // Look for 'z' or 'Z' inside the word.
                int zIdx = word.indexOf('z');
                if (zIdx == -1) {
                    zIdx = word.indexOf('Z');
                }
                // Check that the 'z' is neither the first nor the last character.
                if (zIdx != -1 && zIdx > 0 && zIdx < word.length() - 1) {
                    found = true;
                    break;                     // no need to look further
                }
            }
        }

        // Use a StringBuilder for the result – cheap and avoids any hidden concatenation.
        StringBuilder sb = new StringBuilder();
        if (found) {
            sb.append("Found a match!");
        } else {
            sb.append("Not matched!");
        }
        return sb.toString();
    }
}

import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the upper‑left
     * corner and ends at the lower‑right corner of the given n×n matrix.
     * Movement is restricted to right or down only.
     *
     * @param cost the square matrix (list of rows)
     * @param n    size of the matrix
     * @return     the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);
        return Double.valueOf(average);
    }

    // --------------------------------------------------------------------
    // Simple manual test (not part of the required solution)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

