class CountVowels {

    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() < 2) {
            // No character can have a neighbour if the string is empty or has length 1
            return 0;
        }

        // Helper to check if a character is a vowel (case‑insensitive)
        java.util.function.Function<Character, Boolean> isVowel = ch -> {
            char c = Character.toLowerCase(ch);
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        };

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // We only count non‑vowel characters that have a vowel neighbour
            if (!isVowel.apply(ch)) {
                boolean hasVowelNeighbour = false;

                // Check left neighbour
                if (i > 0 && isVowel.apply(testStr.charAt(i - 1))) {
                    hasVowelNeighbour = true;
                }
                // Check right neighbour (only if left didn't already satisfy)
                if (!hasVowelNeighbour && i < len - 1 && isVowel.apply(testStr.charAt(i + 1))) {
                    hasVowelNeighbour = true;
                }

                if (hasVowelNeighbour) {
                    count++;
                }
            }
        }
        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

