class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle edge cases
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        if (n == 0 || n == 1) {
            return 1; // Base cases: a(0) = 1, a(1) = 1
        }

        // Iterate to compute the nth term using the recurrence
        // a(n) = 2 * a(n-1) + a(n-2)
        long a0 = 1; // a(0)
        long a1 = 1; // a(1)
        long a = 0;  // a(n) to be computed

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // Compute a(i)
            a0 = a1;         // Update a0 to a(i-1)
            a1 = a;          // Update a1 to a(i)
        }

        // Return the result as an int (assuming it fits within int range)
        return (int) a;
    }
}

