import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the upper‑left cell
     * (0,0) and ends at the lower‑right cell (n‑1,n‑1) of the given n×n matrix.
     * Movement is allowed only to the right or downward.
     *
     * @param cost the square matrix of non‑negative integer costs
     * @param n    the dimension of the matrix (cost.size() == n)
     * @return the maximum average (rounded to one decimal place) as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- defensive checks -------------------------------------------------
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // ---- DP table: dp[i][j] = maximum sum to reach cell (i, j) ----------
        // We use the List interface as the type (per Item 64)
        List<List<Double>> dp = new ArrayList<>(n);

        // ----- first row (i == 0) ---------------------------------------------
        List<Double> firstRow = new ArrayList<>(n);
        double runningSum = 0.0;
        for (int j = 0; j < n; j++) {
            runningSum += cost.get(0).get(j).doubleValue();
            firstRow.add(runningSum);
        }
        dp.add(firstRow);

        // ----- remaining rows --------------------------------------------------
        for (int i = 1; i < n; i++) {
            List<Double> curRow = new ArrayList<>(n);

            // first column (j == 0)
            double fromAbove = dp.get(i - 1).get(0);
            double cellCost  = cost.get(i).get(0).doubleValue();
            curRow.add(fromAbove + cellCost);

            // other columns
            for (int j = 1; j < n; j++) {
                double bestFromAbove = dp.get(i - 1).get(j);
                double bestFromLeft = curRow.get(j - 1);
                double cellValue    = cost.get(i).get(j).doubleValue();

                curRow.add(cellValue + Math.max(bestFromAbove, bestFromLeft));
            }
            dp.add(curRow);
        }

        // ---- compute the average ----------------------------------------------
        double maxSum    = dp.get(n - 1).get(n - 1);   // sum of the best path
        double average   = maxSum / (2 * n - 1);       // length of any monotonic path

        // round to one decimal place to match the examples
        average = Math.round(average * 10.0) / 10.0;

        return Double.valueOf(average);
    }

    // ---- simple manual test -------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
