     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null input
        if (testStr == null) {
            return 0;
        }

        // Use the Set interface to store vowels (both lower‑ and upper‑case)
        Set<Character> vowels = new HashSet<>(Arrays.asList(
                'a', 'e', 'i', 'o', 'u',
                'A', 'E', 'I', 'O', 'U'
        ));

        int length = testStr.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            char ch = testStr.charAt(i);

            // We only count non‑vowel characters that have a vowel neighbour
            if (!vowels.contains(ch)) {
                boolean hasVowelNeighbor = (i > 0 && vowels.contains(testStr.charAt(i - 1)))   // left neighbour
                                         || (i < length - 1 && vowels.contains(testStr.charAt(i + 1))); // right neighbour

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }

        return count;
    }

    // Simple test driver (optional)
