class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * For the values shown in the examples (n = 3,4,5) this coincides
     * with the NSW primes 7, 17 and 41.
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th term of the NSW sequence
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // a0 = a1 = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long prev2 = 1; // a_{i-2}
        long prev1 = 1; // a_{i-1}
        long cur = 0;  // a_i

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2; // a_i = 2*a_{i-1} + a_{i-2}
            prev2 = prev1;
            prev1 = cur;
        }

        return (int) cur; // the sequence fits in int for reasonable n
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

