import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path from the top‑left corner
     * to the bottom‑right corner of the given n×n matrix.
     * The path may only move right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table: dp[i][j] holds the maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                // Convert the integer cost to double for arithmetic
                double cur = cost.get(i).get(j).doubleValue();

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cur;
                } else {
                    // Best previous sum coming from above or from the left
                    double fromUp    = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double fromLeft  = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = cur + Math.max(fromUp, fromLeft);
                }
            }
        }

        // The path length (number of visited cells) is 2*n - 1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        // Return as a Double (boxed) to match the method signature
        return average;
    }
}

