class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle edge cases
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        if (n == 0) {
            return 1; // s0 = 1
        }
        if (n == 1) {
            return 1; // s1 = 1
        }

        // Initialize the first two NSW numbers
        long prev2 = 1; // s0
        long prev1 = 1; // s1
        long current = 0;

        // Compute the NSW number at index n
        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }

        // Return the result as an int (assuming it fits within int range)
        return (int) current;
    }
}

