class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i < testStr.length(); i++) {
            char c = testStr.charAt(i);
            // Only count consonants (non‑vowel characters)
            if (isVowel(c)) {
                continue;
            }

            // Check left neighbor
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                count++;
                continue;
            }

            // Check right neighbor
            if (i < testStr.length() - 1 && isVowel(testStr.charAt(i + 1))) {
                count++;
            }
        }
        return count;
    }

    /** Helper method to determine if a character is a vowel (case‑insensitive). */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u';
    }
}

