class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2·a(n‑1) + a(n‑2)   for n ≥ 2
     *
     * The values for n = 3, 4, 5 … are 7, 17, 41 … (often prime).
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // base cases
        if (n == 1) return 1;   // a(1) = 1
        if (n == 2) return 3;  // a(2) = 3

        int a0 = 1; // a(1)
        int a1 = 1; // a(2) = 3 after the first iteration
        int a  = 0;

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }
        return a;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

