public class TextMatchWordzMiddle {

    /**
     * Checks whether the given text contains a word that includes the character 'z'
     * (case‑insensitive) somewhere other than the first or last position.
     *
     * @param text the input string to examine
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Defensive check – a null string is treated as no match.
        if (text == null) {
            return "Not matched!";
        }

        // Regex explanation:
        // \b               – word boundary
        // [A-Za-z]+        – one or more letters (the part before the 'z')
        // [zZ]             – the letter 'z' (case‑insensitive)
        // [A-Za-z]+        – one or more letters (the part after the 'z')
        // \b               – word boundary
        Pattern p = Pattern.compile("\\b[A-Za-z]+[zZ][A-Za-z]+\\b", Pattern.CASE_INSENSITIVE);
        Matcher m = p.matcher(text);

        return m.find() ? "Found a match!" : "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));    // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));  // "Not matched!"
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the upper‑left
     * cell and ends at the lower‑right cell, moving only right or down.
     *
     * @param cost square matrix of integers
     * @param n    dimension of the matrix (cost.size() == n)
     * @return the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive checks
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach (i, j)
        double[][] dp = new double[n][n];

        // initialise start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                          + cost.get(i).get(j);
            }
        }

        // maximum sum and corresponding average
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1); // denominator is constant for given n

        return average;
    }
}

