class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   ai = 2 * a(i‑1) + a(i‑2)  for i >= 2
     *
     * @param n index (0‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0) return 1;
        if (n == 1) return 1;

        // Use long to avoid overflow while computing the recurrence
        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a  = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        // The problem expects an int return type; the values fit in int for reasonable n.
        return (int) a;
    }

    // Optional simple test (not required for the solution)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

