import java.util.List;

public class Maxaverageofpath {

    /**
     * Computes the maximum possible average of a monotone path
     * (moving only right or down) from the top‑left corner to the
     * bottom‑right corner of an n×n integer matrix.
     *
     * @param cost square matrix of integers
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a {@code Double}, or {@code null}
     *         if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive checks
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = best sum to reach (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int c = cost.get(i).get(j);          // cost of current cell

                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = c;
                } else if (i == 0) {
                    // first row: can only come from the left
                    dp[i][j] = dp[i][j - 1] + c;
                } else if (j == 0) {
                    // first column: can only come from above
                    dp[i][j] = dp[i - 1][j] + c;
                } else {
                    // general case: take the better predecessor
                    dp[i][j] = c + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1); // length of any monotone path
        return average;
    }

    // -----------------------------------------------------------------
    // Simple manual test (not part of the required solution)
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

