class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Null or empty string → no characters to count
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set (lower‑case only – we’ll compare case‑insensitively)
        final String vowels = "aeiou";

        int count = 0;
        int n = testStr.length();

        for (int i = 0; i < n; i++) {
            char current = testStr.charAt(i);
            char lowerCurrent = Character.toLowerCase(current);

            // Skip vowels themselves; we only count consonants (or non‑vowel characters)
            if (vowels.indexOf(lowerCurrent) != -1) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0) {
                char left = Character.toLowerCase(testStr.charAt(i - 1));
                if (vowels.indexOf(left) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbour (only if we haven’t already found a vowel neighbour)
            if (!hasVowelNeighbor && i < n - 1) {
                char right = Character.toLowerCase(testStr.charAt(i + 1));
                if (vowels.indexOf(right) != -1) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

