    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // a0 = a(0), a1 = a(1)
        long a0 = 1L;
        long a1 = 1L;

        // Compute a(2) … a(n) iteratively
        for (int i = 2; i <= n; i++) {
            long a2 = 2 * a1 + a0; // recurrence
            a0 = a1;
            a1 = a2;
        }

        // n == 0 → a0, n == 1 → a1, otherwise a1 holds a(n)
        if (n == 0) return (int) a0;
        return (int) a1;   // for n >= 1
    }
}

