    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     * The sequence of NSW primes (starting from the second prime) is:
     * 3, 7, 17, 41, 239, 577, …
     *
     * For n >= 2 the method returns the (n‑1)-th prime in that sequence
     * (i.e. it skips the first prime 3).  For n == 1 the method returns 3.
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // n == 1 -> first NSW prime = 3
        if (n == 1) {
            return 3;
        }

        List<Integer> primes = new ArrayList<>();

        long a = 1;   // S0
        long b = 1;   // S1

        // Generate NSW numbers starting from S2 (value 3)
        for (int i = 2; primes.size() < n - 1; i++) {
            long c = 2 * b + a;          // Sn
            if (isPrime(c)) {
                primes.add((int) c);    // store the prime
            }
            a = b;
            b = c;
        }

        // Return the (n‑2)-th prime (0‑based index)
        return primes.get(n - 2);
    }

    /** Trial‑division primality test for positive long values. */
    private static boolean isPrime(long num) {
        if (num <= 1) return false;
        if (num <= 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        long limit = (long) Math.sqrt(num);
        for (long i = 5; i <= limit; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

