import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * upper‑left corner, ends at the lower‑right corner and moves only
     * right or down.
     *
     * @param cost square matrix (List of rows) containing the cell costs
     * @param n    size of the matrix (n × n)
     * @return     the maximal average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;                // invalid input
        }

        // dp[i][j] = best sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) +
                           Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);   // number of cells on any path
        return average;
    }

    // --------------------------------------------------------------
    // Simple test harness (not part of the required solution)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = new ArrayList<>();
        m1.add(Arrays.asList(1, 2, 3));
        m1.add(Arrays.asList(6, 5, 4));
        m1.add(Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = new ArrayList<>();
        m2.add(Arrays.asList(2, 3, 4));
        m2.add(Arrays.asList(7, 6, 5));
        m2.add(Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = new ArrayList<>();
        m3.add(Arrays.asList(3, 4, 5));
        m3.add(Arrays.asList(8, 7, 6));
        m3.add(Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

