class CountVowels {
    /** 
     * Counts characters that are NOT vowels and that have a vowel 
     * as an immediate neighbour (to the left or to the right).
     *
     * @param testStr the input string (assumed non‑null)
     * @return the number of such characters
     *
     * Examples:
     *   countVowels("bestinstareels")          -> 7
     *   countVowels("partofthejourneyistheend")-> 12
     *   countVowels("amazonprime")             -> 5
     */
    public static int countVowels(String testStr) {
        // Quick handling for null or empty strings
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set (both lower‑ and upper‑case)
        final String VOWELS = "aeiouAEIOU";

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only count consonants (or any non‑vowel)
            if (VOWELS.indexOf(ch) != -1) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbor = false;
            if (i > 0 && VOWELS.indexOf(testStr.charAt(i - 1)) != -1) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour if left didn't give a vowel
            if (!hasVowelNeighbor && i < len - 1
                    && VOWELS.indexOf(testStr.charAt(i + 1)) != -1) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

