class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2*a(n‑1) + a(n‑2)  for n >= 2
     *
     * @param n the index (0‑based) of the desired term
     * @return the value of a(n)
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        long prev2 = 1; // a(0)
        long prev1 = 1; // a(1)
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // a(i) = 2*a(i‑1) + a(i‑2)
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int; the series stays well within int range for reasonable n.
        return (int) current;
    }
}

