class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the letter 'z'
     * somewhere other than the first or last position. Otherwise returns "Not matched!".
     *
     * @param text the input string to examine
     * @return the appropriate message
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern that matches a whole word consisting of ASCII letters only.
        // \b denotes a word boundary (between a letter and a non‑letter such as space or punctuation).
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();          // the actual word text
            int zIndex = word.indexOf('z');         // position of 'z' inside the word, -1 if absent

            // If 'z' exists and is not at the first (0) or last (length‑1) position,
            // we have a match.
            if (zIndex != -1 && zIndex != 0 && zIndex != word.length() - 1) {
                return "Found a match!";
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

