class Maxaverageofpath {
    /**
     * Returns the maximum possible average of a path that goes from the
     * top‑left corner to the bottom‑right corner of the given n×n matrix.
     * Movement is restricted to right or down steps only.
     *
     * @param cost the n×n matrix of integers
     * @param n    size of the matrix
     * @return the maximum average (as a Double)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Invalid cost matrix");
        }

        // dp[i][j] = max sum to reach (i, j) from (0,0)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // Total number of cells in any valid path = 2*n - 1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        // Auto‑boxing to Double (the method signature returns Double)
        return average;
    }

    // -----------------------------------------------------------------
    // Simple test driver (not required for the solution, but convenient)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
