class TextMatchWordzMiddle {
    /**
     * Returns "Found a match!" if the input string contains a word
     * that has the letter 'z' somewhere other than the first or last
     * position; otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern that matches a whole word consisting of ASCII letters.
        // \b denotes a word boundary, so punctuation such as '.' is ignored.
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // Look for 'z' (case‑insensitive) inside the word.
            int zIdx = word.indexOf('z');
            if (zIdx == -1) {               // also accept uppercase 'Z'
                zIdx = word.indexOf('Z');
            }

            // A match is valid only when 'z' is present and it is
            // neither the first nor the last character of the word.
            if (zIdx != -1 && zIdx != 0 && zIdx != word.length() - 1) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // Optional test driver (you can remove this when submitting)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));   // Not matched!
    }
}

import java.util.List;

public class MaxAverageOfPath {

    /**
     * Returns the maximum average of any path that starts at the top‑left
     * cell (0,0) and ends at the bottom‑right cell (n‑1,n‑1) of the given
     * n×n cost matrix. Movement is allowed only to the right or down.
     *
     * @param cost a square list of lists representing the matrix
     * @param n    the dimension of the matrix (number of rows/columns)
     * @return the maximum average as a {@code Double}, or {@code null} if
     *         the input is invalid
     */
    public static Double maxAverageOfPath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] holds the greatest sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) +
                           Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // All paths from (0,0) to (n‑1,n‑1) have exactly (2n‑1) cells
        double maxSum = dp[n - 1][n - 1];
        double pathLength = 2 * n - 1;

        return maxSum / pathLength;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxAverageOfPath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxAverageOfPath(mat2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxAverageOfPath(mat3, 3)); // Expected: 7.2
    }
}

