class CountVowels {

    /**
     * Counts the consonants in the given string that have at least one
     * vowel (a, e, i, o, u) as an immediate neighbour (either to the left
     * or to the right).
     *
     * @param testStr the input string
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        // Empty or single‑character strings cannot have a vowel neighbour
        if (testStr == null || testStr.length() <= 1) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only count consonants (i.e. characters that are not vowels)
            if (!isVowel(ch)) {
                boolean hasVowelNeighbour = false;

                // Check left neighbour
                if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                    hasVowelNeighbour = true;
                }

                // Check right neighbour if we haven't already found a vowel neighbour
                if (!hasVowelNeighbour && i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                    hasVowelNeighbour = true;
                }

                if (hasVowelNeighbour) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Helper method that determines whether a given character is a vowel
     * (a, e, i, o, u). The check is case‑insensitive.
     *
     * @param c the character to test
     * @return true if c is a vowel, false otherwise
     */
    private static boolean isVowel(char c) {
        char lower = Character.toLowerCase(c);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u';
    }
}

