import java.lang.*;
import java.util.*;
import java.math.*;

public class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     * The NSW sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(i) = 2*a(i‑1) + a(i‑2)  for i ≥ 2.
     * The function returns a(n) if it is prime; otherwise it returns
     * the next prime in the sequence.
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The first two terms are 1 (not prime).  The function is not
        // defined for n = 0 or n = 1, so we return 1 as a placeholder.
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute a(n) using the recurrence.
        long a0 = 1;   // a(i‑2)
        long a1 = 1;   // a(i‑1)
        long a  = 0;   // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }

        // If a(n) is not prime, advance until we find a prime.
        while (!isPrime((int) a)) {
            long next = 2 * a1 + a0; // a(i+1)
            a0 = a1;
            a1 = next;
            a = next;
        }

        return (int) a;
    }

    /** Simple deterministic primality test for int values. */
    private static boolean isPrime(int num) {
        if (num <= 1) return false;
        if (num <= 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) return false;
        }
        return true;
    }

    // ---- Optional test harness -------------------------------------------------
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

