            if (token.length() < 3) {
                continue;
            }

            // Scan characters from index 1 up to length-2 (inclusive)
            // looking for a 'z' that is not at the start or the end.
            for (int i = 1; i <= token.length() - 2; i++) {
                if (token.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }

        // No suitable word was found
