class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * The sequence is defined as:
     *   a(1) = 1, a(2) = 3,
     *   a(k) = 2 * a(k‑1) + a(k‑2)  for k > 2.
     *
     * @param n 1‑based index (must be >= 1)
     * @return the n‑th element of the NSW sequence
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // First two base cases
        if (n == 1) return 1;
        if (n == 2) return 3;

        // prev2 = a(k‑2), prev1 = a(k‑1)
        long prev2 = 1; // a(1)
        long prev1 = 3; // a(2)
        long current = 0;

        // Compute a(3) … a(n)
        for (int i = 3; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }

        return (int) current;
    }

    // Simple manual test (not required by the task)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

