class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the input text contains a word that has the
     * letter 'z' somewhere other than the first or last position; otherwise
     * returns "Not matched!".
     *
     * @param text the input string to examine
     * @return a message indicating whether a matching word was found
     */
    public static String textMatchWordzMiddle(String text) {
        // Word = consecutive alphabetic characters
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();           // the actual word
            String lower = word.toLowerCase();       // case‑insensitive check

            // A 'z' can only be “in the middle” if the word is at least 3 chars long
            if (lower.length() >= 3) {
                int idx = lower.indexOf('z');
                while (idx != -1) {
                    // idx is the index of a 'z' in the original word (same in lower)
                    if (idx > 0 && idx < word.length() - 1) {
                        return "Found a match!";
                    }
                    // Look for the next occurrence of 'z' in the same word
                    idx = lower.indexOf('z', idx + 1);
                }
            }
        }
        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // Optional test harness (can be removed when integrating into a larger project)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));      // "Not matched!"
    }
}

import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum average value among all paths that start at the
     * top‑left cell and end at the bottom‑right cell of the given n×n matrix.
     * Movement is restricted to right or down steps only.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average (as a {@code Double}) of any valid path,
     *         or {@code null} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against empty or malformed input
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // dp[i][j] stores the maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The longest possible path contains exactly (2*n - 1) cells
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        return average;
    }
}

