class CountVowels {
    /**
     * Counts consonants that are adjacent to a vowel in the supplied string.
     *
     * @param testStr the input string (may be null or empty)
     * @return the number of consonants that have at least one vowel neighbor
     *
     * > countVowels("bestinstareels")          // 7
     * > countVowels("partofthejourneyistheend") // 12
     * > countVowels("amazonprime")             // 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set – both lower‑ and upper‑case
        final String VOWELS = "aeiouAEIOU";

        int count = 0;
        for (int i = 0; i < testStr.length(); i++) {
            char ch = testStr.charAt(i);

            // We only care about consonants (i.e. characters that are not vowels)
            if (VOWELS.indexOf(ch) == -1) {
                boolean hasVowelNeighbor = false;

                // Check the left neighbour
                if (i - 1 >= 0) {
                    char left = testStr.charAt(i - 1);
                    if (VOWELS.indexOf(left) != -1) {
                        hasVowelNeighbor = true;
                    }
                }

                // Check the right neighbour if we haven't already found a vowel neighbour
                if (!hasVowelNeighbor && i + 1 < testStr.length()) {
                    char right = testStr.charAt(i + 1);
                    if (VOWELS.indexOf(right) != -1) {
                        hasVowelNeighbor = true;
                    }
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

