class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a1 = 1, a2 = 3,
     *   an = 2 * a(n‑1) + a(n‑2)  for n > 2.
     *
     * @param n the index (1‑based) of the desired number
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // Handle the first two base cases
        if (n == 1) return 1;   // a1
        if (n == 2) return 3;   // a2

        // Iteratively compute the sequence using the recurrence
        int aMinus2 = 1; // a1
        int aMinus1 = 3; // a2
        int current = 0;

        for (int i = 3; i <= n; i++) {
            current = 2 * aMinus1 + aMinus2;
            // Shift the window for the next iteration
            aMinus2 = aMinus1;
            aMinus1 = current;
        }
        return current;
    }

    // Simple test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

