class TextMatchWordzMiddle {

    /**
     * Determines whether the supplied text contains a word that includes the
     * letter 'z' but not as the first or last character of that word.
     *
     * @param text the input string to be examined
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Defensive check for null input
        if (text == null) {
            return "Not matched!";
        }

        // Pattern explanation:
        // \b               – word boundary
        // [a-zA-Z]+        – one or more letters before the 'z'
        // z                – the letter 'z' (case‑insensitive)
        // [a-zA-Z]+        – one or more letters after the 'z'
        // \b               – word boundary
        // The requirement “not at the start or end” is satisfied because
        // there must be at least one letter on each side of 'z'.
        Pattern pattern = Pattern.compile("\\b[a-zA-Z]+z[a-zA-Z]+\\b", Pattern.CASE_INSENSITIVE);
        Matcher matcher = pattern.matcher(text);

        return matcher.find() ? "Found a match!" : "Not matched!";
    }

