/**
 * Solution for the “count characters that have vowels as neighbours” problem.
 *
 * <p>Examples:
 * <ul>
 *   <li>countVowels("bestinstareels") → 7</li>
 *   <li>countVowels("partofthejourneyistheend") → 12</li>
 *   <li>countVowels("amazonprime") → 5</li>
 * </ul>
 */
class CountVowels {

    /** Utility method that tells whether a given character is a vowel. */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i'
                || lower == 'o' || lower == 'u';
    }

    /**
     * Counts characters in {@code testStr} that are not vowels themselves
     * but have at least one vowel neighbour (immediately to the left or right).
     *
     * @param testStr the input string (may contain uppercase letters)
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int length = testStr.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            char current = testStr.charAt(i);

            // We only consider non‑vowel characters
            if (isVowel(current)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check the left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check the right neighbour (only if we haven't already found one)
            if (!hasVowelNeighbor && i < length - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Optional main method for quick manual testing
    public static void main(String[] args) {
