class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * For n >= 2 this number is a prime.
     *
     * > newmanPrime(3)  -> 7
     * > newmanPrime(4)  -> 17
     * > newmanPrime(5)  -> 41
     */
    public static int newmanPrime(int n) {
        // The first two values of the sequence are 1, 1
        if (n <= 1) {
            return 1;
        }

        // Use BigInteger to avoid overflow for moderately large n
        BigInteger a0 = BigInteger.ONE; // a_{i-2}
        BigInteger a1 = BigInteger.ONE; // a_{i-1}
        BigInteger cur = BigInteger.ZERO;

        for (int i = 2; i <= n; i++) {
            cur = a1.multiply(BigInteger.valueOf(2)).add(a0); // a_i = 2*a_{i-1} + a_{i-2}
            a0 = a1;
            a1 = cur;
        }

        // The result fits in an int for the usual test cases
        return cur.intValue();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

