import java.util.*;
import java.math.*;

class Maxaverageofpath {
    /**
     * Write a function to find a path with the maximum average over all existing
     * paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // The matrix is assumed to be n × n; use n as the dimension.
        final int N = n;

        // dp[j] – maximum sum to reach cell (i, j) in the current row.
        double[] dp = new double[N];

        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                double val = cost.get(i).get(j).doubleValue();

                if (i == 0 && j == 0) {
                    // Starting cell.
                    dp[j] = val;
                } else if (i == 0) {
                    // First row: can only come from the left.
                    dp[j] = dp[j - 1] + val;
                } else if (j == 0) {
                    // First column: can only come from above.
                    dp[j] = dp[j] + val;          // dp[0] still holds the value from the previous row.
                } else {
                    // General case: take the max of the cell above (dp[j] before update)
                    // and the cell to the left (dp[j‑1] after update), then add current value.
                    dp[j] = Math.max(dp[j], dp[j - 1]) + val;
                }
            }
        }

        // Maximum sum to reach the bottom‑right corner.
        double maxSum = dp[N - 1];

        // Average = sum / number of cells in the path (2*N‑1).
        double average = maxSum / (2 * N - 1);

        // Return as a Double object.
        return Double.valueOf(average);
    }
}

