class CountVowels {

    // Vowels we consider – lower‑case only (input is converted to lower‑case)
    private static final String VOWELS = "aeiou";

    /**
     * Counts consonants that have at least one vowel as a neighbour.
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty strings
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work in lower‑case to be case‑insensitive
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);

            // Skip vowels – we only count consonants
            if (isVowel(c)) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbor = false;
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour
            if (i < len - 1 && isVowel(s.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    /** Helper: true if ch is one of a, e, i, o, u */
    private static boolean isVowel(char ch) {
        return VOWELS.indexOf(ch) != -1;
    }

    // ------------------------------------------------------------------
    // Optional test driver (not required by the problem, but handy for verification)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

