class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2·a(n‑1) + a(n‑2)   for n ≥ 2
     *
     * @param n index of the desired term (0‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the first two base cases
        if (n == 0) return 1; // a(0)
        if (n == 1) return 1; // a(1)

        // Iterate using long to avoid overflow for moderate n
        long prev2 = 1; // a(i‑2)
        long prev1 = 1; // a(i‑1)
        long cur = 0;

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2; // a(i) = 2*a(i‑1) + a(i‑2)
            prev2 = prev1;
            prev1 = cur;
        }

        // The values fit in int for the expected input range
        return (int) cur;
    }

    // Optional simple test (can be removed when integrating into a larger codebase)
    public static void main(String[] args) {
        // Example usage:
        System.out.println(newmanPrime(3)); // → 7
        System.out.println(newmanPrime(4)); // → 17
        System.out.println(newmanPrime(5)); // → 41
    }
}

