import java.util.Arrays;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner, ends at the bottom‑right corner and may only move
     * right or down.
     *
     * @param cost square matrix of integers (size n×n)
     * @param n    dimension of the matrix
     * @return     maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive programming
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] – maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j)
                            + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1);   // denominator fits in int
        return average;
    }

    // -----------------------------------------------------------------
    // Optional test driver
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

