class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // Base cases: s(1) = 1, s(2) = 3
        if (n == 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }
        // Iteratively compute the nth term using the recurrence
        // s(i) = 2 * s(i-1) + s(i-2)
        int a = 1; // s(1)
        int b = 3; // s(2)
        int c = 0;
        for (int i = 3; i <= n; i++) {
            c = 2 * b + a;
            a = b;
            b = c;
        }
        return b;
    }
}

