class CountVowels {
    /**
     * Counts the characters in the given string that are not vowels
     * but have at least one vowel as an immediate neighbour.
     *
     * @param testStr the input string
     * @return the number of such characters
     *
     * Examples:
     * countVowels("bestinstareels")        → 7
     * countVowels("partofthejourneyistheend") → 12
     * countVowels("amazonprime")           → 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int length = testStr.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            char ch = testStr.charAt(i);

            // We only count consonants; vowels themselves are ignored.
            if (isVowel(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour if not already found a vowel neighbour
            if (!hasVowelNeighbor && i < length - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /** Helper method to determine whether a character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // -----------------------------------------------------------------
    // Optional main method for quick manual testing
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
