class NewmanPrime {
    /**
     * Returns the nth Newman-Shanks-Williams prime.
     * The sequence starts: 2, 3, 7, 17, 41, 239, 577, ...
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (n == 1) {
            return 2;
        }
        // We need the (n-1)th prime from the recurrence since 2 is handled separately.
        int target = n - 1;
        int count = 0;
        BigInteger aPrev = BigInteger.ONE; // a0 = 1
        BigInteger aPrev2 = BigInteger.ONE; // a1 = 1
        BigInteger aCurrent = null;
        for (int i = 2; ; i++) {
            aCurrent = aPrev.multiply(BigInteger.valueOf(2)).add(aPrev2);
            if (aCurrent.isProbablePrime(100)) {
                count++;
                if (count == target) {
                    // Assuming the result fits in int; for larger n, consider long or BigInteger.
                    return aCurrent.intValue();
                }
            }
            aPrev2 = aPrev;
            aPrev = aCurrent;
        }
    }
}

