class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Validate the input – a malformed matrix is a programming error, so use an unchecked exception.
        if (cost == null) {
            throw new IllegalArgumentException("Cost matrix cannot be null");
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException("Cost matrix must have " + n + " rows");
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Each row must have " + n + " columns");
            }
        }

        // DP[i][j] = maximum sum of a monotone (right/down) path from (0,0) to (i,j).
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);               // value of the current cell
                if (i == 0 && j == 0) {
                    dp[i][j] = val;                         // start cell
                } else {
                    long best = 0;
                    if (i > 0) best = Math.max(best, dp[i - 1][j]); // from above
                    if (j > 0) best = Math.max(best, dp[i][j - 1]); // from left
                    dp[i][j] = val + best;
                }
            }
        }

        // The path always contains (2*n‑1) cells (n‑1 moves right + n‑1 moves down + the start cell).
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);
        return average;
    }
}

