class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a1 = 1,
     *   a2 = 3,
     *   an = 2 * a(n‑1) + a(n‑2)   for n > 2
     *
     * @param n the 1‑based index of the desired number (must be > 0)
     * @return the n‑th NSW number
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // Base cases
        if (n == 1) return 1;   // a1
        if (n == 2) return 3;   // a2

        // Use long for intermediate values to avoid premature overflow
        long a1 = 1; // a(n‑2)
        long a2 = 3; // a(n‑1)
        long a  = 0; // a(n)

        for (int i = 3; i <= n; i++) {
            a  = 2 * a2 + a1; // compute next term
            a1 = a2;          // shift window
            a2 = a;
        }

        // The problem expects an int return type; cast safely
        return (int) a;
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        // Example tests from the problem statement
        System.out.println(newmanPrime(3)); // → 7
        System.out.println(newmanPrime(4)); // → 17
