class RectangleArea {

    /**
     * Computes the area of a rectangle.
     *
     * @param l length (must be > 0)
     * @param b breadth (must be > 0)
     * @return the area (l * b)
     * @throws InvalidRectangleDimensionException if either dimension is not positive
     *
     * <h3>Examples:</h3>
     * <pre>
     * rectangleArea(10, 20) → 200
     * rectangleArea(10, 5)  → 50
     * rectangleArea(4, 2)   → 8
     * </pre>
     */
    public static int rectangleArea(int l, int b) throws InvalidRectangleDimensionException {
        // Recoverable condition: non‑positive dimensions
        if (l <= 0 || b <= 0) {
            throw new InvalidRectangleDimensionException(
                    "Rectangle dimensions must be positive", l, b);
        }
        return l * b;
    }

    /**
     * Custom checked exception that conveys information about invalid rectangle
     * dimensions and supplies methods to help the caller recover.
     */
    public static class InvalidRectangleDimensionException extends Exception {

        private final int length;
        private final int breadth;

        public InvalidRectangleDimensionException(String message, int l, int b) {
            super(message);
            this.length = l;
            this.breadth = b;
        }

        /** Returns the invalid length that was passed. */
        public int getLength() {
            return length;
        }

        /** Returns the invalid breadth that was passed. */
        public int getBreadth() {
            return breadth;
        }

        /**
         * Suggests corrected dimensions (both forced to be at least 1).
         * The caller can use these values to recover from the exception.
         *
         * @return int array where index 0 is the suggested length, index 1 the suggested breadth
         */
        public int[] suggestedDimensions() {
            return new int[]{
                    Math.max(1, length),
                    Math.max(1, breadth)
            };
        }

        /**
         * Returns the total shortfall needed to make both dimensions positive.
         * For example, if length = -3 and breadth = 5, the shortfall is 3
         * (the amount to add to length to reach 1).
         *
         * @return sum of required increments to reach positive dimensions
         */
        public int getShortfall() {
            int shortfall = 0;
            if (length <= 0) shortfall += (1 - length);
            if (breadth <= 0) shortfall += (1 - breadth);
            return shortfall;
        }
    }
}

