class NewmanPrime {

    /**
     * Returns the n‑th number of the Newman‑Shanks‑Williams sequence.
     * The sequence is defined by:
     *   s0 = 1, s1 = 1
     *   sn = 2·sn‑1 + sn‑2   for n ≥ 2
     *
     * For n = 3 the method returns 7, for n = 4 it returns 17,
     * and for n = 5 it returns 41, exactly as required.
     *
     * @param n index of the desired NSW number (0‑based)
     * @return the NSW number at position n
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;   // s0 = s1 = 1
        }

        // Compute iteratively using long to avoid early overflow
        long prev2 = 1; // s0
        long prev1 = 1; // s1
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // sn = 2·sn‑1 + sn‑2
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int; we cast (the values fit in int for reasonable n)
        return (int) current;
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

