        // \w+  – one or more word characters (letter, digit, underscore)
        // z    – the literal 'z' (case‑insensitive)
        // \w+  – at least one character after the 'z' ensures it's not at the end
        // The leading \w+ also guarantees there is at least one character
        // before the 'z', so it can't be the first character of the word.
        Pattern pattern = Pattern.compile("\\b\\w+z\\w+\\b", Pattern.CASE_INSENSITIVE);
