import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner of the given square matrix and ends at the bottom‑right
     * corner.  Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of non‑negative integers
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}, or {@code null} if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // DP[i][j] holds the maximum sum of a path from (0,0) to (i,j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cur = cost.get(i).get(j);   // the cost of the current cell

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cur;
                } else {
                    double best = 0.0;
                    if (i > 0) {
                        best = dp[i - 1][j];          // came from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]); // came from left
                    }
                    dp[i][j] = cur + best;
                }
            }
        }

        // The path always contains exactly (2*n - 1) cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average; // auto‑boxed to Double
    }
}

