     *
     * @param number the number of terms (n)
     * @return the sum 1^2 + 2^2 + ... + n^2
     */
    public static int seriesSum(int number) {
        if (number <= 0) {
            return 0;
        }
        // Use long to avoid overflow, then cast to int.
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;
        return (int) sum;
    }

