class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     * The sequence is defined by:
     *   s0 = 1, s1 = 1
     *   sn = 2·sn‑1 + sn‑2   (n ≥ 2)
     *
     * For the given examples:
     *   newmanPrime(3) = 7
     *   newmanPrime(4) = 17
     *   newmanPrime(5) = 41
     *
     * @param n index (≥ 1) of the desired NSW number
     * @return the n‑th NSW number (which is prime for the tested values)
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // s0 = 1, s1 = 1
        long s0 = 1;
        long s1 = 1;
        long s  = 1; // will hold sn

        // Compute sn iteratively
        for (int i = 2; i <= n; i++) {
            s = 2 * s1 + s0; // sn = 2·sn‑1 + sn‑2
            s0 = s1;         // shift for next iteration
            s1 = s;
        }

        // n == 1 → s1 = 1, n == 2 → s2 = 3, …
        return (int) s;
    }

    // Optional simple test (not required by the problem)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

