import java.util.List;

/**
 * Computes the maximum average value of any monotonic (right‑down) path
 * from the top‑left corner to the bottom‑right corner of an n×n cost matrix.
 *
 * @param cost the n×n matrix of integer costs (must not be null, must be square)
 * @param n    the dimension of the matrix (must be > 0)
 * @return the maximum average as a {@code Double}
 * @throws NullPointerException     if {@code cost} or any of its rows is {@code null}
 * @throws IllegalArgumentException if {@code n} is not positive, the matrix
 *                                  is not square, or its size does not match {@code n}
 */
public class Maxaverageofpath {

    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- Input validation -------------------------------------------------
        if (cost == null) {
            throw new NullPointerException("Cost matrix cannot be null");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("Matrix dimension must be positive");
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException("Matrix size does not match the given n");
        }

        for (List<Integer> row : cost) {
            if (row == null) {
                throw new NullPointerException("Matrix row cannot be null");
            }
            if (row.size() != n) {
                throw new IllegalArgumentException("Matrix must be square and match the given n");
            }
        }

        // ---- DP: maximum sum to reach each cell --------------------------------
        double[] dp = new double[n];            // dp[j] = best sum for current row, column j
        dp[0] = cost.get(0).get(0);             // start cell

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[j] = dp[j - 1] + cost.get(0).get(j);
        }

        // remaining rows
        for (int i = 1; i < n; i++) {
            // first column – can only come from above
            dp[0] = dp[0] + cost.get(i).get(0);

            for (int j = 1; j < n; j++) {
                double fromAbove = dp[j];       // value from previous row, same column
                double fromLeft = dp[j - 1];    // value from current row, previous column
                dp[j] = cost.get(i).get(j) + Math.max(fromAbove, fromLeft);
            }
        }

        // ---- Compute average ---------------------------------------------------
        double maxSum = dp[n - 1];
        int pathLength = 2 * n - 1;   // any monotonic path from (0,0) to (n‑1,n‑1) has this many cells
        double average = maxSum / pathLength;

        // Auto‑boxing to Double
        return average;
    }

    // -----------------------------------------------------------------------
    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9));
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10));
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11));
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

