/**
 * Utility class for computing the sum of a series of squares.
 */
class SeriesSum {

    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms (must be a positive integer)
     * @return the sum of the squares from 1 to number
     * @throws IllegalArgumentException if {@code number} is less than 1
     */
    public static int seriesSum(int number) {
        // ---- Input validation ----
        if (number < 1) {
            throw new IllegalArgumentException(
                "Number must be a positive integer; got " + number);
        }

        // ---- Compute using the formula n(n+1)(2n+1)/6 ----
        // Use long to avoid overflow of intermediate products.
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;

        // The problem statement expects an int return; guard against overflow.
        if (sum > Integer.MAX_VALUE) {
            throw new IllegalArgumentException(
                "Result exceeds Integer.MAX_VALUE for n = " + number);
        }

        return (int) sum;
    }

    // ---- Simple test harness ----
    public static void main(String[] args) {
        int[] tests = {6, 7, 12};
        for (int n : tests) {
            System.out.println("seriesSum(" + n + ") = " + seriesSum(n));
        }
    }
}

