class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1,
     *   an = 2·a(n‑1) + a(n‑2)  for n ≥ 2.
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman–Shanks–Williams number
     * @throws IllegalArgumentException if n is negative or too large to fit in an int
     */
    public static int newmanPrime(int n) {
        // Validate the input – negative indices are not meaningful.
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The first two terms of the sequence are both 1.
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use long arithmetic to avoid intermediate overflow, then check the final range.
        long a0 = 1; // a(n‑2)
        long a1 = 1; // a(n‑1)
        long a = 0; // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            // Shift the window for the next iteration.
            a0 = a1;
            a1 = a;
        }

        // Ensure the result fits into an int; otherwise the caller gets misleading values.
        if (a > Integer.MAX_VALUE) {
            throw new IllegalArgumentException("n is too large; result exceeds Integer.MAX_VALUE");
        }

        return (int) a;
    }
}

class RemoveOdd {
    /**
     * Removes (i.e., discards) the characters at even positions,
