class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the supplied text contains the
     * letter 'z' somewhere other than the first or last position;
     * otherwise returns "Not matched!".
     *
     * @param text the input string (must not be null)
     * @return    the appropriate message
     * @throws IllegalArgumentException if text is null
     */
    public static String textMatchWordzMiddle(String text) {
        // Validate the argument – throw a standard exception for null input
        if (text == null) {
            throw new IllegalArgumentException("Input text must not be null");
        }

        // Pattern that matches whole words consisting of ASCII letters.
        // (Using \b for word boundaries; \w would also include digits & '_'.)
        Pattern wordPattern = Pattern.compile("\\b[A-Za-z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();           // the actual word
            if (containsZNotAtEdge(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * Helper that checks whether the given word contains the letter 'z'
     * (case‑insensitive) at a position that is neither the first nor the last.
     *
     * @param word a non‑empty word
     * @return true if such a 'z' exists, false otherwise
     */
    private static boolean containsZNotAtEdge(String word) {
        String lower = word.toLowerCase();           // make the check case‑insensitive
        // Examine every character except the first and last ones.
        for (int i = 1; i < lower.length() - 1; i++) {
            if (lower.charAt(i) == 'z') {
                return true;
            }
        }
        return false;
    }

    // Simple demo (not required for the solution, but useful for testing)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));     // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that starts at the top‑left
     * corner of the given n×n matrix and ends at the bottom‑right corner.
     * Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the size of the matrix (number of rows/columns)
     * @return the maximum average as a {@code Double}
     * @throws IllegalArgumentException if the matrix is null, not square,
     *                                   or any row has a different length
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation (reusing standard IllegalArgumentException) ----
        if (cost == null || n <= 0 || cost.size() != n) {
            throw new IllegalArgumentException("Cost matrix must be a non‑null square list of size n.");
        }
        for (List<Integer> row : cost) {
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Each row of the cost matrix must have exactly n elements.");
            }
        }

        // ---- DP table: dp[i][j] = maximum sum to reach cell (i, j) ----
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells – take the better of the two predecessor paths
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The path length from (0,0) to (n‑1,n‑1) when moving only right/down
        // is (2*n - 1) cells.
        double maxSum = dp[n - 1][n - 1];
        return maxSum / (2.0 * n - 1);
    }
}

class CountVowels {
    /** Vowel characters (lower‑case only – we case‑insensitive compare). */
    private static final String VOWELS = "aeiou";

    /**
     * Counts characters that are NOT vowels and that have at least one
     * adjacent vowel (either to the left or to the right).
     *
     * @param testStr the input string (may be empty, must not be {@code null})
     * @return the number of such characters
     * @throws IllegalArgumentException if {@code testStr} is {@code null}
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            // “Non‑null parameter value is inappropriate” → IllegalArgumentException
            throw new IllegalArgumentException("Input string must not be null");
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char c = testStr.charAt(i);
            if (isVowel(c)) {
                // We only count consonants, so skip vowels.
                continue;
            }

            // Check the left neighbour.
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                count++;
                continue;
            }

            // Check the right neighbour.
            if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                count++;
            }
        }
        return count;
    }

    /** Returns true if the given character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return VOWELS.indexOf(c) != -1;
    }
}

