public static int newmanPrime(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    if (n == 1) {
        return 1;
    }
    if (n == 2) {
        return 3;
    }
    int a = 1;
    int b = 3;
    for (int i = 3; i <= n; i++) {
        int c = 2 * b + a;
        a = b;
        b = c;
    }
    return b;
}

