class TextMatchWordzMiddle {

    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // ---- Exception translation (Item 73) ----
        // The lower‑level operation (String.split) can throw a NullPointerException
        // if the receiver is null.  We translate it to an IllegalArgumentException,
        // which is meaningful at the level of this method.
        try {
            // Validate the input – a null text is considered illegal.
            if (text == null) {
                throw new NullPointerException("text is null");
            }

            // Split the input into “words” using whitespace as delimiter.
            String[] words = text.split("\\s+");

            // Examine each word for a 'z' that is not the first or last character.
            for (String word : words) {
                int idx = word.indexOf('z');          // find first 'z' in this word
                while (idx != -1) {                   // while there is a 'z' somewhere
                    // Check that the 'z' is not at position 0 and not the last character.
                    if (idx > 0 && idx < word.length() - 1) {
                        return "Found a match!";
                    }
                    // Look for the next occurrence of 'z' in the same word.
                    idx = word.indexOf('z', idx + 1);
                }
            }

            // No suitable 'z' was found.
            return "Not matched!";

        } catch (NullPointerException e) {
            // Translate the lower‑level exception into a higher‑level one.
            throw new IllegalArgumentException("Input text must not be null", e);
        }
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
        System.out.println(textMatchWordzMiddle("  lang  ."));
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // Exception handling for null or invalid input
    if (cost == null) {
        throw new IllegalArgumentException("Cost matrix cannot be null");
    }
    if (cost.size() != n) {
        throw new IllegalArgumentException("Cost matrix size must be n x n");
    }

    // Initialize DP table
    double[][] dp = new double[n][n];

    // Fill the DP table
    for (int i = 0; i < n; i++) {
        if (cost.get(i) == null || cost.get(i).size() != n) {
            throw new IllegalArgumentException("Each row must have n elements");
        }
        for (int j = 0; j < n; j++) {
            if (i == 0 && j == 0) {
                dp[i][j] = cost.get(i).get(j);
            } else if (i == 0) {
                dp[i][j] = cost.get(i).get(j) + dp[i][j-1];
            } else if (j == 0) {
                dp[i][j] = cost.get(i).get(j) + dp[i-1][j];
            } else {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i-1][j], dp[i][j-1]);
            }
        }
    }

    // Return the maximum average
    return dp[n-1][n-1] / (2 * n - 1);
}

import java.util.Arrays;
