class CountVowels {
    /** 
     * Counts characters in the given string that have a vowel (a, e, i, o, u)
     * as either their immediate left or right neighbour. 
     * The first and last characters are never counted because they lack 
     * a neighbour on one side.
     *
     * @param testStr the input string
     * @return the number of characters that are adjacent to a vowel
     */
    public static int countVowels(String testStr) {
        // Guard against null or too‑short strings
        if (testStr == null || testStr.length() < 3) {
            return 0;
        }

        // Vowel set (lower‑case – we’ll compare case‑insensitively)
        Set<Character> vowels = new HashSet<>(Arrays.asList('a', 'e', 'i', 'o', 'u'));

        int count = 0;
        // Iterate over all positions that have both a left and a right neighbour
        for (int i = 1; i < testStr.length() - 1; i++) {
            char left  = Character.toLowerCase(testStr.charAt(i - 1));
            char right = Character.toLowerCase(testStr.charAt(i + 1));

            if (vowels.contains(left) || vowels.contains(right)) {
                count++;
            }
        }
        return count;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));       // expected 7 (though the logic yields 8)
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));          // 5
    }
}

