/**
 * Utility class for computing the sum of squares of the first n natural numbers.
 */
class SeriesSum {

    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms in the series (must be non‑negative)
     * @return the sum of squares of the first {@code number} positive integers
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        // Guard against invalid input – a negative n does not make sense for this series.
        if (number < 0) {
            throw new IllegalArgumentException("Number must be non‑negative");
        }

        // The sum of squares 1² + 2² + … + n² = n(n+1)(2n+1) / 6.
        // Using long intermediate arithmetic prevents overflow for moderate n.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;   // The problem statement expects an int return type.
    }

    // A tiny demo (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12)); // 650
    }
}

