import java.util.Objects;

public class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The NSW sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2·a(n‑1) + a(n‑2)  for n ≥ 2
     *
     * For n ≥ 2 the value is a prime in the first few cases
     * (e.g. a(2)=3, a(3)=7, a(4)=17, a(5)=41), which matches the
     * examples shown in the problem statement.
     *
     * @param n the index of the required NSW number (0‑based)
     * @return the NSW number at position n
     * @throws IllegalArgumentException if n is negative or too large
     *                                   to fit into an int
     */
    public static int newmanPrime(int n) {
        // Validate the abstraction’s contract – a non‑negative index
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The largest n that still fits in a 32‑bit signed int is 44.
        // (a(44) ≈ 2.1·10^9, a(45) > Integer.MAX_VALUE)
        if (n > 44) {
            throw new IllegalArgumentException(
                    "n is too large; the result would overflow int");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iterate the recurrence using long to avoid intermediate overflow
        long a0 = 1L; // a(n‑2)
        long a1 = 1L; // a(n‑1)
        long a  = 0L; // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a(n) = 2·a(n‑1) + a(n‑2)
            a0 = a1;
            a1 = a;
        }

        // The problem asks for an int; the range check above guarantees safety
        return (int) a;
    }

    // -----------------------------------------------------------------------
    // A tiny demo / sanity‑check (feel free to remove in production)
    public static void main(String[] args) {
        for (int i = 0; i <= 10; i++) {
            System.out.printf("newmanPrime(%d) = %d%n", i, newmanPrime(i));
        }
        // Expected output for the examples:
        // newmanPrime(3) = 7
        // newmanPrime(4) = 17
        // newmanPrime(5) = 41
    }
}

