/**
 * Utility class for computing the volume of a regular tetrahedron.
 *
 * The volume V of a regular tetrahedron with edge length a is:
 *     V = a³ / (6·√2)
 *
 * Example values:
 *   a = 10 → V ≈ 117.85
 *   a = 15 → V ≈ 397.75
 *   a = 20 → V ≈ 942.81
 */
public class VolumeTetrahedron {

    /**
     * Calculates the volume of a regular tetrahedron for the given edge length.
     *
     * @param num the length of each edge (must be positive)
     * @return the volume as a {@code Double}
     * @throws IllegalArgumentException if {@code num} is not positive
     */
    public static Double volumeTetrahedron(int num) {
        // Validate the input – throw an exception appropriate to this abstraction
        if (num <= 0) {
            throw new IllegalArgumentException("Edge length must be positive: " + num);
        }

        // Edge length cast to double for the arithmetic
        double a = num;

        // Compute the volume using the regular tetrahedron formula
        double volume = (a * a * a) / (6.0 * Math.sqrt(2.0));

        // Return the result as a boxed Double (as required by the method signature)
        return Double.valueOf(volume);
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

