public class TextMatchWordzMiddle {
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            throw new IllegalArgumentException("Input text must not be null");
        }

        // Pattern to match words consisting of one or more letters
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            String lower = word.toLowerCase();
            int len = lower.length();

            // Need at least three characters to have a middle character
            if (len >= 3) {
                // Check each character except the first and last
                for (int i = 1; i < len - 1; i++) {
                    if (lower.charAt(i) == 'z') {
                        return "Found a match!";
                    }
                }
            }
        }

        return "Not matched!";
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of all paths that go from the top‑left
     * cell (0,0) to the bottom‑right cell (n‑1,n‑1) in the given n×n matrix.
     * Movement is restricted to rightward or downward steps.
     *
     * @param cost the n×n matrix of path costs (List of rows, each row a List of Integers)
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}
     * @throws IllegalArgumentException if {@code cost} is null, not square,
     *                                  or any row has the wrong size
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- Input validation -------------------------------------------------
        if (cost == null) {
            throw new IllegalArgumentException("Input cost matrix must not be null.");
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException(
                    "Number of rows (" + cost.size() + ") does not match the given n (" + n + ").");
        }

        // Build a 2‑D int array for fast random access; also validate each row length.
        int[][] matrix = new int[n][n];
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException(
                        "Row " + i + " is null or does not have " + n + " columns.");
            }
            for (int j = 0; j < n; j++) {
                matrix[i][j] = row.get(j);   // may throw IndexOutOfBoundsException – translate below
            }
        }

        // ---- Dynamic programming: maximum sum to each cell --------------------
        long[][] dp = new long[n][n];
        dp[0][0] = matrix[0][0];

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + matrix[0][j];
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + matrix[i][0];
        }

        // Remaining cells: take the maximum of the two possible predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = matrix[i][j] + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;               // number of cells visited on any valid path
        double average = (double) maxSum / pathLength;

        return Double.valueOf(average);
    }

    // ---------------------------------------------------------------------------
    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9));
        System.out.println(maxaverageofpath(m1, 3)); // expected 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10));
        System.out.println(maxaverageofpath(m2, 3)); // expected 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11));
        System.out.println(maxaverageofpath(m3, 3)); // expected 7.2
    }
}

