class NewmanPrime {
    /**
     * Returns the n-th Newman–Shanks–Williams prime number.
     * <p>
     * The sequence is defined by {@code a(0) = 1, a(1) = 1} and
     * {@code a(i) = 2 * a(i-1) + a(i-2)} for {@code i >= 2}.
     * For {@code n >= 2} the returned value is a prime.
     *
     * @param n the index (1‑based) of the Newman–Shanks–Williams sequence
     * @return the n‑th term of the sequence
     * @throws IllegalArgumentException if {@code n <= 0}
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        long a0 = 1; // a(i-2)
        long a1 = 1; // a(i-1)
        long a = 1;  // a(i)
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }
}

