/**
 * Utility class for computing the volume of a regular tetrahedron.
 *
 * The volume of a regular tetrahedron with edge length a is given by
 * V = a³ / (6·√2).  This method returns the volume rounded to two
 * decimal places.
 */
public class VolumeTetrahedron {

    /**
     * Calculates the volume of a regular tetrahedron with the given edge length.
     *
     * @param num the length of each edge of the regular tetrahedron (must be positive)
     * @return the volume of the tetrahedron, rounded to two decimal places
     * @throws IllegalArgumentException if {@code num} is not positive
     */
    public static Double volumeTetrahedron(int num) {
        // Precondition check – IllegalArgumentException is an unchecked exception
        if (num <= 0) {
            throw new IllegalArgumentException("Edge length must be positive");
        }

        // Volume formula for a regular tetrahedron: V = a^3 / (6 * sqrt(2))
        double volume = (Math.pow(num, 3)) / (6.0 * Math.sqrt(2));

        // Round to two decimal places
        double roundedVolume = Math.round(volume * 100.0) / 100.0;

        return roundedVolume;
    }

    // Simple test (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
