        java.util.regex.Pattern wordPattern =
                java.util.regex.Pattern.compile("[a-zA-Z]+");
        java.util.regex.Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // A 'z' can only be in the middle if the word has at least 3 characters
            for (int i = 1; i < word.length() - 1; i++) {
                char ch = word.charAt(i);
                if (ch == 'z' || ch == 'Z') {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }
}

import java.util.List;

/**
 * Computes the maximum average of all possible paths from the top‑left corner
 * to the bottom‑right corner of a square matrix.  A path may only move
 * right or down, and its average equals the sum of the visited cell values
 * divided by the number of visited cells (2·n − 1).
 *
 * <p>Example:
 * <pre>
 * List&lt;List&lt;Integer&gt;&gt; cost = List.of(
 *     List.of(1, 2, 3),
 *     List.of(6, 5, 4),
 *     List.of(7, 3, 9)
 * );
 * Double result = Maxaverageofpath.maxaverageofpath(cost, 3); // → 5.2
 * </pre>
 *
 * @param cost the n × n matrix of integer costs (must not be {@code null})
 * @param n    the dimension of the square matrix (must be positive)
 * @return     the maximum possible average as a {@code Double}
 * @throws IllegalArgumentException if {@code n} is not positive,
 *                                  or if {@code cost} is not a valid n × n matrix
 * @throws NullPointerException     if {@code cost} or any of its rows is {@code null}
 */
public class Maxaverageofpath {

    /**
     * Returns the maximum average of a right‑down path from (0,0) to (n‑1,n‑1).
     *
     * @param cost the cost matrix
     * @param n    matrix dimension
     * @return maximum average
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- validation ----------------------------------------------------
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (cost == null) {
            throw new NullPointerException("cost matrix must not be null");
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException("cost matrix must have exactly " + n + " rows");
        }
        for (int i = 0; i < n; ++i) {
            List<Integer> row = cost.get(i);
            if (row == null) {
                throw new NullPointerException("Row " + i + " of cost matrix is null");
            }
            if (row.size() != n) {
                throw new IllegalArgumentException("Row " + i + " must have exactly " + n + " columns");
            }
        }

        // ---- dynamic programming (only right/down moves) -------------------
        // dp[j] holds the best sum to reach cell (current row, column j)
        double[] dp = new double[n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int val = cost.get(i).get(j);           // the cost of the current cell
                if (i == 0 && j == 0) {
                    // start cell
                    dp[j] = val;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[j] = dp[j - 1] + val;
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[j] = dp[j] + val;   // dp[j] still contains the value from the previous row
                } else {
                    // interior cell – take the better of the top or left neighbour
                    dp[j] = val + Math.max(dp[j], dp[j - 1]);
                }
            }
        }

        // The total number of cells visited on any right‑down path is 2*n‑1
        double maxSum = dp[n - 1];
        double average = maxSum / (2L * n - 1);

        return average; // auto‑boxed to Double
    }

    // -----------------------------------------------------------------------
    // Optional test harness (can be removed when the method is used elsewhere)
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

public static int countVowels(String testStr) {
    // null check
    if (testStr == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    final String vowels = "aeiouAEIOU";
    int count = 0;
    int len = testStr.length();

    for (int i = 0; i < len; i++) {
        char ch = testStr.charAt(i);
        // skip vowels themselves
        if (vowels.indexOf(ch) != -1) {
            continue;
        }

        boolean hasVowelNeighbor = false;
        if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
            hasVowelNeighbor = true;
        }
        if (i < len - 1 && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
            hasVowelNeighbor = true;
        }

        if (hasVowelNeighbor) {
            count++;
        }
    }
    return count;
}

