class SeriesSum {
    /**
     * Calculates the sum of the squares of the first {@code number} positive integers:
     * 1² + 2² + 3² + … + {@code number}².
     *
     * @param number the number of terms in the series (must be non‑negative)
     * @return the sum of squares of the first {@code number} natural numbers
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative");
        }

        // Use long for the intermediate computation to avoid overflow.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The problem statement expects an int return type.
        return (int) sum;
    }
}

