/**
 * Utility class for computing Newman‑Shanks‑Williams numbers.
 */
class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams (NSW) number.
     *
     * <p>The NSW sequence is defined by:
     * <ul>
     *   <li>S₀ = 1</li>
     *   <li>S₁ = 1</li>
     *   <li>Sₙ = 2·Sₙ₋₁ + Sₙ₋₂ for n ≥ 2</li>
     * </ul>
     *
     * <p>This method returns Sₙ.
     *
     * @param n the index of the NSW number to return; must be non‑negative
     * @return the n‑th NSW number
     * @throws IllegalArgumentException if {@code n} is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // S0 and S1 are both 1
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use long arithmetic to avoid overflow while computing the sequence
        long prev2 = 1L; // S_{i-2}
        long prev1 = 1L; // S_{i-1}
        long current = 0L;

        for (int i = 2; i <= n; i++) {
            current = 2L * prev1 + prev2;
            // shift the window for the next iteration
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int return; for the typical range of n this fits.
        return (int) current;
    }

    // -----------------------------------------------------------------
    // Optional test driver (uncomment to run)
    // -----------------------------------------------------------------
    // public static void main(String[] args) {
    //     for (int i = 2; i <= 10; i++) {
    //         System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
    //     }
    // }
}

