class RemoveOdd {
    /**
     * Removes characters at even positions (i.e., characters with even indices)
     * from the given string.
     *
     * <p>For example, {@code removeOdd("python")} returns {@code "yhn"}.</p>
     *
     * @param str1 the input string; must not be {@code null}
     * @return a new string containing the characters of {@code str1} that are
     *         located at odd indices (1, 3, 5, ...)
     * @throws NullPointerException if {@code str1} is {@code null}
     */
    public static String removeOdd(String str1) {
        if (str1 == null) {
            throw new NullPointerException("str1 cannot be null");
        }
        StringBuilder result = new StringBuilder();
        // Start from index 1 (the second character) and keep every second character.
        for (int i = 1; i < str1.length(); i += 2) {
            result.append(str1.charAt(i));
        }
        return result.toString();
    }
