class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron whose side length is {@code num}.
     *
     * The volume of a regular tetrahedron with side length a is given by
     * V = a³ / (6·√2).
     *
     * @param num the length of each side of the tetrahedron (must be > 0)
     * @return the volume of the tetrahedron, rounded to two decimal places
     * @throws IllegalArgumentException if {@code num} is less than or equal to zero
     */
    public static Double volumeTetrahedron(int num) {
        if (num <= 0) {
            throw new IllegalArgumentException("Side length must be positive");
        }

        // V = a³ / (6 * sqrt(2))
        double volume = (Math.pow(num, 3)) / (6.0 * Math.sqrt(2));

        // Round to two decimal places to match the example output
        volume = Math.round(volume * 100.0) / 100.0;

        return Double.valueOf(volume);
    }
}

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * <p>
 * Determines whether the supplied text contains a word that includes the
 * character <code>'z'</code> somewhere other than as the first or last
 * character of that word.
 * </p>
 *
 * <p>Examples:</p>
 * <ul>
 *   <li>{@code textMatchWordzMiddle("pythonzabc.") → "Found a match!"}</li>
 *   <li>{@code textMatchWordzMiddle("xyzabc.")   → "Found a match!"}</li>
 *   <li>{@code textMatchWordzMiddle("  lang  .") → "Not matched!"}</li>
 * </ul>
 *
 * @param text the input string to be examined
 * @return     "Found a match!" if such a word exists, otherwise "Not matched!"
 * @throws NullPointerException if {@code text} is {@code null}
 */
public class TextMatchWordzMiddle {

    /**
     * Scans the input for words that contain a 'z' (or 'Z') that is not the
     * first or last character of the word.
     *
     * @param text the string to search
     * @return     "Found a match!" if a suitable word is found,
     *             "Not matched!" otherwise
     * @throws NullPointerException if {@code text} is {@code null}
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            throw new NullPointerException("Input text cannot be null");
        }

        // Word = consecutive letters (a‑z or A‑Z).  Punctuation, spaces, digits, etc.
        // act as delimiters.
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            if (hasMiddleZ(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * Checks whether the given word contains a 'z' (lower‑case or upper‑case)
     * at a position that is neither the first nor the last character.
     *
     * @param word the word to examine
     * @return     {@code true} if such a 'z' exists, {@code false} otherwise
     */
    private static boolean hasMiddleZ(String word) {
        // A word shorter than three characters cannot have a middle character.
        if (word.length() < 3) {
            return false;
        }
        // Examine all positions except the first (index 0) and the last (index length‑1).
        for (int i = 1; i < word.length() - 1; i++) {
            char ch = word.charAt(i);
            if (ch == 'z' || ch == 'Z') {
                return true;
            }
        }
        return false;
    }

    /** Simple test driver (optional). */
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
        System.out.println(textMatchWordzMiddle("  lang  ."));
    }
}

import java.util.List;

/**
 * <p>
 * Utility class for computing the maximum average of a path in a square
 * matrix.  A path starts at the upper‑left cell (0, 0) and ends at the
 * bottom‑right cell (n‑1, n‑1).  From any cell you may move only
 * <strong>right</strong> or <strong>down</strong>.  All such paths contain
 * exactly {@code 2*n‑1} cells, therefore maximizing the sum also maximizes
 * the average.
 * </p>
 *
 * <p>
 * Example: for the 3×3 matrix
 * <pre>
 * [[1, 2, 3],
 *  [6, 5, 4],
 *  [7, 3, 9]]
 * </pre>
 * the path that yields the maximum average is
 * down → down → right → right (1 + 6 + 7 + 3 + 9 = 26) giving an average of
 * 26 / 5 = 5.2.
 * </p>
 *
 * @author  (your name)
 * @version 1.0
 */
public class Maxaverageofpath {

    /**
     * Computes the maximum possible average of a path that travels from the
     * top‑left corner to the bottom‑right corner of the given {@code n × n}
     * cost matrix, moving only right or down.
     *
     * @param cost a square list of integer lists representing the matrix.
     *             The outer list must contain exactly {@code n} rows and each
     *             row must contain exactly {@code n} elements.
     * @param n    the dimension of the square matrix (must be positive).
     * @return     a {@code Double} that is the highest average among all
     *             valid paths.  The value is rounded as a normal double.
     * @throws NullPointerException     if {@code cost} is {@code null} or any
     *                                  of its row lists are {@code null}.
     * @throws IllegalArgumentException if {@code n <= 0}, or the outer list
     *                                  size differs from {@code n}, or any
     *                                  row size differs from {@code n}.
     * @throws IndexOutOfBoundsException if the matrix entries are accessed
     *                                  with invalid indices (indicates a bug
     *                                  in the caller).
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- precondition checks ---------------------------------------
        if (cost == null) {
            throw new NullPointerException("The cost list must not be null.");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer.");
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException(
                    "The outer list must contain exactly n rows.");
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null) {
                throw new NullPointerException(
                        "Row " + i + " is null.");
            }
            if (row.size() != n) {
                throw new IllegalArgumentException(
                        "Row " + i + " does not contain n elements.");
            }
        }

        // ---- dynamic programming for maximum path sum -----------------
        // dp[i][j] = maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells – take the better of the two predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                double best = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = best + cost.get(i).get(j);
            }
        }

        // ---- compute average -------------------------------------------
        // Every path has exactly (2*n - 1) cells.
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1);

        return average;
    }

    // --------------------------------------------------------------------
    // Optional simple test driver (not required by the task)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9));
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10));
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11));
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

