class CountVowels {
    /**
     * Counts the consonants in the given string that have at least one vowel
     * as an immediate neighbor (to the left or right).
     *
     * <p>Examples:
     * <ul>
     *   <li>{@code countVowels("bestinstareels")} returns {@code 7}</li>
     *   <li>{@code countVowels("partofthejourneyistheend")} returns {@code 12}</li>
     *   <li>{@code countVowels("amazonprime")} returns {@code 5}</li>
     * </ul>
     * </p>
     *
     * @param testStr the input string to evaluate
     * @return the number of consonants that are adjacent to a vowel
     * @throws NullPointerException if {@code testStr} is {@code null}
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            throw new NullPointerException("Input string cannot be null");
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            if (isVowel(ch)) {
                // Vowels are not counted; skip them.
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbor
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbor if not already found
            if (!hasVowelNeighbor && i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    /**
     * Determines whether a given character is a vowel (a, e, i, o, u) regardless of case.
     *
     * @param ch the character to check
     * @return {@code true} if the character is a vowel, {@code false} otherwise
     */
    private static boolean isVowel(char ch) {
        return "aeiouAEIOU".indexOf(ch) >= 0;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

