import java.util.*;
import java.math.*;

/**
 * A utility class for computing the sum of a series.
 */
public class SeriesSum {

    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * <p>The formula used is:
     * <blockquote>
     *   S(n) = n·(n + 1)·(2n + 1) / 6
     * </blockquote>
     *
     * @param number the number of terms in the series (must be non‑negative)
     * @return the sum of the squares of the first {@code number} natural numbers
     * @throws IllegalArgumentException if {@code number} is negative
     * @throws ArithmeticException      if the result overflows an {@code int}
     *                                   (i.e., when {@code number} is large enough
     *                                   that the true mathematical result exceeds
     *                                   {@link Integer#MAX_VALUE})
     */
    public static int seriesSum(int number) {
        if (number < 0) {
            throw new IllegalArgumentException(
                    "number must be non‑negative, but was " + number);
        }

        // Use long to avoid intermediate overflow, then cast back to int.
        // The cast may overflow for very large n; the JVM will throw
        // ArithmeticException when the cast narrows a value that does not fit.
        long result = (long) number * (number + 1) * (2L * number + 1) / 6;

        // Explicit overflow check – this guarantees an ArithmeticException
        // is thrown exactly when the true result does not fit in an int.
        if (result > Integer.MAX_VALUE || result < Integer.MIN_VALUE) {
            throw new ArithmeticException(
                    "Overflow: the sum of squares for n=" + number +
                    " exceeds Integer.MAX_VALUE");
        }

        return (int) result;
    }

    // -----------------------------------------------------------------
    // Optional test driver (not required by the problem statement)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        int[] tests = {6, 7, 12, 0, 1, 100};
        for (int n : tests) {
            System.out.printf("seriesSum(%d) = %d%n", n, seriesSum(n));
        }
    }
}

