/**
 * Utility class for computing Newman–Shanks–Williams numbers.
 */
class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1,  a(1) = 1,
     *   a(i) = 2·a(i‑1) + a(i‑2)  for i ≥ 2.
     *
     * @param n the index of the sequence (0‑based)
     * @return the value a(n)
     * @throws IllegalArgumentException if n is negative or if the result
     *         does not fit into a 32‑bit signed integer
     */
    public static int newmanPrime(int n) {
        // ---- Input validation ----
        if (n < 0) {
            // Detail message captures the exact input that caused the failure
            throw new IllegalArgumentException(
                "n must be non‑negative, but got " + n);
        }

        // ---- Base cases ----
        if (n == 0 || n == 1) {
            return 1;   // a(0) = a(1) = 1
        }

        // ---- Compute a(n) using BigInteger to avoid intermediate overflow ----
        BigInteger a0 = BigInteger.ONE; // a(i‑2)
        BigInteger a1 = BigInteger.ONE; // a(i‑1)
        BigInteger a  = BigInteger.ZERO; // a(i)

        for (int i = 2; i <= n; i++) {
            a = a0.multiply(BigInteger.TWO).add(a1); // a(i) = 2·a(i‑1) + a(i‑2)
            a1 = a0;
            a0 = a;
        }

        // ---- Ensure the result fits into an int ----
        if (a.compareTo(BigInteger.valueOf(Integer.MAX_VALUE)) > 0) {
            // Detail message includes both the offending n and the computed value
            throw new IllegalArgumentException(
                "n is too large: n=" + n + " yields " + a +
                " which exceeds Integer.MAX_VALUE");
        }

        // ---- Return the result as an int ----
        return a.intValue();
    }
}

