/**
 * Utility class that demonstrates matching a word that contains the letter
 * 'z' (case‑insensitive) somewhere *inside* the word – i.e. not as the first
 * or last character.
 *
 * The method returns "Found a match!" when such a word is found,
 * otherwise it returns "Not matched!".
 */
class TextMatchWordzMiddle {

    /**
     * Checks whether the given text contains a word that has the letter 'z'
     * (or 'Z') neither at the start nor at the end of the word.
     *
     * @param text the input string to examine
     * @return "Found a match!" if a suitable word exists, otherwise "Not matched!"
     * @throws IllegalArgumentException if {@code text} is {@code null};
     *         the exception's detail message captures the failure for later analysis.
     */
    public static String textMatchWordzMiddle(String text) {
        // ---- failure‑capture: null input ------------------------------------
        if (text == null) {
            // Detail message includes the fact that the input is null,
            // which is essential for debugging.
            throw new IllegalArgumentException("Input text is null");
        }

        StringBuilder currentWord = new StringBuilder();

        // Scan the string, treating sequences of letters as words.
        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);

            if (Character.isLetter(ch)) {
                // Build the current word.
                currentWord.append(ch);
            } else {
                // Encountered a non‑letter delimiter – evaluate the word we've built.
                if (currentWord.length() > 0) {
                    if (containsZInside(currentWord.toString())) {
                        return "Found a match!";
                    }
                    // Reset for the next word.
                    currentWord.setLength(0);
                }
            }
        }

        // Don't forget the last word (if the string ends with a letter).
        if (currentWord.length() > 0) {
            if (containsZInside(currentWord.toString())) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    /**
     * Helper that returns {@code true} if the given word contains the letter
     * 'z' (case‑insensitive) somewhere other than the first or last position.
     *
     * @param word a non‑empty word consisting only of letters
     * @return {@code true} if the word meets the “z‑inside” condition
     */
    private static boolean containsZInside(String word) {
        String lower = word.toLowerCase();          // case‑insensitive check
        if (!lower.contains("z")) {
            return false;                            // no 'z' at all
        }
        // The 'z' must not be the first or the last character.
        return !lower.startsWith("z") && !lower.endsWith("z");
    }

    // -----------------------------------------------------------------------
    // Example usage (you can remove or comment out this main method if not needed)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

import java.util.*;

class Maxaverageofpath {

    /**
     * Returns the maximum average of a path from the top‑left corner to the
     * bottom‑right corner of the given n×n cost matrix.  Movement is allowed
     * only to the right or down.
     *
     * @param cost the n×n matrix of integer costs (List of rows)
     * @param n    the dimension of the square matrix
     * @return the maximum average (as a {@code Double}) over all valid paths
     * @throws IllegalArgumentException if the input is inconsistent or invalid;
     *         the exception’s detail message contains the values that caused the
     *         failure (n, matrix size, row sizes, etc.) for later analysis.
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {

        // ---------- Input validation with rich failure‑capture ----------
        if (cost == null) {
            throw new IllegalArgumentException(
                "Cost matrix is null. Provided n = " + n);
        }
        if (n <= 0) {
            throw new IllegalArgumentException(
                "Invalid matrix dimension: n = " + n + ". n must be positive.");
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException(
                "Matrix size mismatch: n = " + n + " but cost.size() = " + cost.size());
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null) {
                throw new IllegalArgumentException(
                    "Row " + i + " is null. n = " + n);
            }
            if (row.size() != n) {
                throw new IllegalArgumentException(
                    "Row " + i + " size mismatch: expected " + n + " but got " + row.size()
                    + ". n = " + n);
            }
        }

        // ---------- DP: maximum sum from (0,0) to each cell ----------
        double[][] dp = new double[n][n];
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells – take the better of the two predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                double best = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = best + cost.get(i).get(j);
            }
        }

        // Every path from (0,0) to (n‑1,n‑1) contains exactly 2*n‑1 cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;               // auto‑boxed to Double
    }

    // ---------- Simple test driver ----------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

import java.util.Set;

class CountVowels {

    /** 
     * Vowel set – both lower‑ and upper‑case.
     */
    private static final Set<Character> VOWELS = Set.of(
            'a', 'e', 'i', 'o', 'u',
            'A', 'E', 'I', 'O', 'U'
    );

    /**
     * Counts characters that are consonants and have at least one vowel
     * as a neighbour (left or right).  The first and last characters are
     * considered to have only the single existing neighbour.
     *
     * @param testStr the input string (may not be {@code null})
     * @return the number of such consonants
     * @throws IllegalArgumentException if {@code testStr} is {@code null}
     */
    public static int countVowels(String testStr) {
        // ---- failure‑capture (Item 75) ----
        if (testStr == null) {
            throw new IllegalArgumentException(
                    "CountVowels input string is null");
        }

        int length = testStr.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            char ch = testStr.charAt(i);

            // only consider actual letters that are not vowels
            if (Character.isLetter(ch) && !isVowel(ch)) {
                boolean hasVowelNeighbor = false;

                // check left neighbour
                if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // check right neighbour (if left wasn't a vowel)
                if (!hasVowelNeighbor && i < length - 1 && isVowel(testStr.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    /** 
     * Returns true if the given character is a vowel (a, e, i, o, u) 
     * regardless of case. 
     */
    private static boolean isVowel(char ch) {
        return VOWELS.contains(Character.toLowerCase(ch));
    }

    // -----------------------------------------------------------------
    // Optional test driver
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

