class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n (must be non‑negative)
     * @return the sum of squares from 1 to n
     * @throws IllegalArgumentException if number is negative
     */
    public static int seriesSum(int number) {
        // Validate the input – capture the failing value in the detail message
        if (number < 0) {
            throw new IllegalArgumentException(
                "Series sum undefined for negative number: " + number);
        }

        // Use the closed‑form formula n(n+1)(2n+1)/6 to avoid O(n) iteration.
        // long is used for the intermediate computation to prevent overflow.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The problem statement expects an int return type; assume the result fits.
        return (int) sum;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12)); // 650
    }
}

