/**
 * Computes the n‑th Newman‑Shanks‑Williams number (sometimes called a “Newman prime”).
 *
 * The sequence is defined by:
 *   a(0) = 1, a(1) = 1
 *   a(n) = 2·a(n‑1) + a(n‑2)   for n ≥ 2
 *
 * The function expects a positive index n (1‑based):
 *   newmanPrime(1) → 1
 *   newmanPrime(2) → 3
 *   newmanPrime(3) → 7
 *   …
 *
 * @param n the index of the desired Newman‑Shanks‑Williams number (must be > 0)
 * @return the value of the n‑th Newman‑Shanks‑Williams number
 * @throws IllegalArgumentException if n is not positive, with the invalid value in the message
 */
public static int newmanPrime(int n) {
    // ---- failure‑capture information (Item 75) ----
    if (n <= 0) {
        throw new IllegalArgumentException(
            String.format("n must be positive, but got %d", n));
    }

    // Base cases (1‑based indexing)
    if (n == 1) return 1;   // a(1) = 1
    if (n == 2) return 3;   // a(2) = 2·a(1) + a(0) = 3

    // Iterative computation using long to avoid early overflow.
    // The recurrence fits easily into a long for the typical range of n.
    long aPrev2 = 1;   // a(1)
    long aPrev1 = 3;   // a(2)
    long current = 0;

    for (int i = 3; i <= n; i++) {
        current = 2 * aPrev1 + aPrev2; // a(i) = 2·a(i‑1) + a(i‑2)
        aPrev2 = aPrev1;
        aPrev1 = current;
    }

    // The problem’s signature declares a return type of int.
    // For reasonably small n the result fits; otherwise the cast may overflow.
    return (int) current;
}

