class VolumeTetrahedron {

    /**
     * Calculates the volume of a regular tetrahedron whose side length is {@code num}.
     *
     * The volume V of a regular tetrahedron with side a is:
     *     V = a³ / (6·√2)
     *
     * @param num the side length of the tetrahedron (must be positive)
     * @return the volume, rounded to two decimal places
     * @throws IllegalArgumentException if {@code num} is not positive
     */
    public static Double volumeTetrahedron(int num) {
        // ---- Input validation (Item 75) ----
        if (num <= 0) {
            // The detail message captures the exact failure information.
            String detail = String.format(
                    "Side length must be positive, but got %d", num);
            throw new IllegalArgumentException(detail);
        }

        // Volume of a regular tetrahedron: a³ / (6·√2)
        double volume = Math.pow(num, 3) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places to match the expected output.
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Auto‑boxing to Double
        return rounded;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

