import java.util.List;

/**
 * Computes the maximum possible average value of a path that travels
 * from the top‑left corner to the bottom‑right corner of a square matrix,
 * moving only right or down.
 *
 * The average is defined as (sum of visited cells) / (2·n‑1) because every
 * such path contains exactly 2·n‑1 cells.
 */
public class Maxaverageofpath {

    /**
     * Returns the maximum average of a valid path in the given cost matrix.
     *
     * @param cost the n×n matrix of non‑negative integer costs
     * @param n    the dimension of the square matrix
     * @return the maximal average as a {@code Double}
     * @throws IllegalArgumentException if the matrix is null, not square,
     *                                  or n is non‑positive
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- INPUT VALIDATION (with detailed failure‑capture messages) ----
        if (cost == null) {
            throw new IllegalArgumentException(
                String.format("Cost matrix is null (n = %d).", n));
        }
        if (n <= 0) {
            throw new IllegalArgumentException(
                String.format("Invalid dimension: n = %d (must be > 0).", n));
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException(
                String.format("Row count mismatch: cost.size() = %d, expected n = %d.",
                              cost.size(), n));
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException(
                    String.format("Column count mismatch at row %d: size = %d, expected n = %d.",
                                  i, (row == null ? 0 : row.size()), n));
            }
        }

        // ---- DP FOR MAXIMUM SUM ----
        long[][] dp = new long[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // ---- COMPUTE AVERAGE ----
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);

        return average;
    }

    // -----------------------------------------------------------------------
    // Simple manual test (can be removed or turned into JUnit tests)
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
            List.of(1, 2, 3),
            List.of(6, 5, 4),
            List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // expected 5.2

        List<List<Integer>> m2 = List.of(
            List.of(2, 3, 4),
            List.of(7, 6, 5),
            List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // expected 6.2

        List<List<Integer>> m3 = List.of(
            List.of(3, 4, 5),
            List.of(8, 7, 6),
            List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // expected 7.2
    }
}

