/**
 * Utility class for counting characters that have a vowel as a neighbour.
 */
class CountVowels {

    /** Vowel set for quick lookup (both lower‑ and upper‑case). */
    private static final String VOWELS = "aeiouAEIOU";

    /**
     * Counts characters (excluding vowels) that have at least one vowel
     * as an immediate neighbour (either to the left or to the right).
     *
     * @param testStr the input string; may not be {@code null}
     * @return the number of such characters
     * @throws IllegalArgumentException if {@code testStr} is {@code null}
     */
    public static int countVowels(String testStr) {
        // ---- failure‑capture (Item 75) ----
        if (testStr == null) {
            // Detail message captures the failure condition.
            throw new IllegalArgumentException(
                "CountVowels called with null string");
        }

        int length = testStr.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            char ch = testStr.charAt(i);

            // We only consider non‑vowel characters.
            if (!isVowel(ch)) {
                boolean leftIsVowel  = (i > 0)         && isVowel(testStr.charAt(i - 1));
                boolean rightIsVowel = (i < length - 1) && isVowel(testStr.charAt(i + 1));

                if (leftIsVowel || rightIsVowel) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Helper that tells whether a given character is a vowel. */
    private static boolean isVowel(char c) {
        return VOWELS.indexOf(c) >= 0;
    }

    // --------------------------------------------------------------------
    // Optional test driver (not required by the problem, but handy for quick checks)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        String[] tests = {
            "bestinstareels",
            "partofthejourneyistheend",
            "amazonprime"
        };
        int[] expected = { 7, 12, 5 };

        for (int i = 0; i < tests.length; i++) {
            int result = countVowels(tests[i]);
            System.out.printf("countVowels(\"%s\") = %d  (expected %d)%n",
                              tests[i], result, expected[i]);
        }
    }
}

