/**
 * Utility class that counts the number of alphabetic characters,
 * digits, and special characters in a given string.
 */
class CountAlphaDigSpl {

    /**
     * Custom exception that captures failure‑capture information
     * (the offending input and its length) in its detail message.
     * This follows the recommendation of Item 75.
     */
    static class InvalidStringException extends RuntimeException {
        private final String input;
        private final int length;

        public InvalidStringException(String input) {
            // Generate a detail message that includes the failure information
            super(String.format("Invalid input: %s (length: %d)",
                    input == null ? "null" : input,
                    input == null ? 0 : input.length()));
            this.input = input;
            this.length = (input == null) ? 0 : input.length();
        }

        /** Returns the input string that caused the exception. */
        public String getInput() {
            return input;
        }

        /** Returns the length of the input string (0 if the input was null). */
        public int getLength() {
            return length;
        }
    }

    /**
     * Counts alphabets, digits and special characters in the given string.
     *
     * @param string the input string (must not be null)
     * @return a List containing three integers:
     *         - count of alphabetic characters,
     *         - count of digit characters,
     *         - count of special (non‑letter, non‑digit) characters
     * @throws InvalidStringException if {@code string} is null
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Guard against null input – capture failure info in the exception
        if (string == null) {
            throw new InvalidStringException(string);
        }

        int alphaCount = 0;
        int digitCount = 0;
        int specialCount = 0;

        for (char ch : string.toCharArray()) {
            if (Character.isLetter(ch)) {
                alphaCount++;
            } else if (Character.isDigit(ch)) {
                digitCount++;
            } else {
                specialCount++;
            }
        }

        // Build the result list
        List<Integer> result = new ArrayList<>();
        result.add(alphaCount);
        result.add(digitCount);
        result.add(specialCount);

