public class SeriesSum {

    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n (must be a positive integer)
     * @return the sum of squares from 1 to n
     * @throws IllegalArgumentException if {@code number} is not positive
     *
     * <p>Examples:
     * <ul>
     *   <li>seriesSum(6) → 91</li>
     *   <li>seriesSum(7) → 140</li>
     *   <li>seriesSum(12) → 650</li>
     * </ul>
     */
    public static int seriesSum(int number) {
        // ---- failure‑capture (Item 75) ----
        if (number <= 0) {
            // The detail message includes the invalid value, making debugging easier.
            throw new IllegalArgumentException(
                String.format("Invalid number for series sum: %d. The number must be a positive integer.", number));
        }

        // Use the closed‑form formula: n(n+1)(2n+1)/6
        // Cast to long to avoid overflow of the intermediate multiplication.
        long result = (long) number * (number + 1) * (2L * number + 1) / 6;
        return (int) result;   // the problem constraints fit in an int
    }

    // A simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

