import java.math.BigInteger;   // optional – used only if you want to be safe for large n

class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(i) = 2·a(i‑1) + a(i‑2)  for i ≥ 2.
     *
     * For the small values of n used in the test cases the result fits
     * in a 32‑bit signed integer.
     *
     * @param n the index (0‑based) of the desired term; must be non‑negative
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        // ---- failure‑atomicity: validate input before any mutation ----
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;               // a(0) = a(1) = 1
        }

        // Iterate using two variables – O(n) time, O(1) extra space
        long a0 = 1L;   // a(i‑2)
        long a1 = 1L;   // a(i‑1)
        long a  = 0L;   // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence
            a0 = a1;
            a1 = a;
        }

        // The problem statement expects an int; assume n is small enough
        // to fit. If you need to handle larger n safely, switch to BigInteger.
        return (int) a;
    }

    // ---- optional test harness ----
    public static void main(String[] args) {
        // Example tests (matching the problem statement)
        System.out.println(newmanPrime(3)); // → 7
        System.out.println(newmanPrime(4)); // → 17
        System.out.println(newmanPrime(5)); // → 41
    }
}

