import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Returns "Found a match!" if the given text contains a word that
 * includes the letter 'z' (or 'Z') somewhere other than the first
 * or last character of that word; otherwise returns "Not matched!".
 *
 * @param text the input string to examine
 * @return     the appropriate result message
 */
public static String textMatchWordzMiddle(String text) {
    // ---- Failure‑atomic: validate input before any processing ----
    if (text == null) {
        return "Not matched!";
    }

    // Pattern that matches a contiguous sequence of letters (a "word").
    // \b marks a word boundary, [A-Za-z]+ matches one or more ASCII letters.
    final Pattern wordPattern = Pattern.compile("\\b[A-Za-z]+\\b");
    final Matcher matcher = wordPattern.matcher(text);

    while (matcher.find()) {
        String word = matcher.group();
        int len = word.length();

        // A word must be at least three characters long to have a middle position.
        if (len < 3) {
            continue;
        }

        // Scan the word for a 'z' (case‑insensitive) that is not at index 0 or len‑1.
        for (int i = 0; i < len; i++) {
            char ch = word.charAt(i);
            if (Character.toLowerCase(ch) == 'z' && i != 0 && i != len - 1) {
                return "Found a match!";
            }
        }
    }

    // No qualifying word was found.
    return "Not matched!";
}

