class Maxaverageofpath {
    /**
     * Find a path with the maximum average over all existing paths for the given
     * square matrix of size n×n.  Movement is restricted to right or down.
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     the dimension of the matrix
     * @return      the maximum average (as a {@code Double}) of any valid path
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- failure‑atomic validation ----
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Cost matrix must be non‑null and have size n");
        }
        for (List<Integer> row : cost) {
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Each row must be non‑null and have size n");
            }
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Remaining cells – take the better of the two predecessors
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // Number of cells visited on any top‑left → bottom‑right path = 2·n – 1
        double average = (double) maxSum / (2 * n - 1);
        return average;
    }
}

