     * @param number the positive integer n (must be >= 1)
     * @return the sum of squares from 1 to n
     * @throws IllegalArgumentException if number is less than 1
     * @throws ArithmeticException      if the result does not fit in an int
     */
    public static int seriesSum(int number) {
        // ---- Failure‑atomic: validate the parameter first ----
        if (number < 1) {
            throw new IllegalArgumentException(
                "Input must be a positive integer; got " + number);
        }

        // Use the O(1) formula: n(n+1)(2n+1)/6
        long n = number;                     // promote to long to avoid overflow in intermediate steps
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // Detect overflow for int (optional, but makes the method safer)
        if (sum > Integer.MAX_VALUE) {
            throw new ArithmeticException(
                "Sum of squares exceeds Integer.MAX_VALUE for n = " + number);
        }

