class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   p0 = 1, p1 = 1
     *   pn = 2 * p(n‑1) + p(n‑2)  for n >= 2
     *
     * Examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n the 1‑based index (n >= 1)
     * @return the n‑th term of the sequence
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // p0 = 1, p1 = 1
        if (n == 1) {
            return 1;
        }

        long prev2 = 1; // p0
        long prev1 = 1; // p1
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            // shift the window forward
            prev2 = prev1;
            prev1 = current;
        }

        // The values fit in int for reasonable n (up to n ≈ 25).
        // Cast is safe for the typical range of inputs.
        return (int) current;
    }

    // Simple sanity‑check (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

