/**
 * Finds a word that contains the letter 'z' but not as its first or last character.
 *
 * The method does not modify the input string, so it is automatically failure‑atomic.
 */
class TextMatchWordzMiddle {

    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input – no state has been changed yet.
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split on whitespace to obtain individual “words”.
        String[] words = text.split("\\s+");

        for (String word : words) {
            if (word.isEmpty()) {
                continue;               // skip any empty tokens (e.g., due to multiple spaces)
