        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that travels from the
     * top‑left corner to the bottom‑right corner of the given n×n matrix.
     * Movement is restricted to rightward or downward steps.
     *
     * @param cost  the n×n matrix of integer costs (must be non‑null, rectangular)
     * @param n     the dimension of the square matrix
     * @return      the highest possible average (sum / (2·n‑1))
     * @throws IllegalArgumentException if the matrix is null, not square,
     *         or contains null rows/columns
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- Input validation (fails fast, does not modify 'cost') ----
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Cost matrix must be non‑null and have exactly n rows.");
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Each row of the cost matrix must have exactly n columns.");
            }
        }

        // ---- DP array: maximum sum to reach each cell -----------------
        // Using long to avoid overflow for large inputs.
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Remaining cells – take the better of the two predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // ---- Compute average -----------------------------------------
        long maxSum = dp[n - 1][n - 1];                 // sum of the best path
        double average = (double) maxSum / (2 * n - 1); // path length = 2·n‑1
        return average;
    }
}

