/**
 * Computes the n‑th Newman‑Shanks‑Williams number.
 *
 * The sequence is defined by:
 *   s0 = 1, s1 = 1
 *   sn = 2·sn‑1 + sn‑2   (n ≥ 2)
 *
 * @param n the 1‑based index (must be > 0)
 * @return the n‑th NSW number
 * @throws IllegalArgumentException if n ≤ 0
 */
public static int newmanPrime(int n) {
    // Validate input – do not ignore the error.
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    // Base cases: s1 = 1, s2 = 3
    if (n == 1) {
        return 1;
    }

    // Use long to avoid premature overflow while iterating.
    long prev2 = 1L; // sn‑2  (initially s0)
    long prev1 = 1L; // sn‑1  (initially s1)
    long current = 0L;

    for (int i = 2; i <= n; i++) {
        current = 2 * prev1 + prev2; // sn = 2·sn‑1 + sn‑2
        // Shift the window for the next iteration.
        prev2 = prev1;
        prev1 = current;
    }

    // The result always fits into int for reasonable input.
    // If overflow occurs we let the JVM throw the arithmetic exception,
    // which is preferable to silently returning a wrong value.
    return (int) current;
}

