class VolumeTetrahedron {

    /**
     * Calculates the volume of a regular tetrahedron whose side length equals {@code num}.
     *
     * The volume V of a regular tetrahedron with side length a is:
     *     V = a³ / (6 * √2)
     *
     * The result is rounded to two decimal places.
     *
     * @param num the side length of the tetrahedron (must be non‑negative)
     * @return the volume rounded to two decimal places, or null if the input is invalid
     *
     * Example:
     *     volumeTetrahedron(10) → 117.85
     *     volumeTetrahedron(15) → 397.75
     *     volumeTetrahedron(20) → 942.81
     */
    public static Double volumeTetrahedron(int num) {
        // Validate the input – a negative side length makes no physical sense.
        if (num < 0) {
            // According to the programming advice, we should not ignore exceptions.
            // Here we choose to signal an illegal argument instead of silently proceeding.
            throw new IllegalArgumentException("Side length must be non‑negative: " + num);
        }

        // Convert to double to avoid integer overflow for large inputs.
        double side = num;

        // Volume formula for a regular tetrahedron.
        double volume = (side * side * side) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places as shown in the expected output.
        // Using Math.round ensures correct “half‑up” rounding.
        volume = Math.round(volume * 100.0) / 100.0;

        // Return the result as a Double object.
        return Double.valueOf(volume);
    }

