     * Write a function that matches a word containing 'z',
     * but not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // -----------------------------------------------------------------
        // 1. Validate the argument – never ignore a possible null input.
        // -----------------------------------------------------------------
        if (text == null) {
            // Throwing an explicit exception is better than silently ignoring it.
            throw new IllegalArgumentException("Input text cannot be null");
        }

        // -----------------------------------------------------------------
        // 2. Use a regex to locate whole words (letters only).
        //    The pattern is fixed, so PatternSyntaxException cannot occur.
        // -----------------------------------------------------------------
        Pattern wordPattern = Pattern.compile("\\b[A-Za-z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        // -----------------------------------------------------------------
        // 3. Scan each word and check for a 'z' that is not the first
        //    or last character.
        // -----------------------------------------------------------------
        while (matcher.find()) {
            String word = matcher.group();

            int zIndex = word.indexOf('z');          // -1 if no 'z'
            // Condition: word contains 'z' AND 'z' is not at position 0
            // AND 'z' is not at the last position.
            if (zIndex != -1 && zIndex != 0 && zIndex != word.length() - 1) {
                return "Found a match!";
            }
        }

        // -----------------------------------------------------------------
        // 4. No qualifying word was found.
        // -----------------------------------------------------------------
        return "Not matched!";
    }

