import java.math.*;

class CountVowels {

    /**
     * Counts characters (other than vowels) that have a vowel as a neighbour.
     * A neighbour is the immediate left or right character in the string.
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        // Defensive check – treating null/empty input as zero.
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels themselves – we only count consonants.
            if (isVowel(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }

            // Check right neighbour (if not already true)
            if (!hasVowelNeighbor && i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /**
     * Helper method to determine whether a given character is a vowel.
     * Both lower‑case and upper‑case letters are accepted.
     *
     * @param c the character to test
     * @return true if c is a vowel (a, e, i, o, u), false otherwise
     */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // -----------------------------------------------------------------
    // Optional test driver (feel free to remove or comment out)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

