class NewmanPrime {
    /**
     * Returns the nth term of the Newman‑Shanks‑Williams sequence.
     * The sequence is defined by:
     *   p_0 = 1, p_1 = 1
     *   p_n = 2 * p_{n-1} + p_{n-2} for n >= 2
     *
     * Examples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     *
     * @param n the index of the term to compute (1‑based)
     * @return the nth term of the Newman‑Shanks‑Williams sequence
     * @throws IllegalArgumentException if n is less than 1
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Use long to avoid overflow for moderate values of n.
        long a = 1; // p_0
        long b = 1; // p_1

        // Compute p_n iteratively.
        for (int i = 2; i <= n; i++) {
            long c = 2 * b + a; // p_i = 2 * p_{i-1} + p_{i-2}
            a = b;
            b = c;
        }

        // For n == 1, return p_1 (which is 1).
        // For n >= 2, return p_n.
        return (int) (n == 1 ? a : b);
    }
}

