class RemoveOdd {
    /**
     * Removes characters at odd positions (1‑based) from the input string,
     * i.e. keeps characters at even positions (2, 4, 6, ...).
     *
     * @param str1 the input string
     * @return a new string containing only the characters at even positions
     *
     * @example
     * <pre>
     * removeOdd("python")   -> "yhn"
     * removeOdd("program")  -> "rga"
     * removeOdd("language") -> "agae"
     * </pre>
     */
    public static String removeOdd(String str1) {
        // The method does not mutate any shared state, so it is thread‑safe
        // and does not require synchronization (see Item 78).
        if (str1 == null) {
            return null;
        }

        StringBuilder result = new StringBuilder(str1.length() / 2 + 1);
        // i == 0 corresponds to position 1 (odd), i == 1 to position 2 (even), etc.
        for (int i = 0; i < str1.length(); i++) {
            // Keep characters at odd indices (i % 2 == 1), i.e. even positions in 1‑based indexing.
            if (i % 2 == 1) {
                result.append(str1.charAt(i));
            }
        }
        return result.toString();
    }

    // Simple test driver
