public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the input contains the letter 'z'
     * somewhere other than the first or last position; otherwise returns
     * "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.trim().isEmpty()) {
            return "Not matched!";
        }

        // Split on one or more whitespace characters
        String[] words = text.trim().split("\\s+");

        for (String word : words) {
