}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left
     * cell and ends at the bottom‑right cell of a square matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    the dimension of the square matrix
     * @return the maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against bad input
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long cellValue = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cellValue;
                } else {
                    // Best predecessor: either from above or from the left
                    long fromAbove  = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                    long fromLeft   = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;
                    dp[i][j] = cellValue + Math.max(fromAbove, fromLeft);
                }
            }
        }

        // The path always contains (2 * n - 1) cells
        double maxAverage = dp[n - 1][n - 1] / (double) (2 * n - 1);
        return maxAverage;
    }

    // --------------------------------------------------------------------
    // Simple manual test (uncomment to run)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // Expected: 5.2

        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // Expected: 6.2

        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // Expected: 7.2
    }
}

