class CountVowels {

    /** 
     * Vowel set (lower‑case).  The check is case‑insensitive.
     */
    private static final Set<Character> VOWELS = Set.of(
            'a', 'e', 'i', 'o', 'u'
    );

    /**
     * Counts characters that are not vowels (consonants) and that have
     * at least one vowel neighbour in the given string.
     *
     * @param testStr the input string (may be null)
     * @return the number of such characters
     */
    public static synchronized int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }

        char[] a = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < a.length; i++) {
            char ch = Character.toLowerCase(a[i]);

            // Skip vowels – we only count consonants.
            if (VOWELS.contains(ch)) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbor = false;
            if (i > 0) {
                char left = Character.toLowerCase(a[i - 1]);
                if (VOWELS.contains(left)) {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbour if not already found
            if (!hasVowelNeighbor && i < a.length - 1) {
                char right = Character.toLowerCase(a[i + 1]);
                if (VOWELS.contains(right)) {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

