class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2*a(n‑1) + a(n‑2)   for n ≥ 2.
     *
     * The function returns the value at index n (0‑based).
     *
     * Examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n the index of the desired Newman–Shanks–Williams number
     * @return the n‑th element of the sequence
     * @throws IllegalArgumentException if n is negative
     * @throws ArithmeticException     if the result does not fit in an int
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases a(0) = a(1) = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long prev2 = 1; // a(i‑2)
        long prev1 = 1; // a(i‑1)
        long cur   = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2; // a(i) = 2*a(i‑1) + a(i‑2)
            // shift the window for the next iteration
            prev2 = prev1;
            prev1 = cur;
        }

        // The problem expects an int result.  Guard against overflow.
        if (cur > Integer.MAX_VALUE) {
            throw new ArithmeticException("Result exceeds Integer.MAX_VALUE");
        }
        return (int) cur;
    }

    // --------------------------------------------------------------------
    // A tiny demo (optional)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        for (int i = 3; i <= 5; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

