class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the positive integer n
     * @return the sum of squares from 1 to n
     */
    public static int seriesSum(int number) {
        // Use a long intermediate to avoid overflow before the division.
        long n = number;
        // Apply the formula: n * (n + 1) * (2n + 1) / 6
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        // The result fits in an int for reasonable input sizes; cast back to int.
        return (int) sum;
    }

