class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2*a(n-1) + a(n-2) for n >= 2
     *
     * Examples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        // Base cases: a(0) = 1, a(1) = 1
        if (n <= 1) {
            return 1;
        }

        long a0 = 1; // a(n-2)
        long a1 = 1; // a(n-1)
        long a2 = 0; // a(n) temporary

        // Compute iteratively from index 2 up to n
        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0; // recurrence relation
            // Shift the window for next iteration
            a0 = a1;
            a1 = a2;
        }

        // The result fits in an int for reasonable n; cast is safe for the problem constraints
        return (int) a1;
    }
}

