class Maxaverageofpath {

    /**
     * Returns the maximum average value among all paths that go from the
     * top‑left corner (0,0) to the bottom‑right corner (n‑1,n‑1) moving only
     * right or down.
     *
     * @param cost  a square matrix represented as a list of rows
     * @param n     size of the matrix (n x n)
     * @return      the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] holds the maximum sum to reach cell (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);          // value of current cell

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else {
                    long fromTop  = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                    long fromLeft = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;
                    dp[i][j] = val + Math.max(fromTop, fromLeft);
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // A path from (0,0) to (n‑1,n‑1) always contains (2*n‑1) cells.
        double average = maxSum / (double) (2L * n - 1);
        return average;               // auto‑boxed to Double
    }

    // -----------------------------------------------------------------
    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Null or empty string -> no such characters
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with lower‑case characters to make the vowel check case‑insensitive
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);

            // Vowels themselves are not counted
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0) {
                char left = s.charAt(i - 1);
                if (left == 'a' || left == 'e' || left == 'i' || left == 'o' || left == 'u') {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbour if we haven't found a vowel yet
            if (!hasVowelNeighbor && i < len - 1) {
                char right = s.charAt(i + 1);
                if (right == 'a' || right == 'e' || right == 'i' || right == 'o' || right == 'u') {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

