class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     *
     * The NSW numbers are generated by
     *   a0 = 1, a1 = 1
     *   a(i) = 2*a(i‑1) + a(i‑2)   (i ≥ 2)
     *
     * The primes that appear in this sequence are:
     *   3, 7, 17, 41, 239, 577, …
     *
     * The problem’s examples show that
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     * which corresponds to returning the (n‑1)-th prime (1‑based).
     *
     * @param n  the index (must be ≥ 1)
     * @return   the corresponding NSW prime
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // The first NSW prime (index 1) is 3.
        if (n == 1) {
            return 3;
        }

        // Generate the NSW sequence and collect primes until we have (n‑1) of them.
        List<Integer> primes = new ArrayList<>();

        long a0 = 1;   // a(i‑2)
        long a1 = 1;   // a(i‑1)

        for (int i = 2; primes.size() < n - 1; i++) {
            long a = 2 * a1 + a0;   // a(i)
            if (isPrime(a)) {
                primes.add((int) a);
            }
            // Shift the window for the next iteration
            a0 = a1;
            a1 = a;
        }

        // The last collected prime is the answer.
        return primes.get(primes.size() - 1);
    }

    /** Simple deterministic primality test for a positive {@code long}. */
    private static boolean isPrime(long num) {
        if (num <= 1) {
            return false;
        }
        if (num <= 3) {
            return true;                // 2 and 3 are prime
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;               // multiples of 2 or 3
        }

        // Check divisibility by candidates of the form 6k ± 1 up to √num.
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    // -----------------------------------------------------------------
    // Optional test driver (feel free to remove / comment out in production)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
        // Additional sanity checks
        System.out.println(newmanPrime(2)); // 3
        System.out.println(newmanPrime(1)); // 3
    }
}

