}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left corner
     * of the given n×n matrix and ends at the bottom‑right corner, moving only
     * right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    size of the matrix (cost.size() == n)
     * @return the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                int val = row.get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else {
                    long bestFromTop = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                    long bestFromLeft = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;
                    dp[i][j] = val + Math.max(bestFromTop, bestFromLeft);
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // Number of cells visited on any valid path = 2*n - 1
        double average = maxSum / (double) (2 * n - 1);

        return average;
    }

    // -----------------------------------------------------------------
    // Optional test harness (uncomment to run)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

