class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i < testStr.length(); i++) {
            char ch = testStr.charAt(i);

            // We only care about consonants
            if (!isConsonant(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check the left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check the right neighbour if we haven't found a vowel yet
            if (!hasVowelNeighbor && i < testStr.length() - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    /** Returns true if the given character is a vowel (including y). */
    private static boolean isVowel(char c) {
        char lower = Character.toLowerCase(c);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u' || lower == 'y';
    }

    /** Returns true if the given character is a consonant (alphabetic but not a vowel). */
    private static boolean isConsonant(char c) {
        if (!Character.isLetter(c)) {
            return false;           // ignore non‑letters
        }
        return !isVowel(c);
    }

    // -----------------------------------------------------------------
    // Optional quick test (can be removed when integrating into a larger codebase)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

