public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2*a(n‑1) + a(n‑2) for n >= 2.
     *
     * For the given examples:
     *   newmanPrime(3) -> 7
     *   newmanPrime(4) -> 17
     *   newmanPrime(5) -> 41
     *
     * @param n the index of the desired term (0‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the first two base cases
        if (n == 0) return 1;
        if (n == 1) return 1;

        // Use long for intermediate values to avoid overflow of int
        long prev2 = 1; // a(n‑2)
        long prev1 = 1; // a(n‑1)
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            // shift the window forward
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int return type; cast the result.
        // (If larger values are needed, consider returning long or BigInteger.)
        return (int) current;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

