public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that goes from the
     * top‑left corner to the bottom‑right corner of the given n×n matrix.
     * The path may only move right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation ------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // ---- dynamic programming table (long to avoid overflow) -------------
        long[][] dp = new long[n][n];

        // first cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average -------------------------------------------------
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------------
    // Simple manual test (not required for the solution, but useful for verification)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
