class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // Use BigInteger to avoid overflow for larger n
        BigInteger a0 = BigInteger.ONE;
        BigInteger a1 = BigInteger.ONE;
        if (n == 1) {
            return a1.intValue(); // returns 1, though not a prime
        }
        BigInteger a = BigInteger.ZERO;
        for (int i = 2; i <= n; i++) {
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            a0 = a1;
            a1 = a;
        }
        // The result may exceed int range; we return int assuming n is small enough.
        return a.intValue();
    }
}

