     * (or 'Z') at a position other than the first or last character.
     * Otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern matches sequences of ASCII letters – i.e. words.
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int len = word.length();

            // A word must be at least 3 characters long to have a "middle" position.
            if (len < 3) {
                continue;
            }

            // Scan characters except the first and last for 'z' or 'Z'.
            for (int i = 1; i < len - 1; i++) {
                char c = word.charAt(i);
                if (c == 'z' || c == 'Z') {
                    return "Found a match!";
                }
            }
        }

        return "Not matched!";
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

import java.util.Arrays;
import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that starts at the top‑left
     * cell and ends at the bottom‑right cell, moving only right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    dimension of the matrix
     * @return the maximal average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] – maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long val = cost.get(i).get(j);          // value in current cell
                if (i == 0 && j == 0) {
                    dp[i][j] = val;                     // start cell
                } else {
                    long best = Long.MIN_VALUE;
                    if (i > 0) best = Math.max(best, dp[i - 1][j]); // from above
                    if (j > 0) best = Math.max(best, dp[i][j - 1]); // from left
                    dp[i][j] = val + best;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2L * n - 1);
        return average;
    }

    // --------------------------------------------------------------------
    // Simple test driver (not required for the final solution)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with a lower‑case copy for case‑insensitive vowel detection
        String s = testStr.toLowerCase();
        int n = s.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);

            // Skip vowels – we only count consonants
            if (isVowel(ch)) {
                continue;
            }

            // Check the left neighbour
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                count++;
                continue; // already satisfied, no need to check the right side
            }

            // Check the right neighbour
            if (i < n - 1 && isVowel(s.charAt(i + 1))) {
                count++;
            }
        }

        return count;
    }

    /** Helper that returns true if the given character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // Optional simple test (can be removed when integrating into a larger codebase)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

