class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (n == 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }
        int a0 = 1; // a(1)
        int a1 = 3; // a(2)
        for (int i = 3; i <= n; i++) {
            int a2 = 2 * a1 + a0;
            a0 = a1;
            a1 = a2;
        }
        return a1;
    }
}

