public class Maxaverageofpath {
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive copy? Not needed but can check dimensions.
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Invalid matrix size");
        }
        double[][] dp = new double[n][n];
        // start cell
        dp[0][0] = cost.get(0).get(0);
        // first row
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j-1] + cost.get(0).get(j);
        }
        // first column
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i-1][0] + cost.get(i).get(0);
        }
        // fill rest
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i-1][j], dp[i][j-1]);
            }
        }
        double maxSum = dp[n-1][n-1];
        double average = maxSum / (2 * n - 1);
        return average;
    }

    // Simple test driver
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
            Arrays.asList(1,2,3),
            Arrays.asList(6,5,4),
            Arrays.asList(7,3,9)
        );
