public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1,
     *   an = 2·a(n‑1) + a(n‑2)  for n ≥ 2.
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th NSW number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use BigInteger to avoid overflow, then cast back to int.
        // (The problem expects small n, so the result fits in an int.)
        BigInteger a0 = BigInteger.ONE; // a(i‑2)
        BigInteger a1 = BigInteger.ONE; // a(i‑1)
        BigInteger a  = null;           // a(i)

        for (int i = 2; i <= n; i++) {
            a = a1.multiply(BigInteger.valueOf(2)).add(a0); // a = 2*a1 + a0
            a0 = a1;
            a1 = a;
        }

        return a.intValue();   // safe for the intended input range
    }

    // Simple test (optional)
    public static void main(String[] args) {
        for (int i = 0; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

