class TextMatchWordzMiddle {
    /**
     * Returns "Found a match!" if any word in the given text contains the letter 'z'
     * somewhere other than the first or last character of that word; otherwise returns
     * "Not matched!".
     *
     * @param text the input string to examine
     * @return result string as described above
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern matches whole words (boundaries at word‐character <-> non‑word‑character)
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // the actual word
            String lower = word.toLowerCase();           // case‑insensitive check

            // Look for any 'z' that is not at position 0 or at the last position
            int idx = lower.indexOf('z');
            while (idx != -1) {
                if (idx > 0 && idx < word.length() - 1) {
                    return "Found a match!";
                }
                // Continue searching for other 'z's in the same word
                idx = lower.indexOf('z', idx + 1);
            }
        }

        return "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));     // "Not matched!"
    }
}

