class CountVowels {
    /**
     * Counts characters that are not vowels and that have a vowel
     * as an immediate neighbour (either left or right).
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() < 2) {
            // No character can have a vowel neighbour if the string is empty or a single char.
            return 0;
        }

        // Set of vowel characters (both lower‑ and upper‑case)
        final String vowels = "aeiouAEIOU";

        char[] a = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < a.length; i++) {
            char c = a[i];
            // Skip vowels themselves – we only count consonants (or any non‑vowel chars)
            if (vowels.indexOf(c) != -1) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbor = (i > 0 && vowels.indexOf(a[i - 1]) != -1);
            // Check right neighbour if left didn't contain a vowel
            if (!hasVowelNeighbor) {
                hasVowelNeighbor = (i < a.length - 1 && vowels.indexOf(a[i + 1]) != -1);
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

