class NewmanPrime {
    /**
     * Write a function to find the nth Newman–Shanks–Williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // The sequence starts 1, 1, 3, 7, 17, …
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use BigInteger to avoid overflow for larger n; finally cast to int.
        BigInteger aNm2 = BigInteger.ONE; // a(n‑2)
        BigInteger aNm1 = BigInteger.ONE; // a(n‑1)
        BigInteger aN   = BigInteger.ONE; // a(n)

        for (int i = 2; i <= n; i++) {
            aN = aNm1.multiply(BigInteger.valueOf(2)).add(aNm2);
            aNm2 = aNm1;
            aNm1 = aN;
        }

        // For the small test cases the result fits in an int.
        return aN.intValue();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

