class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2 * a(n‑1) + a(n‑2)  for n >= 2
     *
     * @param n index of the term (0‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Handle the first two base cases
        if (n == 0) return 1;   // a(0)
        if (n == 1) return 1;  // a(1)

        // Iterate using long to avoid early overflow; the result fits in int
        // for the typical range of n used in the tests.
        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a  = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence relation
            a0 = a1;
            a1 = a;
        }
        return (int) a; // the problem expects an int result
    }
}

