public class Maxaverageofpath {
    /**
     * Find a path with the maximum average over all existing paths
     * from the top‑left corner to the bottom‑right corner of an n×n matrix.
     * Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of integers
     * @param n    the dimension of the matrix
     * @return the maximum possible average (as a {@code Double})
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table holds the maximum sum to reach each cell.
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cur = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = cur;                     // start cell
                } else {
                    long best = Long.MIN_VALUE;
                    if (i > 0) best = Math.max(best, dp[i - 1][j]); // from top
                    if (j > 0) best = Math.max(best, dp[i][j - 1]); // from left
                    dp[i][j] = cur + best;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1); // number of cells visited = 2n‑1

        return average; // auto‑boxed to Double
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        List<List<Integer>> mat2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
