class CountVowels {
    /**
     * Counts consonants in the given string that have at least one vowel
     * as an immediate neighbour (left or right).
     *
     * @param testStr the input string
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // We only consider non‑vowel characters
            if (!isVowel(ch)) {
                boolean hasVowelNeighbor = false;

                // Check left neighbour
                if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // Check right neighbour
                if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Helper: determines whether a character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char c) {
        char lower = Character.toLowerCase(c);
        return lower == 'a' || lower == 'e' || lower == 'i'
            || lower == 'o' || lower == 'u';
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

