class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // The first Newman–Shanks–Williams prime is 3.
        if (n == 1) {
            return 3;
        }

        // The examples indicate that newmanPrime(3) = 7, newmanPrime(4) = 17,
        // newmanPrime(5) = 41, i.e., the result is the (n‑1)th prime in the
        // NSW sequence.  So we look for the (n‑1)th prime.
        int target = n - 1;

        BigInteger a0 = BigInteger.ONE; // a(i‑2)
        BigInteger a1 = BigInteger.ONE; // a(i‑1)
        int found = 0;

        while (true) {
            // Compute the next NSW number: a(i) = 2*a(i‑1) + a(i‑2)
            BigInteger a = a1.multiply(BigInteger.valueOf(2)).add(a0);

            if (a.isProbablePrime(100)) {
                found++;
                if (found == target) {
                    // The result is guaranteed to fit in an int for the
                    // expected input range.
                    return a.intValue();
                }
            }

            // Advance the sequence
            a0 = a1;
            a1 = a;
        }
    }
}

