        }

        // Set of vowel characters – both lower‑ and upper‑case
        final Set<Character> VOWELS = new HashSet<>();
        for (char c : "aeiouAEIOU".toCharArray()) {
            VOWELS.add(c);
        }

        int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // We only care about consonants; vowels are never counted
            if (VOWELS.contains(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0 && VOWELS.contains(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour (only if left didn't already satisfy)
            if (!hasVowelNeighbor && i < len - 1 && VOWELS.contains(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

