class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Validate input
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Base cases: the first two terms of the Newman‑Shanks‑Williams sequence are 1, 1
        if (n == 0) return 1;
        if (n == 1) return 1;
        // Iteratively compute the n‑th term using the recurrence:
        // a(n) = 2*a(n‑1) + a(n‑2)
        long aNm2 = 1; // a(n‑2)
        long aNm1 = 1; // a(n‑1)
        long aN = 0;
        for (int i = 2; i <= n; i++) {
            aN = 2 * aNm1 + aNm2;
            aNm2 = aNm1;
            aNm1 = aN;
        }
        // The result fits in an int for the expected range of n
        return (int) aN;
    }
}

