     * corner of the given square matrix and ends at the lower‑right corner,
     * moving only right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    dimension of the matrix (must match cost.size())
     * @return the maximum possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }
        // In case the caller passed a different n, adapt to the actual matrix size
        if (cost.size() != n) {
            n = cost.size();
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Start cell
        dp[0][0] = cost.get(0).get(0).longValue();

        // First row (只能从左边来)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j).longValue();
        }

        // First column (只能从上边来)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0).longValue();
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                         + cost.get(i).get(j).longValue();
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);
        return Double.valueOf(average);
    }

    // --------------------------------------------------------------------
    // Simple test driver (matches the examples from the problem statement)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

class CountVowels {
    /**
     * Counts consonants in the given string that have at least one vowel
     * as an immediate neighbour (either to the left or to the right).
     * Vowels themselves are not counted. The method is not thread‑safe;
     * callers must not share an instance across threads without external
     * synchronisation (see Item 82).
     *
     * @param testStr the input string (may contain mixed case)
     * @return the number of consonants that are adjacent to a vowel
     */
    public static int countVowels(String testStr) {
        // Null or empty strings have no such characters.
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with a lower‑case copy so we can treat both cases uniformly.
        String lower = testStr.toLowerCase();
        int length = lower.length();
        int count = 0;

        // Helper to test if a character is a vowel.
        for (int i = 0; i < length; i++) {
            char ch = lower.charAt(i);

            // Skip vowels – we only count consonants.
            if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour.
            if (i > 0) {
                char left = lower.charAt(i - 1);
                if (left == 'a' || left == 'e' || left == 'i' || left == 'o' || left == 'u') {
                    hasVowelNeighbor = true;
                }
            }

            // Check right neighbour (only if we haven't already found a vowel).
            if (!hasVowelNeighbor && i < length - 1) {
                char right = lower.charAt(i + 1);
                if (right == 'a' || right == 'e' || right == 'i' || right == 'o' || right == 'u') {
                    hasVowelNeighbor = true;
                }
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple manual test (optional).
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

