class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2*a(n‑1) + a(n‑2)  for n ≥ 2
     *
     * Examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n index of the required term (0‑based)
     * @return the n‑th NSW number
     */
    public static int newmanPrime(int n) {
        // Base cases
        if (n <= 0) {
            return 1;               // a0 = 1
        }
        if (n == 1) {
            return 1;               // a1 = 1
        }

        long prev2 = 1; // a(i‑2)
        long prev1 = 1; // a(i‑1)

        for (int i = 2; i <= n; i++) {
            long curr = 2 * prev1 + prev2; // a(i) = 2*a(i‑1) + a(i‑2)
            prev2 = prev1;
            prev1 = curr;
        }

        // The result always fits into int for the expected input range
        return (int) prev1;
    }

    // Simple manual test (can be removed when submitting)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

