class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split the string on whitespace to get individual “words”
        String[] tokens = text.split("\\s+");

        for (String token : tokens) {
            // Skip any empty tokens (should not happen after split, but safe to check)
            if (token.isEmpty()) {
                continue;
            }

            // Look for a 'z' that is not the first or the last character
            boolean innerZ = false;
            // We only need to examine characters between index 1 and length-2
            for (int i = 1; i < token.length() - 1; i++) {
                if (token.charAt(i) == 'z') {
                    innerZ = true;
                    break;               // no need to search further
                }
            }

            if (innerZ) {
                return "Found a match!";
            }
        }

        // No token contained an internal 'z'
        return "Not matched!";
    }

    // Simple test harness
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

import java.util.List;

/**
 * Computes the maximum average of a monotone (down/right) path
 * from the top‑left corner to the bottom‑right corner of a square matrix.
 */
public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // dp[i][j] – maximal sum to reach cell (i, j)
    double[][] dp = new double[n][n];

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int val = cost.get(i).get(j);          // value of current cell

            if (i == 0 && j == 0) {
                // start cell
                dp[i][j] = val;
            } else {
                double fromTop  = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                double fromLeft = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                dp[i][j] = Math.max(fromTop, fromLeft) + val;
            }
        }
    }

    double maxSum = dp[n - 1][n - 1];
    // every path has exactly (2*n - 1) cells
    return maxSum / (2.0 * n - 1);
}

