 *
 * The method counts characters that are not vowels (consonants) and that have
 * at least one vowel (a, e, i, o, u – both lower‑ and upper‑case) as an
 * immediate left or right neighbour.
 */
class CountVowels {

    /** Set of vowels (both cases). */
    private static final String VOWELS = "aeiouAEIOU";

