public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' somewhere other than the first or last position;
     * otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") -> "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")    -> "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   -> "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Split the input on any non‑word character (spaces, punctuation, etc.)
        String[] words = text.split("\\W+");

        // Use a parallel stream (backed by a fork‑join pool) to test the words.
        // The anyMatch operation will stop as soon as a matching word is found.
        boolean found = Arrays.stream(words)
                .parallel()                     // exploit the fork‑join pool
                .filter(w -> !w.isEmpty())      // ignore empty tokens
                .anyMatch(w -> {
                    int idx = w.indexOf('z'); // position of 'z' (‑1 if absent)
                    // match only if 'z' is present and not at the first or last index
                    return idx > 0 && idx < w.length() - 1;
                });

        return found ? "Found a match!" : "Not matched!";
    }

