class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle edge cases
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }

        // Initialize the NSW sequence: a(0) = 1, a(1) = 1
        long a0 = 1;
        long a1 = 1;

        // Iterate through indices to find the first prime at index >= n
        int index = 0;
        while (true) {
            long currentValue;
            if (index == 0) {
                currentValue = a0;
            } else if (index == 1) {
                currentValue = a1;
            } else {
                // Compute next NSW number: a(n) = 2*a(n-1) + a(n-2)
                long a2 = 2 * a1 + a0;
                a0 = a1;
                a1 = a2;
                currentValue = a2;
            }

            // Check if we have reached index n and current value is prime
            if (index >= n && isPrime(currentValue)) {
                return (int) currentValue;
            }

            index++;
        }
    }

    // Helper method to check if a number is prime
    private static boolean isPrime(long num) {
        if (num < 2) {
            return false;
        }
        if (num == 2) {
            return true;
        }
        if (num % 2 == 0) {
            return false;
        }
        // Check odd divisors up to sqrt(num)
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

