public class Maxaverageofpath {

    /**
     * Returns the maximum average of any path that travels from the top‑left
     * corner to the bottom‑right corner of the given n×n cost matrix.
     * Movement is restricted to rightward or downward steps.
     *
     * @param cost  list of rows, each row a list of integers representing cell costs
     * @param n     size of the square matrix (number of rows/columns)
     * @return      the highest possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- basic validation -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // ---- DP array: dp[i][j] = max sum to reach cell (i, j) ----------------
        double[][] dp = new double[n][n];

        // initialise start cell
        dp[0][0] = cost.get(0).get(0);

        // first column – can only come from the cell above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // first row – can only come from the cell on the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // total number of cells in any valid path = 2 * n - 1
        int pathLength = 2 * n - 1;
        double maxSum = dp[n - 1][n - 1];
        return maxSum / pathLength;   // automatically boxed to Double
    }

    // -----------------------------------------------------------------------
    // A tiny manual test (you can remove or replace with proper unit tests)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // expected 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // expected 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // expected 7.2
    }
}

