import java.util.concurrent.*;   // for ConcurrentHashMap

class SeriesSum {

    // A simple cache for previously computed results.
    // Using ConcurrentHashMap lets multiple threads safely call computeIfAbsent.
    private static final ConcurrentHashMap<Integer, Integer> cache = new ConcurrentHashMap<>();

    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * The result is cached, so repeated calls for the same {@code number}
     * return the cached value without recomputation.
     *
     * @param number the term n of the series (must be non‑negative)
     * @return the sum 1² + 2² + … + n²
     * @throws IllegalArgumentException if number is negative
     */
    public static int seriesSum(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative");
        }

        // computeIfAbsent atomically computes the value only if the key is absent.
        // The lambda computes the sum using the closed‑form formula:
        //   n * (n + 1) * (2n + 1) / 6
        return cache.computeIfAbsent(number, n -> {
            // Use long for the intermediate product to avoid overflow.
            long result = (long) n * (n + 1) * (2L * n + 1) / 6;
            return (int) result;   // the problem expects an int return.
        });
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

