public static int newmanPrime(int n) {
    if (n == 0 || n == 1) {
        return 1;
    }
    int prev = 1;  // a(n-2)
    int curr = 1;  // a(n-1)
    for (int i = 2; i <= n; i++) {
        int next = 2 * curr + prev;
        prev = curr;
        curr = next;
    }
    return curr;
}

