public static int newmanPrime(int n) {
    // The sequence is defined as:
    // a(0) = 1, a(1) = 1
    // a(i) = 2*a(i-1) + a(i-2) for i >= 2
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }
    // Base cases
    if (n == 0 || n == 1) {
        return 1;
    }

    long a0 = 1; // a(i‑2)
    long a1 = 1; // a(i‑1)
    long a  = 0; // a(i)

    for (int i = 2; i <= n; i++) {
        a  = 2 * a1 + a0; // compute a(i)
        a0 = a1;           // shift for next iteration
        a1 = a;
    }
    // The result fits in an int for reasonable n (up to n ≈ 25)
    return (int) a;
}

