import java.util.List;

public class Maxaverageofpath {

    /**
     * Finds the maximum average of all monotonic (right‑/down) paths
     * from the top‑left corner to the bottom‑right corner of the
     * given n×n matrix.
     *
     * @param cost the square matrix (List of List of Integers)
     * @param n    the dimension of the matrix
     * @return the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // n is guaranteed to be > 0
        long[] dp = new long[n]; // dp[j] = max sum to reach cell (current row, j)

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // start cell
                    dp[0] = val;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[j] = dp[j - 1] + val;
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[0] = dp[0] + val;
                } else {
                    // max of coming from above (dp[j] before update) or from left (dp[j‑1])
                    dp[j] = Math.max(dp[j], dp[j - 1]) + val;
                }
            }
        }

        long maxSum = dp[n - 1];                     // sum of the best path
        double average = (double) maxSum / (2L * n - 1); // number of cells on the path = 2*n‑1
        return Double.valueOf(average);
    }
}

