class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)   for n >= 2
     *
     * @param n the index (1‑based) of the term to compute
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        // Handle the base cases
        if (n <= 0) {
            // By definition a0 = 1
            return 1;
        }
        if (n == 1) {
            // a1 = 1
            return 1;
        }

        // Iteratively compute the sequence using int (fits for n <= 25)
        int aPrev2 = 1; // a0
        int aPrev1 = 1; // a1
        int current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * aPrev1 + aPrev2;
            // Shift the window for the next iteration
            aPrev2 = aPrev1;
            aPrev1 = current;
        }
        return current;
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

