import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts at
     * the top‑left corner and ends at the bottom‑right corner of the given
     * n×n matrix.  Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the size of the matrix (number of rows/columns)
     * @return the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] – best sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double pathLength = 2.0 * n - 1.0;   // number of cells in any path
        return maxSum / pathLength;
    }

    // --------------------------------------------------------------------
    // A tiny test driver (optional)
