class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n of the series (must be >= 0)
     * @return the sum of squares from 1 to number (as an int)
     */
    public static int seriesSum(int number) {
        // Guard against negative input – the series is defined for n >= 0
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative");
        }

        // Use a long intermediate to avoid overflow while computing the formula.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The problem statement expects an int return type, so we cast.
        // For very large n the result may exceed Integer.MAX_VALUE,
        // in which case the cast discards the high bits (behaviour is
        // undefined). If you need the full result, consider returning long.
        return (int) sum;
    }

    // Simple manual test driver (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

