    }
}

import java.util.Arrays;
import java.util.List;

/**
 * Counts alphabets, digits and special characters in a given string.
 *
 * @param string the input text (may be null)
 * @return a List containing [alphabets, digits, special characters]
 */
public static List<Integer> countAlphaDigSpl(String string) {
    // Guard against null input – treat it as an empty string
    if (string == null) {
        return Arrays.asList(0, 0, 0);
    }

    // Use codePoints() to correctly handle Unicode characters outside the BMP.
    // The parallel() method spreads the work across multiple threads (concurrency utility).
    int[] counts = string.codePoints()
            .parallel()
            .collect(
                    () -> new int[3],                     // supplier: int[0]=alpha, int[1]=digit, int[2]=special
                    (int[] a, int cp) -> {                 // accumulator
                        if (Character.isLetter(cp)) {
                            a[0]++;                       // alphabet
                        } else if (Character.isDigit(cp)) {
                            a[1]++;                       // digit
                        } else {
                            a[2]++;                       // special character
                        }
                    },
                    (int[] a, int[] b) -> {                // combiner
                        a[0] += b[0];
                        a[1] += b[1];
                        a[2] += b[2];
                    });

    // Return the result as an immutable list (Java 9+), or use Arrays.asList for Java 8
    return Arrays.asList(counts[0], counts[1], counts[2]);
}

/* ---- Example usage ---- */
public static void main(String[] args) {
    System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
    System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
    System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
}

