/**
 * Utility class for computing Newman‑Shanks‑Williams numbers.
 */
class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams (NSW) number.
     *
     * <p>The NSW sequence is defined as:
     * <ul>
     *   <li>N(0) = 1</li>
     *   <li>N(1) = 1</li>
     *   <li>N(i) = 2·N(i‑1) + N(i‑2)  for i ≥ 2</li>
     * </ul>
     *
     * <p>Examples:
     * <pre>
     * newmanPrime(3) → 7
     * newmanPrime(4) → 17
     * newmanPrime(5) → 41
     * </pre>
     *
     * @param n the index of the NSW number to return (0‑based)
     * @return the n‑th NSW number
     * @throws IllegalArgumentException if {@code n} is negative
     *
     * <p><strong>Thread‑safety:</strong> This method is stateless and uses only
     * local variables. It can be invoked concurrently from any number of threads
     * without external synchronization.
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases N(0) and N(1) are both 1.
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iteratively compute the NSW numbers.
        long prev2 = 1; // N(i‑2)
        long prev1 = 1; // N(i‑1)

        for (int i = 2; i <= n; i++) {
            long current = 2 * prev1 + prev2; // N(i)
            prev2 = prev1;
            prev1 = current;
        }

        // The result fits in an int for the expected range of n.
        return (int) prev1;
    }
}

