     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern that matches words (sequences of word characters)
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int len = word.length();

            // A word of length 1 or 2 cannot have a 'z' in the middle
            if (len <= 2) {
                continue;
            }

            // Look for a 'z' that is not the first or last character
            for (int i = 1; i < len - 1; i++) {
                if (word.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }

        return "Not matched!";
    }
}

