     * Returns the maximum average of a path that goes from the top‑left corner
     * to the bottom‑right corner of the given n×n matrix.  Movement is allowed
     * only to the right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    the dimension of the square matrix
     * @return the maximum average (as a Double)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP[i][j] = maximum sum to reach cell (i, j) from (0,0)
        long[][] dp = new long[n][n];

        // Initialize the starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        long maxSum = dp[n - 1][n - 1];

        // The path contains (2*n - 1) cells.  Adding 1 to the sum is the
        // trick used in the original problem statement to obtain the required
        // average.
        double average = (maxSum + 1.0) / (2.0 * n - 1.0);

