     * (either to the left or to the right). 
     *
     * <p>Examples:
     * <ul>
     *   <li>countVowels("bestinstareels") → 7</li>
     *   <li>countVowels("partofthejourneyistheend") → 12</li>
     *   <li>countVowels("amazonprime") → 5</li>
     * </ul>
     *
     * @param testStr the input string (may contain mixed case letters)
     * @return the number of consonants that are adjacent to a vowel
     *
     * @threadSafety This method is immutable and stateless; it is unconditionally
     *                thread‑safe and can be used concurrently without external synchronization.
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Use a simple set for quick vowel lookup (both lower‑ and upper‑case)
        final Set<Character> vowels = Set.of(
            'a', 'e', 'i', 'o', 'u',
            'A', 'E', 'I', 'O', 'U'
        );

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // Skip vowels – we only count consonants
            if (vowels.contains(ch)) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbor = false;
            if (i > 0 && vowels.contains(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour if left didn't give a vowel
            if (!hasVowelNeighbor && i < len - 1 && vowels.contains(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));           // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

