class SeriesSum {

    /**
     * Calculates the sum of the squares of the first {@code number} positive integers:
     * 1² + 2² + 3² + … + n².
     *
     * <p>This method is <strong>unconditionally thread‑safe</strong>:
     * it does not maintain any mutable state and therefore can be called
     * concurrently from multiple threads without any external synchronization.
     *
     * @param number the number of terms to include (must be non‑negative)
     * @return the sum of squares of the first {@code number} integers
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative: " + number);
        }

        // Use long to avoid intermediate overflow, then cast to int.
        // The result fits in int for reasonably small inputs; for large n
        // the caller should consider using a larger return type.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        return (int) sum;
    }
}

