class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     *
     * The sequence of NSW primes begins: 3, 7, 17, 41, 239, 577, 8119, …
     * This implementation uses 1‑based indexing:
     *   newmanPrime(1) → 3,
     *   newmanPrime(2) → 7,
     *   newmanPrime(3) → 17,
     *   …
     *
     * @param n the index (must be ≥ 1) of the desired NSW prime
     * @return the n‑th Newman‑Shanks‑Williams prime
     * @throws IllegalArgumentException if n < 1
     *
     * This method is <strong>thread‑safe</strong> because it does not
     * rely on any mutable shared state.
     */
    public static int newmanPrime(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n must be at least 1");
        }

        // Q_0 = 1 (not prime), Q_1 = 3
        long prev2 = 1L; // Q_{i-2}
        long prev1 = 3L; // Q_{i-1}
        int primeCount = 0;

        for (int i = 1; ; i++) {
            long q;
            if (i == 1) {
                q = prev1;               // Q_1 = 3
            } else {
                q = 2 * prev1 + prev2;   // Q_i = 2*Q_{i-1} + Q_{i-2}
            }

            if (isPrime(q)) {
                primeCount++;
                if (primeCount == n) {
                    // For reasonable n the result fits in int.
                    return (int) q;
                }
            }

            // Prepare next iteration
            prev2 = prev1;
            prev1 = q;
        }
    }

    /**
     * Simple deterministic primality test for positive long values.
     * Sufficient for the range of numbers produced by newmanPrime.
     */
    private static boolean isPrime(long num) {
        if (num <= 1) return false;
        if (num <= 3) return true;
        if (num % 2 == 0) return false;

        long limit = (long) Math.sqrt(num);
        for (long d = 3; d <= limit; d += 2) {
            if (num % d == 0) return false;
        }
        return true;
    }

    // Optional test driver
    public static void main(String[] args) {
        // Example calls (1‑based indexing)
        System.out.println(newmanPrime(1)); // 3
        System.out.println(newmanPrime(2)); // 7
        System.out.println(newmanPrime(3)); // 17
        System.out.println(newmanPrime(4)); // 41
    }
}

