import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that starts at the top‑left
     * corner of the given square matrix and ends at the bottom‑right corner,
     * moving only right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the matrix (may be omitted; the method uses cost.size())
     * @return the maximum average, or 0.0 if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Defensive checks
        if (cost == null || cost.isEmpty() || cost.get(0).isEmpty()) {
            return 0.0;
        }

        int N = cost.size();               // actual size (could use the parameter n)
        long[] dp = new long[N];           // dp[j] = best sum to (current row, column j)

        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                int val = cost.get(i).get(j);   // cost[i][j]

                if (i == 0 && j == 0) {
                    // starting cell
                    dp[j] = val;
                } else if (i == 0) {
                    // first row – can only come from the left
                    dp[j] = dp[j - 1] + val;
                } else if (j == 0) {
                    // first column – can only come from above
                    dp[j] = dp[j] + val;   // dp[j] still holds the value from the previous row
                } else {
                    // take the better of the two possible predecessors
                    dp[j] = val + Math.max(dp[j], dp[j - 1]);
                }
            }
        }

        // The path always contains exactly (2 * N - 1) cells
        double average = (double) dp[N - 1] / (2 * N - 1);
        return average;
    }

    // --------------------------------------------------------------------
    // Optional test driver
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * <p>A character is counted only if it is <b>not</b> a vowel (a, e, i, o, u) and
     * at least one of its immediate neighbours (the character to the left or the right)
     * is a vowel. The string is treated as case‑insensitive.
     *
     * @param testStr the input string
     * @return the number of such characters
     *
     * @see #isVowel(char)
     *
     * <p><b>Thread‑safety:</b> This method is thread‑safe because it does not rely on
     * any mutable shared state. All intermediate data are local to the method’s stack.
     */
    public static int countVowels(String testStr) {
        // Guard against null or too short strings
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        // Pre‑compute a set of vowels (both lower‑ and upper‑case)
        final String VOWELS = "aeiouAEIOU";

        char[] chars = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];

            // Skip vowels – we only count consonants that are adjacent to a vowel
            if (VOWELS.indexOf(c) != -1) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0 && VOWELS.indexOf(chars[i - 1]) != -1) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour (only if we haven't already found a vowel neighbour)
            if (!hasVowelNeighbor && i < chars.length - 1 && VOWELS.indexOf(chars[i + 1]) != -1) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Optional helper (not strictly required but kept for clarity)
    private static boolean isVowel(char c) {
        return "aeiouAEIOU".indexOf(c) != -1;
    }

    // Simple test driver (can be removed when integrating into a larger codebase)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

