import java.util.*;
import java.math.*;

class NewmanPrime {
    // Cache for previously computed values
    private static final Map<Integer, BigInteger> cache = new HashMap<>();

    // Private lock object – cannot be accessed from outside the class
    private static final Object lock = new Object();

    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2·a(n‑1) + a(n‑2)  for n ≥ 2
     *
     * For the given examples:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n the index (starting from 0) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Quick cache lookup (outside the synchronized block for read‑most scenarios)
        synchronized (lock) {
            if (cache.containsKey(n)) {
                return cache.get(n).intValue();
            }
        }

        // Compute the sequence using BigInteger to avoid overflow
        BigInteger a0 = BigInteger.ONE; // a(0)
        BigInteger a1 = BigInteger.ONE; // a(1)
        BigInteger a  = BigInteger.ONE; // a(0) and a(1) are both 1

        for (int i = 2; i <= n; i++) {
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            a0 = a1;
            a1 = a;
        }

        // Convert to int (the problem expects an int; the inputs are small enough)
        int result = a.intValue();

        // Store in cache while holding the lock
        synchronized (lock) {
            cache.put(n, a);
        }

        return result;
    }
}

