import java.lang.*;

class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron with edge length `num`.
     *
     * The volume V of a regular tetrahedron with side length a is:
     *     V = a³ / (6·√2)
     *
     * @param num the length of each edge (must be non‑negative)
     * @return the volume rounded to two decimal places, as a {@code Double}
     */
    public static Double volumeTetrahedron(int num) {
        double a = num;                     // edge length
        // V = a³ / (6 * sqrt(2))
        double volume = Math.pow(a, 3.0) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places and autobox to Double
        return Math.round(volume * 100.0) / 100.0;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

