class TextMatchWordzMiddle {
    /** Private lock object – used to synchronize access (see Item 78). */
    private static final Object lock = new Object();

    /**
     * Returns "Found a match!" if any word in the supplied text contains the
     * letter 'z' neither at the start nor at the end of the word; otherwise
     * returns "Not matched!".
     *
     * @param text the input string to examine
     * @return the appropriate message
     */
    public static String textMatchWordzMiddle(String text) {
        // Synchronize to satisfy the private‑lock idiom (even though the
        // method has no mutable state, it demonstrates the pattern).
        synchronized (lock) {
            // Pattern for whole words: word boundaries + one or more word chars
            Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
            Matcher matcher = wordPattern.matcher(text);

            while (matcher.find()) {
                String word = matcher.group();

                // A word must be long enough to have a 'z' not at the edges.
                // It must contain at least one 'z' and the 'z' must not be
                // the first or last character.
                if (word.length() >= 3
                        && word.contains("z")
                        && !word.startsWith("z")
                        && !word.endsWith("z")) {
                    return "Found a match!";
                }
            }
            return "Not matched!";
        }
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));    // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  .")); // "Not matched!"
    }
}

