class CountVowels {
    // Private lock object to illustrate concurrency advice (unconditionally thread‑safe class)
    private static final Object lock = new Object();

    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        synchronized(lock) {
            if (testStr == null || testStr.isEmpty()) {
                return 0;
            }
            int n = testStr.length();
            int count = 0;
            // We only look at characters up to the second‑last position;
            // the last character is never counted.
            for (int i = 0; i < n - 1; i++) {
                char ch = testStr.charAt(i);
                if (isVowel(ch)) {
                    // The specification asks for characters that are not vowels.
                    continue;
                }
                boolean hasVowelNeighbor = false;
                // Check left neighbor (if not first character)
                if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // Check right neighbor (guaranteed to exist because we stop at n-2)
                if (!hasVowelNeighbor && isVowel(testStr.charAt(i + 1))) {
                    hasVowelNeighbor = true;
                }
                if (hasVowelNeighbor) {
                    count++;
                }
            }
            return count;
        }
    }

    /** Helper that returns true for vowels a, e, i, o, u (case‑insensitive) */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

