class SeriesSum {
    // Private lock object – inaccessible to clients, prevents synchronization interference
    private static final Object lock = new Object();

    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound of the series (n ≥ 0)
     * @return the sum of squares from 1 to number
     *
     * <p>Examples:</p>
     * <ul>
     *   <li>seriesSum(6) → 91</li>
     *   <li>seriesSum(7) → 140</li>
     *   <li>seriesSum(12) → 650</li>
     * </ul>
     */
    public static int seriesSum(int number) {
        // Guard the computation with the private lock
        synchronized (lock) {
            if (number <= 0) {
                return 0;
            }

            // Use the closed‑form formula: n(n+1)(2n+1)/6
            long sum = (long) number * (number + 1) * (2L * number + 1) / 6;
            return (int) sum;   // the problem expects an int return type
        }
    }
}

