class NewmanPrime {
    // Lazy initialization: cache the sequence values
    private static final List<Long> cache = new ArrayList<>();

    static {
        // Initialize with a(1) = 1, a(2) = 3
        cache.add(0L); // dummy for 0-index
        cache.add(1L);
        cache.add(3L);
    }

    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Compute additional terms lazily if needed
        while (cache.size() <= n) {
            int i = cache.size() - 1; // current last index
            long next = 2 * cache.get(i) + cache.get(i - 1);
            cache.add(next);
        }

        return cache.get(n).intValue();
    }
}

