/**
 * Utility class that demonstrates a simple word‑matching routine.
 *
 * The problem: “Write a function that matches a word containing 'z',
 * not at the start or end of the word.”
 *
 * The implementation follows the advice given in Item 83 (use lazy
 * initialization judiciously) by lazily initialising the regular‑expression
 * Pattern that is used to locate words.
 */
public class TextMatchWordzMiddle {

    // Lazy‑initialised Pattern (holder idiom – thread‑safe, lazy, no synchronization)
    private static class PatternHolder {
        // \\b\\w+\\b matches a whole word consisting of word characters (letters, digits, _)
        static final Pattern WORD_PATTERN = Pattern.compile("\\b\\w+\\b");
    }

    /**
     * Returns the lazily initialised Pattern for word matching.
     */
    private static Pattern getWordPattern() {
        return PatternHolder.WORD_PATTERN;
    }

    /**
     * Determines whether the supplied text contains a word that has the
     * letter 'z' somewhere other than the first or last position.
     *
     * @param text the input string to examine
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        Matcher matcher = getWordPattern().matcher(text);
        while (matcher.find()) {
            String word = matcher.group();
            int len = word.length();

            // A word must have at least three characters to be able to contain
            // a non‑start/non‑end 'z'.
            if (len >= 3) {
                // Scan the interior of the word (index 1 … len‑2) for a 'z'.
                for (int i = 1; i < len - 1; i++) {
                    if (word.charAt(i) == 'z') {
                        return "Found a match!";
                    }
                }
            }
        }
        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // A tiny test driver (feel free to remove / comment out in production)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        String[] tests = {
            "pythonzabc.",
            "xyzabc.",
            "  lang  .",
            "noZhere",
            "zabcde",
            "abcz",
            "azbzc",
            "123z45",
            "   z   "
        };
        for (String t : tests) {
            System.out.printf("%-20s -> %s%n", "\"" + t + "\"", textMatchWordzMiddle(t));
        }
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value among all paths from the top‑left
     * corner to the bottom‑right corner of the matrix, moving only right or down.
     *
     * @param cost the n×n matrix of non‑negative integers
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a {@code Double}, or {@code null} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ----- basic validation -------------------------------------------------
        if (cost == null || n <= 0) {
            return null;
        }
        for (int i = 0; i < n; i++) {
            if (cost.get(i) == null || cost.get(i).size() != n) {
                return null;                     // malformed input
            }
        }

        // ----- dynamic programming (max sum to each cell) ----------------------
        // dp[i][j] = maximum sum of a path that ends at cell (i, j)
        long[][] dp = new long[n][n];

        // initialise the start cell
        dp[0][0] = cost.get(0).get(0);

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // remaining cells – take the best of the two predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                           + cost.get(i).get(j);
            }
        }

        // ----- compute the average -----------------------------------------------
        // Every path from (0,0) to (n‑1,n‑1) has exactly (2*n‑1) cells.
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2 * n - 1);

        return average;   // boxed Double as required by the signature
    }
}

