class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Null or empty string -> no characters to count
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with a lower‑case copy for case‑insensitive vowel detection
        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char c = s.charAt(i);

            // Skip vowels – we only count consonants that are next to a vowel
            if (isVowel(c)) {
                continue;
            }

            // Check left neighbour
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                count++;
                continue; // no need to check the right neighbour
            }

            // Check right neighbour
            if (i < len - 1 && isVowel(s.charAt(i + 1))) {
                count++;
            }
        }

        return count;
    }

    /** Helper: returns true if the given character is a vowel (a, e, i, o, u). */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    // Optional main method for quick manual testing
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));        // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));          // 5
    }
}

