class VolumeTetrahedron {

    /**
     * Lazy‑initialization holder class for the constant sqrt(2)/12.
     * The inner class is not loaded until {@code SQRT2_OVER_12} is first accessed,
     * which satisfies the “lazy initialization holder class idiom” advice.
     */
    private static class Holder {
        // The factor √2 / 12 appears in the formula V = (√2 / 12) * a³
        static final double SQRT2_OVER_12 = Math.sqrt(2.0) / 12.0;
    }

    /**
     * Calculates the volume of a regular tetrahedron whose edge length is {@code num}.
     *
     * The volume of a regular tetrahedron with edge length a is:
     *     V = a³ * √2 / 12
     *
     * The result is rounded to two decimal places to match the expected output.
     *
     * @param num the edge length of the tetrahedron (must be non‑negative)
     * @return the volume rounded to two decimal places, as a {@link Double}
     */
    public static Double volumeTetrahedron(int num) {
        // Use the lazily‑initialised constant
        double factor = Holder.SQRT2_OVER_12;

        // V = factor * a³
        double volume = factor * num * num * num;

        // Round to two decimal places (e.g., 117.851… → 117.85)
        volume = Math.round(volume * 100.0) / 100.0;

        return volume;   // auto‑boxed to Double
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

