public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if the input text contains a word that
     * has the letter 'z' (or 'Z') somewhere other than the first or last
     * character of that word. Otherwise returns "Not matched!".
     *
     * @param text the input string to be examined
     * @return    the appropriate result message
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split the input on anything that is not a letter.
        // This yields an array of all words (empty strings are ignored below).
        String[] words = text.split("[^a-zA-Z]+");

        for (String word : words) {
            if (word.isEmpty()) {
                continue;               // skip possible empty tokens at ends
            }

            // Look for 'z' (case‑insensitive) inside the word
            String lower = word.toLowerCase();
            int idx = lower.indexOf('z');

            // idx != -1  → the word contains a 'z'
            // idx != 0   → 'z' is not the first character
            // idx != word.length() - 1 → 'z' is not the last character
            if (idx != -1 && idx != 0 && idx != word.length() - 1) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    // ---- simple manual test harness -------------------------------------------------
    public static void main(String[] args) {
        String[] tests = {
            "pythonzabc.",
            "xyzabc.",
            "  lang  .",
            "abcze",
            "zabc",
            "abcz",
            "aZb",          // uppercase Z
            "no z here",
            "one.z two.z"
        };

        for (String t : tests) {
            System.out.printf("%-20s -> %s%n", "\"" + t + "\"", textMatchWordzMiddle(t));
        }
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner and ends at the bottom‑right corner of the given
     * n×n cost matrix.  Movement is allowed only to the right or down.
     *
     * @param cost  list of rows, each row a list of integers
     * @param n     size of the square matrix
     * @return      maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // total number of cells visited on any path = 2*n - 1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // Simple manual test (can be removed when integrating into a larger project)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11));
