class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2 * a(n‑1) + a(n‑2)  for n ≥ 2.
     *
     * This yields the numerators of the convergents of √2:
     * 1, 1, 3, 7, 17, 41, 99, …
     *
     * @param n index (0‑based) of the term to return
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute the sequence iteratively using long to avoid overflow
        // (the result fits into int for the typical range of n)
        long prev2 = 1L; // a(0)
        long prev1 = 1L; // a(1)
        long current = 0L;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            // shift the window for the next iteration
            prev2 = prev1;
            prev1 = current;
        }

        // The problem’s examples all fit in int; cast safely
        return (int) current;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

