class Maxaverageofpath {
    /**
     * Finds a path with the maximum average over all existing paths
     * for the given square matrix of size n*n.
     *
     * The path starts at (0,0) and ends at (n‑1,n‑1) and may only move
     * right or down. The average is computed as
     *     (maximum sum of the path) / (2*n - 1)
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     the dimension of the square matrix
     * @return      the maximum possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] holds the maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Initialize the starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first column (can only come from the cell above)
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the first row (can only come from the cell to the left)
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The maximum sum from start to finish
        long maxSum = dp[n - 1][n - 1];

        // Number of cells visited on any such path = 2*n - 1
        int pathLength = 2 * n - 1;

        // Compute the average as a double
        double average = maxSum / (double) pathLength;

        return average;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
