class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' (case‑insensitive) somewhere other than the first or last
     * character of the word. Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") → "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     → "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   → "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern to capture contiguous letters (words) – punctuation and
        // whitespace act as delimiters.
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();           // the whole word
            int len = word.length();

            // A 'z' can only be “in the middle” if the word is at least 3 characters long.
            if (len >= 3) {
                // Extract the part that is neither the first nor the last character.
                String middle = word.substring(1, len - 1).toLowerCase();
                if (middle.contains("z")) {
                    return "Found a match!";
                }
            }
        }
        return "Not matched!";
    }

    // --------------------------------------------------------------------
    // Simple manual test (feel free to remove / comment out in production)
