public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path from the top‑left
     * corner to the bottom‑right corner of the given n×n cost matrix.
     * Movement is restricted to steps to the right or down.
     *
     * @param cost the n×n matrix of non‑negative integers
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average (as a {@code Double}) over all valid paths
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = maximum sum to reach cell (i, j) from (0,0)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long cell = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = cell;                     // start cell
                } else {
                    long best = Long.MIN_VALUE;
                    if (i > 0) best = Math.max(best, dp[i - 1][j]); // from above
                    if (j > 0) best = Math.max(best, dp[i][j - 1]); // from left
                    dp[i][j] = cell + best;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // A path from (0,0) to (n‑1,n‑1) using only right/down moves
        // always contains exactly (2*n - 1) cells.
        double average = maxSum / (2.0 * n - 1.0);
        return average;
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

