class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * For n = 3 the result is 7, for n = 4 it is 17, for n = 5 it is 41, …
     *
     * @param n position in the sequence (1‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Use BigInteger to avoid overflow for larger n.
        BigInteger s0 = BigInteger.ONE; // S0 = 1
        BigInteger s1 = BigInteger.ONE; // S1 = 1

        // Compute S2 … Sn
        for (int i = 2; i <= n; i++) {
            BigInteger cur = s1.multiply(BigInteger.valueOf(2)).add(s0);
            s0 = s1;
            s1 = cur;
        }

        // s1 now holds Sn.  Convert to int (the test cases stay within int range).
        return s1.intValue();
    }
}

