class CountAlphaDigSpl {
    /**
     * Write a function to count alphabets, digits and special characters in a given string.
     *
     * > countAlphaDigSpl("abc!@#123")
     * [3, 3, 3]
     * > countAlphaDigSpl("dgsuy@#$%&1255")
     * [5, 4, 5]
     * > countAlphaDigSpl("fjdsif627348#%$^&")
     * [6, 6, 5]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Handle null or empty input gracefully
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alphaCount = 0;
        int digitCount = 0;
        int specialCount = 0;

        for (int i = 0; i < string.length(); i++) {
            char ch = string.charAt(i);
            if (Character.isLetter(ch)) {
                alphaCount++;
            } else if (Character.isDigit(ch)) {
                digitCount++;
            } else {
                specialCount++;
            }
        }

        // Return the counts as a List in the required order
        return Arrays.asList(alphaCount, digitCount, specialCount);
    }

    // Optional: simple test driver
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

