import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * By definition the sequence is:
     *   a0 = 1, a1 = 1
     *   a_n = 2 * a_{n-1} + a_{n-2}   (n >= 2)
     *
     * The examples show that for n = 3, 4, 5 the returned values are 7, 17, 41
     * which are exactly a3, a4 and a5 of the recurrence.
     *
     * @param n the index (1‑based) of the desired term; n must be >= 1
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // The first two values of the sequence
        long a0 = 1; // a_0
        long a1 = 1; // a_1

        // Handle the trivial cases
        if (n == 1) {
            return (int) a0; // a_0 = 1
        }
        if (n == 2) {
            return (int) a1; // a_1 = 1
        }

        long current = 0;
        // Compute a_n iteratively
        for (int i = 3; i <= n; i++) {
            current = 2 * a1 + a0; // a_i = 2*a_{i-1} + a_{i-2}
            a0 = a1;
            a1 = current;
        }

        // The problem expects an int; the test values fit in int range
        return (int) current;
    }

    // --------------------------------------------------------------------
    // Optional helper: quick primality test (not required by the task,
    // but useful if you ever need to verify that the returned value is prime)
    // --------------------------------------------------------------------
    private static boolean isPrime(long value) {
        if (value < 2) return false;
        if (value == 2) return true;
        if (value % 2 == 0) return false;
        long sqrt = (long) Math.sqrt(value);
        for (long i = 3; i <= sqrt; i += 2) {
            if (value % i == 0) return false;
        }
        return true;
    }

    // --------------------------------------------------------------------
    // Simple test driver (feel free to remove or comment out in production)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Example runs from the problem statement
        System.out.println(newmanPrime(3)); // → 7
        System.out.println(newmanPrime(4)); // → 17
        System.out.println(newmanPrime(5)); // → 41

        // Additional sanity checks
        System.out.println(newmanPrime(2)); // → 3 (a_2)
        System.out.println(newmanPrime(1)); // → 1 (a_0)
    }
}

/**
 * Removes characters at even positions (0‑based index 0,2,4,…)
 * and returns a string composed of the characters at odd indices.
 *
 * @param str1 the input string (may be null or empty)
 * @return a string containing the characters at odd positions,
 *         or an empty string if the input is null/empty
 */
public static String removeOdd(String str1) {
    // Guard against null or empty input
    if (str1 == null || str1.isEmpty()) {
        return "";
    }

    StringBuilder result = new StringBuilder();

    // Start from index 1 and step by 2 to pick only odd‑indexed characters
    for (int i = 1; i < str1.length(); i += 2) {
        result.append(str1.charAt(i));
    }

    return result.toString();
}

