import java.util.regex.*;

class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the letter 'z'
     * somewhere other than the first or last character; otherwise returns "Not matched!".
     *
     * @param text the input string to examine
     * @return the appropriate result message
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern to match a sequence of one or more letters (a word)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // the current word
            // Perform a case‑insensitive search for 'z'
            int idx = word.toLowerCase().indexOf('z');

            // If 'z' is present and is not at the first or last position
            if (idx != -1 && idx > 0 && idx < word.length() - 1) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));     // "Not matched!"
    }
}

import java.util.List;

/**
 * Computes the maximum average of a path that moves only right or down
 * from the top‑left corner to the bottom‑right corner of a square matrix.
 *
 * The average is defined as (sum of all visited cells) / (2·n – 1),
 * where n is the matrix dimension.
 */
public class Maxaverageofpath {

    /**
     * Returns the maximum average of a valid path in the given cost matrix.
     *
     * @param cost  a square matrix (List of rows) containing non‑negative integers
     * @param n     dimension of the matrix (cost.size() == n)
     * @return      the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Defensive programming: if the caller passed a mismatched n, infer it.
        if (cost == null || cost.isEmpty()) {
            return null;
        }
        if (n <= 0) {
            n = cost.size(); // use the actual size
        }

        // DP array – using double to avoid overflow for large sums.
        double[][] dp = new double[n][n];

        // Initialize the start cell.
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (只能往右).
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (只能往下).
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the DP table.
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Compute the average. The path always contains (2·n – 1) cells.
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1);

        return average;
    }

    // --------------------------------------------------------------------
    // A tiny test driver (not required for the solution, but useful for
    // verifying the examples from the problem statement).
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

import java.util.*;

class CountVowels {
    /**
     * Counts characters that are not vowels but have a vowel as a neighbour.
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Define vowels (both lower‑ and upper‑case)
        Set<Character> vowelSet = new HashSet<>(
                Arrays.asList('a', 'e', 'i', 'o', 'u',
                              'A', 'E', 'I', 'O', 'U'));

        int count = 0;
        for (int i = 0; i < testStr.length(); i++) {
            char ch = testStr.charAt(i);

            // Skip vowels themselves – we only count consonants
            if (vowelSet.contains(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0 && vowelSet.contains(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour if we haven't found a vowel yet
            if (!hasVowelNeighbor && i < testStr.length() - 1
                    && vowelSet.contains(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    // Simple test harness
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

