import java.math.BigInteger;

/**
 *  NewmanPrime – computes the n‑th term of the Newman‑Shanks‑Williams sequence.
 *
 *  The sequence is defined by:
 *      a(0) = 1, a(1) = 1
 *      a(n) = 2·a(n‑1) + a(n‑2)   for n ≥ 2
 *
 *  The values for n ≥ 2 begin 3, 7, 17, 41, 99, 239, … – the first few are prime.
 *
 *  The function returns the integer value; for very large n you can switch to
 *  BigInteger (see the commented‑out version below).
 */
public class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * @param n index (0‑based).  For n = 0 or 1 the result is 1.
     * @return the integer value of a(n).
     * @throws IllegalArgumentException if n is negative.
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // a(0) = 1, a(1) = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        int a0 = 1; // a(i‑2)
        int a1 = 1; // a(i‑1)
        int a  = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a  = 2 * a1 + a0; // recurrence
            a0 = a1;
            a1 = a;
        }
        return a;
    }

    /* -----------------------------------------------------------------
       If you need the sequence for very large indices, use BigInteger.
       Uncomment the following method and change the return type of
       newmanPrime to BigInteger.

    public static BigInteger newmanPrimeBig(int n) {
        if (n < 0) throw new IllegalArgumentException("n must be non‑negative");
        if (n == 0 || n == 1) return BigInteger.ONE;

        BigInteger a0 = BigInteger.ONE;
        BigInteger a1 = BigInteger.ONE;
        BigInteger a  = BigInteger.ZERO;

        for (int i = 2; i <= n; i++) {
            a = a1.shiftLeft(1).add(a0); // 2*a1 + a0
            a0 = a1;
            a1 = a;
        }
        return a;
    }
    ----------------------------------------------------------------- */

    // Simple sanity check – prints the first 11 values
    public static void main(String[] args) {
        for (int i = 0; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
