import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a monotonic path (right/down) from the
     * top‑left corner to the bottom‑right corner of the given n×n cost matrix.
     *
     * @param cost  list of rows, each row a list of integers representing cell costs
     * @param n     size of the square matrix (number of rows/columns)
     * @return      the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation – you can adjust or remove if inputs are guaranteed valid
        if (cost == null || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = max sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long cellValue = cost.get(i).get(j);   // cost[i][j]

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cellValue;
                } else {
                    long best = Long.MIN_VALUE;
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]); // from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]); // from left
                    }
                    dp[i][j] = cellValue + best;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // Every monotonic path has exactly (2*n - 1) cells
        double average = maxSum / (double) (2 * n - 1);

        return average; // auto‑boxed to Double
    }

    // --------------------------------------------------------------------
    // Optional test driver (matches the examples from the problem statement)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

