class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(n) = 2 * a(n‑1) + a(n‑2)  for n >= 2
     *
     * @param n the index (0‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        // Basic cases – the first two terms are 1
        if (n <= 1) {
            return 1;               // a(0) = a(1) = 1
        }

        // Use long to avoid premature overflow while iterating
        long prev2 = 1; // a(n‑2)
        long prev1 = 1; // a(n‑1)
        long cur = 0;   // a(n)

        for (int i = 2; i <= n; i++) {
            cur = 2 * prev1 + prev2;
            // shift the window forward
            prev2 = prev1;
            prev1 = cur;
        }

        // The problem expects an int return type; cast safely for the test range
        return (int) cur;
    }
}

