public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner, ends at the bottom‑right corner and moves only
     * right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    size of the matrix
     * @return the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = max sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = val;                     // start cell
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + val;      // first row
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + val;      // first column
                } else {
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        return Double.valueOf(average);
    }
}

