class Maxaverageofpath {
    /**
     * Find a path with the maximum average over all existing paths
     * for the given square matrix of size n*n.
     *
     * The matrix is represented as a List of Lists of Integer.
     * Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average value of any valid path, or null if input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against bad input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table holds the maximum sum to reach each cell.
        // Use long to avoid overflow for large n or large cell values.
        long[][] dp = new long[n][n];

        // First cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The maximum sum to reach the bottom‑right corner
        long maxSum = dp[n - 1][n - 1];

        // Every path from top‑left to bottom‑right has exactly (2*n - 1) cells
        int pathLength = 2 * n - 1;

        // Compute the average as a double
        double average = (double) maxSum / pathLength;

        // Return the result as a Double object
        return Double.valueOf(average);
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
