class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // The Newman–Shanks–Williams sequence is defined by:
        // a(0) = 1, a(1) = 1
        // a(n) = 2 * a(n-1) + a(n-2) for n >= 2
        // The sequence yields: 1, 1, 3, 7, 17, 41, 99, ...

        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        int a0 = 1; // a(i-2)
        int a1 = 1; // a(i-1)
        int a = 0;  // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // Compute a(i)
            a0 = a1;         // Shift for next iteration
            a1 = a;
        }
        return a;
    }
}

