class RemoveOdd {
    /**
     * Removes characters at odd positions (1‑indexed) from the given string.
     *
     * Example:
     *   removeOdd("python") → "yhn"
     *   removeOdd("program") → "rga"
     *   removeOdd("language") → "agae"
     *
     * @param str1 the input string (may be null)
     * @return a new string containing only the characters at even positions,
     *         or null if the input is null
     */
    public static String removeOdd(String str1) {
        // Guard against null to satisfy defensive programming (Item 49)
        if (str1 == null) {
            return null;
        }

        // Use StringBuilder for efficient concatenation
        StringBuilder result = new StringBuilder(str1.length());

        // i == 0 → 1st character (odd position) → drop it
        // i == 1 → 2nd character (even position) → keep it
        // i == 2 → 3rd character (odd position) → drop it
        // …
        for (int i = 0; i < str1.length(); i++) {
            if (i % 2 == 1) {               // keep characters at even indices (2nd,4th,…)
                result.append(str1.charAt(i));
            }
        }

        return result.toString();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));   // "yhn"
        System.out.println(removeOdd("program"));  // "rga"
