/**
 * Solution for “Maximum average of a path in a square matrix”.
 *
 * The algorithm uses dynamic programming to find the path with the greatest
 * sum from (0,0) to (n‑1,n‑1) while moving only right or down.
 * Since all valid paths have the same length (2·n‑1 cells), the path with the
 * largest sum also yields the largest average.
 *
 * Note: This class does *not* implement {@link java.io.Serializable},
 * in line with the recommendation that implementing Serializable carries
 * significant costs (see the provided programming advice).
 */
public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts at the
     * top‑left cell and ends at the bottom‑right cell of the given n×n matrix.
     * Movement is allowed only to the right or downwards.
     *
     * @param cost the n×n matrix of integer costs (as a list of rows)
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a {@link Double}, or {@code null} if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // DP array holds the maximum sum to reach each cell (i, j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the DP table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The maximum sum to reach the bottom‑right corner
        long maxSum = dp[n - 1][n - 1];

        // Every path contains exactly (2 * n - 1) cells
        int pathLength = 2 * n - 1;

        // Compute the average as a double
        double average = (double) maxSum / pathLength;

        // Auto‑boxing to Double (the method signature requires Double)
        return average;
    }

