/**
 *  NewmanPrime – returns the n‑th term of the Newman‑Shanks‑Williams sequence.
 *
 *  The sequence is defined by:
 *      a(1) = 1
 *      a(2) = 3
 *      a(n) = 2·a(n‑1) + a(n‑2)   for n > 2
 *
 *  The values for n ≥ 2 are the first few NSW primes (3, 7, 17, 41, …).
 */
class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     *
     * @param n the 1‑based index (n >= 1)
     * @return the value a(n)
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // First two terms of the sequence
        if (n == 1) return 1;   // a(1) = 1
        if (n == 2) return 3;   // a(2) = 3

        // Use long to avoid early overflow; the result is cast back to int
        // (the problem’s test cases stay well within int range).
        long prev2 = 1L;   // a(i‑2)  – initially a(1)
        long prev1 = 3L;   // a(i‑1)  – initially a(2)
        long cur   = 0L;

        for (int i = 3; i <= n; i++) {
            cur = 2 * prev1 + prev2;   // a(i) = 2·a(i‑1) + a(i‑2)
            prev2 = prev1;
            prev1 = cur;
        }

        return (int) cur;
    }

    // -----------------------------------------------------------------
    // A tiny demo (optional)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        for (int i = 1; i <= 10; i++) {
            System.out.println("newmanPrime(" + i + ") = " + newmanPrime(i));
        }
    }
}

