 */
class CountAlphaDigSpl {

    /**
     * Returns a list containing three integers:
     *   - number of alphabetic characters (A‑Z, a‑z)
     *   - number of digit characters (0‑9)
     *   - number of all other characters (special symbols)
     *
     * @param string the input text (may be null)
     * @return a List<Integer> with the three counts in the order
     *         [alphabets, digits, special characters]
     *
     * Example:
     * <pre>
     * countAlphaDigSpl("abc!@#123") → [3, 3, 3]
     * countAlphaDigSpl("dgsuy@#$%&1255") → [5, 4, 5]
     * countAlphaDigSpl("fjdsif627348#%$^&") → [6, 6, 5]
     * </pre>
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Defensive handling for null input
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alpha = 0;
        int digit = 0;
        int special = 0;

        for (char ch : string.toCharArray()) {
            if (Character.isLetter(ch)) {
                alpha++;
            } else if (Character.isDigit(ch)) {
                digit++;
            } else {
                // Anything that is neither a letter nor a digit is considered "special"
                special++;
            }
        }

        // Returns an immutable list with the three counts
        return Arrays.asList(alpha, digit, special);
