 * with the letter 'z' somewhere other than the first or last position.
 *
 * The class is marked Serializable to satisfy the serialization advice,
 * even though it holds no instance state.
 */
public class TextMatchWordzMiddle implements Serializable {

    private static final long serialVersionUID = 1L;

    /**
     * Determines whether the supplied text contains a word that has the
     * letter 'z' in a position other than the first or last character.
     *
     * @param text the input string to be examined (may be null)
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern to match sequences of letters (i.e., words)
        Pattern wordPattern = Pattern.compile("[a-zA-Z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            if (hasMiddleZ(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * Helper that returns true if the given word contains the letter 'z'
     * at any index other than 0 or length‑1.
     *
     * @param word the word to test
     * @return true if a middle 'z' exists, false otherwise
     */
    private static boolean hasMiddleZ(String word) {
        int len = word.length();
        // A middle position is only possible when the word is at least 3 chars long
        if (len < 3) {
            return false;
        }
        // Scan characters from index 1 up to len‑2 (inclusive)
        for (int i = 1; i < len - 1; i++) {
            if (word.charAt(i) == 'z') {
                return true;
            }
        }
        return false;
    }

    // --------------------------------------------------------------------
    // Optional simple test driver (can be removed when integrating)
