public class Maxaverageofpath {

    /**
     * Returns the maximum average of all paths that go from the top‑left
     * corner to the bottom‑right corner of the square matrix `cost`.
     * Movement is allowed only to the right or down.
     *
     * @param cost a square n×n matrix represented as a list of rows,
     *             each row being a list of integers
     * @param n    the dimension of the matrix (number of rows/columns)
     * @return the highest possible average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation – feel free to adjust the policy for invalid input
        if (cost == null || cost.isEmpty() || cost.get(0).isEmpty()) {
            return null;
        }

        // dp[i][j] holds the maximum sum reachable at (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cur = cost.get(i).get(j);          // current cell value
                if (i == 0 && j == 0) {
                    // Starting point
                    dp[i][j] = cur;
                } else {
                    long best = Long.MIN_VALUE;
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]); // from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]); // from left
                    }
                    dp[i][j] = cur + best;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // Every path from (0,0) to (n‑1,n‑1) contains exactly 2*n‑1 cells
        double average = (double) maxSum / (2 * n - 1);

        return average; // auto‑boxed to Double
    }

    // --------------------------------------------------------------------
    // Optional test driver (not required by the task, but useful for verification)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // expected: 7.2
    }
}

