import java.math.*;

/**
 * Class containing utilities for Newman‑Shanks‑Williams primes.
 */
class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams prime.
     * The sequence of NSW primes is: 2, 3, 7, 17, 41, 239, 577, 8119, …
     *
     * @param n the index (1‑based) of the NSW prime to return
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n is less than 1
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        // The first NSW prime is 2, which does not appear in the recurrence.
        if (n == 1) {
            return 2;
        }

        // Generate the sequence a(0)=1, a(1)=1, a(k)=2*a(k-1)+a(k-2)
        int a0 = 1; // a(k-2)
        int a1 = 1; // a(k-1)
        int count = 0; // number of primes found in the sequence (excluding the initial 2)

        while (true) {
            int a2 = 2 * a1 + a0; // compute next term a(k)

            // shift the window
            a0 = a1;
            a1 = a2;

            // Test a2 for primality
            if (isPrime(a2)) {
                count++;
                // We need the (n‑1)‑th prime from the recurrence because the first prime (2) is handled separately.
                if (count == n - 1) {
                    return a2;
                }
            }
        }
    }

    /**
     * Simple primality test for positive integers.
     *
     * @param number the integer to test
     * @return true if number is prime, false otherwise
     */
    private static boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        if (number <= 3) {
            return true;
        }
        if (number % 2 == 0 || number % 3 == 0) {
            return false;
        }
        // Check for factors of the form 6k ± 1 up to sqrt(number)
        for (int i = 5; i * i <= number; i += 6) {
            if (number % i == 0 || number % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    // Optional simple test driver
    public static void main(String[] args) {
        // Example usage:
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

