import java.util.List;

/**
 * Computes the maximum average of a path that moves only right or down
 * from the top‑left to the bottom‑right corner of a square matrix.
 */
public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a valid path.
     *
     * @param cost  list of n rows, each containing n integers
     * @param n     size of the square matrix (number of rows/columns)
     * @return      maximum average as a {@code Double}, or {@code null} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // defensive check – not required by the problem statement but harmless
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: double is used to avoid overflow for large sums
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // total number of cells in any valid path = 2·n – 1
        int pathLength = 2 * n - 1;
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / pathLength;

        return Double.valueOf(average);
    }
}

