/**
 * Utility class for counting characters that have vowels as neighbours.
 *
 * <p>The rule used is:
 * <ul>
 *   <li>Consider only characters that are <b>not</b> vowels (consonants).</li>
 *   <li>A consonant is counted if at least one of its immediate neighbours
 *       (the character to its left or the character to its right) is a vowel
 *       ({@code a, e, i, o, u}).</li>
 * </ul>
 *
 * <p>Examples:
 * <ul>
 *   <li>{@code countVowels("bestinstareels")} → 7</li>
 *   <li>{@code countVowels("partofthejourneyistheend")} → 12</li>
 *   <li>{@code countVowels("amazonprime")} → 5</li>
 * </ul>
 *
 * @author  (your name)
 * @version 1.0
 */
class CountVowels {

    /** Set of vowel characters (lower‑case). */
    private static final String VOWELS = "aeiou";

    /**
     * Counts consonants in the given string that have at least one vowel
     * as an immediate neighbour (left or right).
     *
     * @param testStr the input string; may be {@code null} or empty
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        // Defensive handling for null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            char lowerCh = Character.toLowerCase(ch);

            // Skip vowels – we only count consonants
            if (VOWELS.indexOf(lowerCh) != -1) {
                continue;
            }

            // Check left neighbour
            boolean leftIsVowel = false;
            if (i > 0) {
                char left = testStr.charAt(i - 1);
                leftIsVowel = VOWELS.indexOf(Character.toLowerCase(left)) != -1;
            }

            // Check right neighbour
            boolean rightIsVowel = false;
            if (i < len - 1) {
                char right = testStr.charAt(i + 1);
                rightIsVowel = VOWELS.indexOf(Character.toLowerCase(right)) != -1;
            }

            // Count if at least one neighbour is a vowel
            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }

    /** Simple driver to verify the examples. */
    public static void main(String[] args) {
        String[] tests = {
            "bestinstareels",
            "partofthejourneyistheend",
            "amazonprime"
        };
        int[] expected = {7, 12, 5};

        for (int i = 0; i < tests.length; i++) {
            int result = countVowels(tests[i]);
            System.out.printf("countVowels(\"%s\") = %d (expected %d)%n",
                    tests[i], result, expected[i]);
        }
    }
}

