class NewmanPrime {
    /**
     * Returns the n-th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2*a(n-1) + a(n-2) for n >= 2.
     * The examples given (newmanPrime(3) = 7, etc.) show that n is the index
     * in this sequence (starting from 0).
     *
     * @param n the index of the desired Newman–Shanks–Williams number
     * @return the value at index n in the Newman–Shanks–Williams sequence
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Use long to avoid overflow for moderate n; the result is cast to int.
        long a0 = 1; // a(n-2)
        long a1 = 1; // a(n-1)
        if (n == 0) return (int) a0;
        if (n == 1) return (int) a1;
        long a = 0;
        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;
            a0 = a1;
            a1 = a;
        }
        return (int) a;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

