public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if some word in the given text contains the
     * letter 'z' somewhere other than the first or last position of that word.
     * Otherwise returns "Not matched!".
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") -> "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     -> "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   -> "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Defensive programming – treat null or empty input as no match.
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // A word = maximal sequence of non‑whitespace characters.
        Pattern wordPattern = Pattern.compile("\\S+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();

            // Search for any 'z' that is not at position 0 or at the last position.
            int idx = word.indexOf('z');
            while (idx != -1) {
                if (idx > 0 && idx < word.length() - 1) {
                    return "Found a match!";
                }
                // Move to the next occurrence of 'z' in the same word.
                idx = word.indexOf('z', idx + 1);
            }
        }

        // No word satisfied the required condition.
        return "Not matched!";
    }

