public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that travels from the
     * top‑left to the bottom‑right of the given n×n matrix, moving only
     * right or down.  The average is computed as (maximum sum) / (2·n‑1).
     *
     * @param cost  the n×n matrix of integer costs
     * @param n     size of the square matrix
     * @return      the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.size() != n) {
            return null;
        }

        // DP table: dp[i][j] = max sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Maximum sum at the destination
        double maxSum = dp[n - 1][n - 1];

        // Every path has exactly (2 * n - 1) cells
        double average = maxSum / (2.0 * n - 1.0);

        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------
    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

