class CountVowels {
    /**
     * Counts characters that are not vowels and that have a vowel
     * as an immediate neighbour (either to the left or to the right).
     *
     * @param testStr the input string (may contain uppercase letters)
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowel characters (both lower‑ and upper‑case)
        final String VOWELS = "aeiouAEIOU";

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char c = testStr.charAt(i);

            // Skip vowels themselves – we only count non‑vowel characters
            if (VOWELS.indexOf(c) != -1) {
                continue;
            }

            // Check left neighbour
            if (i > 0 && VOWELS.indexOf(testStr.charAt(i - 1)) != -1) {
                count++;
                continue; // no need to check the right neighbour
            }

            // Check right neighbour
            if (i < len - 1 && VOWELS.indexOf(testStr.charAt(i + 1)) != -1) {
                count++;
            }
        }

        return count;
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));           // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

