class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a monotonic path
     * (moving only right or down) from the top‑left corner (0,0) to the
     * bottom‑right corner (n‑1,n‑1) of the given cost matrix.
     *
     * @param cost  a square n×n list of lists of integers representing the cell costs
     * @param n     the dimension of the matrix
     * @return      the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input
        if (cost == null || n <= 0) {
            return null;
        }

        // Ensure the matrix is actually n×n
        if (cost.size() != n) {
            return null;
        }

        // DP array: dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Initialize start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the DP table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The number of cells visited on any such path is 2*n - 1
        int totalCells = 2 * n - 1;
        double maxAverage = dp[n - 1][n - 1] / (double) totalCells;

        return maxAverage;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        // Example 2
        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // Expected: 6.2

        // Example 3
        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // Expected: 7.2
    }
}

