public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left cell
     * and ends at the bottom‑right cell of an n×n matrix.  The path may move
     * only right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@code Double}, or {@code null} if the
     *         input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- basic validation -------------------------------------------------
        if (cost == null || cost.size() != n) {
            return null;
        }
        for (List<Integer> row : cost) {
            if (row == null || row.size() != n) {
                return null;
            }
        }

        // ---- DP table ----------------------------------------------------------
        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average ---------------------------------------------------
        // Every monotonic path from (0,0) to (n‑1,n‑1) has exactly (2n‑1) cells.
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------------
    // Optional test driver (matches the examples from the problem statement)
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        List<List<Integer>> mat1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // Expected: 5.2

        List<List<Integer>> mat2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // Expected: 6.2

        List<List<Integer>> mat3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // Expected: 7.2
    }
}

import java.io.*;
