class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Work with a lower‑case copy so the check is case‑insensitive
        String s = testStr.toLowerCase();
        int n = s.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);

            // Skip vowels – we only count consonants
            if (isVowel(c)) {
                continue;
            }

            // Check if there is a vowel to the left or right
            boolean hasVowelNeighbor = false;
            if (i > 0 && isVowel(s.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            if (i < n - 1 && isVowel(s.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /** Helper: true if the character is one of the five English vowels. */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }

    // -----------------------------------------------------------------
    // Optional test driver
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

