public class CountAlphaDigSpl {

    /**
     * Counts alphabets, digits and special characters in a given string.
     *
     * @param str the input string (may be null)
     * @return a List containing [alphabets, digits, special characters]
     */
    public static List<Integer> countAlphaDigSpl(String str) {
        // Handle null input gracefully
        if (str == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alphabets = 0;
        int digits = 0;
        int specials = 0;

        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (Character.isLetter(ch)) {
                alphabets++;
            } else if (Character.isDigit(ch)) {
                digits++;
            } else {
                // Anything that is not a letter or digit is considered special
                specials++;
            }
        }

        // Return the three counts as an immutable list
        return Arrays.asList(alphabets, digits, specials);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));   // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

