/**
 * Utility class that provides a method to compute the length of the longest
 * word in a list of strings.
 *
 * The class implements {@link Serializable} to satisfy the recommendation
 * from Item 87/86 to declare an explicit serial version UID in every
 * serializable class.
 */
class LenLog implements Serializable {

    /** Serial version UID – recommended whenever a class implements Serializable. */
    private static final long serialVersionUID = 1L;

    /**
     * Returns the length of the longest word in the supplied list.
     *
     * @param list1 a list containing words (may be empty or {@code null})
     * @return the length of the longest word; returns {@code 0} if the list
     *         is {@code null} or empty
     */
    public static int lenLog(List<String> list1) {
        // Guard against null or empty input
        if (list1 == null || list1.isEmpty()) {
            return 0;
        }

        int maxLen = 0;
        for (String word : list1) {
            // Skip any null entries; they do not affect the maximum length
            if (word != null) {
                int len = word.length();
                if (len > maxLen) {
                    maxLen = len;
                }
            }
        }
        return maxLen;
    }

    /** Simple test driver – not required for the solution but useful for verification. */
    public static void main(String[] args) {
        System.out.println(lenLog(Arrays.asList("python", "PHP", "bigdata"))); // 7
        System.out.println(lenLog(Arrays.asList("a", "ab", "abc")));           // 3
        System.out.println(lenLog(Arrays.asList("small", "big", "tall")));    // 5
        System.out.println(lenLog(Collections.emptyList()));                  // 0
    }
}

public static int newmanPrime(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }
    // base cases
    if (n == 0 || n == 1) {
        return 1;
    }
    long a0 = 1; // a(0)
    long a1 = 1; // a(1)
    long a = 0;
    for (int i = 2; i <= n; i++) {
        a = 2 * a1 + a0; // a(i) = 2*a(i‑1) + a(i‑2)
        a0 = a1;
        a1 = a;
    }
    return (int) a;
}

