class TextMatchWordzMiddle {

    /**
     * Checks whether any word in the given text contains the letter 'z'
     * somewhere other than the first or last position.
     *
     * @param text the input string to be examined
     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") -> "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     -> "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   -> "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split the input on whitespace (one or more spaces/tabs/etc.)
        String[] tokens = text.split("\\s+");

        for (String token : tokens) {
            // Ignore empty tokens (should not happen after split)
            if (token.isEmpty()) {
                continue;
            }

            int len = token.length();

            // A 'z' can only be in the middle if the word has at least 3 characters
            if (len < 3) {
                continue;
            }

            int zIndex = token.indexOf('z');   // -1 if 'z' not present

            // Match if 'z' is present and its position is neither the first
            // nor the last character of the token
            if (zIndex != -1 && zIndex != 0 && zIndex != len - 1) {
                return "Found a match!";
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

    // ---- Simple test harness ----
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
        // Additional checks
        System.out.println(textMatchWordzMiddle("zabc"));          // Not matched! (z at start)
        System.out.println(textMatchWordzMiddle("abcz"));          // Not matched! (z at end)
        System.out.println(textMatchWordzMiddle("bza"));           // Found a match! (z in middle)
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

/**
 * Solution for the “maximum average of a path” problem.
 * The class is {@link Serializable} and declares an explicit
 * {@link serialVersionUID} as recommended in Item 87.
 */
class Maxaverageofpath implements Serializable {

    /** Serial version UID – recommended (Item 87). */
    private static final long serialVersionUID = 1L;

    /**
     * Returns the maximum possible average of a monotonic path
     * (moving only right or down) from the top‑left corner to the
     * bottom‑right corner of an n × n cost matrix.
     *
     * @param cost the n × n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average as a {@link Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP[i][j] – maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int val = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = val;
                } else if (i == 0) {
                    // First row – can only come from the left
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    // First column – can only come from above
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    // General case: choose the better predecessor
                    dp[i][j] = val + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // A monotonic path from (0,0) to (n‑1,n‑1) visits 2*n‑1 cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }
}

