/**
 * Utility class that provides a method to find the length of the longest word
 * in a list of strings.
 *
 * The class does not implement {@link Serializable}, so no
 * {@code serialVersionUID} is required (see the serialization advice).
 */
class LenLog {

    /**
     * Returns the length of the longest word in the given list.
     *
     * @param list1 a list of strings (may be {@code null} or empty)
     * @return the maximum length among the strings; {@code 0} if the list is
     *         {@code null} or empty
     */
    public static int lenLog(List<String> list1) {
        // Guard against null or empty input
        if (list1 == null || list1.isEmpty()) {
            return 0;
        }

        // Using streams – concise and clear
        return list1.stream()
                    .filter(Objects::nonNull)          // ignore null entries
                    .mapToInt(String::length)          // map each word to its length
                    .max()                              // get the largest length
                    .orElse(0);                        // fallback (won't happen because we filtered nulls)
    }

    // Simple test driver
    public static void main(String[] args) {
        // Example 1
        List<String> list1 = Arrays.asList("python", "PHP", "bigdata");
        System.out.println(lenLog(list1)); // 7

