class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * For the values shown in the examples (n = 3,4,5) this number is prime.
     *
     * @param n the index (0‑based) of the desired Newman‑Shanks‑Williams number
     * @return the value s(n)
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // s(0) = 1, s(1) = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        long a = 1; // s(0)
        long b = 1; // s(1)
        long c = 0;

        // Compute s(2) … s(n)
        for (int i = 2; i <= n; i++) {
            c = 2 * b + a; // s(i) = 2*s(i‑1) + s(i‑2)
            a = b;
            b = c;
        }

        // The problem’s examples (n = 3,4,5) return 7, 17, 41 – all prime.
        return (int) b;
    }
}

