class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null or too‑short strings
        if (testStr == null || testStr.length() <= 1) {
            return 0;
        }

        // Helper to test whether a character is a vowel (case‑insensitive)
        final String vowels = "aeiou";

        char[] ch = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < ch.length; i++) {
            char c = Character.toLowerCase(c);

            // We only consider non‑vowel characters
            if (vowels.indexOf(c) == -1) {
                boolean hasVowelNeighbor = false;

                // Check left neighbour
                if (i - 1 >= 0 && vowels.indexOf(Character.toLowerCase(ch[i - 1])) != -1) {
                    hasVowelNeighbor = true;
                }
                // Check right neighbour
                if (i + 1 < ch.length && vowels.indexOf(Character.toLowerCase(ch[i + 1])) != -1) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

