class LenLog {
    /**
     * Returns the length of the longest string in the supplied list.
     *
     * @param list1 a list of strings (may contain {@code null} elements)
     * @return the maximum length among the non‑null strings; {@code 0} if the
     *         list is {@code null} or empty or contains only {@code null}s
     */
    public static int lenLog(List<String> list1) {
        // Defensive check: the list itself must not be null
        if (list1 == null) {
            return 0;
        }

        int maxLen = 0;
        for (String s : list1) {
            // Defensive check: ignore null elements
            if (s != null) {
                int len = s.length();   // String.length() is O(1)
                if (len > maxLen) {
                    maxLen = len;
                }
            }
        }
        return maxLen;
    }

    /*--------------------------------------------------------------
     * Alternative one‑liner using streams (Java 8+).  It performs
     * the same null‑checking and returns 0 for an empty/ null list.
     *--------------------------------------------------------------*/
    public static int lenLogStream(List<String> list1) {
        return (list1 == null)
                ? 0
                : list1.stream()
                       .filter(Objects::nonNull)
                       .mapToInt(String::length)
                       .max()
                       .orElse(0);
    }
}

