class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron whose edge length is {@code num}.
     *
     * The volume V of a regular tetrahedron with edge length a is:
     *     V = a³ / (6·√2)
     *
     * @param num the length of each edge (must be positive)
     * @return the volume of the tetrahedron
     * @throws IllegalArgumentException if {@code num} is not positive
     *
     * Example:
     * <pre>
     * volumeTetrahedron(10) → 117.85
     * volumeTetrahedron(15) → 397.75
     * volumeTetrahedron(20) → 942.81
     * </pre>
     */
    public static Double volumeTetrahedron(int num) {
        // Defensive check – reject non‑positive edge lengths
        if (num <= 0) {
            throw new IllegalArgumentException("Edge length must be positive: " + num);
        }

        // Volume = a³ / (6·√2)
        double volume = (Math.pow(num, 3)) / (6.0 * Math.sqrt(2.0));

        // Return the result as a Double (auto‑boxing)
        return Double.valueOf(volume);
    }
}

