public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' at a position other than the first or last character of the
     * word; otherwise returns "Not matched!".
     *
     * @param text the input string to be examined
     * @return     the appropriate result message
     */
    public static String textMatchWordzMiddle(String text) {
        // \b = word boundary, \w+ = one or more word characters (letters, digits, _)
        Pattern wordPattern = Pattern.compile("\\b\\w+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();               // the actual word text
            String lower = word.toLowerCase();            // case‑insensitive check

            int zIndex = lower.indexOf('z');               // position of 'z' (or -1 if none)

            // a match only when 'z' is present and not at the first or last position
            if (zIndex != -1 && zIndex != 0 && zIndex != lower.length() - 1) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    // Simple manual test harness
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));      // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));    // "Not matched!"
    }
}

