class Maxaverageofpath {
    /**
     * Write a function to find a path with the maximum average over all existing
     * paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cur = cost.get(i).get(j); // current cell value

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cur;
                } else {
                    double fromTop = (i > 0) ? dp[i - 1][j] : Double.NEGATIVE_INFINITY;
                    double fromLeft = (j > 0) ? dp[i][j - 1] : Double.NEGATIVE_INFINITY;
                    dp[i][j] = cur + Math.max(fromTop, fromLeft);
                }
            }
        }

        // Maximum sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // Every valid path contains exactly (2*n - 1) cells
        int totalCells = 2 * n - 1;

        // Return the maximum average as a Double
        return maxSum / totalCells;
    }
}

