public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left cell and ends at the bottom‑right cell of the given n×n matrix.
     * Movement is restricted to only right or down steps.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = max sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The path always contains (2*n‑1) cells (start + n‑1 rights + n‑1 downs)
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);

        return Double.valueOf(average);
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
