class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n of the series (n >= 1)
     * @return the sum of squares from 1 to number
     *
     * Example:
     * seriesSum(6) → 91
     * seriesSum(7) → 140
     * seriesSum(12) → 650
     */
    public static int seriesSum(int number) {
        // Use long for the intermediate computation to avoid overflow
        // before casting back to int (the problem guarantees the result fits in int).
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;
    }

