class NewmanPrime {
    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     *
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2*a(n‑1) + a(n‑2)  for n >= 2.
     *
     * Example values:
     *   newmanPrime(3) → 7
     *   newmanPrime(4) → 17
     *   newmanPrime(5) → 41
     *
     * @param n index (0‑based) of the desired NSW number
     * @return the n‑th NSW number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;
        }

        // Iteratively compute the sequence using long to avoid early overflow.
        long aNm2 = 1; // a(n‑2)
        long aNm1 = 1; // a(n‑1)
        long aN = 0;   // a(n)

        for (int i = 2; i <= n; i++) {
            aN = 2 * aNm1 + aNm2; // recurrence
            aNm2 = aNm1;
            aNm1 = aN;
        }

        // The problem statement expects an int return type.
        return (int) aN;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

