class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * character 'z' at a position other than the first or last character.
     * Otherwise returns "Not matched!".
     *
     * Words are defined as whitespace‑separated tokens (punctuation is kept
     * as part of the word).
     *
     * Examples:
     *   textMatchWordzMiddle("pythonzabc.") -> "Found a match!"
     *   textMatchWordzMiddle("xyzabc.")     -> "Found a match!"
     *   textMatchWordzMiddle("  lang  .")   -> "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null or empty input
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split on one or more whitespace characters.
        // This keeps punctuation (e.g., '.') attached to the word.
        String[] words = text.split("\\s+");

        for (String word : words) {
            // Skip any empty tokens (can happen with multiple spaces)
            if (word.isEmpty()) {
                continue;
            }

            // Find the first occurrence of 'z'
            int zIndex = word.indexOf('z');

            // If 'z' exists and is NOT at the first (0) or last (length-1) position
            if (zIndex != -1 && zIndex != 0 && zIndex != word.length() - 1) {
                return "Found a match!";
            }
        }

        // No word satisfied the condition
        return "Not matched!";
    }

    // -----------------------------------------------------------------
    // Optional main method for quick manual testing
