import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class NewmanPrime {
    /**
     * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // The first NSW prime is 3 (appears at index 2 of the recurrence)
        if (n == 1) {
            return 3;
        }

        // a0 = a[i-2], a1 = a[i-1]
        BigInteger a0 = BigInteger.ONE;   // a0 = a0 = 1
        BigInteger a1 = BigInteger.ONE;   // a1 = a1 = 1
        BigInteger a  = BigInteger.ZERO;  // placeholder

        // Generate terms up to index n
        for (int i = 2; i <= n; i++) {
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            a0 = a1;
            a1 = a;
        }

        // If a[n] is prime, return it; otherwise find the next prime
        if (isPrime(a)) {
            return a.intValue();
        }

        // Continue generating until we hit a prime
        while (!isPrime(a)) {
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            a0 = a1;
            a1 = a;
        }
        return a.intValue();
    }

    /** Helper: deterministic primality test using Miller‑Rabin (certainty 20). */
    private static boolean isPrime(BigInteger x) {
        if (x.compareTo(BigInteger.ONE) <= 0) {
            return false;
        }
        if (x.equals(BigInteger.valueOf(2))) {
            return true;
        }
        if (x.mod(BigInteger.valueOf(2)).equals(BigInteger.ZERO)) {
            return false;
        }
        // isProbablePrime(certainty) with certainty = 20 gives an extremely low
        // probability of a composite passing as prime.
        return x.isProbablePrime(20);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

