        }

        // \b           – word boundary
        // \w+?         – one or more word characters (non‑greedy)
        // z            – the letter z (or Z, because CASE_INSENSITIVE is used)
        // \w+?         – one or more word characters after the z
        // \b           – closing word boundary
        // The pattern thus requires at least one character before *and*
        // after the z, i.e. z cannot be the first or last character.
        Pattern p = Pattern.compile("\\b\\w+?z\\w+?\\b", Pattern.CASE_INSENSITIVE);
        Matcher m = p.matcher(text);

        return m.find() ? "Found a match!" : "Not matched!";
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!
    }
}

import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that moves only
     * right or down from the top‑left to the bottom‑right corner of the
     * given n×n cost matrix.
     *
     * @param cost  list of rows, each row is a list of integers
     * @param n     size of the square matrix
     * @return      maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = max sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);           // value of current cell

                if (i == 0 && j == 0) {
                    // starting cell
                    dp[i][j] = val;
                } else {
                    double best = Double.NEGATIVE_INFINITY;
                    if (i > 0) best = Math.max(best, dp[i - 1][j]); // from above
                    if (j > 0) best = Math.max(best, dp[i][j - 1]); // from left
                    dp[i][j] = best + val;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        // Every path visits exactly (2*n - 1) cells
        return maxSum / (2 * n - 1);
    }

    // -----------------------------------------------------------------
    // Simple test driver (matches the examples from the problem statement)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

