class NewmanPrime {
    /**
     * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 2) {
            throw new IllegalArgumentException("n must be at least 2");
        }

        List<BigInteger> primes = new ArrayList<>();

        // a(0) = 1, a(1) = 1
        BigInteger aMinus2 = BigInteger.ONE; // a(i-2)
        BigInteger aMinus1 = BigInteger.ONE; // a(i-1)

        // generate a(2), a(3), ... and collect primes
        for (int i = 2; primes.size() < n - 1; i++) {
            BigInteger ai = aMinus1.multiply(BigInteger.TWO).add(aMinus2);
            if (ai.isProbablePrime(20)) {
                primes.add(ai);
            }
            // shift the sequence
            aMinus2 = aMinus1;
            aMinus1 = ai;
        }

        // Return the (n‑2)‑th prime (0‑based index)
        return primes.get(n - 2).intValue();
    }
}

