        while (matcher.find()) {
            String word = matcher.group();

            // Check if the word contains 'z' and the 'z' is not at
            // the start or at the end of the word.
            if (word.contains("z") && !word.startsWith("z") && !word.endsWith("z")) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

