class Maxaverageofpath {

    /**
     * Find a path with the maximum average over all existing paths for the
     * given square matrix of size n*n.
     *
     * The path is allowed to move only right or down, starts at (0,0) and ends
     * at (n‑1, n‑1).  Because every such path visits exactly (2·n‑1) cells,
     * maximizing the average is equivalent to maximizing the total sum.
     *
     * @param cost  a List of n rows, each containing n integer values
     * @param n     the size of the square matrix (number of rows/columns)
     * @return      the maximum average as a {@code Double}, or {@code null}
     *              if n <= 0
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal input
        if (n <= 0) {
            return null;
        }

        // dp[i][j] holds the maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // Initialize the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) +
                           Math.max(dp[i - 1][j],   // from above
                                    dp[i][j - 1]); // from left
            }
        }

        // The best sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // Number of cells visited by any valid path = 2·n‑1
        double average = maxSum / (2.0 * n - 1.0);

        // Return the average as a Double (auto‑boxing)
        return average;
    }

    // --------------------------------------------------------------------
    // Optional main method for quick manual testing
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

