/**
 * SeriesSum provides a utility method to compute the sum of the squares
 * of the first n natural numbers: 1² + 2² + 3² + … + n².
 */
public class SeriesSum {

    /**
     * Calculates the sum of the series 1² + 2² + … + n².
     *
     * @param number the number of terms (n); must be non‑negative
     * @return the sum of the squares of the first {@code number} natural numbers
     */
    public static int seriesSum(int number) {
        // Guard against negative input – the series is defined for n >= 0
        if (number < 0) {
            throw new IllegalArgumentException("Number must be non‑negative");
        }

        // Use long for the intermediate calculation to avoid overflow
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The problem statement expects an int return type
        return (int) sum;
    }

    // Optional main method for quick manual testing
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

