class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams number.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)   for n >= 2
     *
     * @param n index (0‑based) of the desired NSW number
     * @return the n‑th NSW number
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // The first two values are 1.
        if (n == 0 || n == 1) {
            return 1;
        }

        long a0 = 1; // a(n‑2)
        long a1 = 1; // a(n‑1)
        long a  = 0; // a(n)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // recurrence
            a0 = a1;
            a1 = a;
        }
        // The result fits in an int for the typical range of n.
        return (int) a;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

