import java.util.List;
import java.util.Arrays;

public class Maxaverageofpath {

    /**
     * Returns the maximum average of a path that starts at the top‑left
     * corner of the given square matrix and ends at the bottom‑right
     * corner, moving only right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (cost.size() == n)
     * @return     the maximal possible average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] – maximal sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int val = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = val;                     // start cell
                } else {
                    long bestPrev = 0;
                    if (i > 0) bestPrev = Math.max(bestPrev, dp[i - 1][j]);
                    if (j > 0) bestPrev = Math.max(bestPrev, dp[i][j - 1]);
                    dp[i][j] = val + bestPrev;
                }
            }
        }

        // Every path has exactly (2*n - 1) cells
        double average = (double) dp[n - 1][n - 1] / (2L * n - 1);
        return average;               // auto‑boxing to Double
    }

    // -----------------------------------------------------------------
    // Simple manual test (can be removed in production)
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
            Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
            ), 3));   // 5.2

        System.out.println(maxaverageofpath(
            Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
            ), 3));   // 6.2

        System.out.println(maxaverageofpath(
            Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
            ), 3));   // 7.2
