public class Maxaverageofpath {

    /**
     * Returns the maximum average of all paths that go from the top‑left
     * corner to the bottom‑right corner of the given n×n cost matrix.
     * Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against bad input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] holds the maximum sum to reach cell (i, j)
        int[][] dp = new int[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // The maximum sum to reach the bottom‑right corner
        int maxSum = dp[n - 1][n - 1];

        // Each path visits exactly (2*n - 1) cells
        double average = (double) maxSum / (2 * n - 1);

        return average;
    }

    // -----------------------------------------------------------------
    // Simple manual test (you can remove or replace this with unit tests)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

