public static int newmanPrime(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    // The Newman–Shanks–Williams sequence:
    // a0 = 1, a1 = 1, a_i = 2*a_{i-1} + a_{i-2}
    long a0 = 1;
    long a1 = 1;
    if (n == 1) return (int)a0;
    if (n == 2) return (int)a1;
    long a = 0;
    for (int i = 3; i <= n; i++) {
        a = 2 * a1 + a0;
        a0 = a1;
        a1 = a;
    }
    return (int)a;
}

