import java.math.BigInteger;

class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     *
     * The sequence is defined by:
     *   a0 = 1, a1 = 1
     *   an = 2 * a(n‑1) + a(n‑2)   for n >= 2
     *
     * > newmanPrime(3)  -> 7
     * > newmanPrime(4)  -> 17
     * > newmanPrime(5)  -> 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // a0 = a1 = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        BigInteger a0 = BigInteger.ONE; // a(n‑2)
        BigInteger a1 = BigInteger.ONE; // a(n‑1)
        BigInteger a  = null;           // a(n)

        for (int i = 2; i <= n; i++) {
            a = a1.multiply(BigInteger.valueOf(2)).add(a0); // a = 2*a1 + a0
            a0 = a1;
            a1 = a;
        }
        // The result fits in an int for reasonable input; otherwise the
        // intValue() call will simply discard higher bits.
        return a.intValue();
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

