     * @return "Found a match!" if such a word exists, otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Pattern explanation:
        // \b               – word boundary
        // [A-Za-z]+        – one or more letters (the part before the 'z')
        // [zZ]             – the letter 'z' (case‑insensitive)
        // [A-Za-z]+        – one or more letters (the part after the 'z')
        // \b               – closing word boundary
        // The requirement “not at the start or end” is satisfied because
        // both sides of the 'z' must have at least one letter.
        Pattern p = Pattern.compile("\\b[A-Za-z]+[zZ][A-Za-z]+\\b", Pattern.CASE_INSENSITIVE);
        Matcher m = p.matcher(text);

        return m.find() ? "Found a match!" : "Not matched!";
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));       // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));     // "Not matched!"
    }
}

import java.util.*;

class Maxaverageofpath {
    /**
     * Finds the maximum average of a path from the top‑left corner to the
     * bottom‑right corner of the given n×n matrix.  Movement is allowed
     * only right or down.
     *
     * @param cost the n×n matrix of integers
     * @param n    size of the matrix
     * @return the maximum average (as a Double) over all valid paths
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return null;
        }

        // DP[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first column – can only come from above
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // first row – can only come from the left
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // total number of cells visited on any path = 2*n - 1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1);

        return average;
    }

    // Simple test harness
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

import java.io.*;
