import java.util.*;
import java.math.*;

class CountVowels {

    /** Vowel characters (both lower‑ and upper‑case). */
    private static final String VOWELS = "aeiouAEIOU";

    /**
     * Counts characters that are not vowels and have at least one vowel
     * as a neighbour (either to the left or to the right).
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // only consider consonants; skip vowels themselves
            if (isVowel(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // check right neighbour
            else if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    /** Helper method to test if a character is a vowel. */
    private static boolean isVowel(char c) {
        return VOWELS.indexOf(c) != -1;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

