import java.io.*;

/**
 * Utility class that provides a static method to obtain the
 * nth Newman–Shanks–Williams number.  The class is made
 * Serializable to demonstrate the serialization‑proxy pattern.
 */
public class NewmanPrime implements Serializable {

    /** Serial version UID – any number is fine (Item 87). */
    private static final long serialVersionUID = 0xCAFEBABE_L;

    /* -------------------------------------------------------------
     *  Serialization proxy (Item 90)
     * -------------------------------------------------------------
     */
    private static class SerializationProxy implements Serializable {
        private static final long serialVersionUID = 0xDEADBEEF_L;

        /** The proxy simply records that it was created from a
         *  NewmanPrime instance – there is no mutable state to store.
         */
        SerializationProxy(NewmanPrime np) {
            // no fields to copy
        }

        /** When the proxy is deserialized it yields a fresh
         *  NewmanPrime instance.
         */
        private Object readResolve() {
            return new NewmanPrime();
        }
    }

    /** The enclosing class replaces itself with a proxy before
     *  serialization (Item 90).
     */
    private Object writeReplace() {
        return new SerializationProxy(this);
    }

    /** Private constructor – needed only for the serialization proxy. */
    private NewmanPrime() { }

    /* -------------------------------------------------------------
     *  Core algorithm
     * -------------------------------------------------------------
     */

    /**
     * Returns the nth Newman–Shanks–Williams number.
     * The sequence is defined by
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2*a(n‑1) + a(n‑2)   for n ≥ 2.
     *
     * For n ≥ 2 the returned values are prime (3, 7, 17, 41, …).
     *
     * @param n  index of the desired value (must be ≥ 0)
     * @return   the nth Newman–Shanks–Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // a(0) = 1, a(1) = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        int aMinus2 = 1; // a(i‑2)
        int aMinus1 = 1; // a(i‑1)

        for (int i = 2; i <= n; i++) {
            int current = 2 * aMinus1 + aMinus2;
            aMinus2 = aMinus1;
            aMinus1 = current;
        }
        return aMinus1;
    }

    /* -------------------------------------------------------------
     *  Simple test driver
     * -------------------------------------------------------------
     */
    public static void main(String[] args) {
        // Examples from the problem statement
        System.out.println(newmanPrime(3)); // → 7
        System.out.println(newmanPrime(4)); // → 17
        System.out.println(newmanPrime(5)); // → 41
    }
}

