class VolumeTetrahedron {

    /**
     * Calculates the volume of a regular tetrahedron with side length `num`.
     *
     * The volume of a regular tetrahedron is:
     *     V = a^3 / (6 * sqrt(2))
     *
     * The result is rounded to two decimal places to match the examples.
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     *
     * @param num the side length of the tetrahedron
     * @return the volume rounded to two decimal places
     */
    public static Double volumeTetrahedron(int num) {
        // Convert the side length to double for the computation
        double a = num;

        // Apply the formula for the volume of a regular tetrahedron
        double volume = (a * a * a) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places (matches the expected output)
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Return the result as a Double object
        return Double.valueOf(rounded);
    }

    // Optional main method for quick manual testing
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

