/**
 * Demonstrates the “word‑contains‑z‑not‑at‑the‑edges” check and the
 * serialization‑proxy pattern.
 */
public class TextMatchWordzMiddle implements Serializable {
    private static final long serialVersionUID = 1L;

    // -----------------------------------------------------------------
    // Serialization proxy (Item 90)
    // -----------------------------------------------------------------
    private static class SerializationProxy implements Serializable {
        private static final long serialVersionUID = 1L;

        SerializationProxy() {
            // no‑arg constructor – nothing to copy because TextMatchWordzMiddle
            // has no instance state.
        }

        /** 
         * When the proxy is deserialized it yields a fresh enclosing instance.
         */
        private Object readResolve() {
            return new TextMatchWordzMiddle();
        }
    }

    /**
     * Whenever the enclosing instance is serialized, replace it with its proxy.
     */
    private Object writeReplace() {
        return new SerializationProxy();
    }

    /**
     * Prevent direct deserialization of the enclosing class – a proxy must be used.
     */
    private void readObject(ObjectInputStream in) throws InvalidObjectException {
        throw new InvalidObjectException("Serialization proxy required");
    }

    // -----------------------------------------------------------------
    // Task implementation
    // -----------------------------------------------------------------
    /**
     * Returns "Found a match!" if any word in the supplied text contains the
     * letter 'z' (or 'Z') at a position other than the first or last character
     * of that word; otherwise returns "Not matched!".
     *
     * A word is defined as a maximal sequence of ASCII letters ({@code [a-zA-Z]}).
     *
     * Examples:
     * <ul>
     *   <li>{@code textMatchWordzMiddle("pythonzabc.")} → "Found a match!"</li>
     *   <li>{@code textMatchWordzMiddle("xyzabc.")}      → "Found a match!"</li>
     *   <li>{@code textMatchWordzMiddle("  lang  .")}    → "Not matched!"</li>
     * </ul>
     *
     * @param text the input text to examine
     * @return     the appropriate match message
     */
    public static String textMatchWordzMiddle(String text) {
        // Word boundary pattern – matches sequences of ASCII letters.
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int len = word.length();

            // A word shorter than 3 characters cannot have a middle 'z'.
            if (len > 2) {
                // Scan characters except the first and last.
                for (int i = 1; i < len - 1; i++) {
                    if (Character.toLowerCase(word.charAt(i)) == 'z') {
                        return "Found a match!";
                    }
                }
            }
        }
        return "Not matched!";
    }

    // -----------------------------------------------------------------
    // Optional test driver
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));   // Not matched!
    }
}

import java.util.List;

class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts at the
     * top‑left corner of the given cost matrix and ends at the bottom‑right
     * corner, moving only right or down.
     *
     * @param cost  a square matrix (List of List of Integer)
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximal average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = best sum to reach (i, j)
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill first column (only vertical moves)
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill first row (only horizontal moves)
        for (int j = 1; j < n; ++j) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                dp[i][j] = cost.get(i).get(j) +
                           Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Maximum sum at the destination
        long maxSum = dp[n - 1][n - 1];

        // Convert to average (path length = 2*n - 1)
        double average = maxSum / (double) (2 * n - 1);

        return average;
    }

    // ---- simple manual test -------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
            List.of(1, 2, 3),
            List.of(6, 5, 4),
            List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
            List.of(2, 3, 4),
            List.of(7, 6, 5),
            List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
            List.of(3, 4, 5),
            List.of(8, 7, 6),
            List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

import java.io.*;
