/**
 * Utility class that counts consonants which have a vowel as an immediate
 * neighbour (either to the left or to the right).  The class is also
 * Serializable, using a serialization proxy to avoid the pitfalls of
 * extralinguistic object creation.
 */
public class CountVowels implements Serializable {

    /** Unique identifier for serialization */
    private static final long serialVersionUID = 1L;

    // -------------------------------------------------
    // Serialization proxy (Item 90)
    // -------------------------------------------------
    private static class SerializationProxy implements Serializable {
        private static final long serialVersionUID = 2L;

        /** The proxy simply mirrors the logical state of the enclosing instance.
         *  Since CountVowels has no instance fields, the constructor does nothing.
         */
        SerializationProxy(CountVowels obj) {
            // no‑op – there is no mutable state to copy
        }
    }

    /** 
     * The writeReplace method is required by the serialization‑proxy pattern.
     * It replaces the enclosing instance with its proxy during serialization.
     */
    private Object writeReplace() {
        return new SerializationProxy(this);
    }

    /** 
     * readObject is overridden to guarantee that a deserialization attempt
     * of the proxy (instead of the proxy being replaced) fails fast.
     */
    private void readObject(ObjectInputStream stream)
            throws InvalidObjectException {
        throw new InvalidObjectException("Serialization proxy required");
    }

    // -------------------------------------------------
    // Core logic
    // -------------------------------------------------
    /**
     * Counts characters that are **not** vowels (i.e. consonants) and that have
     * at least one vowel neighbour (immediate left or right character).
     *
     * @param testStr the input string (may be empty or null)
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowels – both lower‑ and upper‑case
        final Set<Character> vowelSet = new HashSet<>(
                Arrays.asList('a', 'e', 'i', 'o', 'u',
                              'A', 'E', 'I', 'O', 'U'));

        int count = 0;
        for (int i = 0; i < testStr.length(); i++) {
            char ch = testStr.charAt(i);
            if (vowelSet.contains(ch)) {
                // We only count consonants (non‑vowels)
                continue;
            }

            boolean hasVowelNeighbor = false;
            // check left neighbour
            if (i > 0 && vowelSet.contains(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            // check right neighbour
            if (!hasVowelNeighbor && i < testStr.length() - 1
                    && vowelSet.contains(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    // -------------------------------------------------
    // Simple test driver
    // -------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

