            char ch = string.charAt(i);
            if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) {
                alphabets++;
            } else if (ch >= '0' && ch <= '9') {
                digits++;
            } else {
                specials++;
            }
        }

        List<Integer> result = new ArrayList<>();
        result.add(alphabets);
        result.add(digits);
        result.add(specials);
        return result;
    }

    // Simple test driver (optional)
