import java.io.*;
import java.util.*;

public class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * The sequence is defined by:
     *   a0 = 1, a1 = 1,
     *   an = 2 * a(n‑1) + a(n‑2)   for n >= 2.
     *
     * The values for n = 2,3,4,… correspond to the NSW prime numbers
     * (3, 7, 17, 41, …).  This implementation works for any non‑negative
     * integer n; however, the result is returned as an int, so n should be
     * small enough that the value fits in 32‑bit signed integer
     * (n ≤ 24 for typical int range).
     *
     * @param n the index of the desired NSW term (0‑based)
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases
        if (n == 0 || n == 1) {
            return 1;   // a0 = a1 = 1
        }

        // Compute the sequence iteratively
        long prev2 = 1L; // a0
        long prev1 = 1L; // a1
        long current = 0L;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2; // an = 2*a(n‑1) + a(n‑2)
            // Shift the sliding window
            prev2 = prev1;
            prev1 = current;
        }

        // The problem expects an int return type; we cast the result.
        // If the value does not fit in an int, the cast will truncate
        // (this should not happen for valid test cases).
        return (int) current;
    }

    // -----------------------------------------------------------------
    // Optional main method for quick manual testing
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example calls as given in the task description
        System.out.println("newmanPrime(3) = " + newmanPrime(3)); // 7
        System.out.println("newmanPrime(4) = " + newmanPrime(4)); // 17
        System.out.println("newmanPrime(5) = " + newmanPrime(5)); // 41

        // A few more terms to illustrate the sequence
        for (int i = 0; i <= 10; i++) {
            System.out.println("a(" + i + ") = " + newmanPrime(i));
        }
    }
}

