import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum average of a path that starts at the top‑left
     * cell and ends at the bottom‑right cell of the square matrix.
     * Movement is restricted to right or down steps.
     *
     * @param cost 2‑D list representing the n×n matrix
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[j] holds the maximum sum to reach the cell (i, j) from (0,0)
        long[] dp = new long[n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long val = cost.get(i).get(j);          // value of current cell

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[j] = val;
                } else if (i == 0) {
                    // First row – can only come from the left
                    dp[j] = dp[j - 1] + val;
                } else if (j == 0) {
                    // First column – can only come from above
                    dp[j] = dp[j] + val;
                } else {
                    // General case: take the larger of the top or left predecessor
                    dp[j] = Math.max(dp[j], dp[j - 1]) + val;
                }
            }
        }

        long maxSum = dp[n - 1];                     // sum of the best path
        double average = maxSum / (double) (2 * n - 1); // average over all visited cells
        return average;
    }

    // Simple manual test (can be removed when integrating into a larger codebase)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

