import java.math.BigInteger;

public class NewmanPrime {

    /**
     * Returns the n‑th term of the Newman‑Shanks‑Williams sequence.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1,
     *   a(n) = 2*a(n‑1) + a(n‑2) for n >= 2.
     *
     * For n = 3, 4, 5 the values are 7, 17, 41 respectively,
     * matching the examples.
     *
     * @param n index of the term (0‑based)
     * @return the n‑th NSW number as an int
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Use BigInteger to avoid overflow for moderate n,
        // then narrow to int as required by the method signature.
        BigInteger a0 = BigInteger.ONE; // a(0)
        if (n == 0) return a0.intValue();

        BigInteger a1 = BigInteger.ONE; // a(1)
        if (n == 1) return a1.intValue();

        BigInteger a = BigInteger.ZERO;
        for (int i = 2; i <= n; i++) {
            // a(i) = 2*a(i‑1) + a(i‑2)
            a = a1.multiply(BigInteger.valueOf(2)).add(a0);
            a0 = a1;
            a1 = a;
        }
        return a.intValue();
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

