class NewmanPrime {
    /**
     * Returns the n-th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     *   s0 = 1, s1 = 1,
     *   sn = 2*s_{n-1} + s_{n-2} for n >= 2.
     *
     * @param n the index of the term to return (0‑based)
     * @return the value of s_n
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Use long for intermediate results to avoid overflow.
        if (n == 0 || n == 1) {
            return 1;
        }
        long prev2 = 1; // s_{i-2}
        long prev1 = 1; // s_{i-1}
        long current = 0;
        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        // The problem expects an int return type; we assume n is small enough
        // to fit into an int. If not, the cast will truncate the value.
        return (int) current;
    }
}

