class TextMatchWordzMiddle {

    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Split on whitespace – punctuation stays attached to the word.
        String[] tokens = text.split("\\s+");

        for (String token : tokens) {
            if (token.isEmpty()) {
                continue; // skip empty tokens (shouldn't happen after split)
            }

            // Check if the token contains at least one 'z' that is
            // neither the first nor the last character.
            if (token.contains("z")) {
                int firstZ = token.indexOf('z');
                int lastZ  = token.lastIndexOf('z');
                int len    = token.length();

                // If there is a 'z' that is not at position 0 and not at the last position.
                if (firstZ > 0 || lastZ < len - 1) {
                    return "Found a match!";
                }
            }
        }

        return "Not matched!";
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    if (cost == null || n <= 0) return null;
    double[][] dp = new double[n][n];
    // first cell
    dp[0][0] = cost.get(0).get(0);
    // first row
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j-1] + cost.get(0).get(j);
    }
    // first column
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i-1][0] + cost.get(i).get(0);
    }
    // fill rest
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i-1][j], dp[i][j-1]) + cost.get(i).get(j);
        }
    }
    double maxSum = dp[n-1][n-1];
    double average = maxSum / (2 * n - 1);
    return average;
}

