class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the top‑left
     * corner of the given n×n matrix and ends at the bottom‑right corner, moving
     * only right or down.
     *
     * @param cost a square list of lists representing the matrix
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a {@code Double}, or {@code null} if the input
     *         is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- basic validation -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                return null;               // matrix is not truly n×n
            }
        }

        // ---- DP table: maximum sum to reach each cell -------------------------
        double[][] dp = new double[n][n];
        dp[0][0] = cost.get(0).get(0);    // starting cell

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells: take the best of the two possible predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average ---------------------------------------------------
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2L * n - 1);   // denominator is constant for any path

        return Double.valueOf(average);
    }

