    // a(0)=1, a(1)=1, a(n)=2*a(n-1)+a(n-2)
    if (n < 2) {
        // For n=0 or 1, the sequence value is 1, which is not prime.
        // But we can assume n>=2 based on examples.
        // However, we can handle it by returning 1 or throw exception.
        // Let's return 1 for n=0 or 1? But not sure.
        // We'll assume n>=2.
    }
    int a0 = 1;
    int a1 = 1;
    int an = 0;
    for (int i = 2; i <= n; i++) {
        an = 2 * a1 + a0;
        a0 = a1;
        a1 = an;
    }
    // Now an is a(n). Check if prime.
    if (isPrime(an)) {
        return an;
    } else {
        // If not prime, we might need to find the next prime? 
        // But the problem doesn't specify. Let's find the next prime in the sequence.
        // We'll iterate further until we find a prime.
        int i = n + 1;
        while (!isPrime(an)) {
            an = 2 * an + a1; // Wait, we need to compute next term.
