public class VolumeTetrahedron {

    /**
     * Calculates the volume of a regular tetrahedron whose side length is {@code num}.
     *
     * The volume V of a regular tetrahedron with side length a is:
     *     V = a³ / (6·√2)
     *
     * The result is rounded to two decimal places.
     *
     * @param num side length of the tetrahedron (must be positive)
     * @return the volume rounded to two decimal places
     * @throws IllegalArgumentException if {@code num} is not positive
     */
    public static Double volumeTetrahedron(int num) {
        // ---- Check parameters for validity ----
        if (num <= 0) {
            throw new IllegalArgumentException("Side length must be positive");
        }

        double a = num;                     // side length
        double volume = (a * a * a) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places (as shown in the examples)
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Return as a boxed Double as required by the method signature
        return Double.valueOf(rounded);
    }

    // ---- Simple test driver ----
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

