import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a path that starts
     * at the top‑left corner and ends at the bottom‑right corner of the
     * given n×n matrix. Movement is restricted to right or down steps.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return     the maximum average as a {@code Double}
     * @throws IllegalArgumentException if the matrix is null, not square,
     *                                  or its dimensions do not match n
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- parameter validation ----
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Cost matrix must be non‑null and have " + n + " rows.");
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("Each row must contain " + n + " integers.");
            }
        }

        // ---- dynamic programming ----
        double[][] dp = new double[n][n];

        dp[0][0] = cost.get(0).get(0);

        // first row
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // interior cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);
        return average;
    }

    // --------------------------------------------------------------------
    // Optional test driver (can be removed when integrating into a larger project)
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // expected 5.2

        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // expected 6.2

        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // expected 7.2
    }
}

public static int countVowels(String testStr) {
    if (testStr == null || testStr.isEmpty()) {
        return 0;
    }

    // Set of vowel characters (lower‑case)
    Set<Character> vowels = Set.of('a', 'e', 'i', 'o', 'u');

    char[] ch = testStr.toLowerCase().toCharArray();
    int count = 0;

    for (int i = 0; i < ch.length; i++) {
        // Skip vowels themselves – we only count consonants
        if (vowels.contains(ch[i])) {
            continue;
        }

        // Check left neighbor
        boolean hasVowelNeighbor = (i > 0 && vowels.contains(ch[i - 1]));
        // Check right neighbor
        if (!hasVowelNeighbor && i < ch.length - 1) {
            hasVowelNeighbor = vowels.contains(ch[i + 1]);
        }

        if (hasVowelNeighbor) {
            count++;
        }
    }
    return count;
}

