class SeriesSum {
    /**
     * Calculates the sum of the squares of the first {@code n} positive integers:
     * 1² + 2² + … + n².
     *
     * @param number the number of terms (must be non‑negative)
     * @return the sum of squares for the given {@code number}
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        // ---- Check parameters for validity ----
        if (number < 0) {
            throw new IllegalArgumentException("Number must be non‑negative");
        }

        // ---- Use a longer intermediate type to avoid overflow ----
        // Formula: n * (n + 1) * (2n + 1) / 6
        long sum = (long) number * (number + 1) * (2L * number + 1) / 6;

        // The problem expects an int result, so we cast back.
        return (int) sum;
    }

    // Simple demo (optional)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12)); // 650
    }
}

