import java.util.*;

public class NewmanPrime {
    /**
     * Returns the n‑th term of the Newman–Shanks–Williams sequence.
     * The sequence is defined by:
     * <ul>
     *   <li>a(0) = 1</li>
     *   <li>a(1) = 1</li>
     *   <li>a(i) = 2*a(i‑1) + a(i‑2) for i ≥ 2</li>
     * </ul>
     * For the given examples:
     * <ul>
     *   <li>newmanPrime(3) → 7</li>
     *   <li>newmanPrime(4) → 17</li>
     *   <li>newmanPrime(5) → 41</li>
     * </ul>
     *
     * @param n the 1‑based index of the term to retrieve (must be ≥ 1)
     * @return the n‑th term of the Newman–Shanks–Williams sequence
     * @throws IllegalArgumentException if {@code n} is less than 1
     */
    public static int newmanPrime(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n must be at least 1");
        }

        // Base cases
        if (n == 1) {
            return 1; // a(0)
        }
        if (n == 2) {
            return 3; // a(2)
        }

        long prev2 = 1; // a(i‑2)
        long prev1 = 1; // a(i‑1)
        long current = 0;

        for (int i = 3; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }

        return (int) current;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

