import java.util.List;

/**
 * Finds the maximum average value of any path that starts in the upper‑left
 * cell of a square matrix and ends in the lower‑right cell.  Movement is
 * restricted to right‑ward or downward steps.
 *
 * @param cost  the n×n matrix of non‑negative integers
 * @param n     the dimension of the square matrix
 * @return      the maximum average value as a {@code Double}, or {@code null}
 *              if the input is invalid
 */
public class Maxaverageofpath {

    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- Input validation ------------------------------------------------
        if (cost == null || n <= 0) {
            return null;                               // invalid size
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException(
                        "Matrix must be a " + n + "x" + n + " square.");
            }
        }

        // ---- DP: maximum sum from (0,0) to each cell ------------------------
        double[][] dp = new double[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double cellValue = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = cellValue;             // start cell
                } else {
                    double bestPrev = Double.NEGATIVE_INFINITY;
                    if (i > 0) {
                        bestPrev = Math.max(bestPrev, dp[i - 1][j]); // from above
                    }
                    if (j > 0) {
                        bestPrev = Math.max(bestPrev, dp[i][j - 1]); // from left
                    }
                    dp[i][j] = cellValue + bestPrev;
                }
            }
        }

        // ---- Compute average -------------------------------------------------
        double maxSum = dp[n - 1][n - 1];
        double pathLength = 2.0 * n - 1.0;            // number of cells visited
        return maxSum / pathLength;
    }

    // ---- Simple test harness (optional) ------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9));
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10));
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11));
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

