/**
 * Utility class for counting characters that are adjacent to vowels.
 *
 * @author  (your name)
 * @version 1.0
 */
public class CountVowels {

    /**
     * Counts the characters (excluding vowels) in {@code testStr} that have
     * at least one vowel as a direct neighbour (either to the left or right).
     *
     * @param testStr the input string; must not be {@code null}
     * @return the number of such characters
     * @throws IllegalArgumentException if {@code testStr} is {@code null}
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            throw new IllegalArgumentException("Input string must not be null");
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels themselves – we only count consonants (or other non‑vowel chars)
            if (isVowel(ch)) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }

            // Check right neighbour if we haven't found a vowel neighbour yet
            if (!hasVowelNeighbor && i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    /**
     * Determines whether a given character is a vowel (a, e, i, o, u) case‑insensitively.
     *
     * @param ch the character to test
     * @return {@code true} if {@code ch} is a vowel, {@code false} otherwise
     */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u';
    }

    // ----- simple manual test driver -------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));            // 5
    }
}

