import java.math.*;

class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        // The first NSW prime is 3
        if (n == 1) {
            return 3;
        }

        List<Integer> primes = new ArrayList<>();
        long a0 = 1;   // a(0)
        long a1 = 1;   // a(1)

        // Generate the recurrence a(i) = 2*a(i‑1) + a(i‑2)
        while (true) {
            long a2 = 2 * a1 + a0;
            if (isPrime(a2)) {
                primes.add((int) a2);
                // We need the (n‑1)‑th prime (1‑based)
                if (primes.size() == n - 1) {
                    return (int) a2;
                }
            }
            a0 = a1;
            a1 = a2;
        }
    }

    /** Simple deterministic primality test for long values */
    private static boolean isPrime(long num) {
        if (num < 2) return false;
        if (num % 2 == 0) return num == 2;
        for (long i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

import java.util.Objects;

/**
 * Utility class for manipulating strings.
 */
public final class RemoveOdd {

    // Prevent instantiation
    private RemoveOdd() { }

    /**
     * Removes every character that appears in an odd position (1‑based) of the
     * supplied string.  In other words, only the characters at even positions
     * (2, 4, 6, …) are retained.
     *
     * <p>This method is <strong>thread‑safe</strong> because it does not
     * maintain any mutable state.</p>
     *
     * @param str the input string; may be {@code null}
     * @return a new string consisting of the characters at even positions,
     *         or {@code null} if the input is {@code null}
     * @example
     * <pre>{@code
     * removeOdd("python")   // → "yhn"
     * removeOdd("program")  // → "rga"
     * removeOdd("language") // → "agae"
     * }</pre>
     */
    public static String removeOdd(String str) {
        // Defensively handle null input
        if (str == null) {
            return null;
        }

        // Use StringBuilder for efficient concatenation
        StringBuilder result = new StringBuilder(str.length() / 2 + 1);

        // Keep characters at odd indices (1‑based even positions)
        for (int i = 1; i < str.length(); i += 2) {
            result.append(str.charAt(i));
        }

        return result.toString();
    }

    // Simple demo (optional)
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));   // yhn
        System.out.println(removeOdd("program"));  // rga
        System.out.println(removeOdd("language")); // agae
    }
}

