class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron given the length of its edges.
     * 
     * The volume V of a regular tetrahedron with side length a is:
     *     V = a³ / (6·√2)
     *
     * @param num the length of each edge (a)
     * @return the volume rounded to two decimal places
     */
    public static Double volumeTetrahedron(int num) {
        // Convert to double to avoid integer division
        double a = num;
        // Formula for the volume of a regular tetrahedron
        double volume = (a * a * a) / (6.0 * Math.sqrt(2.0));
        // Return as a Double object (boxing).  The caller can format as needed.
        return Double.valueOf(volume);
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

import java.util.regex.*;

public static String textMatchWordzMiddle(String text) {
    // Defensive check – treat null or empty input as no match.
    if (text == null || text.isEmpty()) {
        return "Not matched!";
    }

    // \b … \b  → word boundary
    // [A-Za-z]+ → one or more letters before the 'z'
    // [zZ]      → the letter 'z' (case‑insensitive)
    // [A-Za-z]+ → one or more letters after the 'z'
    // This guarantees the 'z' is not the first or last character.
    Pattern pattern = Pattern.compile("\\b[A-Za-z]+[zZ][A-Za-z]+\\b");
    Matcher matcher = pattern.matcher(text);

    return matcher.find() ? "Found a match!" : "Not matched!";
}

import java.util.Arrays;
import java.util.List;

class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a path that starts at the
     * top‑left cell and ends at the bottom‑right cell of the given n×n matrix.
     * Movement is restricted to only right or down steps.
     *
     * @param cost the square matrix (List of rows, each row a List of Integer)
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximum average as a {@code Double}, or {@code null} if the
     *         input is malformed
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation ------------------------------------------------
        if (cost == null || cost.size() != n) {
            return null;
        }
        for (List<Integer> row : cost) {
            if (row == null || row.size() != n) {
                return null;
            }
        }

        // ---- DP: maximum sum to reach each cell ------------------------------
        double[][] dp = new double[n][n];

        // start cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // remaining cells: take the better of the two possible predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // ---- compute average --------------------------------------------------
        // A path from (0,0) to (n‑1,n‑1) using only right/down moves visits
        // exactly (2*n‑1) cells.
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return Double.valueOf(average);
    }

    // ---- simple test harness ------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(m1, 3)); // 5.2

        // Example 2
        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(m2, 3)); // 6.2

        // Example 3
        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

import java.io.*;
