class CountVowels {

    /** 
     * Counts consonants in the given string that have at least one vowel 
     * as an immediate neighbor (to the left or right). 
     * 
     * <p>This method is thread‑safe because it does not modify any state 
     * and only reads the input string.
     *
     * @param testStr the input string (may be null or empty)
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        // Null or empty input yields zero
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set for fast O(1) lookup – both lower‑ and upper‑case
        final String VOWELS = "aeiouAEIOU";

        char[] ch = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < ch.length; i++) {
            char c = ch[i];

            // Skip vowels – we only count consonants
            if (VOWELS.indexOf(c) >= 0) {
                continue;
            }

            // Check left neighbour
            boolean hasVowelNeighbor = false;
            if (i > 0 && VOWELS.indexOf(ch[i - 1]) >= 0) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour
            if (i < ch.length - 1 && VOWELS.indexOf(ch[i + 1]) >= 0) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // ------------------------------------------------------------------
    // Optional test driver (feel free to remove or comment out in production)
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

import java.util.*;

class CountAlphaDigSpl {

    /**
     * Counts alphabetic characters, digits, and special characters in the
     * supplied string.
     *
     * @param string the input text to analyse (may be {@code null})
     * @return an unmodifiable {@link List} containing three integers:
     *         <ol>
     *           <li>number of alphabetic characters (A‑Z, a‑z)</li>
     *           <li>number of digit characters (0‑9)</li>
     *           <li>number of all other characters</li>
     *         </ol>
     *
     * @apiNote This method is <strong>thread‑safe</strong> because it does not
     *          mutate any state and always returns a new, immutable list.
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Guard against null input – treat it as an empty string.
        if (string == null) {
            return Collections.unmodifiableList(Arrays.asList(0, 0, 0));
        }

        // Use streams to count each category of character.
        long alphas = string.chars()
                            .filter(Character::isLetter)
                            .count();
        long digits = string.chars()
                            .filter(Character::isDigit)
                            .count();
        long specials = string.length() - alphas - digits;

        // Return an immutable list to prevent accidental modification.
        return Collections.unmodifiableList(
                Arrays.asList((int) alphas, (int) digits, (int) specials));
    }

    // Simple manual test (optional)
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

