class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms (n). Must be non‑negative.
     * @return the sum of the squares from 1 to n.
     * @throws IllegalArgumentException if number is negative.
     */
    public static int seriesSum(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("Number must be non‑negative");
        }

        // Use long for the intermediate computation to avoid overflow.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;   // n(n+1)(2n+1)/6

        // The problem expects an int return; cast after confirming fit.
        return (int) sum;
    }

    // Simple manual test (can be removed when integrating into a larger project)
    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

