class VolumeTetrahedron {

    /**
     * Calculates the volume of a regular tetrahedron whose side length is {@code num}.
     *
     * @param num the length of each edge (must be > 0)
     * @return the volume rounded to two decimal places
     */
    public static Double volumeTetrahedron(int num) {
        // Validate the input – assertions can be enabled with -ea
        assert num > 0 : "Side length must be positive";

        // Volume of a regular tetrahedron: V = a^3 / (6 * sqrt(2))
        double a = num;
        double volume = Math.pow(a, 3) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places (e.g., 117.85, 397.75, 942.81)
        double rounded = Math.round(volume * 100.0) / 100.0;

        // Return the boxed Double (auto‑boxing works as well)
        return Double.valueOf(rounded);
    }

