import java.util.regex.*;

public class TextMatchWordzMiddle {

    /**
     * Returns "Found a match!" if any word in the given text contains the
     * letter 'z' (or 'Z') somewhere other than the first or last position.
     * Otherwise returns "Not matched!".
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // Pattern matches whole words (letters only, ignoring punctuation)
        Pattern wordPattern = Pattern.compile("\\b[a-zA-Z]+\\b");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            int len = word.length();

            // Look for 'z' or 'Z' inside the word
            int idx = word.indexOf('z');
            if (idx == -1) {
                idx = word.indexOf('Z');
            }

            // If we found a 'z' and it is not at position 0 or at the last position
            if (idx != -1 && idx != 0 && idx != len - 1) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    // Simple manual test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // "Found a match!"
        System.out.println(textMatchWordzMiddle("xyzabc."));     // "Found a match!"
        System.out.println(textMatchWordzMiddle("  lang  ."));   // "Not matched!"
    }
}

import java.util.*;

class Maxaverageofpath {
    /**
     * Returns the maximum average of a monotonic (right/down) path
     * from the top‑left corner to the bottom‑right corner of an n×n matrix.
     *
     * @param cost the n×n matrix of integers
     * @param n    dimension of the matrix
     * @return     the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic safety check
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the DP table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The path always contains (2*n - 1) cells
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1);

        return average;
    }

    // -----------------------------------------------------------------
    // Optional test driver (matches the examples from the problem statement)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        // Example 2
        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        // Example 3
        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

