class CountVowels {

    /**
     * Counts consonants in the given string that have a vowel as one of their
     * immediate neighbours (either to the left or to the right).
     *
     * @param testStr the input string
     * @return the number of such consonants
     *
     * Examples:
     * countVowels("bestinstareels")          -> 7
     * countVowels("partofthejourneyistheend")-> 12
     * countVowels("amazonprime")             -> 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set (both lower‑ and upper‑case)
        final String vowels = "aeiouAEIOU";

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char c = testStr.charAt(i);

            // Skip vowels – we only count consonants
            if (vowels.indexOf(c) != -1) {
                continue;
            }

            // Check left neighbour
            if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
                count++;
                continue; // already satisfied, no need to check right side
            }

            // Check right neighbour
            if (i < len - 1 && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
                count++;
            }
        }

        return count;
    }

    // --------------------------------------------------------------------
    // Optional main method for quick manual testing (uses assertions)
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Run with -ea flag to enable assertions
        assert countVowels("bestinstareels") == 7;
        assert countVowels("partofthejourneyistheend") == 12;
        assert countVowels("amazonprime") == 5;

        System.out.println("All example tests passed.");
    }
}

import java.util.Arrays;
import java.util.List;

class CountAlphaDigSpl {
    /**
     * Write a function to count alphabets, digits and special characters in a given string.
     *
     * > countAlphaDigSpl("abc!@#123")
     * [3, 3, 3]
     * > countAlphaDigSpl("dgsuy@#$%&1255")
     * [5, 4, 5]
     * > countAlphaDigSpl("fjdsif627348#%$^&")
     * [6, 6, 5]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        // Defensive check: treat null as an empty string
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        int alpha = 0;
        int digit = 0;
        int special = 0;

        for (char ch : string.toCharArray()) {
            if (Character.isLetter(ch)) {
                alpha++;
            } else if (Character.isDigit(ch)) {
                digit++;
            } else {
                special++;
            }
        }

        List<Integer> result = Arrays.asList(alpha, digit, special);

        // Assert that we always return exactly three counts
        assert result.size() == 3 : "Result must contain three elements";

        return result;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));           // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));      // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

