/**
 * SeriesSum provides a utility method to compute the sum of the squares
 * of the first n natural numbers: 1² + 2² + … + n².
 */
class SeriesSum {

    /**
     * Returns the sum of squares of the first {@code number} positive integers.
     *
     * @param number the count of terms (must be non‑negative)
     * @return the sum 1² + 2² + … + number²
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative");
        }

        // Use long for the intermediate calculation to avoid overflow.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The problem statement expects an int return type.
        return (int) sum;
    }

    // -----------------------------------------------------------------
    // Optional main method for quick manual testing (not required by the task)
    // -----------------------------------------------------------------
    public static void main(String[] args) {
        // Example tests taken from the problem description
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

