public static int newmanPrime(int n) {
    // Handle non‑positive indices
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }
    // Base cases
    if (n == 0 || n == 1) {
        return 1; // S_0 = S_1 = 1
    }

    // Iteratively compute S_i = 2*S_{i-1} + S_{i-2}
    long prev2 = 1; // S_{i-2}
    long prev1 = 1; // S_{i-1}
    long current = 0;
    for (int i = 2; i <= n; i++) {
        current = 2 * prev1 + prev2;
        // Shift the window
        prev2 = prev1;
        prev1 = current;
    }
    // The problem expects an int return type; assuming n is small enough to fit.
    return (int) current;
}

