class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Pattern to extract words consisting only of letters (ignore punctuation/spaces)
        Pattern wordPattern = Pattern.compile("[A-Za-z]+");
        Matcher matcher = wordPattern.matcher(text);

        while (matcher.find()) {
            String word = matcher.group();
            if (hasInternalZ(word)) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * Returns true if the given word contains the letter 'z' (case‑insensitive)
     * at a position other than the first or last character.
     */
    private static boolean hasInternalZ(String word) {
        int len = word.length();
        // A word shorter than 3 letters cannot have an internal character
        if (len < 3) {
            return false;
        }
        // Check every character except the first and last
        for (int i = 1; i < len - 1; i++) {
            if (Character.toLowerCase(word.charAt(i)) == 'z') {
                return true;
            }
        }
        return false;
    }

    // Simple test harness
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));
        System.out.println(textMatchWordzMiddle("xyzabc."));
        System.out.println(textMatchWordzMiddle("  lang  ."));
        System.out.println(textMatchWordzMiddle("zabc"));
        System.out.println(textMatchWordzMiddle("abz"));
        System.out.println(textMatchWordzMiddle("abczzdef"));
    }
}

import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the
     * top‑left corner of the given square matrix and ends at the bottom‑right
     * corner, moving only right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    size of the matrix (number of rows/columns)
     * @return the maximal average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                long cellValue = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    // start cell
                    dp[i][j] = cellValue;
                } else {
                    long best = Long.MIN_VALUE;
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]); // came from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]); // came from left
                    }
                    dp[i][j] = cellValue + best;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        // Number of cells visited on any valid path = 2*n - 1
        double average = maxSum / (double) (2 * n - 1);
        return average;
    }

    // --------------------------------------------------------------------
    // Simple manual test (can be removed or replaced by JUnit tests)
    public static void main(String[] args) {
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // expected 5.2

        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // expected 6.2

        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // expected 7.2
    }
}

class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Handle null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set (both lower‑ and upper‑case)
        final String vowels = "aeiouAEIOU";

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);
            // Consider only consonants (i.e., characters that are not vowels)
            if (vowels.indexOf(ch) == -1) {
                boolean hasVowelNeighbor = false;

                // Check left neighbour
                if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
                    hasVowelNeighbor = true;
                }
                // Check right neighbour
                if (i < len - 1 && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }
}

