import java.math.BigInteger;

/**
 * Returns the n‑th Newman–Shanks–Williams number.
 *
 * The sequence is defined by:
 * <ul>
 *   <li>a(0) = 1</li>
 *   <li>a(1) = 1</li>
 *   <li>a(n) = 2·a(n‑1) + a(n‑2) for n ≥ 2</li>
 * </ul>
 *
 * The values produced for n = 3, 4, 5 are 7, 17 and 41 respectively,
 * matching the examples in the problem statement.
 *
 * @param n the index of the desired term (0‑based)
 * @return the n‑th Newman–Shanks‑Williams number
 * @throws IllegalArgumentException if {@code n} is negative
 * @throws ArithmeticException      if the result does not fit into an {@code int}
 */
public static int newmanPrime(int n) {
    // ---- Input validation (secure‑coding) ----
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }

    // ---- Base cases ----
    if (n == 0 || n == 1) {
        return 1;               // a(0) = a(1) = 1
    }

    // ---- Compute the sequence using BigInteger to avoid overflow ----
    BigInteger a0 = BigInteger.ONE; // a(0)
    BigInteger a1 = BigInteger.ONE; // a(1)
    BigInteger a  = BigInteger.ZERO; // will hold a(i)

    for (int i = 2; i <= n; i++) {
        // a(i) = 2 * a(i‑1) + a(i‑2)
        a = a1.multiply(BigInteger.valueOf(2)).add(a0);
        // shift the window for the next iteration
        a0 = a1;
        a1 = a;
    }

    // ---- Ensure the result fits into an int ----
    if (a.compareTo(BigInteger.valueOf(Integer.MAX_VALUE)) > 0) {
        throw new ArithmeticException("Result exceeds Integer.MAX_VALUE");
    }

    return a.intValue();
}

