import java.util.List;
import java.util.Objects;

/**
 * <p>Given a square matrix of size {@code n×n}, this class provides a method
 * that returns the maximum possible average of any path that starts at the
 * upper‑left cell {@code (0,0)} and ends at the lower‑right cell
 * {@code (n‑1,n‑1)}.  Allowed moves are <b>right</b> and <b>down</b> only.</p>
 *
 * <p>All paths have the same length (2·n‑1 cells), therefore the problem
 * reduces to finding the path with the largest sum; the average is then
 * {@code sum / (2·n‑1)}.</p>
 *
 * @author  (Your name)
 * @version 1.0
 */
public class Maxaverageofpath {

    /**
     * Computes the maximum average value among all valid paths.
     *
     * @param cost a square list of lists representing the {@code n×n} matrix
     *             of non‑negative integer costs; must not be {@code null}
     * @param n    the dimension of the matrix (number of rows/columns)
     * @return the maximum average as a {@code Double}, or {@code null} if the
     *         input is invalid
     * @throws IllegalArgumentException if {@code cost} is {@code null},
     *         {@code n <= 0}, or the size of {@code cost} does not equal {@code n}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- 1. Input validation (Secure Coding Guideline) ----
        if (cost == null) {
            throw new IllegalArgumentException("The cost matrix must not be null.");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("Matrix dimension n must be positive.");
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException(
                    "The number of rows in the cost matrix (" + cost.size() +
                    ") does not match the given n (" + n + ").");
        }

        // Ensure each row has exactly n elements
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException(
                        "Row " + i + " is either null or does not contain " + n + " elements.");
            }
        }

        // ---- 2. Dynamic programming to find the maximum sum ----
        // dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Retrieve the cell value; we already validated the matrix,
                // so no further null‑checks are needed.
                int cellValue = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = cellValue;
                } else {
                    long best = Long.MIN_VALUE;

                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]); // from above
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]); // from left
                    }

                    // Adding the current cell value.  The sum can be stored in a
                    // long because the maximal possible sum fits comfortably
                    // within the range of a 64‑bit signed integer for typical
                    // inputs.
                    dp[i][j] = best + cellValue;
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (double) (2L * n - 1);

        // ---- 3. Return the result as a Double (auto‑boxing) ----
        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------------
    // Optional main method for quick manual testing
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println("Example 1: " + maxaverageofpath(cost1, 3)); // expected 5.2

        // Example 2
        List<List<Integer>> cost2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println("Example 2: " + maxaverageofpath(cost2, 3)); // expected 6.2

        // Example 3
        List<List<Integer>> cost3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println("Example 3: " + maxaverageofpath(cost3, 3)); // expected 7.2
    }
}

