class CountVowels {
    // Set of both lower‑ and upper‑case vowels
    private static final Set<Character> VOWELS = new HashSet<>(Arrays.asList(
            'a', 'e', 'i', 'o', 'u',
            'A', 'E', 'I', 'O', 'U'
    ));

    /**
     * Counts consonants in {@code testStr} that have a vowel as an immediate neighbour
     * (either to the left or to the right).
     *
     * @param testStr the input string (may contain only letters)
     * @return the number of such consonants
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i < testStr.length(); i++) {
            char c = testStr.charAt(i);

            // We only consider letters that are not vowels (i.e. consonants)
            if (!VOWELS.contains(c) && Character.isLetter(c)) {
                boolean hasVowelNeighbor = false;

                // check left neighbour
                if (i > 0 && VOWELS.contains(testStr.charAt(i - 1))) {
                    hasVowelNeighbor = true;
                }
                // check right neighbour
                if (i < testStr.length() - 1 && VOWELS.contains(testStr.charAt(i + 1))) {
