        throw new IllegalArgumentException("n must be non‑negative");
    }
    // base cases: a(0) = 1, a(1) = 1
    if (n == 0 || n == 1) {
        return 1;
    }
    long aMinus2 = 1; // a0
    long aMinus1 = 1; // a1
    long a = 0;
    for (int i = 2; i <= n; i++) {
        a = 2 * aMinus1 + aMinus2;
        aMinus2 = aMinus1;
        aMinus1 = a;
    }
    return (int) a;
