class Maxaverageofpath {
    /**
     * Returns the maximum average of a path from the upper‑left cell (0,0)
     * to the bottom‑right cell (n‑1,n‑1) in the given n×n matrix.
     * Movement is restricted to right or down steps only.
     *
     * @param cost a list of n rows, each row a list of n integers
     * @param n    size of the square matrix
     * @return the maximum average as a Double
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = maximum sum to reach cell (i,j)
        double[][] dp = new double[n][n];

        // starting cell
        dp[0][0] = cost.get(0).get(0);

        // first row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // maximum sum to reach the bottom‑right corner
        double maxSum = dp[n - 1][n - 1];

        // number of cells on any valid path = (n‑1) + (n‑1) + 1 = 2·n‑1
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // ------------------------------------------------------------------
    // Optional test driver
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> cost1 = new ArrayList<>(Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
