class NewmanPrime {

    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   a(0) = 1, a(1) = 1
     *   a(i) = 2 * a(i‑1) + a(i‑2)   for i ≥ 2
     *
     * The values at indices 2,3,4,5,… are the NSW primes:
     * 3, 7, 17, 41, …
     *
     * @param n the index (1‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // Base cases
        if (n == 1) {
            return 1;   // a(1) = 1
        }
        if (n == 2) {
            return 3;   // a(2) = 3 (first prime in the series)
        }

        // Use long to avoid overflow for moderate n; cast back to int for the result.
        long a0 = 1;   // a(i‑2)
        long a1 = 1;   // a(i‑1)
        long a  = 0;   // a(i)

        for (int i = 3; i <= n; i++) {
            a = 2 * a1 + a0;   // recurrence: a(i) = 2*a(i‑1) + a(i‑2)
            a0 = a1;
            a1 = a;
        }

        return (int) a;
    }

    // Simple test driver
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

