class Maxaverageofpath {
    /**
     * Returns the maximum possible average value among all paths that go
     * from the top‑left corner to the bottom‑right corner of the square
     * matrix `cost`.  Paths may only move right or down.
     *
     * @param cost  a square matrix (List of Lists) of integers
     * @param n     size of the matrix (number of rows/columns)
     * @return      the maximum average as a {@code Double}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum of a path from (0,0) to (i,j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Total number of cells visited on any path from (0,0) to (n‑1,n‑1)
        int steps = 2 * n - 1;   // (n‑1) right moves + (n‑1) down moves + 1 starting cell

        double maxSum = dp[n - 1][n - 1];
        return maxSum / steps;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

public static int countVowels(String testStr) {
    // Guard against null or empty input
    if (testStr == null || testStr.isEmpty()) {
        return 0;
    }

    // Vowel set (both lower‑ and upper‑case)
    final String VOWELS = "aeiouAEIOU";

    int count = 0;
    int len = testStr.length();

    for (int i = 0; i < len; i++) {
        char ch = testStr.charAt(i);

        // Skip vowels themselves – we only count consonants that have a vowel neighbor
        if (VOWELS.indexOf(ch) != -1) {
            continue;
        }

        // Check left neighbor
        boolean leftIsVowel = (i > 0) && (VOWELS.indexOf(testStr.charAt(i - 1)) != -1);
        // Check right neighbor
        boolean rightIsVowel = (i < len - 1) && (VOWELS.indexOf(testStr.charAt(i + 1)) != -1);

        // Count this character if it has at least one vowel neighbor
        if (leftIsVowel || rightIsVowel) {
            count++;
        }
    }

    return count;
}

