     * defined by:
     *   a0 = 1, a1 = 1
     *   an = 2·a(n‑1) + a(n‑2)   (n ≥ 2)
     *
     * The sequence starts: 1, 1, 3, 7, 17, 41, …
     *
     * @param n index of the term to return (0‑based)
     * @return the n‑th term of the sequence
     * @throws IllegalArgumentException if n is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // For n = 0 or 1 the result is 1
        if (n == 0 || n == 1) {
            return 1;
        }

        // Use long arithmetic to avoid intermediate overflow,
        // then cast back to int (the problem expects int results).
        long a0 = 1;   // a(i‑2)
        long a1 = 1;   // a(i‑1)
        long a  = 0;   // a(i)

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0;   // recurrence relation
            a0 = a1;
            a1 = a;
        }

        return (int) a;
    }
}

