class Maxaverageofpath {

    /**
     * Returns the maximum possible average value among all paths that start
     * at the top‑left corner and end at the bottom‑right corner of the given
     * n×n matrix. Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integers (as a list of rows)
     * @param n    size of the square matrix
     * @return     the maximum average as a {@code Double}, or {@code null}
     *             if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against bad input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // DP table: dp[i][j] = maximum sum to reach (i, j)
        long[][] dp = new long[n][n];

        // ---- First row (can only come from the left) ----
        for (int j = 0; j < n; j++) {
            if (j == 0) {
                dp[0][0] = cost.get(0).get(0);
            } else {
                dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
            }
        }

        // ---- First column (can only come from above) ----
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // ---- Remaining cells: take the better of the two possible predecessors ----
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                long bestPrev = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = bestPrev + cost.get(i).get(j);
            }
        }

        // The best sum is now stored in the bottom‑right cell
        long maxSum = dp[n - 1][n - 1];

        // Every path from (0,0) to (n-1,n-1) has exactly (2*n - 1) cells
        double average = (double) maxSum / (2L * n - 1);

        // Return as a Double object (as required by the method signature)
        return average;
    }

    // --------------------------------------------------------------------
    // Optional: a tiny demo / test driver
    // --------------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

