    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Vowel set – handles both lower‑ and upper‑case
        Set<Character> vowels = new HashSet<>(
                Arrays.asList('a', 'e', 'i', 'o', 'u',
                              'A', 'E', 'I', 'O', 'U'));

        int count = 0;
        for (int i = 0; i < testStr.length(); i++) {
            char ch = testStr.charAt(i);

            // Skip vowels themselves; we only count consonants
            if (vowels.contains(ch)) {
