                hasVowelNeighbor = true;
            }
            // Check right neighbour
            if (i + 1 < testStr.length() && vowels.contains(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

