/**
 * Returns the n‑th term of the Newman‑Shanks‑Williams like sequence
 * defined by:
 *   a₀ = 1, a₁ = 1
 *   aᵢ = 2·aᵢ₋₁ + aᵢ₋₂   for i ≥ 2
 *
 * The sequence yields primes for i ≥ 2 (3, 7, 17, 41, …),
 * matching the examples newmanPrime(3) → 7, newmanPrime(4) → 17,
 * newmanPrime(5) → 41.
 *
 * @param n 1‑based index (n ≥ 1)
 * @return the n‑th term of the sequence
 * @throws IllegalArgumentException if n ≤ 0
 */
public static int newmanPrime(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }

    // Handle the first two base cases
    if (n == 1) return 1;   // a₁ = 1
    if (n == 2) return 3;  // a₂ = 3

    // Iterate using long to avoid overflow, then cast to int for the result
    long a0 = 1; // a_{i-2}
    long a1 = 1; // a_{i-1}
    long a  = 0; // a_i

    for (int i = 3; i <= n; i++) {
        a = 2 * a1 + a0; // recurrence relation
        a0 = a1;
        a1 = a;
    }

    return (int) a;
}

