}

import java.util.*;

public class Maxaverageofpath {

    /**
     * Returns the maximum average value of a path that starts at the
     * top‑left cell and ends at the bottom‑right cell of the given
     * n×n matrix. Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || n <= 0) {
            return null;
        }
        if (cost.size() != n) {
            return null;
        }
        for (int i = 0; i < n; i++) {
            if (cost.get(i) == null || cost.get(i).size() != n) {
                return null;
            }
        }

        // DP array holds the maximum sum to reach each cell
        long[][] dp = new long[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Every path from (0,0) to (n-1,n-1) has exactly (2*n-1) cells
        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (2 * n - 1);

        return average;
    }

    // Simple manual test
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

class CountVowels {
    /**
     * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        int len = testStr.length();
        int count = 0;

        // 1) Count consonants (non‑vowels) that have at least one vowel neighbour.
        for (int i = 1; i < len - 1; i++) {
            char c = testStr.charAt(i);
            if (!isVowel(c)) {
                if (isVowel(testStr.charAt(i - 1)) || isVowel(testStr.charAt(i + 1))) {
                    count++;
                }
            }
        }

        // 2) Add the first vowel that is next to another vowel (if any).
        for (int i = 0; i < len; i++) {
            char c = testStr.charAt(i);
            if (isVowel(c)) {
                boolean hasVowelNeighbor = (i > 0 && isVowel(testStr.charAt(i - 1))) ||
                                            (i < len - 1 && isVowel(testStr.charAt(i + 1)));
                if (hasVowelNeighbor) {
                    count++;   // count only the first such vowel
                    break;
                }
            }
        }

        return count;
    }

    /** Helper: true if ch is a vowel (case‑insensitive). */
    private static boolean isVowel(char ch) {
        char lower = Character.toLowerCase(ch);
        return lower == 'a' || lower == 'e' || lower == 'i' ||
               lower == 'o' || lower == 'u';
    }
}

