import java.util.List;

public class Maxaverageofpath {
    /**
     * Returns the maximum average value of a monotone path (只能向右或向下)
     * from the top‑left corner (0,0) to the bottom‑right corner (n‑1,n‑1)
     * in the given n×n cost matrix.
     *
     * @param cost n×n list of lists containing the cell costs
     * @param n    dimension of the square matrix
     * @return     the maximum average, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- input validation ------------------------------------------------
        if (cost == null || cost.size() != n) {
            return null;                     // defensive: invalid dimensions
        }
        for (int i = 0; i < n; ++i) {
            if (cost.get(i) == null || cost.get(i).size() != n) {
                return null;                 // each row must have exactly n entries
            }
        }

        // ---- DP: max sum to each cell ---------------------------------------
        // Use long to avoid overflow for large n and large cell values
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                int cur = cost.get(i).get(j);   // current cell value

                if (i == 0 && j == 0) {
                    // Starting point
                    dp[i][j] = cur;
                } else {
                    long fromTop   = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                    long fromLeft  = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;
                    dp[i][j] = cur + Math.max(fromTop, fromLeft);
                }
            }
        }

        // ---- compute average -------------------------------------------------
        long maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);   // denominator = 2n‑1

        return Double.valueOf(average);
    }

    // -----------------------------------------------------------------------
    // Simple manual test (feel free to comment out / remove in production)
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
            List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
            ), 3));   // Expected: 5.2

        System.out.println(maxaverageofpath(
            List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
            ), 3));   // Expected: 6.2

        System.out.println(maxaverageofpath(
            List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
            ), 3));   // Expected: 7.2
    }
}

