class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle invalid input
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // Base cases: a0 = 1, a1 = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute the sequence iteratively
        long a0 = 1; // a_(i-2)
        long a1 = 1; // a_(i-1)
        long a  = 0; // a_i

        for (int i = 2; i <= n; i++) {
            a = 2 * a1 + a0; // a_i = 2*a_(i-1) + a_(i-2)
            a0 = a1;
            a1 = a;
        }

        // The result fits in int for the expected small values of n
        return (int) a;
    }
}

