import java.math.BigInteger;

/**
 * Returns the n‑th Newman‑Shanks‑Williams number.
 * The sequence is defined by:
 *   a(0) = 1, a(1) = 1
 *   a(n) = 2·a(n‑1) + a(n‑2)  for n ≥ 2
 *
 * The first few values are:
 *   a(2) = 3, a(3) = 7, a(4) = 17, a(5) = 41, …
 *
 * The problem’s examples (newmanPrime(3) = 7, …) match a(n) directly.
 */
public static int newmanPrime(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }

    // Base cases
    if (n == 0 || n == 1) {
        return 1;               // a(0) = a(1) = 1
    }

    // Use BigInteger to avoid overflow for moderately large n,
    // then convert the result to int (the problem expects int).
    BigInteger a0 = BigInteger.ONE; // a(i‑2)
    BigInteger a1 = BigInteger.ONE; // a(i‑1)
    BigInteger a  = BigInteger.ZERO; // a(i)

    for (int i = 2; i <= n; i++) {
        a = a1.multiply(BigInteger.TWO).add(a0); // a(i) = 2*a(i‑1) + a(i‑2)
        a0 = a1;
        a1 = a;
    }

    // The returned value fits into an int for the typical test ranges.
    return a.intValue();
}

