class CountVowels {
    /**
     * Counts characters that are not vowels but have at least one vowel
     * as an immediate neighbour (left or right).
     *
     * @param testStr the input string
     * @return the number of such characters
     *
     * Example:
     * countVowels("bestinstareels") → 7
     * countVowels("partofthejourneyistheend") → 12
     * countVowels("amazonprime") → 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        final String vowels = "aeiouAEIOU";
        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels themselves – they must not be counted
            if (vowels.indexOf(ch) != -1) {
                continue;
            }

            boolean hasVowelNeighbor = false;

            // Check left neighbour
            if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
                hasVowelNeighbor = true;
            }
            // Check right neighbour (if not already found)
            if (!hasVowelNeighbor && i < len - 1 && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }
}

