public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a monotone path
     * (right / down only) from the top‑left corner to the bottom‑right
     * corner of the given n×n cost matrix.
     *
     * @param cost list of rows, each row is a list of integers
     * @param n    size of the square matrix
     * @return     maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // basic validation
        if (cost == null || n <= 0 || cost.size() != n) {
            return null;
        }

        // DP table, using double to avoid overflow of the sum
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cur = cost.get(i).get(j);          // current cell cost
                if (i == 0 && j == 0) {
                    dp[i][j] = cur;                    // start cell
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + cur;      // first row: only from left
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + cur;      // first column: only from top
                } else {
                    dp[i][j] = cur + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2.0 * n - 1.0);      // length = 2*n‑1
        return Double.valueOf(average);
    }

    // --------------------------------------------------------------
    // Simple manual test (can be removed or replaced by JUnit)
    public static void main(String[] args) {
