import java.math.BigInteger;

public class NewmanPrime {

    /**
     * Returns the n‑th Newman–Shanks–Williams prime.
     *
     * @param n position in the prime sequence (1‑based)
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n <= 0
     */
    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // The first NSW prime is 2
        if (n == 1) {
            return 2;
        }

        // NSW numbers: a0 = 1, a1 = 1, a_i = 2*a_{i-1} + a_{i-2}
        BigInteger aPrev2 = BigInteger.ONE; // a0
        BigInteger aPrev1 = BigInteger.ONE; // a1

        // Count how many NSW numbers we have found that are prime.
        // We start from a2 (i = 2), which corresponds to the first NSW prime after 2.
        int primeCount = 0;

        for (int i = 2; ; i++) {
            BigInteger aCurr = aPrev1.multiply(BigInteger.valueOf(2)).add(aPrev2);

            if (aCurr.isProbablePrime(100)) { // deterministic Miller‑Rabin for BigInteger
                primeCount++;
                // When we have found (n‑1) primes after the initial 2, we have the n‑th prime.
                if (primeCount == n - 1) {
                    // The problem expects an int; assume the value fits.
                    return aCurr.intValue();
                }
            }

            // Move the window forward
