import java.util.List;

public class Maxaverageofpath {

    /**
     * Returns the maximum possible average value of a monotonic path
     * (right/down only) from the top‑left corner to the bottom‑right corner
     * of the given n×n cost matrix.
     *
     * @param cost a square list of lists of integers representing the matrix
     * @param n    the dimension of the matrix (number of rows/columns)
     * @return the highest average value (as a Double) among all such paths
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = maximum sum to reach cell (i, j) from (0,0)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0);

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Total number of cells in any monotonic path from (0,0) to (n‑1,n‑1)
        int pathLength = 2 * n - 1;

        // Maximum average = maximum sum / pathLength
        double maxAverage = dp[n - 1][n - 1] / pathLength;

        return Double.valueOf(maxAverage);
    }
}

