class SeriesSum {
    /**
     * Calculates the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the upper bound n of the series (must be non‑negative)
     * @return the sum of squares from 1² up to number²
     * @throws IllegalArgumentException if number is negative
     *
     * <p>Example:
     * <pre>
     * seriesSum(6) → 91
     * seriesSum(7) → 140
     * seriesSum(12) → 650
     * </pre>
     */
    public static int seriesSum(int number) {
        // Defensive check – enforce preconditions
        if (number < 0) {
            throw new IllegalArgumentException("number must be non‑negative: " + number);
        }

        // Use long for the intermediate computation to avoid overflow.
        // The closed‑form formula for the sum of squares is:
        //   n(n + 1)(2n + 1) / 6
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        // The method contract declares an int return, so we cast.
        // If the result exceeds Integer.MAX_VALUE, the cast discards
        // higher bits – this matches the behavior of the original
        // examples where n is small.
        return (int) sum;
    }
}

