    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Match sequences of letters – these are the “words” we inspect.
        Matcher m = Pattern.compile("[a-zA-Z]+").matcher(text);

        while (m.find()) {
