class Maxaverageofpath {
    /**
     * Returns the maximum average value of a path that travels from the
     * top‑left corner to the bottom‑right corner of the given n×n matrix.
     * Movement is restricted to right and down steps only.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    the dimension of the square matrix
     * @return the maximum average (as a {@code Double}) or {@code null} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Basic validation
        if (cost == null || n <= 0) {
            return null;
        }

        // dp[i][j] = maximum sum to reach cell (i, j)
        long[][] dp = new long[n][n];

        // Start cell
        dp[0][0] = cost.get(0).get(0).longValue();

        // First row – can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j).longValue();
        }

        // First column – can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0).longValue();
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j).longValue()
                         + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The best sum from (0,0) to (n‑1,n‑1)
        long maxSum = dp[n - 1][n - 1];

        // Number of cells visited on any such path = 2*n - 1
        double average = (double) maxSum / (2 * n - 1);

        return average;               // auto‑boxed to Double
    }
}

