class TextMatchWordzMiddle {
    /**
     * Write a function that matches a word containing 'z',
     * not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null input
        if (text == null) {
            return "Not matched!";
        }

        // Split the input on whitespace; each token is treated as a “word”
        String[] tokens = text.split("\\s+");

        for (String word : tokens) {
            // A middle 'z' can only exist if the word is at least 3 characters long
            if (word.length() >= 3) {
                // Check that the word contains 'z' and that 'z' is neither the first
                // nor the last character.
                if (word.contains("z")
                        && word.charAt(0) != 'z'
                        && word.charAt(word.length() - 1) != 'z') {
                    return "Found a match!";
                }
            }
        }

        // No qualifying word was found
        return "Not matched!";
    }
}

