class VolumeTetrahedron {

    // Static constants – computed once at class loading time
    private static final double SQRT2 = Math.sqrt(2.0);
    private static final double FACTOR = 6.0 * SQRT2;   // 6·√2

    /**
     * Computes the volume of a regular tetrahedron with edge length `num`.
     *
     * The volume formula for a regular tetrahedron is:
     *     V = a³ / (6·√2)
     *
     * @param num the length of each edge (must be positive)
     * @return the volume, rounded to two decimal places
     */
    public static Double volumeTetrahedron(int num) {
        if (num <= 0) {
            throw new IllegalArgumentException("Edge length must be positive");
        }

        // V = a³ / (6·√2)
        double volume = (num * num * num) / FACTOR;

        // Round to two decimal places to match the examples
        volume = Math.round(volume * 100.0) / 100.0;

        // Return as a boxed Double (as required by the signature)
        return Double.valueOf(volume);
    }
}

