public class Maxaverageofpath {

    /**
     * Returns the maximum possible average of a path that starts at the top‑left
     * corner of the square matrix `cost` and ends at the bottom‑right corner.
     * Movement is restricted to rightward or downward steps.
     *
     * @param cost  a square n×n matrix given as a list of rows
     * @param n     the size of the matrix (number of rows/columns)
     * @return      the maximum average (as a Double) of any valid path
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table: dp[i][j] = maximum sum to reach cell (i, j)
        double[][] dp = new double[n][n];

        // Starting cell
        dp[0][0] = cost.get(0).get(0).doubleValue();

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0).doubleValue();
        }

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j).doubleValue();
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                double fromAbove = dp[i - 1][j];
                double fromLeft  = dp[i][j - 1];
                dp[i][j] = cost.get(i).get(j).doubleValue() + Math.max(fromAbove, fromLeft);
            }
        }

        // The total number of cells visited in any path is 2*n - 1
        double maxSum = dp[n - 1][n - 1];
        double average = maxSum / (2 * n - 1);

        return average;
    }

    // Simple test driver (can be removed when integrating into a larger codebase)
    public static void main(String[] args) {
        List<List<Integer>> cost1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(cost1, 3)); // 5.2

        List<List<Integer>> cost2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(cost2, 3)); // 6.2

        List<List<Integer>> cost3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(cost3, 3)); // 7.2
    }
}

