            // left neighbour
            if (i > 0 && vowels.contains(testStr.charAt(i - 1))) {
                count++;
                continue;                     // already satisfied, no need to check right
            }

            // right neighbour
            if (i < len - 1 && vowels.contains(testStr.charAt(i + 1))) {
                count++;
            }
        }
        return count;
    }

