class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Handle non‑negative indices
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // Base cases: a(0) = 1, a(1) = 1
        if (n == 0 || n == 1) {
            return 1;
        }

        // Compute the sequence iteratively using long to avoid overflow
        long a0 = 1; // a(i‑2)
        long a1 = 1; // a(i‑1)
        long a2 = 0; // a(i)

        for (int i = 2; i <= n; i++) {
            a2 = 2 * a1 + a0; // recurrence relation
            a0 = a1;
            a1 = a2;
        }

        // Cast to int (the problem expects int results for the given test cases)
        return (int) a2;
    }

    // Optional main method for quick testing
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

