            }

            // Look for 'z' (case‑insensitive)
            int idx = word.toLowerCase().indexOf('z');

            // 'z' must be present and not at the first or last position
            if (idx > 0 && idx < word.length() - 1) {
                return "Found a match!";
            }
        }

        return "Not matched!";
    }

    // ---- simple test harness -------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
    }
}

import java.util.List;

public class Maxaverageofpath {

    // ------------------------------------------------------------
    // public API
    // ------------------------------------------------------------
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ----- convert to primitive array for fast access ----------
        int[][] a = new int[n][n];
        int maxVal = Integer.MIN_VALUE;
        for (int i = 0; i < n; ++i) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; ++j) {
                int v = row.get(j);
                a[i][j] = v;
                if (v > maxVal) maxVal = v;
            }
        }

        // ----- trivial case -------------------------------------------------
        if (n == 1) {
            return (double) a[0][0];
        }

        final int L = 2 * n - 2;               // number of moves
        final int totalCells = L + 1;           // = 2*n-1

        final int[] di = {-1, 1, 0, 0};
        final int[] dj = {0, 0, -1, 1};

        boolean[][] visited = new boolean[n][n];
        double[] best = {Double.NEGATIVE_INFINITY};

        // ----- start a DFS from every cell -------------------------------
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                visited[i][j] = true;
                dfs(i, j, 0, a[i][j], a, n, L, maxVal,
                    visited, di, dj, totalCells, best);
                visited[i][j] = false;
            }
        }

        return best[0];
    }

    // ------------------------------------------------------------
    // recursive depth‑first search
    // ------------------------------------------------------------
    private static void dfs(int i, int j, int steps, int sum,
                            int[][] a, int n, int L, int maxVal,
                            boolean[][] visited,
                            int[] di, int[] dj, int totalCells,
                            double[] best) {

        // finished a full path ?
        if (steps == L) {
            double avg = (double) sum / totalCells;
            if (avg > best[0]) {
                best[0] = avg;
            }
            return;
        }

        // ----- pruning: even the optimistic bound cannot beat current best ----
        int remaining = L - steps;                       // moves still to do
        double optimisticAvg = (double) (sum + remaining * maxVal) / totalCells;
        if (optimisticAvg <= best[0]) {
            return;                                     // no chance to improve
        }

        // ----- explore the four neighbours ------------------------------------
        for (int d = 0; d < 4; ++d) {
            int ni = i + di[d];
            int nj = j + dj[d];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n && !visited[ni][nj]) {
                visited[ni][nj] = true;
                dfs(ni, nj, steps + 1, sum + a[ni][nj],
                    a, n, L, maxVal, visited, di, dj, totalCells, best);
                visited[ni][nj] = false;
            }
        }
    }

    // ------------------------------------------------------------
    // simple test driver
    // ------------------------------------------------------------
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> m1 = List.of(
                List.of(1, 2, 3),
                List.of(6, 5, 4),
                List.of(7, 3, 9)
        );
        System.out.println(maxaverageofpath(m1, 3)); // expected 5.2

        // Example 2
        List<List<Integer>> m2 = List.of(
                List.of(2, 3, 4),
                List.of(7, 6, 5),
                List.of(8, 4, 10)
        );
        System.out.println(maxaverageofpath(m2, 3)); // expected 6.2

        // Example 3
        List<List<Integer>> m3 = List.of(
                List.of(3, 4, 5),
                List.of(8, 7, 6),
                List.of(9, 5, 11)
        );
        System.out.println(maxaverageofpath(m3, 3)); // expected 7.2
    }
}

