/**
 * Utility class that provides a method to count consonants which are adjacent to a vowel.
 */
class CountVowels {

    /** Set of vowels (both lower‑ and upper‑case are handled). */
    private static final String VOWELS = "aeiouAEIOU";

    /**
     * Counts characters that are NOT vowels (i.e., consonants) and that have
     * at least one vowel neighbor (either to the left or to the right).
     *
     * @param testStr the input string
     * @return the number of such characters
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int count = 0;
        final int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char ch = testStr.charAt(i);

            // Skip vowels – we only count consonants
            if (isVowel(ch)) {
                continue;
            }

            // Check left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                count++;
                continue; // no need to check the right neighbour
            }

            // Check right neighbour
            if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                count++;
            }
        }

        return count;
    }

    /** Helper that determines whether a given character is a vowel. */
    private static boolean isVowel(char c) {
        return VOWELS.indexOf(c) != -1;
    }

    // -----------------------------------------------------------------
    // Optional test driver (uncomment to run manually)
    // -----------------------------------------------------------------
    // public static void main(String[] args) {
