class SeriesSum {
    /**
     * Returns the sum of the series 1² + 2² + 3² + … + n².
     *
     * @param number the number of terms (n)
     * @return the sum of the first 'number' squares
     */
    public static int seriesSum(int number) {
        if (number <= 0) {
            return 0;                     // no terms → sum is 0
        }
        long n = number;
        // Formula: n * (n + 1) * (2n + 1) / 6
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;                  // fit back into int
    }
}

