/**
 * Returns the n-th term of the Newman–Shanks–Williams sequence.
 * The sequence is defined by a(0)=1, a(1)=1 and a(n)=2*a(n-1)+a(n-2) for n>=2.
 * The numbers in this sequence are sometimes called NSW primes.
 *
 * @param n the index of the term to return (0‑based)
 * @return the n‑th Newman–Shanks–Williams number
 */
public static int newmanPrime(int n) {
    if (n <= 0) return 1; // a(0)
    if (n == 1) return 1; // a(1)
    long aPrev2 = 1; // a(0)
    long aPrev1 = 1; // a(1)
    long a = 0;
    for (int i = 2; i <= n; i++) {
        a = 2 * aPrev1 + aPrev2;
        aPrev2 = aPrev1;
        aPrev1 = a;
    }
    return (int) a;
}

