class VolumeTetrahedron {
    /**
     * Calculates the volume of a regular tetrahedron given the length of its edge.
     *
     * @param num the length of each edge of the tetrahedron
     * @return the volume rounded to two decimal places
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        double a = num;                     // edge length
        // Volume formula for a regular tetrahedron
        double volume = (a * a * a) / (6.0 * Math.sqrt(2.0));

        // Round to two decimal places
        double rounded = Math.round(volume * 100.0) / 100.0;

        return rounded;
    }

    // Simple test driver (optional)
    public static void main(String[] args) {
        System.out.println(volumeTetrahedron(10)); // 117.85
        System.out.println(volumeTetrahedron(15)); // 397.75
        System.out.println(volumeTetrahedron(20)); // 942.81
    }
}

public static String textMatchWordzMiddle(String text) {
    // Guard against null or empty input
    if (text == null || text.isEmpty()) {
        return "Not matched!";
    }

    // Split the input on whitespace – punctuation stays part of the token
    String[] tokens = text.split("\\s+");

    for (String token : tokens) {
        int len = token.length();

        // A ‘z’ can only be in the middle if the word has at least 3 characters
        if (len >= 3) {
            // Scan positions 1 … len‑2 (i.e. not the first or last character)
            for (int i = 1; i < len - 1; i++) {
                if (token.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }
    }

    // No word contained a ‘z’ in a non‑edge position
    return "Not matched!";
}

import java.util.List;

class Maxaverageofpath {
    /**
     * Returns the maximum possible average value of a path that starts at the
     * top‑left cell and ends at the bottom‑right cell of the given n×n matrix.
     * Movement is allowed only to the right or down.
     *
     * @param cost the n×n matrix of integer costs
     * @param n    dimension of the square matrix (unused – derived from the list)
     * @return     the maximum average, or null if the input is empty/null
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against malformed input
        if (cost == null || cost.isEmpty()) {
            return null;
        }

        int size = cost.size();               // actual matrix dimension
        double[][] dp = new double[size][size];

        // Initialise the start cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < size; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < size; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table: best sum to reach (i,j) is the cell value
        // plus the larger of the two possible predecessor sums.
        for (int i = 1; i < size; i++) {
            for (int j = 1; j < size; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // The longest possible path always contains exactly (2*n‑1) cells.
        double maxSum = dp[size - 1][size - 1];
        double average = maxSum / (2.0 * size - 1.0);

        return average; // auto‑boxed to Double
    }
}

