class NewmanPrime {
    /**
     * Returns the n‑th Newman‑Shanks‑Williams number.
     * The sequence is defined by:
     *   S0 = 1, S1 = 1,
     *   Sn = 2 * Sn‑1 + Sn‑2   for n >= 2.
     *
     * @param n index (zero‑based) of the desired term
     * @return the n‑th Newman‑Shanks‑Williams number
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        // For n = 0 or 1 the value is 1
        if (n <= 1) {
            return 1;
        }

        long prev2 = 1; // S0
        long prev1 = 1; // S1
        long current = 0;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        // The result fits in an int for reasonable n; cast is safe.
        return (int) current;
    }

    // Simple test (optional)
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

