public static long newmanPrime(int n) {
    if (n < 0) throw new IllegalArgumentException("n must be non‑negative");
    if (n == 0) return 1L;
    if (n == 1) return 1L;
    long prev2 = 1L; // a0
    long prev1 = 1L; // a1
    long current = 0L;
    for (int i = 2; i <= n; i++) {
        current = 2 * prev1 + prev2;
        prev2 = prev1;
        prev1 = current;
    }
    return current;
}

