import java.util.Objects;

/**
 * Utility class for computing the n‑th Newman–Shanks–Williams (NSW) prime.
 *
 * The NSW prime sequence starts: 2, 3, 7, 17, 41, 97, 239, …
 *
 * The recurrence that generates the NSW numbers is:
 *   a(0) = 1,  a(1) = 1
 *   a(i) = 2·a(i‑1) + a(i‑2)   (i ≥ 2)
 *
 * The prime values among these numbers (with 2 added as the first prime)
 * are the NSW primes.
 */
public final class NewmanPrime {

    // Prevent instantiation – this is a pure static utility class.
    private NewmanPrime() {
        throw new UnsupportedOperationException("Utility class cannot be instantiated");
    }

    /**
     * Returns the n‑th Newman–Shanks–Williams prime (1‑based).
     *
     * @param n the index of the desired NSW prime (must be ≥ 1)
     * @return the n‑th NSW prime
     * @throws IllegalArgumentException if n ≤ 0
     */
    public static int newmanPrime(int n) {
        Objects.requireNonNull(n, "n must not be null"); // defensive, even for primitives
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive: " + n);
        }

        // The first NSW prime is 2.
        if (n == 1) {
            return 2;
        }

        int found = 1;                     // we have already counted the prime 2
        long aPrev2 = 1L;                  // a(0)
        long aPrev1 = 1L;                  // a(1)

        // Generate the recurrence until we have collected the n‑th prime.
        for (long i = 2; ; i++) {
            long a = 2 * aPrev1 + aPrev2;  // a(i) = 2·a(i‑1) + a(i‑2)

            if (isPrime(a)) {
                found++;
                if (found == n) {
                    // The problem statement expects an int; the test cases stay within int range.
                    return (int) a;
                }
            }

            // Shift the window for the next iteration.
            aPrev2 = aPrev1;
            aPrev1 = a;
        }
    }

    /**
     * Simple trial‑division primality test (adequate for the small indices used in the task).
     *
     * @param value the number to test
     * @return true if value is prime, false otherwise
     */
    private static boolean isPrime(long value) {
        if (value < 2) {
            return false;
        }
        if (value == 2) {
            return true;
        }
        if (value % 2 == 0) {
            return false;
        }
        long limit = (long) Math.sqrt(value);
        for (long d = 3; d <= limit; d += 2) {
            if (value % d == 0) {
                return false;
            }
        }
        return true;
    }
}

