class Maxaverageofpath {
    /**
     * Finds a path with the maximum average over all existing paths
     * for the given square matrix of size n*n.
     *
     * The path is assumed to start at the upper‑left cell (0,0) and end
     * at the lower‑right cell (n‑1,n‑1), moving only right or down.
     * The length of any such path is always 2*n‑1 cells, therefore
     * maximizing the average is equivalent to maximizing the total sum.
     *
     * @param cost  a list of n rows, each row a list of n integers
     * @param n     the dimension of the square matrix
     * @return      the maximum average as a Double, or null if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against illegal arguments
        if (cost == null || n <= 0) {
            return null;
        }

        // DP array holds the maximum sum reachable at each cell
        long[][] dp = new long[n][n];

        // Initialize the starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill the first row (can only come from the left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the first column (can only come from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest of the table: take the better of the two predecessors
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                            + cost.get(i).get(j);
            }
        }

        // The best sum到达右下角
        long maxSum = dp[n - 1][n - 1];

        // Number of cells visited in any valid path = 2*n - 1
        double average = maxSum / (2.0 * n - 1.0);

        // Return the average as a Double object
        return Double.valueOf(average);
    }

    // Simple test harness (optional)
    public static void main(String[] args) {
        // Example 1
        List<List<Integer>> mat1 = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(6, 5, 4),
            Arrays.asList(7, 3, 9)
        );
        System.out.println(maxaverageofpath(mat1, 3)); // 5.2

        // Example 2
        List<List<Integer>> mat2 = Arrays.asList(
            Arrays.asList(2, 3, 4),
            Arrays.asList(7, 6, 5),
            Arrays.asList(8, 4, 10)
        );
        System.out.println(maxaverageofpath(mat2, 3)); // 6.2

        // Example 3
        List<List<Integer>> mat3 = Arrays.asList(
            Arrays.asList(3, 4, 5),
            Arrays.asList(8, 7, 6),
            Arrays.asList(9, 5, 11)
        );
        System.out.println(maxaverageofpath(mat3, 3)); // 7.2
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class CountVowels {
    /**
     * Counts consonants in the given string that have a vowel as an immediate neighbour
     * (either to the left or to the right). Vowels are a, e, i, o, u (both lower‑ and
     * upper‑case). The character y is treated as a consonant.
     *
     * Examples:
     *   countVowels("bestinstareels")        -> 7
     *   countVowels("partofthejourneyistheend") -> 12
     *   countVowels("amazonprime")          -> 5
     *
     * @param testStr the input string (may be null or empty)
     * @return the number of consonants that are adjacent to at least one vowel
     */
    public static int countVowels(String testStr) {
        // Guard against null or empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        // Set of vowels for fast lookup
        final String VOWELS = "aeiouAEIOU";
        int n = testStr.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char ch = testStr.charAt(i);

            // We only count characters that are NOT vowels
            if (VOWELS.indexOf(ch) == -1) {
                boolean hasVowelNeighbor = false;

                // Check left neighbour
                if (i > 0 && VOWELS.indexOf(testStr.charAt(i - 1)) != -1) {
                    hasVowelNeighbor = true;
                }
                // Check right neighbour (only if we haven't already found a vowel)
                if (!hasVowelNeighbor && i < n - 1
                        && VOWELS.indexOf(testStr.charAt(i + 1)) != -1) {
                    hasVowelNeighbor = true;
                }

                if (hasVowelNeighbor) {
                    count++;
                }
            }
        }
        return count;
    }

    // Simple manual test driver
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));           // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class CountAlphaDigSpl {

    /**
     * Counts the number of alphabetic characters, digits, and special characters
     * in the given string.
     *
     * @param string the input text (must not be null)
     * @return a List containing three integers:
     *         <ol>
     *           <li>number of alphabetic characters (a‑z, A‑Z)</li>
     *           <li>number of digit characters (0‑9)</li>
     *           <li>number of all other characters</li>
     *         </ol>
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        if (string == null) {
            throw new IllegalArgumentException("Input string must not be null");
        }

        int alphas = 0;
        int digits = 0;
        int specials = 0;

        for (int i = 0; i < string.length(); i++) {
            char ch = string.charAt(i);
            if (Character.isLetter(ch)) {
                alphas++;
            } else if (Character.isDigit(ch)) {
                digits++;
            } else {
                specials++;
            }
        }

        // Return a mutable list (ArrayList) with the three counts
        return new ArrayList<>(Arrays.asList(alphas, digits, specials));
    }

    // Simple demo (optional)
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Guard against non‑positive input
        if (number <= 0) {
            return 0;
        }

        // Use long to avoid intermediate overflow, then cast back to int
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;   // n(n+1)(2n+1)/6
        return (int) sum;
    }
}
